// the picker therefore cannot leave an empty channel behind.
let pendingAddTrack = null;

const emptyMix = () => ({ master: 0, masterPan: 0, limiter: false, lanes: {}, voice: undefined });
const emptyLaneMix = () => ({
  ...LANE_DEFAULTS,
  eq: { ...LANE_DEFAULTS.eq },
  send: { ...LANE_DEFAULTS.send },
  effects: [],
});
/**
 * The mix in force for a song — and always in the shape the desk edits.
 *
 * The serialiser leaves `lanes` out of the file when no channel has been touched (see
 * tools/lib/mix-source.js), so a song whose only saved decisions are layers, voices or
 * an off-list comes back from disk with no `lanes` at all — every imported song starts
 * that way. Half the desk indexes `mix.lanes[key]` straight, and the first thing to do
 * it was buildRack, which cleared the rack before it threw and left the sends detached
 * for every build after. Filling the gap in one place is cheaper than an optional chain
 * on each of them, and it is in place on purpose: the object handed back is the draft or
 * the file's own, and everything that mutates a mix expects to be writing into it. An
 * empty lanes object signs as no change (see mixSignature), so no song becomes dirty by
 * being looked at.
 */
const mixFor = (id) => {
  const m = draft[id] || saved[id] || emptyMix();
  if (!m.lanes || typeof m.lanes !== 'object') m.lanes = {};
  // Retire the pre-rename layer label in memory as well as at the file boundary. It
  // was commonly an imported MIDI track name, and keeping it around lets old drafts
  // leak that name into a later copy or freeze operation.
  if (Array.isArray(m.layers)) {
    for (const layer of m.layers) if (layer && Object.hasOwn(layer, 'label')) delete layer.label;
  }
  return m;
};

/** A user-facing track name. It never changes the lane key used by playback. */
function customTrackLabel(key) {
  const value = mixFor(trackId).labels?.[key];
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

// The mix and arrangement are song data; the panels around them are the desk. A
// keyboard left open while working on one song should not unexpectedly cover a
// different song, and a piano roll is useful context when returning to the melody
// that was being edited. Keep only that workspace context here — never audio or mix
// state — keyed by the same stable song id used by drafts and recent songs.
const SONG_LAYOUT_KEY = 'mash-mixer-song-layout';
let songLayouts = {};
try { songLayouts = JSON.parse(localStorage.getItem(SONG_LAYOUT_KEY) || '{}') || {}; }
catch { songLayouts = {}; }
let restoringSongLayout = false;

function saveSongLayouts() {
  localStorage.setItem(SONG_LAYOUT_KEY, JSON.stringify(songLayouts));
}

function currentSongLayout() {
  // Which panels are open: the on-screen keyboard, the step grid window, and whether
  // the notes panel (piano roll) is visible. The Arrangement, Mixer and Effects folds
  // are NOT in here — they are desk furniture and are remembered globally, next to the
  // panel heights, so they do not change under you when you switch songs.
  const notes = !$('notes').classList.contains('collapsed');
  return {
    keyboard: oskShown(),
    notes,
    grid: stepSeq.isOpen(),
    // An open piano roll is workspace context for one particular track. Keep that
    // track with the panel so returning to this song cannot reopen its notes while a
    // channel carried over from another song remains selected.
    lane: notes && notesRollUp() ? rollShownLane() : null,
  };
}

function notesOpenInLayout(layout) {
  if (!layout) return null;
  if (layout.notes != null) return layout.notes === true;
  if (layout.view != null) return layout.view === 'notes';
  return null;
}

function rememberSongLayout(id = trackId) {
  if (restoringSongLayout || !id || !track || !resolveTrack(id)) return;
  songLayouts[id] = currentSongLayout();
  saveSongLayouts();
}

function restoreSongLayout(id) {
  const layout = songLayouts[id];
  // A first visit inherits the current desk rather than surprising the user by
  // closing panels they just opened. It is recorded after the song is loaded, so
  // subsequent visits become song-specific.
  if (!layout) return false;
  restoringSongLayout = true;
  try {
    // Restore which panels were open. The old `editor` / `view` keys are from when
    // Effects and Notes shared one region; `notes` is the new key for the independent
    // notes panel. If neither is present, leave both panels at their defaults.
    const notesOpen = notesOpenInLayout(layout);
    if (notesOpen != null) setNotesFolded(!notesOpen, false);
    stepSeqWanted = layout.grid === true || layout.editor === 'step';
    stepSeq.open(stepSeqWanted);
    $('seqbtn').classList.toggle('on', stepSeqWanted);
    showOsk(layout.keyboard === true);
  } finally {
    restoringSongLayout = false;
  }
  return true;
}

// Persist the current song's workspace even when the user reloads without changing
// songs. This is deliberately page-lifecycle state, not a Save-to-game operation.
// beforeunload captures modeless popups before the window blur handler dismisses them;
// visibilitychange covers a mobile browser freezing or discarding the tab instead.
addEventListener('beforeunload', () => {
  deskSessionCapturedForUnload = true;
  rememberSongLayout();
  rememberDeskSession();
  persistFrozenIntent();
});
addEventListener('pagehide', () => {
  rememberSongLayout();
  if (!deskSessionCapturedForUnload && !document.hidden) rememberDeskSession();
});
document.addEventListener('visibilitychange', () => {
  if (document.hidden) rememberDeskSession();
});

/**
 * The song as this mix shapes it: layers materialised, deleted tracks gone — and as
 * this ARRANGEMENT orders it: the bars it plays, in the order it plays them, with
 * the lanes each bar drops.
 *
 * Everything on the desk that asks "what tracks does this song have" asks this rather
 * than `track.bank` — the rack, the arrangement, the lane numbers, the labels — so
 * there is one answer and the desk cannot disagree with the engine about it. Cached
 * on the shape alone, because the answer changes only when a track is duplicated or
 * deleted, or a bar is edited, and building the arrangement asks for it once per row.
 *
 * The arrangement goes on FIRST, matching applyMix: it changes which sections exist,
 * and deskBank has to rewrite the layer lanes into all of them.
 */
let bankCache = { bank: null, sig: null, arr: null, out: null };
function viewBank() {
  const m = mixFor(trackId);
  const arr = arrFor(trackId);
  // `order` is in the signature because `deskBank` bakes it into the bank it returns.
  // Left out, the cache went on serving the order the desk had before the drag to
  // everything that asks it what tracks this song has — and undo, which does not clear
  // the cache itself, put the strips back by leaving them exactly where they were.
  //
  // These three are signed because a mix is edited IN PLACE — `mixFor` hands out the
  // draft itself — so the object being the same object says nothing. They are also
  // tiny: a song's layers are tens of bytes.
  //
  // The ARRANGEMENT is not signed, it is compared by identity, because it is never
  // edited in place: every writer builds a whole new entry and puts it in `arrDraft`
  // (and nulls `bankCache.sig` on the way past). Signing it meant serialising the
  // whole arrangement on every call, and the grid calls this once per bar per lane
  // while it builds — 6,792 times and 24.7MB of throwaway JSON for one double-click
  // on megamix, none of which could ever differ from the call before it.
  const sig = JSON.stringify([m.layers || null, m.off || null, m.order || null]);
  if (bankCache.bank !== track?.bank || bankCache.sig !== sig || bankCache.arr !== arr) {
    const arranged = applyArrangement(track?.bank, trackId, { [trackId]: arr });
    bankCache = { bank: track?.bank, sig, arr, out: deskBank(arranged, m) };
  }
  return bankCache.out;
}
/**
 * Has this song been changed away from what the file holds?
 *
 * The draft is the only place an edit can live, so no draft is no change — whatever
 * is saved for the song. Comparing the mixes straight through missed that: an absent
 * draft signs as null, a saved mix with anything in it does not, so every one of the
 * 34 songs in mix.js read as dirty from the moment the desk opened, and reverting —
 * which deletes the draft — put it straight back.
 *
 * A draft that EXISTS and signs as null is a different thing and still counts: that is
 * every channel reset to defaults, which is a change worth writing if the file holds
 * anything else.
 *
 * What counts as a difference is `mixSignature` — a mix reduced to what mix.js can
 * hold — and it is shared with the serialiser's own tests rather than written out
 * again here. See tools/lib/mix-signature.js for what that is worth.
 */
// Either half counts: a song whose bars have been rearranged has something to save
// even if no fader moved, and the dot on the hamburger is about whether the FILE has heard it.
// Three halves now, not two. A song whose cabinet screen has been set has something to
// write even if no fader moved and no bar was rearranged — and without this the Save
// button would sit there reading "Saved — matches the file" over an uncaptured treatment.
const isDirty = (id) => (draft[id] != null && mixChanged(draft[id], saved[id]))
  || arrDirty(id) || variantDirty(id);

// Undo holds whole-mix snapshots per track. Slider drags coalesce: a continuous
// drag is one gesture, so undo steps back over the whole move rather than one
// step per pixel.
const undoStack = [];
let lastEditTag = null;
let lastEditAt = 0;

function pushUndo(tag) {
  const now = performance.now();
  const coalesce = tag != null && tag === lastEditTag && now - lastEditAt < 700;
  lastEditTag = tag; lastEditAt = now;
  if (coalesce) return;
  undoStack.push({
    trackId,
    mix: JSON.parse(JSON.stringify(draft[trackId] ?? null)),
    // The song's SHAPE, alongside its balance. A step that put back the faders and
    // left the bars where an edit had moved them would be half an undo, and the half
    // it left behind is the one you can hear.
    arr: JSON.parse(JSON.stringify(arrDraft[trackId] ?? null)),
    hadArr: trackId in arrDraft,
  });
  if (undoStack.length > 200) undoStack.shift();
  syncUndoButton();
}

/**
 * ONE UNDO BUTTON, TWO HISTORIES, NEVER MIXED.
 *
 * While a recipe is live the desk's Undo governs M8TRX's stack and says so — the same
 * borrowing the loop button already does when it becomes Recipe Once / Recipe Loop. Two
 * Undo buttons a few inches apart was the alternative, and the question "which one am I
 * about to press" is exactly the scope confusion the rest of this panel was rebuilt to
 * kill: in M8TRX the answer is now "the only one there is, and it says M8TRX on it".
 *
 * The stacks stay strictly separate. A desk edit made while a recipe is up goes on the
 * desk's stack and waits there; returning to the song hands the button back with that
 * history intact. An M8TRX edit can never be undone into a fader move, or the other way
 * round, which is the property that made two buttons look necessary in the first place.
 */
function syncUndoButton() {
  const button = $('undo');
  if (!button) return;
  const m8 = rearrangeActive();
  button.disabled = m8 ? !rearrangeUndoStack.length : undoStack.length === 0;
  button.textContent = m8 ? 'Undo M8TRX' : 'Undo';
  button.dataset.tip = m8 ? 'Undo M8TRX' : 'Undo';
  button.dataset.tipsays = m8
    ? 'Back through M8TRX edits only — the recipe, never the song. The desk’s own mix and arrangement history is kept separately while a recipe is up, and comes back the moment you return to the song.'
    : 'Back through mix and arrangement edits alike — a painted step, a moved fader, a bar dropped out of the song.';
}

/** ⌘Z and the button, routed to whichever history is in charge. */
function undoGesture() {
  if (rearrangeActive()) { undoRearrange(); return; }
  undo();
}

/** Whatever is open in the top layer, or null. Guarded: `:popover-open` is a parse error
 *  on a browser without popover support, where the answer is null anyway. */
function openPopover() {
  try { return document.querySelector('[popover]:popover-open'); } catch { return null; }
}

/**
 * How tall the desk's header and status bar are, published so the M8TRX panel can sit
 * exactly between them.
 *
 * Measured, never written down. Both were magic numbers first and both were wrong: the
 * footer is one line of 11px text, which moves with the font stack, and the header WRAPS
 * to a second row at some window widths. A panel pinned at a hardcoded 56px then covered
 * the row holding Undo M8TRX and the ? — the two controls the desk lends M8TRX — so the
 * panel was eating its own buttons.
 */
// The last values written, so an unchanged measurement costs nothing. This is not a
// micro-optimisation: writing a custom property the observer below is watching for is how
// a ResizeObserver feeds itself, and a measure/write loop on this desk is a measure/write
// loop competing with the audio graph for the one core it has.
let deskHeadH = null;
let deskFootH = null;

function measureDeskEdges() {
  const root = document.documentElement.style;
  const header = document.querySelector('header');
  const footer = document.querySelector('footer');
  // Distances from the EDGES of the viewport, not the elements' own heights: the footer does
  // not sit flush to the bottom of the window, so its height was 14px short of the space it
  // actually claims and the panel overlapped it by exactly that much.
  if (header) {
    const value = Math.ceil(header.getBoundingClientRect().bottom);
    if (value !== deskHeadH) { deskHeadH = value; root.setProperty('--headh', `${value}px`); }
  }
  if (footer) {
    const value = Math.max(0, Math.ceil(innerHeight - footer.getBoundingClientRect().top));
    if (value !== deskFootH) { deskFootH = value; root.setProperty('--footh', `${value}px`); }
  }
}

/**
 * At most ONE measurement per frame, however many things ask for one.
 *
 * PLAYBACK WINS. A window drag fires `resize` continuously and the observer alongside it,
 * and each measurement is a forced layout — `getBoundingClientRect` on two elements after
 * a style write. Run twice per frame for the length of a drag, that is enough main-thread
 * work to starve the audio graph, which is exactly what dragging the window edge during
 * M8TRX playback sounded like. Coalescing makes a drag cost one measurement per frame no
 * matter how many events it generates.
 */
let deskEdgeFrame = 0;
function scheduleDeskEdges() {
  if (deskEdgeFrame) return;
  deskEdgeFrame = requestAnimationFrame(() => {
    deskEdgeFrame = 0;
    measureDeskEdges();
  });
}

/**
 * Re-measure whenever the header or footer actually CHANGES SIZE, not only when the
 * window does.
 *
 * The bug this closes: `openRearrangePanel` measured on the way in, before the panel was
 * shown — and the footer GROWS a line when M8TRX's own status joins it. So the panel was
 * sized against a footer one line shorter than the one it then had to sit above, and it
 * covered it. Nothing looked wrong until a resize happened to re-measure, which is why it
 * read as "the footer is only in front after a resize".
 *
 * An observer rather than another call site at the point of the symptom: the header wraps
 * at some widths, the footer grows and shrinks with what it has to say, and fonts settle
 * after boot. Every one of those is the same measurement going stale, and chasing them one
 * at a time is how the next one gets missed.
 */
function watchDeskEdges() {
  if (typeof ResizeObserver !== 'function') return;
  const observer = new ResizeObserver(() => scheduleDeskEdges());
  for (const selector of ['header', 'footer']) {
    const element = document.querySelector(selector);
    if (element) observer.observe(element);
  }
}

// Every step on this stack is one song wide, and there is deliberately no way to make
// one that is not: nothing on this desk writes to a song other than the one on it. See
// the note over `restoreFrom`.

function editMix(mutate, tag, { undo = true } = {}) {
  if (undo) pushUndo(tag);
  const cur = JSON.parse(JSON.stringify(mixFor(trackId)));
  mutate(cur);
  draft[trackId] = cur;
  localStorage.setItem(LS_KEY, JSON.stringify(draft));
  reconcileFrozen();
  updateStatus();
}

// ---- tooltips ---------------------------------------------------------------------
//
// One card for the whole page, filled and moved on hover. Any element carrying
// `data-tip` gets one: the name goes in bold, `data-tipkey` becomes the key chip beside
// it, and `data-tipsays` is the sentence underneath — which is the only reason to have
// built this rather than leave the browser's `title` doing it. A row of icon buttons is
// exactly the case a one-line grey system tooltip cannot serve: the picture is the label,
// so the tooltip has to carry both the name AND what the thing is for.
//
// Never both: an element with `data-tip` must not also have a `title`, or the OS draws
// its own on top a second later.
const TIP_DELAY = 340;         // long enough that crossing the row does not flash six cards
let tipTimer = null;
let tipTarget = null;

function hideTip() {
  clearTimeout(tipTimer);
  tipTimer = null;
  tipTarget = null;
  $('tip').classList.remove('show', 'in');
}

/**
 * Put a floating card beside the thing it is about, and aim its arrow at that thing.
 *
 * Shared by the tooltip and the tour, because both have the same two problems and the
 * same two answers. The card is sized by its own sentence, so whether it fits below the
 * anchor cannot be known until it is in the page and measured — hence `show` before
 * place, never after. And the card is clamped to the window while the anchor is not, so
 * at the ends of a row the two stop agreeing about where the middle is: the arrow
 * follows the ANCHOR, because a point aimed at the centre of a card that had to move is
 * a point aimed at nothing.
 *
 * `prefer: 'side'` moves it out to the left or right instead. A tooltip never needs this
 * — it is two lines under a toolbar button and gone again — but a card that stays up
 * while you read four lines of it will lie straight over a channel strip, which is the
 * one thing on the desk it was pointing at. Beside, the strip is still readable. It
 * falls back to above/below when there is no room either side.
 */
function placeCard(card, el, arrow, { gap = 9, edge = 6, inset = 11, prefer = 'below' } = {}) {
  const r = el.getBoundingClientRect();
  const box = card.getBoundingClientRect();
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(v, hi));

  if (prefer === 'side') {
    const right = r.right + gap;
    const leftSide = r.left - gap - box.width;
    const at = right + box.width <= innerWidth - edge ? right
      : leftSide >= edge ? leftSide
        : null;
    if (at !== null) {
      const top = clamp(r.top + r.height / 2 - box.height / 2, edge,
        innerHeight - box.height - edge);
      card.style.left = `${Math.round(at)}px`;
      card.style.top = `${Math.round(top)}px`;
      if (arrow) {
        // The side arrows are the same rotated square wearing a different pair of the
        // card's borders — see the `.tutarrow.beside` rules.
        arrow.classList.remove('under');
        arrow.classList.add('beside');
        arrow.classList.toggle('after', at === leftSide);
        arrow.style.left = '';
        arrow.style.top = `${Math.round(
          clamp(r.top + r.height / 2 - top, inset, box.height - inset) - 4.5)}px`;
      }
      return true;
    }
  }

  const below = r.bottom + gap + box.height <= innerHeight - edge;
  const left = clamp(r.left + r.width / 2 - box.width / 2, edge, innerWidth - box.width - edge);
  card.style.left = `${Math.round(left)}px`;
  card.style.top = `${Math.round(below ? r.bottom + gap : r.top - gap - box.height)}px`;
  if (!arrow) return below;
  arrow.classList.remove('beside', 'after');
  arrow.style.top = '';
  arrow.classList.toggle('under', !below);
  const at = clamp(r.left + r.width / 2 - left, inset, box.width - inset);
  arrow.style.left = `${Math.round(at - 4.5)}px`;
  return below;
}

function showTip(el) {
  const tip = $('tip');
  tip.textContent = '';
  tip.classList.toggle('bartip', el.dataset.tipkind === 'bar');
  tip.classList.toggle('tracktip', el.dataset.tipkind === 'track');
  const head = document.createElement('div');
  head.className = 'tiphead';
  const name = document.createElement('span');
  name.className = 'tipname';
  name.textContent = el.dataset.tip;
  head.append(name);
  if (el.dataset.tipkey) {
    const key = document.createElement('kbd');
    key.className = 'tipkey';
    key.textContent = el.dataset.tipkey;
    head.append(key);
  }
  tip.append(head);
  if (el.dataset.tipcontext) {
    const context = document.createElement('div');
    context.className = 'tipcontext';
    context.textContent = el.dataset.tipcontext;
    tip.append(context);
  }
  if (el.dataset.tipsays) {
    const says = document.createElement('div');
    says.className = 'tipsays';
    says.textContent = el.dataset.tipsays;
    tip.append(says);
  }
  if (el.dataset.tipgroups) {
    let groups = [];
    try { groups = JSON.parse(el.dataset.tipgroups); } catch { groups = []; }
    const body = document.createElement('div');
    body.className = 'tipgroups';
    for (const group of groups) {
      const row = document.createElement('div');
      row.className = 'tipgroup';
      const label = document.createElement('div');
      label.className = 'tipgroup-label';
      label.textContent = group.label || '';
      const values = document.createElement('div');
      values.className = 'tipgroup-values';
      if (group.context) {
        const source = document.createElement('span');
        source.className = 'tipgroup-context';
        source.textContent = group.context;
        values.append(source);
      }
      for (const item of group.items || []) {
        const chip = document.createElement('span');
        chip.className = `tipchip${item.tone ? ` ${item.tone}` : ''}`;
        chip.textContent = item.text || '';
        values.append(chip);
      }
      row.append(label, values);
      body.append(row);
    }
    tip.append(body);
  }
  if (el.dataset.tiphints) {
    const foot = document.createElement('div');
    foot.className = 'tipfoot';
    let hints = [];
    try { hints = JSON.parse(el.dataset.tiphints); } catch { hints = []; }
    for (const hint of hints) {
      const item = document.createElement('span');
      item.className = 'tiphint';
      const key = document.createElement('kbd');
      key.textContent = hint.key || '';
      const action = document.createElement('span');
      action.textContent = hint.text || '';
      item.append(key, action);
      foot.append(item);
    }
    tip.append(foot);
  }
  const arrow = document.createElement('span');
  arrow.className = 'tiparrow';
  tip.append(arrow);

  // Shown first, then placed — see placeCard for why the order matters.
  tip.classList.add('show');
  placeCard(tip, el, arrow);
  requestAnimationFrame(() => tip.classList.add('in'));
}

addEventListener('pointerover', (ev) => {
  const el = ev.target.closest?.('[data-tip]') || null;
  if (el === tipTarget) return;
  hideTip();
  if (!el) return;
  tipTarget = el;
  tipTimer = setTimeout(() => { if (tipTarget === el) showTip(el); }, TIP_DELAY);
});
// Reached by keyboard, the tip is the only label there is — the buttons are pictures — so
// it comes up at once rather than after a delay meant to keep a moving pointer quiet.
addEventListener('focusin', (ev) => {
  const el = ev.target.closest?.('[data-tip]');
  if (!el || !el.matches(':focus-visible')) return;
  hideTip();
  tipTarget = el;
  showTip(el);
});
addEventListener('focusout', hideTip);
// Capture, so the card is gone before the click it belongs to opens a panel underneath it.
addEventListener('pointerdown', hideTip, true);
addEventListener('keydown', hideTip, true);
addEventListener('scroll', hideTip, true);
addEventListener('blur', hideTip);

let toastTimer = null;
/**
 * How long a message stays up, and why it is a multiplier rather than a new default.
 *
 * A toast on this desk lands in the corner while your eyes are on the thing you just
 * changed — a fader, a note, an effect you dropped — so the clock starts before you
 * look at it, not when it appears. At 2.2s the sentence was usually gone by the time
 * you turned your head, which makes it a flicker rather than a message.
 *
 * The call sites say RELATIVE length — "this warning is longer than that confirmation"
 * — and that ordering is right; it was only the floor that was wrong. So they keep
 * their numbers and the stretch lands here, where raising it raises all of them
 * together. Capped, because past ten seconds a message stops reading as a reply to
 * something you did and starts reading as a thing stuck on the screen.
 */
const TOAST_STRETCH = 2;
const TOAST_MAX_MS = 10000;
// `ms: 0` holds the toast until something replaces it — for a job that takes longer
// than a message about it should be on screen, like an offline render. It is not
// stretched, because it is not a duration.
function toast(msg, ms = 2200) {
  const t = $('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toastTimer);
  if (ms) {
    toastTimer = setTimeout(() => t.classList.remove('show'),
      Math.min(TOAST_MAX_MS, ms * TOAST_STRETCH));
  }
}

function undo() {
  // A take that has not been written yet is not on this stack, so undoing past it would
  // step back over the bar BEFORE the one you just played — and then the buffered notes
  // would land on top of what was restored. Writing it first makes ⌘Z mean what it
  // looks like it means: take the last thing I played back off.
  if (recArmed) endTake('undo', { announce: false });
  const step = undoStack.pop();
  if (!step) { toast('Nothing to undo'); return; }
  lastEditTag = null;
  // What the sequencer is playing, and what it is playing WITH — as opposed to what
  // the strips are doing to it. Everything else on this desk is a live node that
  // applyToEngine can move, but a voice is a bank key and a duplicated or deleted
  // track is a lane: undoing either has to re-bank, or the desk goes back and the
  // sound does not. Read before the draft is restored, compared after.
  // `order` rides along because undoing a drag has to repaint BOTH views — the plain
  // branch below rebuilds the rack alone, which put the strips back and left the
  // arrangement rows in the order the undone drag had left them.
  const bankSig = () => {
    const m = mixFor(trackId);
    return JSON.stringify([m.voice || null, m.layers || null, m.off || null, m.order || null]);
  };
  // Track Note FX are mix state, but the arrangement draws them: the row's NFX marker
  // and the bar badges. The plain branch below rebuilds the rack alone, which undid the
  // setting and left the marker showing it.
  const noteFxSig = () => {
    const lanes = mixFor(trackId).lanes || {};
    return JSON.stringify(Object.keys(lanes).sort()
      .map((k) => [k, lanes[k].noteFx || null]));
  };
  const before = bankSig();
  const fxBefore = noteFxSig();
  const arrBefore = JSON.stringify(arrFor(step.trackId) || null);
  if (step.mix === null) delete draft[step.trackId];
  else draft[step.trackId] = step.mix;
  // The arrangement half of the step. `hadArr` distinguishes "there was no unsaved
  // arrangement edit" from "there was one, and it was empty" — the second is a real
  // state (a song reverted to its written form) and deleting the key would lose it.
  if (step.hadArr) arrDraft[step.trackId] = step.arr;
  else delete arrDraft[step.trackId];
  localStorage.setItem(LS_KEY, JSON.stringify(draft));
  localStorage.setItem(ARRANGE_KEY, JSON.stringify(arrDraft));
  syncUndoButton();
  const arrMoved = JSON.stringify(arrFor(step.trackId) || null) !== arrBefore;
  if (step.trackId === trackId && arrMoved) {
    // Bars moved: the sequencer needs the order it had, and the timeline and grid
    // are both drawn from it. Handed over without stopping, like the edit was.
    bankCache.sig = null;
    Audio.setArrangement(arrFor(trackId));
    // The tempo lives on the arrangement too, so undoing one is undoing the other —
    // and a readout still showing the tempo the song no longer plays at is the half
    // of the undo you can see. The swing rides on the same entry and needs the same.
    pushTempo();
    pushSwing();
    buildTimeline();
  }
  if (step.trackId !== trackId) { selectSong(step.trackId); }
  else if (bankSig() !== before || arrMoved) {
    // The lane list may have changed under it, so the arrangement is rebuilt too —
    // a row for a track that is no longer there is a row that plays nothing.
    rebuildForShape();
    updateStatus();
  } else {
    buildRack(); applyToEngine(mixFor(trackId)); updateStatus();
    if (noteFxSig() !== fxBefore) buildArrangement();
  }
  toast('undone');
}

/**
 * Re-bank the sequencer without losing your place in the song.
 *
 * `setBank` restarts from bar 1 by design — a new song should start at its top. A
 * voice change is not a new song, so the step is carried across by hand: half a
 * second of silence (setBank's own clean gap) with the playhead where you left it.
 *
 * A stopped desk has nothing to re-bank. Handing the engine a bank is also what makes
 * it PLAY — the sequencer runs whenever there is one — so choosing a voice while
 * paused used to start the song under a transport that said it was stopped, and from
 * there `playing` and the engine disagreed about everything: the next song switch read
 * `playing` as false, skipped its own re-bank, and left the previous song running under
 * the new song's name. Play re-banks with whatever the mix says, so the change is
 * heard the moment there is anything to hear it in.
 */
function rebank() {
  if (!playing) return;
  // Not setBank: that is the song-CHANGE door, and it mutes for half a second on the
  // way through. Choosing a preset is not a song change — it is a question about the
  // bar you are listening to, and the answer has to arrive in it. See reapplyBank.
  Audio.reapplyBank(track.bank, mixFor(trackId), arrFor(trackId));
}

/** The IEC power mark — the same one Logic puts on the left of an insert slot. */
function powerIcon() {
  const NS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 12 12');
  svg.setAttribute('class', 'pwr');
  const ring = document.createElementNS(NS, 'path');
  ring.setAttribute('d', 'M3.6 3.7a3.4 3.4 0 1 0 4.8 0');
  const stem = document.createElementNS(NS, 'path');
  stem.setAttribute('d', 'M6 1.9v3.7');
  svg.append(ring, stem);
  return svg;
}

/**
 * Remove. A drawn multiplication cross — two even diagonals at the same angle —
 * rather than the letter x, which leans and has a different weight in every
 * typeface. Chunkier than the power mark: it is the destructive one.
 */
function closeIcon() {
  const NS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 12 12');
  svg.setAttribute('class', 'pwr cross');
  for (const d of ['M3.3 3.3 8.7 8.7', 'M8.7 3.3 3.3 8.7']) {
    const stroke = document.createElementNS(NS, 'path');
    stroke.setAttribute('d', d);
    svg.append(stroke);
  }
  return svg;
}

/**
 * Where a target keeps its effect chain. A channel, a send and the master each
 * store theirs in a different corner of the mix, and every writer needs all three
 * cases — so there is one of them, and adding a fourth kind of strip is one line.
 */
function storeEffects(m, key, list) {
  // The master keeps its list even when it is empty — the one strip that does. It is
  // stored rather than deleted so this branch stays the same shape as the aux one
  // beside it, and so a future seed here (there was one once: a bypassed bus
  // compressor) cannot come back on the next read after being taken off.
  if (key === '__master') {
    m.masterEffects = list;
  } else if (key.startsWith('__aux:')) {
    const id = key.slice(6);
    m.fx = m.fx || {};
    m.fx[id] = { ...AUX_DEFAULTS[id], ...(m.fx[id] || {}) };
    if (list.length) m.fx[id].effects = list; else delete m.fx[id].effects;
  } else {
    const L = laneOf(m, key);
    if (list.length) L.effects = list; else delete L.effects;
  }
}

/**
 * The insert-slot list every strip carries — channels, sends and master alike, so
 * all three read as the same object. Logic's layout, our palette.
 *
 * `rows` is the longest chain anywhere in the rack plus a spare, not this strip's:
 * every strip reserves the same block so the rule above the slots lands on one line
 * across the whole desk instead of wandering with each channel's count, and the
 * spare is where the next effect goes on whichever strip you are on.
 */
// One line of the insert block: a 23px button, the 2px that sits it off the line
// above, and the 4px gap to the next. The reserved height is counted in these, so
// a chain and the empty slot under it end exactly on the block's bottom edge.
const SLOT_ROW = 29;
// Which slot is being dragged, while it is being dragged. One at a time, so one
// variable — the drag is a gesture, not a state anything else can observe.
let dragFromSlot = null;

function insertSlots(key, label, rows) {
  const el = document.createElement('div');
  el.className = 'fxbtns';
  // The empty slot under the chain is where the next effect would go, so clicking it
  // opens the catalogue. Plain click, not right-click: there is only one thing you
  // could mean by clicking an empty slot, and a menu to choose it from is a step for
  // nothing. Right-click does the same, for anyone who tries it.
  //
  // The OUTLINE, and nothing else. The rest of the block is reserved height — the
  // room the longest chain in the rack needs, which every strip holds so the slots
  // land on one line — and a catalogue opening out of that empty space is a popup
  // from a click that was aimed at the strip. One click on any strip, selected or
  // not: the outline comes up under the pointer before the click lands, so you are
  // always aiming at something you can see.
  const openHere = (ev) => {
    if (!ev.target.classList.contains('addslot')) return;
    ev.preventDefault();
    ev.stopPropagation();
    selectLane(key);
    if (effectsOf(key).length >= MAX_EFFECTS) {
      toast(`${MAX_EFFECTS} effects is the limit on one strip — remove one first`);
      return;
    }
    closeMenu();
    openPicker({ anchor: el, x: ev.clientX, y: ev.clientY });
  };
  el.addEventListener('click', openHere);
  el.addEventListener('contextmenu', openHere);
  const list = effectsOf(key);
  const slots = rows ?? Math.max(1, list.length);
  el.style.height = `${slots * SLOT_ROW - 4}px`;      // no gap hanging off the last line
  list.forEach((e, i) => {
    const def = EFFECT_BY_ID[e.id];
    const btn = document.createElement('button');
    btn.className = e.bypass ? '' : 'on';
    // The power mark toggles the effect; the name opens it. Two targets in one slot,
    // the way an insert slot works everywhere else.
    const power = document.createElement('span');
    power.className = 'pwrhit';
    power.append(powerIcon());
    power.title = `${e.bypass ? 'Enable' : 'Bypass'} ${def?.name || e.id}`;
    const toggle = () => {
      const next = list.map((x, j) => (j === i ? { ...x, bypass: !x.bypass } : x));
      editMix((m) => storeEffects(m, key, next), null);
      bypassOn(key, i, !e.bypass);
      buildRack();
      toast(`${def?.name || e.id} ${next[i].bypass ? 'bypassed' : 'on'} — ${label}`);
    };
    power.onclick = (ev) => { ev.stopPropagation(); toggle(); };
    const name = document.createElement('span');
    name.className = 'fxname';
    name.textContent = def?.short || def?.name || e.id;
    // And out the other side: remove, on the right, on hover. Both marks are
    // revealed by the pointer, so an untouched slot is just a name.
    const remove = document.createElement('span');
    remove.className = 'rmhit';
    remove.append(closeIcon());
    remove.title = `Remove ${def?.name || e.id} from ${label}`;
    remove.onclick = (ev) => {
      ev.stopPropagation();
      setEffects(key, list.filter((_, j) => j !== i));
      toast(`${def?.name || e.id} removed from ${label} — ⌘Z to undo`);
    };
    btn.append(power, name, remove);
    btn.title = `${def?.name || e.id} — click to open it below`
      + `\nThe power mark ${e.bypass ? 'enables' : 'bypasses'} it without leaving the fader`;
    btn.onclick = (ev) => {
      ev.stopPropagation();
      if (ev.altKey) { toggle(); return; }        // ⌥-click still works from anywhere
      // Otherwise: switch to this strip and open this effect, which is what clicking
      // the name of a thing usually means.
      selectLane(key);
      focusDevice(i);
    };

    // Drag a slot onto another to reorder the chain, the same gesture as the cards
    // in the panel below. The order IS the signal path, so being able to shove a
    // filter in front of a delay without opening anything is worth the wiring.
    btn.draggable = true;
    btn.addEventListener('dragstart', (ev) => {
      dragFromSlot = i;
      btn.classList.add('dragging');
      ev.dataTransfer.effectAllowed = 'move';
      ev.dataTransfer.setData('text/plain', String(i));   // Firefox needs a payload
    });
    btn.addEventListener('dragend', () => {
      dragFromSlot = null;
      for (const b of el.children) b.classList.remove('dragging', 'dropzone');
    });
    btn.addEventListener('dragover', (ev) => {
      if (dragFromSlot == null || dragFromSlot === i) return;
      ev.preventDefault();
      btn.classList.add('dropzone');
    });
    btn.addEventListener('dragleave', () => btn.classList.remove('dropzone'));
    btn.addEventListener('drop', (ev) => {
      ev.preventDefault();
      btn.classList.remove('dropzone');
      if (dragFromSlot == null || dragFromSlot === i) return;
      const next = effectsOf(key);
      const [moved] = next.splice(dragFromSlot, 1);
      next.splice(i, 0, moved);
      dragFromSlot = null;
      setEffects(key, next);
      toast(`${EFFECT_BY_ID[moved.id]?.name || moved.id} moved to ${i + 1} of ${next.length}`);
    });

    // Everything you can do to one slot, in one place — the strip's own menu is
    // about the channel, and a right-click on an effect is about the effect.
    btn.addEventListener('contextmenu', (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      selectLane(key);
      const nm = def?.name || e.id;
      const cur = effectsOf(key);
      const room = cur.length < MAX_EFFECTS;
      const reorder = (to) => {
        const next = [...cur];
        const [moved] = next.splice(i, 1);
        next.splice(to, 0, moved);
        setEffects(key, next);
        toast(`${nm} moved to ${to + 1} of ${next.length}`);
      };
      openMenu(ev.clientX, ev.clientY, `${nm} · ${targetLabel(key)}`, [
        { label: 'Open below', run: () => { selectLane(key); focusDevice(i); } },
        { label: e.bypass ? 'Enable' : 'Bypass', run: toggle },
        { label: 'Copy settings', run: () => {
          fxClipboard = { id: e.id, name: nm, params: { ...(e.params || {}) } };
          toast(`${nm} settings copied`);
        } },
        fxClipboard && fxClipboard.id === e.id && {
          label: `Paste settings from ${fxClipboard.name}`,
          run: () => {
            setEffects(key, cur.map((x, j) => (j === i ? { ...x, params: { ...fxClipboard.params } } : x)));
            toast(`${nm} — settings pasted`);
          },
        },
        room && { label: 'Duplicate', run: () => {
          const next = [...cur];
          next.splice(i + 1, 0, JSON.parse(JSON.stringify(cur[i])));
          setEffects(key, next);
          toast(`${nm} duplicated`);
        } },
        room && { label: 'Insert effect before…',
          run: () => openPicker({ at: i, anchor: btn, x: ev.clientX, y: ev.clientY }) },
        room && { label: 'Insert effect after…',
          run: () => openPicker({ at: i + 1, anchor: btn, x: ev.clientX, y: ev.clientY }) },
        i > 0 && { label: 'Move up', run: () => reorder(i - 1) },
        i < cur.length - 1 && { label: 'Move down', run: () => reorder(i + 1) },
        Object.keys(e.params || {}).length && { label: 'Reset to defaults', run: () => {
          setEffects(key, cur.map((x, j) => (j === i ? { id: x.id, ...(x.bypass ? { bypass: true } : {}) } : x)));
          toast(`${nm} back to defaults`);
        } },
        { label: 'Remove', run: () => {
          setEffects(key, cur.filter((_, j) => j !== i));
          toast(`${nm} removed — ⌘Z to undo`);
        } },
      ].filter(Boolean));
    });
    el.append(btn);
  });
  // The next slot, at the end of the chain — the same target whether the strip holds
  // nothing or holds three, so adding a second effect is the click that added the
  // first rather than a right-click and a submenu. Left out when the block has no
  // line spare, which is only the strip carrying the longest chain in the rack: the
  // panel below it ends in its own + card.
  if (list.length < slots && list.length < MAX_EFFECTS) {
    const add = document.createElement('div');
    add.className = 'addslot';
    add.title = `Add an effect to ${label}`;
    el.append(add);
  }
  return el;
}

/**
 * The fader law — where each dB sits along the travel.
 *
 * dB is already logarithmic; a fader marked in dB is not linear in loudness. What a
 * console fader adds on top is a TAPER: the dB are not spread evenly along the
 * travel. Spread evenly over −60…+6, the six dB above unity that a mix actually
 * lives in get a tenth of the fader, while the bottom thirty — the difference
 * between inaudible and slightly less inaudible — get half of it, and every strip on
 * the desk sits jammed against the top of its slot.
 *
 * So: the breakpoints of a console fader, as positions up the travel. Unity three
 * quarters of the way up, the working six dB above it in the top quarter, and the
 * scale falling away faster the further down you go. Straight lines between them,
 * which is all a printed fader scale is.
 *
 * One law and one range for every strip — channels, sends and the master. A fader
 * whose knee means a different gain from the one beside it is a desk you have to
 * remember exceptions about.
 */
const FADER_SCALE = [[0, -60], [0.15, -35], [0.3, -20], [0.5, -10], [0.75, 0], [1, 6]];
// dB, not pixels — FADER_MIN further down is the fader's minimum HEIGHT, which is a
// different thing about the same control.
const FADER_DB_MIN = FADER_SCALE[0][1];
const FADER_DB_MAX = FADER_SCALE[FADER_SCALE.length - 1][1];

/** Position up the travel (0–1) → dB. */
function posToDb(p) {
  const t = clamp(p, 0, 1);
  for (let i = 1; i < FADER_SCALE.length; i++) {
    const [p0, d0] = FADER_SCALE[i - 1];
    const [p1, d1] = FADER_SCALE[i];
    if (t <= p1) return d0 + (d1 - d0) * ((t - p0) / (p1 - p0));
  }
  return FADER_DB_MAX;
}

/** dB → position up the travel (0–1). The inverse of posToDb, on the same table. */
function dbToPos(db) {
  const d = clamp(db, FADER_DB_MIN, FADER_DB_MAX);
  for (let i = 1; i < FADER_SCALE.length; i++) {
    const [p0, d0] = FADER_SCALE[i - 1];
    const [p1, d1] = FADER_SCALE[i];
    if (d <= d1) return p0 + (p1 - p0) * ((d - d0) / (d1 - d0));
  }
  return 1;
}

/**
 * A vertical fader with its meter and dB readout — the same control on every strip
 * type. `meter: false` keeps the space but draws nothing, for a bus the engine has
 * no meter on; the fader still lands on the same line as every other one.
 *
 * The range input holds a POSITION, not a level: dB goes in through dbToPos and
 * comes back out through posToDb, which is what puts the taper on it. Everything
 * outside this function — the mix, the engine, the readout — is in dB throughout.
 */
function faderBlock({ value, onInput, onReset, title, stereo }) {
  const col = document.createElement('div'); col.className = 'fadercol';
  const fw = document.createElement('div'); fw.className = 'faderwrap';
  const fader = document.createElement('input');
  fader.type = 'range'; fader.className = 'fader';
  // Fine enough that a pixel of travel is several steps, so a drag is smooth and the
  // arrow keys move by about a twentieth of a dB where the mixing happens.
  fader.min = 0; fader.max = 1; fader.step = 0.002;
  fader.value = dbToPos(value);
  if (title) fader.title = title;
  const meter = document.createElement('div');
  // `stereo` splits the same 7px into a pair down the middle — see .meter.stereo. One
  // bar or two, the ballistics are per-channel and identical; tick() walks `chans`.
  meter.className = stereo ? 'meter stereo' : 'meter';
  const chans = [];
  for (let i = 0; i < (stereo ? 2 : 1); i++) {
    const fill = document.createElement('i');
    const peak = document.createElement('b');          // the held peak, see tick()
    meter.append(fill, peak);
    chans.push({ fill, peak });
  }
  const { fill, peak } = chans[0];
  fw.append(fader, meter);
  const db = document.createElement('div'); db.className = 'db';
  const fmt = (x) => (x > 0 ? '+' : '') + Number(x).toFixed(1);
  const show = (x) => { db.textContent = fmt(x); };
  // A tenth of a dB is what the readout shows and what the mix stores; the position
  // under it is finer than that, so the number never jitters mid-drag.
  const dbOf = () => Math.round(posToDb(+fader.value) * 10) / 10;
  show(clamp(value, FADER_DB_MIN, FADER_DB_MAX));
  fader.addEventListener('input', () => { const x = dbOf(); show(x); onInput(x); });
  const reset = () => { fader.value = dbToPos(0); show(0); (onReset || onInput)(0); };
  fader.addEventListener('dblclick', reset);
  db.addEventListener('dblclick', reset);
  // The readout types and drags in dB whatever the fader is doing with position.
  makeTypableDb(db, {
    get: dbOf,
    set: (x) => { fader.value = dbToPos(x); },
    min: FADER_DB_MIN, max: FADER_DB_MAX, step: 0.1,
  }, (x) => { show(x); onInput(x); }, fmt);
  col.append(fw, db);
  const sync = (x) => { fader.value = dbToPos(x); show(clamp(x, FADER_DB_MIN, FADER_DB_MAX)); };
  return { col, fw, db, fill, peak, chans, meter, fader, sync };
}

/**
 * The same master trim in the header: one horizontal fader whose rail is also a
 * larger stereo meter. The dB readout only appears during the gesture, so the control
 * remains a single slider rather than becoming a labelled control with a second box.
 */
function masterToolbarBlock({ value, onInput, onReset, title }) {
  const col = document.createElement('div'); col.className = 'mastertoolbar-control';
  const rail = document.createElement('div'); rail.className = 'master-fader-rail';
  const fader = document.createElement('input');
  fader.type = 'range'; fader.className = 'master-fader';
  fader.min = 0; fader.max = 1; fader.step = 0.002;
  fader.setAttribute('aria-label', 'Master volume');
  if (title) fader.title = title;
  const meter = document.createElement('div');
  meter.className = 'meter stereo toolbar-meter'; meter.setAttribute('aria-hidden', 'true');
  const chans = [];
  for (let i = 0; i < 2; i++) {
    const fill = document.createElement('i');
    const peak = document.createElement('b');
    meter.append(fill, peak);
    chans.push({ fill, peak });
  }
  const readout = document.createElement('span');
  readout.className = 'master-fader-readout'; readout.setAttribute('aria-live', 'polite');
  const fmt = (x) => (x > 0 ? '+' : '') + Number(x).toFixed(1);
  const dbOf = () => Math.round(posToDb(+fader.value) * 10) / 10;
  let hideTimer = 0;
  const hideReadout = () => {
    clearTimeout(hideTimer);
    hideTimer = setTimeout(() => readout.classList.remove('show'), 700);
  };
  const show = (x, transient = true) => {
    const text = `${fmt(x)} dB`;
    readout.textContent = text;
    fader.setAttribute('aria-valuetext', text);
    if (!transient) return;
    readout.classList.add('show');
    hideReadout();
  };
  const sync = (x) => {
    fader.value = dbToPos(x);
    show(clamp(x, FADER_DB_MIN, FADER_DB_MAX), false);
  };
  sync(value);
  fader.addEventListener('pointerdown', () => show(dbOf()));
  fader.addEventListener('input', () => { const x = dbOf(); show(x); onInput(x); });
  const reset = () => { sync(0); show(0); (onReset || onInput)(0); };
  fader.addEventListener('pointerup', hideReadout);
  fader.addEventListener('pointercancel', hideReadout);
  fader.addEventListener('dblclick', reset);
  rail.append(meter, readout, fader);
  col.append(rail);
  return { col, rail, fader, readout, chans, meter, sync };
}

/**
 * A strip's right-click menu. Reset used to be a button on every strip: a whole row
 * of height on all fourteen of them, spent on something you press once an hour.
 */
// One strip's settings, held for pasting onto another. `kind` is what it came from,
// because a channel's gain/pan/sends mean nothing on a bus — but an effect chain
// means the same thing on all three, so pasting just the effects always works.
let clipboard = null;

function copyStrip(key, kind) {
  const mix = mixFor(trackId);
  const data = key === '__master' ? { master: mix.master || 0, limiter: !!mix.limiter, effects: effectsOf(key) }
    : key.startsWith('__aux:') ? fxOf(mix)[key.slice(6)]
    : mix.lanes[key] || {};
  clipboard = { kind, from: targetLabel(key), data: JSON.parse(JSON.stringify(data)) };
  toast(`${clipboard.from} copied`);
}

function pasteStrip(key, kind) {
  if (!clipboard || clipboard.kind !== kind) return;
  const { data } = clipboard;
  editMix((m) => {
    if (key === '__master') {
      m.master = data.master || 0;
      m.limiter = !!data.limiter;
      storeEffects(m, key, data.effects || []);
    } else if (key.startsWith('__aux:')) {
      const id = key.slice(6);
      m.fx = m.fx || {};
      // Everything but the chain, which goes through the one writer that knows
      // where each kind of strip keeps it.
      const { effects, ...rest } = data;
      m.fx[id] = { ...AUX_DEFAULTS[id], ...rest };
      storeEffects(m, key, effects || []);
    } else {
      m.lanes[key] = JSON.parse(JSON.stringify(data));
    }
  });
  buildRack();
  applyToEngine(mixFor(trackId));
  toast(`${clipboard.from} → ${targetLabel(key)}`);
}

function pasteEffects(key) {
  if (!clipboard) return;
  const list = JSON.parse(JSON.stringify(clipboard.data.effects || []));
  setEffects(key, list);
  applyToEngine(mixFor(trackId));
  toast(list.length ? `${list.length} effect${list.length === 1 ? '' : 's'} → ${targetLabel(key)}`
    : `${targetLabel(key)} — effects cleared`);
}

/**
 * The CHANNEL menu — one short list, on every strip in the rack.
 *
 * A channel and a track are two different things about one instrument and the desk shows
 * them in two different places: the arrangement row is the TRACK (what it plays, what
 * plays it, whether it is in the song at all) and the mixer strip is the CHANNEL (the
 * signal path — fader, EQ, sends, inserts). Right-click follows that split, so where you
 * clicked already decides what you get.
 *
 * A channel strip used to open the track panel as well, on the reasoning that a channel
 * IS a track. It is, but the panel it opened held both jobs and so did the strip, which
 * left two routes to the same six buttons and no way to guess which one you were about
 * to take. One place each is the whole point.
 *
 * THE ONE EXCEPTION IS THE PRESET EDITOR, and it is here because the strip's head had to
 * give it up. Opening the synthesiser used to be a » that appeared on hover in the corner
 * of the head, drawn over the tail of the preset's own name because there is nowhere else
 * on a 132px column for it to go — a hidden button, on top of a label, on the one part of
 * the strip that is also a drag handle. A menu item costs a right-click and costs the
 * head nothing, and it lands beside **Preset**, which is the other half of the same
 * question: which sound, and then what that sound does.
 *
 * A send return and the master are not tracks, have no preset, and get exactly the list
 * they always had.
 */
function stripMenu(el, key, kind) {
  el.addEventListener('contextmenu', (ev) => {
    if (ev.target.closest('input, select')) return;
    ev.preventDefault();
    selectLane(key);
    const list = effectsOf(key);
    const anyOn = list.some((x) => !x.bypass);
    // Title Case, like every other menu on the desk — including the noun the label is
    // built from, or this one list would be the only place reading "Copy channel".
    const Kind = kind[0].toUpperCase() + kind.slice(1);
    const fx = (clipboard?.data?.effects || []).length;
    // The sound this channel is playing, if it is one the editor can draw. Note the lane
    // preset rather than `laneVoiceId`: a lane still on the sound its BANK names gets the
    // items too, because `editVoice` forks that into the song's own copy — which is what
    // the » on the head used to do from exactly this state.
    const preset = kind === 'channel' ? editablePresetFor(key) : null;
    // Where the right-click was, held for the editor. The menu is gone by the time `run`
    // fires — `openMenu` closes it first — so the pointer has to be captured here or the
    // window has nothing to open beside.
    const at = { x: ev.clientX, y: ev.clientY };
    openMenu(ev.clientX, ev.clientY, targetLabel(key), [
      preset && { label: 'Preset', run: () => openVoicePickerFor(key, at) },
      // Explicit on both, as in the track menu: one button cannot offer a choice, so
      // each of these says in its name which surface it opens.
      preset && { label: 'Edit Preset', run: () => editVoice(key, { advanced: false, at }) },
      // Only the families that HAVE a second surface — KLNG8, MRDR-3, TNGR-2. Absent
      // rather than disabled elsewhere: a button that can never light on this channel is
      // a promise of a screen that does not exist.
      preset && isQuickVoice(preset) && {
        label: 'Edit Advanced', run: () => editVoice(key, { advanced: true, at }),
      },
      { label: `Copy ${Kind}`, run: () => copyStrip(key, kind) },
      clipboard && clipboard.kind === kind && {
        label: `Paste ${Kind} from ${clipboard.from}`, run: () => pasteStrip(key, kind),
      },
      clipboard && fx && {
        label: `Paste ${fx} Effect${fx === 1 ? '' : 's'} from ${clipboard.from}`,
        run: () => pasteEffects(key),
      },
      list.length && {
        label: anyOn ? 'Bypass All Effects' : 'Enable All Effects',
        run: () => {
          setEffects(key, list.map((x) => ({ ...x, bypass: anyOn })));
          toast(anyOn ? `${targetLabel(key)} — effects bypassed` : `${targetLabel(key)} — effects on`);
        },
      },
      { label: `Reset ${Kind}`, run: () => resetTarget(key) },
    ].filter(Boolean));
  });
}

/** The TRACK panel — on the arrangement row, which is where the track lives. */
function trackMenu(el, key) {
  el.addEventListener('contextmenu', (ev) => {
    if (ev.target.closest('input, select')) return;
    ev.preventDefault();
    selectLane(key);
    openTrackEditor(ev.clientX, ev.clientY, key);
  });
}

const menu = () => $('ctxmenu');
function openMenu(x, y, title, items) {
  const el = menu();
  el.textContent = '';
  const h = document.createElement('div'); h.className = 'ctxhead'; h.textContent = title;
  el.append(h);
  for (const it of items) {
    const b = document.createElement('button');
    b.textContent = it.label;
    b.onclick = () => { closeMenu(); it.run(); };
    el.append(b);
  }
  el.style.left = `${x}px`; el.style.top = `${y}px`;
  el.classList.add('show');
  // Measured after it is shown, then pulled back on-screen if it ran off an edge.
  const r = el.getBoundingClientRect();
  el.style.left = `${Math.max(4, Math.min(x, innerWidth - r.width - 6))}px`;
  el.style.top = `${Math.max(4, Math.min(y, innerHeight - r.height - 6))}px`;
}
const closeMenu = () => {
  restorablePopup = null;
  document.dispatchEvent(new Event('mash-close-custom-select'));
  const pickerWasOpen = $('voicepicker')?.classList.contains('show');
  menu().classList.remove('show');
  // A running freeze keeps its panel: it is the render's only progress readout and its
  // only Cancel, and a stray click on the desk must not leave a minutes-long job with
  // nothing showing it. hideFreezeProgress() is what takes it down, when the job ends.
  if (!$('regionedit').classList.contains('freezeprogress')) {
    $('regionedit').classList.remove('show');
    $('regionedit').classList.remove('barfxmodal');
    $('regionedit').classList.remove('notefxmodal');
  }
  $('fxpicker').classList.remove('show');
  $('voicepicker').classList.remove('show');
  if (pickerWasOpen) pendingAddTrack = null;
  const drawer = $('navdrawer');
  const backdrop = $('drawerbackdrop');
  const nav = $('navbtn');
  const wasOpen = drawer?.classList.contains('show');
  drawer?.classList.remove('show');
  backdrop?.classList.remove('show');
  drawer?.setAttribute('aria-hidden', 'true');
  backdrop?.setAttribute('aria-hidden', 'true');
  nav?.setAttribute('aria-expanded', 'false');
  if (wasOpen) nav?.focus();
};
// Anything that is not the popup itself dismisses it.
addEventListener('pointerdown', (e) => {
  // The tour card counts as inside every one of these: three of its cards point AT the
  // drawer or the effect catalogue, and a Next button that closed the thing it is
  // describing would be a tour that cannot get past card 9.
  const customMenu = e.target.closest && e.target.closest('.regcustommenu');
  const inside = customMenu || [menu(), $('regionedit'), $('fxpicker'), $('navdrawer'),
    $('voicepicker'), $('perfdiag'), $('tut')]
    .some((el) => el.contains(e.target));
  const opener = [$('navbtn')].some((el) => el.contains(e.target))
    || (e.target.closest && e.target.closest('.devaddcard'));
  if (!inside && !opener) closeMenu();
}, true);
// Switching browser tabs should not throw away a staged popup: the tab may be
// reloaded or discarded while hidden, and its session snapshot needs the live fields.
// Clicking into another application still dismisses it after the blur settles.
addEventListener('blur', () => setTimeout(() => {
  if (!document.hidden) closeMenu();
}, 0));

/**
 * Bring one effect card into view and flash it. Selecting the strip is what puts
 * the card on screen; this says WHICH of six it was, which the panel cannot show on
 * its own once a chain is long enough to scroll.
 */
function focusDevice(index) {
  // The cards live in a modeless window now. Clicking an insert is an explicit request
  // to see it, so open the window whatever state an old folded-panel preference held.
  if (!$('devices').classList.contains('fxwindow-open')) setDevicesFolded(false);
  requestAnimationFrame(() => {
    const card = $('devrack').querySelector(`.device[data-idx="${index}"]`);
    if (!card) return;
    card.scrollIntoView({ block: 'nearest', inline: 'center', behavior: 'smooth' });
    card.classList.remove('flash');
    void card.offsetWidth;                 // restart the animation on a repeat click
    card.classList.add('flash');
  });
  scheduleDeskFit();
}

/** Put one target back to defaults — the right-click menu, and the R key. */
function resetTarget(key) {
  const label = targetLabel(key);
  // The voice is the one thing on a strip that says what the channel IS rather than
  // what has been done to it — which is exactly why a reset has to take it too. A
  // channel put back to defaults that carries on playing the preset you chose is a
  // strip whose face and whose sound disagree, and nothing on it explains why.
  const seam = seamFor(key);
  const voiceBefore = JSON.stringify(mixFor(trackId).voice || null);
  editMix((m) => {
    if (key === '__master') {
      m.master = 0; m.masterPan = 0; m.limiter = false; delete m.masterEffects;
    }
    else if (key.startsWith('__aux:')) { if (m.fx) delete m.fx[key.slice(6)]; }
    else {
      delete m.lanes[key];
      // A layer keeps its own, exactly as "Reset every channel" leaves it: a
      // duplicated track with no voice makes no sound at all, so clearing it would not
      // put a channel back to defaults, it would empty the lane.
      if (seam && m.voice && !isLayer(key)) {
        delete m.voice[seam.voiceKey];
        if (!Object.keys(m.voice).length) m.voice = undefined;
      }
    }
  });
  // Only a voice change needs the sequencer re-banked, and re-banking costs half a
  // second of silence — so a reset that changed nothing but levels does not spend it.
  if (JSON.stringify(mixFor(trackId).voice || null) !== voiceBefore) rebank();
  buildRack();
  applyToEngine(mixFor(trackId));
  toast(`${label} reset`);
}

function laneOf(mix, key) {
  if (!mix.lanes[key]) mix.lanes[key] = {};
  return mix.lanes[key];
}

// ---- audio -----------------------------------------------------------------
// What the device panel is editing: a channel, the master bus, or a send return.
// All three own an effect chain, so they are the same thing as far as the panel is
// concerned — only where the chain is stored differs.
//
// Remembered across sessions for the same reason the song is: "I am working on the
// bass" outlasts a reload, and finding the strip again before you can hear last
// night's change is a step for nothing. One key, not one per song — the selection
// already survives switching songs, and a lane the new song does not have falls back
// to the master in buildRack.
const LANE_KEY = 'mash-mixer-lane';
let selectedLane = localStorage.getItem(LANE_KEY) || null;

// The preset name on a strip is a two-step control: the first click selects the
// channel, the second one opens the picker. What arms the second step is the NAME you
// clicked, not the selection — a rebuild or a lane going away can move `selectedLane`
// between two clicks of the same word, and when that happens the click you can see
// yourself making has to still mean what it looked like it meant. selectLane disarms
// it whenever the selection lands anywhere else, so a name is never hot on the first
// click after you were somewhere else on the desk.
let armedPresetLane = null;
const armPreset = (key) => { armedPresetLane = key; };
const presetArmed = (key) => armedPresetLane === key || selectedLane === key;

/**
 * Which editor the Notes panel puts up for a channel — or neither.
 *
 *   'roll'  a pitched part, drawn as pitch against time
 *   'kit'   percussion: booleans, one row per drum the song has, on the docked step grid
 *   null    a gesture lane, which builds its own timing inside the gesture — there is
 *           nothing a grid can honestly draw for it
 *
 * A percussion channel used to be `null` as well, and the panel simply emptied. It kept
 * its room while it did, with a note saying the pattern belonged in it; this is that.
 *
 * Only real lanes. The master and the buses are not "a channel with no roll", they are
 * not a channel's part at all, and the roll keeps showing whatever it was on — the same
 * fallback rollShownLane() has always done for them.
 *
 * The PANEL is not affected by any of it: same height, same place, whichever editor is
 * up. Folding it away made every click between a drum strip and a melodic one resize the
 * desk.
 */
const editorFor = (key) => {
  if (!key || key.startsWith('__')) return 'roll';
  if (PERCUSSION_LANES.includes(baseLane(key))) return 'kit';
  return rollEditable(key) ? 'roll' : null;
};
/** Whether the selected channel puts the roll away — for anything the roll owns. */
const laneHidesRoll = (key) => editorFor(key) !== 'roll';
const notesOpen = () => !$('notes').classList.contains('collapsed');
/** There is a roll on screen: the panel is unfolded, and on a channel that has one. */
const notesRollUp = () => notesOpen() && $('desk').dataset.lowerView === 'roll'
  && editorFor(selectedLane) === 'roll';
/** And the same question for the kit. */
const notesKitUp = () => notesOpen() && $('desk').dataset.lowerView === 'pattern';
const fxOf = (mix) => Object.fromEntries(AUXES.map((a) => [a.id, {
  ...AUX_DEFAULTS[a.id],
  ...(mix.fx?.[a.id] || {}),
  eq: { ...AUX_DEFAULTS[a.id].eq, ...(mix.fx?.[a.id]?.eq || {}) },
}]));

function blankCardTarget(card, ev) {
  // A double-click on a control is already meaningful (slider reset, select choice,
  // button action). Only the card itself or a blank part of its grid is an authoring
  // target; the empty add-effect card never receives this handler.
  return ev.target === card || ev.target.classList?.contains('devgrid');
}

function bindDefaultSave(card, { scope, id, name, snapshot }) {
  if (!DEV_USER) return;
  card.addEventListener('dblclick', (ev) => {
    if (!blankCardTarget(card, ev)) return;
    ev.preventDefault();
    ev.stopPropagation();
    saveEffectDefault(scope, id, name, snapshot);
  });
}

async function saveEffectDefault(scope, id, name, snapshot) {
  if (!DEV_USER || STATIC) return;
  closeMenu();
  const ok = await ask(
    `Save new default settings for ${name}`,
    '<p>This writes the current effect-local controls as the default used by future '
      + 'or rebuilt instances. The current mix and live audio stay unchanged.</p>',
    'Save default',
  );
  if (!ok) return;
  let res;
  try {
    res = await fetch('/effect-default-save', {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-mixer-role': 'dev' },
      body: JSON.stringify({ scope, id, params: snapshot() }),
    });
  } catch (err) {
    await tell('Could not save effect default', escapeHtml(err.message || err));
    return;
  }
  const text = await res.text();
  if (!res.ok) {
    await tell('Could not save effect default', escapeHtml(text));
    return;
  }
  toast(`${name} default saved to src/data/effect-presets.js — reload to use it`, 5000);
}

/**
 * The bank as the engine would play it: layers materialised, voice overrides merged.
 *
 * A stopped desk has handed the engine no bank at all — stopping is `setBank(null)` —
 * so the keyboard cannot ask it what the selected channel plays with. applyMix
 * answers that on its way past, and every mix edit goes through applyToEngine, so
 * keeping what it returned is the whole of it. A/B holds the saved mix's bank while
 * the button is down, which is right: you preview what you are hearing.
 */
let appliedBank = null;
const engineBank = () => (playing && Audio.bank) || appliedBank;

/**
 * Push a whole mix onto the engine — the engine's OWN apply, not a copy of it, so
 * what the desk hears is exactly what the game will play and what the renderer will
 * write. The copy that used to live here quietly drifted: it never restored effect
 * chains after its own reset(), and it gave every dry lane a delay send of 1, so
 * releasing A/B could leave the kit echoing when the song says it does not.
 */
function applyToEngine(mix) {
  if (!Audio.mixer) return;
  // Every chain on the desk is about to be torn down and rebuilt, and a graph
  // mid-rebuild is briefly and legitimately silent. Forget the strikes the watchdog
  // has counted so its repair cannot be triggered by the desk's own surgery — see
  // checkAudioHealth.
  health.deadRuns = 0;
  const m = mix || emptyMix();
  // This song's arrangement, before the mix rather than after it: applyMix rebuilds
  // the bank from the song, so it has to know which bars to build. Set every time
  // rather than only when it changes — this function is the one path everything
  // takes to the engine, and a desk holding an edit the engine has forgotten is a
  // grid drawing bars nobody can hear.
  Audio.arrangement = arrFor(trackId) || null;
  // Whatever the desk seeds the master with has to exist in the ENGINE's chain too,
  // or the desk's card index and the live chain index drift apart and the first
  // slider drag on the master writes to the wrong node. The seed is empty now, so
  // this is a no-op in practice — it stays because the two indices have to agree
  // however the seed is filled in, and effectsOf reads the same fallback.
  appliedBank = Audio.applyMix(track?.bank || null,
    m.masterEffects ? m : { ...m, masterEffects: DEFAULT_MASTER_CHAIN() });
  // The mix arrived by resetting every strip, and the reset took the engine's solo
  // with it. Solo belongs to the desk rather than to the mix, so it goes straight
  // back on — see reapplySolo.
  reapplySolo();
}

/** Write one send's settings, and push them straight at the live aux. */
function editFx(id, patch, tag) {
  editMix((m) => {
    m.fx = m.fx || {};
    m.fx[id] = { ...AUX_DEFAULTS[id], ...(m.fx[id] || {}), ...patch };
  }, tag);
  const { effects, eq, level, pan, mute, ...rest } = fxOf(mixFor(trackId))[id];
  if (id === 'delay') {
    // Delay 1's time, feedback and damping are AudioSys nodes; its EQ, level, pan
    // and mute are the mixer's, like every other aux.
    Audio.setDelay(rest);
    Audio.mixer.setAux('delay', { eq, level, pan, mute }, deskTempo());
  } else {
    Audio.mixer.setAux(id, { ...rest, eq, level, pan, mute }, deskTempo());
  }
}

function loadTrack(id) {
  pendingAddTrack = null;
  if (rearrangeActive()) clearRearrangement({ announce: false });
  rearrangeSelectedOperations.clear();
  rearrangeFavourites.length = 0;
  rearrangeClips.length = 0;
  rearrangeLockedSections.clear();
  // A held seed belongs to the arrangement it was pinned on. The next song's recipe is
  // a different song, so the pin has nothing left to hold.
  rearrangeSeedHold = false;
  syncRearrangeSeedHold();
  // A deferred grid open belongs to the song whose button was clicked. If a song
  // switch wins the race, cancel that intent unless the grid is already visible.
  stepSeqWanted = stepSeq.isOpen();
  rememberSongLayout(trackId);
  // Solo does not travel between songs. It is monitoring on one channel of one mix,
  // and the same lane key in the next song is a different part played by a different
  // preset — so a solo left on from the last song opens the new one with most of it
  // silent and nothing on screen explaining why. Cleared before buildRack, so the S
  // buttons are built dark, and before applyToEngine, whose reapplySolo would
  // otherwise push the old solo straight back onto the new mix.
  dropSolo();
  const hasSongLayout = !!songLayouts[id];
  // Apply a remembered closed Notes state before the rack/song build. The shell starts
  // with Notes open, so waiting for restoreSongLayout below would build a whole piano
  // roll only to hide it again — exactly the first-use pause this layout state is meant
  // to avoid.
  if (notesOpenInLayout(songLayouts[id]) === false) setNotesFolded(true, false);
  // A bar selection and the open editor's DOM belong to the song they were built
  // from. Carrying either across this boundary made the old pattern appear under the
  // new song's name; touching it then wrote those old-looking cells into the new
  // song. Clear the selection first and rebuild the grid from the new bank below.
  selectedBar = null;
  trackId = id;
  track = resolveTrack(id);
  resetSongClockMinimum();
  // Restore the track that owned this song's open piano roll before building either
  // view of the song. Older layout records have no lane and retain the previous/global
  // selection; a stale lane is left for buildRack's normal master fallback.
  const layoutLane = notesOpenInLayout(songLayouts[id]) === true
    && typeof songLayouts[id]?.lane === 'string'
    ? songLayouts[id].lane : null;
  if (layoutLane) selectedLane = layoutLane;
  // The same lane in a different song is played by a different preset, or by none —
  // the editor following its lane, by another route. Before buildRack, which is what
  // puts the panel back beside the strip once it knows which preset it is on.
  syncVoiceEditorToLane(voiceEditor.laneKey);
  buildRack();
  syncMasterControls(mixFor(id).master || 0);
  buildTimeline();
  buildArrangement();
  // buildRack selected the restored piano-roll lane before the arrangement rows
  // existed. They exist now, so reveal that track in the finished arrangement.
  syncArrangementLaneSelection({ reveal: true });
  stepSeq.songChanged();
  pianoRoll.songChanged();
  kitRoll.songChanged();
  // The piano roll is visible whenever the notes panel is open on a channel that has
  // one. Make sure it renders its content on initial load and after song switches —
  // and that the header names the new song's preset, which is rarely the old one's.
  syncNotesPanel();
  if (notesRollUp()) pianoRoll.open(true);
  if (notesKitUp()) kitRoll.open(true);
  voiceLibrary.songChanged();
  // The old song is dropped either way. Only doing it while `playing` trusted the
  // desk's own flag about what the engine was up to, and anything that had left the
  // two disagreeing turned a song switch into a second song's worth of controls
  // pointed at the first song's audio. setBank(null) is the engine's "no song" state:
  // if nothing was sounding it costs nothing, and if something was, it stops.
  Audio.setBank(null);
  Audio.clearFrozenLanes();
  // A voice change has to come back through setBank; level edits do not, so the song
  // keeps playing without a gap while you mix.
  if (playing) Audio.setBank(track.bank, mixFor(id), arrFor(id));
  applyToEngine(mixFor(id));
  restoreFrozenToEngine(id);
  syncRollFollowButton();
  // A new song brings its own tempo — its arrangement's, else the one it was written
  // at. After applyToEngine, so the strips it retunes are this song's. And its own
  // feel with it, which is straight unless its arrangement says otherwise.
  pushTempo();
  pushSwing();
  loopAnchor = 0;              // a different song means a different timeline
  pendingLoopAnchor = null;
  parkedAt = 0;
  locA = null;                 // locators don't carry across songs
  locB = null;
  pianoRollTimeSelection = null;
  pianoRollLoopRange = null;
  applyLoop(0);
  renderRearrangeList();
  // The new song's key, straight away if the panel is up. The analysis cache misses on
  // the new bank by identity; the sync rebuilds it when the transport is parked.
  if (rearrangePanelOpen) syncRearrangeKeyReadout();
  if (hasSongLayout) restoreSongLayout(id);
  // A song without a record inherits the current desk once, then owns its own state.
  rememberSongLayout(id);
  updateStatus();
  if (freezeRestoreReady) queueFrozenRestorePrompt(id);
}

// ---- UI --------------------------------------------------------------------
/**
 * Make a readout draggable: pull up or down to change it, click to type it.
 *
 * A number on a mixing desk is a control. Having to find the slider that owns a
 * value before you can nudge it is a step for nothing, and the old behaviour was
 * worse than nothing — dragging over a number selected the text.
 *
 * `moved` is what tells a drag from a click: under three pixels and the pointer was
 * only ever a click, so the type-in opens instead.
 */
function dragNumber(el, { value, set, range, step, onClick }) {
  el.classList.add('draggy');
  let startY = 0, startVal = 0, moved = 0, active = false;
  el.addEventListener('pointerdown', (e) => {
    if (el.querySelector('input')) return;         // already typing into it
    active = true; moved = 0;
    startY = e.clientY; startVal = value();
    el.setPointerCapture(e.pointerId);
    e.preventDefault();                            // and never start a text selection
  });
  el.addEventListener('pointermove', (e) => {
    if (!active) return;
    const dy = startY - e.clientY;
    moved = Math.max(moved, Math.abs(dy));
    // A full range in 200px, a fifth of that with shift held.
    const perPixel = (range / 200) * (e.shiftKey ? 0.2 : 1);
    const next = startVal + dy * perPixel;
    set(Math.round(next / step) * step);
  });
  const end = (e) => {
    if (!active) return;
    active = false;
    try { el.releasePointerCapture(e.pointerId); } catch { /* already gone */ }
    if (moved < 3 && onClick) onClick();
  };
  el.addEventListener('pointerup', end);
  el.addEventListener('pointercancel', end);
}

function slider({ min, max, step, value, fmt, onInput, reset, curve, display }) {
  // When `curve` is set, the HTML range stores a 0–1 POSITION and the value-space
  // number is mapped through a power curve: value = max * (position ^ curve).
  // This gives more fine-grained control at lower values — unity ends up at ~71%
  // of the slider travel with curve=2 instead of dead centre.
  const hasCurve = curve != null && curve > 0 && max > min;
  const toPos = (val) => hasCurve ? (clamp(val, min, max) / (max - min)) ** (1 / curve) : val;
  const fromPos = (pos) => hasCurve ? min + (max - min) * (clamp(pos, 0, 1) ** curve) : pos;
  // The range input goes 0–1 in curve mode, or min–max in linear mode.
  const rMin = hasCurve ? 0 : min;
  const rMax = hasCurve ? 1 : max;
  const rStep = hasCurve ? 0.001 : step;
  const rVal = hasCurve ? toPos(value) : value;
  // `display` lets callers show a different unit in the readout and type-in
  // (e.g. dB on a send whose internal value is linear gain). When absent the
  // raw value is shown and typed.
  const show = display ? (v) => display.format(v) : fmt;
  const parse = display ? (s) => display.parse(s) : null;

  const wrap = document.createElement('div');
  wrap.className = 'row';
  const head = document.createElement('div'); head.className = 'head';
  const k = document.createElement('span'); k.className = 'k';
  const v = document.createElement('span'); v.className = 'v';
  head.append(k, v);
  const input = document.createElement('input');
  input.type = 'range'; input.min = rMin; input.max = rMax; input.step = rStep; input.value = rVal;
  v.textContent = show(value);
  // Click the readout to type an exact value. A slider is fine for finding a
  // setting by ear and useless for dialling in one you already know.
  v.classList.add('typable');
  v.title = 'Drag to change · click to type a value';
  const curveVal = () => hasCurve ? fromPos(+input.value) : +input.value;
  const openEditor = () => {
    if (v.querySelector('input')) return;
    const box = document.createElement('input');
    box.type = 'text'; box.className = 'typein';
    // Show the displayed form so the user edits what they see (e.g. dB, not raw gain).
    box.value = display ? display.format(curveVal()) : String(curveVal());
    v.textContent = '';
    v.append(box);
    box.focus(); box.select();
    const done = (commit) => {
      let n;
      if (commit && parse) {
        n = parse(box.value);
        if (n == null) { v.textContent = show(curveVal()); return; } // unparseable — abort
      } else {
        n = parseFloat(box.value);
      }
      if (commit && Number.isFinite(n)) {
        input.value = hasCurve ? toPos(n) : clamp(n, min, max);
        onInput(curveVal());
      }
      v.textContent = show(curveVal());
    };
    box.addEventListener('keydown', (ev) => {
      ev.stopPropagation();
      if (ev.key === 'Enter') { done(true); }
      else if (ev.key === 'Escape') { done(false); }
    });
    box.addEventListener('blur', () => done(true));
  };
  dragNumber(v, {
    value: () => curveVal(),
    set: (x) => { input.value = hasCurve ? toPos(clamp(x, min, max)) : clamp(x, min, max); v.textContent = show(curveVal()); onInput(curveVal()); },
    range: max - min,
    step,
    onClick: openEditor,
  });
  input.addEventListener('input', () => { v.textContent = show(curveVal()); onInput(curveVal()); });
  // Reset by clicking the label. Double-clicking the slider itself also works, but
  // it is not discoverable and a double-click on a range often reads as a drag.
  const doReset = () => { input.value = hasCurve ? toPos(reset) : reset; v.textContent = show(reset); onInput(reset); };
  k.classList.add('resettable');
  k.title = `Reset to ${show(reset)}`;
  k.addEventListener('click', doReset);
  input.addEventListener('dblclick', doReset);
  wrap.append(head, input);
  return { wrap, label: k, input, readout: v, reset: doReset };
}

const meters = [];
let masterStripControl = null;
let masterToolbarControl = null;

function syncMasterControls(value) {
  masterStripControl?.sync(value);
  masterToolbarControl?.sync(value);
}

function setMasterControlValue(value, tag = null) {
  editMix((m) => { m.master = value; }, tag);
  Audio.mixer?.setMasterTrim(value);
  syncMasterControls(value);
}

function buildMasterToolbar() {
  const mount = $('mastertoolbar');
  if (!mount || masterToolbarControl) return;
  masterToolbarControl = masterToolbarBlock({
    value: mixFor(trackId).master || 0,
    title: 'Master trim, on top of the bank’s own musicTrim',
    onInput: (x) => setMasterControlValue(x, 'master'),
    onReset: (x) => setMasterControlValue(x),
  });
  mount.replaceChildren(masterToolbarControl.col);
}

// Arrangement volume rails share the channel meters' level source, but keep their
// own small DOM readout so the track header remains live even when its mixer strip
// is filtered out of the rack.
const arrangementMeters = new Map();

// Which families of track the desk is showing. A view, not a mix control: the song
// keeps playing every lane, so what you hear while you work on the drums is the song
// with drums in it. Remembered, because "I am working on the percussion" outlasts a
// reload. Numbers come from the full lane list — see buildRack.
const GROUPS_KEY = 'mash-mixer-hidden-groups';
let hiddenGroups = new Set(JSON.parse(localStorage.getItem(GROUPS_KEY) || '[]'));
let laneNumbers = new Map();

// And which PARTS of a strip it is showing — parts, not sections: a section of this
// song is a chorus, and the timeline owns that word. The same kind of switch as the
// families and for the same reason: a view of the desk, not a mix control — a hidden
// EQ is still doing whatever it was set to, and a hidden send still sends. All three
// off leaves the fader, the pan and the mute/solo pair, which is the whole desk when
// balancing is all you are doing. Remembered, like the families.
//
// Every one of them may be off at once — that is the point of them, unlike the family
// switches, where the last one on has nothing to fall back to but an empty rack.
const STRIP_PARTS = [
  { id: 'eq', label: 'EQ', cls: 'no-eq', what: 'the three EQ bands' },
  { id: 'sends', label: 'Sends', cls: 'no-sends', what: 'the send rows' },
  { id: 'effects', label: 'Effects', cls: 'no-fx', what: 'the insert slots' },
];
const PARTS_KEY = 'mash-mixer-hidden-parts';
let hiddenParts = new Set(JSON.parse(localStorage.getItem(PARTS_KEY) || '[]'));

/**
 * Show or hide those parts, by class on the rack — see the #rackwrap.no-* rules.
 * A class rather than a rebuild: nothing about the strips changes, only how much of
 * them is on screen, and a rebuild here would close whatever menu you had open and
 * throw away the fader you were dragging.
 */
function applyStripParts() {
  const wrap = $('rackwrap');
  for (const p of STRIP_PARTS) wrap.classList.toggle(p.cls, hiddenParts.has(p.id));
  // Every rung of the shrink ladder just changed height: a block hidden by hand has
  // none left for the ladder to save by hiding it again.
  forgetStripMetrics();
  // The height the rows gave up goes to the faders, and comes back off them again
  // when the rows return — fitStrips computes both from the window.
  requestAnimationFrame(fitStrips);
}

function buildPartFilter() {
  const wrap = $('partfilter');
  wrap.textContent = '';
  for (const p of STRIP_PARTS) {
    const b = document.createElement('button');
    const name = document.createElement('span');
    name.className = 'lbl';        // what the struck-through `shed` state marks
    name.textContent = p.label;
    b.dataset.part = p.id;         // how markShedParts finds it again
    b.append(partIcon(p.id), name);
    const shown = !hiddenParts.has(p.id);
    b.classList.toggle('off', !shown);
    b.title = `${shown ? 'Hide' : 'Show'} ${p.what} on every strip`
      + ' — this changes what the MIXER shows; nothing is bypassed, reset or muted';
    b.onclick = () => {
      if (hiddenParts.has(p.id)) hiddenParts.delete(p.id); else hiddenParts.add(p.id);
      localStorage.setItem(PARTS_KEY, JSON.stringify([...hiddenParts]));
      buildPartFilter();
      applyStripParts();
    };
    wrap.append(b);
  }
}

function buildLaneFilter(all) {
  const wrap = $('lanefilter');
  wrap.textContent = '';
  // Only the families this song actually has: a Vocal button on a song with no vocal
  // lane is a control that does nothing, which is worse than one that is missing.
  const counts = new Map();
  for (const l of all) counts.set(l.group, (counts.get(l.group) || 0) + 1);
  const redraw = () => {
    localStorage.setItem(GROUPS_KEY, JSON.stringify([...hiddenGroups]));
    buildRack();                 // the rack only — the arrangement keeps every lane
  };

  // No All button: the switches stay where they are when they are off, so putting a
  // family back is the same click that took it away — a second control for that is a
  // second thing to look at for nothing.
  for (const [group, n] of counts) {
    const b = document.createElement('button');
    const name = document.createElement('span');
    name.textContent = group;
    const count = document.createElement('span');
    count.className = 'n';
    count.textContent = String(n);
    b.append(groupIcon(group), name, count);
    const shown = !hiddenGroups.has(group);
    b.classList.toggle('off', !shown);
    b.title = `${shown ? 'Hide' : 'Show'} the ${n} ${group} track${n === 1 ? '' : 's'}`
      + ' — this changes what the MIXER shows; the arrangement keeps every lane and'
      + ' nothing is muted';
    b.onclick = () => {
      if (hiddenGroups.has(group)) hiddenGroups.delete(group); else hiddenGroups.add(group);
      // Hiding the last one would leave an empty desk, which is not a view of anything.
      if (hiddenGroups.size >= counts.size) hiddenGroups.delete(group);
      redraw();
    };
    wrap.append(b);
  }
}

function buildRack() {
  const rack = $('rack');
  // Held across the clear: the sends live inside the rack, so emptying it detaches
  // them, and this reference is what puts them back at the end of the row. Rebuilt
  // rather than assumed, because that also means a build that died between the clear
  // and the re-append — the sends detached, off the document, unfindable — costs one
  // wrong-looking rack instead of a desk that throws on every song you click after.
  let sends = $('sendslot');
  if (!sends) { sends = document.createElement('div'); sends.id = 'sendslot'; }
  // The strips about to be thrown away are what the rack's floor was measured off.
  forgetStripMetrics();
  rack.textContent = '';
  meters.length = 0;
  masterStripControl = null;
  const mix = mixFor(trackId);
  const all = deskLanes(viewBank(), 1);
  // Track numbers come from the whole song, not from what is on screen: hiding the
  // drums must not renumber the bass, or "mute 7" means a different channel every
  // time you change the view.
  laneNumbers = new Map(all.map((l, i) => [l.key, i + 1]));
  const lanes = all.filter((l) => !hiddenGroups.has(l.group));
  // One reserved insert block for the whole rack — sends and master included — so
  // the slots land on the same pixel on every strip rather than wandering up and
  // down with each strip's own count.
  const maxChain = Math.max(
    0,
    ...lanes.map((l) => effectsOf(l.key).length),
    ...AUXES.map((a) => effectsOf(`__aux:${a.id}`).length),
    effectsOf('__master').length,
  );
  // The longest chain and one line more: the spare is the empty slot at the end of
  // the selected strip's chain, and reserving it for the whole rack means selecting
  // a strip reveals an outline rather than moving every fader on the desk down a
  // row. On a rack where something is already at the limit there is nothing to
  // reserve for — a full strip has nowhere to put a seventh effect anyway.
  const slotRows = Math.min(MAX_EFFECTS, maxChain + 1);

  lanes.forEach((lane) => rack.append(channelStrip(lane, mix, slotRows, laneNumbers.get(lane.key))));
  // The preset editor is a rack item too, so it goes back in beside its strip — the
  // clear above detached it. See placeVoiceEditor.
  placeVoiceEditor();

  // The master goes in the left column — the one the arrangement spends on names —
  // so the channels start on the same line their lanes do above. Same strip as a
  // channel in both cases, because that is what they are: a fader, a chain of
  // inserts and somewhere to send.
  const slot = $('masterslot');
  slot.textContent = '';
  slot.append(masterStrip(mix, slotRows));
  if (masterToolbarControl) {
    meters.push({ key: '__master-toolbar', master: true, horizontal: true,
      chans: masterToolbarControl.chans, meter: masterToolbarControl.meter });
  }
  buildLaneFilter(all);          // the switches live in the mixer's header now
  buildPartFilter();             // and the switches for which parts of a strip it shows
  applyStripParts();
  // The sends are the last thing in the rack's own row, not a column beside it —
  // see #sendslot: with room to spare they sit against the right edge, and when the
  // channels overflow they queue up behind the last of them instead.
  sends.textContent = '';
  for (const def of AUXES) sends.append(sendStrip(def, mix, slotRows));
  rack.append(sends);

  const special = selectedLane === '__master' || (selectedLane || '').startsWith('__aux:');
  if (selectedLane && !special && !lanes.some((l) => l.key === selectedLane)) selectedLane = null;
  requestAnimationFrame(fitStrips);

  // Never nothing: the device panel is the biggest surface on the desk, and opening
  // it empty wastes it. The master is the one strip every song has, and the one you
  // want when you have not said otherwise.
  selectLane(selectedLane || '__master');
}

/**
 * The three zones every strip has: a pinned name, a body that scrolls if it must,
 * and a foot pinned to the bottom. Feet are bottom-anchored in all of them, which
 * is what puts every fader in the rack on one line.
 */
function stripShell(key, {
  label, tag, sublabel = null, synth = null, colour, tint, cls = '', number = null,
}) {
  const el = document.createElement('div');
  el.className = `strip ${cls}`.trim();
  el.dataset.lane = key;
  const freezeState = freezeLaneState(trackId, key);
  const frozen = freezeState !== 'live';
  if (frozen) el.classList.add('frozen');
  if (freezeState === 'partial') el.classList.add('partially-frozen');
  if (colour) {
    el.style.setProperty('--lane', colour);
    if (tint) el.style.setProperty('--lanedim', tint);
  }
  const head = document.createElement('div'); head.className = 'striphead';
  // The same number the arrangement row carries, in the corner where a console
  // stencils it: the strips and the track list are one list, counted once.
  if (number != null) {
    const n = document.createElement('span');
    n.className = 'stripnum';
    n.textContent = String(number);
    head.append(n);
  }
  const h = document.createElement('h3'); h.textContent = label;
  head.append(h);
  if (frozen) {
    head.append(freezeMark('freezebadge', freezeState === 'partial' ? '❄ PARTIAL' : '❄ FROZEN'));
  }
  if (sublabel != null) {
    const sub = document.createElement('div');
    sub.className = 'stripsub';
    sub.append(document.createTextNode(sublabel));
    // Beside the category, never under it. Every head in the rack is one line of name
    // over one line of caption and they are level across the whole desk — a second line
    // here would drop this strip's fader out of the row it shares with every other.
    if (synth) {
      const s = document.createElement('span');
      s.className = 'stripsynth';
      s.textContent = synth;
      sub.append(s);
    }
    head.append(sub);
  } else {
    head.append(groupChip(tag));
  }
  // Cursor in the stylesheet rather than inline: a channel strip's head is also a drag
  // handle and wants `grab`, and an inline `pointer` here is a rule no class can beat.
  head.classList.add('headclick');
  head.title = 'Click anywhere on this strip to show its devices below';
  const body = document.createElement('div'); body.className = 'stripbody';
  const foot = document.createElement('div'); foot.className = 'stripfoot';
  el.append(head, body, foot);
  // Any empty part of the strip selects it — hunting for a specific hit target on a
  // strip you are already looking at is friction for nothing. Controls stop the
  // event so dragging a fader does not also re-select.
  el.addEventListener('click', (ev) => {
    if (ev.target.closest('input, button, select')) return;
    selectLane(key);
  });
  return { el, head, body, foot };
}

/**
 * The fader group, centred in the strip. The pan pot used to sit in a slot beside the
 * fader, with a mirrored empty slot opposite holding the centre; it has a line of its
 * own under the fader now, so both slots go and the column centres itself.
 */
function faderRow(fadercol) {
  const row = document.createElement('div');
  row.className = 'faderrow';
  row.append(fadercol);
  return row;
}

/**
 * The pan pot on its own line, between the fader and the mute/solo pair and clear of
 * both — beside the fader it read as something hanging off it, where under it, above
 * the buttons, it is the strip's own control in the order a console puts them.
 *
 * Empty on the master, which has no panner: the row keeps its height either way, so
 * every strip's buttons still land on one line.
 */
function panRow(pan) {
  const row = document.createElement('div');
  row.className = 'panrow';
  if (pan) row.append(pan);
  return row;
}

/** Mute and solo under the fader, sharing the width of the strip. */
function btnRow(...kids) {
  const row = document.createElement('div');
  row.className = 'ctlbtns';
  row.append(...kids);
  return row;
}

/**
 * The master's limiter, on the line the channels keep M and S on. A button rather
 * than a slot or a card: it is not an insert, it cannot be reordered, and it is the
 * last thing on the path whatever else the master is carrying — which is exactly what
 * being down here with the buttons, instead of up in the block with the chain, says.
 *
 * Off by default, and it says so by being unlit: the ceiling costs 6ms of output
 * latency, and a mix that needs it to stay under is a mix to fix on the desk.
 */
function limiterButton(on) {
  const btn = document.createElement('button');
  btn.textContent = 'LIMITER';
  btn.className = `limbtn${on ? ' on' : ''}`;
  btn.title = `The master limiter, a ceiling at −1 dB on the way out — ${on ? 'on' : 'off'}`
    + '\nit costs 6ms of output latency, so it is off unless you put it on';
  btn.onclick = (ev) => {
    ev.stopPropagation();
    setLimiter(!on);
    toast(`Limiter ${on ? 'off' : 'on'}`);
  };
  return btn;
}

/** A stand-in for a control the master has no node for — see .gap-btns. */
function gap(cls) {
  const el = document.createElement('div');
  el.className = `gap ${cls}`;
  return el;
}

/** A delay time reads better in seconds once it is past a second. */
const fmtDelay = (secs) => (secs >= 1 ? `${secs.toFixed(2)}s` : `${Math.round(secs * 1000)}ms`);

/**
 * The line at the top of a bus strip: what its own device is set to, and the way in
 * to change it. The parameters live in the panel below now, and a strip that showed
 * nothing about them left you hunting for where they had gone — this both says what
 * the delay is doing and opens the card that changes it.
 */
function deviceSummary(key, text) {
  const b = document.createElement('button');
  b.className = 'devlink';
  b.textContent = text;
  b.title = `${targetLabel(key)} — its own controls live in the panel below. Click to open them.`;
  b.onclick = (ev) => { ev.stopPropagation(); selectLane(key); };
  return b;
}

// A glyph per family, drawn rather than spelled: at a glance you are looking for
// "the drums" or "the effects", and six kinds of thing tell each other apart faster
// by shape than by reading six words in the same typeface.
//
// They live on the ARRANGEMENT rows, not on the strips. On a 118px strip the mark
// had to be 10px to sit beside the word, and at 10px a microphone and a drum are the
// same smudge; the two-line arrangement header gives the same mark room beside the
// track name, so the strip keeps the plain word.
// `head` is drawn filled — a quaver without a filled note head is a stem with a
// flag on it, which is not a note at all.
const GROUP_ICONS = {
  drums: { d: 'M6 1.6a4.4 4.4 0 1 1 0 8.8 4.4 4.4 0 0 1 0-8.8M1.9 4.6h8.2' },
  melodic: { d: 'M6.7 9.1V2.3c2.5.7 3.5 1.9 3.5 3.5', head: [4.5, 9.1, 2.2] },
  // A closed bolt, filled: as an open stroke it was three lines that never met, and
  // at eleven pixels that reads as a scribble rather than as lightning.
  fx: { d: 'M7.3 1.2 3.4 6.6h2.2l-.7 4.2 3.9-5.6H6.6z', fill: true },
  vocal: { d: 'M6 1.5a1.6 1.6 0 0 1 1.6 1.6v2.4a1.6 1.6 0 0 1-3.2 0V3.1A1.6 1.6 0 0 1 6 1.5M3.2 5.8a2.8 2.8 0 0 0 5.6 0M6 8.6v1.9' },
  send: { d: 'M1.8 8.6h4.4a2.6 2.6 0 0 0 0-5.2H3.9M5.6 1.9 3.7 3.4l1.9 1.5' },
  bus: { d: 'M2 2.8h8M2 6h8M2 9.2h5.4' },
};

// A mark per strip part, for the switches that show and hide them. Same 12px box as
// the family marks, drawn as the thing itself rather than as a letter: two faders at
// different heights for the EQ, the return arrow the send strips already carry, and a
// pair of stacked slots for the insert block.
const PART_ICONS = {
  eq: { d: 'M4 1.6v8.8M8 1.6v8.8M2.6 4.4h2.8M6.6 7.4h2.8' },
  sends: { d: 'M1.8 8.6h4.4a2.6 2.6 0 0 0 0-5.2H3.9M5.6 1.9 3.7 3.4l1.9 1.5' },
  effects: { d: 'M2.2 2.4h7.6v3.4H2.2zM2.2 7h7.6v2.6H2.2z' },
};

/** The family mark on its own, for an arrangement row. */
function groupIcon(tag) { return drawIcon(GROUP_ICONS[tag], tag); }

/** The mark for one of the strip-part switches — see PART_ICONS. */
function partIcon(id) { return drawIcon(PART_ICONS[id], id); }

function drawIcon(spec = { d: '' }, tag = '') {
  const NS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 12 12');
  svg.setAttribute('class', 'grpicon');
  const path = document.createElementNS(NS, 'path');
  path.setAttribute('d', spec.d);
  if (spec.fill) path.setAttribute('class', 'grpfill');   // a solid shape, not an outline
  svg.append(path);
  if (spec.head) {
    const [cx, cy, r] = spec.head;
    const head = document.createElementNS(NS, 'ellipse');
    head.setAttribute('cx', cx); head.setAttribute('cy', cy);
    head.setAttribute('rx', r); head.setAttribute('ry', r * 0.82);
    head.setAttribute('class', 'grpfill');
    svg.append(head);
  }
  const t = document.createElementNS(NS, 'title');
  t.textContent = tag;
  svg.append(t);
  return svg;
}

/** The family this strip belongs to, in a word. */
function groupChip(tag) {
  const el = document.createElement('div');
  el.className = 'grp-tag';
  el.textContent = tag;
  return el;
}

/** One EQ band — the same row on a channel and on a send return. */
function eqRow(band, value, onInput) {
  const r = slider({
    min: -18, max: 18, step: 0.1, value, reset: 0,
    fmt: (x) => (x > 0 ? '+' : '') + x.toFixed(1),
    onInput,
  });
  r.label.textContent = band.toUpperCase();
  r.wrap.classList.add('eqrow');       // what the EQ switch in the header hides
  return r.wrap;
}

// Solo is monitoring only — never written to the draft, never saved — but it does
// have to survive a rack rebuild, so the desk remembers it here rather than in the
// mix. The engine holds the same set; this is what re-draws the lit button.
const soloed = new Set();
const soloedAux = new Set();

/**
 * The M and S pair for one lane. There are two of each on screen — the channel
 * strip and the arrangement row, as in Logic — and pressing either has to light
 * both, so the state lives in the mix and the buttons are only ever a view of it.
 */
function muteSoloPair(key, label) {
  const muted = !!mixFor(trackId).lanes?.[key]?.mute;
  const mute = document.createElement('button');
  mute.textContent = 'M';
  mute.className = 'mutebtn warn' + (muted ? ' on' : '');
  mute.title = `Mute ${label} (M)`;
  mute.onclick = (ev) => {
    ev.stopPropagation();
    setLaneMute(key, !mute.classList.contains('on'));
  };
  const solo = document.createElement('button');
  solo.textContent = 'S';
  solo.className = 'solobtn' + (soloed.has(key) ? ' on' : '');
  solo.title = `Solo ${label} — monitoring only, never saved (S)`;
  solo.onclick = (ev) => {
    ev.stopPropagation();
    setLaneSolo(key, !solo.classList.contains('on'));
  };
  return [mute, solo];
}

function setLaneMute(key, on) {
  editMix((m) => { laneOf(m, key).mute = on; });
  Audio.mixer?.lane(key)?.setMute(on);
  syncLaneButtons(key);
  // Mute and solo silence the keyboard exactly as they silence the song, so the
  // window has to say so the moment it happens — a keyboard that went quiet two
  // clicks ago otherwise reads as a broken keyboard.
  refreshOsk();
}

function setLaneSolo(key, on) {
  if (on) soloed.add(key); else soloed.delete(key);
  Audio.mixer?.lane(key)?.setSolo(on);
  syncLaneButtons(key);
  updateSoloLight();
  refreshOsk();
}

/**
 * One light for "something is soloed", and one click to undo it.
 *
 * Solo is the setting you leave on by accident: it is monitoring, so it is never
 * saved, never shows up in a diff, and a soloed channel three screens to the right
 * sounds exactly like every other channel being broken.
 */
function updateSoloLight() {
  const any = soloed.size > 0 || soloedAux.size > 0;
  const btn = $('clearsolo');
  btn.classList.toggle('on', any);
  btn.title = any
    ? `Soloed: ${[...soloed, ...[...soloedAux].map((id) => `${id} send`)].join(', ')} — click to clear`
    : 'Nothing is soloed';
}

/**
 * Take solo off the desk and off the engine, without saying anything about it.
 *
 * The quiet half of clearAllSolo, for the times solo goes away as part of something
 * larger — opening a song — where a toast would be reporting on a thing the user did
 * not do. The button sweep is a no-op when the rack is about to be rebuilt; it costs
 * a query and it keeps this honest for callers that leave the strips standing.
 */
function dropSolo() {
  for (const key of [...soloed]) { soloed.delete(key); Audio.mixer?.lane(key)?.setSolo(false); syncLaneButtons(key); }
  for (const id of [...soloedAux]) { soloedAux.delete(id); Audio.mixer?.setAuxSolo(id, false); }
  refreshOsk();
  for (const b of document.querySelectorAll('.strip.send .solobtn')) b.classList.remove('on');
  updateSoloLight();
}

function clearAllSolo() {
  const had = soloed.size + soloedAux.size;
  dropSolo();
  if (had) toast('Solo cleared');
}

/**
 * Put the desk's solo back on the engine, after something reset the strips.
 *
 * A mix reaches the engine through applyMix, and the first thing applyMix does is
 * reset every strip — which empties the engine's solo sets along with everything
 * else. The desk keeps its own copy so solo survives a rack rebuild, but nothing
 * ever pushed it back, so any action that re-applied the mix — a preset, a voice,
 * play, pause, holding A/B, undo — quietly un-soloed the channel while its S button
 * stayed lit. From there the button was a lie in the expensive direction: the next
 * click on it read as "turn solo off", so it took two clicks to hear the solo the
 * desk was already claiming to be in.
 */
function reapplySolo() {
  if (!Audio.mixer) return;
  const gone = [];
  for (const key of soloed) {
    const strip = Audio.mixer.lane(key);
    // A lane this mix does not have cannot be soloed, and leaving its key in the set
    // would silence the whole desk instead: solo means "only these", and this one is
    // not here to be heard.
    if (strip) strip.setSolo(true); else gone.push(key);
  }
  for (const key of gone) { soloed.delete(key); syncLaneButtons(key); }
  for (const id of soloedAux) Audio.mixer.setAuxSolo(id, true);
  updateSoloLight();
}

/** Light both copies of a lane's M and S — the strip's and the arrangement row's. */
function syncLaneButtons(key) {
  const sel = `[data-lane="${CSS.escape(key)}"]`;
  const muted = !!mixFor(trackId).lanes?.[key]?.mute;
  for (const b of document.querySelectorAll(`${sel} .mutebtn`)) b.classList.toggle('on', muted);
  for (const b of document.querySelectorAll(`${sel} .solobtn`)) b.classList.toggle('on', soloed.has(key));
}

/**
 * Repaint every control that shows one lane's level, from the mix.
 *
 * A lane's level is on screen in three places at once — the channel fader, the number
 * under it, and the slider on its arrangement row — and each of them can set it. So
 * each of them has to be able to REDRAW the others, or the desk shows one lane at two
 * levels and you have to guess which is playing.
 *
 * It used to be one-way: the fader synced the arrangement row, and the arrangement row
 * patched the fader inline from its own `input` handler. Which meant every path that
 * did not go through that one handler was a path that left something behind — and
 * double-clicking the arrangement row's slider was exactly that. It reset the lane and
 * left the fader standing where it was.
 *
 * `except` is the control the change CAME from, and it is not a nicety: the fader's
 * position is finer than the tenth of a dB the mix stores, so writing the rounded value
 * back into the fader you are dragging makes the thumb stutter under your thumb.
 */
function syncLaneGain(key, { except = null } = {}) {
  const gain = mixFor(trackId).lanes?.[key]?.gain ?? 0;
  const pos = dbToPos(gain);
  const sel = `[data-lane="${CSS.escape(key)}"]`;
  for (const el of document.querySelectorAll(`${sel} .arrgain, .strip${sel} .fader`)) {
    if (el !== except) el.value = pos;
  }
  for (const el of document.querySelectorAll(`.strip${sel} .db`)) {
    // Not while it is being typed into: the readout holds the type-in box, and writing
    // textContent over it removes the box out from under the caret.
    if (el !== except && !el.querySelector('input')) {
      el.textContent = `${gain > 0 ? '+' : ''}${gain.toFixed(1)}`;
    }
  }
}

/**
 * The preset a lane is REALLY playing.
 *
 * `voice` names a library preset and `voiceParams` carries this song's own copy of
 * one — see registerSongVoice. Where there is a copy it is what sounds, so it is what
 * the strip has to label, what the ✎ has to open and what the editor has to edit. One
 * answer, asked everywhere, so the desk cannot disagree with the engine about which
 * sound a channel is making.
 *
 * Registering here as well as in the engine's own merge is not a duplicate: the rack
 * paints before the first applyToEngine of a song, and a lane whose entry is not in
 * the catalogue yet draws as ENGINE — the one thing it certainly is not.
 */
function laneVoiceId(laneKey) {
  const seam = seamFor(laneKey);
  if (!seam) return null;
  const m = mixFor(trackId);
  const params = m.voiceParams?.[seam.voiceKey];
  if (params) return registerSongVoice(seam.voiceKey, trackId, params);
  const chosen = m.voice?.[seam.voiceKey];
  if (chosen) return chosen;
  // The same starter the engine's own merge writes onto an unvoiced independent lane
  // (`defaultAddedVoice` in src/data/voices.js) — a Tom on a drum, a square on anything
  // pitched. Answering `null` for the pitched half is what left an imported song's
  // melodic layers reading `Tom` on the strip: the name fell through to the percussion
  // default below while the lane played the square, or nothing at all.
  const independent = (m.layers || []).some((l) => l.key === laneKey && l.independent);
  if (independent) return defaultAddedVoice(laneKey);
  return null;
}

/** The preset identity shown anywhere the desk names a channel. */
function presetForLane(laneKey) {
  const chosen = laneVoiceId(laneKey);
  return (chosen && VOICES[chosen])
    || (isIndependentLane(laneKey)
      ? VOICES[defaultAddedVoice(laneKey)]
      : defaultVoiceOf(track?.bank, laneKey));
}

/**
 * The preset on a lane that the editor can actually draw, or null.
 *
 * An ENGINE preset is a bundle of bank keys the hand-written voice reads rather than a
 * synth, so there is no panel behind it — `open` in the editor refuses one, and every
 * door to the editor asks this before offering itself. One function, because there are
 * three of those doors now (the channel menu, the track menu and the tour) and three
 * copies of the same two conditions is how they drift.
 */
function editablePresetFor(laneKey) {
  const preset = presetForLane(laneKey);
  return preset && preset.kind !== 'engine' ? preset : null;
}

function presetHeadingFor(laneKey) {
  const preset = presetForLane(laneKey);
  return {
    name: customTrackLabel(laneKey) || preset?.label || targetLabel(laneKey),
    type: preset?.category ? String(preset.category).toUpperCase() : null,
  };
}

/** The actual voice family behind a preset, for the track/region inspector. */
function synthesizerLabelFor(preset) {
  if (!preset) return null;
  if (preset.synth) return String(preset.synth);
  if (preset.kind === 'noise') return 'Noise Synth';
  if (preset.kind === 'drum') return 'KLNG8';
  if (preset.kind === 'engine') return 'Game Engine';
  return preset.kind ? cap(preset.kind) : null;
}

/**
 * The same families as `synthesizerLabelFor`, three characters wide, for the one place
 * that has no room for the word: the strip head, where the abbreviation sits beside the
 * preset's category on the caption line.
 *
 * Three characters for every one of them, because the strips are a rack and a ragged
 * column of 2s and 3s reads as noise. `FM`/`AM` are the ones that pay for it — they are
 * the two everybody would write with two letters — but they are also the two nobody has
 * to decode, so the padding costs nothing to read.
 *
 * The named instruments keep their number (`MR3`, `KL8`) rather than being truncated to
 * letters, which is what stops four M-words — MRDR-3, MonoSynth, MembraneSynth,
 * MetalSynth — collapsing into each other at 8.5px. Two more that would collide are
 * split on purpose: `GME` is the GameSynth preset class, `ENG` is the game's own voice.
 */
const SYNTH_ABBR = {
  'KLNG8': 'KL8',
  'MRDR-3': 'MR3',
  'TNGR-2': 'TN2',
  'Game Engine': 'ENG',
  'MonoSynth': 'MNO',
  'FMSynth': 'FMS',
  'Noise Synth': 'NSE',
  'MembraneSynth': 'MBR',
  'MetalSynth': 'MTL',
  'Synth': 'SYN',
  'DuoSynth': 'DUO',
  'AMSynth': 'AMS',
  'AdditiveSynth': 'ADD',
  'GameSynth': 'GME',
};

/**
 * The strip's synth tag, or nothing at all.
 *
 * Nothing at all is the important half. `presetForLane` answers with a fallback for a
 * lane the catalogue does not know yet — see `laneVoiceId` — and a fallback's `kind` is
 * `engine`, so a tag taken straight off it would stencil ENG onto the one lane that is
 * certainly not the engine. A family this map has never heard of is the same case: leave
 * the line to the category alone rather than inventing three letters for it.
 */
function synthAbbrevFor(preset) {
  if (!preset) return null;
  return SYNTH_ABBR[synthesizerLabelFor(preset)] || null;
}

/**
 * Retitle one arrangement row after its preset changed.
 *
 * The row is the track and the strip is its channel, but both are titled with the same
 * thing: the name of the preset playing the lane. Only the strip was being repainted on
 * a voice change, so choosing a sound from the row's own right-click menu renamed the
 * strip and left the row behind — the one place you were looking.
 *
 * In place rather than through buildArrangement, because nothing about the SHAPE of the
 * song changed: the bars, the meters and the playback marks are all still correct, and
 * rebuilding the grid to write two words would throw them away under a moving playhead.
 * The lane's own name and family are read back off the row, so a lane with no preset
 * falls back to exactly what buildArrangement drew.
 */
function refreshLaneIdentity(laneKey) {
  const row = $('arrgrid')?.querySelector(`.arrrow[data-lane="${CSS.escape(laneKey)}"]`);
  if (!row) return;
  const preset = presetForLane(laneKey);
  const name = row.querySelector('.arrname');
  const category = row.querySelector('.arrpresetcat');
  if (name) {
    name.textContent = customTrackLabel(laneKey)
      || preset?.label || row.dataset.laneLabel || targetLabel(laneKey);
    // markClipped caches the full name to put back as a tooltip; leaving the old one
    // there would title the new name with the preset it replaced.
    delete name.dataset.full;
    markClipped(row);
  }
  if (category) category.textContent = preset?.category || cap(row.dataset.group || 'track');
}

function renderPresetHeading(el, laneKey) {
  el.textContent = '';
  if (!laneKey) return;
  const heading = presetHeadingFor(laneKey);
  const number = laneNumbers.get(laneKey);
  if (number) {
    const trackNumber = document.createElement('span');
    trackNumber.className = 'panelnumber';
    trackNumber.textContent = String(number);
    el.append(trackNumber);
  }
  const name = document.createElement('span');
  name.className = 'panelpreset';
  name.textContent = heading.name;
  el.append(name);
  if (heading.type) {
    const type = document.createElement('span');
    type.className = 'paneltype';
    type.textContent = heading.type;
    el.append(type);
  }
}

/**
 * An edit inside the voice editor, on a preset the SONG owns.
 *
 * A library preset is edited in place in the catalogue and saved to voices.js — the
 * panel's own Save. A song's copy has no home in the catalogue to be saved from: it
 * lives in this song's mix, so its edits are mix edits and this is where they land.
 * That is what puts them in the draft, in the undo stack, in the dirty light and in
 * the file the next Save writes — a preset copied into a song stops being a thing you
 * can lose by reloading.
 *
 * Tagged per voice key so a slider drag coalesces into one undo step, exactly as a
 * fader drag does.
 *
 * The `level` and `peak` that ride along are the editor's live estimates, and they are
 * written here for one reason only: so the mix and the sound agree. Nothing measures
 * them at save. A preset's level is what `voiceGain` divides the lane's target by,
 * which puts a new sound in the right ballpark so your fader stays where you put it —
 * and if an edit has moved the loudness, the fader is right there and the song already
 * saves it.
 * The exact numbers are settled in a batch, on purpose, by tools/measure-voices.js,
 * which is how the library has always worked too.
 */
// `undo: false` is the editor undoing itself — the mix still has to follow the preset
// back, but the step that took it there is the editor's, not the desk's.
function writeSongVoice(id, preset, { undo = true } = {}) {
  const key = songVoiceKey(id, trackId);
  if (!key) return;                     // a library preset: its home is voices.js
  editMix((m) => {
    m.voiceParams = { ...(m.voiceParams || {}), [key]: preset };
  }, `voiceparams:${key}`, { undo });
}

/**
 * Which of a song's voice keys name this preset.
 *
 * Both places a song can say so: its mix, where the desk put it, and its bank, where it
 * was written by hand — including any one section, since a song can change voice
 * part-way through. The answer is the set of keys to pin, because pinning writes a
 * `voiceParams` entry per key and a song using the same preset on two lanes needs two.
 */
function voiceKeysUsing(id, voiceId) {
  const keys = new Set();
  const m = mixFor(id);
  for (const [k, v] of Object.entries(m.voice || {})) if (v === voiceId) keys.add(k);
  const named = (o) => {
    if (!o) return;
    for (const [k, v] of Object.entries(o)) if (k.endsWith('Voice') && v === voiceId) keys.add(k);
  };
  const bank = resolveTrack(id)?.bank;
  named(bank);
  for (const sec of bank?.sections || []) named(sec);
  return [...keys];
}

/**
 * Freeze a preset's CURRENT sound into the songs that play it, then let the library
 * entry move on without them.
 *
 * The third answer to "this preset is in six songs", after updating them all and
 * forking to a new name. Here the library entry keeps its id and its name and becomes
 * the new sound, and the songs you tick stop tracking it: each gets its own copy of
 * what it sounds like right now, written into its mix as `voiceParams`, which
 * `laneVoiceId` reads in preference to the library. So they go on sounding exactly as
 * they do today, whatever happens to the preset afterwards.
 *
 * That last clause is the cost, and it is silent: a song pinned today will not receive
 * a fix made to that preset next month, and nothing on the desk will later explain why
 * it did not move. Which is why this is per-song and opt-in rather than a mode.
 *
 * It writes SONGS THE DESK IS NOT ON, which `saveMix` exists to make impossible — see
 * its note. The guard is right and this is genuinely the other case: that rule is there
 * so mixes are not balanced from memory, and nothing here is balanced at all. Every
 * written song is pinned to the sound it already makes, and each one still gets its own
 * history snapshot on the way, so it stays as undoable as any other save.
 */
async function pinPresetInSongs(voiceId, preset, trackIds) {
  const entries = {};
  for (const id of trackIds) {
    const keys = voiceKeysUsing(id, voiceId);
    if (!keys.length) continue;          // it moved since the list was drawn; nothing to pin
    const cur = JSON.parse(JSON.stringify(mixFor(id)));
    cur.voiceParams = { ...(cur.voiceParams || {}) };
    for (const k of keys) cur.voiceParams[k] = JSON.parse(JSON.stringify(preset));
    entries[id] = cur;
  }
  const ids = Object.keys(entries);
  if (!ids.length) return true;
  // Into the drafts first, so a failed write leaves the pin visible and undoable on the
  // desk rather than silently lost — the same place every other unsaved edit lives.
  for (const id of ids) draft[id] = entries[id];
  localStorage.setItem(LS_KEY, JSON.stringify(draft));
  try {
    const res = await fetch('/save', {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ ids, entries }, null, 2),
    });
    const text = await res.text();
    if (!res.ok) { await tell('Those songs were not pinned', escapeHtml(text)); return false; }
    for (const id of ids) delete draft[id];
    try {
      const body = JSON.parse(text);
      if (body?.mix) saved = body.mix;
      else for (const id of ids) saved[id] = JSON.parse(JSON.stringify(entries[id]));
    } catch {
      for (const id of ids) saved[id] = JSON.parse(JSON.stringify(entries[id]));
    }
    localStorage.setItem(LS_KEY, JSON.stringify(draft));
    updateStatus();
    return true;
  } catch (err) {
    await tell('Those songs were not pinned', escapeHtml(String(err.message || err)));
    return false;
  }
}

/**
 * Library presets carrying edits that are on the sound and nowhere else.
 *
 * The trap this closes: the editor writes straight into the catalogue entry, which is
 * why an edit is audible everywhere the moment you make it and why it rides through a
 * song change. Nothing on disk has moved, though — `Save song` writes the song, not
 * the library — so a reload puts the file's version back and the work is simply gone.
 * The panel could not warn about it either: it forgets its state when it closes, and
 * the loss happens later.
 *
 * A song's own copy is not in here. It lives in the draft mix, which is in
 * localStorage from the moment it is touched, so it survives a reload by construction.
 */
const dirtyLibraryVoices = new Set();

function markVoiceDirty(id, dirty) {
  if (!id || songVoiceKey(id, trackId)) return;   // a copy is saved with its song
  if (dirty) dirtyLibraryVoices.add(id); else dirtyLibraryVoices.delete(id);
  updateStatus();
}

// The only moment the loss can still be prevented. Browsers will not show our words —
// it is their own dialogue — but they show it, and that is the whole job: a reload
// that would have quietly dropped an hour of sound design now asks first.
addEventListener('beforeunload', (ev) => {
  if (!dirtyLibraryVoices.size) return;
  ev.preventDefault();
  ev.returnValue = '';
});

/**
 * Copy the sound on the panel into this song, as the song's own.
 *
 * Nothing is measured here. The copy keeps the level of the preset it was made from,
 * which puts it in the right ballpark, and if the edit has moved the loudness the
 * channel fader is the control for that — the song saves it already. Exact levels are
 * settled in a batch by tools/measure-voices.js, which is where the library's have
 * always come from; a preset that renders silent offline is reported there too.
 *
 * The lane then plays the copy rather than the preset it was made from, which is what
 * moves the editor onto it: `syncVoiceEditorToLane` sees the lane's voice change and
 * follows. From that moment every touch goes to the draft through `writeSongVoice`,
 * and the song's own Save is what puts it on disk.
 */
function saveVoiceToSong(laneKey, preset) {
  const seam = laneKey && seamFor(laneKey);
  if (!seam) { toast('This lane cannot take a voice, so it cannot carry one'); return false; }
  editMix((m) => {
    m.voiceParams = { ...(m.voiceParams || {}), [seam.voiceKey]: preset };
  });
  rebank();
  applyToEngine(mixFor(trackId));
  // Onto the copy, which is what the lane plays now. Then the repaint, which is also
  // what puts the panel back beside its strip.
  syncVoiceEditorToLane(laneKey);
  buildRack();
  refreshOsk();
  toast(`${preset.label} is now ${targetLabel(laneKey)}’s own in ${track.title}`
    + ' — save the song to keep it.', 4000);
  return true;
}

/**
 * Choose what a lane is played BY.
 *
 * A voice is a bank key (`bassVoice`), so it merges onto the bank at schedule time
 * rather than being pushed at a live node the way a fader is — which means it is the
 * one control on this desk that has to go back through setBank to be heard. See
 * `rebank`, which `undo` needs for the same reason.
 *
 * Choosing a preset drops this song's copy of whatever was there. The copy was a
 * version OF the old preset — its envelope, its filter, its name — so keeping it over
 * the top of a new choice would mean picking Sub Sine and hearing the bass you had
 * already shaped, with no way to tell why. Undo puts it back.
 */
function setLaneVoice(laneKey, voiceId, { redraw = true, autoCopy = true } = {}) {
  const seam = seamFor(laneKey);
  const before = mixFor(trackId);
  const hadCopy = !!before.voiceParams?.[seam.voiceKey];
  const layerDef = (before.layers || []).find((l) => l.key === laneKey);
  const independent = !!layerDef?.independent;
  editMix((m) => {
    const v = { ...(m.voice || {}) };
    if (voiceId) v[seam.voiceKey] = voiceId; else delete v[seam.voiceKey];
    m.voice = Object.keys(v).length ? v : undefined;
    if (m.voiceParams?.[seam.voiceKey]) {
      const p = { ...m.voiceParams };
      delete p[seam.voiceKey];
      m.voiceParams = Object.keys(p).length ? p : undefined;
    }
  });
  rebank();
  // The editor goes where the lane goes — onto the new preset, or off the desk when
  // the lane is sent back to the engine. See syncVoiceEditorToLane.
  const closed = syncVoiceEditorToLane(laneKey, { autoCopy });
  // A voice change updates the strip's header and the arrangement identity together.
  // The picker owns the interaction now, so the rack can repaint normally after a choice.
  if (redraw || closed) buildRack();
  applyToEngine(mixFor(trackId));
  // The strip is only half of what names this preset. The track row names it too — and
  // the row is where the right-click that changes it usually starts — so a choice that
  // repainted only the rack left the row you clicked still reading the sound you had
  // just replaced. An independent lane can also change its LABEL here, which moves the
  // row's name as well as its preset, so that one goes through a full rebuild.
  if (independent) buildArrangement(); else refreshLaneIdentity(laneKey);
  // Both note editors title themselves with the preset name as well, and both no-op
  // when they are closed. See rebuildForShape.
  stepSeq.refresh();
  pianoRoll.refresh();
  kitRoll.refresh();
  syncNotesPanel();                     // the Notes header names the preset on the roll
  refreshOsk();                         // the keyboard names what it is playing with
  const gone = hadCopy ? ' — this song’s own copy dropped, ⌘Z to put it back' : '';
  toast((voiceId ? `${targetLabel(laneKey)} → ${VOICES[voiceId].label}`
    : `${targetLabel(laneKey)} → the engine’s own voice`) + gone);
}

// ---- tracks: duplicate, delete, restore -------------------------------------
//
// Everything above this line changes how a track SOUNDS. These four change which
// tracks the song has, which is the one kind of edit the desk could not make: the
// arrangement was whatever the bank said and the only answer to "I want the bass
// doubled with a sub" was to write a second lane into the song file by hand.
//
// Both are stored in the mix (`layers`, `off`) and applied by deskBank, so the song
// file is never rewritten, ⌘Z steps back over them like any other edit, and deleting
// the mix entry puts the song back exactly as it was composed.

/** Rebuild everything that shows the lane list. Both edits below change it. */
function rebuildForShape() {
  // Own the cache invalidation here. A caller should not be able to request a shape
  // rebuild and accidentally repaint the last shaped bank because it forgot to
  // clear one signature first.
  bankCache = { bank: null, sig: null, arr: null, out: null };

  // Repaint from the new lane set before touching the live engine. Re-banking can
  // legitimately do audio work (voice disposal, graph pruning); if that ever throws,
  // a completed mix edit must not leave the deleted strip and arrangement row on
  // screen until the next reload.
  buildRack();
  buildArrangement();
  // The note editors are drawn from the same draft the arrangement is, so a shape
  // change has to reach them too. Undo is the case that showed it: stepping back over
  // a note edit moved the bars, rebuilt the grid above, and left the panel you made
  // the edit in still showing it — the one place you were looking. Both are cheap and
  // both no-op when closed, so this is the choke point rather than the call sites.
  stepSeq.refresh();
  pianoRoll.refresh();
  kitRoll.refresh();
  // M8TRX's missing-kit offer reads the LANE LIST, which is precisely what just changed, and
  // it is the only thing on that panel that does. Here for the same reason the editors are:
  // the choke point rather than the call sites, so the offer cannot outlive its reason
  // whichever way the drums arrived — the offer's own Kit button, the arrangement's +, a
  // delete, or an undo stepping back over any of them. Cheap, and a no-op with the panel
  // shut; nothing in this function runs per frame.
  syncRearrangeDrumControl();
  fitStrips();
  rebank();
  applyToEngine(mixFor(trackId));
}

/** The next free key for a layer of `from`: bass → bass2, then bass3. */
function nextLayerKey(from) {
  const taken = new Set((mixFor(trackId).layers || []).map((l) => l.key));
  for (let n = 2; ; n++) if (!taken.has(`${from}${n}`)) return `${from}${n}`;
}

/**
 * Linked layers laid over a lane — the rows that go with it if it is deleted.
 *
 * Transitive for legacy linked layers only. Independent tracks still carry `from` as
 * family metadata, but own their notes and must survive deletion on either side.
 */
const layersOf = (key) => {
  const all = mixFor(trackId).layers || [];
  const drop = [];
  const sources = new Set([key]);
  // One pass, in creation order: a copy is always declared after the thing it copies.
  for (const l of all) {
    if (l.independent) continue;
    if (!sources.has(l.from)) continue;
    sources.add(l.key);
    drop.push(l);
  }
  return drop;
};
/** A new editor track uses layer-shaped storage, but it is not a duplicate. */
const isIndependentLane = (key) => !!(mixFor(trackId).layers || [])
  .find((l) => l.key === key && l.independent)
  || pendingAddTrack?.key === key;

/**
 * ---- Track order -------------------------------------------------------------------
 *
 * Where the strips sit, dragged rather than inherited.
 *
 * Order used to be entirely derived — `DESK_ORDER` in src/engine/lanes.js, kit first,
 * then whatever LANES says — which is a sensible order for the game's own songs and no
 * order at all for an imported one, where every part is a layer and the desk's idea of
 * "melodic" covers nine strips you would like in a particular sequence.
 *
 * It is stored on the MIX (`order`), beside `layers` and `off`, for the same reason
 * those are: it is a decision about this song's shape, it belongs in the file, and it
 * must never be written into a composition. A song nobody has dragged has no `order`
 * and is ordered exactly as it always was — see `applyStoredOrder`, which also carries
 * a stale list forward rather than making a lane the drag never saw disappear to the
 * bottom of the desk.
 */

/**
 * The dragged track and the layers riding under it, as one contiguous run.
 *
 * A layer is a copy of the part above it, and dragging the bass to the top of the desk
 * while its sub stays behind at strip 9 is not a move anybody meant. So a track takes
 * the layers that are ACTUALLY sitting under it — the run immediately below, not every
 * layer it owns. A layer deliberately dragged somewhere else has been separated on
 * purpose and stays where it was put.
 */
function laneBlock(order, from) {
  const owned = new Set(layersOf(order[from]).map((l) => l.key));
  const block = [order[from]];
  while (owned.has(order[from + block.length])) block.push(order[from + block.length]);
  return block;
}

/**
 * Move a track so it sits where `targetKey` sits.
 *
 * Dragged DOWN it lands after the target, dragged UP it lands before it — the gesture
 * every list with a drag handle in it makes, and the one the effect slots above already
 * make. The whole desk order is written, not a delta: it is nine short strings, it is
 * what the file should say out loud, and a delta against a derived order is a thing
 * nobody could read in a diff.
 */
function reorderLane(key, targetKey) {
  if (!key || !targetKey || key === targetKey) return;
  const cur = deskLanes(viewBank(), 1).map((l) => l.key);
  const from = cur.indexOf(key);
  const to = cur.indexOf(targetKey);
  if (from === -1 || to === -1) return;
  const block = laneBlock(cur, from);
  // Dropping a track onto its own layer would ask it to sit after something that is
  // travelling with it. Nothing to do rather than an order that argues with itself.
  if (block.includes(targetKey)) return;
  const rest = cur.filter((k) => !block.includes(k));
  const at = rest.indexOf(targetKey) + (from < to ? 1 : 0);
  rest.splice(at, 0, ...block);
  if (rest.join('\0') === cur.join('\0')) return;
  editMix((m) => { m.order = rest; });
  // The strips and the rows both come off `deskLanes`, and the track NUMBERS come off
  // the rack — so this has to be the full shape rebuild, not a repaint of one row.
  rebuildForShape();
  const label = targetLabel(key);
  const n = rest.indexOf(key) + 1;
  toast(`${label} moved to ${n} of ${rest.length}`
    + `${block.length > 1 ? `, with ${block.length - 1} layer${block.length > 2 ? 's' : ''}` : ''}`
    + ' — ⌘Z to undo');
}

/**
 * Wire a strip or an arrangement row as a drag handle for its own track.
 *
 * The same listeners as the effect slots and cards, against a different array — one
 * function because the arrangement and the mixer are two views of ONE order, and a
 * reorder that behaved differently depending on which of them you did it in would be
 * two features wearing one name. The lane KEY is the payload rather than an index, so a
 * drag that begins in the arrangement can end on a strip and mean the same thing.
 *
 * `handle` is the part of the row you may drag by, and the drag is armed on mousedown
 * inside it exactly as a device card's is: a permanently draggable strip swallowed the
 * gestures of everything living on it — the preset name, the fader, the pan pot, a
 * drag across the bars to select them — because the container and the control were
 * fighting for one press.
 */
let dragFromLane = null;
const clearLaneDrag = () => {
  for (const n of document.querySelectorAll('.dragging, .dropzone')) {
    n.classList.remove('dragging', 'dropzone');
  }
};
function laneDragHandle(el, handle, key, skip) {
  el.draggable = false;
  handle.classList.add('draghandle');
  handle.addEventListener('mousedown', (ev) => {
    if (skip && ev.target.closest(skip)) return;
    el.draggable = true;
    // Armed for this press only. Left on, the next drag from anywhere inside the strip
    // would be a track move whether or not it started on the handle.
    addEventListener('mouseup', () => { el.draggable = false; }, { once: true });
  });
  el.addEventListener('dragstart', (ev) => {
    dragFromLane = key;
    el.classList.add('dragging');
    ev.dataTransfer.effectAllowed = 'move';
    ev.dataTransfer.setData('text/plain', key);   // Firefox needs a payload
  });
  el.addEventListener('dragend', () => {
    dragFromLane = null;
    el.draggable = false;
    clearLaneDrag();
  });
  el.addEventListener('dragover', (ev) => {
    if (dragFromLane == null || dragFromLane === key) return;
    ev.preventDefault();
    el.classList.add('dropzone');
  });
  el.addEventListener('dragleave', () => el.classList.remove('dropzone'));
  el.addEventListener('drop', (ev) => {
    ev.preventDefault();
    el.classList.remove('dropzone');
    if (dragFromLane == null || dragFromLane === key) return;
    const moved = dragFromLane;
    dragFromLane = null;
    reorderLane(moved, key);
  });
}

/**
 * Duplicate a track: the same part, on a second strip, so a different voice can go
 * under it. The copy is where a layer comes from — a sub under the bass, a pad under
 * the chords, a rimshot doubling the snare — none of which the desk could do before,
 * because there was only ever one strip per part.
 *
 * The channel comes across with it: a layer arriving at unity under a part sitting at
 * −6 is not under it, it is on top of it. Solo does not, because solo is monitoring.
 *
 * A layer is played by a preset and nothing else — it has no hand-written body in the
 * engine — so a lane the voice library cannot play cannot be layered either, and a
 * fresh layer opens the library rather than sitting there silently.
 *
 * The copy is of THIS LANE, whatever kind of lane it is. Copying `baseLane(key)`
 * instead — the engine lane the key is named after — meant duplicating a track that
 * was itself a duplicate, or one of the added tracks every imported song is entirely
 * made of, gave you a strip playing the engine's own `lead` or `tom`: a different part
 * in the bars where the song has one at all, and an empty row in the bars where it does
 * not. The NAME still comes off the base lane, so the copy of `lead3` is `lead2` or
 * `lead4` and the rack still reads in one family.
 *
 * WHERE IT LANDS is directly under the track it copies, which is what the splice into
 * `layers` is for: `deskLanes` orders a family by declaration order, so the position in
 * that list is the position on the desk. Appending put the copy at the bottom of its
 * family — a duplicate of `lead5` arriving as `lead8`, three strips below the part it
 * doubles — and the key could not be renamed into place, because the number in it is a
 * bank key rather than a position.
 *
 * WHAT IT PLAYS IT WITH is the whole preset, not just its name. `voice` names a library
 * preset and `voiceParams` carries the song's own copy of one — a sound edited on this
 * desk, or a song-local preset with nothing in the catalogue behind it (see
 * registerSongVoice). Carrying the name alone gave the copy the LIBRARY version of a
 * sound the source has since edited, or, where the song owns the preset outright,
 * nothing at all: the picker opened on a duplicate that was supposed to arrive ready.
 * The params are copied, not shared, so the two strips can be taken apart afterwards —
 * which is the point of a layer.
 */
function duplicateLane(key) {
  const from = key;
  const seam = seamFor(key);
  if (!seam) {
    toast(`${targetLabel(key)} is a gesture the engine plays, not a part a voice can`
      + ' play — there is nothing to layer');
    return;
  }
  const newKey = nextLayerKey(baseLane(key));
  const newSeam = seamFor(newKey);
  const cur = mixFor(trackId);
  // Only a preset carries over. An ENGINE voice is a bundle of bank keys the
  // hand-written lane reads, and a layer has no hand-written lane — see voicesFor.
  const carried = cur.voice?.[seam.voiceKey];
  const keepVoice = carried && VOICES[carried]?.kind !== 'engine' ? carried : null;
  const keepParams = cur.voiceParams?.[seam.voiceKey];
  // Capture the part before changing its shape. Once the mix marks the new lane as
  // independent, its bank fallback is silence; the arrangement snapshot below is
  // therefore the complete, private note data the duplicate starts with.
  const arr = arrDraftOf();
  const copiedContent = duplicateLaneContent(editBank(), arr, key, newKey);
  editMix((m) => {
    const layers = [...(m.layers || [])];
    // After the source, so the copy is the next row down. `deskBank` reads this list
    // in order and requires a layer's source to be declared before it, which inserting
    // after the source is exactly what preserves — and inserting never reorders the
    // pairs already in it.
    const at = layers.findIndex((l) => l.key === key);
    // An ENGINE lane is not in this list at all: it is the lane the family is named
    // after and it sits above every layer of it, so its copy goes in FRONT of them.
    // Appending put a second bass under bass4 instead of under the bass.
    const firstOfFamily = layers.findIndex((l) => baseLane(l.key) === key);
    const insertAt = at !== -1 ? at + 1
      : firstOfFamily !== -1 ? firstOfFamily : layers.length;
    layers.splice(insertAt, 0,
      { key: newKey, from, independent: true });
    m.layers = layers;
    m.lanes = m.lanes || {};
    const copy = JSON.parse(JSON.stringify(m.lanes[key] || {}));
    delete copy.mute;              // a duplicate you cannot hear is not a duplicate
    m.lanes[newKey] = copy;
    if (keepVoice) m.voice = { ...(m.voice || {}), [newSeam.voiceKey]: keepVoice };
    if (keepParams) {
      m.voiceParams = {
        ...(m.voiceParams || {}),
        [newSeam.voiceKey]: JSON.parse(JSON.stringify(keepParams)),
      };
    }
  });
  // The bars the source does not play in. Only reachable once the mix above has been
  // written — the new lane has to exist on the desk before the arrangement is allowed
  // to name it — and folded into the same undo step, because half of a duplicate is
  // not a thing to be left holding. No render: rebuildForShape below does it once.
  const withBars = copiedContent;
  // And if that half is refused, there is no duplicate: refusing an arrangement edit
  // undoes the step it belongs to, which is the mix edit above. Say nothing more — the
  // refusal has already said why — rather than announcing a track that is not there.
  // This is how the bug above stayed invisible: the copy was rolled back and the toast
  // still read "added under Celeste 2".
  if (withBars !== arr
    && !applyArrangementEdit(withBars, 'duplicate', { undo: false, render: false })) return;
  rebuildForShape();
  selectLane(newKey);
  if (keepVoice || keepParams) {
    toast(`${targetLabel(newKey)} added under ${targetLabel(key)} — same part, same`
      + ' sound. Give it a different one and you have a layer.');
    return;
  }
  // No voice or pattern is carried over: this is a new empty strip. The library is
  // the next thing you were going to open anyway, and opening it says so more plainly
  // than a toast about a strip you have not looked at yet.
  toast(`${targetLabel(newKey)} added — choose the voice it plays`);
  // Under the new track's own row, which is where the gesture that made it was. See
  // `laneAnchor`: the strip is the fallback, not the first answer.
  openVoicePickerFor(newKey);
}

/** Commit the staged Add Track once the user has chosen its first preset. */
function commitPendingAddTrack(laneKey, voiceId) {
  const pending = pendingAddTrack;
  if (!pending || pending.key !== laneKey) return false;
  const seam = seamFor(laneKey);
  if (!seam) { pendingAddTrack = null; return false; }
  pendingAddTrack = null;
  editMix((m) => {
    m.layers = [...(m.layers || []), {
      key: pending.key, from: pending.from, independent: true,
    }];
    m.lanes = m.lanes || {};
    // A newly-added channel is deliberately independent of the selected lane. Keep
    // the neutral state explicit so no live strip, send, EQ, or insert can leak into it.
    m.lanes[pending.key] = emptyLaneMix();
    const voice = { ...(m.voice || {}) };
    if (voiceId) voice[seam.voiceKey] = voiceId;
    else delete voice[seam.voiceKey];
    m.voice = Object.keys(voice).length ? voice : undefined;
  });
  bankCache.sig = null;
  rebuildForShape();
  selectLane(laneKey);
  // The preset trails the name only when it is not already the name. A new track wears
  // its preset's label, so "=808 Clap added — =808 Clap" is what saying both got you.
  const label = targetLabel(laneKey);
  const sound = voiceId && VOICES[voiceId] ? VOICES[voiceId].label : null;
  toast(`${label} added${sound && sound !== label ? ` — ${sound}` : ''}`);
  return true;
}

/**
 * The lane a kit preset belongs on.
 *
 * `homeLane` where a preset names one — it is the only thing that can tell a closed hat
 * from an open one — and the catalogue's own category for the rest, which is how the
 * library already groups them. It decides which piece of the kit an added track IS: the
 * figures it is offered (`PATTERNS` reads the base lane), where it sits in the row order,
 * and what a groove writes to it. Without it every drum added from the `+` would be a tom
 * with somebody else's sound on it.
 */
const CATEGORY_LANE = {
  Kick: 'kick', Snare: 'snare', Clap: 'clap', Hats: 'hats',
  Tom: 'tom', Crash: 'crash', Perc: 'rim',
};
function kitLaneOf(voice) {
  if (!voice) return null;
  if (voice.homeLane) return voice.homeLane;
  // Hats are the one category holding two lanes. The presets that care say so with a
  // `homeLane`; the older ones only say it in their name, and an open hat on the closed
  // hat's row is offered the closed hat's figures — eighths and sixteenths for a sound
  // that plays on the and.
  if (voice.category === 'Hats' && /open/i.test(`${voice.id} ${voice.label}`)) return 'ohats';
  return CATEGORY_LANE[voice.category] || null;
}

/**
 * A whole kit of sounds at once — see KITS in mixer-step-seq.js.
 *
 * Re-voices the drums the song has and brings in the ones it has not, so "hear this song
 * as an 808 record" is one click rather than six. SOUNDS ONLY: not one step is touched,
 * because re-voicing a part somebody has already programmed must not wipe it — the
 * grooves are the button next door.
 *
 * ONE `editMix`, which is the whole reason this is not a loop over `setLaneVoice`. That
 * function does its own edit, its own re-bank and its own rack repaint each time, so six
 * calls would be six undo steps: ⌘Z after trying a kit would take the tom back off it and
 * leave you standing in the middle of a kit you did not want. One edit, one ⌘Z.
 */
function applyKit(name, voices) {
  const lanes = deskLanes(viewBank(), 1).map((l) => l.key);
  // Where a piece lands: the canonical lane when the song has it, otherwise whichever
  // layer is already standing in for that drum — a song with `clap2` and no `clap` has
  // a clap, and giving it a second one is not what "the 808 kit" means.
  const homeFor = (drum) => (lanes.includes(drum) ? drum
    : lanes.find((key) => baseLane(key) === drum) || null);
  const taken = new Set((mixFor(trackId).layers || []).map((l) => l.key));
  // Not `nextLayerKey`: that reads the STORED layers, so a kit adding a clap and a tom
  // in one edit would hand both of them the same key.
  const freeKey = (drum) => {
    for (let n = 2; ; n++) {
      const key = `${drum}${n}`;
      if (!taken.has(key)) { taken.add(key); return key; }
    }
  };
  const revoiced = [];
  const added = [];
  editMix((m) => {
    const voice = { ...(m.voice || {}) };
    const params = { ...(m.voiceParams || {}) };
    let layers = [...(m.layers || [])];
    m.lanes = m.lanes || {};
    for (const [drum, id] of Object.entries(voices)) {
      if (!VOICES[id]) continue;
      const home = homeFor(drum);
      const key = home || freeKey(drum);
      const seam = seamFor(key);
      if (!seam) continue;
      voice[seam.voiceKey] = id;
      // A hand-edited copy of the preset that was there is not this preset — the same
      // reason setLaneVoice drops it.
      delete params[seam.voiceKey];
      if (home) {
        revoiced.push(key);
        // An added track wears its preset's name unless it was named by hand — again
        // setLaneVoice's rule, so a kit swap renames the same channels a single voice
        // change would have, and leaves a "Clap" called Clap.
      } else {
        layers.push({ key, from: drum, independent: true });
        // Neutral, exactly as a track added one at a time is: no send, EQ or insert
        // from whatever strip happened to be selected leaks into it.
        m.lanes[key] = emptyLaneMix();
        added.push(key);
      }
    }
    m.voice = Object.keys(voice).length ? voice : undefined;
    m.voiceParams = Object.keys(params).length ? params : undefined;
    m.layers = layers.length ? layers : undefined;
  });
  if (!revoiced.length && !added.length) { toast(`${name} kit — nothing to change`); return; }
  bankCache.sig = null;
  rebuildForShape();
  const names = (keys) => keys.map((key) => targetLabel(key).toLowerCase()).join(', ');
  // Both halves, because the added channels are the part you would not otherwise notice:
  // they arrive silent, and a strip you did not know had appeared is a strip you go
  // looking for later.
  toast(`${name} kit — ${revoiced.length ? `${names(revoiced)} re-voiced` : 'nothing re-voiced'}`
    + (added.length ? `, ${names(added)} added` : ''));
}

/**
 * Stage a silent, independently sequenced track, then let the preset selector name it.
 *
 * `drumsOnly` is the pattern editor's `+`. The picker is where a new track decides what
 * it IS — pick a pad and it re-keys itself to a melodic lane — and that is right from
 * the arrangement's plus, which adds tracks of every kind. Asked from the kit it is not:
 * the grid it was added from is one row of booleans per drum, and a pad added there is a
 * channel that grid cannot show a single note of.
 */
function addBlankTrack(anchor = null, { drumsOnly = false } = {}) {
  const from = 'tom';
  const newKey = nextLayerKey(from);
  const extras = (mixFor(trackId).layers || []).filter((l) => l.independent
    && PERCUSSION_LANES.includes(baseLane(l.key))).length;
  const label = `Track ${extras + 1}`;
  pendingAddTrack = { key: newKey, from, label, ...(drumsOnly ? { drumsOnly } : {}) };
  const plusRect = anchor?.getBoundingClientRect?.();
  // The arrangement plus is the action's anchor. There is no strip yet, so the
  // selector uses the plus itself rather than a temporary row that would look real.
  const x = plusRect ? plusRect.right + 8 : innerWidth / 2;
  const y = plusRect ? plusRect.top : 120;
  openVoicePicker(x, y, newKey);
}

/**
 * Delete a track from this song.
 *
 * A layer is removed outright — it only ever existed in this mix. A lane of the song
 * itself is taken OFF the mix instead: the bank keeps its notes, this song's desk
 * stops having that channel, and putting it back is one item in the Song Desk drawer. Nothing
 * is written to a composition file, here or ever.
 *
 * Layers standing on the lane go with it. A layer of a part that is no longer in the
 * song is a row playing nothing.
 */
async function deleteLane(key) {
  const label = targetLabel(key);
  const layer = isLayer(key);
  const layerDef = (mixFor(trackId).layers || []).find((l) => l.key === key);
  const independent = !!layerDef?.independent;
  // A layer can carry layers of its own now — a duplicate of a duplicate, a second
  // voice under an added track — so this is asked of every lane, not only the song's.
  const kids = layersOf(key);
  const also = kids.length
    ? `\n\nThe ${kids.length} layer${kids.length === 1 ? '' : 's'} on it `
      + `(${kids.map((l) => targetLabel(l.key)).join(', ')}) ${kids.length === 1 ? 'goes' : 'go'} too.`
    : '';
  const body = (layer
    ? independent
      ? 'It is an added sound, so this removes its pattern, mixer channel and settings.'
      : 'It is a duplicate, so this removes it and its settings.'
    : 'The song keeps the part — this removes the channel and arrangement row from this desk. '
      + 'The other tracks and all song bars stay in place. <b>⌘Z puts it back.</b>')
    + (also ? `<br><br>${escapeHtml(also.trim())}` : '');
  // The track is named here and nowhere else in the gesture: the button that starts it
  // says only `Delete track`, so this is the one place you can check you are about to
  // delete the one you meant. Same verb as the button, so the confirmation reads as the
  // second half of the thing you clicked rather than as a different question.
  const number = laneNumbers.get(key);
  if (!await ask(`Delete ${number ? `track ${number}, ` : ''}${escapeHtml(label)}?`,
    body, 'Delete')) return;
  const drop = new Set([key, ...kids.map((l) => l.key)]);
  // Pattern notes live in the arrangement while the channel itself lives in the
  // mix. Capture and clean both before changing either, then make one undo snapshot
  // so ⌘Z restores the complete instrument rather than only half of it.
  const currentArrangement = arrDraftOf();
  const cleanedArrangement = removeLanes(currentArrangement, [...drop]);
  const arrangementChanged = JSON.stringify(cleanedArrangement)
    !== JSON.stringify(currentArrangement);
  pushUndo(null);
  editMix((m) => {
    m.layers = (m.layers || []).filter((l) => !drop.has(l.key)
      && (l.independent || !drop.has(l.from)));
    if (!m.layers.length) m.layers = undefined;
    if (!layer) m.off = [...new Set([...(m.off || []), key])];
    // A deleted track's name comes out of the desk order too. `applyStoredOrder` would
    // ignore it either way, so this is not correctness — it is so the `order` line in
    // the file is a list of this song's tracks rather than an archaeology of them.
    if (m.order?.length) {
      m.order = m.order.filter((k) => !drop.has(k));
      if (!m.order.length) m.order = undefined;
    }
    if (m.labels) {
      for (const k of drop) delete m.labels[k];
      if (!Object.keys(m.labels).length) m.labels = undefined;
    }
    for (const k of drop) {
      // A deleted LAYER takes its settings with it — nothing will ever read them
      // again. A lane that is only off keeps its channel, so restoring it gives back
      // the strip you had rather than one at unity.
      if (k !== key || layer) delete m.lanes?.[k];
      const s = seamFor(k);
      if (s && m.voice) {
        delete m.voice[s.voiceKey];
        if (!Object.keys(m.voice).length) m.voice = undefined;
      }
    }
  }, null, { undo: false });
  let arrangementError = null;
  if (arrangementChanged) {
    try {
      const entry = entryOf(editBank(), cleanedArrangement);
      arrDraft[trackId] = entry;
      localStorage.setItem(ARRANGE_KEY, JSON.stringify(arrDraft));
    } catch (err) {
      // The mix already owns the structural deletion. Arrangement cleanup is
      // secondary metadata; it must never strand the deleted strip on screen.
      arrangementError = err;
      console.error('Could not clean the deleted track from the arrangement', err);
    }
  }
  // Shape changes are the cache invalidation boundary, even when the lane had no
  // authored arrangement notes. In particular, a freshly-added empty track has no
  // arrangement delta to remove, but its layer still has to disappear from the rack
  // and the arrangement immediately.
  bankCache.sig = null;
  // A row whose CHANNEL has gone has to go with it. Both kits hold their row order
  // steady so that erasing a lane's last note cannot pull the row out from under the
  // pointer that emptied it, and an absent lane looks the same to them either way — so
  // this is the desk saying which of the two just happened. See drumRowOrder.
  stepSeq.forgetRows();
  kitRoll.forgetRows();
  for (const k of drop) { soloed.delete(k); Audio.mixer?.lane(k)?.setSolo(false); }
  updateSoloLight();
  if (drop.has(selectedLane)) {
    selectedLane = null;
    localStorage.removeItem(LANE_KEY);
  }
  // Keep a song-range selection, but detach it from the lane that has gone. Without
  // this, the timeline can keep targeting a key that no longer has a row.
  if (selectedBar && drop.has(selectedBar.key)) selectedBar = { ...selectedBar, key: null };
  let refreshError = null;
  try {
    if (arrangementChanged && !arrangementError) buildTimeline();
    rebuildForShape();
  } catch (err) {
    // rebuildForShape paints before it re-banks, but keep a final DOM postcondition
    // below as well. An audio error is not permission for an old strip to remain.
    refreshError = err;
    console.error('Track was removed but the desk refresh did not finish', err);
  }

  // Postcondition: once the mix says a lane is gone, neither of its two screen
  // representations may survive. This is deliberately after the normal rebuild;
  // it is a safety net for a partially-failed repaint, not a second delete path.
  const after = mixFor(trackId);
  const mixRemoved = layer
    ? !(after.layers || []).some((item) => drop.has(item.key))
    : (after.off || []).includes(key);
  if (mixRemoved) {
    for (const laneKey of drop) {
      document.querySelector(`.arrrow[data-lane="${CSS.escape(laneKey)}"]`)?.remove();
      document.querySelector(`.strip[data-lane="${CSS.escape(laneKey)}"]`)?.remove();
    }
  }
  const warning = arrangementError || refreshError ? ' — refresh warning; reload if audio stopped' : '';
  toast(`${label} removed — ⌘Z to undo${warning}`, warning ? 5000 : 2200);
}


/**
 * Everything about one TRACK, in the window a bar already opens: its name, what plays
 * it, what it plays, the channel it plays through, and exact adjustments across the
 * song. Right-clicking the strip or the arrangement row header lands here.
 *
 * It replaced a list of fixed items because a track is not a list of verbs — half of
 * what you want from one is a value, and typing 3 into Transpose beat picking
 * "Transpose +3" out of a submenu. Mute and solo are the two things deliberately not
 * here: both views already carry those buttons, permanently and with their state on.
 */
function openTrackEditor(x, y, key, options = {}) {
  openRegionEditor(x, y, { laneKey: key, from: 0, to: 0, wholeTrack: true, ...options });
}

function noteFxFor(key) {
  return JSON.parse(JSON.stringify(mixFor(trackId).lanes?.[key]?.noteFx || {}));
}

function setTrackNoteFx(key, next) {
  editMix((m) => {
    m.lanes = m.lanes || {};
    m.lanes[key] = m.lanes[key] || emptyLaneMix();
    if (next?.strum?.enabled || next?.arp?.enabled) m.lanes[key].noteFx = next;
    else delete m.lanes[key].noteFx;
  });
  applyToEngine(mixFor(trackId));
  buildRack();
  // The row's NFX marker and its bar badges are both drawn from the track Note FX,
  // so a grid built before this edit is still showing the setting it replaced.
  buildArrangement();
}

/**
 * Retire a lane's track arpeggiator once its notes have been written out.
 *
 * A whole-song render leaves the arp nothing to apply to, so leaving it armed only
 * means the next bar added to the song quietly arpeggiates rendered material. The
 * strum is a separate decision and stays. No `pushUndo`: this rides the step
 * `applyArrangementEdit` pushed a moment ago, which snapshots mix and arrangement
 * together, so one ⌘Z puts back both the notes and the arp.
 */
function clearTrackArp(key) {
  const current = noteFxFor(key);
  if (!current.arp?.enabled) return;
  const next = { ...current, arp: { ...current.arp, enabled: false } };
  editMix((m) => {
    m.lanes = m.lanes || {};
    m.lanes[key] = m.lanes[key] || emptyLaneMix();
    if (next.strum?.enabled) m.lanes[key].noteFx = next;
    else delete m.lanes[key].noteFx;
  }, undefined, { undo: false });
  applyToEngine(mixFor(trackId));
  buildRack();
  // Bar badges resolve against the track, so the grid drawn a moment ago by
  // applyArrangementEdit is describing an arpeggiator that has just gone.
  buildArrangement();
}

/**
 * The bounds the arpeggiator's range offers, spelled the way the desk spells every other
 * pitch: the same eighty-eight keys as the on-screen keyboard, so a window can be put
 * anywhere a note can be played. The two ends are offered from different slices of that
 * span because the fold needs a whole octave to work in — the highest Lowest and the
 * lowest Highest are a window exactly one octave tall, so no pick on either list is an
 * impossible one.
 */
const NOTE_FX_RANGE_BOUNDS = Array.from(
  { length: NOTE_FX_RANGE_MAX - NOTE_FX_RANGE_MIN + 1 },
  (_, i) => [NOTE_FX_RANGE_MIN + i, deskNoteName(NOTE_FX_RANGE_MIN + i, { fancy: true })]);
const NOTE_FX_RANGE_LO_OPTIONS = NOTE_FX_RANGE_BOUNDS
  .filter(([midi]) => midi <= NOTE_FX_RANGE_MAX - 12);
const NOTE_FX_RANGE_HI_OPTIONS = NOTE_FX_RANGE_BOUNDS
  .filter(([midi]) => midi >= NOTE_FX_RANGE_MIN + 12);
// Desk C2–C4: two octaves around the register a chord lane already sits in, so switching
// the range on is a decision about where the arpeggio lives, not an instant transposition.
const NOTE_FX_RANGE_DEFAULT_LO = 48;
const NOTE_FX_RANGE_DEFAULT_HI = 72;

function openNoteFxEditor(x, y, key, scope = null) {
  if (regionPanelBusy()) return;
  closeMenu();
  restorablePopup = { kind: 'noteFx', laneKey: key,
    scope: scope ? { from: scope.from, to: scope.to } : null };
  const panel = $('regionedit'); panel.textContent = ''; panel.classList.add('notefxmodal');
  const trackDefault = noteFxFor(key);
  const firstOverride = scope ? arrDraftOf().plan?.[scope.from]?.noteFx?.[key] : null;
  const current = firstOverride?.mode === 'on'
    ? { ...trackDefault, ...firstOverride,
      strum: { ...(trackDefault.strum || {}), ...(firstOverride.strum || {}) },
      arp: { ...(trackDefault.arp || {}), ...(firstOverride.arp || {}) } }
    : trackDefault;
  const head = document.createElement('div'); head.className = 'reghead';
  const title = document.createElement('div'); title.className = 'regtitle';
  title.textContent = `Note FX · ${targetLabel(key)}${scope ? ` · bars ${scope.from + 1}–${scope.to + 1}` : ''}`;
  const close = document.createElement('button'); close.className = 'regclose'; close.textContent = '×';
  close.title = 'Close without applying these staged Note FX changes';
  close.setAttribute('aria-label', close.title);
  close.onclick = closeMenu; head.append(title, close); panel.append(head);

  const form = document.createElement('div'); form.className = 'regcontrols notefxcontrols';
  const help = document.createElement('div'); help.className = 'notefxhelp';
  help.textContent = scope
    ? `Apply + Play saves these settings, starts at bar ${scope.from + 1}, and leaves this window open.`
    : 'Apply saves the track Note FX and leaves this window open; it does not start playback.';
  form.append(help);
  const check = (label, value) => {
    const row = document.createElement('label'); row.className = 'regcheck';
    const input = document.createElement('input'); input.type = 'checkbox'; input.checked = !!value;
    row.append(input, document.createTextNode(label)); form.append(row); return input;
  };
  const field = (label, options, value, tip = null) => {
    const row = document.createElement('label'); row.className = 'regcontrol';
    const name = document.createElement('span'); name.textContent = label;
    const select = createCustomSelect({
      label, options, value,
      idPrefix: `notefx-${label.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
    });
    if (tip) {
      row.dataset.tip = tip.name;
      row.dataset.tipsays = tip.says;
      select.dataset.tip = tip.name;
      select.dataset.tipsays = tip.says;
    }
    row.append(name, select); form.append(row); return select;
  };
  const number = (label, min, max, step, value, suffix, tip = null) => {
    const row = document.createElement('label'); row.className = 'regcontrol';
    const name = document.createElement('span'); name.textContent = label;
    const input = document.createElement('input'); input.type = 'number';
    input.min = min; input.max = max; input.step = step; input.value = value;
    const read = document.createElement('div'); read.className = 'regread'; read.textContent = suffix;
    if (tip) {
      row.dataset.tip = tip.name;
      row.dataset.tipsays = tip.says;
    }
    row.append(name, input, read); form.append(row); return input;
  };

  const mode = scope ? field('Bar override', [['inherit', 'Inherit track'], ['off', 'Off in these bars'],
    ['on', 'Use these settings']], firstOverride?.mode || 'inherit', {
      name: 'Bar Note FX override',
      says: 'Bars inherit the track Note FX by default. Use these settings merges this bar’s settings over the track defaults; Off disables the track Note FX in these bars. The two effects are not automatically exclusive, so disable an unwanted Strum or Arpeggiator explicitly.'
    }) : null;

  const strumOn = check('Strum', current.strum?.enabled);
  const strumDir = field('Direction', [['up', 'Up · low to high'], ['down', 'Down · high to low'],
    ['random', 'Random · deterministic']], current.strum?.direction || 'up');
  const gap = number('Gap', 0, 250, 1, current.strum?.gapMs ?? 18, 'milliseconds between notes');
  const arpOn = check('Arpeggiator', current.arp?.enabled);
  const arpDir = field('Pattern', [['up', 'Up'], ['down', 'Down'], ['updown', 'Up / Down'],
    ['downup', 'Down / Up'], ['random', 'Random'], ['asPlayed', 'As played / stored']],
  current.arp?.direction || 'up');
  // Triplet rates, now that the transport can hold them. The arp fires on integral phase
  // (`(step - started) / rate`), which used to make a third impossible however it was
  // spelled — `step` only ever moved in 1s and 0.5s, so `rate: 2/3` fired every TWO
  // sixteenths rather than three to the beat. The counter behind `step` is exact at 48
  // and 96 now, so these land. Same labels and order as the roll's snap menu.
  const arpRate = field('Rate', [[4, '1/4'], [8 / 3, '1/4T'], [2, '1/8'], [4 / 3, '1/8T'],
    [1, '1/16'], [2 / 3, '1/16T'], [0.5, '1/32'], [1 / 3, '1/32T']],
    current.arp?.rate ?? 1);
  const octaves = number('Octaves', 1, 4, 1, current.arp?.octaves ?? 1, 'octaves');
  // Octaves builds the stack; this stops the climb partway up it. Two controls because
  // the useful shape is between the octave counts — a seventh over two octaves cut to
  // five notes is not one octave and not two, and no octave count can spell it.
  const limit = number('Note limit', 0, NOTE_FX_LIMIT_MAX, 1, current.arp?.limit ?? 0,
    'notes · 0 plays the whole stack', {
      name: 'Arpeggiator note limit',
      says: 'Stops the pattern after this many notes, counted up the stack Octaves built — set Octaves to 2 and this to 5 and a seventh plays its four notes plus the lowest one again an octave up. Counted after the range folds, so the number here is the number you hear. Without Repeat the pattern stops there; with Repeat it cycles those notes instead.',
    });
  const rangeTip = {
    name: 'Arpeggiator range',
    says: 'Folds every arpeggiated note by whole octaves until it lands between these two, so the pattern plays in the same register whatever octave the chord was written in. Notes already inside keep their octave. The window is at least an octave tall — moving one end pushes the other — and an octave stack taller than the window folds back into it rather than sounding above it.',
  };
  const rangeOn = check('Keep notes inside a range', current.arp?.rangeLimit);
  const rangeLo = field('Lowest', NOTE_FX_RANGE_LO_OPTIONS,
    current.arp?.rangeLo ?? NOTE_FX_RANGE_DEFAULT_LO, rangeTip);
  const rangeHi = field('Highest', NOTE_FX_RANGE_HI_OPTIONS,
    current.arp?.rangeHi ?? NOTE_FX_RANGE_DEFAULT_HI, rangeTip);
  // The fold needs a whole octave to work in — in anything shorter some pitch class has
  // nowhere to land. Rather than take a narrower window and quietly play a wider one,
  // the two ends push each other apart on screen, so the panel reads as it sounds.
  const keepAnOctave = (moved) => {
    const lo = Number(rangeLo.value);
    const hi = Number(rangeHi.value);
    if (hi - lo >= 12) return;
    if (moved === rangeLo) rangeHi.value = lo + 12;
    else rangeLo.value = hi - 12;
  };
  rangeLo.addEventListener('input', () => keepAnOctave(rangeLo));
  rangeHi.addEventListener('input', () => keepAnOctave(rangeHi));
  const repeat = check('Repeat pattern', current.arp?.repeat !== false);
  const gate = number('Gate', 1, 150, 1, current.arp?.gate ?? 80, 'percent of rate');
  const retrigger = field('Retrigger', [['chord', 'Each chord'], ['bar', 'Each bar'],
    ['continuous', 'Continuous']], current.arp?.retrigger || 'chord');
  const latch = check('Latch until the next chord', current.arp?.latch);
  // A bar editor opens in Inherit mode so merely opening and applying it cannot create
  // an empty override. Once somebody actually edits a Note FX control, however, that
  // edit is necessarily meant for these bars; leaving it on Inherit silently threw the
  // change away and made single-bar Note FX appear broken.
  const armBarOverride = () => {
    if (mode) mode.value = 'on';
  };
  for (const control of [strumOn, strumDir, gap, arpOn, arpDir, arpRate, octaves, limit,
    rangeOn, rangeLo, rangeHi,
    repeat, gate, retrigger, latch]) control.addEventListener('input', armBarOverride);
  panel.append(form);

  const playBarScope = () => {
    if (!scope) return;
    selectLane(key);
    markBar(key, scope.from, scope.to);
    jumpTo(scope.from * 16, { start: true, immediate: true });
  };
  const collect = () => ({
    strum: { enabled: strumOn.checked, direction: strumDir.value,
      gapMs: clamp(Number(gap.value) || 0, 0, 250) },
    arp: { enabled: arpOn.checked, direction: arpDir.value,
      rate: clamp(Number(arpRate.value) || 1, 1 / 3, 4),
      octaves: clamp(Math.round(Number(octaves.value) || 1), 1, 4),
      limit: clamp(Math.round(Number(limit.value) || 0), 0, NOTE_FX_LIMIT_MAX),
      rangeLimit: rangeOn.checked,
      rangeLo: clamp(Math.round(Number(rangeLo.value) || NOTE_FX_RANGE_DEFAULT_LO),
        NOTE_FX_RANGE_MIN, NOTE_FX_RANGE_MAX - 12),
      rangeHi: clamp(Math.round(Number(rangeHi.value) || NOTE_FX_RANGE_DEFAULT_HI),
        NOTE_FX_RANGE_MIN + 12, NOTE_FX_RANGE_MAX),
      repeat: repeat.checked,
      gate: clamp(Number(gate.value) || 80, 1, 150), retrigger: retrigger.value,
      latch: latch.checked },
  });
  const applyNoteFx = () => {
    const next = collect();
    if (scope) {
      const override = mode.value === 'inherit' ? null
        : mode.value === 'off' ? { mode: 'off' } : { mode: 'on', ...next };
      const ok = applyArrangementEdit(setBarNoteFx(arrDraftOf(), scope.from, scope.to, key, override), '');
      if (!ok) return;
      playBarScope();
      toast(`Playing ${targetLabel(key)} from bar ${scope.from + 1} with Note FX — ⌘Z to undo`);
    } else {
      setTrackNoteFx(key, next);
      toast(`${targetLabel(key)} Note FX applied — ⌘Z to undo`);
    }
  };

  const foot = document.createElement('div'); foot.className = 'regfoot notefxfoot';
  const renderButton = document.createElement('button');
  renderButton.className = 'notefxrender';
  renderButton.textContent = 'Render Arp to Notes';
  renderButton.title = scope
    ? `Write ${targetLabel(key)}'s arpeggiator as ordinary notes in these bars`
    : `Write ${targetLabel(key)}'s arpeggiator as ordinary notes across the song`;
  renderButton.disabled = !resolveNoteFx(trackDefault,
    scope ? arrDraftOf().plan?.[scope.from] : null, key)?.arp?.enabled;
  renderButton.onclick = () => {
    const draft = arrDraftOf();
    const from = scope?.from ?? 0;
    const to = scope?.to ?? Math.max(0, draft.plan.length - 1);
    // A whole-song render consumes the track arpeggiator outright, so it is retired
    // here rather than suppressed bar by bar. Telling the render that up front is what
    // lets it leave the bars unmarked instead of stamping an arp-off override on
    // every one of them.
    const retireTrackArp = !scope && Boolean(trackDefault.arp?.enabled);
    const ok = applyArrangementEdit(
      renderArpToNotes(editBank(), draft, from, to, key, trackDefault,
        { trackArpCleared: retireTrackArp }), '');
    if (!ok) return;
    if (retireTrackArp) clearTrackArp(key);
    if (scope) {
      selectLane(key);
      markBar(key, from, to);
      jumpTo(from * 16, { start: true, immediate: true });
      toast(`Playing ${targetLabel(key)} from bar ${from + 1} with rendered Note FX — ⌘Z to undo`);
    } else {
      toast(`${targetLabel(key)} arpeggiator rendered to notes and switched off — ⌘Z to undo`);
      // The panel is now describing an arp that no longer exists. Redraw it from the
      // track it just changed, so Render reads as spent rather than still offered.
      openNoteFxEditor(x, y, key, scope);
    }
  };
  const clear = document.createElement('button'); clear.textContent = scope ? 'Inherit Track' : 'Clear Note FX';
  clear.onclick = () => {
    if (scope) {
      const ok = applyArrangementEdit(setBarNoteFx(arrDraftOf(), scope.from, scope.to, key, null), '');
      if (!ok) return;
      playBarScope();
      toast(`Playing ${targetLabel(key)} from bar ${scope.from + 1} with track Note FX — ⌘Z to undo`);
    } else {
      setTrackNoteFx(key, {});
      toast(`${targetLabel(key)} Note FX cleared — ⌘Z to undo`);
    }
  };
  const closeButton = document.createElement('button'); closeButton.textContent = 'Close';
  closeButton.title = 'Close without applying these staged Note FX changes';
  closeButton.setAttribute('aria-label', closeButton.title);
  closeButton.onclick = closeMenu;
  const applyButton = document.createElement('button');
  applyButton.className = `regapply${scope ? ' notefxplay' : ''}`;
  applyButton.textContent = scope ? 'Apply + Play' : 'Apply';
  applyButton.title = scope
    ? `Save these Note FX settings and play ${targetLabel(key)} from bar ${scope.from + 1}`
    : `Save ${targetLabel(key)}'s track Note FX without starting playback`;
  applyButton.setAttribute('aria-label', applyButton.title);
  applyButton.onclick = applyNoteFx;
  foot.append(renderButton, clear, closeButton, applyButton); panel.append(foot);
  panel.style.left = `${x}px`; panel.style.top = `${y}px`; panel.classList.add('show');
  const rect = panel.getBoundingClientRect();
  panel.style.left = `${Math.max(6, Math.min(x, innerWidth - rect.width - 6))}px`;
  panel.style.top = `${Math.max(6, Math.min(y, innerHeight - rect.height - 6))}px`;
}

function openBarEffectsEditor(x, y, key, { from, to, chain: restoredChain = null }) {
  if (regionPanelBusy()) return;
  closeMenu();
  const panel = $('regionedit'); panel.textContent = ''; panel.classList.add('barfxmodal');
  let chain = JSON.parse(JSON.stringify(restoredChain
    || arrDraftOf().plan?.[from]?.inlineFx?.[key] || []));
  restorablePopup = { kind: 'barEffects', laneKey: key, from, to, chain };
  const head = document.createElement('div'); head.className = 'reghead';
  const title = document.createElement('div'); title.className = 'regtitle';
  title.textContent = `Bar Effects · ${targetLabel(key)} · bars ${from + 1}–${to + 1}`;
  const close = document.createElement('button'); close.className = 'regclose'; close.textContent = '×';
  close.title = 'Close without applying these staged changes';
  close.setAttribute('aria-label', 'Close without applying these staged changes');
  close.onclick = closeMenu; head.append(title, close); panel.append(head);

  const form = document.createElement('div'); form.className = 'regcontrols barfxcontrols';
  const list = document.createElement('div'); list.className = 'barfxlist';
  const status = document.createElement('div'); status.className = 'barfxstatus';
  const chainNames = () => chain.map((effect) => EFFECT_BY_ID[effect.id]?.short
    || EFFECT_BY_ID[effect.id]?.name || effect.id).join(' + ');
  const refreshStatus = () => {
    status.textContent = chain.length
      ? `${chainNames()} replaces the channel inserts only in bars ${from + 1}–${to + 1}.`
        + ' Apply + Play saves it, starts at this range, and leaves this window open.'
      : `No bar insert is active in bars ${from + 1}–${to + 1}. The normal channel plays there.`;
  };
  const rememberChain = () => {
    if (restorablePopup?.kind === 'barEffects') {
      restorablePopup.chain = JSON.parse(JSON.stringify(chain));
    }
  };
  const draw = () => {
    rememberChain();
    refreshStatus();
    list.textContent = '';
    if (!chain.length) {
      const empty = document.createElement('div'); empty.className = 'devnote';
      empty.textContent = 'No bar effects. Later bars use the normal channel and any tail from this chain can finish.';
      list.append(empty);
    }
    chain.forEach((effect, index) => {
      const def = EFFECT_BY_ID[effect.id];
      const name = def?.name || effect.id;
      const card = document.createElement('div');
      card.className = `device barfxdevice${effect.bypass ? ' bypassed' : ''}`;
      card.dataset.idx = String(index);
      const bar = document.createElement('div'); bar.className = 'devbar';
      const bypass = document.createElement('button');
      bypass.className = `devtoggle${effect.bypass ? '' : ' on'}`;
      bypass.append(powerIcon());
      bypass.title = effect.bypass ? `Enable ${name}` : `Bypass ${name}`;
      bypass.setAttribute('aria-label', bypass.title);
      bypass.onclick = () => { chain[index] = { ...chain[index], bypass: !effect.bypass }; draw(); };
      const heading = document.createElement('h4'); heading.textContent = name;
      const up = document.createElement('button'); up.className = 'barfxmove'; up.textContent = '↑';
      up.disabled = index === 0; up.title = `Move ${name} earlier in the chain`;
      up.setAttribute('aria-label', up.title);
      up.onclick = () => {
        if (index <= 0) return;
        [chain[index - 1], chain[index]] = [chain[index], chain[index - 1]]; draw();
      };
      const down = document.createElement('button'); down.className = 'barfxmove'; down.textContent = '↓';
      down.disabled = index === chain.length - 1; down.title = `Move ${name} later in the chain`;
      down.setAttribute('aria-label', down.title);
      down.onclick = () => {
        if (index >= chain.length - 1) return;
        [chain[index], chain[index + 1]] = [chain[index + 1], chain[index]]; draw();
      };
      const remove = document.createElement('button'); remove.className = 'devclose';
      remove.append(closeIcon());
      remove.title = `Remove ${name} from this bar effect snapshot`;
      remove.setAttribute('aria-label', remove.title);
      remove.onclick = () => { chain.splice(index, 1); draw(); };
      bar.append(bypass, heading, up, down, remove); card.append(bar);
      const grid = document.createElement('div'); grid.className = 'devgrid'; card.append(grid);
      fillEffectControls({
        grid, def, entry: effect, rebuild: draw,
        patch: (params) => {
          if (!chain[index]) return;
          chain[index] = { ...chain[index], params: { ...(chain[index].params || {}), ...params } };
          rememberChain();
        },
        replaceParams: (params) => {
          if (!chain[index]) return;
          chain[index] = { ...chain[index], params };
          rememberChain();
        },
      });
      list.append(card);
    });
  };
  form.append(status, list);
  const addRow = document.createElement('label'); addRow.className = 'regcontrol';
  const addName = document.createElement('span'); addName.textContent = 'Add effect';
  const picker = document.createElement('select');
  picker.add(new Option('Choose an effect…', ''));
  for (const def of EFFECTS) picker.add(new Option(def.name, def.id));
  const add = document.createElement('button'); add.textContent = 'Add';
  add.disabled = true;
  picker.onchange = () => { add.disabled = !picker.value; };
  add.onclick = () => {
    if (chain.length >= MAX_EFFECTS) return toast(`A bar holds at most ${MAX_EFFECTS} effects`);
    const def = EFFECT_BY_ID[picker.value];
    if (def) chain.push({ id: def.id, params: JSON.parse(JSON.stringify(def.defaults || {})) });
    draw();
  };
  add.title = 'Add the selected effect to the end of this bar effect snapshot';
  add.setAttribute('aria-label', add.title);
  const addHelp = document.createElement('div'); addHelp.className = 'barfxhelp';
  addHelp.textContent = 'Add creates an editable card. Changes remain staged until Apply.';
  addRow.append(addName, picker, add, addHelp); form.append(addRow); panel.append(form); draw();

  const foot = document.createElement('div'); foot.className = 'regfoot barfxfoot';
  const snapshot = document.createElement('button'); snapshot.textContent = 'Snapshot Inserts';
  snapshot.title = 'Copy this channel’s current insert chain into the bar snapshot';
  snapshot.setAttribute('aria-label', snapshot.title);
  snapshot.onclick = () => { chain = JSON.parse(JSON.stringify(effectsOf(key).slice(0, MAX_EFFECTS))); draw(); };
  const clear = document.createElement('button'); clear.textContent = 'Clear';
  clear.title = 'Remove every effect from this bar snapshot';
  clear.setAttribute('aria-label', clear.title);
  clear.onclick = () => { chain = []; draw(); };
  const closeButton = document.createElement('button'); closeButton.textContent = 'Close';
  closeButton.title = 'Close without applying these staged bar-effect changes';
  closeButton.setAttribute('aria-label', closeButton.title);
  closeButton.onclick = closeMenu;
  const applyPlay = document.createElement('button'); applyPlay.className = 'regapply barfxplay';
  applyPlay.textContent = 'Apply + Play';
  applyPlay.title = `Save these effects and play ${targetLabel(key)} from bar ${from + 1}`;
  applyPlay.setAttribute('aria-label', applyPlay.title);
  applyPlay.onclick = () => {
    const ok = applyArrangementEdit(setBarEffects(arrDraftOf(), from, to, key, chain), '');
    if (!ok) return;
    selectLane(key);
    markBar(key, from, to);
    jumpTo(from * 16, { start: true, immediate: true });
    toast(`Playing ${targetLabel(key)} from bar ${from + 1} with ${chain.length || 'no'} bar effects — ⌘Z to undo`);
  };
  const guide = document.createElement('div'); guide.className = 'barfxguide';
  guide.innerHTML = '<span><strong>Per-bar insert</strong> replaces the channel inserts only while these bars play.</span>'
    + '<span><strong>Apply + Play</strong> saves the snapshot, starts here, and keeps this window open.</span>'
    + '<span><strong>Snapshot Inserts</strong> replaces these cards with a copy of the channel chain.</span>'
    + '<span><strong>Power / arrows</strong> bypass and reorder the staged chain.</span>'
    + '<span><strong>Close</strong> discards staged changes.</span>'
    + '<span><strong>Effect tails</strong> may continue after the selected bars.</span>';
  foot.append(snapshot, clear, closeButton, applyPlay);
  panel.append(guide, foot);
  panel.style.left = `${x}px`; panel.style.top = `${y}px`; panel.classList.add('show');
  const rect = panel.getBoundingClientRect();
  panel.style.left = `${Math.max(6, Math.min(x, innerWidth - rect.width - 6))}px`;
  panel.style.top = `${Math.max(6, Math.min(y, innerHeight - rect.height - 6))}px`;
}

/**
 * Where a window about a lane opens from: the track's NAME in the arrangement.
 *
 * A track is one thing with two faces on this desk, and only one of them is where the
 * work is. The arrangement row is up top, it is what you point at to choose a preset,
 * and it is beside the empty half of the screen a preset window needs. The channel
 * strip is at the bottom of the desk, is about a hundred pixels wide, and anchoring a
 * window to it puts that window in the bottom of the screen every time — under the
 * pointer that asked for it in the arrangement, and nowhere near enough room.
 *
 * So: the row's name area first, the strip only where the arrangement cannot answer —
 * folded away, or a lane it does not draw. Measured rather than merely found, because
 * a folded arrangement leaves its rows in the document at no size at all, and a
 * zero-height anchor puts the window in the top-left corner.
 */
function laneAnchor(laneKey) {
  const id = CSS.escape(laneKey);
  const shown = (el) => (el && el.getBoundingClientRect().height > 0 ? el : null);
  return shown(document.querySelector(`#arrgrid .arrrow[data-lane="${id}"] .arrtrack-top`))
    || shown(document.querySelector(`#arrgrid .arrrow[data-lane="${id}"]`))
    || shown(document.querySelector(`.strip[data-lane="${id}"] .strippreset`))
    || shown(document.querySelector(`.strip[data-lane="${id}"] .striphead`))
    || shown(document.querySelector(`.strip[data-lane="${id}"]`));
}

/**
 * Open the preset picker on a lane, from a menu rather than from the name itself.
 *
 * WHERE IT LANDS IS WHERE YOU CLICKED, when there is a click to go on — `at` is the
 * pointer that opened the menu the item was chosen from, and the picker drops from it
 * exactly as it drops from the strip's own name. That is the same rule the preset EDITOR
 * follows; the two are one gesture split in half — which sound, then what that sound
 * does — and they should not answer from two different corners of the desk.
 *
 * The "this new track has no sound yet" prompts have no pointer behind them: a track
 * arrives by paste, by import or by a toast, and there is nothing to hang the picker off.
 * Those fall back to the track's own name — see `laneAnchor` — which is the thing the
 * offer is about.
 */
function openVoicePickerFor(laneKey, at = null) {
  selectLane(laneKey);
  if (at && at.x != null && at.y != null) { openVoicePicker(at.x, at.y, laneKey); return; }
  const r = laneAnchor(laneKey)?.getBoundingClientRect();
  openVoicePicker(r ? r.left : innerWidth / 2, r ? r.bottom + 6 : 120, laneKey);
}

/**
 * The preset editor — see tools/mixer-voice-editor.js.
 *
 * Handed the desk's own pot so a preset's ATTACK behaves like every other rotary on
 * the desk, and a `refresh` so an edit is audible on the lane while it is made. It
 * mutates the catalogue entry in place, which is what makes that work: `VOICES[id]`
 * is the object `playVoice` reads at schedule time, so a re-bank is the whole of the
 * plumbing between a slider and the sound.
 */
// Held, not looked up. The panel is a rack item that gets detached whenever it is
// closed or the rack repaints, and `getElementById` does not find a detached element —
// so a lookup would come back null the first time `buildRack` ran, and stay null.
const voiceEditEl = $('voiceedit');

const voiceEditor = createVoiceEditor({
  el: voiceEditEl,
  knob,
  toast,
  // The full-window editor, built the first time EDIT is pressed and never otherwise.
  // Its two elements are held for the same reason `voiceEditEl` is: they live outside the
  // rack, so a rack repaint never touches them.
  createFull: ({ kit }) => createSynthFull({
    kit, el: $('synthfull'), backdrop: $('synthfullback'),
    // FIVE octaves, C2 up. Seven fit the board, but the board is no longer the width of
    // the window — the cards below it are as wide as they need to be and no wider, and a
    // keyboard that kept spanning the screen under them was the widest thing on a panel
    // that had just been narrowed. Five octaves is the range a preset is auditioned over,
    // and the octave shift reaches the rest.
    keyboard: { octaves: 5, initialOctave: 2 },
  }),
  // Not `rebank`. A re-bank restarts the sequencer with a deliberate half-second gap,
  // which on a slider drag is half a second of silence per pixel — see
  // `VoiceRack.refresh`. Dropping the synths built from the old options is the whole
  // of what an edit needs, and the next note is already the new sound.
  refresh: (id) => Audio.refreshVoice(id),
  liveCompensation: () => !!Audio.mixer && !Audio.mixer.limiterOn,
  // Layer solo lives on the engine, not on the panel: the panel forgets everything when
  // it closes, and a solo that outlived it would be a stack playing with a layer missing
  // and nothing on screen to explain why. A null id clears the lot — see setLayerSolo.
  setLayerSolo: (id, key, on) => {
    if (!id) Audio.clearLayerSolo();
    else Audio.setLayerSolo(id, key, on);
  },
  // A filter/VCA bypass changes the native graph, not just a parameter. Clear only
  // audition notes already queued on the bench so the next hit is the unmistakable
  // bypassed sound; the song's own playback continues through its normal scheduler.
  onSectionChange: () => {
    releaseHeldPreviews();
    Audio.stopPreview?.();
  },
  // For measuring a preset here in the page: the engine's SEEDED noise buffer, so a
  // noise preset is measured on the same bytes it will be played on, and the desk's
  // own sample rate, so the reference and the comparison are taken the same way.
  // Both read late — the buffer is built when audio starts, well after this runs.
  noiseBuf: () => Audio.noiseBuf,
  sampleRate: () => Audio.ctx?.sampleRate || 44100,
  // A preset's name and category are what the picker and every strip label show, so
  // an edit to either has to reach the rack — and its level reaches the rack too,
  // through `voiceGain`, once a save has measured it. The user collection is filed BY those
  // two, so a rename moves a row and a refile moves it to another column: it has to
  // repaint or it goes on showing the preset under the name it no longer has.
  onChanged: () => { buildRack(); voiceLibrary.refresh(); },
  onBlank: () => voiceLibrary.clearPick(),
  ask,
  listPresets: ({ engine, laneKey, keep }) => offeredByEngine(engine, { laneKey, keep }),
  selectPreset: (id, { laneKey }) => {
    if (laneKey) setLaneVoice(laneKey, id);
    else if (voiceEditor.open(id, { isNew: true })) voiceEditor.openFull();
  },
  auditionNote: (midi, opts) => oskPlay(midi, { ...opts, record: false }),
  releaseAudition: ({ src }) => oskRelease(src),
  panicAudition: () => releaseHeldPreviews(),
  midiState: () => synthMidiAdapter.state(),
  toggleMidi: (on) => setMidi(on),
  midiAdapter: synthMidiAdapter,
  isDevUser: () => DEV_USER,
  // No server on the deployed desk, so no library to file a preset into. See the
  // `if (STATIC)` block below, which is the same rule applied to every other control
  // that would post somewhere.
  canFile: () => !STATIC,
  // A never-saved preset takes its id from its name at the moment it is saved, so the
  // lane holding the old id has to be repointed at the new one — see `commit`.
  assign: (laneKey, id) => { if (laneKey) setLaneVoice(laneKey, id, { redraw: false, autoCopy: false }); },
  // Where an edit lands when the preset is the song's own — see writeSongVoice.
  onEdit: writeSongVoice,
  saveToSong: saveVoiceToSong,
  // Hold named songs on the sound they have now, so updating the preset leaves them
  // alone. See pinPresetInSongs — it writes songs the desk is not on, which is the one
  // place anything here does.
  onDirty: markVoiceDirty,
  // Detached, not just hidden, so a closed editor is off the document entirely.
  //
  // Docked in the preset library it FOLDS instead. There the ✕ is on a panel you are
  // living in rather than one you opened for a moment, and tearing it down would lose
  // which preset it was on — so the same button means "put this away" and the panel
  // comes back exactly as it was. See setCollapsed.
  //
  // The rack repaint is still owed: a strip's heading is the preset's name, and closing
  // is the moment a rename or a category change that has not repainted yet gets one.
  close: () => {
    if (voiceLibrary.slots && !voiceEditor.laneKey) { voiceLibrary.collapse('edit', true); return; }
    dismissVoiceEditor();
    buildRack();
  },
});

/**
 * ⎋ closes the full-window editor — and this listener HAS TO BE REGISTERED HERE.
 *
 * `stopImmediatePropagation` only stops listeners added AFTER it on the same target, and
 * the PANIC handler is on `window` too, eight thousand lines further down. Registered
 * after it, this would close the editor and silence every voice on the same keypress —
 * a failure you hear rather than see, which is the worst kind to leave to chance. There
 * is an assertion on that source ordering in tests/mixer-layout.js.
 *
 * Nothing needs to be done about `ask()`: its own Escape listener is capture-phase, so a
 * confirm dialog over this window already wins whatever order they went on in.
 */
addEventListener('keydown', (ev) => {
  if (ev.key !== 'Escape' || !voiceEditor.fullOpen) return;
  ev.preventDefault();
  ev.stopImmediatePropagation();
  voiceEditor.closeFull();
});

/** Take the panel down, without asking for the rack repaint that `close` does. */
function dismissVoiceEditor() {
  voiceEditEl.classList.remove('show', 'vefloat');
  voiceEditEl.remove();
  voiceEditor.forget();
}

// ---- the editor as a window -------------------------------------------------
//
// It is ALWAYS a window now — opened from a channel's menu as much as from the preset
// library. It used to be a rack item beside the strip that opened it, and that is the
// thing the strip has given up: see `stripMenu`, and `placeVoiceEditor` for what
// replaced the pair.

const VE_POS_KEY = 'mash-mixer-voiceedit-pos';

/** Put the floating editor somewhere on the screen, and remember where. */
function placeFloatingEditor(x, y) {
  const el = voiceEditEl;
  if (x == null) {
    let pos = null;
    try { pos = JSON.parse(localStorage.getItem(VE_POS_KEY) || 'null'); } catch { pos = null; }
    const r = el.getBoundingClientRect();
    // First open: to the right of the library window, which opens centred — so the two
    // are side by side rather than the editor landing on top of the list it came from.
    x = pos?.x ?? Math.max(4, innerWidth - r.width - 40);
    y = pos?.y ?? 120;
  }
  const { left, top } = clampFloatingEditor(x, y);
  localStorage.setItem(VE_POS_KEY, JSON.stringify({ x: left, y: top }));
}

/**
 * Put the window at x/y, pulled back on screen — and remember NOTHING.
 *
 * The split from `placeFloatingEditor` is which positions count as a choice. Dragging
 * the header is a choice and is remembered; being re-placed by a repaint, or centred on
 * open, is the desk moving its own furniture, and writing either of those to `VE_POS_KEY`
 * would quietly overwrite where the user last put it.
 */
function clampFloatingEditor(x, y) {
  const el = voiceEditEl;
  const r = el.getBoundingClientRect();
  const left = clamp(x, 4, Math.max(4, innerWidth - r.width - 4));
  const top = clamp(y, 4, Math.max(4, innerHeight - r.height - 4));
  el.style.left = `${left}px`;
  el.style.top = `${top}px`;
  return { left, top };
}

/**
 * Open the window where the click that asked for it was.
 *
 * It used to be hung off an ELEMENT — the channel strip, and then the arrangement row —
 * and neither reads as "here": the strip is a hundred-pixel column at the bottom of the
 * desk, the row's name is at the far left, and a window placed against either one lands
 * a long way from the hand that asked for it. The pointer is the honest answer, and it is
 * the same answer for every door into the editor: a right-click on a strip puts the panel
 * beside that strip because that is where you clicked, and the track panel's own buttons
 * put it beside the track panel for the same reason.
 *
 * Just off the pointer, flipped to its other side where the window will not fit, and
 * clamped from there — so a strip clicked at the bottom of the screen gets a panel that
 * rides up to fit rather than one hanging off the edge. `x`/`y` missing means nobody
 * clicked: the tour and a restored session both arrive that way, and the middle of the
 * screen is the only honest answer to "where did this come from".
 */
const EDITOR_POINTER_GAP = 12;
function placeEditorAtPointer(at) {
  const r = voiceEditEl.getBoundingClientRect();
  if (!at || at.x == null || at.y == null) {
    clampFloatingEditor((innerWidth - r.width) / 2, (innerHeight - r.height) / 2);
    return;
  }
  const right = at.x + EDITOR_POINTER_GAP;
  const left = right + r.width <= innerWidth ? right : at.x - EDITOR_POINTER_GAP - r.width;
  clampFloatingEditor(left, at.y);
}

// Dragged by its header, like every other window here. Delegated from the panel rather
// than bound to the header, because `build()` replaces the header on every repaint — a
// listener on the header itself would survive exactly until the first slider moved.
voiceEditEl.addEventListener('pointerdown', (ev) => {
  if (!voiceEditEl.classList.contains('vefloat')) return;
  const head = ev.target.closest('.vehead');
  if (!head || ev.target.closest('button, input, select, textarea')) return;
  ev.preventDefault();
  const r = voiceEditEl.getBoundingClientRect();
  const dx = ev.clientX - r.left;
  const dy = ev.clientY - r.top;
  const move = (e) => placeFloatingEditor(e.clientX - dx, e.clientY - dy);
  const stop = () => { head.removeEventListener('pointermove', move); head.classList.remove('dragging'); };
  head.classList.add('dragging');
  try { head.setPointerCapture(ev.pointerId); } catch { /* not a real pointer */ }
  head.addEventListener('pointermove', move);
  head.addEventListener('pointerup', stop, { once: true });
  head.addEventListener('pointercancel', stop, { once: true });
});

/**
 * Keep the editor pointed at whatever its lane is actually playing.
 *
 * The panel edits ONE preset, beside ONE strip, drawn as a single object with it — so
 * the moment the lane is put on something else, every control on it is aimed at a
 * sound nothing on screen is making. It follows the lane instead: onto the new preset
 * where there is one to open, and off the desk entirely where there is not — the
 * engine's own voice has no entry behind it at all, and an engine preset is a bundle
 * of bank keys the hand-written lane reads rather than a synth, which is why `open`
 * refuses one.
 *
 * Following RE-OPENS rather than re-labels. `open` takes the sound it finds as the
 * baseline, and the baseline belongs to the preset you have arrived at, not the one
 * you left — otherwise Revert on the new preset would put back the old one's shape.
 * Edits made to the preset you left are still on it: the editor mutates the catalogue
 * entry in place, so stepping back onto it finds them.
 *
 * Returns true only when the panel CLOSED, because that is the case the caller has to
 * repaint for: the panel and its strip share a wrapper and the wrapper has to go.
 * Following needs no repaint — `build` refills the panel where it already sits, which
 * is what keeps the ‹ › audition loop from losing the hover under the pointer.
 */
function syncVoiceEditorToLane(laneKey, { autoCopy = true } = {}) {
  // Standalone Advanced deliberately hides the compact panel behind it. That does not
  // mean the editor has let go of the lane: the full window still reads and writes the
  // same state.voice, and a preset chosen in its own title bar must move that state onto
  // the lane's new song-local copy. Treating only the compact panel's `show` class as
  // ownership changed the lane but left Advanced editing the detached previous object.
  if ((!voiceEditor.isOpen() && !voiceEditor.fullOpen)
      || !laneKey || voiceEditor.laneKey !== laneKey) return false;
  let chosen = laneVoiceId(laneKey);
  let preset = chosen && VOICES[chosen];
  if (!preset || preset.kind === 'engine') { dismissVoiceEditor(); return true; }
  // Auto-copy a library preset into the song so the editor never mutates the shared
  // catalogue through a lane strip. A normal lane choice always copies; the explicit
  // `autoCopy: false` exception is only safe when the lane already points at the editor's
  // current PRESET (the Save-as-New handoff, where the panel is already holding the very
  // object the lane was just put on). If the choice changed, copy it even in that mode,
  // otherwise opening can be refused by the library guard and leave the old Quick surface
  // attached to the new, detailed synth.
  const choiceChanged = chosen !== voiceEditor.editing || preset !== voiceEditor.voice;
  if (!preset.songLocal && (autoCopy || choiceChanged)) {
    const seam = seamFor(laneKey);
    if (seam) {
      editMix((m) => {
        m.voiceParams = { ...(m.voiceParams || {}), [seam.voiceKey]: JSON.parse(JSON.stringify(preset)) };
      });
      rebank();
      applyToEngine(mixFor(trackId));
      chosen = laneVoiceId(laneKey);
      preset = VOICES[chosen];
    }
  }
  // Still on it only if the panel is holding the very OBJECT the lane plays.
  //
  // THE BUG THIS PINS: a song-local copy is keyed by lane and song — `bassVoice@neon` —
  // so the id does not move when you put the lane on a different preset. The copy of the
  // new choice is registered under that same id, as a NEW object, and an id comparison
  // read that as "already on it" and returned before the re-open. The panel went on
  // drawing the object it was handed when it opened: pick MRDR-3 while the strip's editor
  // was on a DuoSynth and you got DuoSynth's Note/detailed cards over an MRDR-3 lane, no
  // Quick macros and no ADVANCED — and the same in reverse, MRDR-3's Quick surface over a
  // DuoSynth. Both surfaces are resolved from `state.voice` at build time and were
  // correct; nothing ever rebuilt. See the `voice` getter on the editor.
  if (chosen === voiceEditor.editing && preset === voiceEditor.voice) return false;
  // A REFUSED open is the state this whole function exists to prevent.
  //
  // `open` turns a preset away for reasons that have nothing to do with the lane — a
  // library sound the copy above could not make song-local because the lane has no seam
  // to hold one, an entry that has gone from the catalogue between the choice and here.
  // Refused, the panel would keep drawing the preset you LEFT: MRDR-3's Quick macros on
  // a strip now playing a GameSynth, an ADVANCED button onto a window with no layout
  // behind it, and every pot aimed at a sound nothing is making. There is no surface to
  // fall back to in that case, so the editor comes off the desk instead — and `forget`
  // takes the full window with it. The caller repaints, which is what the `true` says.
  if (!voiceEditor.open(chosen, { laneKey, laneLabel: targetLabel(laneKey) })) {
    dismissVoiceEditor();
    return true;
  }
  return false;
}

/**
 * Keep the editor on screen, wherever the desk repaints around it.
 *
 * IT IS A WINDOW, NOT A RACK ITEM. It used to be one: the panel was inserted into the
 * rack beside the strip that opened it, the two wrapped in a `.voicepair` that took the
 * border and drew one shared header over both halves, so an edited channel simply got
 * wider. That is gone with the strip's » — a channel is about a hundred pixels wide and
 * the editor is three of them, so opening one shoved the rest of the rack sideways, tied
 * the panel's height to whatever rung the shrink ladder was standing on, and put the
 * controls at the bottom of the screen because that is where the rack is. Centred, it is
 * in the same place every time and the rack does not move at all.
 *
 * What survives from the rack-item days is why the ELEMENT is held in a variable rather
 * than rebuilt: `buildRack` used to detach it on every repaint, and keeping the node
 * meant keeping its inputs and their focus. It is parked on the body now, so a repaint
 * cannot touch it — but a save or a rename still calls through here, and re-placing
 * rather than rebuilding is still what keeps the caret in the name field.
 *
 * A lane that has gone — deleted, or filtered out of the view — leaves the editor
 * describing a channel that is not there, so it closes.
 */
function placeVoiceEditor() {
  const el = voiceEditEl;
  const laneKey = voiceEditor.laneKey;
  if (!voiceEditor.isOpen()) { el.remove(); return; }
  // Inside the library, if it is open: that window has a slot down its right side and
  // the three panels are one workspace. Only ever a lane-free editor — the library is
  // where you browse the catalogue, and a channel's preset is a song's own copy.
  if (!laneKey && voiceLibrary.slots) { dockIntoLibrary(); return; }
  // Not `close()`: this runs FROM buildRack, and close rebuilds the rack. Tearing the
  // panel down without asking for another repaint is the whole difference between
  // closing an editor and re-entering the function that is already running.
  if (laneKey && !document.querySelector(`.strip[data-lane="${CSS.escape(laneKey)}"]`)) {
    dismissVoiceEditor();
    return;
  }
  if (el.parentElement !== document.body) document.body.append(el);
  el.classList.remove('vedocked');
  el.classList.add('vefloat');
  // Where it already is, clamped back on screen — not re-placed. This runs on every
  // repaint, and a window that jumped back to the last pointer position each time a fader
  // moved would be unusable. `placeEditorAtPointer` is called once, by whatever opened it.
  const r = el.getBoundingClientRect();
  if (laneKey) clampFloatingEditor(r.left, r.top); else placeFloatingEditor();
}

/**
 * Open the editor on a lane's chosen preset.
 *
 * It used to take an `isNew` option, for a menu item that opened the editor already
 * forked onto a copy. The editor has its own **Save as new**, which is the same gesture
 * at the moment you want it — after you have moved something and decided to keep it —
 * so the option had no caller left and is gone rather than left as a branch nothing
 * takes. The editor's own `state.isNew` is unaffected: that is what its Save as new sets.
 *
 * WHICH SURFACE IT LANDS ON. Three preset families have both — KLNG8, MRDR-3 and TNGR-2 — and
 * `advanced` says which one was asked for:
 *
 *   undefined  the caller has no opinion, so the preset decides: a drum goes to the full
 *              window, because its Quick surface is eight pots of a kit that has
 *              hundreds, and everything else gets the small panel. The tour is the last
 *              caller that asks this way.
 *   true       the full window, standalone — nothing behind it.
 *   false      the small Quick panel, on a drum as much as on anything else.
 *
 * The track panel and the channel menu pass it explicitly on both of their items, so
 * **Edit Preset** and **Edit Advanced** each do exactly what they are called. A preset
 * with only one surface ignores it; there is nothing else to open.
 *
 * Either way the window opens at the POINTER — `at` is the click that asked for it, and
 * `placeEditorAtPointer` is where it lands.
 */
function editVoice(laneKey, { advanced, at = null } = {}) {
  let chosen = laneVoiceId(laneKey);
  // A GENERATED SONG NAMES ITS INSTRUMENTS IN THE BANK, NOT IN THE MIX.
  //
  // `bassVoice: 'stRoundMono'` is written into the composition by the style pack — see
  // `resolveDefault` — so the desk reads it back for the strip's heading and the picker
  // shows it as what the lane is on, but `laneVoiceId` has nothing to return: the mix
  // names no preset and holds no copy. That made every lane of every new song answer
  // the pen with "this lane is on the engine's own voice", which is both wrong and a
  // dead end — the sound has a name on the strip, and there was no way to edit it short
  // of picking some other preset first.
  //
  // The bank's own name is the answer, and the fork below turns it into the song's copy
  // exactly as it does for one chosen from the picker. That is also what makes a FROZEN
  // STARTER editable: it is immutable in the catalogue on purpose, and a song-local copy
  // is not the catalogue — `registerSongVoice` clears the flag, and Save can only ever
  // put it in the library under a new name.
  const named = chosen ? null : defaultVoiceOf(track?.bank, laneKey);
  // An ENGINE preset is the exception this message was written for, and stays it: it is
  // a bundle of the bank keys the hand-written voice reads rather than a synth, so there
  // is nothing for the editor to draw. See `open` in the editor, which refuses one too.
  const source = chosen ? VOICES[chosen] : (named?.kind === 'engine' ? null : named);
  // Only when the lane names nothing at all. A mix pointed at an id the catalogue no
  // longer holds is a different failure, and `open` has the words for it.
  if (!chosen && !source) {
    // Nothing to copy and nothing to edit. The engine's own voice is not a preset —
    // it is what plays when no preset is named — so there is no entry behind it.
    toast('This lane is on the engine’s own voice. Choose a preset first, then edit it'
      + ' — or copy one into a new preset.');
    return;
  }
  // Opening the editor from a lane always works on a song-local copy. The library
  // preset is never mutated through a channel strip — edit it from the library
  // browser if you mean to change it for every song.
  if (source && !source.songLocal && source.kind !== 'engine') {
    const seam = seamFor(laneKey);
    if (seam) {
      editMix((m) => {
        m.voiceParams = { ...(m.voiceParams || {}), [seam.voiceKey]: JSON.parse(JSON.stringify(source)) };
      });
      rebank();
      applyToEngine(mixFor(trackId));
      chosen = laneVoiceId(laneKey);  // now returns the song-local id
    }
  }
  // The fork is the only way a bank-named preset becomes something the editor can open,
  // so a lane with no seam to hold the copy has to say so rather than open on nothing.
  if (!chosen) {
    toast(`${source?.label ?? 'That sound'} is named by the song itself, and this lane has`
      + ' nowhere to keep its own copy — so there is nothing here to edit.');
    return;
  }
  closeMenu();
  selectLane(laneKey);
  // Whether there is a second surface to ask for at all. Both windowed branches below
  // are gated on it, so `advanced: true` on a preset that has only the one panel opens
  // that panel rather than nothing.
  const hasAdvanced = isQuickVoice(VOICES[chosen]);
  const strip = document.querySelector(`.strip[data-lane="${CSS.escape(laneKey)}"]`);
  // BOTH WINDOWS OPEN AT THE POINTER, not against an element. `at` is where the click
  // that asked for them was — see `placeEditorAtPointer`, and the `at` branch of the full
  // window's own `open`. Every caller that has a pointer hands it over; the ones that do
  // not (the tour, a restored session) get the middle of the screen.
  //
  // Already open on this very preset: leave it where it is and stop. Re-opening would
  // call `open` again, which takes the CURRENT sound as the baseline — so a second ask
  // for the editor would quietly make your unsaved edits the thing Revert goes back to.
  if (voiceEditor.isOpen() && voiceEditor.laneKey === laneKey
      && voiceEditor.editing === chosen) {
    // Except when the full window is what was asked for and it is not up yet — then the
    // panel already being open is no reason to refuse. Not `standalone`: there IS a
    // panel behind this one, it was there first, and closing the window should reveal it
    // rather than put the preset down.
    if (advanced && hasAdvanced && !voiceEditor.fullOpen) {
      voiceEditor.openFull(1, { at, avoidTransport: true });
      return;
    }
    return;
  }
  if (!voiceEditor.open(chosen, { laneKey, laneLabel: targetLabel(laneKey) })) return;
  const fullEngine = VOICES[chosen]?.kind === 'drum' ? 'drum' : VOICES[chosen]?.synth;
  // Straight to the full window with nothing docked behind it. `standalone` is what
  // says so: closing the window puts the preset down, rather than uncovering a panel
  // the user never asked to open. A drum takes this route on its own — see the note on
  // `advanced` above — and `advanced: false` is the one thing that overrules it.
  if (strip && ((fullEngine === 'drum' && advanced !== false) || (advanced && hasAdvanced))) {
    voiceEditEl.classList.remove('show');
    voiceEditor.openFull(1, { standalone: true, at, avoidTransport: true });
    return;
  }
  placeVoiceEditor();
  placeEditorAtPointer(at);
}

// ---- the preset library -----------------------------------------------------
//
// The catalogue with no song in front of it. See tools/mixer-voice-library.js — the
// window, the patterns, and the bench a preset with no channel is heard on.

const voiceLibrary = createVoiceLibrary({
  el: $('voicelib'),
  Audio,
  // Read late and through a closure, for two reasons: the pattern follows the desk
  // tempo including while you drag it, which is how you hear what a release really
  // does — and `deskTempo` is declared several thousand lines below this, so naming it
  // directly here would be reading a `const` before it exists.
  bpm: () => deskTempo(),
  /**
   * The song's clock, for the pattern to lock onto — null when nothing is playing.
   *
   * Read straight off the sequencer rather than derived from the tempo readout. `spb`
   * carries the warp multiplier, which the readout does not, and `nextTime`/`step` are
   * the actual grid the song's own notes are being placed on — so a figure started
   * against them is on the beat because it is on the same beat, not because two clocks
   * were set to the same number and have not drifted yet.
   */
  sync: () => {
    if (!playing || !Audio.ctx || !Audio.bpm) return null;
    return {
      time: Audio.nextTime,
      step: Audio.step,
      spb: (60 / (Audio.bpm * (Audio.tempo || 1))) / 4,
    };
  },
  edit: editLibraryVoice,
  file: () => voiceEditor.saveSheet(),
  editing: () => voiceEditor.editing,
  // The keyboard plays whatever is on the bench while the library is up, so it has to
  // be told the moment that changes — otherwise it goes on naming the last preset.
  scale: () => oskScale(),
  onPick: () => refreshOsk(),
  // The library rebuilt itself, which detached whatever was parked in it. Put them
  // back — same contract `placeVoiceEditor` has with `buildRack`.
  onLayout: () => dockIntoLibrary(),
  onCollapse: onLibraryCollapse,
  // Closing the library hands the keyboard back to the selected channel, and takes the
  // editor with it: an editor left floating over the desk with no library behind it is
  // a window with no way back to the list it came from.
  onClose: () => {
    if (voiceEditor.isOpen() && !voiceEditor.laneKey) dismissVoiceEditor();
    // Put the desk back the way it was found: a keyboard the library switched on goes
    // off with it. One the desk already had stays, and goes back to floating.
    if (!oskWasOn) showOsk(false);
    undockFromLibrary();
    refreshOsk();
  },
});

/**
 * Open the editor on a library preset — no lane, no song, no strip.
 *
 * The one thing this does that `editVoice` does not is leave every song alone: there is
 * no lane to point at the preset and nothing is written to any draft. Re-opening on the
 * preset already showing is refused for the same reason it is on a lane — `open` takes
 * the CURRENT sound as the baseline, so a second click would quietly make your unsaved
 * edits the thing Revert goes back to.
 */
function editLibraryVoice(id) {
  if (voiceEditor.isOpen() && !voiceEditor.laneKey
    && (voiceEditor.editing === id || voiceEditor.librarySource === id)) return voiceEditor.editing;
  // Marked BEFORE it is opened, not after it is placed. `open` builds the panel, and
  // the panel reads this class to decide whether its ✕ is a close or a fold — so
  // setting it on the way past would leave the first build wearing the wrong one.
  voiceEditEl.classList.toggle('vedocked', !!voiceLibrary.slots);
  // Built-in library sounds are reference material. Opening one from the library
  // creates one hidden editor draft; the original remains untouched and no user
  // preset is filed until Save as New.
  const source = VOICES[id];
  const updateLibrary = DEV_USER && !!source?.factory;
  if (!voiceEditor.open(id, {
    isNew: !!source?.factory && !updateLibrary,
    allowLibraryUpdate: updateLibrary,
  })) return false;
  // A re-place is all it takes now: the panel is a window wherever it was opened from,
  // so moving it from a channel to the library is a change of home rather than of kind
  // — nothing has to be rebuilt for it to leave. It used to be a rack item beside its
  // strip, wrapped with it, and floating it out on its own left that wrapper drawing a
  // border round a lone strip, so this asked for a whole rack repaint instead.
  placeVoiceEditor();
  return voiceEditor.editing;
}

/**
 * Park the editor and the keyboard into the library's own slots.
 *
 * The three of them are one job — find a sound, shape it, play it — and they were three
 * windows to open and arrange before any of that could start. So while the library is
 * up it holds the other two: the editor down its right side, the keyboard along the
 * bottom, both in boxes the library laid out for them.
 *
 * MOVED, not copied. `append` relocates a node it already holds, so these are the same
 * elements the desk uses everywhere else — the editor that also docks beside a channel
 * strip, the keyboard that also plays one. A second copy of either would be a second
 * implementation of something that already works, and they would drift.
 *
 * Runs after every library repaint, because a repaint empties the window and detaches
 * whatever was in it. Cheap: two `append` calls on nodes that are usually already
 * where they belong.
 */
function dockIntoLibrary() {
  const slots = voiceLibrary.slots;
  if (!slots) return;
  if (voiceEditor.isOpen() && !voiceEditor.laneKey && !voiceLibrary.isCollapsed('edit')) {
    // Docked, so it gives up the floating window's frame and position — see .vedocked.
    voiceEditEl.classList.add('vedocked');
    voiceEditEl.classList.remove('vefloat');
    slots.edit.append(voiceEditEl);
  }
  if (oskShown() && !voiceLibrary.isCollapsed('keys')) {
    oskEl.classList.add('docked');
    slots.keys.append(oskEl);
    fitDockedKeys();
  }
}

/**
 * How wide the docked keyboard's band actually is, inside its frame.
 *
 * Zero when it is not docked, which is the signal to use the floating board's fixed
 * two octaves: out on the desk it is a corner window with no band to fill.
 */
// The frame around the keys, per side — `#osk .oskkeys`'s own border. It is inside the
// slot, so it is part of what the keys have to fit within.
const OSK_CHASSIS = 5;

function oskRoom() {
  const slot = voiceLibrary.slots?.keys;
  if (!slot || !oskEl.classList.contains('docked')) return 0;
  return Math.max(0, slot.clientWidth - OSK_CHASSIS * 2);
}

/**
 * Redraw the docked keyboard when the band it sits in has changed size.
 *
 * The keys are SIZED, not scaled — see `oskKeyPlan`. So filling a different width is a
 * different number of keys rather than the same keys stretched, and the only thing this
 * has to do is notice the width moved and ask for a rebuild.
 *
 * Guarded on the width it last drew for, because the rebuild re-docks, and re-docking
 * calls this again. Without that it is a loop.
 */
let oskDrawnFor = -1;
function fitDockedKeys() {
  const room = oskRoom();
  if (!room || room === oskDrawnFor) return;
  buildOsk();
}

/**
 * How many keys to draw, and how wide each one is.
 *
 * ONE rule, in both homes: a key is the size the piano's key is, and the RANGE gives. The
 * space is whatever the space is — the band's, docked; the title bar's, floating — and
 * what changes with the key you play in is how far up the keyboard reaches, not how big
 * it is. Pick a pentatonic and you get the same keys, more of them, spanning further.
 *
 * It was the other way round, and both of the ways it was wrong are worth keeping:
 *
 * It first drew a fixed number — four octaves — and `zoom`ed them until they fitted, so
 * the keys changed size with the scale: a pentatonic has seventeen where a chromatic
 * board has twenty-nine, and the same band gave one 64px keys and the other 37px.
 *
 * Fixing the RANGE at three octaves and deriving the width fixed that within a scale and
 * moved it between them. Three octaves of a pentatonic is sixteen keys where a piano has
 * twenty-two, so the same band divided sixteen ways gave a key half again as wide — and a
 * key is a shape, the heights come off the width (see sizeOskKeys), so it came out half
 * again as TALL. The keyboard changed size when you chose a key, which is the same
 * complaint one layer along. Floating it did not even fill: a window is as wide as the
 * widest thing in it, which is the title bar, so the sparse board just left bare frame.
 *
 * So the reference is a CHROMATIC board — `OSK_KEYS`, three octaves of white keys — and
 * every scale gets that key at that size, however many of them the space holds. Docked
 * the piano's key is the band divided by twenty-two; floating it is KEY_W, which is the
 * number the window was built around. Both are the same sentence with a different width
 * in it.
 *
 * `DOCK_KEY_MIN` is a floor, not a target. Three octaves of a chromatic board in a
 * narrow band is a row of slivers, and past that point range is the cheaper thing to
 * give up — but only past it.
 *
 * The width is fractional on purpose. Rounding it down leaves up to a key's worth of
 * bare band on the right; keys are positioned at `i * width`, so every key's left edge
 * is the previous key's right edge exactly, and the only cost of a fraction is which
 * device pixel the shared edge lands on.
 */
const DOCK_KEY_MIN = 26;                 // narrowest a docked white key may get, px
// The floating window's inside width, as last measured — see fillFloatingKeys. Zero until
// the keyboard has been in the document once, which is the one draw that cannot know it.
let oskFloatRoom = 0;
function oskKeyPlan(perOctave) {
  const room = oskRoom();
  // ---- floating: the width is the title bar's, and the key is KEY_W.
  //
  // Rounding rather than flooring the fit is what closes the last few pixels: the count
  // that fits best, and then the exact width for it, which is never more than half a key
  // from KEY_W — a key you would have to measure to tell from the piano's.
  if (!room) {
    const fit = oskFloatRoom ? Math.round(oskFloatRoom / KEY_W) : 0;
    // Nothing measured yet, or a title bar shorter than the keys: then the keys are the
    // widest thing in the window and it is they that set its width.
    if (fit <= OSK_KEYS) return { count: OSK_KEYS, width: KEY_W, fills: false };
    return { count: fit, width: oskFloatRoom / fit, fills: false };
  }
  // ---- docked: the width is the band's, and the key is the band divided by a piano.
  //
  // Which makes the count a piano's count as well — the same arithmetic backwards — so it
  // is stated rather than derived. The range is what moves: twenty-two pentatonic keys is
  // four octaves and a bit where twenty-two white ones is three.
  const wide = room / OSK_KEYS;
  if (wide >= DOCK_KEY_MIN) return { count: OSK_KEYS, width: wide, fills: true };
  // Too narrow for a playable key at that count, so the count is what a playable key
  // leaves — but never fewer than an octave and a note, because a keyboard that cannot
  // reach its own octave is not one.
  const count = Math.max(perOctave + 1, Math.floor(room / DOCK_KEY_MIN));
  return { count, width: room / count, fills: true };
}

/**
 * A region of the library folded or unfolded.
 *
 * Folding the keyboard has to reach further than hiding it: while `Keyboard` is on it
 * owns the letter keys, and a keyboard you have put away that is still swallowing M, S
 * and R is a desk whose shortcuts have stopped working for no visible reason.
 */
function onLibraryCollapse(which, isCollapsed) {
  if (which === 'keys') {
    if (isCollapsed) {
      releaseOskSources('k:');
      clearOskHeldVisuals();
      oskCatch = false; oskHeld.clear(); oskEl.remove();
    }
    else if (oskShown()) buildOsk();
  }
  if (which === 'edit' && isCollapsed) voiceEditEl.remove();
  dockIntoLibrary();
}

/**
 * Give them back to the desk. The library is going away and they are not its.
 *
 * The keyboard survives — it plays channels too, and closing the library is not a
 * reason to stop playing — so it goes back to the body as a floating window at the
 * position it last had. The editor does not: opened from the library it is editing a
 * preset with no channel behind it, and a panel floating over the desk with no list to
 * go back to is a window with no way out.
 */
function undockFromLibrary() {
  const osk = oskEl;
  osk.classList.remove('docked');
  if (oskShown()) {
    document.body.append(osk);
    let pos = null;
    try { pos = JSON.parse(localStorage.getItem(OSK_POS_KEY) || 'null'); } catch { pos = null; }
    const r = osk.getBoundingClientRect();
    oskPlace(pos?.x ?? innerWidth - r.width - 24, pos?.y ?? innerHeight - r.height - 54);
    buildOsk();          // back to the selected channel's keys — see oskBench
  } else {
    document.body.append(osk);
  }
  voiceEditEl.classList.remove('vedocked');
}

// The keyboard comes with it. Playing a preset is most of what the library is FOR, and
// making you find a button in the main toolbar first is a step between opening a
// workspace and being able to use it. Whether it was on before is remembered, so
// closing the library puts the desk back the way it was rather than leaving a keyboard
// floating over it that you never asked for.
let oskWasOn = false;
function openPresetLibrary() {
  closeMenu();
  // The library and its docked editor are one of the desk's big synchronous builds,
  // and the sequencer runs on the thread it blocks — so it goes through `heavyUi`,
  // which queues audio past the stall and records what the stall was for.
  heavyUi('open preset library', () => {
    oskWasOn = oskShown();
    voiceLibrary.show(true);
    // The editor is part of the library workspace, even before a row has been picked.
    // A previously folded editor is a remembered desk preference, not a reason for a
    // fresh library opening to have no editor at all.
    if (voiceLibrary.isCollapsed('edit')) voiceLibrary.collapse('edit', false);
    if (!voiceLibrary.isCollapsed('edit')) {
      if (voiceEditor.isOpen() && voiceEditor.laneKey) dismissVoiceEditor();
      voiceEditEl.classList.add('vedocked');
      if (!voiceEditor.isOpen()) voiceEditor.blank();
      dockIntoLibrary();
    }
    if (!oskWasOn) showOsk(true);
  });
}
$('voicelibbtn').onclick = openPresetLibrary;
$('presetbtn').onclick = openPresetLibrary;

// ---- full screen visualiser -------------------------------------------------
// The jukebox visuals, run against the desk's own playback. The song is already
// going through Audio's song lane, and the analyser that feeds these presets is
// tapped off it — so this needs no audio work at all, only a canvas and the
// engine's own analysis object.
//
// What it DOES need is for the desk to stop drawing. A preset painting the whole
// window at native density is real fill rate, and it is being asked for on a
// machine whose one job is not to drop the song. The desk's own frame is a
// picture of audio nobody can see while this is up, so tick() returns early the
// same way it already does when the window loses focus — transport work above
// that line still runs, so loops arm and seeks land while the visual is playing.
let visPreset = null;
let visFrame = 0;
let visAt = 0;
let visIdleTimer = 0;
let visIndex = 0;
let visualiserOpen = false;
// The tunable half-pipe. It is not a member of the pack — it is the same preset
// with its constants brought out where they can be turned, so it sits after the
// list rather than inside it, the way every dev-only section in this project
// sorts after the production ones. Its settings live for the session only: they
// are a way to play with the picture, not a property of the song.
const VIS_LAB = 'HALF-PIPE HORIZON — LAB';
let visLabTune = HALF_PIPE_DEFAULTS();

/** Backing store at the window's size, capped: this is fill rate, not detail. */
function sizeVisualiser() {
  const canvas = $('viscanvas');
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.max(1, Math.round(innerWidth * dpr));
  canvas.height = Math.max(1, Math.round(innerHeight * dpr));
}

function visualiserFrame() {
  if (!visualiserOpen) return;
  visFrame = requestAnimationFrame(visualiserFrame);
  const canvas = $('viscanvas');
  const ctx = canvas.getContext('2d');
  if (!ctx || !visPreset) return;
  const now = performance.now();
  const dt = visAt ? Math.min(0.25, (now - visAt) / 1000) : 1 / 60;
  visAt = now;
  visPreset.update(dt, Audio.musicAnalysis());
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // Cover, not stretch. The presets are composed in a fixed 480x270 space and a
  // non-uniform scale turns every ring in them into an ellipse; cropping the long
  // edge is what the game's own full-screen visual mode does.
  const fit = Math.max(canvas.width / 480, canvas.height / 270);
  ctx.setTransform(fit, 0, 0, fit, (canvas.width - 480 * fit) / 2, (canvas.height - 270 * fit) / 2);
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  visPreset.draw(ctx);
}

/** Show the hint again, with a message, and start it fading out afresh. */
function visHint(text) {
  const panel = $('visualiser');
  $('vishint').textContent = text;
  panel.classList.remove('idle');
  clearTimeout(visIdleTimer);
  visIdleTimer = setTimeout(() => panel.classList.add('idle'), 2600);
}

/**
 * Build a preset and put it up. Seeded off the clock rather than fixed, so
 * arriving at the same preset twice deals a different palette and layout the way
 * the jukebox does rather than replaying one picture.
 */
function startPreset(index) {
  // The lab sits one past the end of the pack, so browsing with the arrows reaches
  // it and wraps past it like anything else.
  const total = VISUALISER_NAMES.length + 1;
  visIndex = ((index % total) + total) % total;
  const track = { bpm: Audio.bank?.bpm || appliedBank?.bpm || 120 };
  const seed = ((Math.random() * 0xffffffff) ^ (visIndex * 0x9e3779b9)) >>> 0;
  const lab = visIndex === VISUALISER_NAMES.length;
  visPreset = lab ? createHalfPipeLab(seed, track, visLabTune) : createVisualiser(visIndex, seed, track);
  // The drawer's picker is the same choice by another route, so it follows along
  // and is already on the right preset when the desk comes back.
  $('vispreset').value = lab ? VIS_LAB : VISUALISER_NAMES[visIndex];
  $('visualiser').classList.toggle('lab', lab);
  if (lab) renderVisKnobs();
}

/** One row of steppers, rebuilt from the preset's own control list. */
function renderVisKnobs() {
  const bar = $('viscontrols');
  if (bar.childElementCount) { syncVisKnobs(); return; }
  for (const control of HALF_PIPE_CONTROLS) {
    const knob = document.createElement('div');
    knob.className = 'visknob';
    knob.dataset.key = control.key;
    knob.innerHTML = '<span>' + control.label + '</span>'
      + '<button type="button" data-step="-1" aria-label="less">−</button>'
      + '<b></b>'
      + '<button type="button" data-step="1" aria-label="more">+</button>';
    bar.appendChild(knob);
  }
  for (const [label, act] of [['RANDOMISE', randomiseVisTune], ['RESET', resetVisTune]]) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'visact';
    button.textContent = label;
    button.onclick = act;
    bar.appendChild(button);
  }
  syncVisKnobs();
}

/** AUTO and OFF are values, not absences — see nextHold() in visualisers.js. */
function visKnobText(control, value) {
  if (control.unit === 'beats') {
    if (value < 0) return 'OFF';
    if (value === 0) return 'AUTO';
    return String(value);
  }
  return Number.isInteger(value) ? String(value) : value.toFixed(1);
}

function syncVisKnobs() {
  for (const knob of $('viscontrols').querySelectorAll('.visknob')) {
    const control = HALF_PIPE_CONTROLS.find((c) => c.key === knob.dataset.key);
    const value = visLabTune[control.key];
    knob.querySelector('b').textContent = visKnobText(control, value);
    knob.querySelector('[data-step="-1"]').disabled = value <= control.min;
    knob.querySelector('[data-step="1"]').disabled = value >= control.max;
  }
}

function setVisTune(next) {
  visLabTune = { ...visLabTune, ...next };
  // Straight onto the running preset. Rebuilding it would restart the ride every
  // time a number moved, which is the opposite of what a knob is for.
  if (visPreset?.applyTune) visPreset.applyTune(next);
  syncVisKnobs();
}

function randomiseVisTune() {
  const next = {};
  for (const control of HALF_PIPE_CONTROLS) {
    const steps = Math.round((control.max - control.min) / control.step);
    next[control.key] = Number((control.min + Math.round(Math.random() * steps) * control.step)
      .toFixed(2));
  }
  setVisTune(next);
  visHint('RANDOMISED');
}

function resetVisTune() {
  setVisTune(HALF_PIPE_DEFAULTS());
  visHint('BACK TO THE SHIPPED SETTINGS');
}

function openVisualiser() {
  if (visualiserOpen) return;
  startPreset(VISUALISER_NAMES.indexOf($('vispreset').value));
  visualiserOpen = true;
  visAt = 0;
  sizeVisualiser();
  const panel = $('visualiser');
  panel.classList.add('show');
  panel.setAttribute('aria-hidden', 'false');
  visHint('← → TO BROWSE · CLICK OR ESC TO RETURN TO THE DESK');
  visFrame = requestAnimationFrame(visualiserFrame);
}

function closeVisualiser() {
  if (!visualiserOpen) return;
  visualiserOpen = false;
  cancelAnimationFrame(visFrame);
  clearTimeout(visIdleTimer);
  visPreset = null;
  const panel = $('visualiser');
  panel.classList.remove('show', 'idle', 'lab');
  panel.setAttribute('aria-hidden', 'true');
  // The desk's frame accumulates meter falloff against a timestamp. Left alone it
  // would come back to a dt of however long the visual was up and snap every meter
  // to the floor in one frame.
  meterAt = 0;
}

for (const name of VISUALISER_NAMES) {
  const option = document.createElement('option');
  option.value = name;
  option.textContent = name;
  $('vispreset').appendChild(option);
}
{
  const lab = document.createElement('option');
  lab.value = VIS_LAB;
  lab.textContent = VIS_LAB;
  $('vispreset').appendChild(lab);
}
$('vispreset').value = 'HALF-PIPE HORIZON';
$('viscontrols').onclick = (ev) => {
  // The bar sits on top of the panel whose own click is the way out.
  ev.stopPropagation();
  const button = ev.target.closest('button[data-step]');
  if (!button) return;
  const control = HALF_PIPE_CONTROLS.find((c) => c.key === button.closest('.visknob').dataset.key);
  const step = Number(button.dataset.step) * control.step;
  const value = Math.min(control.max, Math.max(control.min,
    Number((visLabTune[control.key] + step).toFixed(2))));
  setVisTune({ [control.key]: value });
  visHint(control.label + '  ' + visKnobText(control, value));
};
$('visopen').onclick = () => { closeMenu(); openVisualiser(); };
$('visualiser').onclick = closeVisualiser;
addEventListener('resize', () => { if (visualiserOpen) sizeVisualiser(); });
// Everything the keyboard does while the visual is up, and nothing reaches the
// desk underneath: it is not on screen, and a keystroke aimed at a picture must
// not move a fader. Ahead of the desk's panic handler on the same window, for the
// same reason the drawer's Escape is — leaving is not a reason to cut the sound.
const VIS_STEP = { ArrowLeft: -1, ArrowUp: -1, ArrowRight: 1, ArrowDown: 1 };
addEventListener('keydown', (ev) => {
  if (!visualiserOpen) return;
  ev.preventDefault();
  ev.stopImmediatePropagation();
  const step = VIS_STEP[ev.key];
  if (step) {
    startPreset(visIndex + step);
    visHint(VISUALISER_NAMES[visIndex]);
    return;
  }
  closeVisualiser();
}, true);
$('addtrackbtn').onclick = (ev) => {
  ev.stopPropagation();
  closeMenu();
  addBlankTrack(ev.currentTarget);
};

/**
 * The voice library, as a panel.
 *
 * Sixty-five presets in a context menu is a scrolling list you cannot read, so this
 * is laid out the way the effect catalogue is: a column per category, everything
 * visible at once. Categories are about the SOUND, not the lane — a bass preset on
 * the lead is a lead, and the only entries a lane hides are the few engine ones that
 * are genuinely bass-only code paths.
 *
 * The head row carries the lane, kind/engine filters and search. Existing tracks keep
 * their lane kind fixed; the plus picker is the only route where kind is a choice.
 */
let voicePickerQuery = '';

function openVoicePicker(x, y, laneKey) {
  closeMenu();
  restorablePopup = { kind: 'voicePicker', laneKey };
  const seam = seamFor(laneKey);
  const chosen = mixFor(trackId).voice?.[seam.voiceKey];
  // A preset the library would otherwise leave off the menu is still offered while
  // this lane is the thing playing it — a picker cannot hide the row it is meant to
  // be highlighting. Today that is only the song quotations nothing in the game plays
  // any more, which were pickable before they were filtered; see offeredVoices.
  const offer = { keep: chosen || null };
  const pending = pendingAddTrack?.key === laneKey;
  // A duplicate layer has no engine default to go back to. An independent editor lane
  // is different: it is empty, not copied, and its neutral engine fallback is still a
  // valid starting point while the user chooses a preset.
  const independent = isIndependentLane(laneKey);
  const layer = isLayer(laneKey) && !independent;
  const el = $('voicepicker');
  el.textContent = '';

  const pick = (id) => {
    // A freshly added lane is only a proposal until its first sound is chosen. Commit
    // before closing so closeMenu does not treat this successful choice as a cancel.
    if (pendingAddTrack?.key === laneKey) {
      // The voice the user picked is what the track IS, not whatever lane happened to be
      // selected when they clicked +. A pitched voice re-keys the pending track as a
      // melodic independent lane instead of leaving it a drum; a kit voice re-keys it
      // onto the piece of the kit it actually is, which is what gives it that drum's
      // figures, its place in the row order and its share of a groove — chosen straight
      // from the library, a clap staged as a tom would otherwise stay a tom playing a
      // clap. Only where the two disagree, so nothing moves for no reason.
      //
      // The pitched half cannot happen from the PATTERN EDITOR: there the list holds
      // nothing but the kit. It is the rule rather than the list that has to be true —
      // a pitched voice arriving here would make a row the kit cannot show a note of.
      const voice = VOICES[id];
      const home = voice && isKitVoice(voice) ? kitLaneOf(voice) : 'lead';
      const blocked = home === 'lead' && pendingAddTrack.drumsOnly;
      if (voice && home && home !== pendingAddTrack.from && !blocked) {
        const newKey = nextLayerKey(home);
        pendingAddTrack.key = newKey;
        pendingAddTrack.from = home;
        commitPendingAddTrack(newKey, id);
      } else {
        commitPendingAddTrack(laneKey, id);
      }
      closeMenu();
      return;
    }
    closeMenu();
    setLaneVoice(laneKey, id);
  };
  const entry = (id, label, kind, title) => {
    const btn = document.createElement('button');
    btn.className = (id === chosen || (!id && !chosen)) ? 'on' : '';
    // Named, so the header's readout can scroll to the row it is naming without
    // searching the panel for a label that two presets could share.
    if (id) btn.dataset.voice = id;
    const n = document.createElement('span');
    n.textContent = label;
    const k = document.createElement('span');
    k.className = 'vkind';
    k.textContent = kind;
    btn.title = title;
    btn.append(n, k);
    btn.onclick = () => pick(id);
    return btn;
  };

  const engineOf = (v) => v?.kind === 'drum' ? 'drum' : v?.synth || null;
  const engineLabel = (id) => id === 'drum' ? 'KLNG8' : id;
  const selectedPreset = VOICES[chosen]
    || (independent ? VOICES[defaultAddedVoice(laneKey)] : defaultVoiceOf(track?.bank, laneKey));
  const selectedEngine = engineOf(selectedPreset);

  // The search box. A hundred presets in sixteen columns is quick to scan when you
  // know roughly where you are going and slow when you only know the word — so
  // typing filters the lot, across labels AND the descriptions, which is where words
  // like "808", "gated" or "detune" actually live.
  const search = document.createElement('input');
  search.className = 'voicesearch';
  search.type = 'search';
  search.placeholder = 'Search presets…';
  search.value = voicePickerQuery;
  search.setAttribute('aria-label', 'Search presets');

  // The head row: what you are choosing for, how to find it, and the way back.
  //
  const head = document.createElement('div');
  head.className = 'voicehead';
  const who = document.createElement('span');
  who.className = 'voicewho';
  who.textContent = `${targetLabel(laneKey)} voice`;

  // WHAT THE LANE IS ON NOW, named rather than only highlighted.
  //
  // The chosen row carries `on`, and a highlight answers this only while the row is on
  // screen. It routinely is not: the panel opens filtered to the engine the lane plays,
  // keeps the search from the last time it was opened, and wraps a hundred presets over
  // sixteen columns — so the one preset you most want named is the one scrolled past.
  // And on a generated song, whose lane names its sound in the BANK rather than in the
  // mix, no row is highlighted at all; the sound has a name and the panel never said it.
  //
  // `selectedPreset` above is that name, already worked out for the engine filter: the
  // chosen preset, or the song's own copy, or the bank's default, in that order.
  //
  // A button when the library holds a row for it — clicking is the way BACK to the row,
  // dropping whatever filter is hiding it — and a plain span when it does not, which is
  // a frozen starter on a generated song. There is nothing to scroll to there, and a
  // button that does nothing is worse than a label.
  //
  // The PLUS picker has none of this: a track that does not exist yet is not on
  // anything, and the head already says so in the line under it.
  const nowPreset = pending ? null : selectedPreset;
  const nowInList = !!nowPreset && offeredVoices(laneKey, offer).some((v) => v.id === nowPreset.id);
  const now = pending ? null : document.createElement(nowInList ? 'button' : 'span');
  if (now) {
    now.className = 'voicenow';
    if (nowInList) now.type = 'button';
    const nowName = document.createElement('span');
    nowName.className = 'voicenow-name';
    nowName.textContent = nowPreset?.label || 'the engine’s own voice';
    now.append(nowName);
    if (nowPreset?.category) {
      const nowCat = document.createElement('span');
      nowCat.className = 'voicenow-cat';
      nowCat.textContent = nowPreset.category;
      now.append(nowCat);
    }
    now.title = nowPreset
      ? `This lane is on ${nowPreset.label}`
        + (nowInList ? ' — click to show it in the list below' : '')
      : 'This lane is on the engine’s own voice — no preset is chosen';
  }
  // The row for the current preset, or null while a filter is hiding it.
  const currentRow = () => (nowPreset
    ? results.querySelector(`button[data-voice="${CSS.escape(nowPreset.id)}"]`)
    : null);
  // Put that row back on screen, whatever is hiding it. The filters are only dropped
  // when one of them is the thing in the way, so clicking this while the row is already
  // visible leaves the panel exactly as it was bar the scroll.
  const revealCurrent = () => {
    if (!currentRow()) {
      voicePickerQuery = '';
      search.value = '';
      engine = 'all';
      if (KINDS.some((k) => k.id === 'all')) kind = 'all';
      for (const c of chips.children) c.classList.toggle('on', c.textContent === 'All');
      refreshEngineOptions();
      draw('');
    }
    currentRow()?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  };
  if (now && nowInList) now.onclick = (ev) => { ev.stopPropagation(); revealCurrent(); };

  // Drums or not — the one split the catalogue's categories do not make, and the only
  // one that is about the LANE. A lead strip has no use for seven columns of kit before
  // it reaches the Lead, so the panel opens on the kind the lane plays.
  //
  // On a PERCUSSION lane it is a rule and not a view, and the chips do not appear at all.
  // A drum lane holds booleans: a step says a hit happens and carries no pitch, so a
  // melodic preset there is a synth being struck at whatever note the lane happens to
  // name, over and over. That is not a sound anybody is reaching for, and it was reachable
  // from every route into this picker — the strip, the row menu, the drum editor. The
  // other direction stays open: a snare through a bass lane is a legitimate noise.
  //
  // The one exception is a preset the lane is ALREADY playing. A picker cannot hide the
  // row it is meant to be highlighting, and hiding it would leave a drum whose sound has
  // no entry — see `offer.keep` above.
  const drumsOnly = pending
    ? !!pendingAddTrack?.drumsOnly
    : PERCUSSION_LANES.includes(baseLane(laneKey));
  const isDrumChoice = (v) => isKitVoice(v) || (chosen && v?.id === chosen);
  const KINDS = drumsOnly ? [{ id: 'drums', label: 'Drums', keep: isDrumChoice }] : [
    { id: 'all', label: 'All', keep: () => true },
    { id: 'pitched', label: 'Pitched', keep: (v) => !isKitVoice(v) },
    { id: 'drums', label: 'Drums', keep: (v) => isKitVoice(v) },
  ];
  // The plus button is deliberately neutral: it is creating a new track, not adding
  // another Tom. Existing lanes still open on their useful lane-specific family.
  let kind = drumsOnly ? 'drums' : pending ? 'all'
    : PERCUSSION_LANES.includes(baseLane(laneKey)) ? 'drums' : 'pitched';
  let engine = 'all';
  const keepOf = (id) => (KINDS.find((k) => k.id === id) || KINDS[0]).keep;
  // A lane whose own kind is empty opens on everything rather than on nothing. Nothing
  // in the catalogue does that today; a preset library one edit from now might.
  if (!drumsOnly && !offeredVoices(laneKey, offer).some(keepOf(kind))) kind = 'all';
  const enginesForKind = (kindId) => [...new Set(offeredVoices(laneKey, offer)
    .filter(keepOf(kindId)).map(engineOf).filter(Boolean))]
    .sort((a, b) => engineLabel(a).localeCompare(engineLabel(b)));
  const initialEngines = enginesForKind(kind);
  if (!pending && selectedEngine && initialEngines.includes(selectedEngine)) engine = selectedEngine;
  const chips = document.createElement('div');
  chips.className = 'voicekinds';
  const chipFor = (k) => {
    const c = document.createElement('button');
    c.className = 'voicekind' + (k.id === kind ? ' on' : '');
    c.textContent = k.label;
    c.title = k.id === 'all' ? 'Every preset in the library'
      : k.id === 'drums' ? 'kicks, snares, claps, hats and percussion'
        : 'Everything that plays a note';
    c.onclick = () => {
      kind = k.id;
      for (const other of chips.children) other.classList.toggle('on', other === c);
      refreshEngineOptions();
      draw(search.value);
    };
    return c;
  };
  // Existing tracks cannot change between melodic and drum lanes, so those filters
  // are useful only while the plus picker is deciding what kind of track to create.
  if (pending && !drumsOnly) for (const k of KINDS) chips.append(chipFor(k));
  const engineSelect = document.createElement('select');
  engineSelect.className = 'fxsel voiceengine';
  const refreshEngineOptions = () => {
    const availableEngines = enginesForKind(kind);
    if (engine !== 'all' && !availableEngines.includes(engine)) engine = 'all';
    engineSelect.textContent = '';
    const allEngines = document.createElement('option');
    allEngines.value = 'all'; allEngines.textContent = 'All engines';
    allEngines.selected = engine === 'all';
    engineSelect.append(allEngines);
    for (const id of availableEngines) {
      const option = document.createElement('option');
      option.value = id;
      option.textContent = engineLabel(id);
      option.selected = id === engine;
      engineSelect.append(option);
    }
    engineSelect.hidden = availableEngines.length < 2;
  };
  refreshEngineOptions();
  engineSelect.title = 'Show presets for the current engine, or all engines';
  engineSelect.onchange = () => { engine = engineSelect.value; draw(search.value); };
  head.append(who);
  if (now) head.append(now);
  head.append(chips);
  head.append(engineSelect);
  head.append(search);
  if (layer) {
    // A layer carries the identity of the part it copies, so its explanatory note stays
    // in the header rather than adding another filter control.
    const why = document.createElement('span');
    why.className = 'voicewhy';
    // The lane it actually copies, which is not always the engine lane it is named
    // after: a copy of `lead3` plays lead 3's part, not the song's own lead.
    const source = (mixFor(trackId).layers || []).find((l) => l.key === laneKey)?.from
      || baseLane(laneKey);
    why.textContent = `A duplicate of ${targetLabel(source)} — it plays that`
      + ' part with whatever you choose here';
    head.append(why);
  } else if (pending) {
    const why = document.createElement('span');
    why.className = 'voicewhy';
    why.textContent = 'Choose a preset for this new track';
    head.append(why);
  }

  // Keep the picker’s way out in the same place and style as the other desk
  // overlays. It is deliberately separate from preset rows so a close never
  // changes the current voice.
  const close = document.createElement('button');
  close.className = 'voiceclose popclose';
  close.type = 'button';
  close.textContent = '✕';
  close.title = 'Close preset selector';
  close.setAttribute('aria-label', 'Close preset selector');
  close.onclick = (ev) => { ev.stopPropagation(); closeMenu(); };
  head.append(close);

  // Nothing about EDITING a preset lives here. This panel answers "which sound",
  // which is a different question from "what should this sound be like" — and the way
  // into the second is on the strip header and the two items on the right-click menu.

  const results = document.createElement('div');
  results.className = 'voiceresults';

  const draw = (query) => {
    results.textContent = '';
    const q = query.trim().toLowerCase();
    const hit = (v) => !q || `${v.label} ${v.category} ${v.note} ${v.kind}`.toLowerCase().includes(q);
    const keep = keepOf(kind);
    const keepEngine = (v) => engine === 'all' || engineOf(v) === engine;

    let shown = 0;
    for (const [category, list] of offeredByCategory(laneKey, offer)) {
      const matches = list.filter((v) => keep(v) && keepEngine(v) && hit(v));
      if (!matches.length) continue;
      shown += matches.length;
      const g = document.createElement('div');
      g.className = 'fxgroup';
      const h5 = document.createElement('h5');
      h5.textContent = category;
      g.append(h5);
      for (const v of matches) {
        g.append(entry(v.id, v.label, v.kind === 'engine' ? 'Built in' : '',
          `${v.label} — ${v.note}`
          + (v.lanes ? `\n\nOnly on: ${v.lanes.map((k) => cap(VOICE_LANES[k].label)).join(', ')}.` : '')));
      }
      results.append(g);
    }
    // A query is a request for a SOUND, not a request to be told that the currently
    // selected engine cannot make it. If the engine-specific view is empty but the same
    // query exists elsewhere in the offered catalogue, broaden to All engines and keep
    // the query in place so the result appears without a second click or retype.
    if (q && !shown && engine !== 'all') {
      const elsewhere = offeredVoices(laneKey, offer)
        .some((v) => keep(v) && hit(v));
      if (elsewhere) {
        engine = 'all';
        refreshEngineOptions();
        draw(query);
        return;
      }
    }
    // A search that finds nothing has to say so. An empty panel reads as broken.
    //
    // If there really is no match in the offered kind, say so plainly rather than leaving
    // a blank panel that reads as broken.
    if (q && !shown) {
      const none = document.createElement('div');
      none.className = 'fxgroup voicesearch-none';
      none.textContent = `Nothing matches “${query.trim()}” in ${kind}`;
      results.append(none);
    }
  };

  search.addEventListener('input', () => {
    voicePickerQuery = search.value;
    draw(search.value);
  });
  // Escape clears the filter first and closes the panel only when it is already
  // empty — one key, and it never throws away a search you were still reading.
  search.addEventListener('keydown', (ev) => {
    if (ev.key !== 'Escape') return;
    ev.stopPropagation();
    if (search.value) {
      voicePickerQuery = '';
      search.value = '';
      draw('');
    } else closeMenu();
  });
  el.addEventListener('keydown', (ev) => {
    if (ev.key !== 'Escape' || ev.target === search) return;
    ev.preventDefault();
    ev.stopPropagation();
    closeMenu();
  });

  draw(search.value);
  el.append(head, results);

  el.style.left = `${x}px`;
  el.style.top = `${y}px`;
  el.classList.add('show');
  const r = el.getBoundingClientRect();
  el.style.left = `${Math.max(4, Math.min(x, innerWidth - r.width - 6))}px`;
  el.style.top = `${Math.max(4, Math.min(y, innerHeight - r.height - 6))}px`;
  requestAnimationFrame(() => {
    if (!el.classList.contains('show')) return;
    // Opening ON the sound the lane already plays, rather than at the top of a list it
    // is somewhere inside. `nearest` so a row that is already visible does not move,
    // and `preventScroll` on the focus after it so the caret does not undo the scroll.
    currentRow()?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    search.focus({ preventScroll: true });
  });
}

function channelStrip(lane, mix, slotRows, number) {
  const key = lane.key;
  const s = laneSettings(mix.lanes[key]);
  const seam = seamFor(key);
  const preset = presetForLane(key);
  const { el, head, body, foot } = stripShell(key, {
    label: customTrackLabel(key) || preset?.label || lane.label,
    sublabel: preset?.category || null,
    synth: synthAbbrevFor(preset),
    tag: lane.group, colour: laneColour(key), tint: laneTint(key), number,
  });
  // The head is the strip's handle, so double-clicking it plays the channel: from
  // the bar it comes in on, which for anything that enters late is the only bar you
  // wanted to hear. See playFromLaneStart.
  head.title = 'Click to show this strip’s devices below'
    + ' — double-click to play from where this channel comes in';
  head.addEventListener('dblclick', (ev) => {
    if (!ev.target.closest('.strippreset')) playFromLaneStart(key);
  });
  // …and it is the strip's handle in the other sense too: drag it to move the track.
  // The head only, not the whole strip — everything below it is a control with a drag
  // of its own. The preset name is excluded because it is a button living on the handle.
  laneDragHandle(el, head, key, '.strippreset, button, input, select');

  const presetName = head.querySelector('h3');
  if (seam && presetName) {
    presetName.classList.add('strippreset');
    presetName.setAttribute('role', 'button');
    presetName.tabIndex = 0;
    // No title: markClipped() owns this element's title attribute — it puts the full
    // name on only when the strip is too narrow to show it — so anything written here
    // is wiped on the next fit. A "Change X on Y" title used to sit here and had been
    // invisible for exactly that reason.
    //
    // One click, one job. Clicking the name of an unselected strip used to select the
    // channel and open the picker in the same motion, so the selection you had just
    // made was underneath the popup that came with it — you never got to see the strip
    // you landed on. Now the first click selects, and the second one changes the preset.
    const choosePreset = (ev) => {
      ev.stopPropagation();
      if (!presetArmed(key)) { selectLane(key); armPreset(key); return; }
      openVoicePicker(ev.clientX, ev.clientY, key);
    };
    presetName.addEventListener('click', choosePreset);
    presetName.addEventListener('dblclick', (ev) => ev.stopPropagation());
    presetName.addEventListener('keydown', (ev) => {
      if (ev.key !== 'Enter' && ev.key !== ' ') return;
      ev.preventDefault();
      const r = presetName.getBoundingClientRect();
      choosePreset({ clientX: r.left, clientY: r.bottom, stopPropagation() {} });
    });
  }

  // NO EDIT BUTTON ON THE HEAD. There used to be a » here that opened the preset editor
  // docked beside the strip. It is gone, and so is the docked editor: a strip head is
  // about a hundred pixels wide and already carries the number, the name, the caption
  // and — while you hover — a button drawn over the tail of that name. Editing the sound
  // is on the strip's right-click menu now, under SOUND, next to the picker that chooses
  // one. See stripMenu.

  const setEq = (band) => (x) => {
    editMix((m) => {
      const L = laneOf(m, key);
      L.eq = { ...LANE_DEFAULTS.eq, ...(L.eq || {}), [band]: x };
    }, `eq:${key}:${band}`);
    Audio.mixer?.lane(key)?.setEQ({ [band]: x });
  };
  for (const band of ['high', 'mid', 'low']) {
    body.append(eqRow(band, s.eq[band], setEq(band)));
  }

  // One send per aux, generated from AUXES — adding a fifth send upstream adds a
  // row here with no further work. Full words: a 132px strip has room for them,
  // and DLY/RVB made you translate.
  const SHORT = { delay: 'DELAY SEND', reverb: 'REVERB SEND' };
  for (const aux of AUXES) {
    // Every send starts shut and reads back what the mix actually stores — no family
    // default behind it, so a channel that echoes says so on its own face.
    const dflt = 0;
    // Both sends share the same displayed dB ceiling so the two sliders look
    // consistent. Reverb cheats: its +6 dB maps to gain 3.0 instead of 2.0
    // (a 1.5× hotter scale), so the knob still reaches the higher ceiling.
    const SEND_DB_MAX = 6;
    const sendGainMax = aux.id === 'reverb' ? 3 : 2;
    const gainScale = sendGainMax / dbToGain(SEND_DB_MAX);
    const rawVal = mix.lanes[key]?.send?.[aux.id] ?? dflt;
    // Same taper as the channel faders (FADER_SCALE). The slider stores a
    // 0–1 POSITION; posToDb/dbToPos give it the same piecewise curve every
    // fader on the desk uses. Unity at 75%, -10 dB at 50%, boost at the top.
    const toDisplayDb = (g) => {
      if (g <= 0.001) return FADER_DB_MIN;
      return clamp(gainToDb(g / gainScale), FADER_DB_MIN, SEND_DB_MAX);
    };
    const fromDisplayDb = (db) => db <= FADER_DB_MIN ? 0 : dbToGain(db) * gainScale;
    const fmtSend = (db) => {
      if (db <= FADER_DB_MIN) return 'OFF';
      return (db > 0 ? '+' : '') + db.toFixed(1);
    };
    const parseSend = (s) => {
      const cleaned = String(s).replace(/dB|db|Db/gi, '').trim();
      if (/^off$/i.test(cleaned)) return FADER_DB_MIN;
      const n = parseFloat(cleaned);
      return Number.isFinite(n) ? clamp(n, FADER_DB_MIN, SEND_DB_MAX) : null;
    };
    const row = slider({
      min: 0, max: 1, step: 0.001,
      value: dbToPos(toDisplayDb(rawVal)),
      reset: dbToPos(FADER_DB_MIN),
      fmt: (pos) => fmtSend(posToDb(pos)),
      display: {
        format: (pos) => fmtSend(posToDb(pos)),
        parse: (s) => {
          const db = parseSend(s);
          return db != null ? dbToPos(db) : null;
        },
      },
      onInput: (pos) => {
        const db = posToDb(pos);
        const lin = fromDisplayDb(db);
        editMix((m) => {
          const L = laneOf(m, key);
          L.send = { ...LANE_DEFAULTS.send, ...(L.send || {}), [aux.id]: lin };
        }, `${aux.id}:${key}`);
        Audio.mixer?.lane(key)?.setSend({ [aux.id]: lin });
      },
    });
    row.label.textContent = SHORT[aux.id] || aux.id.toUpperCase();
    row.wrap.classList.add('sendrow');       // what the Sends switch in the header hides
    // Nothing to qualify any more. Every channel taps the whole lane into every send
    // and no bank key scales it on the way, so this number IS the amount: the same
    // reading sends the same amount of kick as it does of lead, in every bar of every
    // song. It used to be worth whatever the playing section's `echoLevel` said, which
    // is why the tooltip had a story to tell and the control could not be trusted.
    row.wrap.title = `${aux.name} send`;
    body.append(row.wrap);
  }

  // Pan sits under the fader, above the buttons — see panRow.
  const pan = panKnob({
    value: s.pan,
    onInput: (x) => {
      editMix((m) => { laneOf(m, key).pan = x; }, `pan:${key}`);
      Audio.mixer?.lane(key)?.setPan(x);
    },
  });
  // Mute and solo close the strip, under the pot — the same small pair the
  // arrangement rows carry, so they read the same in both places.
  const btns = btnRow(...muteSoloPair(key, lane.label));

  // Declared before the fader so both callbacks can name it, and assigned after: the
  // fader is what `except` has to point at, and it does not exist yet.
  let fader = null;
  const applyGain = (x) => {
    editMix((m) => { laneOf(m, key).gain = x; }, `gain:${key}`);
    Audio.mixer?.lane(key)?.setGain(x);
    syncLaneGain(key, { except: fader });
  };
  const fb = faderBlock({
    value: s.gain,
    title: `${lane.label} level`,
    onInput: applyGain,
    // An untagged edit, so a double-click back to 0 is its own undo step rather
    // than being coalesced into the drag that came before it. Nothing is excepted:
    // a reset has already put the fader on 0 itself, and the readout with it.
    onReset: (x) => {
      editMix((m) => { laneOf(m, key).gain = x; });
      Audio.mixer?.lane(key)?.setGain(x);
      syncLaneGain(key);
    },
  });
  fader = fb.fader;

  foot.append(insertSlots(key, lane.label, slotRows), faderRow(fb.col), panRow(pan.el), btns);
  stripMenu(el, key, 'channel');
  meters.push({ key, chans: fb.chans, meter: fb.meter });
  return el;
}

/**
 * A send return. Its own parameters — the delay's time and feedback, the reverb's
 * decay — are the pinned card in the device panel below, not rows on the strip: a
 * 132px column cannot hold TIME/FBK/DAMP legibly, and the attempt pushed the
 * return EQ off the strip entirely.
 */
function sendStrip(def, mix, slotRows) {
  const key = `__aux:${def.id}`;
  const cur = fxOf(mix)[def.id];
  const hue = def.type === 'delay' ? 196 : 268;
  const { el, body, foot } = stripShell(key, {
    label: def.name.toUpperCase(), tag: 'send', cls: 'send',
    colour: hueColour(hue), tint: hueTint(hue),
  });

  // Values only, in the order the card lists them — a 132px strip has room for the
  // numbers or for their names, and the numbers are what you are checking.
  body.append(deviceSummary(key, def.type === 'delay'
    ? `${fmtDelay(syncSeconds(cur.division, deskTempo()))} · ${cur.feedback.toFixed(2)}`
      + ` · ${cur.tone >= 1000 ? `${(cur.tone / 1000).toFixed(1)}k` : cur.tone}`
    : `${cur.decay.toFixed(1)}s · pre ${(cur.preDelay * 1000).toFixed(0)}ms`));

  // The return EQ, in the same three rows and the same place a channel keeps its
  // own. On a reverb this is the damping control in everything but name.
  for (const band of ['high', 'mid', 'low']) {
    body.append(eqRow(band, cur.eq?.[band] ?? 0, (x) => {
      editFx(def.id, { eq: { ...(fxOf(mixFor(trackId))[def.id].eq || {}), [band]: x } },
        `${def.id}:eq:${band}`);
    }));
  }

  // The return level IS this strip's fader, which is what it always was
  // semantically — it just used to be a slider called SEND halfway up the panel.
  const lvlDb = 20 * Math.log10(Math.max(0.001, cur.level ?? 1));
  const fb = faderBlock({
    value: Math.round(lvlDb * 10) / 10,
    // +6, the same ceiling every fader on the desk has. A return that went to +12
    // because the echo happens to be quiet is a fader that means something different
    // from the one beside it, and a desk you have to remember exceptions about is
    // worse than an echo you have to push. The loud end is still reachable: the send
    // itself goes to 2, which with this at +6 puts the return within a dB of the
    // channel it came from.
    title: def.legacy
      ? `${def.name} return level — a scale on the echo the song asks for`
        + ' (its sections automate that between 0 and about 0.35, so this lifts the'
        + ' whole ramp and keeps its shape)'
      : `${def.name} return level`,
    onInput: (x) => editFx(def.id, { level: 10 ** (x / 20) }, `${def.id}:level`),
  });

  // A return pans like a channel: the same pot in the same place. Mute takes the
  // return out of the mix; solo leaves the channels feeding it and mutes everything
  // else, so you hear the effect on its own.
  const pan = panKnob({
    value: cur.pan ?? 0,
    onInput: (x) => editFx(def.id, { pan: x }, `${def.id}:pan`),
  });
  const mute = document.createElement('button');
  mute.textContent = 'M';
  mute.className = 'mutebtn warn' + (cur.mute ? ' on' : '');
  mute.title = `Mute the ${def.name} return`;
  mute.onclick = (ev) => {
    ev.stopPropagation();
    const on = !mute.classList.contains('on');
    mute.classList.toggle('on', on);
    editFx(def.id, { mute: on }, null);
  };
  const solo = document.createElement('button');
  solo.textContent = 'S';
  solo.className = 'solobtn' + (soloedAux.has(def.id) ? ' on' : '');
  solo.title = `Solo the ${def.name} return — monitoring only, never saved`;
  solo.onclick = (ev) => {
    ev.stopPropagation();
    const on = !solo.classList.contains('on');
    solo.classList.toggle('on', on);
    if (on) soloedAux.add(def.id); else soloedAux.delete(def.id);
    Audio.mixer?.setAuxSolo(def.id, on);
    updateSoloLight();
  };
  foot.append(insertSlots(key, def.name, slotRows), faderRow(fb.col), panRow(pan.el),
    btnRow(mute, solo));
  stripMenu(el, key, 'send');
  meters.push({ key, chans: fb.chans, meter: fb.meter });
  return el;
}

/**
 * The master bus. No EQ rows: there is no EQ node on the master path — a parametric
 * EQ in the insert slots is how you do it, and it is a better EQ than three fixed
 * bands anyway. The limiter is the last slot in the insert block, where the rest of
 * the chain is: it is the LIMITER button under the fader, on the line the channels
 * keep their M and S on. There used to be a summary line up here saying "limiter off"
 * in words, and a checkbox on a card called "Master" in the panel below.
 */
function masterStrip(mix, slotRows) {
  const { el, foot } = stripShell('__master', { label: 'MASTER', tag: 'bus', cls: 'master' });
  const setMaster = (x) => setMasterControlValue(x, 'master');
  const fb = faderBlock({
    // The same fader as every channel, which it did not used to be: this one ran
    // −24…+12, so the master was the one strip that could be pushed somewhere none
    // of the channels feeding it could follow, and the one whose knee meant a
    // different gain from its neighbours'. The narrow range was buying fine control
    // near unity; the taper gives that to every fader on the desk — see FADER_SCALE.
    value: mix.master || 0,
    // The only stereo meter on the desk: the master is where a mix leaning to one side
    // shows up, and the one strip whose meter you read as a pair rather than a level.
    stereo: true,
    title: 'Master trim, on top of the bank’s own musicTrim',
    onInput: setMaster,
    onReset: (x) => setMasterControlValue(x),
  });
  masterStripControl = fb;
  syncMasterControls(mix.master || 0);
  // The master's own balance, in the pot every other strip keeps its pan in. It is
  // the last thing on the bus before the limiter, so it moves the whole mix rather
  // than anything in it — which is what a master pan is for.
  const pan = panKnob({
    value: mix.masterPan || 0,
    onInput: (x) => {
      editMix((m) => { m.masterPan = x; }, 'masterPan');
      Audio.mixer?.setMasterPan(x);
    },
  });
  // Where a channel keeps M and S, the master keeps its limiter — under the fader and
  // out of the insert block, which is the honest place for it. It is not in the chain
  // and cannot be moved within it: it is the last thing before the speakers, always.
  foot.append(insertSlots('__master', 'master', slotRows), faderRow(fb.col), panRow(pan.el),
    btnRow(limiterButton(!!mix.limiter)));
  stripMenu(el, '__master', 'master');
  meters.push({ key: '__master', chans: fb.chans, meter: fb.meter });
  return el;
}

// ---- the desk's vertical budget, in one place --------------------------------
// Every minimum and every automatic target the layout uses. They used to be six
// numbers spread across five functions — a 48 in the fader, a 140 in the --striph
// floor, a 96 in the effects panel, an 8 called a floor in the arrangement, and two
// ceiling expressions that disagreed with each other about what the effects panel
// was allowed to take. Anything that wants to know how small a region may be asks
// here, and there is one answer.

// The fader is the desk's shock absorber. In a short window it gives up height so
// the EQ and send rows above it stay on screen — they are read constantly while
// balancing, where the fader is a grip you can still hit, with an exact dB readout
// under it either way. Given room it takes all of it — there is no cap, so the
// strips always fill the rack exactly and a tall window ends up with long faders
// rather than a band of empty desk under short ones.
//
// A comfortable height rather than a floor: this is the fader the rack ASKS for when
// it is deciding how much of the window to want (see rackWant). What it will actually
// settle for is FADER_FLOOR below.
const FADER_MIN = 48;
// And how far it will compress to keep one more BLOCK on screen. Two numbers rather
// than one, because with only the comfortable minimum to bargain with the ladder shed
// far too eagerly: five pixels short of fitting the EQ, it would drop the EQ and the
// sends together and then hand the ninety pixels that freed straight back to the
// fader — a strip that was nearly all fader, with the rows you were reaching for
// gone. A fader is still a fader at this height; three EQ bands you cannot see are
// not an EQ.
const FADER_FLOOR = 34;
// The arrangement's automatic answer. Eight lanes is enough to read a song's shape
// and the rest is a scroll. It is a TARGET, not a floor: the floor is one lane, and
// calling the eight a floor is most of why this used to be hard to reason about.
// Read from the shell rather than written here twice: the CSS cap on #arrange is the
// same eight, and the two being separate numbers is a bug waiting for the day one of
// them is changed.
const ARR_AUTO_LANES = () => {
  const n = parseFloat(getComputedStyle(document.documentElement)
    .getPropertyValue('--arrmax-lanes'));
  return Number.isFinite(n) && n >= 1 ? n : 8;
};
// The effects panel below its own header: enough for one card's controls. Below it
// the panel is a title bar with a sliver under it, which tells you nothing and
// still costs the height.
const DEV_MIN_EXTRA = 48;
// And the least the same panel may be while it is showing the piano roll instead:
// about eight keys under the scope, which is a hand's worth of range. A roll is a
// much taller thing than a rack of cards, and one floor cannot serve both.
const DEV_MIN_ROLL = 8 * 29;
/**
 * The rack's own vertical chrome: its padding, plus whatever the horizontal
 * scrollbar takes at the bottom. Measured, because `scrollbar-gutter: stable`
 * reserves that space whether or not the bar is showing — assuming 20px left six
 * pixels unaccounted for, which was enough to put a vertical scrollbar down the rack
 * and cut the padding under the strips.
 */
function rackPad() {
  const rack = $('rack');
  if (!rack) return 20;
  return px(rack, 'paddingTop') + px(rack, 'paddingBottom')
    + (rack.offsetHeight - rack.clientHeight);
}

const h = (el) => (el ? el.getBoundingClientRect().height : 0);
const px = (el, prop) => parseFloat(getComputedStyle(el)[prop]) || 0;

/**
 * Every pixel #desk has to divide between its four regions:
 * the window, less the things that live outside the desk and are never
 * negotiated with.
 *
 * Note what is NOT in here: the effects panel is allocated by planDesk, not treated as
 * page chrome. Its natural or dragged height is subtracted there alongside the other
 * desk regions, while every border hit area remains layout-free.
 */
const deskPool = () => innerHeight
  - h(document.querySelector('header')) - h($('timeline'))
  - h(document.querySelector('footer')) - h($('err'));

// The window height the remembered panel sizes were dragged on. The sizes themselves
// are absolute pixels — coming back to the desk you left is the whole point of keeping
// them — but a height set on a tall display would swallow a laptop screen whole. A
// shorter window scales them all by the ratio the desk itself shrank by, so the panels
// keep their proportions, and the STORED numbers are left alone: plug the big screen
// back in and you get the desk you set up on it, not the squeezed version.
const DESK_VH_KEY = 'mash-mixer-deskvh';
const storedDeskVh = Number(localStorage.getItem(DESK_VH_KEY));
const deskScale = Number.isFinite(storedDeskVh) && storedDeskVh > 200
  ? Math.min(1, innerHeight / storedDeskVh)
  : 1;
// Clamped on the way in: a stale or nonsense height (drag hard upwards and it goes
// negative) would otherwise pin a panel shut on every load with no way to tell why.
const restoredDeskH = (value, floor) => (Number.isFinite(value) && value > floor
  ? Math.round(value * deskScale)
  : null);

// A height the user dragged the Notes border to, which beats the automatic fit until
// they double-click it away. Kept across reloads: it is a preference about this
// screen, not about the mix.
const ARR_KEY = 'mash-mixer-arrh';
const storedArrH = Number(localStorage.getItem(ARR_KEY));
let userArrH = restoredDeskH(storedArrH, 40);
// A one-lane height can be useful while actively dragging, but restoring one on the
// next load looks exactly like the arrangement has lost its other instruments. Keep
// that temporary squeeze for the current session; stale one-lane preferences fall
// back to automatic fitting once the rows have been built.
let restoredArrH = userArrH != null;

// A height the user dragged the Notes border to. Like the arrangement height, this
// is a preference about the desk rather than a mix edit, so it lives outside the song
// draft and returns on the next visit. Double-clicking the border clears it and lets
// the measured roll height take over again. DEV_KEY remains the persisted key for
// compatibility with existing mixer sessions.
const DEV_KEY = 'mash-mixer-devh';
const storedDevH = Number(localStorage.getItem(DEV_KEY));
let userDevH = restoredDeskH(storedDevH, 40);
const clampDeviceH = (value, max = notesRoom()) => clamp(value, MIN.notes(), max);

// Effects has its own remembered height. This is the panel's content room below
// its header, kept separate from DEV_KEY, which belongs to Notes.
const FX_KEY = 'mash-mixer-fxh';
const storedFxH = Number(localStorage.getItem(FX_KEY));
let userFxH = restoredDeskH(storedFxH, DEV_MIN_EXTRA);

/**
 * Write the three dragged panel heights and the window they belong to.
 *
 * All three together, never one on its own: the window stamp is what the next load
 * scales them by, so a single height written on a laptop would leave the other two
 * claiming to have been chosen there too, at their full desktop size.
 *
 * Called when a gesture ENDS, not while it runs — the drag handlers move these values
 * every frame, and localStorage is not a place to put a frame loop.
 */
function rememberDeskHeights() {
  const set = (key, value) => (value == null
    ? localStorage.removeItem(key)
    : localStorage.setItem(key, String(Math.round(value))));
  set(ARR_KEY, userArrH);
  set(DEV_KEY, userDevH);
  set(FX_KEY, userFxH);
  localStorage.setItem(DESK_VH_KEY, String(Math.round(innerHeight)));
}

// The arrangement's height is its header, its landing, the panel rule, and a whole
// number of row stacks. Every term is MEASURED off the live elements, so changing
// --arrrow, --arrgap, --arrgrid-pad or the header's control size in the shell moves
// the snap with it and nothing here needs touching.
//
// The gap belongs to the stack: leaving it out makes the last visible row spill below
// a snapped height. There is no trailing gap, so N rows carry N-1 of them.
const laneRowHeight = () => h(document.querySelector('.arrrow')) || 26;
const laneRowGap = () => px($('arrgrid'), 'rowGap');
const laneStackHeight = (count) => count * laneRowHeight()
  + Math.max(0, count - 1) * laneRowGap();
// The landing under the last visible row. It is #arrange's padding, NOT #arrgrid's:
// inside the scroller it is scroll content, which is only under the last row when you
// happen to be scrolled to the bottom — every other scroll position spent it on the
// gap and the top few pixels of the next lane, so a panel that had snapped correctly
// still showed a sliver of a row it had not made room for.
const laneLanding = () => px($('arrange'), 'paddingBottom');
const arrangeChrome = () => h($('arrhead')) + laneLanding()
  + px($('arrange'), 'borderBottomWidth');
const laneCount = () => document.querySelectorAll('.arrrow').length || 1;
/**
 * How many whole lanes fit in `px` of arrangement. Below one is a fold, not a row.
 *
 * The epsilon is load-bearing. Heights come from getBoundingClientRect and are
 * fractional, so a request built as "the header plus an eight-row stack" divides back
 * out to 7.99999… and Math.floor hands back seven — the automatic fit was one row short
 * of what it had just asked for, on every window tall enough to grant it.
 */
const lanesIn = (px, round = Math.round) => {
  const row = laneRowHeight();
  const gap = laneRowGap();
  const body = px - arrangeChrome();
  return round((body + gap) / (row + gap) + 1e-6);
};
/**
 * The nearest height that shows whole lanes, at least one. Rounding to the NEAREST is
 * right under the hand on the border — half a lane either way should settle on the
 * one you meant. It is wrong against a ceiling: rounding up there hands the rack back
 * a few pixels it was promised, and a strip four pixels short scrolls its last send
 * row out of sight. So the automatic fit passes Math.floor.
 */
const arrangeSnap = (px, round = Math.round) => arrangeChrome()
  + laneStackHeight(clamp(lanesIn(px, round), 1, laneCount()));

/**
 * And the most it can use: every lane at once. The scroller's content is now exactly
 * the row stacks — the landing lives outside it — so its scrollHeight adds straight
 * onto the chrome.
 */
function arrangementWants() {
  const arrange = $('arrange');
  if (arrange.classList.contains('collapsed')) return h(arrange);
  return arrangeChrome() + $('arrgrid').scrollHeight;
}

/**
 * Keep the selected lane inside the arrangement's window while the panel is resized.
 *
 * The scroller holds its scrollTop as the panel shrinks, so the lanes that drop out of
 * sight are the ones nearest the border under the hand — and the lane being worked on
 * is as likely to be one of them as any other. Scroll by the least that puts it back:
 * down when it has fallen off the bottom, up when it sits above the top. A folded panel
 * has nothing to keep visible, and neither has a selection with no row of its own,
 * which is what the master is.
 *
 * The offsets come from the lane's INDEX, not its rect: every row is one fixed height
 * with one fixed gap between, the same two numbers arrangeSnap is written off, and
 * nothing but rows goes into the scroller. A rect would measure from #arrange — the
 * nearest positioned ancestor — and so would carry the header along with it.
 */
function keepSelectedLaneVisible() {
  const grid = $('arrgrid');
  if (!grid || $('arrange').classList.contains('collapsed')) return;
  const index = [...grid.querySelectorAll('.arrrow')]
    .findIndex((el) => el.classList.contains('sel'));
  if (index < 0) return;
  const row = laneRowHeight();
  const view = grid.clientHeight;
  if (!(row > 0) || view <= 0) return;
  const top = index * (row + laneRowGap());
  const bottom = top + row;
  // Below the window: bring its bottom edge in, but never far enough to push its top
  // out — a window too short for a whole row shows the top of the lane, not its feet.
  if (bottom > grid.scrollTop + view) grid.scrollTop = Math.min(bottom - view, top);
  else if (top < grid.scrollTop) grid.scrollTop = top;
}

/**
 * Make the arrangement follow the channel selection in both state and position.
 *
 * Selection can happen before its rows exist (notably buildRack during song load), so
 * buildArrangement calls this again after creating them. The caller chooses whether to
 * reveal it: a channel click and a restored piano-roll track do; an unrelated rebuild
 * only restores the selected mark and preserves the user's manual arrangement scroll.
 */
function syncArrangementLaneSelection({ reveal = false } = {}) {
  for (const el of document.querySelectorAll('.arrrow')) {
    const selected = el.dataset.lane === selectedLane;
    el.classList.toggle('sel', selected);
    el.setAttribute('aria-selected', selected ? 'true' : 'false');
  }
  if (reveal) keepSelectedLaneVisible();
}

// Asked for by a gesture that changes the arrangement's height, spent by the fit that
// gesture scheduled: the lane can only be scrolled back into view once applyDesk has
// written the new height, and that lands a frame later.
let keepLanePending = false;

/**
 * What the strip body needs when nothing is squeezing it. Measured by taking the
 * body out of the flex layout for one frame rather than by adding up rows: the rows
 * carry margins as well as the container's gap and padding, and summing the pieces
 * by hand quietly lost the margins — which cost the last send row its slider.
 */
function naturalHeight(body) {
  const was = body.style.flex;
  body.style.flex = '0 0 auto';
  const natural = body.scrollHeight;
  body.style.flex = was;
  return natural;
}

/**
 * Everything in a strip whose height does not move with the fader — the pan, the
 * buttons and the readout are all fixed, so the fader is the only variable left.
 *
 * Measured across EVERY strip, not off the first one: the insert buttons live in the
 * foot, so a channel with five effects on it stands a hundred pixels taller in the
 * fixed parts than a channel with none. Sizing the rack from the first strip gave the
 * busy ones a body too short for their own rows, and the body scrolls without a
 * scrollbar — so the EQ and sends simply vanished off the bottom.
 *
 * Rounded up: a strip half a pixel short scrolls the last send row's slider out of
 * view, which is the whole thing this is here to prevent.
 */
/**
 * The rack's shrink ladder, in the order the blocks go. Inserts first — they are the
 * one block you set once and then leave alone. Sends next. EQ last, because it is the
 * one you are most likely to be reaching for while the window is small. Below the
 * bottom of this list is the strip you balance on: name, type, fader, dB, pan and
 * mute/solo, with nothing left to take.
 *
 * The same three blocks the header switches hide, hidden the same way — see the
 * #rackwrap.shed-* rules. A DIFFERENT set of classes from the switches, so growing
 * the window back restores exactly what is ticked and nothing more.
 */
const SHED_ORDER = ['effects', 'sends', 'eq'];
// One id space with the switches, and the class derived from theirs rather than
// spelled again: the insert block is `effects` to a switch and `fx` to a stylesheet,
// and writing that mapping down twice is how the two sets drift apart.
const shedClass = (id) => STRIP_PARTS.find((p) => p.id === id).cls.replace('no-', 'shed-');

/**
 * Measure the rack `n` blocks into the ladder, rather than wherever it happens to be
 * standing. Every number the fit is steered by has to be independent of the rung it
 * is currently on, or the fit stops being a function of the window and starts being a
 * function of its own last answer — which is a latch, and a short window once meant a
 * short window forever.
 *
 * `measuring` also lifts --striph off .strip and --bodyh off .stripbody,
 * both of which are given a height explicitly and would otherwise answer the question
 * with the previous answer — the body worst of all, since a body held at last rung's
 * height reports that height back and --bodyh would only ever climb. The fader is
 * pinned for the same reason: left live, a strip measures taller on a tall window than
 * on a short one and the rack's floor ratchets up as the window grows.
 */
function atShed(n, fn) {
  const wrap = $('rackwrap');
  const had = SHED_ORDER.map(shedClass).filter((c) => wrap.classList.contains(c));
  wrap.classList.remove(...SHED_ORDER.map(shedClass));
  wrap.classList.add(...SHED_ORDER.slice(0, n).map(shedClass), 'measuring');
  wrap.style.setProperty('--faderh', `${FADER_FLOOR}px`);
  try {
    return fn();
  } finally {
    wrap.style.removeProperty('--faderh');
    wrap.classList.remove('measuring', ...SHED_ORDER.map(shedClass));
    wrap.classList.add(...had);
  }
}

/**
 * Two numbers from one pass, `n` blocks into the ladder: the body height every strip
 * is held to at this rung, and everything in a strip whose height does not move with
 * the fader — header, body, inserts, readout, pan and buttons are all fixed, so the
 * fader is the only variable left.
 *
 * The MAX of the bodies, not each strip's own — that is what --bodyh is: the rack
 * reserves the tallest body on every strip, so a master with nothing in its body and a
 * channel with three EQ rows and two sends start their faders on the same line.
 *
 * The rest is a max across EVERY strip too, not off the first one: the insert buttons
 * live in the foot, so a channel with five effects on it stands a hundred pixels taller
 * in the fixed parts than a channel with none, and sizing the rack from the first strip
 * gave the busy ones a body too short for their own rows. The two maxes are added
 * rather than the per-strip sums maxed: the tallest body and the tallest foot need not
 * start out on the same strip, and after --bodyh they are on every strip.
 *
 * Rounded up: a strip half a pixel short cuts the last row it is showing.
 */
function measureRungAt(n) {
  return atShed(n, () => {
    let body = 0, rest = 0;
    for (const s of document.querySelectorAll('.strip')) {
      const b = s.querySelector('.stripbody');
      if (!b) continue;
      body = Math.max(body, naturalHeight(b));
      // Each strip's own fader comes out of its own total — that is the part this is
      // solving for, and a strip without one has none to subtract.
      rest = Math.max(rest, px(s, 'paddingTop') + px(s, 'paddingBottom')
        + h(s.querySelector('.striphead'))
        + h(s.querySelector('.stripfoot')) - h(s.querySelector('.faderwrap')));
    }
    return { body: Math.ceil(body), chrome: Math.ceil(body + rest) + 2 };
  });
}

/**
 * The four rungs, cached: chrome and body height, one pair per rung of the ladder.
 * Measuring all of them costs four passes over the rack, so it is done once and thrown
 * away by forgetStripMetrics() when something that could move them moves — a rack
 * rebuild, a typeface change, or a part switch, since a block you have already hidden
 * by hand has no height for the ladder to save by hiding it again.
 */
let chromeRungs = null;
const forgetStripMetrics = () => { chromeRungs = null; };
function stripRungAt(n) {
  if (!chromeRungs) {
    // Asked before the first buildRack — applyFont() and reserveDevices() both run at
    // load. Plausible numbers rather than a throw; the real ones arrive with the first
    // fit after the rack exists, and forgetStripMetrics() is what fetches them.
    // These are only a pre-build safety estimate. Keep them aligned with the current
    // selector-free strip: the preset now lives in the header and adds no body row.
    // No body number to guess at: nothing is on screen for --bodyh to hold level, and
    // the first real fit writes it before a strip exists to read it.
    if (!document.querySelector('.strip[data-lane]')) {
      return { chrome: [230, 190, 150, 110][n], body: 0 };
    }
    chromeRungs = SHED_ORDER.map((_, i) => measureRungAt(i));
    chromeRungs.push(measureRungAt(SHED_ORDER.length));
  }
  return chromeRungs[n];
}
const stripChromeAt = (n) => stripRungAt(n).chrome;

/** What a full strip needs, and what the last one standing needs. */
const stripChrome = () => stripChromeAt(0);
const bareChrome = () => stripChromeAt(SHED_ORDER.length);

/**
 * The least the rack may be: a strip with every sheddable block gone and the fader at
 * its own minimum, plus the rack's padding. Nothing is hidden behind this — there is
 * no scrolled-away row under it, because the ladder hides whole blocks and says so on
 * the header switch rather than letting a body scroll silently.
 */
function rackFloor() { return bareChrome() + FADER_FLOOR + rackPad(); }

// The roll's scope strip, measured while it is up and kept while it is not. Zero only
// before the roll has ever been built, which is the same nothing the old direct
// measurement returned then.
let lastRollScopeH = 0;
function rollScopeH() {
  const now = h($('pianoroll').querySelector('.ssqscope'));
  if (now) lastRollScopeH = now;
  return lastRollScopeH;
}

/**
 * The least each region may be while it is OPEN, measured rather than written down:
 * every one of these moves with the typeface, and two of them move with the song. A
 * FOLDED region is not in here — its height is its own header and there is nothing
 * to negotiate about it.
 */
const MIN = {
  /** Fixed by CSS at 30 or 44; the sections fold is the only thing that moves it. */
  timeline: () => h($('timeline')),
  /** Header and one row. Whole rows only, always — see arrangeSnap. */
  arrange: () => arrangeChrome() + laneStackHeight(1),
  /** A strip with every sheddable block gone, and the rack's padding. */
  mixer: () => rackFloor(),
  /** The notes panel: header plus enough of a keyboard to play against. The scope
   *  strip is measured when it is on screen and REMEMBERED when it is not — a drum
   *  channel takes the roll out of the panel (see laneHidesRoll), and a floor that
   *  drops by the height of a hidden strip would let a cramped desk claw back room
   *  from the panel every time the selection landed on the kick. */
  notes: () => h($('notehead')) + rollScopeH() + DEV_MIN_ROLL,
  /** Effects panel: header plus room for one card row. */
  devices: () => h($('devhead')) + DEV_MIN_EXTRA,
};

/** What each region asks for when nothing is squeezing it. A dragged height wins. */
const WANT = {
  arrange: () => (userArrH != null ? userArrH
    : Math.min(arrangementWants(),
      arrangeChrome() + laneStackHeight(ARR_AUTO_LANES()))),
  /** Notes panel wants enough height for the roll. */
  notes: () => (userDevH != null ? userDevH : (autoDevH || 204)),
};

// The height the effect cards themselves ask for, measured by reserveDevices().
let autoDevH = 0;
/** Effects panel height — its content by default, or the user's dragged height. */
const effectsNaturalHeight = () => {
  if ($('devices').classList.contains('collapsed')) return 0;
  return h($('devhead')) + (userFxH != null ? userFxH : (autoDevH || DEV_MIN_EXTRA));
};

/** Maximum effects room while leaving the other open panels at their floors. */
function effectsRoom() {
  const arrH = $('arrange').classList.contains('collapsed')
    ? h($('arrange')) : plannedArrangeHeight();
  const notesH = $('notes').classList.contains('collapsed')
    ? h($('notes')) : Math.max(MIN.notes(), userDevH ?? MIN.notes());
  const rackH = $('rackwrap').classList.contains('collapsed') ? 0 : MIN.mixer();
  return Math.max(DEV_MIN_EXTRA, Math.floor(deskPool()
    - h($('mixhead')) - arrH - notesH - rackH - h($('devhead'))));
}
const clampEffectsH = (value) => clamp(value, DEV_MIN_EXTRA, effectsRoom());

/** The height the arrangement will be given, from preferences and content alone. */
const plannedArrangeHeight = () => ($('arrange').classList.contains('collapsed')
  ? h($('arrange'))
  : arrangeSnap(WANT.arrange(), Math.floor));

/**
 * What the notes panel is allowed to take — the room between the rack's floor and
 * the effects panel's selected height at the bottom.
 */
function notesRoom(arrH = plannedArrangeHeight()) {
  const fxH = effectsNaturalHeight();
  const room = deskPool()
    - h($('mixhead'))
    - arrH
    - ($('rackwrap').classList.contains('collapsed') ? 0 : MIN.mixer())
    - fxH;
  return Math.max(MIN.notes(), Math.floor(room));
}

/**
 * Exactly one region in the desk is elastic, chosen in this order: the rack, then
 * the arrangement, then the notes panel, then the empty band at the end. The effects
 * panel has its own selected height and is outside that elastic chain.
 */
const DESK_CHAIN = ['rackwrap', 'arrange', 'notes', 'deskslack'];
function applyDeskChain() {
  const winner = DESK_CHAIN
    .filter((id) => id !== 'arrange')
    .find((id) => id === 'deskslack' || !$(id).classList.contains('collapsed'));
  for (const id of DESK_CHAIN) $(id).classList.toggle('greedy', id === winner);
}

/**
 * Who gets which pixels, worked out before anything is written.
 *
 * The effects panel at the bottom takes its natural or manually selected height. If
 * that leaves the window short, the Mixer gives up its room first; only then do the
 * other panels surrender space to preserve their minimums.
 */
function planDesk() {
  const arrOpen = !$('arrange').classList.contains('collapsed');
  const rackOpen = !$('rackwrap').classList.contains('collapsed');
  // The FOLD, and only the fold. A panel with its roll out is still open and still
  // holds its room — see laneHidesRoll.
  const notesOpen = !$('notes').classList.contains('collapsed');

  if (restoredArrH && laneCount() > 1) {
    if (userArrH <= MIN.arrange() + 1) {
      userArrH = null;
      rememberDeskHeights();
    }
    restoredArrH = false;
  }

  const fxH = effectsNaturalHeight();
  // When the effects panel is collapsed, its header still occupies space in the
  // flex layout but effectsNaturalHeight() returns 0. Account for it so the rack
  // doesn't get over-allocated height that the header then steals.
  const fxCollapsedHeader = (!$('devices').classList.contains('collapsed') || fxH > 0) ? 0 : h($('devhead'));
  const fixed = h($('mixhead'))
    + (arrOpen ? 0 : h($('arrange')))
    + (notesOpen ? 0 : h($('notes')))
    + fxH + fxCollapsedHeader;
  const arrMin = arrOpen ? MIN.arrange() : 0;
  const notesMin = notesOpen ? MIN.notes() : 0;
  const rackMin = rackOpen ? MIN.mixer() : 0;
  const chrome = rackOpen ? stripChrome() : 0;
  const rackWant = !rackOpen ? 0
    : notesOpen ? MIN.mixer()
      : chrome + FADER_MIN + rackPad();
  const room = deskPool() - fixed;
  const lane = laneRowHeight() + laneRowGap();

  let arrH = !arrOpen ? 0
    : arrangeSnap(rackOpen ? WANT.arrange()
      : (userArrH != null ? userArrH : arrangementWants()), Math.floor);
  let notesH = notesOpen ? Math.max(notesMin, WANT.notes()) : 0;
  let rackH = room - arrH - notesH;

  const byHand = (arrOpen && userArrH != null)
    || (notesOpen && userDevH != null) || userFxH != null;

  const clawBack = (short, forced) => {
    if (notesOpen && (forced || !byHand)) {
      const give = Math.min(short, notesH - notesMin);
      notesH -= give;
      short -= give;
    }
    if (short > 0 && arrOpen && (forced || !byHand)) {
      arrH -= Math.min(Math.ceil(short / lane) * lane, arrH - arrMin);
    }
    rackH = room - arrH - notesH;
  };

  if (rackH < rackWant) clawBack(rackWant - rackH, false);
  if (rackH < rackMin) clawBack(rackMin - rackH, true);
  const cramped = rackH < rackMin - 1;
  return { arrOpen, rackOpen, notesOpen, arrH, notesH, fxH, chrome, rackH: rackOpen ? rackH : 0, cramped };
}

/** Write the plan out. */
function applyDesk({ arrOpen, rackOpen, notesOpen, arrH, notesH, fxH, chrome, rackH, cramped }) {
  $('desk').classList.toggle('cramped', cramped);
  $('arrange').style.maxHeight = arrOpen ? `${Math.round(arrH)}px` : '';
  // Notes panel height. When folded or greedy, let CSS handle it.
  if (!notesOpen) {
    $('notes').style.height = '';
  } else if ($('notes').classList.contains('greedy')) {
    $('notes').style.height = '';
  } else {
    $('notes').style.height = `${Math.round(notesH)}px`;
  }
  // Effects panel: natural or manually selected height.
  if (fxH > 0) {
    $('devices').style.height = `${Math.round(fxH)}px`;
  } else {
    $('devices').style.height = '';
  }
  if (rackOpen) sizeStrips(Math.floor(rackH - rackPad()));
}

/**
 * The rack's shrink ladder. `strips` is the height one strip may occupy — the rack's
 * own height less its padding and its horizontal scrollbar.
 *
 * The fader goes first and goes furthest: it is the shock absorber, uncapped upwards
 * so a tall window ends up with long faders rather than a band of empty desk, and
 * squeezed all the way to FADER_FLOOR before any block is touched. When even that is not
 * enough the desk starts shedding whole BLOCKS, in SHED_ORDER — inserts, then sends,
 * then EQ — until a strip fits. It never scrolls a strip body: a row half out of
 * sight is a row you cannot read and cannot click, and it goes without saying that it
 * has gone. A hidden block says so on its header switch instead.
 *
 * The rung is a state of the whole rack rather than of one strip. --striph, --bodyh
 * and --faderh are root variables, the measurement takes its MAX across every strip
 * precisely so they all stand level, and a per-strip ladder would put the faders on
 * three different lines. The precedent is the part switches themselves, which hide a
 * block on every strip at once for the same reason.
 */
function sizeStrips(strips) {
  // Called before the first buildRack, from applyFont() and from the fold restore.
  // Nothing to size, and every measurement below would be zero.
  if (!document.querySelector('.strip[data-lane]')) return;
  const wrap = $('rackwrap');
  const root = document.documentElement.style;

  // The fewest blocks that make a strip fit. Fewest, so the desk gives up as little
  // as it has to and hands each block back at the same height it took it away at.
  let shed = 0;
  while (shed < SHED_ORDER.length && strips < stripChromeAt(shed) + FADER_FLOOR) shed++;
  const chrome = stripChromeAt(shed);
  const gone = SHED_ORDER.slice(0, shed);

  for (const id of SHED_ORDER) wrap.classList.toggle(shedClass(id), gone.includes(id));
  markShedParts(gone);

  // Nothing here about the preset editor any more. It used to be a rack item wearing
  // --striph, so the bottom rung squashed a full editor into the height of a bare strip
  // and the ladder had to close it on the way past. It is a window over the desk now:
  // the rack can shed every block it has without the editor noticing.

  // The band between the head and the foot, the same on every strip: the tallest body
  // at this rung. Written here with --faderh and --striph and for the same reason —
  // the three of them are one layout, and a rung that changed how long the fader is
  // without fixing where it starts would put the master's back off its neighbours'
  // line. The rows a strip does not have are this band, not extra fader.
  root.setProperty('--bodyh', `${stripRungAt(shed).body}px`);
  // FADER_FLOOR, and the same number the shed loop above bargains with. They have to
  // be the one number: floored at FADER_MIN while the loop was letting the strip down
  // to chrome + FADER_FLOOR, a strip could be given fourteen pixels more content than
  // height — and a strip body that overflows scrolls, silently, which is the one
  // thing this whole ladder exists to avoid.
  const fader = Math.max(FADER_FLOOR, strips - chrome);
  root.setProperty('--faderh', `${Math.round(fader)}px`);
  // Sized to the rack, never past it: there is no vertical scrollbar on the rack, so
  // a strip that wanted more would simply be cut off. `strips` already accounts for
  // the rack's padding and its horizontal scrollbar, so this fills the space exactly
  // and leaves the padding showing under the last strip.
  root.setProperty('--striph', `${Math.round(Math.min(strips, chrome + fader))}px`);
}

/**
 * Mark the header switches for the blocks the desk is hiding of its own accord.
 *
 * The switch stays ON — it is still what you want, and it comes back the moment there
 * is room — but it is struck through, so "there is no space for this" reads as a
 * different thing from "you turned this off". This is the affordance the whole ladder
 * rests on: the reason it is allowed to hide a block at all is that it says it has.
 */
function markShedParts(gone) {
  for (const b of $('partfilter').querySelectorAll('button[data-part]')) {
    const off = hiddenParts.has(b.dataset.part);
    const shed = !off && gone.includes(b.dataset.part);
    b.classList.toggle('shed', shed);
    if (!shed) continue;
    b.title = `No room for ${STRIP_PARTS.find((p) => p.id === b.dataset.part).what}`
      + ' — the window is too short. Give the mixer more height and it comes back.';
  }
}

/** Size the desk to the window. */
function fitStrips() {
  // The unified workspace lets flex resolve exactly two rooms. The old four-panel
  // planner must not write heights back into them: it was designed to bargain among
  // Arrangement, Notes, Mixer and Effects, three of which are no longer simultaneous
  // regions. The rack still needs its shrink ladder, so size it from the lower room it
  // actually owns and retain the common post-layout housekeeping below.
  if ($('upperwork') && $('lowerwork')) {
    if ($('desk').dataset.lowerView === 'mixer') {
      const available = Math.max(rackFloor() - rackPad(), h($('rackwrap')) - rackPad());
      sizeStrips(Math.floor(available));
    }
    if (keepLanePending) {
      keepLanePending = false;
      keepSelectedLaneVisible();
    }
    scheduleMarkClipped();
    return;
  }
  applyDeskChain();
  applyDesk(planDesk());
  // After every write in the frame, so the one forced reflow it costs is the last one.
  if (keepLanePending) {
    keepLanePending = false;
    keepSelectedLaneVisible();
  }
  // Name clipping is a tooltip convenience, not part of the layout decision. Reading
  // scrollWidth/clientWidth immediately after the flex writes above forces the browser
  // to finish the whole desk reflow in the same task that opened a panel. Defer that
  // read so a fold only does the measurements needed to keep playback alive.
  scheduleMarkClipped();
}

// Panel folds can change several flex constraints at once. Coalesce all of the
// resulting requests into one frame, after the browser has applied the new classes,
// rather than measuring once before flex settles and again afterwards.
let deskFitPending = 0;
let deskFitSettle = false;
function scheduleDeskFit(settle = false) {
  deskFitSettle ||= settle;
  if (deskFitPending) return;
  deskFitPending = requestAnimationFrame(() => {
    deskFitPending = 0;
    fitStrips();
    // Flex assigns the newly freed/claimed panel pixels in this frame, while the
    // rack's strip height is written by fitStrips. A fold therefore gets one bounded
    // follow-up measurement so that the cards fill the new rack height instead of
    // leaving the old card height and a blank band below it.
    if (deskFitSettle) {
      deskFitSettle = false;
      deskFitPending = requestAnimationFrame(() => {
        deskFitPending = 0;
        fitStrips();
      });
    }
  });
}

let clippedMarkPending = 0;
function scheduleMarkClipped() {
  if (clippedMarkPending) return;
  const run = () => {
    clippedMarkPending = 0;
    markClipped();
  };
  if (typeof requestIdleCallback === 'function') {
    clippedMarkPending = requestIdleCallback(run, { timeout: 400 });
  } else {
    clippedMarkPending = setTimeout(run, 0);
  }
}

/**
 * A tooltip only where the name is cut off. "Electro-Fx" fits in a strip and needs no
 * hover; the ones that ellipsis do, and there is no way to read them otherwise. It is
 * a measurement, not a property of the name, so it is re-taken whenever the layout
 * moves — a name that fits at one window width is truncated at another.
 */
function markClipped(root = document) {
  for (const el of root.querySelectorAll('.strip h3, .arrname')) {
    const full = el.dataset.full || el.textContent;
    el.dataset.full = full;
    // Track names have the desk tooltip now; a native title appearing later would
    // compete with it when a long name is truncated.
    el.title = el.dataset.tip ? '' : el.scrollWidth > el.clientWidth + 1 ? full : '';
  }
}

// One resizer between the permanent upper and lower workspaces. Store a ratio rather
// than pixels so the same choice survives moving between monitors or rotating a tablet.
const UPPER_WORK_KEY = 'mash-mixer-upper-work-ratio';
const clampWorkRatio = (value) => Math.max(0.24, Math.min(0.76,
  Number.isFinite(Number(value)) ? Number(value) : 0.44));
const restoredWorkRatio = Number.parseFloat(localStorage.getItem(UPPER_WORK_KEY));
let upperWorkRatio = clampWorkRatio(Number.isFinite(restoredWorkRatio) ? restoredWorkRatio : 0.44);
const writeWorkRatio = (value, remember = true) => {
  upperWorkRatio = clampWorkRatio(value);
  document.documentElement.style.setProperty('--upper-work-height', `${upperWorkRatio * 100}%`);
  $('worksplitter').setAttribute('aria-valuemin', '24');
  $('worksplitter').setAttribute('aria-valuemax', '76');
  $('worksplitter').setAttribute('aria-valuenow', String(Math.round(upperWorkRatio * 100)));
  if (remember) localStorage.setItem(UPPER_WORK_KEY, String(upperWorkRatio));
  keepLanePending = true;
  scheduleDeskFit();
};
writeWorkRatio(upperWorkRatio, false);

(() => {
  const splitter = $('worksplitter');
  let dragging = false;
  const setFromPointer = (event) => {
    const desk = $('desk').getBoundingClientRect();
    if (!(desk.height > 0)) return;
    writeWorkRatio((event.clientY - desk.top) / desk.height, false);
  };
  splitter.addEventListener('pointerdown', (event) => {
    if (event.button != null && event.button !== 0) return;
    dragging = true;
    pianoRoll.setResizeDeferred(true);
    splitter.classList.add('dragging');
    try { splitter.setPointerCapture(event.pointerId); } catch { /* synthetic pointer */ }
    setFromPointer(event);
    event.preventDefault();
  });
  splitter.addEventListener('pointermove', (event) => { if (dragging) setFromPointer(event); });
  const stop = () => {
    if (!dragging) return;
    dragging = false;
    splitter.classList.remove('dragging');
    localStorage.setItem(UPPER_WORK_KEY, String(upperWorkRatio));
    requestAnimationFrame(() => pianoRoll.setResizeDeferred(false));
    scheduleDeskFit(true);
  };
  splitter.addEventListener('pointerup', stop);
  splitter.addEventListener('pointercancel', stop);
  splitter.addEventListener('dblclick', () => writeWorkRatio(0.44));
  splitter.addEventListener('keydown', (event) => {
    if (!['ArrowUp', 'ArrowDown', 'Home'].includes(event.key)) return;
    event.preventDefault();
    if (event.key === 'Home') writeWorkRatio(0.44);
    else writeWorkRatio(upperWorkRatio + (event.key === 'ArrowDown' ? 0.02 : -0.02));
  });
})();

// Every border sizes the panel ABOVE it, so a handler never lives on the element it
// resizes. This is the first one: the top border of Notes, which is the Arrangement's
// bottom edge. Dragging it is a claim about how much Arrangement you want to see;
// double-clicking it withdraws the claim.
(() => {
  const edge = $('notes');
  let from = 0, startH = 0, dragging = false;
  edge.addEventListener('pointerdown', (e) => {
    const r = edge.getBoundingClientRect();
    if (!edge.classList.contains('edge-resizable')
        || e.clientY < r.top - 6 || e.clientY > r.top + 6
        || e.target.closest?.('button')) return;
    dragging = true;
    pianoRoll.setResizeDeferred(true);
    from = e.clientY;
    startH = h($('arrange'));
    edge.classList.add('edge-dragging');
    try { edge.setPointerCapture(e.pointerId); } catch { /* not a real pointer */ }
    e.preventDefault();
  });
  edge.addEventListener('pointermove', (e) => {
    if (!dragging) return;
    const dy = e.clientY - from;
    const asked = startH + dy;
    const notesCollapsed = $('notes').classList.contains('collapsed');
    // Pulled up past the first lane: fold it away. Half a lane is not a thing to
    // leave someone looking at, and the fold is where they were heading anyway. If
    // Notes is the folded side of this border, dragging upward across it opens it —
    // the room the arrangement gives up has to go somewhere you can see.
    if (lanesIn(asked) < 1) {
      setArrangeCollapsed(true);
      userArrH = null;
      if (notesCollapsed && dy < 0) setNotesFolded(false, false);
    } else {
      setArrangeCollapsed(false);
      userArrH = arrangeSnap(asked);
    }
    // Taking lanes away should never take away the one being worked on: the drag is
    // about how much arrangement to show, not about which part of it.
    keepLanePending = true;
    scheduleDeskFit();
  });
  const stop = () => {
    if (!dragging) return;
    dragging = false;
    edge.classList.remove('edge-dragging');
    rememberDeskHeights();
    // Again for the settling fit — the rack can claw a lane back at the end of a drag.
    keepLanePending = true;
    scheduleDeskFit(true);
    requestAnimationFrame(() => pianoRoll.setResizeDeferred(false));
  };
  edge.addEventListener('pointerup', stop);
  edge.addEventListener('pointercancel', stop);
  edge.addEventListener('dblclick', (e) => {
    const r = edge.getBoundingClientRect();
    if (!edge.classList.contains('edge-resizable')
        || e.clientY < r.top - 6 || e.clientY > r.top + 6
        || e.target.closest?.('button')) return;
    userArrH = null;
    rememberDeskHeights();
    keepLanePending = true;
    scheduleDeskFit(true);
    toast('Arrangement back to fitting itself');
  });
})();

// Coalesced to one fit a frame. A drag on the window edge fires this continuously,
// and a fit now measures every strip in the rack to find the tallest chrome — on a
// twenty-channel song that is twenty forced reflows, which is not a thing to do
// several times between two paints.
let fitPending = 0;
// PLAYBACK WINS, AND A HIDDEN RACK IS NOT WORTH MEASURING. M8TRX's panel covers the desk
// edge to edge, so every strip this fit measures while it is open is a forced reflow for
// something nobody can see — and dragging the window edge during M8TRX playback was
// audibly spending the one core the audio graph has on exactly that. The fit is not
// skipped, it is DEFERRED: the debt is remembered and paid the moment the panel closes,
// because the rack still has to be right when it comes back.
let deskFitOwed = false;
addEventListener('resize', () => {
  cancelAnimationFrame(fitPending);
  fitPending = requestAnimationFrame(() => {
    if (rearrangePanelOpen) { deskFitOwed = true; return; }
    scheduleDeskFit(true);
    updateArrangementNoteScale();
  });
});

// The second resize edge is the top border of the Mixer header, which is Notes'
// BOTTOM edge: moving it DOWN gives Notes more room, moving it UP gives Notes less.
// That is the opposite sense from when this handler sat on Notes' own top border, and
// the reason every sign in here is inverted from the Effects handler below — that one
// still grows a panel upward, this one grows it downward. It keeps the current height
// live while dragging and only writes the preference when the gesture ends, so a
// resize cannot fill localStorage with intermediate pixels.
(() => {
  const edge = $('mixhead');
  const panel = $('notes');
  let from = 0, startH = 0, startCollapsed = false, dragging = false;
  edge.addEventListener('pointerdown', (e) => {
    const r = edge.getBoundingClientRect();
    if (!edge.classList.contains('edge-resizable')
        || e.clientY < r.top - 6 || e.clientY > r.top + 6
        || e.target.closest?.('button')) return;
    dragging = true;
    pianoRoll.setResizeDeferred(true);
    from = e.clientY;
    startH = h(panel);
    startCollapsed = panel.classList.contains('collapsed');
    edge.classList.add('edge-dragging');
    try { edge.setPointerCapture(e.pointerId); } catch { /* not a real pointer */ }
    e.preventDefault();
  });
  edge.addEventListener('pointermove', (e) => {
    if (!dragging) return;
    const dy = e.clientY - from;
    // A folded Notes panel starts at its header height, which is below the normal
    // open minimum. A downward drag must open it immediately; keep the gesture's
    // distance above the minimum so the panel grows with the pointer from there.
    const asked = startCollapsed && dy > 0
      ? MIN.notes() + dy
      : startH + dy;
    const mixerCollapsed = $('rackwrap').classList.contains('collapsed');
    // Like Arrangement, Notes folds once its open minimum would be crossed. Dragging
    // back across that same boundary reopens it and restores the roll's content. If
    // Mixer is folded, moving the border UP gives that side room instead — the Mixer
    // is below this border now, so it is an upward drag that hands it space.
    if (startCollapsed && dy > 0) {
      setNotesFolded(false, false);
      userDevH = clampDeviceH(asked);
    } else if (asked <= MIN.notes()) {
      setNotesFolded(true, false);
      userDevH = null;
      if (mixerCollapsed && dy < 0) setMixerFolded(false, false);
    } else {
      setNotesFolded(false, false);
      userDevH = clampDeviceH(asked);
      if (mixerCollapsed && dy < 0) setMixerFolded(false, false);
    }
    scheduleDeskFit();
  });
  const stop = () => {
    if (!dragging) return;
    dragging = false;
    edge.classList.remove('edge-dragging');
    rememberDeskHeights();
    scheduleDeskFit(true);
    requestAnimationFrame(() => pianoRoll.setResizeDeferred(false));
    // The same drag folds and unfolds Notes as it crosses the panel's minimum, and
    // that fold belongs to the song, not to the desk.
    rememberSongLayout();
  };
  edge.addEventListener('pointerup', stop);
  edge.addEventListener('pointercancel', stop);
  edge.addEventListener('dblclick', (e) => {
    const r = edge.getBoundingClientRect();
    if (!edge.classList.contains('edge-resizable')
        || e.clientY < r.top - 6 || e.clientY > r.top + 6
        || e.target.closest?.('button')) return;
    userDevH = null;
    rememberDeskHeights();
    reserveDevices();
    scheduleDeskFit(true);
    toast('Notes panel back to fitting itself');
  });
})();

// Effects uses its top border as the resize edge. Moving it UP grows the shelf and
// takes room from the Mixer; moving it DOWN gives the Mixer room back. A folded shelf
// opens on the first upward movement, just like Notes.
(() => {
  const edge = $('devices');
  let from = 0, startH = 0, startCollapsed = false, dragging = false;
  edge.addEventListener('pointerdown', (e) => {
    const r = edge.getBoundingClientRect();
    if (!edge.classList.contains('edge-resizable')
        || e.clientY < r.top - 6 || e.clientY > r.top + 6
        || e.target.closest?.('button')) return;
    dragging = true;
    pianoRoll.setResizeDeferred(true);
    from = e.clientY;
    startH = h(edge);
    startCollapsed = edge.classList.contains('collapsed');
    edge.classList.add('edge-dragging');
    try { edge.setPointerCapture(e.pointerId); } catch { /* not a real pointer */ }
    e.preventDefault();
  });
  edge.addEventListener('pointermove', (e) => {
    if (!dragging) return;
    const dy = e.clientY - from;
    const asked = startCollapsed && dy < 0
      ? MIN.devices() - dy
      : startH - dy;
    const bodyH = asked - h($('devhead'));
    if (startCollapsed && dy < 0) {
      setDevicesFolded(false, false);
      userFxH = clampEffectsH(bodyH);
    } else if (asked <= MIN.devices()) {
      setDevicesFolded(true, false);
      userFxH = null;
    } else {
      setDevicesFolded(false, false);
      userFxH = clampEffectsH(bodyH);
    }
    scheduleDeskFit();
  });
  const stop = () => {
    if (!dragging) return;
    dragging = false;
    edge.classList.remove('edge-dragging');
    rememberDeskHeights();
    scheduleDeskFit(true);
    requestAnimationFrame(() => pianoRoll.setResizeDeferred(false));
  };
  edge.addEventListener('pointerup', stop);
  edge.addEventListener('pointercancel', stop);
  edge.addEventListener('dblclick', (e) => {
    const r = edge.getBoundingClientRect();
    if (!edge.classList.contains('edge-resizable')
        || e.clientY < r.top - 6 || e.clientY > r.top + 6
        || e.target.closest?.('button')) return;
    userFxH = null;
    rememberDeskHeights();
    reserveDevices();
    scheduleDeskFit(true);
    toast('Effects panel back to fitting itself');
  });
})();

// ---- timeline --------------------------------------------------------------
// One segment per two-bar block of the song form. Sections get distinct hues so a
// verse/lift/bridge shape is readable at a glance, which is what you actually
// navigate by when balancing — "the loud bit" is a block, not a timestamp.
const SECTION_HUES = [168, 210, 275, 32, 130, 340, 190, 60];

// One hue per channel, shared by its strip and its arrangement row, so a colour
// means the same thing in both places. Grouped so the kit reads as a family.
const LANE_HUES = {
  kick: 6, snare: 22, clap: 38, hats: 48, ohats: 54, rim: 30, crash: 14,
  bass: 96, lead: 168, leadHarm: 186, twinkle: 200, chords: 212, organChords: 226,
  organGliss: 250, organSwoop: 260, keyGliss: 272, gliss: 284, electroFx: 296,
  sweeps: 308, vox: 330, shout: 344,
};
// Alternate desk themes use a small, deliberately quiet colour vocabulary. The
// track still owns its colour, but the palette is finite enough that the rack reads
// as a console rather than a rainbow. Keep the default on the original HSL path so
// saved screenshots and the familiar Midnight desk do not move unexpectedly.
const TRACK_PALETTES = {
  amber: ['#c87862', '#c59b5b', '#9ca45e', '#6f9b83', '#6e91b5', '#9179a8', '#b57c91', '#7d9d98'],
  ocean: ['#d17c76', '#c59b62', '#a1aa68', '#6ca9a6', '#75a1c4', '#9a88bd', '#c187a0', '#7ea99e'],
  plum: ['#d1847b', '#c9a36a', '#a0ad70', '#6fa5a1', '#7e9fc5', '#ad91c4', '#c98fa6', '#83aa9d'],
  light: ['#9a5d58', '#9b763f', '#6c7b43', '#3d7773', '#496f98', '#705c8e', '#925a73', '#4c7c72'],
  dawn: ['#aa6758', '#a47c4a', '#78834e', '#4c817b', '#58779a', '#786391', '#9b6278', '#5b847c'],
  dusk: ['#b8756d', '#b18b58', '#8d9860', '#64908c', '#6f8fad', '#927eab', '#ad778c', '#789991'],
  // Oscar's are panel legends rather than lights: one lightness, barely any chroma,
  // so a rack of them reads as printing on the bone plate. Any more saturation and
  // the one thing the theme is for — a machine with no colour on it — is gone.
  oscar: ['#b8a89a', '#b3a67c', '#a0a687', '#87a09b', '#8c9cae', '#a294a8', '#b39a9c', '#94a397'],
};
// A layer keeps its source's hue, nudged. It IS that part — a colour that said
// otherwise would break the one thing the colours are for — but two rows the same
// shade with the same name on them is a pair you cannot tell apart at a glance.
const laneHue = (key) => {
  if (LANE_HUES[key] != null) return LANE_HUES[key];
  const base = baseLane(key);
  if (base === key || LANE_HUES[base] == null) return 200;
  return (LANE_HUES[base] + 7 * (parseInt(key.slice(base.length), 10) - 1)) % 360;
};
/* Whether the desk's own surface is light. Measured from the theme rather than listed,
 * so a new theme never has to be added to a list of light ones to look right — read
 * once when the theme changes, because the alternative is a getComputedStyle per bar
 * and there are a few thousand bars. */
let panelIsLight = false;
const measureSurface = () => {
  const hex = getComputedStyle(document.documentElement).getPropertyValue('--panel').trim();
  const m = /^#([0-9a-f]{6})$/i.exec(hex);
  if (!m) return;
  const n = parseInt(m[1], 16);
  // Rec. 601 luma: good enough to answer "is this paper or slate", which is all
  // anything downstream asks it.
  const luma = (0.299 * ((n >> 16) & 255) + 0.587 * ((n >> 8) & 255) + 0.114 * (n & 255)) / 255;
  panelIsLight = luma > 0.5;
};
const themeHueColour = (hue) => {
  const palette = TRACK_PALETTES[document.documentElement.dataset.mixerTheme];
  if (!palette) return null;
  return palette[Math.floor((hue / 360) * palette.length) % palette.length];
};
const themeTrackColour = (key) => themeHueColour(laneHue(key));
/* The send returns are coloured by hue rather than by lane — they are not lanes — but
 * they have to go through the same two doors as everything else, or they keep their
 * raw teal and purple in a theme that has neither. */
const hueColour = (hue, l = 55) => themeHueColour(hue) || `hsl(${hue} 62% ${l}%)`;
const hueTint = (hue) => `color-mix(in srgb, ${hueColour(hue)} 24%, transparent)`;
const laneColour = (key, l = 55) => hueColour(laneHue(key), l);
/** The same hue, quiet enough to sit behind a name without shouting over it.
 *
 * Mixed toward the surface rather than darkened to a fixed lightness. The old path
 * was `hsl(h 32% 12%)` — Midnight's own background written into the colour — which
 * is right on slate and puts a row of black bars across a paper desk. Both paths are
 * one formula now, so a theme with no palette of its own tints correctly whatever
 * colour its panel is. */
const laneTint = (key) => `color-mix(in srgb, ${laneColour(key)} 24%, transparent)`;
const arrangementBarColour = (key, shade = 56) => {
  const themed = themeTrackColour(key);
  if (themed) return themed;
  // This is the original Solid fill: a strong lane colour, never a panel wash. Clamp
  // only protects custom density callers; the shared active field uses the full 56%
  // solid shade below.
  return `hsl(${laneHue(key)} 58% ${Math.min(62, Math.max(44, shade)).toFixed(0)}%)`;
};
/** A lane's active bar is the original Solid field; the selected note language supplies the
 * darker marks on top. Keeping this in one helper also makes recorded notes match the
 * bars that were drawn from the arrangement. */
const arrangementBarField = (key) => arrangementBarColour(key, 56);

/**
 * How long the song is, and what it is made of — in BARS.
 *
 * Counted off the bar plan rather than off `order.length * 2`, because an arranged
 * song no longer has two bars per order entry: an entry can be one bar, and the plan
 * is the only thing that knows how many there are. `order` is still handed back for
 * the timeline's section colours, and `bars` is what everything measuring the song
 * should use.
 */
function songShape() {
  const bank = viewBank();
  const order = bank.order || (bank.sections ? bank.sections.map((_, i) => i) : [0]);
  const bars = barPlan(bank, 1);
  const spb = (60 / deskTempo()) / 4;   // the tempo this song plays at, dragged or written
  const totalSteps = bars.length * 16;
  return { order, bars, spb, totalSteps, loopSecs: totalSteps * spb };
}

const rearrangeActive = () => !!rearrangeRecipe;

function rearrangeSourceSteps() { return songShape().totalSteps; }

// The rich source profile is a whole-bank walk — every lane, every sixteenth — so it
// is built once and held against the bank it describes. `viewBank()` is memoised and
// hands back a new object whenever the mix, arrangement or song changes, which makes
// object identity the whole invalidation: an edited draft is a miss, not a stale
// answer.
//
// PLAYBACK WINS. The walk happens when the Rearrange panel opens, which is a parked
// moment, and Generate then uses whatever is cached. Generating during playback never
// starts one: on a miss it falls back to the cheap per-bar density the generator has
// always accepted, rather than putting a full song walk on the main thread underneath
// an audio graph that is already the thing this desk struggles to keep fed.
let rearrangeProfileCache = null;

function rearrangeSourceProfile({ build = false } = {}) {
  const bank = viewBank();
  // No bank yet — the desk is still booting. Written as two explicit checks, not
  // `cache?.bank === bank`: with a null cache AND an undefined bank that comparison
  // is undefined === undefined, which is TRUE, and the "hit" then reads .profile off
  // the null it just proved was there.
  if (!bank) return null;
  if (rearrangeProfileCache && rearrangeProfileCache.bank === bank) {
    return rearrangeProfileCache.profile;
  }
  // A stale cache is no answer at all — the song it described is not the song being
  // cut up any more.
  if (!build) return null;
  const profile = buildRearrangeProfile(bank);
  rearrangeProfileCache = { bank, profile };
  return profile;
}

/** The old per-bar density array, still the fallback when no rich profile is ready. */
function rearrangeDensityProfile() {
  const bars = songShape().bars.length;
  const rows = laneActivity(viewBank(), 1, 1);
  const profile = new Array(bars).fill(0);
  for (const row of rows) {
    for (let i = 0; i < bars; i++) profile[i] += Number(row.density?.[i]) || 0;
  }
  return profile.map((value) => value / Math.max(1, rows.length));
}

/**
 * What Generate should score against: the rich profile, built on the spot when the
 * transport is parked and it is missing — a parked desk has main thread to spare, and
 * "press Generate, get the musical version" must not depend on which order the panel
 * was opened and the song was chosen in. Only mid-playback does it settle for the
 * cheap per-bar density, because playback wins.
 */
function rearrangeGenerationProfile() {
  return rearrangeSourceProfile({ build: !playing }) || rearrangeDensityProfile();
}

function rearrangeStepLabel(step) {
  const n = Math.max(0, Math.floor(Number(step) || 0));
  return `bar ${Math.floor(n / 16) + 1}, beat ${Math.floor((n % 16) / 4) + 1}, 16th ${(n % 4) + 1}`;
}

// Compact bar:beat.sixteenth notation keeps the visible rows musical without
// throwing away the expanded wording used by hover text and toasts.
function rearrangeOutputLabel(step) {
  const n = Math.max(0, Math.floor(Number(step) || 0));
  return `${Math.floor(n / 16) + 1}:${String(Math.floor((n % 16) / 4) + 1)}.${(n % 4) + 1}`;
}

function rearrangeTransposeLabel(value) {
  const n = Number(value) || 0;
  if (!n) return '';
  const interval = ({
    '-7': 'perfect fifth', '-5': 'perfect fourth', '-2': 'whole tone',
    '2': 'whole tone', '5': 'perfect fourth', '7': 'perfect fifth',
    '-12': 'octave', '12': 'octave',
  })[String(n)];
  return ` · transpose ${n > 0 ? '+' : ''}${n}${interval ? ` (${interval})` : ''}`;
}

// One name per drum mode, used by the button, the status line and every toast that
// mentions it. The three are genuinely different treatments and the labels have to say
// which is which — "original" and "song" both describe the song's own drums, so neither
// word can be left to carry the distinction on its own.
const REARRANGE_DRUM_LABELS = {
  song: 'Song groove',
  original: 'Chopped drums',
  basic4: 'Steady 4/4',
  halftime: 'Half-time',
  break: 'Breakbeat',
  boombap: 'Boom bap',
  garage: 'Two-step',
  disco: 'Disco',
  house: 'House',
  deephouse: 'Deep house',
  techno: 'Techno',
};
const REARRANGE_DRUM_TIPS = {
  song: 'The song’s own drum patterns, played straight underneath the rearranged parts',
  original: 'The drums are chopped with everything else, following each slice’s source',
  basic4: 'A steady four-on-the-floor built from the song’s existing kit sounds',
  halftime: 'The backbeat at bar centre: half the speed at the same tempo',
  break: 'An amen-shaped break — kick off the second beat, busy hats',
  boombap: 'Kick on one and the and-of-three, snare hard on two and four',
  garage: 'Two-step: the second backbeat displaced and the kick skipping',
  disco: 'Four on the floor with a live kit: snare and clap together, sixteenth hats, open hat on every off-beat',
  house: 'Four on the floor, the clap carrying the backbeat alone over eighth hats',
  deephouse: 'Sparser house: the clap answers only the fourth beat, hats stay off the beat',
  techno: 'Kick-dominant and machine-like: no backbeat on two, driving off-beat sixteenths',
};

function rearrangeDrumLabel(mode) {
  return REARRANGE_DRUM_LABELS[mode] || REARRANGE_DRUM_LABELS.original;
}

/**
 * The drum lanes this song has, in desk order — the kit, as it was assembled.
 *
 * Guarded, because the keyboard can now be built before there is a song to build it
 * from: the preset library switches it on as it opens, which can land in the moment
 * between the page starting and a track being resolved. `viewBank` has nothing to
 * return then, and `deskLanes` reads `.sections` off it without asking.
 */
function songKitLanes() {
  const bank = viewBank();
  if (!bank) return [];
  return deskLanes(bank, 1).filter((l) => PERCUSSION_LANES.includes(baseLane(l.key)));
}

/**
 * THE ROW THAT CANNOT SOUND, said out loud, and the one thing that helps.
 *
 * On a song with no percussion channels EVERY setting on the drums menu is a dead letter,
 * and it took two passes to see that. The generated kits write their hits into role-keyed
 * lanes — kick, snare, clap, hats — and have none to write to. Chopped drums and Song groove
 * replay what the song wrote, and it wrote nothing. Whichever is chosen, the menu takes it,
 * the status line reports it, and the bar goes by empty: nothing to hear, and so nothing to
 * diagnose by ear. You would go looking at Drive, at the recipe, at the mix, and never at the
 * fact that the song has no drums in it.
 *
 * So the offer is up whenever the song has none, not only for the kits it can fix. It does
 * not pretend to fix all of it — a kit is SOUNDS, and the two that replay the song are still
 * empty afterwards for want of steps, which is why they are closed in the menu rather than
 * left to fail quietly. What it fixes is the half a kit CAN fix, and the row's presence is
 * what says the song is the problem.
 *
 * `mode` is the RESOLVED kit, so the tooltip names what is actually selected — Auto included,
 * which reads as whatever Drive resolved it to rather than as "Auto".
 */
function syncRearrangeKitOffer(mode, noDrums = !songKitLanes().length) {
  const row = $('redrumskit');
  const select = $('redrumkit');
  if (!row || !select) return;
  const wanted = !!rearrangeRecipe && noDrums;
  row.hidden = !wanted;
  if (!wanted) return;
  if (!select.options.length) {
    // The resting option states the PROBLEM, because the row appearing is the only other
    // thing that says there is one. Disabled: it is a readout of what the song has, and
    // "none" is not a kit anybody can choose their way back to.
    const none = document.createElement('option');
    none.value = '';
    none.disabled = true;
    none.textContent = 'None in this song';
    select.append(none);
    // KITS verbatim — same names, same order as the pattern editor's Kit menu, so the two
    // lists cannot come to disagree about what a kit is called or which ones exist.
    for (const [label] of KITS) {
      const option = document.createElement('option');
      option.value = label;
      option.textContent = label;
      select.append(option);
    }
  }
  // Always back to the readout. Picking a kit gives the song drums, which takes this row off
  // screen entirely — so a value left selected would only ever be seen on the way out, and
  // would be showing on the next drumless song as though it were already applied.
  select.value = '';
  // The sentence the row used to carry, kept where it costs no height. Both halves of it,
  // because "no drums" alone reads as a complaint about the mix rather than about the
  // setting standing next to it. And the honest limit at the end: a kit is sounds, so it
  // wakes the generated patterns and leaves the two that replay the song still waiting for
  // something to replay.
  select.title = `${rearrangeDrumLabel(mode)} has nothing to play — this song has no drum`
    + ' channels. Pick a kit and its sounds are added, which is what the generated patterns'
    + ' need; Chopped drums and Song groove replay what the song wrote, so they stay silent'
    + ' until something is programmed. Sounds only — no step is touched, and it is one undo.';
}

function syncRearrangeDrumControl() {
  const select = $('redrums');
  if (!select) return;
  const mode = rearrangementDrumMode(rearrangeRecipe);
  // A cycling button could name the mode OR offer the alternatives, never both, and with
  // seven of them the cycle had become a way of hiding six behind one.
  if (!select.options.length) {
    const auto = document.createElement('option');
    auto.value = 'auto';
    auto.textContent = 'Drums: Auto · Drive';
    auto.title = 'Let the Drive dial pick the kit at the next Go: the song\'s own groove at the bottom, four-to-the-floor at the top';
    select.append(auto);
    for (const name of REARRANGE_DRUM_MODES) {
      const option = document.createElement('option');
      option.value = name;
      option.textContent = `Drums: ${rearrangeDrumLabel(name)}`;
      option.title = REARRANGE_DRUM_TIPS[name] || '';
      select.append(option);
    }
  }
  select.disabled = !rearrangeRecipe && rearrangeDrumsChoice !== 'auto';
  // THE TWO THAT NOTHING CAN RESCUE, said in the list rather than found out by ear.
  //
  // Chopped drums and Song groove both REPLAY what the song wrote — one cut with the collage,
  // one straight underneath it — so on a song that wrote no drums at all they have no source
  // and produce nothing. Offered as live choices they are two menu entries that quietly do
  // nothing, which is the same silent failure the generated kits had, and the fix that works
  // for those does not work for these: a kit is SOUNDS, and adding one leaves these two with
  // channels but still no steps to replay. So they are closed rather than offered, and they
  // say which of the two problems they have.
  //
  // Derived from the generated list rather than written out again: the complement is what
  // "replays the song's own drums" MEANS here, and a second hand-kept list of two would be a
  // place for the next kit added to go missing.
  const noDrums = !songKitLanes().length;
  for (const option of select.options) {
    if (option.value === 'auto' || REARRANGE_GENERATED_DRUMS.includes(option.value)) continue;
    option.disabled = noDrums;
    option.textContent = `Drums: ${rearrangeDrumLabel(option.value)}${noDrums ? ' — none in song' : ''}`;
  }
  // Auto is a GENERATION setting, so it stays selected between Generates and names what
  // it resolved to; every other choice is applied to the recipe now and reads off it.
  if (rearrangeDrumsChoice === 'auto') {
    select.value = 'auto';
    const kit = driveDrumKit(rearrangeDrive());
    select.options[0].textContent = rearrangeRecipe
      ? `Drums: Auto → ${rearrangeDrumLabel(mode)}`
      : `Drums: Auto → ${rearrangeDrumLabel(kit)}`;
    select.title = `Auto follows Drive — the next Go builds ${rearrangeDrumLabel(kit)}`;
    // Auto itself stays open even when Drive is sitting on Song groove: it is a setting for
    // the NEXT Go and the dial can move before then, so closing it would be the panel
    // refusing a choice on the strength of a number nobody has committed to yet.
    // What is PLAYING, not what the dial will build next: the recipe on the timeline is the
    // thing going silent, and the Drive dial's next answer is not yet anyone's problem.
    syncRearrangeKitOffer(mode, noDrums);
    return;
  }
  select.options[0].textContent = 'Drums: Auto · Drive';
  select.value = mode;
  select.title = REARRANGE_DRUM_TIPS[mode] || REARRANGE_DRUM_TIPS.original;
  syncRearrangeKitOffer(mode, noDrums);
}

function syncRearrangeButton() {
  const button = $('rearrangebtn');
  if (!button) return;
  button.classList.toggle('on', rearrangeActive());
  button.setAttribute('aria-pressed', rearrangeActive() ? 'true' : 'false');
  button.textContent = rearrangeActive() ? 'M8TRX · ON' : 'M8TRX';
  button.title = rearrangeActive()
    ? 'M8TRX is active — open its timeline or return to the normal song'
    : 'Create a musical M8TRX arrangement from this song';
  syncBounceScope();
}

/**
 * BOUNCE SAYS WHAT IT WILL BOUNCE, while a recipe is live.
 *
 * A bounce is "what I am hearing, written down" — and with M8TRX armed that is exactly
 * what it is not: the render walks the SONG's own bank, mix and arrangement, and the word
 * "rearrange" does not appear anywhere in that path. That is the product boundary working
 * as designed (M8TRX never reaches the WAV), but it made Bounce the one control on the desk
 * that quietly means something else in M8TRX mode. Everything else the desk lends M8TRX
 * relabels itself to say so — Undo becomes Undo M8TRX, the loop button becomes Recipe Once,
 * the ? becomes M8TRX's help — so this does too, rather than handing back a file of the
 * plain song and leaving you to diagnose it by ear.
 *
 * Left alone mid-render: the button's text is the progress readout while a bounce runs, and
 * `renderwav.onclick` restores whatever label it captured at the click.
 */
function syncBounceScope() {
  const button = $('renderwav');
  if (!button || rendering) return;
  const m8 = rearrangeActive();
  button.textContent = m8 ? 'Bounce song' : 'Bounce';
  button.title = m8
    ? 'Bounce THE SONG to a WAV — the mix and arrangement as they stand. M8TRX is a performance layer and never reaches the file, so the recipe on the timeline is not in this bounce. Asks how many passes first.'
    : 'Bounce this song to a WAV, offline through the real engine, with the mix as it stands — asks how many passes first';
  // Audition renders through the same path, so it carries the same caveat. Its label already
  // names what it does rather than what it renders, so only the tooltip needs to change.
  const audition = $('auditionwav');
  if (audition) {
    audition.title = m8
      ? 'Bounce THE SONG and open it in tools/audition — a real AU plugin over it, its own GUI, previewed before you keep it. The M8TRX recipe is not in this bounce.'
      : 'Bounce this song and open it in tools/audition — a real AU plugin over it, its own GUI, previewed before you keep it';
  }
}

// Style is a hard gate on what the generator may emit, so the control is a compact
// choice rather than a point on a scale. Held here rather than read back off the DOM
// so the panel and the generator cannot disagree about which one is selected.
/**
 * Style is now an OVERRIDE, and 'auto' is the default.
 *
 * Grain owns how finely the song is cut. Style survives in Advanced for the one thing a
 * dial cannot do — promise — so naming one is an exact claim about cut sizes rather than
 * a leaning. Left on Auto it does not participate at all, which is what stops the panel
 * carrying two controls that answer the same question and disagree.
 */
let rearrangeStyleChoice = 'auto';
const REARRANGE_STYLE_OPTIONS = Object.freeze(['auto', ...REARRANGE_STYLE_CHOICES]);

function rearrangeStyle() {
  return REARRANGE_STYLE_OPTIONS.includes(rearrangeStyleChoice)
    ? rearrangeStyleChoice : 'auto';
}

/**
 * The macro shape the next Go builds: how many parts, how long, and which return.
 *
 * Song is the historical ladder and the default, so an arrangement built before form
 * grammars existed is still exactly what this produces. The others are the shapes the
 * imported catalogue actually shows — where only 29% of parts are four bars long.
 */
let rearrangeFormChoice = REARRANGE_FORM_DEFAULT;
const REARRANGE_FORM_OPTIONS = Object.freeze([...REARRANGE_FORM_NAMES, REARRANGE_FORM_RANDOM]);
function rearrangeForm() {
  return REARRANGE_FORM_OPTIONS.includes(rearrangeFormChoice)
    ? rearrangeFormChoice : REARRANGE_FORM_DEFAULT;
}
function setRearrangeForm(form) {
  if (!REARRANGE_FORM_OPTIONS.includes(form)) return;
  rearrangeFormChoice = form;
  syncRearrangeForm();
}
function syncRearrangeForm() {
  const select = $('reform');
  if (!select) return;
  select.value = rearrangeForm();
  // Back in Advanced, so the popup's counter has to see it — and that call already
  // refreshes the seed-hold state, which a generator input must do.
  syncRearrangeAdvanced();
}

/** How finely the song is cut, 0..1. The dial that replaced Style in the open. */
let rearrangeGrainValue = REARRANGE_GRAIN_DEFAULT;
function rearrangeGrain() {
  const value = Number(rearrangeGrainValue);
  return Number.isFinite(value) ? Math.max(0, Math.min(1, value)) : REARRANGE_GRAIN_DEFAULT;
}
function setRearrangeGrain(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return;
  rearrangeGrainValue = Math.max(0, Math.min(1, number));
  syncRearrangeGrain();
}
function syncRearrangeGrain() {
  const dial = $('regrain');
  const output = $('regrainvalue');
  if (!dial || !output) return;
  const label = grainLabel(rearrangeGrain());
  dial.value = String(Math.round(rearrangeGrain() * 100));
  output.value = label;
  output.textContent = label;
  // Greyed while a named style is in force: the dial is genuinely not deciding anything
  // then, and a live-looking control that changes nothing is worse than a dead one.
  const overridden = rearrangeStyle() !== 'auto';
  dial.disabled = overridden;
  dial.title = overridden
    ? `Style is set to ${REARRANGE_STYLE_WORDS[rearrangeStyle()]} in Advanced, which decides`
      + ' the cut sizes outright. Set Style back to Auto to use this dial.'
    : 'How finely the song is cut. Phrases takes whole one to four-bar phrases; Groove works'
      + ' in bars and half-bars; Shards works in beats. At either end it is a hard limit,'
      + ' not a leaning.';
  syncRearrangeSeedHold();
}

function setRearrangeStyle(style) {
  if (!REARRANGE_STYLE_OPTIONS.includes(style)) return;
  rearrangeStyleChoice = style;
  syncRearrangeStyle();
  // The dial greys or un-greys with it; the form is independent and is left alone.
  syncRearrangeGrain();
}

const REARRANGE_STYLE_WORDS = {
  auto: 'Auto', phrase: 'Phrase', groove: 'Groove', chop: 'Chop', mix: 'Mix',
};

function syncRearrangeStyle() {
  const select = $('restyle');
  if (!select) return;
  select.value = rearrangeStyle();
  syncRearrangeSeedHold();
}

/**
 * ---- THE FOUR DIALS --------------------------------------------------------------
 *
 * One table, because these controls are the same control four times: a 0–100 slider
 * whose reading is a WORD. Five bands each, so the word changes often enough to feel
 * like it is tracking the hand but not so often that it flickers while dragging.
 *
 * The bands are stated in desk units (0–100) and the reader divides by a hundred; the
 * library's defaults and these markup values are the same numbers on purpose, so a
 * fresh panel and a bare `generateRearrangement` call agree without either quoting the
 * other.
 */
const REARRANGE_DIALS = Object.freeze({
  mood: {
    id: 'remood', label: 'Mood',
    words: ['Noir', 'Brooding', 'Bittersweet', 'Golden', 'Euphoric'],
    tips: [
      'Noir: re-read in the relative minor, walking the darkest loop it has',
      'Brooding: minor, and the chords move through more of the loop',
      'Bittersweet: the key the song is actually in, walked as pop does',
      'Golden: major, reaching for the brighter changes',
      'Euphoric: the relative major, lifting through the festival cadence',
    ],
  },
  hypnosis: {
    id: 'rehypnosis', label: 'Hypnosis',
    words: ['Scatter', 'Restless', 'Woven', 'Circling', 'Trance'],
    tips: [
      'Scatter: through-composed — it keeps moving and rarely looks back',
      'Restless: new material more often than returning material',
      'Woven: motifs come back with fresh material between them',
      'Circling: a few pieces of the song, going round',
      'Trance: locked — each part is one figure and its answer, repeating',
    ],
  },
  chaos: {
    id: 'rechaos', label: 'Chaos',
    words: ['Tame', 'Playful', 'Frisky', 'Unruly', 'Feral'],
    tips: [
      'Tame: the best-scoring slice every time, and no lifts',
      'Playful: mostly safe, occasionally not',
      'Frisky: reaches past the obvious answer, and sometimes takes a lift',
      'Unruly: well down the ranking, with lifts and wilder fills',
      'Feral: whatever it finds down there — it will surprise you both ways',
    ],
  },
  drive: {
    id: 'redrive', label: 'Drive',
    words: ['Ambient', 'Cruise', 'Rolling', 'Charged', 'Peak-time'],
    tips: [
      'Ambient: sparse, low-energy material and almost no fills',
      'Cruise: relaxed, with the chords holding home',
      'Rolling: the song\'s own energy, fills about one part in three',
      'Charged: denser material, more fills, chords moving every two bars',
      'Peak-time: highest-energy material, fills everywhere, a chord a bar',
    ],
  },
});

/** The band a 0–100 reading falls in: five words across the dial. */
const rearrangeDialBand = (value) => Math.min(4, Math.floor(Math.max(0, value) / 20));

function rearrangeDial(name) {
  const spec = REARRANGE_DIALS[name];
  const value = Number($(spec.id)?.value);
  return Number.isFinite(value)
    ? Math.max(0, Math.min(100, value)) / 100
    : REARRANGE_CREATIVE_DEFAULTS[name];
}

const rearrangeMood = () => rearrangeDial('mood');
const rearrangeHypnosis = () => rearrangeDial('hypnosis');
const rearrangeChaos = () => rearrangeDial('chaos');
const rearrangeDrive = () => rearrangeDial('drive');

function syncRearrangeDial(name) {
  const spec = REARRANGE_DIALS[name];
  const control = $(spec.id);
  const output = $(`${spec.id}value`);
  if (!control || !output) return;
  const value = Math.max(0, Math.min(100, Number(control.value) || 0));
  const band = rearrangeDialBand(value);
  output.value = spec.words[band];
  output.textContent = spec.words[band];
  control.title = spec.tips[band];
}

const syncRearrangeDials = () => {
  for (const name of Object.keys(REARRANGE_DIALS)) syncRearrangeDial(name);
};

function rearrangeOutputSteps() {
  const source = rearrangeSourceSteps();
  const factor = Number($('relength')?.value);
  if (!Number.isFinite(factor) || factor <= 0) return source;
  return Math.max(16, Math.round((source * factor) / 4) * 4);
}

/**
 * Whether the recipe walks chord loops at all. Mood owns WHICH loop and Drive owns how
 * fast it moves, so there is no palette picker any more; the one remaining question is
 * whether the song has a key to walk in, and that is the Key control's to answer.
 * Key = None is the chromatic escape — it turns the loops off and hands the song back
 * to the Transpose dial, which is otherwise dead on any song with a detectable key.
 */
function rearrangeChordLoop() {
  return $('rekey')?.value === 'none' ? 'off' : 'auto';
}

function rearrangeFill() {
  const value = $('refill')?.value;
  return value === 'none' || REARRANGE_FILL_NAMES.includes(value) ? value : REARRANGE_FILL_DEFAULT;
}

/**
 * THE CHORD A SLICE SOUNDS, as an absolute degree of the recipe's key — 0 for the tonic,
 * and null for a slice no walk has been over.
 *
 * `harmony` is the MOVE, so it names the chord only while the material is assumed to open on
 * the tonic. A walk that could read the source does not assume that: it works out where the
 * material already sits and moves it the rest of the way, then writes down what it landed
 * on. That reading is the answer wherever it is there, and the move is the answer wherever
 * it is not — a chord set by hand on one slice is a move, with nothing read about anything.
 */
function rearrangeSoundingChord(op) {
  if (!op) return 0;
  return op.chord == null ? (Number(op.harmony) || 0) : (Number(op.chord) || 0);
}

/** The chord a slice plays as, for the playback status: ' · chord VI'. */
function rearrangeHarmonyLabel(op) {
  const degrees = rearrangeSoundingChord(op);
  if (!degrees) return '';
  return ` · chord ${harmonyNumeral(degrees, rearrangeRecipe?.key?.minor !== false)}`;
}

const KEY_NAMES = ['C', 'C♯', 'D', 'E♭', 'E', 'F', 'F♯', 'G', 'A♭', 'A', 'B♭', 'B'];

const rearrangeKeyName = (key) => key
  ? `${KEY_NAMES[key.tonic] || '?'} ${key.minor ? 'minor' : 'major'}` : '';

/**
 * The key the chord loops would walk in, shown BESIDE the control before Generate is
 * ever pressed — read off the same analysis the generator will use, so what the panel
 * says and what Generate does cannot disagree. Building it here when the transport is
 * parked is what makes the readout self-healing: opening the panel mid-playback or
 * switching songs under it shows the key the moment there is a parked sync to build
 * in, instead of "no analysis yet" until someone reopens the panel in the right order.
 *
 * An unclear key is shown as a GUESS and still used — an ambiguous reading is nearly
 * always the relative major/minor pair, which share a scale — and the picker beside
 * it is the correction when the guess is wrong.
 */
/**
 * The key the panel is actually showing: the one you named, or the detected one as Mood
 * re-reads it. The same resolution the readout prints, so what the readout says and what a
 * walk walks in cannot disagree.
 *
 * This exists because `recipe.key` is NOT a reliable answer. The generator only writes a key
 * onto a recipe when it happened to walk something itself — so a recipe generated with no
 * walks in it carries no key at all, and every attempt to turn a walk on afterwards was
 * refused with "Choose a key before turning on a chord walk". Picking a key did not help
 * either: the Key select is a next-Go setting and never reached the recipe already on the
 * timeline. There was no way out of that from inside the panel.
 */
function rearrangeEffectiveKey() {
  if (rearrangeChordLoop() === 'off') return null;
  const manual = rearrangeKeyChoice();
  if (manual) return manual;
  const profile = rearrangeSourceProfile({ build: !playing });
  const detected = profile ? detectKey(profile) : null;
  return detected
    ? moodWalkKey({ tonic: detected.tonic, minor: detected.minor }, rearrangeMood())
    : null;
}

function syncRearrangeKeyReadout() {
  const out = $('rechordskey');
  if (!out) return;
  syncRearrangeKeyOptions();
  if (rearrangeChordLoop() === 'off') {
    out.value = 'chord loops off';
    out.textContent = 'chord loops off';
    out.title = 'No key, so no chord walk: every part keeps its written harmony and the chromatic Transpose dial is live';
    syncRearrangeChordLoopControl();
    return;
  }
  const manual = rearrangeKeyChoice();
  const profile = rearrangeSourceProfile({ build: !playing });
  const detected = profile ? detectKey(profile) : null;
  const clear = detected && detected.confidence >= 0.02;
  // MOOD IS SHOWN, NOT HIDDEN. The dark and euphoric ends re-read a detected key in its
  // relative minor/major, so the readout has to name the key Generate will ACTUALLY walk
  // in — otherwise the panel says A minor and the song comes out in C. A key named by
  // hand is never re-read, and reads the same here as it will play.
  const walked = manual || (detected
    ? moodWalkKey({ tonic: detected.tonic, minor: detected.minor }, rearrangeMood()) : null);
  const moved = !manual && detected && walked
    && (walked.tonic !== detected.tonic || walked.minor !== detected.minor);
  const label = walked
    ? `${rearrangeKeyName(walked)}${manual || clear ? '' : ' ?'}${moved ? ' · Mood' : ''}`
    : 'no analysis yet';
  out.value = label;
  out.textContent = label;
  out.title = manual
    ? `Chord loops walk in ${label} because you said so; set the picker back to Detected to trust the analysis`
    : moved
      ? `The song reads as ${rearrangeKeyName(detected)}; Mood re-reads it in its relative ${walked.minor ? 'minor' : 'major'} — the same notes with a different home. Centre the Mood dial to keep the key as analysed`
      : detected
        ? clear
          ? `The song reads as ${rearrangeKeyName(detected)}; chord loops walk its scale degrees`
          : `Best guess — the song does not settle clearly. Usually the relative pair, which walks the same notes; pick a key yourself to overrule it`
        : playing
          ? 'Pause to analyse the song — the walk is skipped while music is playing'
          : 'The song has no pitched notes to read a key from';
  syncRearrangeChordLoopControl();
}

/** Fill the key picker once: Detected, None, then all twenty-four keys. */
function syncRearrangeKeyOptions() {
  const select = $('rekey');
  if (!select || select.options.length > 1) return;
  const none = document.createElement('option');
  none.value = 'none';
  none.textContent = 'None · chromatic';
  select.append(none);
  for (const minor of [true, false]) {
    for (let tonic = 0; tonic < 12; tonic++) {
      const option = document.createElement('option');
      option.value = `${tonic}${minor ? 'm' : 'M'}`;
      option.textContent = rearrangeKeyName({ tonic, minor });
      select.append(option);
    }
  }
}

/** The manually chosen key, or null when the picker trusts the analysis. */
function rearrangeKeyChoice() {
  const value = $('rekey')?.value;
  const match = /^(\d{1,2})([mM])$/.exec(value || '');
  if (!match) return null;
  const tonic = Number(match[1]);
  return tonic >= 0 && tonic <= 11 ? { tonic, minor: match[2] === 'm' } : null;
}

/**
 * One pitch system per recipe: while a chord loop is on, the chromatic Transpose dial
 * does nothing, and a control that does nothing must say so rather than sit there
 * looking adjustable. Setting the Key picker to None hands the dial back.
 */
function syncRearrangeChordLoopControl() {
  const dial = $('retranspose');
  if (!dial) return;
  const walking = rearrangeChordLoop() !== 'off';
  dial.disabled = walking;
  dial.title = walking
    ? 'Mood owns the pitch while the song has a key — set Key to None · chromatic to use the shared lift instead'
    : 'Dial the amount of shared chromatic lift — every note the same distance';
}

function rearrangeTransposeAmount() {
  const value = Number($('retranspose')?.value);
  return Number.isFinite(value)
    ? Math.max(0, Math.min(100, value)) / 100
    : REARRANGE_TRANSPOSE_DEFAULT;
}

/**
 * The Advanced button states what is behind it.
 *
 * Key, Fill new sections and Transpose are reached for least and were half the width of the
 * Generate band, so they sit in a popup. A popup, though, is a place a setting can hide: the
 * next Go would read a key you named an hour ago with nothing on screen to say so. So the
 * button counts whatever is off its default — `Advanced · 2 set` — and lights while it is
 * non-empty. The desk's rule against hidden preset parameters bites hardest on the controls
 * that have been put behind a door.
 */
function syncRearrangeAdvanced() {
  const button = $('readvancedbtn');
  if (!button) return;
  const set = [
    ($('rekey')?.value ?? 'auto') !== 'auto',
    ($('refill')?.value ?? REARRANGE_FILL_DEFAULT) !== REARRANGE_FILL_DEFAULT,
    Number($('retranspose')?.value || 0) > 0,
    rearrangeForm() !== REARRANGE_FORM_DEFAULT,
    rearrangeStyle() !== 'auto',
  ].filter(Boolean).length;
  button.textContent = set ? `Advanced · ${set} set ⌄` : 'Advanced ⌄';
  button.classList.toggle('set', set > 0);
  // These four are generator inputs too, so changing one gives Reshape something to do.
  syncRearrangeSeedHold();
}

function syncRearrangeTranspose() {
  const control = $('retranspose');
  const output = $('retransposevalue');
  if (!control || !output) return;
  const value = Math.max(0, Math.min(100, Number(control.value) || 0));
  const label = value <= 0 ? 'Off'
    : value < 35 ? '±2'
      : value < 70 ? '±2/5'
        : '±2/5/7';
  output.value = label;
  output.textContent = label;
  // A disabled dial keeps the chord-loop explanation on its tooltip; the range
  // description would contradict the control doing nothing.
  if (control.disabled) return;
  control.title = value <= 0
    ? 'No melodic transposition'
    : value < 35
      ? 'Gentle whole-tone lifts only'
      : value < 70
        ? 'Whole-tone and fourth lifts'
        : 'Whole-tone, fourth, and fifth lifts';
}

function syncRearrangeLoopControls() {
  const disabled = rearrangeActive();
  // The song's own loop controls still stand down while a recipe owns the transport —
  // but the recipe's OWN loop is a real switch, not a label. It was drawn permanently on
  // and permanently disabled, which left no way to hear a rearrangement end.
  for (const id of ['formloop', 'songloopstart', 'songloopfrom', 'songloopto', 'songloopclear']) {
    const el = $(id);
    if (el) el.disabled = disabled;
  }
  if ($('looptoggle')) $('looptoggle').disabled = false;
  if (disabled) {
    $('looptoggle')?.setAttribute('title', rearrangeLoopOn
      ? 'The recipe starts again when it ends — click to let it stop instead'
      : 'The recipe stops when it ends — click to loop it');
    $('formloop')?.setAttribute('title', 'The Rearrange recipe owns the temporary output loop');
  }
  syncLoopButton();
  syncSongLoopUi();
}

function clipTemplateForSection(sectionIndex) {
  if (!rearrangeRecipe?.form?.[sectionIndex]) return null;
  const operations = rearrangeSectionOperations(sectionIndex);
  if (!operations.length) return null;
  const section = rearrangeRecipe.form[sectionIndex];
  return {
    id: `${trackId}-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
    label: `${section.letter || ''} · ${section.name}`,
    letter: section.letter || '',
    steps: section.end - section.start,
    operations,
    // A clip is an explicit user choice: preserve its rows exactly when the target
    // letter happens to have the same size, and allow the generator to repeat/trim
    // it when the reassigned letter has a different slot length.
    resizable: true,
    verbatim: true,
    ...(rearrangeRecipe.key ? { key: { ...rearrangeRecipe.key } } : {}),
  };
}

function clipTemplateForSelectedRearrangeSlices() {
  if (!rearrangeRecipe || !rearrangeSelectedOperations.size) return null;
  const indices = [...rearrangeSelectedOperations]
    .filter((index) => rearrangeRecipe.operations?.[index])
    .sort((a, b) => a - b);
  if (!indices.length) return null;
  const operations = indices.map((index) => ({ ...rearrangeRecipe.operations[index] }));
  const steps = operations.reduce((sum, operation) =>
    sum + operation.length * operation.repeats, 0);
  if (!steps) return null;
  let output = 0;
  const sections = new Set();
  for (const [index, section] of (rearrangeRecipe.form || []).entries()) {
    const start = output;
    output = section.end;
    let cursor = 0;
    for (const [operationIndex, operation] of rearrangeRecipe.operations.entries()) {
      const end = cursor + operation.length * operation.repeats;
      if (indices.includes(operationIndex) && cursor >= start && end <= output) sections.add(index);
      cursor = end;
    }
  }
  const sourceSections = [...sections].map((index) => rearrangeRecipe.form[index]).filter(Boolean);
  const sourceLabel = sourceSections.length === 1
    ? `${sourceSections[0].letter || ''} · ${sourceSections[0].name}`.trim()
    : 'Selected slices';
  const durationLabel = steps % 16 === 0 ? `${steps / 16} bars` : `${steps} sixteenths`;
  return {
    id: `${trackId}-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
    label: `${sourceLabel} · ${durationLabel}`,
    letter: sourceSections[0]?.letter || '',
    steps,
    operations,
    resizable: true,
    verbatim: true,
    ...(rearrangeRecipe.key ? { key: { ...rearrangeRecipe.key } } : {}),
  };
}

/** Whether a letter already belongs to a clip on the shelf — at most one clip per letter. */
function rearrangeClipLetterTaken(letter, excludeIndex = -1) {
  return !!letter && rearrangeClips.some((clip, index) => index !== excludeIndex && clip.letter === letter);
}

function addRearrangeClip(clip) {
  if (!clip) return;
  // A freshly snapshotted clip inherits its source section's letter, and TWO sections can
  // share one letter (two Choruses are both 'C'). Saving both to the shelf used to leave
  // them silently sitting on the same letter with no warning — and at Generate time,
  // `Object.fromEntries` on the shelf array keeps only the LAST one, so the first was not
  // just unused, it looked used right up until the moment it quietly wasn't. The letter
  // picker already refuses a REASSIGNMENT onto a taken letter; a clip cannot be allowed to
  // arrive on one silently either, so a collision here strips the letter instead — the
  // clip is saved, it simply is not yet assigned to anything.
  const bumped = rearrangeClipLetterTaken(clip.letter);
  if (bumped) clip.letter = '';
  rearrangeClips.push(clip);
  renderRearrangeClips();
  renderRearrangeInspector();
  toast(bumped
    ? `Saved ${clip.label} to the M8TRX shelf — its letter was already taken, so choose one for it`
    : `Saved ${clip.label} to the M8TRX shelf`);
}

function snapshotRearrangeClip(sectionIndex) {
  addRearrangeClip(clipTemplateForSection(sectionIndex));
}

function snapshotSelectedRearrangeClip() {
  const clip = clipTemplateForSelectedRearrangeSlices();
  if (!clip) {
    toast('Select one or more M8TRX slices first');
    return;
  }
  addRearrangeClip(clip);
}

function rearrangeClipLetterChoices() {
  const choices = [];
  const seen = new Set();
  for (const section of rearrangeRecipe?.form || []) {
    const letter = typeof section.letter === 'string' ? section.letter : '';
    if (!letter || seen.has(letter)) continue;
    seen.add(letter);
    choices.push({ letter, label: `${letter} · ${section.name}` });
  }
  for (const clip of rearrangeClips) {
    const letter = typeof clip.letter === 'string' ? clip.letter : '';
    if (!letter || seen.has(letter)) continue;
    seen.add(letter);
    choices.push({ letter, label: `${letter} · saved assignment` });
  }
  return choices;
}

function assignRearrangeClipLetter(index, letter) {
  const clip = rearrangeClips[index];
  if (!clip) return;
  const next = typeof letter === 'string' && /^[A-Z]$/.test(letter) ? letter : '';
  if (rearrangeClipLetterTaken(next, index)) {
    toast(`${next} already has a clip assigned`);
    renderRearrangeClips();
    return;
  }
  clip.letter = next;
  renderRearrangeClips();
  toast(next ? `${clip.label} assigned to ${next}` : `${clip.label} left unassigned`);
}

function renderRearrangeClips() {
  const shelf = $('reclipstrip');
  if (!shelf) return;
  shelf.textContent = '';
  if (!rearrangeClips.length) { shelf.hidden = true; return; }
  shelf.hidden = false;
  const label = document.createElement('span'); label.className = 'reclipslabel'; label.textContent = 'Clip shelf';
  shelf.append(label);
  rearrangeClips.forEach((clip, index) => {
    const row = document.createElement('span'); row.className = 'reclip';
    const use = document.createElement('button'); use.type = 'button'; use.className = 'reclipuse'; use.textContent = clip.label;
    use.title = clip.letter
      ? `Use ${clip.label} for letter ${clip.letter} on the next Go`
      : 'This clip is unassigned; choose a letter before you press Go';
    use.onclick = () => toast(clip.letter
      ? `${clip.label} ready for letter ${clip.letter}`
      : 'Assign this clip to a letter before you press Go');
    const assign = document.createElement('select'); assign.className = 'reclipletter';
    assign.title = 'Choose which repeated letter uses this clip on the next Go';
    assign.setAttribute('aria-label', `Letter assignment for ${clip.label}`);
    const none = document.createElement('option'); none.value = ''; none.textContent = '—';
    assign.append(none);
    for (const choice of rearrangeClipLetterChoices()) {
      const option = document.createElement('option'); option.value = choice.letter; option.textContent = choice.label;
      assign.append(option);
    }
    assign.value = clip.letter || '';
    assign.onchange = () => assignRearrangeClipLetter(index, assign.value);
    const remove = document.createElement('button'); remove.type = 'button'; remove.className = 'reclipremove'; remove.textContent = '×'; remove.title = 'Remove this clip';
    remove.onclick = () => { rearrangeClips.splice(index, 1); renderRearrangeClips(); renderRearrangeInspector(); };
    row.append(use, assign, remove); shelf.append(row);
  });
}

function renderRearrangeTimeline(geometry = rearrangeTimelineGeometry()) {
  const strip = $('rearrangeform');
  if (!strip) return;
  strip.textContent = '';
  const form = rearrangeRecipe?.form;
  if (!Array.isArray(form) || !form.length) {
    strip.hidden = true;
    return;
  }
  strip.hidden = false;
  // WHICH PART IS HELD, resolved once for the whole draw. Without this the card carried no
  // mark at all and the only part that ever looked picked was whichever one was SOUNDING —
  // usually the first, which made holding a part look like it worked on the intro and
  // nowhere else.
  const heldSection = rearrangeSelectedSectionIndex();
  // ONE SCALE FOR THE WHOLE PANEL, AND A LINE IS AT MOST FOUR BARS. Every slice's width is
  // its share of that scale, so a bar is a bar wherever it is drawn: a two-bar part fills
  // half a line, and a part longer than four bars wraps onto as many lines as it needs
  // rather than shrinking its slices to fit one. Where no part reaches four bars the
  // longest one sets the scale instead, so a short song still uses the width it has.
  const longest = Math.max(1, ...geometry.sections.map((entry) =>
    entry.ops.reduce((sum, op) => sum + op.span, 0)));
  const timescale = Math.min(REARRANGE_LINE_STEPS, longest);
  form.forEach((section, index) => {
    const startBar = Math.floor(section.start / 16) + 1;
    const endBar = Math.ceil(section.end / 16);
    const placed = geometry.sections[index]?.ops || [];
    const slices = placed.map((entry) => entry.index);
    const cycle = rearrangeCycleLength(placed.map((entry) => entry.op));
    const passes = cycle ? placed.length / cycle : 1;
    const allSelected = slices.length
      && slices.every((slice) => rearrangeSelectedOperations.has(slice));
    // The row is the part: its controls at the left, its time across the rest.
    const row = document.createElement('div');
    row.className = 'rerow';
    row.dataset.section = String(index);
    row.dataset.role = section.role || '';
    // A div, not a button: this segment CONTAINS buttons now — the whole-part actions
    // that used to be crammed into the first row of the part down in the list, where
    // they made that one row a different shape from every row under it and made its
    // per-slice checkbox look like it meant the whole part. They are section actions,
    // and this rail is the section UI, so they live here.
    const seg = document.createElement('div');
    seg.className = 'reformseg';
    seg.classList.toggle('chosen', index === heldSection);
    seg.dataset.section = String(index);
    seg.dataset.role = section.role || '';
    seg.draggable = true;
    seg.ondragstart = (event) => {
      event.dataTransfer.effectAllowed = 'move';
      event.dataTransfer.setData('text/plain', String(index));
      seg.classList.add('dragging');
    };
    seg.ondragend = () => seg.classList.remove('dragging');
    seg.ondragover = (event) => { event.preventDefault(); event.dataTransfer.dropEffect = 'move'; };
    seg.ondrop = (event) => {
      event.preventDefault();
      const from = Number(event.dataTransfer.getData('text/plain'));
      if (Number.isInteger(from) && from !== index) reorderRearrangeSections(from, index);
    };
    if (rearrangeLockedSections.has(index)) seg.classList.add('locked');
    if (allSelected) seg.classList.add('chosen');
    // The card IS the part's checkbox. Clicking it anywhere that is not one of its own
    // buttons takes the whole part into the selection, which is what a box in the corner
    // did while also being a second thing to aim at for the same job. Playing from here
    // stays on the name, where a title you can click already reads as "go to this".
    seg.onclick = (event) => {
      if (event.target.closest('button')) return;
      toggleRearrangeSectionSlices(index);
    };
    // Double-click plays from here AND keeps the part held: the two single clicks that
    // precede it would have selected the part and then let go of it again.
    seg.ondblclick = (event) => {
      if (event.target.closest('button')) return;
      playRearrangementAt(section.start, { part: index });
      selectRearrangeSectionSlices(index);
    };
    seg.title = allSelected
      ? `Deselect the ${slices.length} slices in ${section.name} · double-click to play from here`
      : `Select all ${slices.length} slices in ${section.name} · double-click to play from here`;

    const top = document.createElement('div');
    top.className = 'reformtop';
    const chip = document.createElement('i');
    chip.className = 'rerolechip';
    const name = document.createElement('button');
    name.type = 'button';
    name.className = 'reformname';
    name.textContent = `${section.letter || ''} · ${section.name}`;
    name.title = `Play ${section.name}, output bars ${startBar}–${endBar}`;
    name.setAttribute('aria-label', name.title);
    name.onclick = () => playRearrangementAt(section.start);
    const range = document.createElement('span');
    range.className = 'reformbars';
    range.textContent = `Bars ${startBar}–${endBar}${passes > 1 ? ` · ×${passes}` : ''}`;
    if (passes > 1) range.title = `${section.name} plays the same ${cycle} slice${cycle === 1 ? '' : 's'} ${passes} times`;
    top.append(chip, name);
    // The walk this part takes, bar by bar, as roman numerals: 'i i | IV IV | V | VI'.
    // Read off the DRAFT recipe's operations rather than any palette name, so it shows
    // what will actually sound — including a part that only partly walks, or not at all.
    const cycleSteps = passes > 1
      ? Math.round((section.end - section.start) / passes) : 0;
    const chords = rearrangeSectionChordLine(index, 'roman', cycleSteps);
    const walk = document.createElement('div');
    walk.className = 'reformchords';
    if (chords) {
      // Built as elements rather than set as text so the separator can be its own thing: a
      // solid glyph, bigger than the numerals it sits between and tight against them. As
      // plain text the arrow came out thin and floating in a gap on either side, which read
      // as three loose numerals rather than one progression.
      walk.textContent = '';
      chords.split(' → ').forEach((step, at) => {
        if (at) {
          const arrow = document.createElement('i');
          arrow.className = 'rewalkarrow';
          arrow.textContent = '→';
          walk.append(arrow);
        }
        walk.append(document.createTextNode(step));
      });
      walk.title = `${section.name} plays the chords ${chords.replace(/ → /g, ', then ')} in ${rearrangeKeyName(rearrangeRecipe?.key)}, one per bar`;
      walk.setAttribute('aria-label', walk.title);
    }

    top.append(walk, range);

    const acts = document.createElement('div');
    acts.className = 'reformacts';
    const lock = document.createElement('button');
    lock.type = 'button'; lock.className = 'relock';
    lock.textContent = rearrangeLockedSections.has(index) ? '🔒' : '🔓';
    lock.classList.toggle('on', rearrangeLockedSections.has(index));
    lock.title = rearrangeLockedSections.has(index)
      ? `Unlock ${section.name}` : `Keep ${section.name} verbatim through the next Go`;
    lock.setAttribute('aria-label', lock.title);
    lock.setAttribute('aria-pressed', rearrangeLockedSections.has(index) ? 'true' : 'false');
    lock.onclick = () => toggleRearrangeLock(index);
    // The card's own 'Grab' is gone. It locked this part, but ONLY while this part was
    // the one sounding — so on any card you were actually looking at, it usually did
    // nothing and said so in a toast. The lock beside it does the same job with no
    // condition attached, and the header's Lock what's playing covers the heard case.
    const halve = document.createElement('button');
    halve.type = 'button'; halve.className = 'rehalve'; halve.textContent = '½';
    halve.title = 'Halve this section’s output';
    halve.onclick = () => transformRearrangeSectionUi(index, 'halve', 'Section halved');
    const double = document.createElement('button');
    double.type = 'button'; double.className = 'redouble'; double.textContent = '×2';
    double.title = 'Repeat this section once';
    double.onclick = () => transformRearrangeSectionUi(index, 'double', 'Section doubled');
    // A NEW TAKE ON THIS PART, built from scratch. Not a reshuffle of the slices that are
    // there — the part is generated again, so it can come back chopped where it was one
    // loop, or as a pair where it was a collage, from a different phrase of the song. The
    // one thing it may not change is its LENGTH, so the song's form never moves and no
    // other part is touched. The dice beside Walk in the toolbar is the harmony's version
    // of this one; this is the material's.
    const dice = document.createElement('button');
    dice.type = 'button'; dice.className = 'rediceSection'; dice.textContent = '🎲';
    dice.title = `Build ${section.name} again from scratch — new material AND a new chop, in exactly the space it already takes. Its walk, its favourites and its fill are kept`;
    dice.setAttribute('aria-label', dice.title);
    dice.onclick = () => rerollRearrangeSectionMaterial(index);
    // THE PART'S OWN CONTROLS BELONG ON THE PART. They were a whole toolbar row away,
    // which meant holding a card, travelling to the bottom of the panel, and coming back
    // — for edits that are about the thing your pointer is already on. The ones that get
    // used constantly stay as icons; the rest are on the card's right-click menu.
    // ICONS FOR THE THREE PRESSED WHILE LOOKING AT THE PART, each lit when it is on so the
    // card answers "does this part walk, does it fill" without being opened. An emoji on
    // its own is a rebus, so every one of them carries a title and an aria-label that says
    // the whole thing in words.
    const carriesFill = placed.some((entry) => entry.op.fill);
    const partWalks = !!chords;
    const walkButton = document.createElement('button');
    // W AND F, NOT A WALKING MAN AND A LIGHTNING BOLT. A pictogram on a 24px button is a
    // rebus you have to solve every time, and neither of these two has a picture anyone
    // already knows — a walking figure for "moves around the key" is a pun, not an icon. The
    // initial of the word plus the lit/unlit state is the whole message: W on means this
    // part walks, F on means it ends on a fill. Both still carry the sentence in their title.
    walkButton.type = 'button'; walkButton.className = 'rewalkbutton'; walkButton.textContent = 'W';
    walkButton.classList.toggle('on', partWalks);
    walkButton.title = partWalks
      ? `${section.name} walks a chord loop — turn it off, or reroll its order`
      : `Walk ${section.name} around the song’s own key`;
    walkButton.setAttribute('aria-label', walkButton.title);
    // A WALK IS ON OR OFF, so W is a switch and not a door. It opened a two-item menu whose
    // first item was "Walk this part" and whose second — a reroll of the chord order — is
    // already in the part menu a right-click away, so the menu was a click in front of a
    // toggle. The button lights when the part walks, which is the answer to the only
    // question it asks.
    walkButton.onclick = (event) => { event.stopPropagation(); toggleRearrangeWalkUi(index); };
    const fill = document.createElement('button');
    fill.type = 'button'; fill.className = 'refillbutton'; fill.textContent = 'F';
    fill.classList.toggle('on', carriesFill);
    fill.title = carriesFill
      ? `${section.name} ends on a ${placed.find((entry) => entry.op.fill)?.op.fill} fill — change or remove it`
      : `Put a fill on ${section.name}’s ending`;
    fill.setAttribute('aria-label', fill.title);
    fill.onclick = (event) => { event.stopPropagation(); openRearrangeFillMenu(event, index); };
    const shelf = document.createElement('button');
    shelf.type = 'button'; shelf.className = 'reclipbutton'; shelf.textContent = '💾';
    shelf.title = `Save ${section.name} to the shelf, for the next Go to reuse`;
    shelf.setAttribute('aria-label', shelf.title);
    shelf.onclick = () => snapshotRearrangeClip(index);
    // NO ⋯ ON THE CARD. Right-clicking anywhere on the part opens the same menu, so the
    // button was a second door onto one room, taking a slot from a row that has to stay
    // readable at card width. The right-click is the only way in now, which also means the
    // row below holds nothing but the presses that DO something on contact.
    //
    // IN GROUPS, because seven buttons at an even 2px is a strip you have to read from the
    // left every time to find the one you want. Spaced, the hand aims at a group first:
    // what the next Go does to this part, how long it is, and what it plays. The shelf
    // sits on its own — it is the only one that puts something OUTSIDE the card.
    for (const group of [[lock, dice], [halve, double], [walkButton, fill], [shelf]]) {
      const box = document.createElement('div');
      box.className = 'reactgroup';
      box.append(...group);
      acts.append(box);
    }

    seg.append(top, acts);

    const lane = document.createElement('ol');
    lane.className = 'restrip';
    lane.setAttribute('aria-label', `${section.name} slices`);
    lane.style.setProperty('--timescale', String(timescale));
    const variants = rearrangeSliceVariants(placed.map((entry) => entry.op));
    placed.forEach((entry) => {
      const { op, index: opIndex, start, end, span } = entry;
      const slice = document.createElement('li');
      slice.className = 'reslice';
      slice.dataset.operation = String(opIndex);
      slice.dataset.section = String(index);
      if (section.role) slice.dataset.role = section.role;
      // The slice's own step count IS its width: flex-grow against a zero basis divides
      // the row by time, so the strip reads as the part's bar line rather than a list.
      slice.style.setProperty('--slicespan', String(Math.max(1, span)));
      if (rearrangeSelectedOperations.has(opIndex)) slice.classList.add('selected');
      if (op.mute) slice.dataset.mute = 'on';
      const favourite = op.repeats === 1 && op.transpose === 0
        && rearrangeFavourites.some((item) => item.from === op.from && item.length === op.length);
      if (favourite) slice.classList.add('favourite');
      slice.dataset.variant = String(variants.get(`${op.from}:${op.length}`) || 0);
      // The start of every pass after the first, so a doubled part shows its seam.
      if (cycle && placed.indexOf(entry) % cycle === 0 && placed.indexOf(entry) > 0) {
        slice.dataset.cycle = 'on';
      }
      // Compact bar:beat.sixteenth notation on the block, which may be only a few pixels
      // wide; the full wording waits on the hover, where there is room for it. The pass
      // count goes UNDER it rather than beside it — a narrow block clips from the right,
      // and '52:1.1 ×4' losing its tail leaves you reading a source position that is not
      // the whole truth about what happens there.
      const label = document.createElement('span');
      label.className = 'reslicelabel';
      label.textContent = `${favourite ? '★ ' : ''}${rearrangeOutputLabel(op.from)}`;
      slice.append(label);
      if (op.repeats > 1) {
        // Ruled per pass, so the block's own divisions say how many times it goes round.
        slice.dataset.repeats = String(op.repeats);
        slice.style.setProperty('--repeats', String(op.repeats));
        const passes = document.createElement('span');
        passes.className = 'reslicerepeat';
        passes.textContent = `×${op.repeats}`;
        slice.append(passes);
      }
      const foot = document.createElement('div');
      foot.className = 'reslicefoot';
      // ONE MARK PER FILL, ON THE SLICE IT STARTS AT. A fill chops a part's ending into
      // several cells and every one of them carries `fill`, so a tick on each drew four
      // identical dots in a row for one event — four statements of one fact, and the dots
      // read as a property of the slices rather than as a thing that begins here. Marking
      // only where the run starts keeps what the mark is FOR (where does the fill come in)
      // and drops the repetition. The part card's F already says the part has one at all.
      if (op.fill && !placed[placed.indexOf(entry) - 1]?.op?.fill) {
        const tick = document.createElement('i');
        tick.className = 'refilltick';
        tick.title = `${op.fill} fill starts here`;
        foot.append(tick);
      }
      const chord = document.createElement('b');
      chord.className = 'rechordbadge';
      // WHAT THIS SLICE SOUNDS, ASKED OF THE SLICE. It used to be read off the part's
      // stamped chord line by bar, which is the walk's INTENTION for that bar rather than
      // anything this slice agreed to — so a slice taken back out of the walk, or a copy
      // living past the end of a line that was never lengthened when the part was doubled,
      // sat there labelled `iv` while playing exactly as written. See applyWalkChords.
      const sounding = rearrangeSoundingChord(op);
      if (sounding) chord.textContent = harmonyNumeral(sounding, rearrangeRecipe?.key?.minor !== false);
      else if (op.transpose) chord.textContent = op.transpose > 0 ? `+${op.transpose}` : String(op.transpose);
      foot.append(chord);
      slice.append(foot);
      const keyName = rearrangeKeyName(rearrangeRecipe?.key) || 'the key';
      slice.title = `${op.mute ? 'MUTED · ' : ''}Source ${rearrangeStepLabel(op.from)} · ${op.length} sixteenths × ${op.repeats}`
        + ` · output ${rearrangeStepLabel(start)}–${rearrangeStepLabel(end)}`
        + (op.transpose ? rearrangeTransposeLabel(op.transpose) : '')
        + (op.fill ? ` · ${op.fill} fill` : '')
        // A WALKED SLICE THAT MOVED BY NOTHING STILL HAS SOMETHING TO SAY. The walk reads
        // where the material already sits and only moves it the rest of the way, so a bar
        // that is already on the chord the walk wants is left alone — and with the hover
        // silent about it, a badge over an unmoved slice read as a fault rather than as
        // the one case where the walk had nothing to do.
        + (op.harmony
          ? ` · plays as the ${harmonyNumeral(op.harmony, rearrangeRecipe?.key?.minor !== false)} of ${keyName}`
          : (sounding ? ` · already sits on the ${harmonyNumeral(sounding, rearrangeRecipe?.key?.minor !== false)} of ${keyName}, so the walk leaves it as written` : ''))
        + ' · click to select, drag across several, double-click to play from here';
      lane.append(slice);
    });

    row.append(seg, lane);
    strip.append(row);
  });
}

/** A part's bar-by-bar chord walk as grouped scale-degree notation, or '' when it plays as written. */
function rearrangeSectionChordLine(sectionIndex, notation = 'degree', limitSteps = 0) {
  const section = rearrangeRecipe?.form?.[sectionIndex];
  const key = rearrangeRecipe?.key;
  if (!section || !key) return '';
  const minor = key.minor !== false;
  const chords = [];
  // A part that repeats states its walk ONCE. Sixteen bars of numerals is not a chord
  // line, it is a wall, and the part's own '×4' already says the rest is the same again.
  const until = limitSteps > 0 ? Math.min(section.end, section.start + limitSteps) : section.end;
  // WHAT THE PART SOUNDS, NOT THE SHIFT THAT GOT IT THERE — and asked of the SLICE playing
  // in each bar. `harmony` is a RELATIVE move, so the numeral is only true off it while the
  // material is assumed to start on the tonic; a walk that read the source writes down what
  // it landed on instead. This used to be read off the part's stamped line, which is the
  // walk's intention for the part rather than a report on the slices in it: doubling the
  // part left every bar past the old end pinned to the line's last chord, and taking one
  // slice back out of the walk did not change the line at all.
  const stamped = Array.isArray(section.chords) && section.chords.length ? section.chords : null;
  for (let step = section.start; step < until; step += 16) {
    const bar = Math.floor((step - section.start) / 16);
    const op = rearrangementPosition(rearrangeRecipe, step)?.operation;
    // The stamped line stays as the fallback for recipes written before slices carried what
    // they sound — the same reading those recipes have always been printed with.
    const harmony = op?.chord == null && stamped
      ? (stamped[Math.min(stamped.length - 1, bar)] || 0)
      : rearrangeSoundingChord(op);
    if (notation === 'roman') chords.push(harmonyNumeral(harmony, minor));
    else chords.push(String(((harmony % 7) + 7) % 7 + 1));
  }
  const tonic = notation === 'roman' ? (minor ? 'i' : 'I') : '1';
  if (!chords.some((chord) => chord !== tonic)) return '';
  // A HELD CHORD IS COUNTED, NOT REPEATED. Two bars of the tonic written out as `i i` reads
  // as `ii` — the supertonic, a different chord — and at a glance that is not a near miss,
  // it is the wrong information. `i ×2` cannot be misread, and ×N is already the desk's word
  // for "this again" on slices and part cards.
  const groups = [];
  let group = [];
  const flush = () => {
    if (!group.length) return;
    groups.push(group.length > 1 ? `${group[0]} ×${group.length}` : group[0]);
    group = [];
  };
  chords.forEach((chord) => {
    if (group.length && group[group.length - 1] !== chord) flush();
    group.push(chord);
  });
  flush();
  // ARROWS, NOT PIPES. A walk is a progression — it GOES somewhere — and a pipe is a
  // divider, the same mark a bar line uses everywhere else on this desk. Read quickly,
  // `i i | iv | v` looked like three bars of something rather than one chord moving to the
  // next; `i i → iv → v` cannot be read any way but forwards.
  return groups.join(' → ');
}

/**
 * One walk of the draft, giving every slice its place on the timeline.
 *
 * The timeline draws a part as a row and a slice as a block whose width is its share of
 * that row, so drawing it and following it both need the same per-operation output
 * extents. Walking the operation list once and passing the answer around is also what
 * stops a card from re-walking the whole recipe per button it builds.
 */
/** Four bars. One line of the timeline holds this much, and a longer part wraps. */
const REARRANGE_LINE_STEPS = 64;

function rearrangeTimelineGeometry() {
  const form = Array.isArray(rearrangeRecipe?.form) ? rearrangeRecipe.form : [];
  const sections = form.map((section, index) => ({
    index, section, span: Math.max(1, section.end - section.start), ops: [],
  }));
  const ops = [];
  let output = 0;
  for (const [index, op] of (rearrangeRecipe?.operations || []).entries()) {
    const span = op.length * op.repeats;
    // A slice belongs to the part its START falls in — the rule the list read before it.
    const sectionIndex = form.findIndex((item) => output >= item.start && output < item.end);
    const entry = { index, op, start: output, end: output + span - 1, span, sectionIndex };
    ops.push(entry);
    if (sectionIndex >= 0) sections[sectionIndex].ops.push(entry);
    output += span;
  }
  return { total: output, sections, ops };
}

/** How many members a part-colour family has. See the ceiling note in mixer-shell.html. */
const REARRANGE_SLICE_VARIANTS = 3;

/**
 * Which member of its part's colour family each slice in ONE part wears.
 *
 * A slice's identity is where it comes FROM — `from` and `length` — not how many passes
 * it takes, so a riff heard four times and the same riff heard three times later in the
 * part are one material and wear one variant.
 *
 * SCOPED TO THE PART, WHICH IS THE WHOLE POINT AND ALSO THE WHOLE RISK. Colour used to be
 * a hash of the material's own identity, and it was a hash rather than a first-seen index
 * because a first-seen index walked the WHOLE timeline: rebuild one part into a different
 * number of pieces — which the part dice does on purpose — and every material after it
 * shifted, so parts nobody touched appeared to change colour and one edit read as the
 * whole recipe changing.
 *
 * Ranking inside a single part cannot do that. The map is built from one part's own
 * operations and nothing else, so an edit to a part repaints that part and reaches no
 * further: the blast radius is exactly the thing that changed. What it does mean is that
 * editing a part CAN renumber that part's own colours — drop its distinct materials from
 * three to two and the third moves up — and that is correct, because the part really does
 * now hold different material.
 *
 * Ranking rather than hashing within the part, because a hash may collide and a rank may
 * not: two materials in one part must never land on the same variant while a free one is
 * going spare, and that guarantee IS the feature.
 */
function rearrangeSliceVariants(ops) {
  const variants = new Map();
  for (const op of ops) {
    const key = `${op.from}:${op.length}`;
    if (!variants.has(key)) variants.set(key, variants.size % REARRANGE_SLICE_VARIANTS);
  }
  return variants;
}

/**
 * How long a part's repeating cycle is, in slices, or 0 if it does not repeat.
 *
 * Doubling a part copies its slices rather than raising a repeat count — the SEQUENCE
 * repeats, and no single slice does — so nothing in the recipe records that the second
 * half is the first one again. It does not have to: the material says so, and reading it
 * back off the slices means a part that repeats because it was generated that way is
 * marked exactly like one that repeats because it was doubled by hand.
 */
function rearrangeCycleLength(ops) {
  const count = ops.length;
  if (count < 2) return 0;
  const same = (a, b) => a.from === b.from && a.length === b.length && a.repeats === b.repeats
    && (a.transpose || 0) === (b.transpose || 0) && (a.harmony || 0) === (b.harmony || 0)
    && (a.fill || null) === (b.fill || null) && !!a.mute === !!b.mute;
  for (let period = 1; period <= count / 2; period += 1) {
    if (count % period) continue;
    let repeats = true;
    for (let index = period; index < count && repeats; index += 1) {
      if (!same(ops[index], ops[index - period])) repeats = false;
    }
    if (repeats) return period;
  }
  return 0;
}

/** Every operation index that sounds inside one form section. */
function rearrangeSectionOperationIndices(sectionIndex) {
  return rearrangeTimelineGeometry().sections[sectionIndex]?.ops.map((entry) => entry.index) || [];
}

/** Move a whole form block on the M8TRX timeline without changing its internal edits. */
function reorderRearrangeSections(fromIndex, toIndex) {
  if (!rearrangeRecipe?.form?.length) return;
  const form = rearrangeRecipe.form;
  if (fromIndex < 0 || toIndex < 0 || fromIndex >= form.length || toIndex >= form.length) return;
  const blocks = form.map((section, index) => ({
    section,
    operations: rearrangeSectionOperations(index),
  }));
  const [moved] = blocks.splice(fromIndex, 1);
  blocks.splice(toIndex, 0, moved);
  let output = 0;
  const operations = [];
  const nextForm = blocks.map(({ section, operations: block }) => {
    const start = output;
    operations.push(...block.map((operation) => ({ ...operation })));
    output += block.reduce((sum, operation) => sum + operation.length * operation.repeats, 0);
    return { ...section, start, end: output };
  });
  applyRearrangeEdit({ ...rearrangeRecipe, form: nextForm, operations },
    `Moved ${moved.section.letter || moved.section.name}`);
}

/**
 * Take one whole part into the selection, or drop it if it was already the one held.
 *
 * Exactly ONE part at a time: picking a part replaces whatever was selected rather than
 * adding to it. A part is a thing you are working on, and an edit aimed at "the Chorus"
 * that quietly also lands on a Verse picked three clicks ago is the kind of mistake you
 * only notice after it has been installed. Runs that cross parts are still reachable by
 * dragging across the slices themselves, where the range is visible while you make it.
 */
function toggleRearrangeSectionSlices(sectionIndex) {
  const slices = rearrangeSectionOperationIndices(sectionIndex);
  if (!slices.length) return;
  const held = slices.length === rearrangeSelectedOperations.size
    && slices.every((slice) => rearrangeSelectedOperations.has(slice));
  if (held) {
    rearrangeSelectedOperations.clear();
    renderRearrangeList();
    syncRearrangeProgress(Audio.rearrangement ? Audio.step : null);
    return;
  }
  selectRearrangeSectionSlices(sectionIndex);
}

/** Hold one part, without the toggle — what a double-click needs, since its two single
 *  clicks would otherwise select the part and then let go of it again. */
function selectRearrangeSectionSlices(sectionIndex) {
  const slices = rearrangeSectionOperationIndices(sectionIndex);
  if (!slices.length) return;
  rearrangeSelectedOperations.clear();
  for (const slice of slices) rearrangeSelectedOperations.add(slice);
  renderRearrangeList();
  syncRearrangeProgress(Audio.rearrangement ? Audio.step : null);
}

function renderRearrangeList() {
  if (!$('rearrangeform')) return;
  // Every toolbar enabled state is settled in one place, by the thing that draws the
  // toolbar — see renderRearrangeInspector at the foot of this function.
  // The draft is ahead of the audio: mark the whole panel so the slices and the status
  // read as "made, not yet heard". One class; the flash itself is CSS.
  $('rearrangepanel')?.classList.toggle('pending', rearrangePending);
  // NO RECIPE, NO RECIPE CONTROLS. Exit M8TRX leaves the panel standing — the M8TRX
  // button in the toolbar is the way out, not this — but everything scoped to a recipe was
  // left standing with it: a drums menu for drums that are not playing, Save version and
  // Save JSON with nothing to save, a Exit M8TRX that has already returned, and two
  // selection rails inviting you to click slices in an empty timeline. One class says
  // "there is nothing here yet" and the panel shows only what can act on that: the dials,
  // Go, the kept state that outlives a recipe, and Load JSON, which is the other way in.
  $('rearrangepanel')?.classList.toggle('norecipe', !rearrangeRecipe);
  // The status lives in the desk's footer now, so the pending pulse is toggled there too.
  // It shows only while the panel is up: the footer is the desk's line, and a closed panel
  // has no business holding a third of it.
  const strip = $('m8status');
  if (strip) {
    const was = strip.hidden;
    strip.hidden = !rearrangePanelOpen;
    strip.classList.toggle('pending', rearrangePending);
    // Showing this line makes the footer TALLER, so the panel's bottom edge has to be
    // re-measured after it appears rather than before. Measured on the way into the panel
    // alone, the answer was one layout stale and the panel overlapped the bar by 14px.
    if (was !== strip.hidden) measureDeskEdges();
  }
  const geometry = rearrangeTimelineGeometry();
  renderRearrangeTimeline(geometry);
  renderRearrangeClips();
  const meta = $('remetasong');
  if (!rearrangeRecipe) {
    if (meta) meta.textContent = track?.title || trackId || '';
    $('rearrangestatus').textContent = rearrangeFavourites.length
      ? `${rearrangeFavourites.length} piano-roll favourite${rearrangeFavourites.length === 1 ? '' : 's'} ready · Go to include them`
      : 'Press Go ▸ to build a recipe.';
    syncRearrangeDrumControl();
    renderRearrangeInspector();
    return;
  }
  // What is loaded, beside the name of the thing loading it: the song, how many parts the
  // recipe has, and how long it runs. It sits with the title rather than in the status line
  // because it is what this panel IS at rest, not what just happened to it.
  if (meta) {
    const parts = rearrangeRecipe.form?.length || 0;
    meta.textContent = `${track?.title || trackId} · ${parts} part${parts === 1 ? '' : 's'}`
      + ` · ${geometry.total / 16} bars`;
  }
  const form = rearrangeRecipe.form?.map((section) => section.name).join(' → ');
  const kept = rearrangeLockedSections.size ? ` · ${rearrangeLockedSections.size} kept` : '';
  const disliked = '';
  const favourites = rearrangeFavourites.length
    ? ` · ${rearrangeFavourites.length} piano-roll favourite${rearrangeFavourites.length === 1 ? '' : 's'}` : '';
  const selected = rearrangeSelectedOperations.size
    ? ` · ${rearrangeSelectedOperations.size} slice${rearrangeSelectedOperations.size === 1 ? '' : 's'} selected` : '';
  const drums = rearrangementDrumMode(rearrangeRecipe) === 'basic4'
    ? ' · steady 4/4 drums' : '';
  const songKey = rearrangeRecipe.key ? ` · ${rearrangeKeyName(rearrangeRecipe.key)}` : '';
  $('rearrangestatus').textContent = `${form ? `${form} · ` : ''}${rearrangeRecipe.operations.length} operations · ${geometry.total / 16} bars${songKey} · seed ${rearrangeRecipe.seed}${rearrangeSeedHold ? ' · varying this one' : ''}${drums}${kept}${disliked}${favourites}${selected}`;
  syncRearrangeDrumControl();
  renderRearrangeInspector();
}

function renderRearrangeInspector() {
  const info = $('reinspectinfo');
  if (!info) return;
  // The rails are STATIC markup: the same controls in the same places whether one slice is
  // selected or twenty. A rail whose scope holds nothing swaps its controls for one line of
  // instruction, but it keeps its HEIGHT while it does, so the timeline under it never steps
  // up and down while you are aiming at a slice in it.
  const geometry = rearrangeTimelineGeometry();
  const selected = [...rearrangeSelectedOperations].sort((a, b) => a - b);
  const index = selected[0];
  const operation = index == null ? null : rearrangeRecipe?.operations?.[index];
  const entry = index == null ? null : geometry.ops[index];
  const sectionIndex = entry?.sectionIndex ?? -1;
  const section = sectionIndex >= 0 ? rearrangeRecipe.form[sectionIndex] : rearrangeRecipe?.form?.[0];
  const many = selected.length > 1;
  const has = !!rearrangeRecipe;
  const any = has && selected.length > 0;

  // SCOPE IS NAMED IN WORDS, NEVER IN COLOUR. Four scope hues were the obvious answer and
  // the wrong one: they collide with four of the five fixed part-role hues, so a blue badge
  // would mean "selection" in the rail and "Verse" on the card two inches below it. Each
  // rail states its subject as a sentence instead, and the accent stays reserved for the one
  // thing it has always meant — on, selected, or moving.
  const heldSection = rearrangeSelectedSectionIndex();
  const heldPart = heldSection >= 0 ? rearrangeRecipe.form[heldSection] : null;
  const partName = heldPart ? `${heldPart.letter || ''} · ${heldPart.name}`.trim().replace(/^· /, '') : 'no part';
  // "all of B" rather than "6 slices" when the whole part is in hand: the two are the same
  // selection, and only one of them says why it looks that way.
  const wholePart = any && heldSection >= 0
    && selected.length === rearrangeSectionOperationIndices(heldSection).length;
  const count = wholePart
    ? `all of ${heldPart.letter || heldPart.name}`
    : `${selected.length} slice${selected.length === 1 ? '' : 's'}`;
  const subject = !has ? 'no recipe yet'
    : !any ? 'nothing held'
    : heldPart ? `${count} in ${partName}` : count;
  for (const [id, text] of [['reinspectinfo', subject], ['resubarr', subject],
                            ['resubpart', has ? partName : 'no recipe yet']]) {
    const cell = $(id);
    if (cell) cell.textContent = text;
  }
  // The exact output range is a hover on the subject rather than a second line: the rail has
  // two lines and it must keep them, because a rail that grew a line would move the timeline.
  if (!has) {
    info.title = 'Press Go ▸ to build a recipe, then click a slice.';
  } else if (many) {
    const last = geometry.ops[selected[selected.length - 1]];
    const steps = selected.reduce((sum, item) => sum + (geometry.ops[item]?.span || 0), 0);
    info.title = `Output ${rearrangeStepLabel(entry?.start || 0)}–${rearrangeStepLabel(last?.end || 0)}`
      + ` · ${String(+(steps / 16).toFixed(2))} bars`;
  } else if (operation) {
    info.title = `Output ${rearrangeStepLabel(entry?.start || 0)}–${rearrangeStepLabel(entry?.end || 0)}`
      + ` · source ${rearrangeStepLabel(operation.from)} · ${operation.length} sixteenths × ${operation.repeats}`
      + (operation.fill ? ` · ${operation.fill} fill` : '');
  } else {
    info.title = 'Click a slice, or drag across several.';
  }
  // AN EMPTY SCOPE SHOWS ITS INVITATION, NOT THIRTY DEAD BUTTONS. Same height either way.
  for (const bar of document.querySelectorAll('#reinspector .rebar')) {
    bar.classList.toggle('empty', bar.dataset.scope === 'part' ? heldSection < 0 : !any);
  }

  // One walked slice in the selection is enough to disable the chromatic dial: a recipe
  // carries one pitch system at a time, and the library refuses the mix.
  const walksHere = any && selected.some((item) => rearrangeRecipe.operations[item]?.harmony);
  const dial = $('reslicetranspose');
  if (dial) {
    if (!dial.options.length) {
      for (const amount of REARRANGE_TRANSPOSES) {
        const option = document.createElement('option');
        option.value = String(amount);
        option.textContent = amount === 0 ? 'Off' : amount > 0 ? `+${amount}` : String(amount);
        dial.append(option);
      }
    }
    dial.value = String(operation?.transpose || 0);
    dial.disabled = !any || walksHere;
    dial.title = walksHere
      ? 'Chord-walk slice: turn the walk off before changing transpose'
      : 'Transpose the selected slices; Off removes the transpose';
  }
  const chord = $('reslicechord');
  if (chord) {
    const minor = rearrangeRecipe?.key?.minor !== false;
    const wanted = `${minor ? 'm' : 'M'}`;
    if (chord.dataset.mode !== wanted) {
      chord.dataset.mode = wanted;
      chord.textContent = '';
      const asWritten = document.createElement('option');
      asWritten.value = '0';
      asWritten.textContent = 'As written';
      chord.append(asWritten);
      for (let degree = 1; degree < 7; degree += 1) {
        const option = document.createElement('option');
        option.value = String(degree);
        option.textContent = harmonyNumeral(degree, minor);
        chord.append(option);
      }
    }
    chord.value = String(operation?.harmony || 0);
    chord.disabled = !any || !rearrangeRecipe?.key;
    chord.title = rearrangeRecipe?.key
      ? 'What chord these slices play — any degree of the key, or As written'
      : 'No key detected, so there is nothing to move a chord within';
  }
  $('recopysection')?.toggleAttribute('disabled', !any);
  // Paste needs somewhere contiguous to land, the same run Join needs.
  $('repastesection')?.toggleAttribute('disabled', !any || !rearrangeCopiedSection
    || selected[selected.length - 1] - selected[0] !== selected.length - 1);
  const silent = any && selected.every((item) => rearrangeRecipe.operations[item]?.mute);
  const mute = $('remute');
  if (mute) {
    mute.textContent = silent ? 'Unmute' : 'Mute';
    mute.classList.toggle('on', silent);
    mute.disabled = !any;
    mute.title = silent
      ? 'Let the selected slices sound again'
      : 'Mute the selected slices: nothing sounds for their time, and the song keeps its exact length';
  }
  // Join wants a run that is actually a run.
  const run = selected.length > 1
    && selected[selected.length - 1] - selected[0] === selected.length - 1;
  $('rejoin')?.toggleAttribute('disabled', !run);
  // M8TRX has no Undo of its own: while a recipe is live the desk's Undo is M8TRX's, and
  // this is what keeps its label and its enabled state honest as the stack moves.
  syncUndoButton();
  $('reclearkept')?.toggleAttribute('disabled',
    !rearrangeLockedSections.size && !rearrangeClips.length && !rearrangeUniqueLetters.size);
  $('reclearselection')?.toggleAttribute('disabled', !any);
  for (const id of ['rerollselected', 'reclipselected', 'reremove', 'redeleteselected', 'reloopremove', 'reunroll']) {
    $(id)?.toggleAttribute('disabled', !any);
  }
  const stutter = $('restutter');
  if (stutter) {
    stutter.disabled = !any;
    stutter.value = '';
    // EACH OPTION SAYS WHETHER IT FITS. ×3 and ×6 are not offered at all: on a sixteenth
    // grid a slice divides by three only when its duration is a multiple of three, and
    // generated durations are powers of two — measured, they landed on 1.4% of slices,
    // which is a menu item that is a guessing game rather than a choice. Gallop carries
    // the swung, triplet-ish feel instead and fits any slice. The rest are greyed when
    // they will not divide what is in hand, rather than offered and then refused.
    for (const option of stutter.options) {
      if (!option.value) continue;
      const shape = REARRANGE_STUTTER_SHAPES[option.value];
      const parts = shape ? shape.reduce((sum, weight) => sum + weight, 0) : Number(option.value);
      option.disabled = !any || !selected.some((item) => {
        const op = rearrangeRecipe.operations[item];
        const duration = (op?.length || 0) * (op?.repeats || 0);
        return parts > 1 && duration % parts === 0 && duration / parts >= 1;
      });
    }
  }
  $('redoublerepeats')?.toggleAttribute('disabled',
    !any || selected.every((item) => (rearrangeRecipe.operations[item]?.repeats || 1) >= 4));
  $('rehalfrepeats')?.toggleAttribute('disabled',
    !any || selected.every((item) => (rearrangeRecipe.operations[item]?.repeats || 1) <= 1));
  const splitter = $('resplit');
  if (splitter) {
    const splittable = any && selected.some((item) => (rearrangeRecipe.operations[item]?.length || 0) >= 2);
    splitter.disabled = !splittable;
    splitter.title = splittable || !any
      ? 'Interleave each selected slice’s two halves: A B A B, same length'
      : rearrangeEditRefusal('split', selected);
  }
  // Everything that acts on a whole PART now lives on the part's own card — its icons and
  // its right-click menu — so nothing here has to be kept in step with a selection that may
  // not be a part at all.
  $('replayfrom')?.toggleAttribute('disabled', !has);
}

/**
 * The slice context menu.
 *
 * Everything on it is reachable from the toolbar already. It exists because the toolbar is
 * a long way from the block you are looking at, and the edits made most are the ones made
 * over and over on one slice after another — transpose this, walk that, silence the other.
 * Right-clicking a slice that is not held takes it first, so the menu always acts on what
 * was aimed at rather than on whatever happened to be selected beforehand.
 */
function openRearrangeSliceMenu(event, index) {
  const menu = $('reslicemenu');
  if (!menu || !rearrangeRecipe) return;
  if (!rearrangeSelectedOperations.has(index)) {
    rearrangeSelectedOperations.clear();
    rearrangeSelectedOperations.add(index);
    renderRearrangeList();
  }
  const picked = [...rearrangeSelectedOperations].sort((a, b) => a - b);
  const op = rearrangeRecipe.operations[index];
  const many = picked.length > 1;
  const walking = picked.some((item) => rearrangeRecipe.operations[item]?.harmony);
  // WALKED IS NOT THE SAME AS MOVED. A bar the walk found already on the chord it wanted is
  // part of the walk and carries no shift, so asking for a shift hid "walk off" behind the
  // one slice that most looks like it should not be there — a slice showing a chord and
  // doing nothing. Transpose still asks for a shift: it is the pitch systems that clash.
  const walked = walking
    || picked.some((item) => rearrangeRecipe.operations[item]?.chord != null);
  const part = rearrangeSelectedSectionIndex();
  menu.textContent = '';
  const head = document.createElement('div');
  head.className = 'remenuhead';
  head.textContent = many ? `${picked.length} slices` : `Slice ${index + 1}`;
  menu.append(head);
  const close = () => { menu.hidden = true; };
  const item = (label, handler, disabled = false) => {
    const button = document.createElement('button');
    button.type = 'button'; button.textContent = label; button.disabled = disabled;
    button.onclick = () => { close(); handler(); };
    menu.append(button);
    return button;
  };
  const sep = () => { const line = document.createElement('div'); line.className = 'remenusep'; menu.append(line); };

  // The two pitch systems, as rows of one-press choices rather than selects — a menu that
  // makes you open a second menu has not saved anyone anything. Both are here because
  // either can be the one you want, and which of them a slice is currently using is
  // exactly what you are looking at the block to find out.
  const label = (text) => { const el = document.createElement('div'); el.className = 'remenuhead';
    el.textContent = text; menu.append(el); };
  label('Transpose');
  const pitch = document.createElement('div');
  pitch.className = 'remenurow';
  // TWO ROWS, BY WHAT THE INTERVAL DOES RATHER THAN BY ITS SIZE. The top row is the moves
  // that keep a fragment sounding like itself — the fifth, the fourth, the tone — with Off
  // in the middle where it has always been, so the shape of the control somebody already
  // knows is still there and has simply grown a ±7 on each end. The second row is the ones
  // that recolour it: the thirds, and the semitone lift.
  //
  // The octave is deliberately absent. It is the one transpose that changes no note of the
  // material — same pitch classes, same chord, same everything but register — so it is the
  // one entry a row of quick musical choices gains nothing by carrying. Anything not here,
  // the octave included, is still on the inspector's full ±12 dial.
  const INTERVAL_NAMES = {
    1: 'a semitone', 2: 'a tone', 3: 'a minor third', 4: 'a major third',
    5: 'a fourth', 7: 'a fifth',
  };
  const pitchButton = (row, amount) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.textContent = amount === 0 ? 'Off' : amount > 0 ? `+${amount}` : String(amount);
    button.disabled = walking;
    button.title = walking ? 'These slices walk a chord loop; turn the walk off first'
      : amount === 0 ? 'Play at written pitch'
        : `Transpose ${INTERVAL_NAMES[Math.abs(amount)]} ${amount > 0 ? 'up' : 'down'} — ${Math.abs(amount)} semitones`;
    // Which one a slice is already on, marked exactly as the chord row below marks its
    // degree. The two rows are the same kind of control and have to read as one.
    button.classList.toggle('on', (op?.transpose || 0) === amount);
    button.onclick = () => { close(); transformSelectedRearrange('transpose', 'Slice transpose changed', { value: amount }); };
    row.append(button);
  };
  for (const amount of [-7, -5, -2, 0, 2, 5, 7]) pitchButton(pitch, amount);
  menu.append(pitch);
  const colour = document.createElement('div');
  colour.className = 'remenurow';
  for (const amount of [-4, -3, -1, 1, 3, 4]) pitchButton(colour, amount);
  menu.append(colour);
  // The CHORD the slices play, degree by degree. Turning a walk on gives a part a
  // progression; this is how one bar of it is argued with, and it was the thing the menu
  // could not do — you could switch a walk off but not change what it walked to.
  const minor = rearrangeRecipe?.key?.minor !== false;
  label(rearrangeRecipe?.key ? `Chord · ${rearrangeKeyName(rearrangeRecipe.key)}` : 'Chord · no key found');
  const chord = document.createElement('div');
  chord.className = 'remenurow';
  for (let degree = 0; degree < 7; degree += 1) {
    const button = document.createElement('button');
    button.type = 'button';
    button.textContent = degree === 0 ? '–' : harmonyNumeral(degree, minor);
    button.disabled = !rearrangeRecipe?.key;
    button.title = degree === 0 ? 'Play as written' : `Play the ${harmonyNumeral(degree, minor)} chord`;
    button.classList.toggle('on', (op?.harmony || 0) === degree);
    button.onclick = () => { close(); transformSelectedRearrange('harmony', 'Slice chord changed', { value: degree }); };
    chord.append(button);
  }
  menu.append(chord);
  item(walked ? `Chord walk off${many ? ` ×${picked.length}` : ''}` : 'Chord walk these slices', () => {
    if (walked) transformSelectedRearrange('walk-off', 'Chord walk off');
    else transformSelectedRearrange('walk-on', 'Chord walk on');
  }, part < 0);
  item('New chords', () => {
    const index = rearrangeSelectedSectionIndex();
    if (index >= 0) rerollRearrangeWalkUi(index);
  }, part < 0 || !walked);
  sep();
  item('🎲 New material', () => transformSelectedRearrange('reroll', 'New material under those slices'));
  item(op?.mute ? 'Unmute' : 'Mute', () => transformSelectedRearrange(op?.mute ? 'unmute' : 'mute',
    op?.mute ? 'Slices sounding' : 'Slices muted'));
  item('Stutter ×4', () => transformSelectedRearrange('stutter', 'Slice stuttered ×4', { value: '4' }));
  item('Split', () => transformSelectedRearrange('split', 'Slices split'));
  item('Join', () => transformSelectedRearrange('join', 'Slices joined'),
    picked.length < 2 || picked[picked.length - 1] - picked[0] !== picked.length - 1);
  sep();
  item('Copy', () => $('recopysection')?.click());
  item('Paste here', () => $('repastesection')?.click(), !rearrangeCopiedSection);
  item('Delete', () => transformSelectedRearrange('delete', 'Deleted slices'));
  sep();
  item('Play from here', () => playRearrangeSelection());

  menu.hidden = false;
  // Placed after it is measurable, and pulled back inside the window rather than off it.
  const width = menu.offsetWidth;
  const height = menu.offsetHeight;
  menu.style.left = `${Math.max(6, Math.min(event.clientX, window.innerWidth - width - 6))}px`;
  menu.style.top = `${Math.max(6, Math.min(event.clientY, window.innerHeight - height - 6))}px`;
}

/**
 * The part's right-click menu — everything about a whole part that is not worth an icon.
 *
 * The icons on the card are the four pressed constantly; these are the ones pressed
 * occasionally and deliberately, which is exactly the split a "more" menu is for. They
 * used to be a toolbar row at the bottom of the panel, so acting on the card under your
 * pointer meant travelling to the other end of the window and back.
 */
function openRearrangeMenuAt(anchor, build) {
  const menu = $('reslicemenu');
  if (!menu) return;
  menu.textContent = '';
  build(menu, () => { menu.hidden = true; });
  menu.hidden = false;
  const width = menu.offsetWidth;
  const height = menu.offsetHeight;
  // Under the button it belongs to, or at the pointer when there is no button — and
  // pulled back inside the window rather than hanging off it either way.
  const box = anchor?.getBoundingClientRect?.();
  const left = box ? box.left : (anchor?.clientX ?? 0);
  const top = box ? box.bottom + 4 : (anchor?.clientY ?? 0);
  menu.style.left = `${Math.max(6, Math.min(left, window.innerWidth - width - 6))}px`;
  menu.style.top = `${Math.max(6, Math.min(top, window.innerHeight - height - 6))}px`;
}

/** The rows shared by the little menus: a heading, an item, a rule. */
function rearrangeMenuParts(menu, close) {
  return {
    head: (text) => { const el = document.createElement('div'); el.className = 'remenuhead';
      el.textContent = text; menu.append(el); },
    item: (label, handler, disabled = false) => { const button = document.createElement('button');
      button.type = 'button'; button.textContent = label; button.disabled = disabled;
      button.onclick = () => { close(); handler(); }; menu.append(button); },
    sep: () => { const line = document.createElement('div'); line.className = 'remenusep'; menu.append(line); },
  };
}

/**
 * EVERYTHING A PART CAN BE TOLD TO DO, IN WORDS.
 *
 * The card's icons are for speed and they are learnable, but an icon is only ever a
 * reminder of something you already know — nobody reads ⌁ and thinks "fill". This is the
 * same set written out, opened by right-clicking the card — which is now the only way in.
 * The ⋯ button beside the icons opened this very menu, so it was a second door onto one
 * room, and it cost a slot in a row that has to stay readable at card width.
 */
function openRearrangePartMenu(event, index) {
  const section = rearrangeRecipe?.form?.[index];
  if (!section) return;
  const slices = rearrangeSectionOperationIndices(index);
  const walking = !!rearrangeSectionChordLine(index, 'roman');
  const locked = rearrangeLockedSections.has(index);
  const carries = slices.some((slice) => rearrangeRecipe.operations[slice]?.fill);
  const bars = Math.max(1, Math.round((section.end - section.start) / 16));
  openRearrangeMenuAt(event.currentTarget?.tagName === 'BUTTON' ? event.currentTarget : event, (menu, close) => {
    const { head, item, sep } = rearrangeMenuParts(menu, close);
    head(`${section.letter || ''} · ${section.name} · ${bars} bar${bars === 1 ? '' : 's'}`.trim());
    item('Play from here', () => playRearrangementAt(section.start, { part: index }));
    item('Hold this part', () => selectRearrangeSectionSlices(index));
    sep();
    item(locked ? 'Unlock — let the next Go rebuild it' : 'Lock — keep it verbatim through the next Go',
      () => toggleRearrangeLock(index));
    item('Rebuild this part from scratch', () => rerollRearrangeSectionMaterial(index));
    item('Regenerate separately from its twins', () => {
      if (!section.letter) return;
      rearrangeUniqueLetters.add(section.letter);
      toast(`${section.letter} will be built on its own at the next Go`);
      renderRearrangeList();
    }, !section.letter);
    sep();
    item('Halve this part — the song gets shorter',
      () => transformRearrangeSectionUi(index, 'halve', 'Section halved'));
    item('Double this part — the song gets longer',
      () => transformRearrangeSectionUi(index, 'double', 'Section doubled'));
    sep();
    head('Chord walk');
    item(walking ? 'Stop this part walking' : 'Walk this part around the song’s key',
      () => toggleRearrangeWalkUi(index));
    item('New chords for this part', () => rerollRearrangeWalkUi(index), !walking);
    sep();
    head('Fill at this part’s ending');
    for (const [value, name] of [['burst', 'Burst — the final beat'],
      ['rush', 'Rush — the final half-bar'], ['machinegun', 'Machine gun — the final bar']]) {
      item(name, () => transformRearrangeSectionUi(index, 'fill', `${name.split(' —')[0]} fill added`, { value }));
    }
    item('No fill at all', () => transformRearrangeSectionUi(index, 'fill', 'Fill removed', { value: 'none' }), !carries);
    sep();
    item('Save this part to the shelf', () => snapshotRearrangeClip(index));
    item('Delete this part', () => transformRearrangeSectionUi(index, 'delete', 'Part removed'),
      (rearrangeRecipe?.form?.length || 0) < 2);
  });
}


/** The fill at the part's ending, by shape. */
function openRearrangeFillMenu(event, index) {
  const section = rearrangeRecipe?.form?.[index];
  if (!section) return;
  const carries = rearrangeSectionOperationIndices(index)
    .some((slice) => rearrangeRecipe.operations[slice]?.fill);
  openRearrangeMenuAt(event.currentTarget, (menu, close) => {
    const { head, item } = rearrangeMenuParts(menu, close);
    head(`Fill this ending · ${section.letter || section.name}`);
    for (const [value, name] of [['burst', 'Burst · final beat'], ['rush', 'Rush · final half-bar'],
      ['machinegun', 'Machine gun · final bar']]) {
      item(name, () => transformRearrangeSectionUi(index, 'fill', `${name.split(' ·')[0]} fill added`, { value }));
    }
    item('No fill', () => transformRearrangeSectionUi(index, 'fill', 'Fill removed', { value: 'none' }), !carries);
  });
}

function closeRearrangeSliceMenu() {
  const menu = $('reslicemenu');
  if (menu && !menu.hidden) menu.hidden = true;
}

/** Which part the current selection sits in — what the toolbar's part-level controls aim at. */
function rearrangeSelectedSectionIndex() {
  const first = [...rearrangeSelectedOperations].sort((a, b) => a - b)[0];
  if (first == null) return -1;
  return rearrangeTimelineGeometry().ops[first]?.sectionIndex ?? -1;
}

/** Step back through M8TRX's own edits. Recipes are replaced wholesale rather than
 *  mutated, so the previous one IS the undo state and no snapshot is needed. */
function undoRearrange() {
  const previous = rearrangeUndoStack.pop();
  if (!previous) { toast('Nothing to undo on M8TRX'); return; }
  installRearrangement(previous, { announce: false, undoable: false,
    live: playing && rearrangeActive() });
  toast(rearrangePending ? 'M8TRX undo · from the next bar' : 'M8TRX undo');
}

/**
 * A start from scratch for the NEXT Generate, without leaving M8TRX or discarding the
 * recipe currently on the timeline. Locks, the shelf, and the repeated-letter opt-outs
 * are all "what should Generate do differently" state — the same bucket every other
 * reset in this panel already clears together (see `clearRearrangement`,
 * `loadRearrangeJson`) — so one button empties all three rather than three separate ones.
 */
function clearRearrangeKeptState() {
  if (!rearrangeLockedSections.size && !rearrangeClips.length && !rearrangeUniqueLetters.size) {
    toast('Nothing locked or on the shelf');
    return;
  }
  rearrangeLockedSections.clear();
  rearrangeClips.length = 0;
  rearrangeUniqueLetters.clear();
  renderRearrangeList();
  toast('Cleared every lock and the shelf');
}

/** Play from the selection's start, or from the top of the part when nothing is picked. */
function playRearrangeSelection() {
  if (!rearrangeRecipe) return;
  const geometry = rearrangeTimelineGeometry();
  const first = [...rearrangeSelectedOperations].sort((a, b) => a - b)[0];
  const at = first == null ? (rearrangeRecipe.form?.[0]?.start || 0) : (geometry.ops[first]?.start || 0);
  playRearrangementAt(at);
}

/** Let a repeated letter go its own way on the next Go. */
function makeRearrangeSectionUnique() {
  const sectionIndex = Math.max(0, rearrangeSelectedSectionIndex());
  const letter = rearrangeRecipe?.form?.[sectionIndex]?.letter;
  if (!letter) return;
  rearrangeUniqueLetters.add(letter);
  toast(`${letter} will be unique on the next Go`);
}

function toggleRearrangeOperation(index) {
  if (!rearrangeRecipe?.operations?.[index]) return;
  if (rearrangeSelectedOperations.has(index)) rearrangeSelectedOperations.delete(index);
  else rearrangeSelectedOperations.add(index);
  renderRearrangeList();
  syncRearrangeProgress(Audio.rearrangement ? Audio.step : null);
}

/** A plain click means "this one" — pressed again on the same lone slice, it lets go. */
function selectOneRearrangeOperation(index) {
  if (!rearrangeRecipe?.operations?.[index]) return;
  const only = rearrangeSelectedOperations.size === 1 && rearrangeSelectedOperations.has(index);
  rearrangeSelectedOperations.clear();
  if (!only) rearrangeSelectedOperations.add(index);
  renderRearrangeList();
  syncRearrangeProgress(Audio.rearrangement ? Audio.step : null);
}

function selectRearrangeOperationRange(from, to) {
  const low = Math.min(from, to);
  const high = Math.max(from, to);
  rearrangeSelectedOperations.clear();
  for (let index = low; index <= high; index += 1) {
    if (rearrangeRecipe?.operations?.[index]) rearrangeSelectedOperations.add(index);
  }
  renderRearrangeList();
  syncRearrangeProgress(Audio.rearrangement ? Audio.step : null);
}

/**
 * Dragging across the strip selects the run you dragged over.
 *
 * Delegated to the timeline once, so a re-render never orphans it, and painted straight
 * onto the elements while the pointer is down — rebuilding the whole timeline four times
 * a second under a moving finger would fight the drag it is trying to draw. The commit
 * at the end is the only render.
 */
function wireRearrangeTimelineSelection() {
  const timeline = $('rearrangeform');
  if (!timeline) return;
  let anchor = -1;
  let last = -1;
  let moved = false;
  // The double-click is counted HERE rather than left to the browser's own dblclick. A
  // single click selects, selecting re-renders the timeline, and the second click of a
  // pair therefore lands on a freshly built element — the browser never sees two clicks
  // on one target and dispatches nothing. It also meant the pair selected and then
  // deselected, so a double-click on a slice did precisely nothing at all.
  let lastSlice = -1;
  let lastAt = 0;
  const sliceAt = (x, y) => document.elementFromPoint(x, y)?.closest?.('.reslice');
  const paint = (from, to) => {
    const low = Math.min(from, to);
    const high = Math.max(from, to);
    for (const el of timeline.querySelectorAll('.reslice')) {
      const index = Number(el.dataset.operation);
      el.classList.toggle('selected', index >= low && index <= high);
    }
  };
  const finish = () => { anchor = -1; last = -1; moved = false; };
  timeline.addEventListener('contextmenu', (event) => {
    const slice = event.target.closest?.('.reslice');
    if (slice) {
      event.preventDefault();
      openRearrangeSliceMenu(event, Number(slice.dataset.operation));
      return;
    }
    const card = event.target.closest?.('.reformseg');
    if (!card) return;
    event.preventDefault();
    openRearrangePartMenu(event, Number(card.dataset.section));
  });
  timeline.addEventListener('pointerdown', (event) => {
    closeRearrangeSliceMenu();
    if (event.button !== 0) return;
    const slice = event.target.closest?.('.reslice');
    if (!slice) return;
    anchor = Number(slice.dataset.operation);
    last = anchor;
    moved = false;
    try { timeline.setPointerCapture(event.pointerId); } catch { /* capture is a nicety */ }
  });
  timeline.addEventListener('pointermove', (event) => {
    if (anchor < 0) return;
    // Capture pins event.target to the element the drag started on, so the slice under
    // the pointer has to be asked for by position rather than read off the event.
    const slice = sliceAt(event.clientX, event.clientY);
    if (!slice) return;
    const index = Number(slice.dataset.operation);
    if (!Number.isInteger(index) || index === last) return;
    last = index;
    if (index !== anchor) moved = true;
    paint(anchor, index);
  });
  timeline.addEventListener('pointerup', (event) => {
    if (anchor < 0) return;
    const from = anchor;
    const to = last;
    const dragged = moved;
    finish();
    try { timeline.releasePointerCapture(event.pointerId); } catch { /* already released */ }
    if (dragged) { lastSlice = -1; selectRearrangeOperationRange(from, to); return; }
    const doubled = from === lastSlice && performance.now() - lastAt < 400;
    lastSlice = from;
    lastAt = performance.now();
    if (doubled) {
      // Keep it held — the first click of the pair took it, and letting the second one
      // put it back down is how "play from here" used to lose its own selection.
      if (!rearrangeSelectedOperations.has(from)) {
        rearrangeSelectedOperations.clear();
        rearrangeSelectedOperations.add(from);
      }
      playRearrangementAt(rearrangeTimelineGeometry().ops[from]?.start || 0);
      renderRearrangeList();
      return;
    }
    if (event.ctrlKey || event.metaKey || event.shiftKey) toggleRearrangeOperation(from);
    else selectOneRearrangeOperation(from);
  });
  timeline.addEventListener('pointercancel', () => { finish(); renderRearrangeList(); });
}

function clearRearrangeOperationSelection() {
  rearrangeSelectedOperations.clear();
  renderRearrangeList();
}

/**
 * Why an edit did nothing, in the terms of the slices actually in hand.
 *
 * "Needs a longer slice or a compatible repeat count" covers every refusal and explains
 * none of them; a person holding four slices wants to know which of the four was the
 * problem and what about it. Everything here is read off the selection, so the answer
 * names real numbers.
 */
function rearrangeEditRefusal(action, indices, options = {}) {
  const ops = indices.map((index) => rearrangeRecipe?.operations?.[index]).filter(Boolean);
  if (!ops.length) return 'Select one or more slices first.';
  const many = ops.length > 1;
  const these = many ? `these ${ops.length} slices are` : 'this slice is';
  switch (action) {
    case 'split':
      return `Nothing to halve — ${these} already one sixteenth long.`;
    case 'repeat-more':
      return `Already at four passes, which is as many as a slice may take.`;
    case 'repeat-less':
      return `${many ? 'These slices' : 'This slice'} already ${many ? 'play' : 'plays'} once, so there is no pass to remove.`;
    case 'unroll':
      return `${many ? 'These slices' : 'This slice'} already ${many ? 'play' : 'plays'} once each — there are no repeats to separate.`;
    case 'join':
      return indices.length < 2
        ? 'Join needs two or more slices; pick a run of them.'
        : 'Join needs slices that sit next to each other.';
    case 'stutter': {
      const count = Number(options.value);
      const shape = REARRANGE_STUTTER_SHAPES[String(options.value)];
      const parts = shape ? shape.reduce((sum, weight) => sum + weight, 0) : count;
      const lengths = [...new Set(ops.map((op) => op.length * op.repeats))].join(', ');
      return `That rhythm needs ${parts} equal parts, and ${lengths} sixteenths does not divide by ${parts}.`;
    }
    case 'harmony':
      return rearrangeRecipe?.key
        ? 'That chord is out of range for this key.'
        : 'No key was detected for this song, so there is nothing to move a chord within.';
    case 'transpose':
      return ops.some((op) => op.harmony)
        ? 'These slices walk a chord loop; turn the walk off before transposing them.'
        : 'That transpose is not available for these slices.';
    case 'mute':
    case 'unmute':
      return `${many ? 'These slices are' : 'This slice is'} already ${action === 'mute' ? 'silent' : 'sounding'}.`;
    case 'reroll':
      return 'No other material on this grid fits these slices.';
    default:
      return `${many ? 'These slices' : 'This slice'} cannot take that edit.`;
  }
}

/**
 * Reroll one part's material, whatever is selected.
 *
 * The card's buttons act on the part they are drawn on — that is what a card is — so
 * this deliberately does NOT go through the selection. Rerolling the chorus you clicked
 * while three verse slices happen to be held would be the panel doing something other
 * than what the button under your finger says.
 */
function rerollRearrangeSectionMaterial(sectionIndex) {
  if (!rearrangeRecipe) { toast('Press Go ▸ to build an M8TRX recipe first'); return; }
  const name = rearrangeRecipe.form?.[sectionIndex]?.name || 'this part';
  try {
    const result = regenerateRearrangementSection(rearrangeRecipe, sectionIndex, {
      seed: randomSeed(),
      style: rearrangeStyle(),
      grain: rearrangeGrain(),
      form: rearrangeForm(),
      mood: rearrangeMood(),
      hypnosis: rearrangeHypnosis(),
      chaos: rearrangeChaos(),
      drive: rearrangeDrive(),
      progression: rearrangeChordLoop(),
      key: rearrangeKeyChoice(),
      transposeAmount: rearrangeTransposeAmount(),
      sourceProfile: rearrangeGenerationProfile(),
      locked: rearrangeLockedSections.has(sectionIndex),
    });
    if (!result.changed) { toast(`${name} could not be rebuilt`); return; }
    applyRearrangeEdit(result.recipe,
      `${name} rebuilt · ${result.changed} slice${result.changed === 1 ? '' : 's'}`);
  } catch (error) {
    toast(error?.message || `Could not roll ${name}`);
  }
}

function transformSelectedRearrange(action, label, options = {}) {
  if (!rearrangeRecipe) { toast('Press Go ▸ to build an M8TRX recipe first'); return; }
  if (!rearrangeSelectedOperations.size) { toast('Select one or more Rearrange slices first'); return; }
  try {
    // Reroll is the only transform that makes a musical choice rather than performing a
    // named operation, so it is the only one handed the panel's dials — and it is handed
    // them live, at the press, not the values Generate happened to run under. The others
    // do exactly what their word says and would only be given controls they ignore.
    const creative = action === 'reroll' ? {
      profile: rearrangeGenerationProfile(),
      key: rearrangeKeyChoice() || rearrangeRecipe.key || null,
      style: rearrangeStyle(),
      grain: rearrangeGrain(),
      form: rearrangeForm(),
      mood: rearrangeMood(),
      hypnosis: rearrangeHypnosis(),
      chaos: rearrangeChaos(),
      drive: rearrangeDrive(),
    } : { profile: null };
    const result = transformRearrangement(rearrangeRecipe,
      [...rearrangeSelectedOperations], action, {
        seed: randomSeed(),
        ...creative,
        ...options,
      });
    if (!result.changed) {
      toast(rearrangeEditRefusal(action, [...rearrangeSelectedOperations], options));
      return;
    }
    applyRearrangeEdit(result.recipe,
      `${label} · changed ${result.changed} slice${result.changed === 1 ? '' : 's'}`);
  } catch (error) {
    toast(error?.message || `Could not ${label.toLowerCase()}`);
  }
}

function setRearrangeDrums(next) {
  if (!rearrangeRecipe) { toast('Press Go ▸ to build an M8TRX recipe first'); return; }
  if (!REARRANGE_DRUM_MODES.includes(next)) return;
  const recipe = { ...rearrangeRecipe };
  // No field still means the chopped-source behaviour, so a saved recipe stays
  // readable by anything that only knows the original two modes.
  if (next === 'original') delete recipe.drums;
  else recipe.drums = next;
  applyRearrangeEdit(recipe, `Rearrange drums · ${REARRANGE_DRUM_LABELS[next].toLowerCase()}`);
}

function toggleRearrangeLock(sectionIndex) {
  if (!rearrangeRecipe?.form?.[sectionIndex]) return;
  if (rearrangeLockedSections.has(sectionIndex)) rearrangeLockedSections.delete(sectionIndex);
  else rearrangeLockedSections.add(sectionIndex);
  renderRearrangeTimeline();
  // The timeline redraws the card's own lock glyph; the toolbar's Clear-kept-state
  // button also reads `rearrangeLockedSections.size` and needs the same nudge, or it
  // sits disabled right after the very lock that should have woken it up.
  renderRearrangeInspector();
  toast(rearrangeLockedSections.has(sectionIndex)
    ? `Locked ${rearrangeRecipe.form[sectionIndex].letter || rearrangeRecipe.form[sectionIndex].name}`
    : 'Section unlocked');
}

function grabRearrangeSection() {
  if (!rearrangeRecipe || !playing) { toast('Play M8TRX, then lock what is playing'); return; }
  const position = Audio.rearrangementPosition(Audio.step);
  if (position?.formIndex != null) {
    rearrangeLockedSections.add(position.formIndex);
    renderRearrangeTimeline();
    renderRearrangeInspector();
    toast(`Locked the heard section ${position.form?.letter || position.form?.name || ''}`.trim());
  }
}

function transformRearrangeSectionUi(index, action, label, options = {}) {
  if (!rearrangeRecipe) return;
  try {
    const result = transformRearrangementSection(rearrangeRecipe, index, action, {
      seed: randomSeed(), ...options,
    });
    if (!result.changed) { toast(`${label} is not available for this section`); return; }
    applyRearrangeEdit(result.recipe, label);
  } catch (error) { toast(error?.message || `Could not ${label.toLowerCase()}`); }
}

function toggleRearrangeWalkUi(index) {
  if (!rearrangeRecipe) return;
  try {
    // The key the PANEL is showing, not only the one the recipe happens to carry — see
    // rearrangeEffectiveKey. A recipe generated without walks carries no key at all.
    const result = toggleRearrangeSectionWalk(rearrangeRecipe, index,
      { key: rearrangeEffectiveKey(), profile: rearrangeGenerationProfile() });
    applyRearrangeEdit(result.recipe, 'Chord walk toggled');
  } catch (error) { toast(error?.message || 'Could not toggle the chord walk'); }
}

function rerollRearrangeWalkUi(index) {
  if (!rearrangeRecipe) return;
  try {
    const result = rerollSectionWalk(rearrangeRecipe, index,
      { seed: randomSeed(), key: rearrangeEffectiveKey(), profile: rearrangeGenerationProfile() });
    applyRearrangeEdit(result.recipe, 'Chord walk rerolled');
  } catch (error) { toast(error?.message || 'Could not reroll the chord walk'); }
}

function rearrangeKeptAnchors() {
  if (!rearrangeRecipe?.form?.length || !rearrangeLockedSections.size) return [];
  const anchors = [];
  for (const index of rearrangeLockedSections) {
    const section = rearrangeRecipe.form[index];
    if (!section) continue;
    let output = 0;
    const operations = [];
    let complete = true;
    for (const operation of rearrangeRecipe.operations) {
      const end = output + operation.length * operation.repeats;
      if (output >= section.start && end <= section.end) operations.push({ ...operation });
      else if (output < section.end && end > section.start) complete = false;
      output = end;
    }
    if (complete && operations.length) {
      anchors.push({ index, role: section.role, letter: section.letter,
        steps: section.end - section.start, operations });
    }
  }
  return anchors;
}

function rearrangeSectionOperations(sectionIndex) {
  const section = rearrangeRecipe?.form?.[sectionIndex];
  if (!section) return [];
  let output = 0;
  const operations = [];
  for (const operation of rearrangeRecipe.operations) {
    const end = output + operation.length * operation.repeats;
    if (output >= section.start && end <= section.end) operations.push({ ...operation });
    output = end;
  }
  return operations;
}

function syncRearrangeProgress(outputStep = null) {
  if (rearrangeRecipe && !Audio.rearrangement) {
    rearrangeRecipe = null;
    rearrangeLockedSections.clear();
    rearrangeUniqueLetters.clear();
    syncRearrangeButton();
    syncRearrangeLoopControls();
    renderRearrangeList();
  }
  if (!rearrangeRecipe) return;
  const pos = outputStep == null ? null : Audio.rearrangementPosition(outputStep);
  document.querySelectorAll('#rearrangeform .reslice.active').forEach((el) => {
    el.classList.remove('active');
    el.style.removeProperty('--replayed');
  });
  document.querySelectorAll('#rearrangeform .reformseg.active').forEach((el) => el.classList.remove('active'));
  // The queued jump's destination, marked until the scheduler actually takes it. Cleared
  // by the ENGINE having let go of it, never by a timer here: the bar line is the
  // engine's to decide and a self-timed clear would stop pulsing while still waiting.
  document.querySelectorAll('#rearrangeform .seeking').forEach((el) => el.classList.remove('seeking'));
  if (rearrangeSeekStep != null) {
    if (Audio.pendingStep == null) { rearrangeSeekStep = null; rearrangeSeekPart = null; }
    else if (rearrangeSeekPart != null) {
      document.querySelector(`#rearrangeform .reformseg[data-section="${rearrangeSeekPart}"]`)
        ?.classList.add('seeking');
    } else {
      const heading = Audio.rearrangementPosition(rearrangeSeekStep);
      if (heading) {
        document.querySelector(`#rearrangeform .reslice[data-operation="${heading.operationIndex}"]`)
          ?.classList.add('seeking');
      }
    }
  }
  if (pos) {
    const row = document.querySelector(`#rearrangeform .reslice[data-operation="${pos.operationIndex}"]`);
    row?.classList.add('active');
    // How far through the sounding slice the playhead is, as the width of the bar drawn
    // under it. One style write on one element per tick: the block says which slice, the
    // bar says where inside it, and neither needs a redraw of the timeline to say so.
    if (row) {
      const span = Math.max(1, pos.outputEnd - pos.outputStart + 1);
      row.style.setProperty('--replayed',
        Math.min(1, Math.max(0, (pos.outputStep - pos.outputStart + 1) / span)).toFixed(3));
    }
    // Follow the playhead: when the active row CHANGES and the listener has not just
    // scrolled by hand, bring it into view. 'nearest' only moves the list when the row
    // is actually outside it, so a list that fits entirely never twitches — and only
    // on the change, so the four-times-a-second progress tick cannot pin the scroll
    // position against a reader's thumb.
    if (row && pos.operationIndex !== rearrangeFollowedRow
      && performance.now() >= rearrangeFollowHeldUntil) {
      row.scrollIntoView({ block: 'nearest' });
    }
    rearrangeFollowedRow = pos.operationIndex;
  } else {
    rearrangeFollowedRow = -1;
  }
  if (pos?.formIndex != null) {
    const seg = document.querySelector(`#rearrangeform .reformseg[data-section="${pos.formIndex}"]`);
    seg?.classList.add('active');
  }
  if (pos) {
    const mode = rearrangementDrumMode(rearrangeRecipe);
    $('rearrangestatus').textContent = `${pos.form?.name ? `${pos.form.name} · ` : ''}Operation ${pos.operationIndex + 1}/${rearrangeRecipe.operations.length} · repetition ${pos.repeatIndex + 1}/${pos.operation.repeats}`
      + ` · source ${rearrangeOutputLabel(pos.sourceStep)}`
      + rearrangeHarmonyLabel(pos.operation)
      + ` · ${rearrangeDrumLabel(mode).toLowerCase()}`
      + (rearrangePending ? ' · edit lands next bar' : '')
      + (rearrangeSelectedOperations.size ? ` · ${rearrangeSelectedOperations.size} selected` : '');
  }
}

/**
 * Put a recipe on the desk, and on the audio.
 *
 * `live` means this is an edit to something already playing, and then the engine takes
 * it as a queued install: the bar being heard finishes as the bar it was promised to
 * be, and the next one is the new arrangement. The desk's draft changes immediately
 * either way — the panel shows what you have made, marked as not yet heard until it is.
 */
function installRearrangement(recipe, { announce = true, live = false, undoable = true } = {}) {
  if (undoable && rearrangeRecipe && rearrangeRecipe !== recipe) {
    rearrangeUndoStack.push(rearrangeRecipe);
    if (rearrangeUndoStack.length > REARRANGE_UNDO_DEPTH) rearrangeUndoStack.shift();
  }
  rearrangeRecipe = recipe;
  rearrangeSelectedOperations.clear();
  Audio.rearrangeLoop = rearrangeLoopOn;
  if (live) rearrangePending = Audio.queueRearrangement(recipe) === 'queued';
  else { Audio.setRearrangement(recipe); rearrangePending = false; }
  syncRearrangeButton();
  syncRearrangeLoopControls();
  renderRearrangeList();
  syncRearrangeDrumControl();
  if (announce) toast(`Rearrange ready · ${recipe.operations.length} operations`);
}

/**
 * Change the collage without interrupting it.
 *
 * Every edit on this panel goes through here. Nobody auditions an arrangement by
 * restarting it after each change, so while Rearrange is playing an edit is queued for
 * the next output bar instead of stopping the transport, re-seeking, and counting four
 * beats in again. Stopped, it simply lands.
 */
function applyRearrangeEdit(recipe, message = '') {
  // An edit that leaves the slice COUNT alone leaves every index meaning what it meant,
  // so the selection survives it. The slice controls live in the inspector now, and an
  // inspector that emptied itself after each press would make "+ + +" three selections
  // and three presses. A count-changing edit still clears: those indices are gone.
  const held = rearrangeRecipe?.operations?.length === recipe?.operations?.length
    ? [...rearrangeSelectedOperations] : null;
  installRearrangement(recipe, { announce: false, live: playing && rearrangeActive() });
  if (held?.length) {
    held.forEach((index) => rearrangeSelectedOperations.add(index));
    renderRearrangeList();
  }
  if (message) toast(rearrangePending ? `${message} · from the next bar` : message);
}

function clearRearrangement({ announce = true } = {}) {
  rearrangeRecipe = null;
  rearrangeSeekStep = null;
  rearrangeSeekPart = null;
  rearrangeCopiedSection = null;
  rearrangeUndoStack.length = 0;
  rearrangeSelectedOperations.clear();
  rearrangeLockedSections.clear();
  rearrangeUniqueLetters.clear();
  rearrangePending = false;
  Audio.setRearrangement(null);
  // THE DRUMS MENU GOES BACK TO ITS DEFAULT WITH THE RECIPE IT BELONGED TO. Its row is
  // hidden while there is no recipe (see `.norecipe` in the shell), and a control you
  // cannot see must not be holding the next Go to anything — the desk's rule is that every
  // key an engine path reads has a pot you can find. Left as it was, a hidden menu still
  // reading "Techno" would build techno drums at the next Go with nothing on screen saying
  // so. Chopped is the neutral setting: it writes no `drums` field at all.
  rearrangeDrumsChoice = 'original';
  syncRearrangeButton();
  syncRearrangeLoopControls();
  renderRearrangeList();
  syncRearrangeDrumControl();
  if (announce) toast('Returned to the normal song');
}

function generateRearrangeRecipe({ restart = false, freshSeed = false } = {}) {
  // Regenerating while the collage plays is how this is actually used: listen, press
  // Generate, hear the next bar as a different arrangement. That path never stops the
  // transport. Only a normal song playing underneath still has to be handed over.
  const live = playing && rearrangeActive();
  const wasPlaying = playing && !live;
  if (wasPlaying) setPlaying(false);
  const steps = rearrangeSourceSteps();
  // The pin holds THIS recipe's seed, so moving a dial reshapes the song you are already
  // listening to. The dice passes `freshSeed` and rolls past the pin without releasing it
  // — a lucky dip is meant to be a new song, and the one it lands on becomes the held one.
  const seed = !freshSeed && rearrangeSeedHold && rearrangeRecipe
    ? rearrangeRecipe.seed : randomSeed();
  let recipe;
  try {
    recipe = generateRearrangement(steps, {
      seed,
      style: rearrangeStyle(),
      grain: rearrangeGrain(),
      form: rearrangeForm(),
      mood: rearrangeMood(),
      hypnosis: rearrangeHypnosis(),
      chaos: rearrangeChaos(),
      drive: rearrangeDrive(),
      progression: rearrangeChordLoop(),
      fill: rearrangeFill(),
      uniqueLetters: [...rearrangeUniqueLetters],
      letterTemplates: Object.fromEntries(rearrangeClips
        .filter((clip) => /^[A-Z]$/.test(clip.letter || ''))
        .map((clip) => [clip.letter, {
        steps: clip.steps, operations: clip.operations, key: clip.key,
        resizable: !!clip.resizable, verbatim: !!clip.verbatim,
        }])),
      outputSteps: rearrangeOutputSteps(),
      key: rearrangeKeyChoice(),
      transposeAmount: rearrangeTransposeAmount(),
      sourceProfile: rearrangeGenerationProfile(),
      anchors: rearrangeKeptAnchors(),
      favourites: rearrangeFavourites,
    });
  } catch (error) {
    toast(error?.message || 'Could not fit those Rearrange favourites');
    if (wasPlaying) setPlaying(true);
    return;
  }
  recipe.source.song = trackId;
  recipe.source.title = track?.title || trackId;
  // Auto resolves to a real kit HERE, before the recipe is installed or saved, so the
  // word 'auto' never reaches a file, the validator, or the engine.
  const kit = rearrangeDrumsChoice === 'auto'
    ? driveDrumKit(rearrangeDrive()) : rearrangeDrumsChoice;
  if (kit && kit !== 'original') recipe.drums = kit;
  // A PRESS THAT CHANGES NOTHING HAS TO SAY SO. The primary greys out for this case before
  // you can press it (see syncRearrangeSeedHold), so reaching here means something changed
  // the signature without changing a slice — a dial nudged and put back, a setting the
  // generator ignored at this key. Kept as the backstop, because "it did nothing and said
  // nothing" is the failure this whole pair of controls is trying to avoid.
  if (rearrangeSeedHold && rearrangeRecipe
      && JSON.stringify(recipe.operations) === JSON.stringify(rearrangeRecipe.operations)
      && JSON.stringify(recipe.form) === JSON.stringify(rearrangeRecipe.form)) {
    toast('Same settings, same arrangement — move a dial to reshape it, or turn off '
      + '“Vary this one” for a different one', 4200);
    rearrangeBuiltFrom = rearrangeGenerationSignature();
    syncRearrangeSeedHold();
    if (wasPlaying) setPlaying(true);
    return;
  }
  // What this recipe was built from, so the panel knows when you have moved on from it.
  rearrangeBuiltFrom = rearrangeGenerationSignature();
  installRearrangement(recipe, { announce: false, live });
  syncRearrangeSeedHold();
  if (live) {
    toast(rearrangePending
      ? `New arrangement · ${recipe.operations.length} slices, from the next bar`
      : `New arrangement · ${recipe.operations.length} slices`);
  } else if (wasPlaying || restart) playRearrangement();
  else toast(`Generated ${recipe.operations.length} Rearrange operations`);
}

/**
 * LUCKY DIP. Roll the four dials somewhere musical, roll a fresh seed, and generate.
 *
 * Not uniform: a uniform roll spends most of its time in the corners, and the corners
 * are where this stops being music. Mood is the exception and roams the whole range —
 * every reading of it is a real song. The other three are drawn towards the middle,
 * Drive never quite sleeps or redlines, and the one genuinely bad corner — feral
 * material with nothing repeating — is pulled back rather than shipped.
 *
 * `Math.random` on purpose. The recipe stays reproducible from the seed written into
 * it; the dip is the one throw that is meant to be unrepeatable.
 */
function luckyDip() {
  // Two rolls subtracted give a triangular distribution: peaked at the centre, still
  // able to reach the ends, and one line of arithmetic.
  const towardsMiddle = (centre, spread) => centre + (Math.random() - Math.random()) * spread;
  const snap = (value) => Math.max(0, Math.min(100, Math.round(value / 5) * 5));
  const rolled = {
    mood: snap(Math.random() * 100),
    hypnosis: snap(towardsMiddle(55, 45)),
    chaos: snap(towardsMiddle(45, 35)),
    drive: snap(15 + Math.random() * 70),
  };
  if (rolled.chaos >= 70 && rolled.hypnosis <= 25) rolled.hypnosis = 40;
  for (const [name, value] of Object.entries(rolled)) {
    const control = $(REARRANGE_DIALS[name].id);
    if (control) control.value = String(value);
  }
  syncRearrangeDials();
  syncRearrangeKeyReadout();
  syncRearrangeDrumControl();
  const words = Object.entries(rolled)
    .map(([name, value]) => REARRANGE_DIALS[name].words[rearrangeDialBand(value)]);
  toast(`Lucky dip · ${words.join(', ')}`);
  generateRearrangeRecipe({ restart: rearrangeActive() && playing, freshSeed: true });
}

/** The pin: held is a state, so it lights up and says which way it will go next. */
function syncRearrangeSeedHold() {
  const button = $('reseedhold');
  if (!button) return;
  button.classList.toggle('on', rearrangeSeedHold);
  button.setAttribute('aria-pressed', rearrangeSeedHold ? 'true' : 'false');
  // NO "SEED", NO "ROLL". Both are words for the machinery, and the machinery is not what
  // anyone is asking about — the question is "if I nudge Drive and press Go, do I get this
  // song again but pushier, or do I get a different song?" So the tooltip answers that, in
  // those terms, and says what it is FOR: hearing what one dial did.
  button.title = rearrangeSeedHold
    ? 'On: Go keeps the arrangement you are hearing and changes only what the dials ask for — so you can move one dial and hear what that dial did. Turn it off to get a completely different arrangement on every press.'
    : 'Every press of Go builds a completely different arrangement. Turn this on and Go keeps the one you are hearing instead, changing only what the dials ask for — so you can move one dial and hear what that dial did.';
  // THE PRIMARY SAYS WHICH OF ITS TWO JOBS IT IS ABOUT TO DO. This pin used to be a claim
  // about invisible state — you pressed it and nothing on screen changed — and the button it
  // governs was called "Go", which is a word for pressing rather than for what happens. Now
  // the pin's effect is the primary's LABEL, so the pair explains itself without a tooltip.
  const primary = $('regenerate');
  if (!primary) return;
  // "New variation" over-promised: with the pin on, the seed and the dials ARE the inputs,
  // so a press that follows no dial move rebuilds the identical thing. What the press
  // actually does in that mode is apply wherever the dials are now to the arrangement you
  // are holding — so it says that, and a press that would change nothing says so too.
  primary.textContent = rearrangeSeedHold ? 'Reshape this one ▸' : 'New arrangement ▸';
  // THE BUTTON THAT WOULD DO NOTHING IS THE ONE THAT GREYS OUT — not the pin above it.
  //
  // With the arrangement held, the seed and every dial are the inputs they already were, so
  // a press before you have moved anything rebuilds a bit-identical recipe. Disabling it
  // says that in advance instead of after the fact, and it teaches the mechanism: move a
  // dial and the button lights.
  //
  // Deliberately NOT the pin. The pin is armed BEFORE you know which dial you are about to
  // move — "keep this one" is a decision about the arrangement you are hearing — so a pin
  // that only enabled once a dial had moved would be unavailable at the exact moment you
  // reach for it, and would force the two presses into the wrong order.
  const spent = rearrangeSeedHold && !!rearrangeRecipe
    && rearrangeBuiltFrom === rearrangeGenerationSignature();
  primary.disabled = spent;
  primary.title = !rearrangeSeedHold
    ? 'Build a completely new arrangement from these settings — while playing, it is heard from the next bar'
    : spent
      ? 'Nothing to reshape yet — move a dial and this lights up. Or turn off “Vary this one” for a completely different arrangement.'
      : 'Rebuild the arrangement you are hearing with the dials where they are now — while playing, it is heard from the next bar';
}

function playRearrangement() {
  if (!rearrangeRecipe) generateRearrangeRecipe();
  if (!rearrangeRecipe) return;
  if (playing) setPlaying(false);
  // Asking to hear it from the top means hearing the draft, so any queued edit is
  // taken now rather than waiting for a bar line in a pass that no longer exists.
  rearrangePending = false;
  Audio.setRearrangement(rearrangeRecipe);
  syncRearrangeLoopControls();
  setPlaying(true, 0, { countIn: 4 });
  toast('Playing Rearrange from the beginning');
}

function playRearrangementAt(outputStep, { part = null } = {}) {
  if (!rearrangeRecipe) return;
  const total = rearrangeRecipe.output?.steps || rearrangeSourceSteps();
  const at = ((Math.floor(Number(outputStep) || 0) % total) + total) % total;
  // ALREADY PLAYING IS A SEEK, NOT A RESTART. Stopping the transport and starting it again
  // at the new position is audible as a stop and a start — which is the wrong answer when
  // the music is running and you have pointed at the bar you want next. The bar being
  // heard finishes, and the jump lands on its line, the same way clicking the song's own
  // timeline behaves. The slice you aimed at pulses until it arrives, because a jump that
  // waits has to say that it is waiting or it reads as a click that missed.
  if (playing && rearrangeActive()) {
    rearrangePending = false;
    Audio.setRearrangement(rearrangeRecipe);
    Audio.setStepAtBoundary(at);
    rearrangeSeekStep = at;
    // Aiming at a PART flashes the part. Marking only the slice its first bar happens to
    // land in would answer a question nobody asked — you pointed at a section, and what is
    // being waited for is the section.
    rearrangeSeekPart = part;
    syncRearrangeProgress(Audio.rearrangement ? Audio.step : null);
    toast(`Playing from ${rearrangeOutputLabel(at)} at the next bar`);
    return;
  }
  if (playing) setPlaying(false);
  // Jumping somewhere is asking to hear the draft from there, so it installs at once.
  rearrangePending = false;
  rearrangeSeekStep = null;
  rearrangeSeekPart = null;
  Audio.setRearrangement(rearrangeRecipe);
  syncRearrangeLoopControls();
  // No count-in here: only the deliberate from-the-top start gets four beats. Auditioning
  // a section is a jump, and a jump that answers four beats late stops being aimable.
  setPlaying(true, at);
  toast(`Playing Rearrange from ${rearrangeOutputLabel(at)}`);
}

function returnToSong() {
  if (playing) setPlaying(false);
  clearRearrangement({ announce: false });
  // RETURNING TO THE SONG MEANS LEAVING M8TRX. Clearing the recipe without closing the panel
  // left its chrome across the whole window over an empty timeline — which was survivable
  // while the panel was a small inset window and is not now that it covers the desk edge to
  // edge. Its own label says return to the SONG, and the song is what is underneath.
  closeRearrangePanel();
  Audio.step = 0;
  parkedAt = 0;
  applyLoop(0);
  toast('Returned to the normal song');
}

function saveRearrangeJson() {
  if (!rearrangeRecipe) { toast('Press Go ▸ to build an M8TRX recipe first'); return; }
  const stamp = new Date().toISOString().slice(0, 16).replace(/[:T]/g, '-');
  const name = `${track?.slug || trackId}-rearrange-${stamp}.json`;
  // `editor` rides ON the recipe object rather than wrapping it, because a JSON export's
  // top level IS the recipe by contract (`validateRearrangement` reads `kind` straight off
  // it) — a caller loading this file with an older build, or feeding it to a tool that
  // only knows the recipe schema, sees exactly what it always saw. Omitted entirely when
  // there is nothing to carry, so an untouched recipe exports as lean as it always did.
  const editor = rearrangeEditorSnapshot();
  const payload = { ...JSON.parse(JSON.stringify(rearrangeRecipe)), ...(editor ? { editor } : {}) };
  saveBlob(name, new Blob([`${JSON.stringify(payload, null, 2)}\n`], { type: 'application/json' }));
  toast(`Saved ${name}${editor ? ' with locks and shelf' : ''}`);
}

/**
 * The desk settings that BUILT a recipe, saved beside it.
 *
 * A recipe is a finished arrangement; the dials are the question that produced it, and
 * coming back to a parked version to find the dials at their factory positions loses
 * the more useful half — the recipe you can hear is right there, but the settings you
 * would tweak to get the next one are gone. Stored in desk units (0–100), because that
 * is the reading on the control and the same reading has to mean the same thing.
 */
/**
 * The generator inputs, as one comparable string.
 *
 * Everything the recipe was BUILT from and nothing else: drums are applied after generation
 * and the pin is a mode rather than an input, so neither belongs here — including them would
 * make the primary light up for a change that cannot alter a single slice.
 */
function rearrangeGenerationSignature() {
  const { drums, seedHold, ...built } = rearrangeSettingsSnapshot();
  return JSON.stringify(built);
}

function rearrangeSettingsSnapshot() {
  const dial = (name) => Number($(REARRANGE_DIALS[name].id)?.value ?? '');
  return {
    mood: dial('mood'), hypnosis: dial('hypnosis'), chaos: dial('chaos'), drive: dial('drive'),
    style: rearrangeStyle(),
    grain: rearrangeGrain(),
    form: rearrangeForm(),
    length: $('relength')?.value ?? '1',
    drums: rearrangeDrumsChoice,
    key: $('rekey')?.value ?? 'auto',
    fill: $('refill')?.value ?? REARRANGE_FILL_DEFAULT,
    transpose: Number($('retranspose')?.value ?? 0),
    seedHold: rearrangeSeedHold,
  };
}

/**
 * Locks, the shelf, and repeated-letter opt-outs, saved beside a recipe.
 *
 * These are the other half of what a returning session needs back: the recipe is the
 * result, but locks/shelf/uniqueLetters are what the NEXT Generate would have used —
 * losing them on save is losing exactly the editorial work that got here. Omitted
 * entirely when there is nothing to carry, so an untouched recipe still saves as lean
 * as it always did.
 */
function rearrangeEditorSnapshot() {
  const locks = [...rearrangeLockedSections].sort((a, b) => a - b);
  const shelf = rearrangeClips.map((clip) => ({
    label: clip.label,
    letter: clip.letter || '',
    steps: clip.steps,
    operations: clip.operations.map((operation) => ({ ...operation })),
    resizable: !!clip.resizable,
    verbatim: !!clip.verbatim,
    ...(clip.key ? { key: { ...clip.key } } : {}),
  }));
  const uniqueLetters = [...rearrangeUniqueLetters];
  return (locks.length || shelf.length || uniqueLetters.length)
    ? { locks, shelf, uniqueLetters } : null;
}

/**
 * A shelf item read back from a file is untrusted the same way a loaded recipe is: it
 * came from disk, possibly hand-edited, possibly from an older build. This is basic
 * shape and bounds only, not the recipe validator's job repeated — just enough that a
 * malformed entry is dropped rather than handed to the generator as a from/length pair
 * that could point outside the song or crash the next Go.
 */
function sanitizeRearrangeClip(raw, sourceSteps) {
  if (!raw || typeof raw !== 'object') return null;
  const steps = Number(raw.steps);
  if (!Number.isInteger(steps) || steps <= 0) return null;
  if (!Array.isArray(raw.operations) || !raw.operations.length) return null;
  const operations = [];
  for (const op of raw.operations) {
    const from = Number(op?.from);
    const length = Number(op?.length);
    const repeats = Number(op?.repeats);
    if (!Number.isInteger(from) || from < 0) return null;
    if (!Number.isInteger(length) || length <= 0) return null;
    if (!Number.isInteger(repeats) || repeats < 1 || repeats > 4) return null;
    if (Number.isInteger(sourceSteps) && from + length > sourceSteps) return null;
    operations.push({
      from, length, repeats, transpose: Number(op?.transpose) || 0,
      ...(op?.harmony ? { harmony: Number(op.harmony) || 0 } : {}),
      // The same material comes back, so what it was read as sitting on comes back with it.
      ...(op?.chord == null ? {} : { chord: Number(op.chord) || 0 }),
      ...(op?.mute ? { mute: true } : {}),
      ...(typeof op?.fill === 'string' ? { fill: op.fill } : {}),
      ...(op?.favourite ? { favourite: true } : {}),
    });
  }
  const letter = typeof raw.letter === 'string' && /^[A-Z]$/.test(raw.letter) ? raw.letter : '';
  return {
    id: `${trackId}-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
    label: typeof raw.label === 'string' && raw.label
      ? raw.label : (letter ? `${letter} · restored` : 'Restored clip'),
    letter, steps, operations,
    resizable: !!raw.resizable,
    verbatim: !!raw.verbatim,
    ...(raw.key && Number.isInteger(raw.key.tonic) ? { key: { tonic: raw.key.tonic, minor: !!raw.key.minor } } : {}),
  };
}

/** ` · N shelf items could not be restored`, or '' — composed onto whichever toast follows. */
function rearrangeDropNote(dropped) {
  return dropped ? ` · ${dropped} shelf item${dropped === 1 ? '' : 's'} could not be restored` : '';
}

/**
 * Replace locks/shelf/uniqueLetters wholesale — this is what those now ARE, not a merge
 * with whatever the session already had. `editor` absent still clears: a lock is an
 * index position in a SPECIFIC recipe's form, and carrying it over onto a different
 * recipe is how a lock ends up holding the wrong part verbatim.
 *
 * Returns `{ dropped }` rather than toasting itself — this always runs immediately before
 * a caller's OWN toast (installing a recipe, restoring a version), and a toast here would
 * only ever be the message a viewer never gets to read before the next one replaces it.
 */
function applyRearrangeEditorState(editor, sourceSteps) {
  rearrangeLockedSections.clear();
  rearrangeClips.length = 0;
  rearrangeUniqueLetters.clear();
  if (!editor || typeof editor !== 'object') { renderRearrangeClips(); return { dropped: 0 }; }
  if (Array.isArray(editor.locks)) {
    for (const index of editor.locks) {
      if (Number.isInteger(index) && index >= 0) rearrangeLockedSections.add(index);
    }
  }
  let dropped = 0;
  if (Array.isArray(editor.shelf)) {
    for (const raw of editor.shelf) {
      const clip = sanitizeRearrangeClip(raw, sourceSteps);
      if (!clip) { dropped++; continue; }
      // A hand-edited or corrupted file could carry two shelf items on one letter, the
      // same collision `addRearrangeClip` already guards against at creation time.
      if (rearrangeClipLetterTaken(clip.letter)) clip.letter = '';
      rearrangeClips.push(clip);
    }
  }
  if (Array.isArray(editor.uniqueLetters)) {
    for (const letter of editor.uniqueLetters) {
      if (typeof letter === 'string' && /^[A-Z]$/.test(letter)) rearrangeUniqueLetters.add(letter);
    }
  }
  renderRearrangeClips();
  return { dropped };
}

/**
 * A saved blob is either a bare recipe (everything saved before the dials existed) or
 * the wrapper. The recipe carries `kind`, so the two are told apart by the data itself
 * rather than by a version number somebody has to remember to bump.
 */
function unwrapM8trx(blob) {
  if (blob?.kind === REARRANGE_KIND) return { recipe: blob, settings: null, editor: null };
  return { recipe: blob?.recipe ?? null, settings: blob?.settings ?? null, editor: blob?.editor ?? null };
}

function applyRearrangeSettings(settings) {
  if (!settings || typeof settings !== 'object') return;
  for (const [name, spec] of Object.entries(REARRANGE_DIALS)) {
    const value = Number(settings[name]);
    const control = $(spec.id);
    if (control && Number.isFinite(value)) control.value = String(Math.max(0, Math.min(100, value)));
  }
  if (REARRANGE_STYLE_OPTIONS.includes(settings.style)) setRearrangeStyle(settings.style);
  if (settings.grain != null) setRearrangeGrain(settings.grain);
  if (REARRANGE_FORM_OPTIONS.includes(settings.form)) setRearrangeForm(settings.form);
  const select = (id, value) => {
    const control = $(id);
    if (control && value != null
      && [...control.options].some((option) => option.value === String(value))) {
      control.value = String(value);
    }
  };
  select('relength', settings.length);
  select('rekey', settings.key);
  select('refill', settings.fill);
  if (settings.drums === 'auto' || REARRANGE_DRUM_MODES.includes(settings.drums)) {
    rearrangeDrumsChoice = settings.drums;
  }
  const transpose = Number(settings.transpose);
  if ($('retranspose') && Number.isFinite(transpose)) {
    $('retranspose').value = String(Math.max(0, Math.min(100, transpose)));
  }
  rearrangeSeedHold = !!settings.seedHold;
  syncRearrangeDials();
  syncRearrangeStyle();
  syncRearrangeGrain();
  syncRearrangeForm();
  syncRearrangeTranspose();
  syncRearrangeKeyReadout();
  syncRearrangeSeedHold();
  syncRearrangeDrumControl();
  // A restored key or fill is exactly the case the count is for: the setting arrived from a
  // file rather than from a press, so nothing on screen would otherwise say it is set.
  syncRearrangeAdvanced();
}

async function saveM8trxVersion() {
  if (!rearrangeRecipe) { toast('Press Go ▸ to build an M8TRX recipe first'); return; }
  const editor = rearrangeEditorSnapshot();
  const payload = {
    recipe: JSON.parse(JSON.stringify(rearrangeRecipe)),
    settings: rearrangeSettingsSnapshot(),
    ...(editor ? { editor } : {}),
  };
  if (STATIC) {
    savedM8trx[trackId] = payload;
    localStorage.setItem(M8TRX_KEY, JSON.stringify(savedM8trx));
    persistLocalSave();
    toast('Saved M8TRX version for the Mixer only');
    return;
  }
  try {
    const res = await fetch('/save', {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ id: trackId, patch: { m8trx: payload } }),
    });
    const text = await res.text();
    if (!res.ok) throw new Error(text || `HTTP ${res.status}`);
    const body = JSON.parse(text);
    if (body?.m8trx && typeof body.m8trx === 'object') savedM8trx = body.m8trx;
    else savedM8trx[trackId] = payload;
    localStorage.setItem(M8TRX_KEY, JSON.stringify(savedM8trx));
    toast('Saved M8TRX version for the Mixer only');
  } catch (error) {
    await tell('Could not save the M8TRX version', escapeHtml(error.message || String(error)));
  }
}

async function loadRearrangeJson(file) {
  if (!file) return;
  try {
    const raw = JSON.parse(await file.text());
    const sourceSong = raw.source?.song;
    if (sourceSong && sourceSong !== trackId) {
      if (resolveTrack(sourceSong)) {
        const switchIt = await ask('Open the recipe’s song?',
          `<p>This Rearrange recipe belongs to <b>${escapeHtml(raw.source.title || sourceSong)}</b>.</p>`
          + '<p>Open that song before loading the recipe?</p>', 'Open song');
        if (!switchIt) return;
        selectSong(sourceSong);
      } else {
        throw new Error(`The source song ${sourceSong} is not available`);
      }
    }
    const recipe = validateRearrangement(raw, rearrangeSourceSteps(), { songId: trackId });
    // `raw.editor` is read off the file BEFORE validation, not off `recipe` — the
    // validator rebuilds a fixed-shape object from a fixed field whitelist and would
    // silently drop anything it does not recognise, editor included.
    const { dropped } = applyRearrangeEditorState(raw.editor, rearrangeSourceSteps());
    installRearrangement(recipe, { announce: false });
    toast(`Rearrange ready · ${recipe.operations.length} operations${rearrangeDropNote(dropped)}`);
  } catch (error) {
    await tell('Could not load Rearrange JSON', escapeHtml(error.message || String(error)));
  }
}

function openRearrangePanel() {
  rearrangePanelOpen = true;
  $('rearrangepanel').hidden = false;
  // Re-measured on the way in — AFTER the panel is up, because the footer grows a line
  // when M8TRX's own status joins it. Measuring first sized the panel against a footer one
  // line shorter than the one it then had to sit above, so it covered it until some later
  // resize happened to re-measure. `watchDeskEdges` is the belt to this brace: the header
  // also wraps at some widths and the boot measurement predates fonts settling.
  measureDeskEdges();
  if (savedM8trx[trackId]) {
    const { recipe: parkedRaw, settings, editor } = unwrapM8trx(savedM8trx[trackId]);
    // The dials come back whether or not the recipe does — they are what a returning
    // user reaches for, and a recipe that no longer fits the song is no reason to open
    // the panel at the factory settings.
    applyRearrangeSettings(settings);
    // Unlike settings, a missing editor block does NOT clear the current session — a
    // save made before this feature existed carried no opinion on locks/shelf, and an
    // opinion of "empty" is not the same as no opinion at all.
    const editorResult = editor ? applyRearrangeEditorState(editor, rearrangeSourceSteps()) : null;
    if (!rearrangeRecipe && parkedRaw) {
      try {
        const parked = validateRearrangement(parkedRaw, rearrangeSourceSteps(), { songId: trackId });
        installRearrangement(parked, { announce: false, live: false });
        toast(`Restored the saved M8TRX version — parked, not playing${rearrangeDropNote(editorResult?.dropped)}`);
      } catch {
        delete savedM8trx[trackId];
        localStorage.setItem(M8TRX_KEY, JSON.stringify(savedM8trx));
      }
    } else if (editorResult?.dropped) {
      // A recipe was already active, so the branch above never ran — this is the only
      // chance to say that some of what just got restored did not make it.
      toast(`${editorResult.dropped} shelf item${editorResult.dropped === 1 ? '' : 's'} could not be restored`);
    }
  }
  // Opening the panel is the parked moment this work belongs in: one walk of the song,
  // held for every Generate afterwards. Skipped while playing, because a full-bank walk
  // on the main thread is exactly the kind of stall the audio graph cannot absorb —
  // Generate falls back to the cheap per-bar density until the next parked open.
  if (!playing) rearrangeSourceProfile({ build: true });
  syncRearrangeKeyReadout();
  renderRearrangeList();
  syncRearrangeButton();
}

function closeRearrangePanel() {
  rearrangePanelOpen = false;
  $('rearrangepanel').hidden = true;
  // Pay whatever the resize handler deferred while the panel was covering the rack.
  if (deskFitOwed) {
    deskFitOwed = false;
    scheduleDeskFit(true);
    updateArrangementNoteScale();
  }
  // The footer line goes with the panel. The recipe may still be armed and sounding, but
  // the desk's status bar is the desk's, and a closed panel does not get to keep a third
  // of it — the toolbar button already reads "M8TRX · ON" while one is live.
  const strip = $('m8status');
  if (strip) strip.hidden = true;
}

/**
 * Where in the song the music being HEARD right now is, as a fractional sixteenth.
 *
 * `songBeat()` backs off the scheduler's lookahead, so this is what has left the
 * speakers rather than what has been queued — the playhead has to match the ear.
 * Two more lags pull the line the other way from the audio's own: a note's attack ramp
 * means it is heard a few milliseconds after it is scheduled, and the frame this is
 * painted in reaches the glass a frame or two after that. Both put the line behind the
 * music, which is what "the playhead is early" looks like. `phOffset` is milliseconds
 * forward — positive moves it right — and it is the only part of the playhead that
 * cannot be computed, because it is a property of the screen.
 *
 * Before the first step is heard this is NEGATIVE: the scheduler has queued the next
 * step and nothing has left the speakers yet, so `songBeat()` backs off by more than
 * the position it is backing off from. Wrapping that with a modulo would put it at the
 * END of the song — the playhead jumping to the right edge every time play started — so
 * before the top of the song clamps to the top of the song rather than wrapping.
 *
 * Two callers, and it is one function because of the second. The playhead wants it to
 * draw; the recorder wants it to decide which step a note landed on, and a recorder
 * working from its own copy of this arithmetic would drift from the line the moment
 * anybody nudged `[` or `]` — which is a control that exists precisely because the
 * number is machine-specific. Null when there is nothing playing.
 *
 * `Audio.step` is NOT this. That is the scheduler's integer step, up to 120ms in the
 * future and carrying a cycle offset — right for scheduling, wrong for both of these.
 */
function heardStepNow() {
  const beat = Audio.songBeat();
  if (beat == null || !track) return null;
  const { spb, totalSteps } = songShape();
  if (!(totalSteps > 0)) return null;
  const at = beat * 4;
  const led = Math.max(0, at + (phOffset / 1000) / spb);
  // `phOffset` moves the line FORWARD, and forward from the last few milliseconds of a
  // lap is past the end of it. Modulo against the whole song does not catch that when a
  // loop is armed — the song is longer than the loop — so for `phOffset` milliseconds
  // every lap the desk read a step in the bar AFTER the loop, and lit its first note.
  // Wrap against the range the transport is actually turning round in instead.
  return wrappedPlaybackStep(led, at, totalSteps);
}

function sourceHeardStepNow() {
  const output = heardStepNow();
  if (output == null) return null;
  return Audio.rearrangementPosition(output)?.sourceStep ?? output;
}

// The arrangement marks need a small amount of paint lead so the mark is on the glass
// when the attack reaches the ear. Two separate things put it behind the music. The
// frame this is computed in is composited on the NEXT screen refresh, which is one
// frame at best; and each note language spends a slice of its own keyframes getting
// to full strength, so the moment it READS as a hit is later than the moment the class
// went on. Lead by both, per language, rather than by one number that can only be
// right for one of them.
const ARRANGEMENT_PAINT_LEAD_MS = 24;
// Half of each language's time to peak. Leading by the whole of it would start the
// flourish visibly before the note; half puts the accent on the beat while the onset
// still reads as belonging to it.
const NOTE_VISUAL_LEAD_MS = { solid: 0, pulse: 10, trail: 45 };
function arrangementVisualLeadMs() {
  if (!noteAnimation) return ARRANGEMENT_PAINT_LEAD_MS;
  return ARRANGEMENT_PAINT_LEAD_MS + (NOTE_VISUAL_LEAD_MS[noteVisualMode] ?? 0);
}

/**
 * The range the playhead at `step` is turning round in, in song-relative steps.
 *
 * Inside an armed loop that is the LOOP, on every lap including the first: the transport
 * turns round at its end, so nothing drawn past it is ever heard, and what follows it is
 * its own start rather than the next bar. Outside the region — the intro of a song whose
 * loop starts part-way in, or the lookahead still draining after Loop was armed — the
 * song itself is the range, so a step that has left the region is never dragged back
 * into it.
 *
 * One function for both edges. Two would be two places to decide which range a step
 * belongs to, and a loop that ends on the last bar of the song makes them disagree:
 * its end IS the song's end, but its start is not the song's.
 */
function playbackWrapRange(step, totalSteps) {
  const { loopStart, loopEnd } = Audio;
  if (loopStart != null && loopEnd != null && loopEnd > loopStart
    && step >= loopStart && step < loopEnd) {
    return { start: loopStart, end: Math.min(loopEnd, totalSteps) };
  }
  return { start: 0, end: totalSteps };
}

/** Where the playhead this step belongs to will next WRAP. */
function playbackWrapStep(step, totalSteps) {
  return playbackWrapRange(step, totalSteps).end;
}

/**
 * A position carried forward by a lead, brought back inside the range it belongs to.
 *
 * The range is chosen from `at` — where the transport actually is — never from the led
 * position. Choosing it from the led position is the bug this exists to stop: once the
 * lead has crossed the end of the loop it is no longer inside the region, so it would
 * pick the whole song and be left exactly where it should not be.
 */
function wrappedPlaybackStep(led, at, totalSteps) {
  const { start, end } = playbackWrapRange(at, totalSteps);
  const span = end - start;
  if (!(span > 0)) return led;
  return start + ((led - start) % span + span) % span;
}

/**
 * Do not let the paint lead cross a wrap. The next bar becomes eligible only when the
 * heard playhead itself gets there — otherwise the lead spills over the end of the loop
 * and lights the first note of the bar AFTER it, a note that is never played.
 */
function arrangementVisualStep(step) {
  if (step == null) return null;
  const { spb, totalSteps } = songShape();
  const lead = arrangementVisualLeadMs() / 1000 / spb;
  return Math.min(playbackWrapStep(step, totalSteps) - 1e-6, step + lead);
}

function buildTimeline() {
  const { bars: plan, loopSecs } = songShape();
  // One segment per BAR (4 beats). A bar is the unit you count in your head, and
  // since the arrangement became bar-wise it is also the unit the song is made of:
  // an order entry can be one bar now, so two-bars-per-block is no longer a shape
  // the timeline can assume.
  //
  // The ruler: a tick per bar, numbered often enough to read and rarely enough to
  // stay legible. Percentage positions, so it follows the window without rebuilding.
  const barCount = plan.length;
  const every = barCount <= 24 ? 2 : barCount <= 48 ? 4 : barCount <= 96 ? 8 : 16;
  const ruler = $('ruler');
  ruler.textContent = '';
  for (let b = 1; b <= barCount; b++) {
    const major = (b - 1) % every === 0;
    const tick = document.createElement('div');
    tick.className = 'tick' + (major ? ' major' : '');
    tick.style.left = `${((b - 1) / barCount) * 100}%`;
    if (major) {
      const n = document.createElement('span');
      n.textContent = String(b);
      tick.append(n);
    }
    ruler.append(tick);
  }

  $('tnow').title = `Where you are in ${track.title}, and how long it runs`;
  $('tnow').textContent = `0:00/${fmtTime(loopSecs)}`;
  // Reserve both sides of the slash at the song's widest bar number. Without this,
  // the readout grows when 999 becomes 1000 and nudges the whole header to the right.
  const barDigits = String(Math.max(1, plan.length)).length;
  $('barnow').style.width = `${barDigits * 2 + 1}ch`;
  $('barnow').textContent = `1/${plan.length}`;
}

const fmtTime = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

// Loop region is defined by two locator pins on the timeline rather than by bar
// counts. The loop starts OFF, so pressing play gives you the whole song.
// Click the timeline to place locators; click a locator to clear it.
let locA = null;              // first locator step (null = not placed)
let locB = null;              // second locator step
let loopOn = false;
// The piano roll owns a finer, beat-level selection than the desk's bar selection.
// It is session-only; the explicit loop range is kept separately so a later bar click
// cannot silently replace a loop the user armed from the roll.
let pianoRollTimeSelection = null;
let pianoRollLoopRange = null;
// Two different positions. `loopAnchor` is the start of the LOOP REGION (the
// lesser of the two locators). `parkedAt` is where the playhead is, to the step
// — Play resumes exactly where you paused.
let loopAnchor = 0;
let pendingLoopAnchor = null;
let pendingSeekStep = null;
let parkedAt = 0;

/**
 * Resolve the range the transport should loop.
 *
 * An explicitly armed piano-roll range wins first, followed by the highlighted bar
 * range. Alt-click locators are retained as a fallback for the older locator workflow,
 * but they must not override a range the user has visibly selected elsewhere.
 */
function currentLoopBounds() {
  const { totalSteps } = songShape();
  if (pianoRollLoopRange) {
    const start = clamp(Math.round(Number(pianoRollLoopRange.start) || 0), 0, totalSteps);
    const end = clamp(Math.round(Number(pianoRollLoopRange.end) || 0), start, totalSteps);
    if (end > start) return { start, end };
  }
  if (selectedBar) {
    const totalBars = Math.max(1, Math.floor(totalSteps / 16));
    const from = clamp(Math.min(selectedBar.from, selectedBar.to), 0, totalBars - 1);
    const to = clamp(Math.max(selectedBar.from, selectedBar.to), from, totalBars - 1);
    return { start: from * 16, end: Math.min(totalSteps, (to + 1) * 16) };
  }
  if (locA != null && locB != null) {
    return { start: Math.min(locA, locB), end: Math.max(locA, locB) };
  }
  return null;
}

// ---- the song's own start and loop ------------------------------------------------
//
// A different question from the locator loop above. That one is the range you are
// working IN and belongs to the session; this is what the game hears for ever and
// belongs to the song — `arrangement.loop`, saved with everything else the desk writes.
//
// The switch is desk-local and not saved with the song, for the same reason Solo is
// not: it is a monitoring choice. On, the transport plays the song the way a cabinet
// screen will; off, it plays the whole form from bar 1 so the intro can be edited like
// any other bars.
const FORM_LOOP_KEY = 'mash-mixer-form-loop';
let formLoopOn = localStorage.getItem(FORM_LOOP_KEY) !== '0';

/** The markers as the desk has them — the unsaved draft first, like everything else. */
const songLoopOf = () => arrFor(trackId)?.loop || null;

/**
 * Songs the markers can actually affect: the ones the game plays for itself,
 * plus saved alternates whose parent is one of those songs.
 *
 * Asked of `listTracks`, not of `track` — `resolveTrack` hands back a built-in song
 * without a `group` at all, because the group is not IN the file. It is decided by
 * which registry an id is in, and only the picker's list knows that. Which is also why
 * this is a UI rule and not a saved-file rule: the same song is `scratch` before it is
 * wired to a cabinet and `cabinet` after, so a file that was legal on Tuesday would
 * stop being legal on Wednesday for a reason nothing about it had changed. Alternates
 * carry their parent explicitly, so they can use the same toolbar control without
 * being mistaken for scratch songs.
 */
const songLoopGate = () => {
  // Not in user mode. Where a song starts and which bars it settles into is the game's
  // own arrangement — it decides what a level and its cabinet screen sound like long
  // after anyone is listening here, and it is the one control on the desk that mixing
  // never touches. The transport still FOLLOWS it, so the song plays the way the game
  // plays it; there is just nothing to move.
  if (!DEV_USER) return false;
  const song = listTracks().find((t) => t.id === trackId);
  if (!song) return false;
  if (song.group === 'cabinet' || song.group === 'theme') return true;
  return song.group === 'alternate'
    && (song.alternateOf === 'hub' || !!CABINET_BY_ID[song.alternateOf]);
};

/**
 * Whether the song's own markers are what the transport is following right now.
 *
 * The locator loop wins whenever it is armed over a real range — that is someone
 * pointing at bars they are working on, and it should not be quietly overruled by a
 * property of the song.
 */
const songLoopGoverns = () => formLoopOn && !!songLoopOf() && !(loopOn && currentLoopBounds());

function syncLoopButton() {
  const button = $('looptoggle');
  if (rearrangeActive()) {
    button.textContent = rearrangeLoopOn ? 'Recipe Loop' : 'Recipe Once';
    button.classList.toggle('on', rearrangeLoopOn);
    button.setAttribute('aria-pressed', rearrangeLoopOn ? 'true' : 'false');
    syncSelReadout();
    hideLoopUi();
    return;
  }
  const bounds = currentLoopBounds();
  const bars = bounds ? Math.max(1, Math.round((bounds.end - bounds.start) / 16)) : 0;
  const beats = bounds ? Math.max(1, Math.round((bounds.end - bounds.start) / 4)) : 0;
  const exactBars = bounds && (bounds.end - bounds.start) % 16 === 0;
  button.textContent = loopOn
    ? (exactBars ? `Loop ${bars} Bar${bars === 1 ? '' : 's'}`
      : beats ? `Loop ${beats} Beat${beats === 1 ? '' : 's'}` : 'Loop On')
    : 'Loop Off';
  button.classList.toggle('on', loopOn);
  button.setAttribute('aria-pressed', loopOn ? 'true' : 'false');
  // The selection readout carries the same switch, because it names the bars the loop
  // plays — so it has to hear about the loop changing from anywhere.
  syncSelReadout();
  if (loopOn && bounds) showLoopUi(bounds.start, bounds.end, songShape().totalSteps);
}

function syncLoopAnchor() {
  if (!pendingLoopAnchor || Audio.pendingLoop != null) return;
  if (Audio.loopStart === pendingLoopAnchor.start && Audio.loopEnd === pendingLoopAnchor.end) {
    loopAnchor = pendingLoopAnchor.start;
    pendingLoopAnchor = null;
    $('loopregion').classList.remove('pending');
  }
}

function syncPendingSeek() {
  if (pendingSeekStep == null || Audio.pendingStep != null) return;
  pendingSeekStep = null;
  $('selregion').classList.remove('pending');
}

/** Arm the highlighted range, or the two song-relative locators. */
function applyLoop(atStep = null) {
  const { totalSteps } = songShape();
  if (rearrangeActive()) {
    Audio.setLoop();
    syncRearrangeLoopControls();
    return;
  }
  const bounds = currentLoopBounds();
  pendingLoopAnchor = null;
  pendingSeekStep = null;
  $('selregion').classList.remove('pending');
  $('loopregion').classList.remove('pending');
  syncLoopButton();
  if (!loopOn || !bounds) {
    Audio.setLoop();
    // Nothing is picked out, so the song's own markers get the transport back. No seek:
    // clearing a loop is not arriving at a song, and the playhead stays where it is.
    if (formLoopOn) Audio.armSongLoop();
    hideLoopUi();
    syncSongLoopUi();
    return;
  }
  const { start, end } = bounds;
  if (end <= start) { Audio.setLoop(); if (formLoopOn) Audio.armSongLoop(); hideLoopUi(); syncSongLoopUi(); return; }
  // Both selection bars and locator positions are relative to this song, not to
  // whichever whole-song cycle the scheduler happened to be in when Loop was pressed.
  // Keeping the engine bounds in that same coordinate space makes every re-arm land on
  // the same region.
  Audio.setLoop(start, end);
  loopAnchor = start;
  showLoopUi(start, end, totalSteps);
  syncSongLoopUi();
}

/** Arm a piano-roll range, swapping it at the next safe boundary when already playing. */
function armPianoRollLoop(range, { announce = true } = {}) {
  const total = songShape().totalSteps;
  const start = clamp(Math.round(Number(range?.start) || 0), 0, total);
  const end = clamp(Math.round(Number(range?.end) || 0), start, total);
  if (end <= start) return false;
  pianoRollLoopRange = { start, end };
  loopOn = true;
  const bounds = currentLoopBounds();
  if (playing && bounds && Audio.loopStart != null && Audio.loopEnd != null) {
    pendingSeekStep = null;
    $('selregion').classList.remove('pending');
    Audio.setLoopAtBoundary(bounds.start, bounds.end);
    pendingLoopAnchor = { start: bounds.start, end: bounds.end };
    $('loopregion').classList.add('pending');
    syncLoopButton();
  } else {
    applyLoop();
  }
  if (announce) {
    const beats = Math.max(1, Math.round((end - start) / 4));
    toast(`Loop armed from the piano roll — ${beats} beat${beats === 1 ? '' : 's'}`);
  }
  return true;
}

function hideLoopUi() {
  $('loopregion').style.display = 'none';
  $('loopregion').classList.remove('pending');
  showLocatorUi();
}

function showLoopUi(start, end, totalSteps) {
  const reg = $('loopregion');
  // 'block', not '': these bands are `display: none` in the stylesheet, so clearing the
  // inline style hides them again rather than showing them.
  reg.style.display = 'block';
  reg.style.left = (start / totalSteps * 100) + '%';
  reg.style.width = ((end - start) / totalSteps * 100) + '%';
  showLocatorUi(totalSteps);
}

// Locator placement is independent of whether the loop is armed. Hiding the pins when
// Loop was off made Alt-click appear to do nothing and made it impossible to check the
// two positions before enabling playback.
function showLocatorUi(totalSteps = songShape().totalSteps) {
  const span = Math.max(1, totalSteps);
  for (const [id, step] of [['locatorA', locA], ['locatorB', locB]]) {
    const pin = $(id);
    pin.style.display = step == null ? 'none' : 'block';
    if (step != null) pin.style.left = (step / span * 100) + '%';
  }
}

/** Place or clear a locator at the given step. Returns which locator changed. */
function toggleLocator(step) {
  const within = ((Math.floor(step) % songShape().totalSteps) + songShape().totalSteps) % songShape().totalSteps;
  // Clicking on an existing locator clears it
  if (locA === within) { locA = null; applyLoop(); pianoRoll?.redraw?.(); return 'A-cleared'; }
  if (locB === within) { locB = null; applyLoop(); pianoRoll?.redraw?.(); return 'B-cleared'; }
  // Place at the first empty slot
  if (locA == null) { locA = within; applyLoop(); pianoRoll?.redraw?.(); return 'A'; }
  if (locB == null) { locB = within; applyLoop(); pianoRoll?.redraw?.(); return 'B'; }
  // Both are set — replace the nearer one
  const dA = Math.abs(locA - within);
  const dB = Math.abs(locB - within);
  if (dA <= dB) { locA = within; } else { locB = within; }
  applyLoop();
  pianoRoll?.redraw?.();
  return dA <= dB ? 'A' : 'B';
}

/**
 * Arm the loop but do NOT jump the playhead — for "Play from start" where the
 * song should play from the beginning and only loop once it reaches the region.
 *
 * Uses Audio.setLoop() (the same proven path as applyLoop) then immediately
 * overrides the step back to 0, so the scheduler plays from the top and wraps
 * when it hits the region naturally.
 */
function applyLoopNoJump() {
  const { totalSteps } = songShape();
  if (rearrangeActive()) {
    Audio.setLoop();
    syncRearrangeLoopControls();
    return;
  }
  const bounds = currentLoopBounds();
  pendingLoopAnchor = null;
  pendingSeekStep = null;
  $('selregion').classList.remove('pending');
  $('loopregion').classList.remove('pending');
  if (!loopOn || !bounds) {
    Audio.setLoop();
    // Play from the top means the song's own top: the bar the game comes in on.
    if (formLoopOn) Audio.armSongLoop({ seek: true });
    hideLoopUi();
    syncSongLoopUi();
    return;
  }
  const { start, end } = bounds;
  if (end <= start) { Audio.setLoop(); hideLoopUi(); return; }
  // Arm the loop through the exact same path as applyLoop — setLoop validates
  // the bounds, sets loopStart/loopEnd, and would jump the playhead into the
  // region. We override the jump immediately after so the song starts from 0.
  Audio.setLoop(start, end);
  Audio.step = 0;  // override setLoop's jump — play from the top
  loopAnchor = start;
  showLoopUi(start, end, totalSteps);
}

/**
 * Put the song's markers on screen: the three numbers, the switch, and the two bands
 * on the timeline that say which bars the game hears once and which it hears for ever.
 *
 * Drawn from the DRAFT every time rather than kept in step by hand, so an undo, a
 * discard, a snapshot restore and a bar delete all show up here without any of them
 * knowing this exists.
 */
function syncSongLoopUi() {
  const grp = $('songloopgrp');
  grp.hidden = !songLoopGate();
  const loop = songLoopOf();
  const bars = Math.max(1, Math.round(songShape().totalSteps / 16));
  const btn = $('formloop');
  btn.classList.toggle('on', formLoopOn);
  btn.setAttribute('aria-pressed', formLoopOn ? 'true' : 'false');
  btn.textContent = formLoopOn ? 'Game Loop' : 'Whole Song';
  for (const [id, value] of [
    ['songloopstart', loop?.startBar ?? (loop ? 1 : null)],
    ['songloopfrom', loop?.fromBar ?? null],
    ['songloopto', loop?.toBar ?? null],
  ]) {
    const input = $(id);
    if (document.activeElement !== input) input.value = value == null ? '' : String(value);
    input.max = String(bars);
    // A number the song is no longer long enough for. Flagged and left alone: the bars
    // were deleted from under it, and which bar was meant is not this file's to guess.
    input.setAttribute('aria-invalid', value != null && value > bars ? 'true' : 'false');
  }
  // The bands. Only while the markers are actually the thing playing — with a locator
  // loop armed over them they are not what you are hearing, and drawing them anyway
  // would be the timeline claiming otherwise.
  const intro = $('formintro');
  const region = $('formloopregion');
  const show = songLoopGate() && formLoopOn && loop && !(loopOn && currentLoopBounds());
  // Through the shared resolver rather than the engine's copy of it: the bands have to
  // draw with the transport stopped, and a stopped desk has no bank in the engine.
  const r = show ? loopSteps(loop, bars) : null;
  const total = Math.max(1, songShape().totalSteps);
  const pct = (step) => (step / total * 100) + '%';
  // The bars before the loop: heard on the way in and never again. From the start bar,
  // not from bar 1 — anything before the start bar is not heard at all, and the ruler
  // says which bars those are well enough on its own.
  if (r && r.loop && r.loop.start > r.start) {
    intro.style.display = 'block';
    intro.style.left = pct(r.start);
    intro.style.width = pct(r.loop.start - r.start);
  } else intro.style.display = 'none';
  if (r && r.loop) {
    region.style.display = 'block';
    region.style.left = pct(r.loop.start);
    region.style.width = pct(r.loop.end - r.loop.start);
  } else region.style.display = 'none';
}

/** Read the three inputs back as a `{startBar, fromBar, toBar}`, or null for none. */
function songLoopFromFields() {
  const num = (id) => {
    const raw = $(id).value.trim();
    if (!raw) return null;
    const n = Math.round(Number(raw));
    return Number.isFinite(n) ? n : null;
  };
  const startBar = num('songloopstart');
  const fromBar = num('songloopfrom');
  const toBar = num('songloopto');
  if (startBar == null && fromBar == null && toBar == null) return null;
  // One end of a loop and not the other is half a thought, not an error: take the bar
  // that IS named as both ends, which is the one-bar loop it looks like.
  return { startBar: startBar ?? 1, fromBar: fromBar ?? toBar, toBar: toBar ?? fromBar };
}

/**
 * Write the fields into the arrangement, through the same door every other bar edit
 * goes through: `setSongLoop` clamps against the bars the song has, and
 * `applyArrangementEdit` handles undo, validation, the engine and Save.
 */
function commitSongLoop(loop, what) {
  const ok = applyArrangementEdit(setSongLoop(arrDraftOf(), loop), what, {
    render: false, undoTag: 'songloop', rearmLoop: false,
  });
  if (!ok) { syncSongLoopUi(); return false; }
  // Re-armed rather than left to applyLoop's usual re-arm, because the numbers can move
  // while the song is playing and the region has to follow them from the next step —
  // without moving the playhead, which is what `applyLoop` would do here.
  if (formLoopOn) Audio.armSongLoop();
  syncSongLoopUi();
  // `render: false` above skips the whole repaint, and `updateStatus` rides with it —
  // so without this the Save button goes on saying the song matches the file while the
  // markers sit unsaved in the draft.
  updateStatus();
  return true;
}

for (const id of ['songloopstart', 'songloopfrom', 'songloopto']) {
  // On `change` rather than `input`: these are three numbers that depend on each other,
  // and clamping a half-typed "1" of "12" against the other two writes the wrong thing
  // and then argues with the person still typing.
  $(id).onchange = () => {
    const wanted = songLoopFromFields();
    commitSongLoop(wanted, null);
    const got = songLoopOf();
    if (!got) { toast('Game loop cleared — the whole song, round and round'); return; }
    const from = got.fromBar ?? null;
    toast(from == null
      ? `Starts on bar ${got.startBar ?? 1}`
      : `In on bar ${got.startBar ?? 1}, then bars ${from}-${got.toBar} for ever`);
  };
}

$('songloopclear').onclick = () => {
  if (!songLoopOf()) { toast('No game loop on this song'); return; }
  commitSongLoop(null, 'Game loop cleared');
};

$('formloop').onclick = () => {
  if (rearrangeActive()) return;
  formLoopOn = !formLoopOn;
  localStorage.setItem(FORM_LOOP_KEY, formLoopOn ? '1' : '0');
  applyLoop(Audio.step);
  const loop = songLoopOf();
  if (!formLoopOn) toast('Playing the whole song — the game still hears the loop');
  else if (!loop) toast('Game loop on — this song does not name one yet');
  else toast(`Hearing it as the game does — in on bar ${loop.startBar ?? 1}`);
};

$('looptoggle').onclick = () => {
  if (rearrangeActive()) {
    rearrangeLoopOn = !rearrangeLoopOn;
    Audio.rearrangeLoop = rearrangeLoopOn;
    syncLoopButton();
    syncRearrangeLoopControls();
    toast(rearrangeLoopOn ? 'Recipe loops when it ends' : 'Recipe plays once, then stops');
    return;
  }
  loopOn = !loopOn;
  if (!loopOn) pianoRollLoopRange = null;
  applyLoop();
  if (loopOn) {
    const bounds = currentLoopBounds();
    if (!bounds) {
      toast('Loop on — select a bar range, or Alt-click the timeline to place locators');
    } else {
      toast(`Loop on — bars ${barOf(bounds.start)} to ${barOf(bounds.end - 1)}`);
    }
  } else {
    toast('Loop off — playing the whole song');
  }
};

// Clicking directly on a locator pin clears it.
$('locatorA').onclick = (e) => {
  e.stopPropagation();
  if (locA != null) { locA = null; applyLoop(); pianoRoll.redraw(); toast('Locator A cleared'); }
};
$('locatorB').onclick = (e) => {
  e.stopPropagation();
  if (locB != null) { locB = null; applyLoop(); pianoRoll.redraw(); toast('Locator B cleared'); }
};

/**
 * Move the playhead. While playing, an ordinary seek is queued for the next bar
 * boundary so the current bar is allowed to finish. With a bar loop armed, the
 * destination stays inside that loop rather than escaping it.
 *
 * Stopped, it parks the position instead, so Play starts from where you last
 * pointed; `start: true` (a double-click) skips the wait and plays from there.
 */
function jumpTo(step, { start = false, immediate = false } = {}) {
  const { totalSteps, spb, loopSecs } = songShape();
  const within = ((Math.floor(step) % totalSteps) + totalSteps) % totalSteps;
  // Moving the transport by hand is a request to look at that part of the song, so it
  // undoes a scroll that had told the roll to stop following.
  stepSeq.armFollow?.();
  pianoRoll.armFollow?.();
  kitRoll.armFollow?.();
  // The arrangement follows for the same reason the rolls do — and here rather than in
  // the stopped branch alone, because Stop seeks while `playing` is still true and would
  // otherwise leave the view a screen and a half away from the bar it returned to.
  followArrangementScroll(within / totalSteps);
  if (!playing) {
    parkedAt = within;                              // Play resumes on this step
    if (start) { setPlaying(true, within); return; }
    // Nothing is running to move the playhead, so put it where the click was.
    applyLoop(within);
    $('playhead').style.left = `${(within / totalSteps) * 100}%`;
    $('tnow').textContent = `${fmtTime(within * spb)}/${fmtTime(loopSecs)}`;
    $('barnow').textContent = `${barOf(within)}/${totalSteps / 16}`;
    stepSeq.follow(within);
    pianoRoll.follow(within);
    kitRoll.follow(within);
    return;
  }
  if (start && within === 0) {
    // A running loop has audio already queued ahead of the transport. Rewinding only
    // `Audio.step` leaves those loop notes audible before the restart. Re-enter the
    // transport so setBank cuts that queue, resets the song, and then arms the loop
    // without jumping into it.
    setPlaying(false);
    setPlaying(true, 0);
    return;
  }
  if (!immediate) {
    // A normal click is a musical seek, not a transport restart. Let the current
    // bar finish before moving the scheduler so the change lands like a live deck.
    pendingLoopAnchor = null;
    $('loopregion').classList.remove('pending');
    Audio.setStepAtBoundary(within);
    pendingSeekStep = within;
    $('selregion').classList.add('pending');
    return;
  }
  Audio.setLoop();                       // explicit transport actions move immediately
  pendingSeekStep = null;
  $('selregion').classList.remove('pending');
  Audio.step = within;
  Audio.nextTime = Audio.ctx.currentTime + 0.03;
  applyLoop(within);
}

function popupElement(kind) {
  if (kind === 'voicePicker') return $('voicepicker');
  if (kind === 'effectPicker') return $('fxpicker');
  return $('regionedit');
}

/** Capture a meaningful modeless popup, including controls staged but not applied. */
function currentPopupSession() {
  if (!restorablePopup) return null;
  const el = popupElement(restorablePopup.kind);
  if (!el?.classList.contains('show')) return null;
  const controls = [...el.querySelectorAll('input, select, textarea, [role="combobox"]')]
    .filter((field) => field.type !== 'file');
  const fields = controls.map((field) => ({
    value: field.value,
    checked: 'checked' in field ? !!field.checked : undefined,
    start: typeof field.selectionStart === 'number' ? field.selectionStart : undefined,
    end: typeof field.selectionEnd === 'number' ? field.selectionEnd : undefined,
  }));
  const active = controls.indexOf(document.activeElement);
  return {
    ...JSON.parse(JSON.stringify(restorablePopup)),
    x: Number.parseFloat(el.style.left) || 6,
    y: Number.parseFloat(el.style.top) || 6,
    scrollTop: el.scrollTop,
    fields,
    active,
  };
}

function currentDeskSession() {
  const position = playing ? (heardStepNow() ?? parkedAt) : parkedAt;
  const readScroll = (id, axis) => Number($(id)?.[axis]) || 0;
  return {
    version: 1,
    song: trackId,
    lane: selectedLane,
    selection: selectedBar ? { ...selectedBar } : null,
    position: Math.max(0, Math.floor(Number(position) || 0)),
    loop: { on: loopOn, locA, locB },
    lowerView,
    effectsOpen: $('devices')?.classList.contains('fxwindow-open') || false,
    libraryOpen: voiceLibrary?.isShown?.() || false,
    drawerOpen: $('navdrawer')?.classList.contains('show') || false,
    voiceEditor: voiceEditor?.isOpen?.() ? {
      laneKey: voiceEditor.laneKey,
      editing: voiceEditor.editing,
      full: voiceEditor.fullOpen,
    } : null,
    popup: currentPopupSession(),
    scroll: {
      arrangement: readScroll('arrgrid', 'scrollTop'),
      mixer: readScroll('rack', 'scrollLeft'),
      effects: readScroll('devrack', 'scrollTop'),
      roll: pianoRoll?.viewState?.() || null,
      kit: kitRoll?.viewState?.() || null,
    },
  };
}

function rememberDeskSession() {
  if (!track) return;
  try { localStorage.setItem(DESK_SESSION_KEY, JSON.stringify(currentDeskSession())); }
  catch { /* the desk still works if storage is full or unavailable */ }
}

function restorePopupFields(popup) {
  const el = popupElement(popup?.kind);
  if (!el || !Array.isArray(popup?.fields)) return;
  const controls = [...el.querySelectorAll('input, select, textarea, [role="combobox"]')]
    .filter((field) => field.type !== 'file');
  const assign = (field, saved) => {
    if (!field || !saved) return;
    if (saved.checked != null && 'checked' in field) field.checked = saved.checked;
    if (saved.value != null) field.value = saved.value;
  };
  controls.forEach((field, index) => {
    const saved = popup.fields[index];
    assign(field, saved);
    // Region controls keep staged values in closures. Replaying their normal input
    // path restores that state; a final silent assignment below preserves dependent
    // fields such as Note FX's explicit Inherit choice.
    field.dispatchEvent(new Event('input', { bubbles: true }));
    field.dispatchEvent(new Event('change', { bubbles: true }));
  });
  controls.forEach((field, index) => assign(field, popup.fields[index]));
  el.scrollTop = Math.max(0, Number(popup.scrollTop) || 0);
  const active = controls[popup.active];
  if (active) {
    active.focus({ preventScroll: true });
    const saved = popup.fields[popup.active];
    if (typeof active.setSelectionRange === 'function' && saved?.start != null) {
      try { active.setSelectionRange(saved.start, saved.end ?? saved.start); } catch { /* select/number */ }
    }
  }
}

function restoreDeskPopup(popup) {
  if (!popup?.kind) return;
  const x = Number(popup.x) || 6;
  const y = Number(popup.y) || 6;
  try {
    if (popup.kind === 'region') {
      openRegionEditor(x, y, { laneKey: popup.laneKey || null,
        from: popup.from, to: popup.to, wholeTrack: !!popup.wholeTrack,
        focusName: !!popup.focusName });
    } else if (popup.kind === 'noteFx' && popup.laneKey) {
      openNoteFxEditor(x, y, popup.laneKey, popup.scope || null);
    } else if (popup.kind === 'barEffects' && popup.laneKey) {
      openBarEffectsEditor(x, y, popup.laneKey,
        { from: popup.from, to: popup.to, chain: popup.chain || [] });
    } else if (popup.kind === 'noteLength') {
      openNoteLengthAdjust(popup.scopeKind === 'all' ? 'all' : 'selection', x, y);
    } else if (popup.kind === 'voicePicker' && popup.laneKey) {
      openVoicePicker(x, y, popup.laneKey);
    } else if (popup.kind === 'effectPicker') {
      openPicker({ at: popup.at, x, y });
    }
  } catch (err) {
    console.warn('[mixer] could not restore popup', err);
    return;
  }
  requestAnimationFrame(() => restorePopupFields(popup));
}

/** Restore once, after selectSong has built every song-dependent surface. */
function restoreDeskSession(session = savedDeskSession) {
  if (!session || session.version !== 1 || session.song !== trackId) return false;
  const bars = songShape().bars.length;
  const totalSteps = songShape().totalSteps;
  const laneKeys = new Set(deskLanes(viewBank(), 1).map((lane) => lane.key));
  const lane = typeof session.lane === 'string' && (laneKeys.has(session.lane)
    || session.lane === '__master' || session.lane.startsWith('__aux:'))
    ? session.lane : selectedLane;
  if (lane) selectLane(lane);

  loopOn = false;
  locA = Number.isFinite(session.loop?.locA)
    ? clamp(session.loop.locA, 0, Math.max(0, totalSteps - 1)) : null;
  locB = Number.isFinite(session.loop?.locB)
    ? clamp(session.loop.locB, 0, Math.max(0, totalSteps - 1)) : null;
  const selection = session.selection;
  if (selection && bars) {
    const from = clamp(Math.round(Number(selection.from) || 0), 0, bars - 1);
    const to = clamp(Math.round(Number(selection.to) || from), 0, bars - 1);
    const key = laneKeys.has(selection.key) ? selection.key : null;
    markBar(key, from, to, { focus: false });
  } else if (selectedBar) markBar(null, null, null, { focus: false });
  loopOn = session.loop?.on === true;
  jumpTo(clamp(Number(session.position) || 0, 0, Math.max(0, totalSteps - 1)));

  setLowerView(LOWER_VIEWS.has(session.lowerView) ? session.lowerView : lowerView,
    { remember: false });
  // Set the internal positions after selection/view refreshes have been queued, so the
  // build they trigger reads the restored viewport rather than its opening default.
  const restoreEditorViews = () => {
    pianoRoll.restoreViewState?.(session.scroll?.roll);
    kitRoll.restoreViewState?.(session.scroll?.kit);
    syncRollFollowButton();
  };
  restoreEditorViews();
  requestAnimationFrame(() => requestAnimationFrame(restoreEditorViews));
  // A first roll build is deliberately allowed to wait for idle (up to 250ms) so it
  // cannot punch a hole in playback. Its default focus runs after that build; this
  // final restore gives the saved hand-position the last word on a cold reload too.
  setTimeout(restoreEditorViews, 300);
  setDevicesFolded(session.effectsOpen !== true, false);

  const restoreScrollers = () => {
    if ($('arrgrid')) $('arrgrid').scrollTop = Math.max(0, Number(session.scroll?.arrangement) || 0);
    if ($('rack')) $('rack').scrollLeft = Math.max(0, Number(session.scroll?.mixer) || 0);
    if ($('devrack')) $('devrack').scrollTop = Math.max(0, Number(session.scroll?.effects) || 0);
  };
  requestAnimationFrame(() => { restoreScrollers(); requestAnimationFrame(restoreScrollers); });

  // Restore the substantial editor window before the smaller popup that may have
  // been sitting over it. Editing has already been saved through the normal draft
  // path; this only puts its surface back.
  const ve = session.voiceEditor;
  if (ve?.laneKey && laneKeys.has(ve.laneKey)) editVoice(ve.laneKey);
  else if (ve?.editing && session.libraryOpen) editLibraryVoice(ve.editing);
  if (ve?.full) requestAnimationFrame(() => voiceEditor.openFull());

  if (session.drawerOpen) requestAnimationFrame(openDrawer);
  else if (session.popup) requestAnimationFrame(() => restoreDeskPopup(session.popup));
  return true;
}

// The bars area, not the whole strip: the ruler is inset by the arrangement's name
// column, so measuring against the full width put every click a few bars early.
const timelineStep = (e) => {
  const r = $('barsarea').getBoundingClientRect();
  return Math.floor(clamp((e.clientX - r.left) / r.width, 0, 1) * songShape().totalSteps);
};
const barOf = (step) => Math.floor(step / 16) + 1;
const timelineBar = (e) => Math.max(0, Math.min(songShape().bars.length - 1, barOf(timelineStep(e)) - 1));

// Selecting structure is a timeline gesture. The arrangement grid can still add a
// lane target to the same range, but the bar numbers and the ripple operations start
// here, where the song's form is visible and easy to count.
let timelineDrag = null;
let timelineClickSuppress = false;
$('barsarea').onpointerdown = (ev) => {
  if (ev.button !== 0) return;
  timelineClickSuppress = false;
  const bar = timelineBar(ev);
  const anchor = ev.shiftKey && selectedBar ? selFrom() : bar;
  timelineDrag = { anchor, moved: false, last: bar };
  markBar(null, anchor, bar, { focus: false, deferEditors: true });
  try { $('barsarea').setPointerCapture(ev.pointerId); } catch { /* browserless */ }
};
$('barsarea').onpointermove = (ev) => {
  if (!timelineDrag || !(ev.buttons & 1)) return;
  const bar = timelineBar(ev);
  // Pointer events arrive far more often than the endpoint changes. Re-running the
  // selection/loop path inside the same bar did useful work exactly zero times.
  if (bar === timelineDrag.last) return;
  timelineDrag.last = bar;
  timelineDrag.moved = true;
  markBar(null, timelineDrag.anchor, bar, { focus: false, deferEditors: true });
};
$('barsarea').onpointerup = () => {
  if (timelineDrag) scheduleSelectionEditors();
  timelineClickSuppress = !!timelineDrag?.moved;
  timelineDrag = null;
};
$('barsarea').onpointercancel = () => {
  if (timelineDrag) scheduleSelectionEditors();
  timelineDrag = null;
  timelineClickSuppress = false;
};
$('barsarea').oncontextmenu = (ev) => timelineMenu(ev);

$('timeline').onclick = (e) => {
  if (e.target.closest('#tlhead')) return;
  const at = timelineStep(e);
  if (timelineClickSuppress) { timelineClickSuppress = false; return; }
  // Alt-click (or option-click) places/clears a locator instead of seeking.
  if (e.altKey) {
    const which = toggleLocator(at);
    if (which === 'A-cleared' || which === 'B-cleared') {
      toast(`Locator cleared`);
    } else {
      toast(`Locator ${which} set at bar ${barOf(at)}`);
    }
    return;
  }
  const bar = timelineBar(e);
  markBar(null, bar);
  // While a loop is playing, choosing a different bar is a loop edit, not a seek.
  // Seeking here tears down the live scheduler just as the boundary handoff is being
  // queued, which can leave playback silent until the transport is restarted.
  const target = bar * 16;
  if (!(playing && loopOn)) jumpTo(playing ? target : at);
  const looping = loopOn && locA != null && locB != null;
  toast(!playing ? `Parked at bar ${barOf(at)} — double-click to play from here`
    : looping ? `Looping bars ${barOf(Math.min(locA, locB))} to ${barOf(Math.max(locA, locB))}`
    : `Jumped to bar ${barOf(at)}`);
};

// Double-click plays from where you pointed. Stopped, reaching for Play and then
// hunting back to the bar you wanted was the long way round to hear one bar.
$('timeline').ondblclick = (e) => {
  if (e.target.closest('#tlhead')) return;
  const at = timelineStep(e);
  jumpTo(at, { start: true });
  toast(`Playing from bar ${barOf(at)}`);
};

// A lane in by the second bar counts as being in from the top: it starts with the
// song, and dropping the playhead onto bar 2 to hear it would only cost you the bar
// it came in on.
const INTRO_BARS = 2;

/**
 * The bar a lane first plays in, counted from 0. Memoised against the bank, because
 * the answer is a walk of every step of every block and the song does not change
 * while you mix it — switching track swaps the bank and the cache goes with it.
 */
let laneStarts = { bank: null, map: new Map() };
function firstBarOf(key) {
  // Against the SHAPED bank, so a layer has an answer of its own — the same one its
  // source has, which is the point, but the cache has to hold it under its own key.
  const view = viewBank();
  if (laneStarts.bank !== view) {
    const map = new Map();
    // One cell per bar: the question is which bar, not which beat of it.
    for (const row of laneActivity(view, 1, 1)) {
      const bar = row.density.findIndex((d) => d > 0);
      if (bar >= 0) map.set(row.key, bar);
    }
    laneStarts = { bank: view, map };
  }
  return laneStarts.map.get(key);
}

/**
 * Double-click a channel — its strip head, or its name in the arrangement — and the
 * song plays from where that channel comes in. A crash that only sounds in section
 * three was otherwise a matter of pressing Play and waiting for it, or reading along
 * the arrangement row for the first lit bar and double-clicking that.
 *
 * Lanes that are in from the top play from the top: see INTRO_BARS.
 */
function playFromLaneStart(key) {
  selectLane(key);
  const label = targetLabel(key);
  const bar = firstBarOf(key);
  // Only active lanes get a strip or an arrangement row, so this is a fallback and
  // not a case you can click your way into.
  if (bar == null) { jumpTo(0, { start: true }); toast(`${label} never plays — from the top`); return; }
  const from = bar < INTRO_BARS ? 0 : bar;
  jumpTo(from * 16, { start: true });
  markBar(key, from);              // where it starts, marked in the row you can see it in
  toast(from ? `Playing ${label} from bar ${from + 1} — where it comes in`
    : `${label} is in from the top — playing from bar 1`);
}

// ---- device panel ----------------------------------------------------------
// The selected channel's effect chain, along the bottom. Strips carry only a
// one-line summary; a 132px column cannot hold four parameters legibly, and most
// channels have no effects at all.
// Readable names for parameters whose internal keys are terse — the parametric EQ's
// bands especially, where f2/g2/q2 says nothing about what it does.
const PARAM_LABELS = {
  f1: 'LOW FREQ', g1: 'LOW GAIN',
  f2: 'LOW-MID FREQ', g2: 'LOW-MID GAIN', q2: 'LOW-MID Q',
  f3: 'HIGH-MID FREQ', g3: 'HIGH-MID GAIN', q3: 'HIGH-MID Q',
  f4: 'HIGH FREQ', g4: 'HIGH GAIN',
  // One word for a left/right control across the whole catalogue: BALANCE. The KEYS
  // differ — `pan` on the Advanced Delay, `dryPan`/`wetPan` on the Doubler, `balance`
  // on the Gain — because they are what saved mixes hold and renaming them would read
  // as a reset of every song carrying one. What is on the card is what has to be
  // consistent, and two names for one gesture is what sent you looking for the pan
  // control on an effect that called it something else.
  wet: 'WET / DRY', mix: 'MIX', pan: 'BALANCE', balance: 'BALANCE', tone: 'DAMPING',
  feedback: 'FEEDBACK', delayMs: 'TIME', frequency: 'RATE', depth: 'DEPTH',
  baseFrequency: 'BASE FREQ', octaves: 'OCTAVES', distortion: 'DRIVE',
  order: 'ORDER', width: 'WIDTH', pitch: 'PITCH', windowSize: 'WINDOW',
  detune: 'DETUNE', dryPan: 'DRY BALANCE', wetPan: 'WET BALANCE',
  decay: 'DECAY', preDelay: 'PRE-DELAY', threshold: 'THRESHOLD', ratio: 'RATIO',
  attack: 'ATTACK', release: 'RELEASE', spread: 'SPREAD', sensitivity: 'SENSITIVITY',
  delayTime: 'TIME', Q: 'Q', knee: 'KNEE',
  bits: 'BITS', bias: 'BIAS', density: 'DENSITY', gateLength: 'GATE LENGTH',
  wow: 'WOW', flutter: 'FLUTTER', waveform: 'WAVEFORM',
  lowFrequency: 'LOW X-OVER', highFrequency: 'HIGH X-OVER',
  ceiling: 'OUT CEILING', lookahead: 'LOOKAHEAD', arc: 'Auto Release (ARC)',
};

/**
 * A parameter's label. Dotted names are labelled a part at a time — `low.threshold`
 * reads LOW THRESHOLD — so the three bands of a multiband compressor need one entry
 * for THRESHOLD between them rather than one per band.
 */
const paramLabel = (p, def = null) => def?.labels?.[p] || PARAM_LABELS[p] || p.split('.')
  .map((s) => PARAM_LABELS[s] || s.replace(/([A-Z])/g, ' $1').toUpperCase())
  .join(' ');

/**
 * Make a dB readout typable, so a level can be entered exactly rather than nudged
 * to it. Double-click still resets, and the Reset channel button is untouched.
 *
 * `ctl` is the level in dB — `{ get, set, min, max, step }` — and not the slider
 * itself, because the slider under a tapered fader holds a position rather than a
 * level. What is typed is what is applied: the position follows, and never the other
 * way round, so a typed −3.0 stays −3.0 and does not come back as whatever the
 * nearest position rounds to.
 */
function makeTypableDb(el, ctl, apply, fmt) {
  el.classList.add('typable');
  el.title = 'Drag to set the level · click to type it · double-click to reset';
  const put = (x) => { const v = clamp(x, ctl.min, ctl.max); ctl.set(v); apply(v); return v; };
  const openEditor = () => {
    if (el.querySelector('input')) return;
    const box = document.createElement('input');
    box.type = 'text'; box.className = 'typein';
    box.value = String(ctl.get());
    el.textContent = '';
    el.append(box);
    box.focus(); box.select();
    const done = (commit) => {
      const n = parseFloat(box.value);
      const v = commit && Number.isFinite(n) ? put(n) : ctl.get();
      el.textContent = fmt(v);
    };
    box.addEventListener('keydown', (ev) => {
      ev.stopPropagation();
      if (ev.key === 'Enter') done(true);
      else if (ev.key === 'Escape') done(false);
    });
    box.addEventListener('blur', () => done(true));
  };
  dragNumber(el, {
    value: () => ctl.get(),
    set: put,
    range: ctl.max - ctl.min,
    step: ctl.step,
    onClick: openEditor,
  });
}

/**
 * A circular pan pot, as on a Logic channel strip. Drag anywhere on it — vertical
 * or horizontal, whichever your hand does — and the arc fills from centre toward
 * the side you are heading. A horizontal slider reads as a position on a line; a
 * pot reads as a position in the room, which is what pan actually is.
 */
function panKnob({ value, onInput }) {
  const NS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 44 44');
  svg.setAttribute('class', 'panpot');
  // Full grey track first, green arc drawn over it from the top centre — the
  // Logic layout. The number lives inside the ring, so the knob needs no label
  // and no separate readout: 0 in the middle with no arc IS "centred".
  const track = document.createElementNS(NS, 'path');
  track.setAttribute('class', 'pottrack');
  const arc = document.createElementNS(NS, 'path');
  arc.setAttribute('class', 'potarc');
  const face = document.createElementNS(NS, 'circle');
  face.setAttribute('cx', 22); face.setAttribute('cy', 22); face.setAttribute('r', 13);
  face.setAttribute('class', 'potface');
  const label = document.createElementNS(NS, 'text');
  label.setAttribute('x', 22); label.setAttribute('y', 22);
  label.setAttribute('class', 'pottext');
  label.setAttribute('text-anchor', 'middle');
  label.setAttribute('dominant-baseline', 'central');
  svg.append(track, arc, face, label);

  let val = value;
  const SWEEP = 145;                       // degrees either side of top centre
  const R = 18;
  const pt = (deg) => {
    const a = (deg - 90) * Math.PI / 180;
    return [22 + Math.cos(a) * R, 22 + Math.sin(a) * R];
  };
  const arcPath = (fromDeg, toDeg) => {
    const [x1, y1] = pt(fromDeg); const [x2, y2] = pt(toDeg);
    const big = Math.abs(toDeg - fromDeg) > 180 ? 1 : 0;
    const sweep = toDeg > fromDeg ? 1 : 0;
    return `M ${x1} ${y1} A ${R} ${R} 0 ${big} ${sweep} ${x2} ${y2}`;
  };
  track.setAttribute('d', arcPath(-SWEEP, SWEEP));

  const draw = () => {
    const deg = val * SWEEP;
    arc.setAttribute('d', Math.abs(val) < 0.005 ? '' : arcPath(0, deg));
    const n = Math.round(val * 100);
    label.textContent = n === 0 ? '0' : (n > 0 ? '+' : '') + n;
  };
  draw();

  const set = (x) => { val = clamp(x, -1, 1); draw(); onInput(val); };
  let dragging = false, lastX = 0, lastY = 0, moved = 0, fromLabel = false;
  svg.addEventListener('pointerdown', (e) => {
    // The number drags the knob like the rest of the pot does; a click that never
    // moved opens the type-in instead. Dragging over it used to select the text.
    if (holder.querySelector('.typein')) return;
    dragging = true; moved = 0; fromLabel = e.target === label;
    lastX = e.clientX; lastY = e.clientY;
    svg.setPointerCapture(e.pointerId); e.preventDefault();
  });
  svg.addEventListener('pointermove', (e) => {
    if (!dragging) return;
    const dx = e.clientX - lastX, dy = lastY - e.clientY;
    moved = Math.max(moved, Math.abs(dx), Math.abs(dy));
    lastX = e.clientX; lastY = e.clientY;
    // Whichever axis moved more wins, so neither grip feels wrong. Shift is fine.
    const delta = (Math.abs(dx) > Math.abs(dy) ? dx : dy) * (e.shiftKey ? 0.002 : 0.008);
    set(val + delta);
  });
  const stop = () => {
    if (dragging && fromLabel && moved < 3) openPanEditor();
    dragging = false;
  };
  svg.addEventListener('pointerup', stop);
  svg.addEventListener('pointercancel', stop);
  svg.addEventListener('dblclick', () => set(0));
  svg.title = 'Drag to pan · click the number to type · double-click to centre';

  // Type an exact value. The readout lives inside the SVG, so the editor is an HTML
  // input laid over the knob rather than a foreignObject — simpler, and it inherits
  // the same styling as every other type-in on the desk.
  const holder = document.createElement('div');
  holder.className = 'panholder';
  holder.append(svg);
  function openPanEditor() {
    if (holder.querySelector('.typein')) return;
    const box = document.createElement('input');
    box.type = 'text'; box.className = 'typein panin';
    box.value = String(Math.round(val * 100));
    holder.append(box); box.focus(); box.select();
    let closed = false;
    const done = (commit) => {
      if (closed) return;          // blur fires after Enter has already removed it
      closed = true;
      const n = parseFloat(box.value);
      box.remove();
      if (commit && Number.isFinite(n)) set(clamp(n / 100, -1, 1));
    };
    box.addEventListener('keydown', (ev) => {
      ev.stopPropagation();
      if (ev.key === 'Enter') done(true); else if (ev.key === 'Escape') done(false);
    });
    box.addEventListener('blur', () => done(true));
  }

  // The knob alone: the caller owns the row, because mute and solo share it.
  return { el: holder, set: (x) => { val = x; draw(); } };
}

/**
 * The same knob, sweeping from one end instead of from the centre.
 *
 * `panKnob` is bipolar because pan is: nothing is the middle, and the arc growing
 * either way from top-dead-centre is the whole reading. An attack time has no middle —
 * it has a floor — so this fills from the left stop, which is the pot on every synth
 * ever built.
 *
 * Returns the same shape `slider` does (`{ wrap, label, set }`), so a caller can swap
 * one for the other without knowing which it has.
 */
function knob({ min, max, step, value, fmt, onInput, reset, scale = 1, origin = null,
  taper = null, floor = 0, onStart = null, onEnd = null }) {
  const NS = 'http://www.w3.org/2000/svg';
  const wrap = document.createElement('div');
  wrap.className = 'row potrow';
  const k = document.createElement('span'); k.className = 'k';
  const holder = document.createElement('div'); holder.className = 'panholder';

  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 44 44');
  svg.setAttribute('class', 'panpot vepot');
  const track = document.createElementNS(NS, 'path'); track.setAttribute('class', 'pottrack');
  const arc = document.createElementNS(NS, 'path'); arc.setAttribute('class', 'potarc');
  const face = document.createElementNS(NS, 'circle');
  face.setAttribute('cx', 22); face.setAttribute('cy', 22); face.setAttribute('r', 13);
  face.setAttribute('class', 'potface');
  const text = document.createElementNS(NS, 'text');
  text.setAttribute('x', 22); text.setAttribute('y', 22);
  text.setAttribute('class', 'pottext');
  text.setAttribute('text-anchor', 'middle');
  text.setAttribute('dominant-baseline', 'central');
  svg.append(track, arc, face, text);
  holder.append(svg);
  wrap.append(k, holder);

  const SWEEP = 145;                       // degrees either side of top centre
  const R = 18;
  const pt = (deg) => {
    const a = (deg - 90) * Math.PI / 180;
    return [22 + Math.cos(a) * R, 22 + Math.sin(a) * R];
  };
  const arcPath = (fromDeg, toDeg) => {
    const [x1, y1] = pt(fromDeg); const [x2, y2] = pt(toDeg);
    const big = Math.abs(toDeg - fromDeg) > 180 ? 1 : 0;
    const sweep = toDeg > fromDeg ? 1 : 0;
    return `M ${x1} ${y1} A ${R} ${R} 0 ${big} ${sweep} ${x2} ${y2}`;
  };
  track.setAttribute('d', arcPath(-SWEEP, SWEEP));

  // A scale above one gives the low end more physical travel without changing the
  // stored range. Envelope times opt into this shared response; ordinary desk knobs
  // remain linear because their values do not represent elapsed time.
  const curve = Number.isFinite(scale) && scale > 0 ? scale : 1;
  // A BIPOLAR pot tapers about its origin, not across the span. Curving the whole range
  // would drag the centre detent off twelve o'clock — on -10..+10 at curve 3 the middle
  // of the travel reads -7.5 — so each side gets the response applied to its own distance
  // from the origin instead, and zero stays where the eye expects it. Only the two
  // together take this path: without an origin, or at curve 1, the arithmetic below is
  // the linear one it has always been.
  const bipolar = Number.isFinite(origin) && curve !== 1;
  // A TIME pot is dialled in ratios, not in fractions of its ceiling: 5ms to 10ms is the
  // same move as 1s to 2s, and no exponent says that. `taper: 'log'` spends the travel
  // evenly per decade instead — with `floor` as the smallest length it reaches, and the
  // left stop still landing on `min`, so a stage that may be switched off can be.
  const logTaper = taper === 'log' && max > 0;
  const logLo = logTaper ? Math.max(min, floor > 0 ? floor : step, 1e-6) : 0;
  const logSpan = logTaper ? Math.log(max / logLo) : 0;
  const originFrac = (max - min) ? clamp((origin - min) / (max - min), 0, 1) : 0;
  const valueAt = (position) => {
    const pos = clamp(position, 0, 1);
    if (logTaper) return pos <= 0 ? min : logLo * Math.exp(logSpan * pos);
    if (!bipolar) return min + (max - min) * Math.pow(pos, curve);
    if (pos >= originFrac) {
      const f = originFrac >= 1 ? 0 : (pos - originFrac) / (1 - originFrac);
      return origin + (max - origin) * Math.pow(f, curve);
    }
    const f = originFrac <= 0 ? 0 : (originFrac - pos) / originFrac;
    return origin - (origin - min) * Math.pow(f, curve);
  };
  const positionAt = (x) => {
    if (logTaper) {
      const t = clamp(x, min, max);
      // Anything at or under the floor — including a true zero — sits at the stop.
      return t <= logLo ? 0 : clamp(Math.log(t / logLo) / logSpan, 0, 1);
    }
    if (!bipolar) {
      const frac = (max - min) ? clamp((x - min) / (max - min), 0, 1) : 0;
      return Math.pow(frac, 1 / curve);
    }
    const v = clamp(x, min, max);
    if (v >= origin) {
      const span = max - origin;
      return originFrac + (1 - originFrac) * Math.pow(span > 0 ? (v - origin) / span : 0, 1 / curve);
    }
    const span = origin - min;
    return originFrac - originFrac * Math.pow(span > 0 ? (origin - v) / span : 0, 1 / curve);
  };
  // Where the arc grows FROM. Left stop for everything with a floor — an attack time,
  // a level — and the centre for a bipolar control, which is `panKnob`'s reading applied
  // to a pot that still has a min, a max and a step: on a pitch AMOUNT, up and down are
  // opposite directions and an arc that fills leftward from the middle says so at a
  // glance, where a left-filled one says "a bit under half".
  const originPos = Number.isFinite(origin) ? positionAt(clamp(origin, min, max)) : 0;
  const originDeg = -SWEEP + originPos * SWEEP * 2;
  let val = clamp(value, min, max);
  let position = positionAt(val);
  const draw = () => {
    const deg = -SWEEP + position * SWEEP * 2;
    // Nothing to draw at the origin — an arc of zero length still paints a round cap,
    // which reads as a value slightly off it rather than as the value itself.
    arc.setAttribute('d', Math.abs(position - originPos) < 0.004 ? '' : arcPath(originDeg, deg));
    text.textContent = fmt(val);
  };
  draw();

  const set = (x) => {
    onStart?.();
    const stepped = Math.round(x / step) * step;
    const next = clamp(Number(stepped.toFixed(6)), min, max);
    // A pot held against its stop still takes every pointer move — you are past the end
    // of the travel and the hand keeps going — and each one was passed on as an edit of
    // a value that had not moved. Dozens a second of re-writing the preset, rebuilding
    // the rack and re-levelling it, for nothing anyone could hear.
    //
    // Only inside a DRAG. A click, a reset or a type-in still writes its value through
    // even when it matches what is showing: those are a hand saying "this one", and a
    // derived row can put a number somewhere the pot's own reading does not show.
    if (dragging && next === val) return;
    val = next;
    position = positionAt(val);
    draw();
    onInput(val);
    if (!dragging) onEnd?.();
  };
  const setPosition = (x) => set(valueAt(x));

  // The drag accumulates in its own unstepped position, not in `position`: `set`
  // rounds to the step and re-derives `position` from the result, so on a coarse pot
  // (UNISON is four steps across the whole sweep) each few-pixel move would round
  // back to where it started and the pot could never leave its value.
  let dragging = false, lastX = 0, lastY = 0, moved = 0, fromText = false, dragPos = 0;
  svg.addEventListener('pointerdown', (e) => {
    if (holder.querySelector('.typein')) return;
    dragging = true; moved = 0; fromText = e.target === text; dragPos = position;
    lastX = e.clientX; lastY = e.clientY;
    svg.setPointerCapture(e.pointerId); e.preventDefault();
  });
  svg.addEventListener('pointermove', (e) => {
    if (!dragging) return;
    const dx = e.clientX - lastX, dy = lastY - e.clientY;
    moved = Math.max(moved, Math.abs(dx), Math.abs(dy));
    lastX = e.clientX; lastY = e.clientY;
    // Whichever axis moved more wins, so neither grip feels wrong. A full sweep in
    // about 150px, a fifth of that with shift — the same feel as the desk's faders.
    const px = Math.abs(dx) > Math.abs(dy) ? dx : dy;
    dragPos = clamp(dragPos + (px / 150) * (e.shiftKey ? 0.2 : 1), 0, 1);
    setPosition(dragPos);
  });
  const stop = () => {
    if (dragging && fromText && moved < 3) openEditor();
    dragging = false;
    onEnd?.();
  };
  svg.addEventListener('pointerup', stop);
  svg.addEventListener('pointercancel', stop);
  svg.addEventListener('dblclick', () => set(reset));
  svg.title = 'Drag to change · click the number to type · double-click to reset';

  function openEditor() {
    if (holder.querySelector('.typein')) return;
    const box = document.createElement('input');
    box.type = 'text'; box.className = 'typein panin';
    box.value = String(val);
    holder.append(box); box.focus(); box.select();
    let closed = false;
    const done = (commit) => {
      if (closed) return;            // blur fires after Enter has already removed it
      closed = true;
      const n = parseFloat(box.value);
      box.remove();
      if (commit && Number.isFinite(n)) set(n);
    };
    box.addEventListener('keydown', (ev) => {
      ev.stopPropagation();
      if (ev.key === 'Enter') done(true); else if (ev.key === 'Escape') done(false);
    });
    box.addEventListener('blur', () => done(true));
  }

  // Click the label to reset, the way every slider on the desk does.
  k.classList.add('resettable');
  k.title = `Reset to ${fmt(reset)}`;
  k.addEventListener('click', () => set(reset));

  return { wrap, label: k, set: (x) => { val = clamp(x, min, max); position = positionAt(val); draw(); } };
}

/** A one-line labelled checkbox — a whole row plus a full-width button was three
 *  lines of card height to say one boolean. */
function checkRow(label, checked, onChange) {
  const row = document.createElement('label');
  row.className = 'checkrow';
  const box = document.createElement('input');
  box.type = 'checkbox';
  box.checked = !!checked;
  box.onchange = () => onChange(box.checked);
  const t = document.createElement('span');
  t.textContent = label;
  row.append(box, t);
  return row;
}

function effectsOf(key) {
  const mix = mixFor(trackId);
  // The master opens EMPTY — nothing on the bus until you put it there. The seed is
  // read on the way OUT rather than stored, so whatever it is applies to every song,
  // including the ones that already have a saved mix, and no song gains a
  // masterEffects line in mix.js for a chain nobody has touched.
  if (key === '__master') return mix.masterEffects || DEFAULT_MASTER_CHAIN();
  if (key && key.startsWith('__aux:')) return mix.fx?.[key.slice(6)]?.effects || [];
  return mix.lanes[key]?.effects || [];
}

function liveChain(key) {
  if (key === '__master') return Audio.mixer?.masterEffects;
  if (key && key.startsWith('__aux:')) return Audio.mixer?.auxEffects(key.slice(6));
  return Audio.mixer?.lane(key)?.effects;
}

function bypassOn(key, i, on) {
  if (key === '__master') Audio.mixer?.setMasterEffectBypass(i, on);
  else if (key && key.startsWith('__aux:')) Audio.mixer?.setAuxEffectBypass(key.slice(6), i, on);
  else Audio.mixer?.lane(key)?.setEffectBypass(i, on);
}

function targetLabel(key) {
  if (key === '__master') return 'MASTER';
  if (key && key.startsWith('__aux:')) {
    return (AUXES.find((a) => a.id === key.slice(6))?.name || key.slice(6)) + ' return';
  }
  if (pendingAddTrack?.key === key) return pendingAddTrack.label;
  const found = deskLanes(viewBank(), 1).find((l) => l.key === key);
  // A DELETED track has no row and no strip, so it is not in the desk's lane list —
  // and the one place it is still named is the menu that offers to put it back. The
  // engine's own list still knows it, which is what that falls through to.
  return found?.label || cap(LANES.find((l) => l.key === key)?.label) || cap(key);
}

function setEffects(key, list) {
  const bpm = deskTempo();
  // Stored through storeEffects, not beside it: this used to carry its own copy of
  // the same three branches, and the copies disagreed about what an empty master
  // chain means — one wrote it, the other deleted it, and taking the seeded bus
  // compressor off the master came straight back.
  editMix((m) => storeEffects(m, key, list), null);
  if (key === '__master') Audio.mixer?.setMasterEffects(list, bpm);
  else if (key && key.startsWith('__aux:')) Audio.mixer?.setAuxEffects(key.slice(6), list, bpm);
  else Audio.mixer?.lane(key)?.setEffects(list, bpm);
  // Rebuild the rack, not just the summary line: the per-effect bypass buttons live
  // on the strip and have to appear and disappear with the chain.
  buildRack();
}

/**
 * What a dropdown entry reads as. The value is the engine's — a BiquadFilter's type
 * is the string 'lowpass' and nothing else — so the capital goes on at the last
 * moment, on the label alone, and never on what gets stored or sent to the node.
 */
const optionLabel = (s) => String(s).replace(/\b[a-z]/g, (c) => c.toUpperCase());

/**
 * A select row with a live readout, for parameters that are a note division rather
 * than a number — the delay's time, an LFO's rate.
 *
 * A division is still a select, but it occupies the same two-line footprint as every
 * other effect control: label and derived readout on the head line, select underneath.
 * The old one-line exception put RATE/TIME's select at the top of the card while the
 * neighbouring sliders and named choices put their controls underneath their labels.
 * Keeping the value in the head makes the row's rhythm legible without sacrificing the
 * useful Hz/seconds readout.
 */
function divisionRow(label, divisions, value, fmt, onChange) {
  const row = document.createElement('div'); row.className = 'row';
  const hd = document.createElement('div'); hd.className = 'head';
  const k = document.createElement('span'); k.className = 'k'; k.textContent = label;
  const v = document.createElement('span'); v.className = 'v';
  hd.append(k, v);
  const sel = document.createElement('select'); sel.className = 'fxsel';
  for (const [name, beats] of Object.entries(divisions)) {
    const o = document.createElement('option');
    o.value = String(beats); o.textContent = optionLabel(name);
    if (Math.abs(beats - value) < 1e-6) o.selected = true;
    sel.append(o);
  }
  const show = () => { v.textContent = fmt(+sel.value); };
  show();
  sel.onchange = () => { show(); onChange(+sel.value); };
  row.append(hd, sel);
  return row;
}

/** A named choice — a filter's shape, anything else that is a list not a range. */
function optionRow(label, options, value, onChange) {
  const row = document.createElement('div'); row.className = 'row';
  const hd = document.createElement('div'); hd.className = 'head';
  const k = document.createElement('span'); k.className = 'k'; k.textContent = label;
  hd.append(k);
  const sel = document.createElement('select'); sel.className = 'fxsel';
  for (const o of options) {
    const opt = document.createElement('option');
    opt.value = o; opt.textContent = optionLabel(o);
    if (o === value) opt.selected = true;
    sel.append(opt);
  }
  sel.onchange = () => onChange(sel.value);
  row.select = sel;
  row.append(hd, sel);
  return row;
}

/**
 * Draw one insert's editable parameter surface.
 *
 * Channel inserts and bar snapshots are the same engine objects (`{ id, params,
 * bypass }`). Keeping their controls here means a Delay cannot expose tempo mode in
 * one editor and only milliseconds in the other, and a new effect automatically
 * becomes editable in both places. The caller owns where changes land: the channel
 * inspector supplies a live-node writer, while Bar Effects supplies a staged array
 * that is silent until Apply.
 */
function fillEffectControls({
  grid, def, entry, presetScope = 'inserts', patch, replaceParams, rebuild,
  tag = () => null,
}) {
  if (!def) return;
  const entryParams = { ...(def.defaults || {}), ...(entry.params || {}) };
  let presetSelect = null;
  const syncPreset = () => {
    if (presetSelect) {
      presetSelect.value = matchEffectPreset(def.id, entryParams, presetScope) || 'Custom';
    }
  };
  const applyPatch = (next, part = null) => {
    patch(next, tag(part));
    Object.assign(entryParams, next);
    syncPreset();
  };
  const applySnapshot = (snapshot, part = null) => {
    const resolved = resolveEffectSnapshot(def.id, snapshot);
    if (!resolved) return false;
    replaceParams(resolved, tag(part));
    for (const key of Object.keys(entryParams)) delete entryParams[key];
    Object.assign(entryParams, def.defaults || {}, resolved);
    syncPreset();
    return true;
  };

  const presetNames = effectPresetNames(def.id, presetScope);
  if (presetNames.length) {
    const currentPreset = matchEffectPreset(def.id, entryParams, presetScope) || 'Custom';
    const row = optionRow('PRESET', ['Custom', 'Default', ...presetNames], currentPreset, (name) => {
      if (name === 'Custom') return;
      const resolved = resolveEffectPreset(def.id, name, presetScope);
      if (!resolved || !applySnapshot(resolved, 'preset')) return;
      rebuild();
    });
    presetSelect = row.select;
    grid.append(row);
  }

  // Delay time is either a note division or free milliseconds, and a modulation rate
  // either a division or a free frequency. Only the active mode is drawn.
  const hasSync = (def.params || []).includes('sync');
  const synced = hasSync && (entryParams.sync ?? 1) >= 0.5;
  for (const pname of visibleParams(def, entryParams)) {
    const rateSynced = (entryParams.rateSync ?? 0) >= 0.5;
    if (pname === 'rateSync') {
      grid.append(checkRow('Tempo Mode', rateSynced, (on) => {
        applyPatch({ rateSync: on ? 1 : 0 }); rebuild();
      }));
      continue;
    }
    if (pname === 'rateDivision') {
      grid.append(divisionRow('RATE', RATE_DIVISIONS, entryParams.rateDivision ?? 1,
        (beats) => `${(deskTempo() / (60 * beats)).toFixed(2)}Hz`,
        (beats) => applyPatch({ rateDivision: beats }, 'rate')));
      continue;
    }
    if (pname === 'sync') {
      grid.append(checkRow('Tempo Mode', synced, (on) => {
        applyPatch({ sync: on ? 1 : 0 }); rebuild();
      }));
      continue;
    }
    if (pname === 'division') {
      grid.append(divisionRow('TIME', SYNC_DIVISIONS, entryParams.division ?? 0.5,
        (beats) => fmtDelay(syncSeconds(beats, deskTempo())),
        (beats) => applyPatch({ division: beats }, 'div')));
      continue;
    }

    const rng = paramRange(pname, def);
    if (rng.toggle) {
      grid.append(checkRow(paramLabel(pname, def),
        (entryParams[pname] ?? def.defaults?.[pname] ?? 0) >= 0.5,
        (on) => applyPatch({ [pname]: on ? 1 : 0 })));
      continue;
    }
    if (rng.options) {
      grid.append(optionRow(paramLabel(pname, def), rng.options,
        entryParams[pname] ?? rng.options[0],
        (value) => applyPatch({ [pname]: value })));
      continue;
    }

    const value = entryParams[pname] ?? rng.min;
    const useLog = rng.log && rng.min > 0;
    const logToPos = (v) => Math.log(v / rng.min) / Math.log(rng.max / rng.min);
    const logFromPos = (p) => rng.min * Math.pow(rng.max / rng.min, p);
    const unitFmt = (x) => (rng.unit === 'Hz' && x >= 1000 ? (x / 1000).toFixed(1) + 'k'
      : rng.unit === 's' ? (x * 1000).toFixed(0) + 'ms'
      : x.toFixed(rng.step >= 1 ? 0 : 2)) + (rng.unit && rng.unit !== 's' ? ' ' + rng.unit : '');
    const row = slider({
      min: useLog ? 0 : rng.min,
      max: useLog ? 1 : rng.max,
      step: useLog ? 0.001 : rng.step,
      value: useLog ? logToPos(value) : value,
      reset: useLog ? logToPos(def.defaults[pname] ?? rng.min) : (def.defaults[pname] ?? rng.min),
      fmt: (x) => unitFmt(useLog ? logFromPos(x) : x),
      display: useLog ? {
        format: (pos) => unitFmt(logFromPos(pos)),
        parse: (s) => {
          const n = parseFloat(String(s).replace(/[^0-9.\-+eE]/g, ''));
          return Number.isFinite(n) ? clamp(logToPos(n), 0, 1) : null;
        },
      } : undefined,
      onInput: (x) => applyPatch({ [pname]: useLog ? logFromPos(x) : x }, pname),
    });
    row.label.textContent = paramLabel(pname, def);
    grid.append(row.wrap);
  }
}

/**
 * The strip's OWN device, pinned as the first card in the panel: a send's delay or
 * its reverb. These used to be rows on the strip itself, where they crowded out the
 * return EQ and still had no room to be read — a note division and a damping
 * frequency need more than 132px of column.
 *
 * It is not an insert: no bypass, no close, no dragging. It is what the strip is.
 */
function pinnedCard(key) {
  const card = document.createElement('div');
  card.className = 'device pinned';
  const bar = document.createElement('div'); bar.className = 'devbar';
  const h = document.createElement('h4');
  const badge = document.createElement('span'); badge.className = 'devbadge'; badge.textContent = 'BUILT IN';
  bar.append(h, badge);
  const grid = document.createElement('div'); grid.className = 'devgrid';
  card.append(bar, grid);

  const def = AUXES.find((a) => a.id === key.slice(6));
  if (!def) return null;
  const cur = fxOf(mixFor(trackId))[def.id];
  h.textContent = def.name;
  const fxSlider = (param, label, opts) => {
    const r = slider({ ...opts, onInput: (x) => editFx(def.id, { [param]: x }, `${def.id}:${param}`) });
    r.label.textContent = label;
    grid.append(r.wrap);
  };

  if (def.type === 'delay') {
    grid.append(divisionRow('TIME', DELAY_DIVISIONS, cur.division,
      // What the line will actually run, not what the division asks for: past a few
      // bars the delay buffer is the limit and the readout should say so.
      (beats) => fmtDelay(syncSeconds(beats, deskTempo())),
      (beats) => editFx(def.id, { division: beats }, `${def.id}:division`)));
    fxSlider('feedback', 'FEEDBACK', {
      min: 0, max: 0.9, step: 0.01, value: cur.feedback,
      reset: AUX_DEFAULTS[def.id].feedback, fmt: (x) => x.toFixed(2),
    });
    fxSlider('tone', 'DAMPING', {
      min: 400, max: 12000, step: 100, value: cur.tone, reset: AUX_DEFAULTS[def.id].tone,
      fmt: (x) => (x >= 1000 ? `${(x / 1000).toFixed(1)}k` : String(x)) + ' Hz',
    });
  } else {
    // Log taper: decay spans 0.1–10s (100×), pre-delay spans 0.001–0.2s (200×).
    // Tiny differences at the short end matter — a 2ms vs 10ms pre-delay is the
    // difference between intimacy and distance.
    const logSliders = (mn, mx) => {
      const toPos = (v) => Math.log(v / mn) / Math.log(mx / mn);
      const fromPos = (p) => mn * Math.pow(mx / mn, p);
      return { toPos, fromPos };
    };
    const decLog = logSliders(0.1, 10);
    fxSlider('decay', 'DECAY', {
      min: 0, max: 1, step: 0.001,
      value: decLog.toPos(cur.decay),
      reset: decLog.toPos(AUX_DEFAULTS[def.id].decay),
      fmt: (pos) => `${decLog.fromPos(pos).toFixed(1)}s`,
      display: {
        format: (pos) => `${decLog.fromPos(pos).toFixed(1)}s`,
        parse: (s) => {
          const n = parseFloat(String(s).replace(/[^0-9.\-+eE]/g, ''));
          return Number.isFinite(n) ? clamp(decLog.toPos(n), 0, 1) : null;
        },
      },
    });
    const preLog = logSliders(0.001, 0.2);
    fxSlider('preDelay', 'PRE-DELAY', {
      min: 0, max: 1, step: 0.001,
      value: preLog.toPos(cur.preDelay || 0.001),
      reset: preLog.toPos(AUX_DEFAULTS[def.id].preDelay),
      fmt: (pos) => `${(preLog.fromPos(pos) * 1000).toFixed(0)}ms`,
      display: {
        format: (pos) => `${(preLog.fromPos(pos) * 1000).toFixed(0)}ms`,
        parse: (s) => {
          const n = parseFloat(String(s).replace(/[^0-9.\-+eE]/g, ''));
          return Number.isFinite(n) ? clamp(preLog.toPos(n / 1000), 0, 1) : null;
        },
      },
    });
    const note = document.createElement('div');
    note.className = 'devnote';
    note.textContent = 'Tone the tail with the return EQ on the strip — that is what a damping '
      + 'control is, and this reverb is a convolution so it has no other.';
    grid.append(note);
  }
  bindDefaultSave(card, {
    scope: 'returns', id: def.id, name: def.name,
    snapshot: () => {
      const current = fxOf(mixFor(trackId))[def.id] || {};
      return Object.fromEntries((def.presetParams || []).map((key) => [key, current[key]]));
    },
  });
  return card;
}

/** Keep the Effects panel header in sync with the selected channel. Notes names a
 *  preset too, but its own one — see syncNotesPanel: Effects is always the selected
 *  strip, the roll is not. */
function updatePanelTitles() {
  renderPresetHeading($('devtitle'), selectedLane);
}

function buildDevices() {
  const rack = $('devrack');
  rack.textContent = '';
  updatePanelTitles();
  if (!selectedLane) {
    return;
  }

  // A send's delay or reverb comes first: it is what the strip IS, and the inserts
  // are things you put in front of it. The master has no card of its own — its
  // limiter is a button under the fader, where nothing about the rack can put it
  // anywhere but last.
  const pinned = selectedLane.startsWith('__aux:') ? pinnedCard(selectedLane) : null;
  if (pinned) rack.append(pinned);

  const list = effectsOf(selectedLane);
  if (!list.length) {
    rack.append(addCard(true));
    fitDevices();
    return;
  }

  let dragFrom = null;
  rack.addEventListener('dragover', (e) => e.preventDefault());

  list.forEach((entry, i) => {
    const def = EFFECT_BY_ID[entry.id];
    const card = document.createElement('div');
    card.className = 'device' + (entry.bypass ? ' bypassed' : '');
    // Draggable only while the pointer went down on the title bar. With the whole
    // card draggable, dragging a slider inside it started a card drag instead —
    // the control and the container were fighting for the same gesture.
    card.draggable = false;
    card.dataset.idx = String(i);

    const bar = document.createElement('div');
    bar.className = 'devbar';
    const byp = document.createElement('button');
    byp.className = 'devtoggle' + (entry.bypass ? '' : ' on');
    byp.append(powerIcon());
    byp.title = entry.bypass ? 'Enable this effect' : 'Bypass this effect';
    byp.onclick = () => {
      const next = list.map((e, j) => (j === i ? { ...e, bypass: !e.bypass } : e));
      editMix((m) => storeEffects(m, selectedLane, next), null);
      bypassOn(selectedLane, i, !entry.bypass);
      buildRack();
    };
    const h = document.createElement('h4');
    h.textContent = def ? def.name : entry.id;
    const close = document.createElement('button');
    close.className = 'devclose';
    close.append(closeIcon());
    close.title = `Remove ${def ? def.name : entry.id} from this chain`;
    close.onclick = () => {
      setEffects(selectedLane, list.filter((_, j) => j !== i));
      toast(`${def ? def.name : entry.id} removed`);
    };
    bar.append(byp, h, close);
    bar.title = 'Drag here to reorder';
    bar.addEventListener('mousedown', (ev) => {
      if (ev.target.closest('button')) return;
      card.draggable = true;
    });
    addEventListener('mouseup', () => { card.draggable = false; }, { once: true });
    card.append(bar);
    const grid = document.createElement('div');
    grid.className = 'devgrid';
    card.append(grid);
    card.addEventListener('dragstart', (e) => {
      dragFrom = i;
      card.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
      // Firefox will not start a drag without payload.
      e.dataTransfer.setData('text/plain', String(i));
    });
    card.addEventListener('dragend', () => {
      dragFrom = null; card.classList.remove('dragging'); card.draggable = false;
    });
    card.addEventListener('dragover', (e) => {
      e.preventDefault();
      if (dragFrom == null || dragFrom === i) return;
      card.classList.add('dropzone');
    });
    card.addEventListener('dragleave', () => card.classList.remove('dropzone'));
    card.addEventListener('drop', (e) => {
      e.preventDefault();
      card.classList.remove('dropzone');
      if (dragFrom == null || dragFrom === i) return;
      const next = list.slice();
      const [moved] = next.splice(dragFrom, 1);
      next.splice(i, 0, moved);
      dragFrom = null;
      setEffects(selectedLane, next);
      toast(`${moved.id} moved to position ${i + 1}`);
    });

    if (def) {
      bindDefaultSave(card, {
        scope: 'inserts', id: def.id, name: def.name,
        snapshot: () => {
          const current = { ...(def.defaults || {}), ...(list[i]?.params || {}) };
          return Object.fromEntries((def.params || []).map((key) => [key, current[key]]));
        },
      });
    }
    const patch = (p, tag) => {
      const next = list.map((e, j) => (j === i ? { ...e, params: { ...(e.params || {}), ...p } } : e));
      const link = liveChain(selectedLane)?.[i];
      if (link) link.set(p, deskTempo());
      editMix((m) => storeEffects(m, selectedLane, next), tag);
      list[i] = next[i];
    };
    const replaceParams = (resolved, tag) => {
      const next = list.map((e, j) => (j === i ? { ...e, params: resolved } : e));
      const link = liveChain(selectedLane)?.[i];
      if (link) link.set(resolved, deskTempo());
      editMix((m) => storeEffects(m, selectedLane, next), tag);
      list[i] = next[i];
    };
    fillEffectControls({
      grid, def, entry, patch, replaceParams, rebuild: buildDevices,
      tag: (part) => part ? `fx:${selectedLane}:${i}:${part}` : null,
    });

    rack.append(card);
  });
  rack.append(addCard());              // the next slot, at the end of the chain
  fitDevices();
}

/**
 * The panel's height, reserved ONCE for the tallest card the catalogue can produce.
 *
 * It used to be reserved for the tallest card it had happened to show so far, which
 * meant the panel — and the whole rack sitting on top of it — moved a few pixels
 * every time you opened a channel whose effect was taller than anything you had
 * clicked yet. Cards run from two controls (the Gain) to 174px (the Advanced Delay),
 * so that is a lot of small jumps before a session settles down.
 *
 * Only ever four rows tall, however long the list: the grid flows into extra COLUMNS
 * past four, so the Multiband Compressor's seventeen controls make a wide card and
 * not a tall one, and the reserved height still holds.
 *
 * Measured rather than written down: row heights move with the typeface, so a
 * constant would clip the tallest card in one font and waste a band of window in
 * another. The probe is the worst shape a card can take — a grid flows into a second
 * column past four rows, and the tallest row is the one stacking a full-width select
 * under its label. Named choices and tempo divisions use that same two-line footprint
 * now, so the probe represents either kind of select and does not let fitDevices grow
 * the panel a step at a time, which is the jumping this exists to stop.
 */
function reserveDevices() {
  const probe = document.createElement('div');
  probe.className = 'device';
  probe.style.cssText = 'position:absolute; visibility:hidden; left:-9999px; top:0';
  const bar = document.createElement('div');
  bar.className = 'devbar';
  const title = document.createElement('h4');
  title.textContent = 'Probe';
  bar.append(title);
  const grid = document.createElement('div');
  grid.className = 'devgrid';
  for (let i = 0; i < 4; i++) {
    grid.append(optionRow('SHAPE', ['lowpass'], 'lowpass', () => {}));
  }
  probe.append(bar, grid);
  document.body.append(probe);
  // The cards' own height, plus a few pixels so the bottom border isn't flush
  // against the panel edge. The header is added separately in effectsNaturalHeight.
  const need = Math.ceil(h(probe) + 6);
  probe.remove();
  // Recorded as what the cards ASK for, not written to --devh. The planner clamps
  // it against the room actually available and against a dragged height, so the
  // measurement and the layout can no longer arrive at two different answers and
  // overwrite each other — which is what capDevices() used to referee, by reading
  // the panel's live height and making each fit depend on the previous one.
  autoDevH = need;
  fitStrips();
}

/**
 * The reserve is the height in all but exceptional cases; this is the guard for the
 * card that outgrows it anyway — a future effect with taller rows than the probe.
 * It only ever grows the ASK, and the planner still clamps that against the room
 * available, so it cannot take height off the rack on a short screen.
 */
function fitDevices() {
  requestAnimationFrame(() => {
    // A dragged height is a deliberate answer about how much of the shelf to see;
    // do not grow it behind the user's back when a taller card is opened.
    if (userFxH != null) return;
    // Folded, the rack is display:none and every card measures zero — a measurement
    // taken there would hand the panel back a height of nothing to unfold into.
    if ($('devices').classList.contains('collapsed')) return;
    const rack = $('devrack');
    const cards = [...rack.children].filter((c) => c.classList.contains('device'));
    if (!cards.length) return;
    // The cards are stretched to a common height, so their measured height is the
    // panel's, not their own. Let them stand up for one measurement to find out how
    // tall the tallest actually needs to be.
    rack.style.alignItems = 'flex-start';
    const tallest = Math.max(...cards.map(h));
    rack.style.alignItems = '';
    const need = Math.ceil(tallest + 6);
    if (need > autoDevH) {
      autoDevH = need;
      fitStrips();
    }
  });
}

// The catalogue, grouped for the picker. Anything a future effect adds that is not
// listed here still shows up, under Other — a new effect appearing nowhere would be
// a worse bug than one appearing in the wrong column.
const EFFECT_GROUPS = [
  ['Level & EQ', ['gain', 'peq', 'vowel', 'filter']],
  ['Delay', ['chandelay', 'delay', 'pingpong']],
  ['Modulation', ['chorus', 'chorus2', 'rhythmgate', 'flanger', 'ringmod', 'phaser', 'tremolo', 'vibrato', 'autofilter', 'autowah', 'autopanner']],
  ['Drive', ['exciter', 'distortion', 'bitcrusher', 'tape', 'chebyshev']],
  ['Space & stereo', ['reverb', 'doubler', 'widener', 'shifter', 'pitch']],
  ['Dynamics', ['l7', 'compressor', 'msComp', 'mbComp']],
];

function addEffect(id, at = null) {
  if (!id || !selectedLane) return;
  const cur = effectsOf(selectedLane);
  if (cur.length >= MAX_EFFECTS) {
    toast(`${MAX_EFFECTS} effects is the limit on one strip — remove one first`);
    return;
  }
  const next = [...cur];
  if (at == null) next.push({ id, params: {} });
  else next.splice(clamp(at, 0, next.length), 0, { id, params: {} });
  setEffects(selectedLane, next);
  toast(`${EFFECT_BY_ID[id].name} added to ${targetLabel(selectedLane)}`);
}

// One effect's settings, for copying onto another of the same kind. Separate from
// the strip clipboard: a Parametric EQ you have dialled in is worth moving on its
// own, without the channel it happens to sit on.
let fxClipboard = null;

/** The effect catalogue as a panel: grouped, and priced with its measured cost. */
function openPicker({ at = null, anchor = null, x = null, y = null } = {}) {
  restorablePopup = { kind: 'effectPicker', at };
  const el = $('fxpicker');
  el.textContent = '';
  const placed = new Set();
  const column = (title, ids) => {
    const list = ids.map((id) => EFFECT_BY_ID[id]).filter(Boolean);
    if (!list.length) return;
    const g = document.createElement('div');
    g.className = 'fxgroup';
    const h5 = document.createElement('h5');
    h5.textContent = title;
    g.append(h5);
    for (const def of list) {
      placed.add(def.id);
      const b = document.createElement('button');
      const n = document.createElement('span');
      n.textContent = def.name;
      const c = document.createElement('span');
      c.className = 'cost';
      c.textContent = `${(def.cost ?? 0).toFixed(2)}%`;
      b.append(n, c);
      b.title = `${def.name} — about ${(def.cost ?? 0).toFixed(2)}% of one core each`;
      b.onclick = () => { closeMenu(); addEffect(def.id, at); };
      g.append(b);
    }
    el.append(g);
  };
  for (const [title, ids] of EFFECT_GROUPS) column(title, ids);
  column('Other', EFFECTS.filter((e) => !placed.has(e.id)).map((e) => e.id));

  el.classList.add('show');
  // The effects inspector is flush right, so its catalogue opens immediately to its
  // left instead of covering the cards. Other callers keep the pointer/anchor route.
  // Either way the catalogue is pulled back inside the window.
  const r = el.getBoundingClientRect();
  const from = (anchor || $('devrack')).getBoundingClientRect();
  const inInspector = !!anchor?.closest?.('#devices');
  const left = inInspector ? $('devices').getBoundingClientRect().left - r.width - 6
    : (x != null ? x : from.right - r.width);
  const top = inInspector ? from.top : (y != null ? y : from.top - r.height - 6);
  el.style.left = `${Math.max(6, Math.min(left, innerWidth - r.width - 6))}px`;
  el.style.top = `${Math.max(6, Math.min(top, innerHeight - r.height - 6))}px`;
}

/**
 * The empty slot at the end of a chain: click it to add the next effect.
 *
 * `first` is the empty rack — nothing added yet, so the square is alone in the panel
 * and wears its plus faintly rather than waiting for the pointer to find it.
 */
function addCard(first = false) {
  const btn = document.createElement('button');
  btn.className = `devaddcard${first ? ' first' : ''}`;
  const full = effectsOf(selectedLane).length >= MAX_EFFECTS;
  btn.disabled = full;
  btn.title = full ? `${MAX_EFFECTS} effects is the limit on one strip`
    : `Add an effect to ${targetLabel(selectedLane)}`;
  btn.onclick = (ev) => {
    ev.stopPropagation();
    if (btn.disabled) return;
    if ($('fxpicker').classList.contains('show')) { closeMenu(); return; }
    closeMenu();
    openPicker({ anchor: btn, x: ev.clientX, y: ev.clientY });
  };
  return btn;
}
/**
 * Every panel boundary is a real resize edge: Timeline/Arrangement, Arrangement/
 * Notes, Notes/Mixer and Mixer/Effects. Their hit areas stay active even when one
 * side is folded, so dragging can reopen that side. The Mixer is the flexible region
 * that gives up space first.
 *
 * The element a hit area hangs off is the panel BELOW the border, not the one being
 * resized: #notes draws the Arrangement's bottom edge and #mixhead draws the Notes
 * panel's. That is why the two drag handlers look swapped relative to their names.
 */
function syncPanelResizeEdges() {
  if ($('upperwork') && $('lowerwork')) {
    for (const id of ['timeline', 'mixhead', 'notes', 'devices']) $(id).classList.remove('edge-resizable');
    return;
  }
  $('timeline').classList.add('edge-resizable');
  $('mixhead').classList.add('edge-resizable');
  $('notes').classList.add('edge-resizable');
  $('devices').classList.add('edge-resizable');
}

// The former bottom shelf is a modeless right-side inspector. Keep the compatibility function name
// because effect-slot and tutorial paths already call `setDevicesFolded(false)` to
// reveal it; `on` now simply means closed.
function setDevicesFolded(on, refit = true) {
  $('devices').classList.remove('collapsed');
  $('devices').classList.toggle('fxwindow-open', !on);
  $('devices').setAttribute('aria-hidden', on ? 'true' : 'false');
  $('devfold').classList.remove('folded');
  $('devfold').title = 'Close Effects';
  $('devfold').setAttribute('aria-label', 'Close Effects');
  if (refit) scheduleDeskFit(true);
}

$('devfold').onclick = () => setDevicesFolded(true);
setDevicesFolded(true, false);

/** Select one track and reveal the modeless inspector for its channel inserts. */
function openChannelEffects(key) {
  if (!key) return;
  selectLane(key);
  setDevicesFolded(false);
}



function selectLane(key) {
  // A preset editor is docked to the lane that opened it. Once selection moves to a
  // different channel, leaving that panel mounted makes the visible controls describe
  // the previous strip while the desk highlight and keyboard describe the new one. Take
  // down both the compact panel and any full-window synth editor before changing the
  // selection; the next channel can open its own editor explicitly.
  if (voiceEditor.isOpen() && voiceEditor.laneKey && voiceEditor.laneKey !== key) {
    dismissVoiceEditor();
  }
  selectedLane = key;
  // The selection moving off a name puts that name back to its first click.
  if (armedPresetLane !== key) armedPresetLane = null;
  localStorage.setItem(LANE_KEY, key);
  for (const el of document.querySelectorAll('.strip[data-lane]')) {
    const selected = el.dataset.lane === key;
    el.classList.toggle('selected', selected);
    el.setAttribute('aria-selected', selected ? 'true' : 'false');
  }
  const chosenStrip = document.querySelector('.strip[data-lane].selected');
  // The arrangement can select a channel whose strip is outside the horizontally
  // scrolled rack. When the Mixer is the available lower workspace, reveal the strip
  // by the smallest amount so the visible highlight and the selected row cannot
  // disagree. Roll and Pattern preserve the rack's scroll position while it is hidden.
  if (chosenStrip && $('desk').dataset.lowerView === 'mixer' && $('rack').contains(chosenStrip)) {
    const rack = $('rack');
    const rr = rack.getBoundingClientRect();
    const tr = chosenStrip.getBoundingClientRect();
    if (tr.left < rr.left) rack.scrollLeft -= rr.left - tr.left + 6;
    else if (tr.right > rr.right) rack.scrollLeft += tr.right - rr.right + 6;
  }
  syncArrangementLaneSelection({ reveal: true });
  // Do not leave the previous lane's playback accent behind until the next beat
  // after selection moves; the selected-only cue should change immediately.
  clearArrangementPlayback();
  buildDevices();
  // Drums or pitched decides whether there is a roll in the panel at all. Before the
  // refresh below, so a roll on its way out is not repainted first.
  syncNotesPanel();
  // The roll is scoped through lane(), so changing the strip selection must repaint it
  // while it is open. Without this, the panel header follows the click but the roll
  // keeps the previous lane's rows and notes until another roll gesture occurs.
  // Not while it is off screen: a hidden roll paints nothing, and the fit it would take
  // from the drum channel it is standing in for is a window onto the wrong part.
  //
  // Through the same scheduler `markBar` uses, not straight at the grids: a click on a
  // bar cell is a lane change AND a range change, and painting each of them where it
  // happens rebuilt the whole field twice for one click.
  if (notesRollUp() || notesKitUp()) scheduleSelectionEditors();
  // The Notes panel is this channel's part, so moving the selection redraws the roll.
  // The roll's own `lane()` already follows the selection; the panel stays open at
  // whatever fold state the user left it in.
  // The keyboard plays the SELECTED channel, so it follows the selection — new keys,
  // in the octave the new channel's part is written in.
  refreshOsk();
}

// ---- arrangement -----------------------------------------------------------
// One row per instrument, one cell per bar, shaded by how busy that bar is. This
// is the answer to "there is a lane called crash but I have no idea where it
// sounds" — you can see it, and click straight to it.
let arrCells = [];
// What you picked in the grid — a lane and a RANGE of bars. `from` and `to` are the
// same bar for a plain click, which is what every gesture that predates ranges still
// produces, so the one-bar case needed no special handling anywhere.
//
// The timeline owns the song-range selection. A lane key is added only when an
// arrangement row is the current target for lane-specific actions; the range itself
// remains the same selection in both places.
let selectedBar = null;
// Delete is deliberately scoped to the last surface the user worked on. A bar selected
// in the arrangement may be erased; clicking Notes, the Pattern editor or the Mixer must
// take that destructive key away from the arrangement before it can do anything.
let arrangementKeyboardActive = false;
const lowerSurface = $('lowerwork');
lowerSurface?.addEventListener('pointerdown', () => { arrangementKeyboardActive = false; });
// Deliberately NOT cleared by `loadTrack`. Track and note clips hold resolved musical
// values rather than source-song section references, so they mean the same thing in
// any song — and lifting a part out of one song into another is a reason to have a
// clipboard at all.
let arrangementClipboard = null;

/**
 * What the clipboard holds, named the way it was when it was copied.
 *
 * `targetLabel` answers for the song ON SCREEN, and a clip outlives the song it came
 * from. Asked after a song switch it named the DESTINATION's track for that lane key,
 * so the menu offered to paste "Bass" from a song whose bass had never been copied —
 * and where the new song had no such lane, it fell back to the bare key. The clip
 * carries the name it had at copy time, and says which song that was whenever the
 * answer is not the one you are looking at.
 */
const clipLabel = (clip) => {
  if (!clip) return '';
  const name = clip.label || targetLabel(clip.lane);
  return clip.song && clip.song !== trackId ? `${name} — ${clip.songTitle || clip.song}` : name;
};

/** Who and where a clip came from, stamped at copy time. See `clipLabel`. */
const clipOrigin = (label) => ({ label, song: trackId, songTitle: track?.title || trackId });

const copyData = (value) => (value == null ? value : JSON.parse(JSON.stringify(value)));

/** The editable bank and bar draft for any song, not only the song on the desk. */
function editBankForSong(id) {
  const source = resolveTrack(id);
  return deskBank(source?.bank, mixFor(id));
}

function arrDraftForSong(id) {
  return draftOf(editBankForSong(id), arrFor(id));
}

/** Name a source lane without borrowing the destination song's labels or preset. */
function sourceLaneLabel(id, key, fallback) {
  const source = resolveTrack(id);
  const sourceMix = mixFor(id);
  const explicit = sourceMix.labels?.[key];
  if (typeof explicit === 'string' && explicit.trim()) return explicit.trim();
  const seam = seamFor(key);
  const params = seam && sourceMix.voiceParams?.[seam.voiceKey];
  const localId = params ? registerSongVoice(seam.voiceKey, id, params) : null;
  const chosen = localId || (seam && sourceMix.voice?.[seam.voiceKey]);
  const chosenPreset = chosen && VOICES[chosen]?.kind !== 'engine' ? VOICES[chosen] : null;
  const independent = (sourceMix.layers || []).some((layer) =>
    layer?.key === key && layer.independent);
  const preset = chosenPreset
    || (independent ? VOICES[defaultAddedVoice(key)] : null)
    || defaultVoiceOf(source?.bank, key);
  return preset?.label || fallback || cap(key);
}

/** Capture the same complete-track payload as Copy Track, from a chosen song. */
function trackClipForSong(sourceId, key, fallbackLabel) {
  const source = resolveTrack(sourceId);
  const sourceMix = mixFor(sourceId);
  const sourceDraft = arrDraftForSong(sourceId);
  const seam = seamFor(key);
  if (!source?.bank || !seam) return null;
  const sourceVoice = sourceMix.voice?.[seam.voiceKey];
  const sourceParams = sourceMix.voiceParams?.[seam.voiceKey];
  const voiceParams = sourceParams?.kind === 'engine' ? null : copyData(sourceParams);
  let voice = voiceParams ? null
    : sourceVoice && VOICES[sourceVoice]?.kind !== 'engine' && !VOICES[sourceVoice]?.songLocal
      ? sourceVoice : null;
  if (!voice && !voiceParams) {
    const authored = defaultVoiceOf(source.bank, key);
    if (authored?.id && authored.kind !== 'engine' && !authored.songLocal) voice = authored.id;
  }
  return {
    kind: 'track',
    label: sourceLaneLabel(sourceId, key, fallbackLabel),
    song: sourceId,
    songTitle: source.title || sourceId,
    sourceLane: key,
    bars: copyLaneTrack(editBankForSong(sourceId), sourceDraft, 0,
      Math.max(0, sourceDraft.plan.length - 1), key),
    track: {
      lane: copyData(sourceMix.lanes?.[key] || {}),
      label: typeof sourceMix.labels?.[key] === 'string' && sourceMix.labels[key].trim()
        ? sourceMix.labels[key].trim() : null,
      voice,
      voiceParams,
    },
  };
}

/** The visible, playable tracks in a source song, including its independent layers. */
function importableTracksForSong(id) {
  const bank = freezeViewBank(id);
  return engineDeskLanes(bank, 1)
    .filter((lane) => seamFor(lane.key))
    .map((lane) => ({
      ...lane,
      label: sourceLaneLabel(id, lane.key, lane.label),
    }));
}

/**
 * Copy the track as a new-track clip rather than as a note clip.
 *
 * The arrangement part is resolved now, while the source song is still on the desk.
 * A section index is only meaningful inside its own song; resolved notes, lengths and
 * lane-scoped bar decisions are what make this clipboard safe to paste elsewhere.
 */
function copyTrack(key) {
  const seam = seamFor(key);
  if (!seam) { toast(`${targetLabel(key)} cannot be copied as a track`); return; }
  const sourceMix = mixFor(trackId);
  const sourceDraft = arrDraftOf();
  const sourceVoice = sourceMix.voice?.[seam.voiceKey];
  const sourceParams = sourceMix.voiceParams?.[seam.voiceKey];
  // A song-local preset is carried by voiceParams, not by its source-scoped catalogue
  // id. Engine presets are bank-key bundles and cannot be attached to an independent
  // layer, so the new lane will ask for a playable layer preset in that one case.
  let voice = sourceParams ? null
    : sourceVoice && VOICES[sourceVoice]?.kind !== 'engine' && !VOICES[sourceVoice]?.songLocal
      ? sourceVoice : null;
  if (!voice && !sourceParams) {
    const authored = defaultVoiceOf(track?.bank, key);
    if (authored?.id && authored.kind !== 'engine' && !authored.songLocal) voice = authored.id;
  }
  const label = customTrackLabel(key) || presetHeadingFor(key).name;
  arrangementClipboard = {
    kind: 'track',
    ...clipOrigin(label),
    sourceLane: key,
    bars: copyLaneTrack(editBank(), sourceDraft, 0, Math.max(0, sourceDraft.plan.length - 1), key),
    track: {
      lane: copyData(sourceMix.lanes?.[key] || {}),
      label: customTrackLabel(key),
      voice,
      voiceParams: copyData(sourceParams),
    },
  };
  toast(`${label} copied — right-click a track in this song or another song to paste as a new track`);
}

/** The next independent key in the copied track's engine lane family. */
function nextPastedTrackKey(sourceLane, existingKeys = null) {
  const base = baseLane(sourceLane);
  const used = existingKeys || new Set(deskLanes(viewBank(), 1).map((lane) => lane.key));
  for (let n = 2; ; n++) {
    const key = `${base}${n}`;
    if (!used.has(key) && seamFor(key)) return key;
  }
}

/** Paste a complete track as a fresh independent lane in the current song. */
function pasteTrack() {
  const clip = arrangementClipboard;
  if (!clip || clip.kind !== 'track') return;
  const newKey = nextPastedTrackKey(clip.sourceLane);
  const newSeam = seamFor(newKey);
  if (!newSeam) { toast('That track cannot be added here'); return; }
  const destinationMix = mixFor(trackId);
  const destinationLayers = [...(destinationMix.layers || [])];
  const sourceFamily = baseLane(clip.sourceLane);
  const sourceAt = destinationLayers.findIndex((layer) => layer.key === clip.sourceLane);
  const familyAt = destinationLayers.reduce((last, layer, index) =>
    (baseLane(layer.key) === sourceFamily ? index : last), -1);
  const insertAt = sourceAt >= 0 ? sourceAt + 1 : familyAt >= 0 ? familyAt + 1 : destinationLayers.length;
  const copiedLane = copyData(clip.track?.lane || {});
  const copiedVoice = clip.track?.voice;
  const copiedParams = copyData(clip.track?.voiceParams);
  editMix((m) => {
    const layers = [...(m.layers || [])];
    layers.splice(insertAt, 0, { key: newKey, from: clip.sourceLane, independent: true });
    m.layers = layers;
    m.lanes = m.lanes || {};
    m.lanes[newKey] = copiedLane;
    if (clip.track?.label) m.labels = { ...(m.labels || {}), [newKey]: clip.track.label };
    if (copiedVoice) {
      m.voice = { ...(m.voice || {}), [newSeam.voiceKey]: copiedVoice };
    }
    if (copiedParams) {
      m.voiceParams = { ...(m.voiceParams || {}), [newSeam.voiceKey]: copiedParams };
    }
  });
  const destinationDraft = arrDraftOf();
  const pasted = pasteLaneTrack(editBank(), destinationDraft, 0, newKey, clip.bars);
  if (!applyArrangementEdit(pasted, null, { undo: false, render: false, rearmLoop: false })) return;
  rebuildForShape();
  selectLane(newKey);
  const sourceName = clipLabel(clip);
  const dropped = Math.max(0, clip.bars.bars.length - destinationDraft.plan.length);
  const noVoice = !copiedVoice && !copiedParams
    && !PERCUSSION_LANES.includes(baseLane(newKey));
  toast(`${targetLabel(newKey)} pasted as a new track from ${sourceName}`
    + (dropped ? ` — ${dropped} bar${dropped === 1 ? '' : 's'} past the end was not pasted` : '')
    + (noVoice ? ' — choose a preset for its sound' : ' — full notes, edits and channel settings copied'), 6000);
  if (noVoice) openVoicePickerFor(newKey);
}

/** Add several complete tracks from another song as one independent, undoable edit. */
function importTracksFromSong(sourceId, sourceKeys) {
  const clips = sourceKeys.map((key) => trackClipForSong(sourceId, key,
    importableTracksForSong(sourceId).find((lane) => lane.key === key)?.label))
    .filter(Boolean);
  if (!clips.length) {
    toast('No tracks selected');
    return;
  }

  const destinationMix = mixFor(trackId);
  const layers = [...(destinationMix.layers || [])];
  const used = new Set(engineDeskLanes(viewBank(), 1).map((lane) => lane.key));
  const imports = [];
  for (const clip of clips) {
    const newKey = nextPastedTrackKey(clip.sourceLane, used);
    const newSeam = seamFor(newKey);
    if (!newSeam) continue;
    const sourceFamily = baseLane(clip.sourceLane);
    const sourceAt = layers.findIndex((layer) => layer.key === clip.sourceLane);
    const familyAt = layers.reduce((last, layer, index) =>
      (baseLane(layer.key) === sourceFamily ? index : last), -1);
    const insertAt = sourceAt >= 0 ? sourceAt + 1 : familyAt >= 0 ? familyAt + 1 : layers.length;
    layers.splice(insertAt, 0, { key: newKey, from: clip.sourceLane, independent: true });
    used.add(newKey);
    imports.push({ clip, newKey, newSeam });
  }
  if (!imports.length) {
    toast('Those tracks cannot be added here');
    return;
  }

  editMix((m) => {
    m.layers = layers;
    m.lanes = m.lanes || {};
    for (const { clip, newKey, newSeam } of imports) {
      m.lanes[newKey] = copyData(clip.track?.lane || {});
      if (clip.track?.label) m.labels = { ...(m.labels || {}), [newKey]: clip.track.label };
      if (clip.track?.voice) {
        m.voice = { ...(m.voice || {}), [newSeam.voiceKey]: clip.track.voice };
      }
      if (clip.track?.voiceParams) {
        m.voiceParams = { ...(m.voiceParams || {}), [newSeam.voiceKey]: copyData(clip.track.voiceParams) };
      }
    }
  }, null);

  // Grow the destination first. The new bars are silent for every existing lane;
  // pasteLaneTrack then explicitly wakes each imported lane while preserving source
  // bar edits. This keeps an import from changing the ending of the rest of the song.
  let destinationDraft = arrDraftOf();
  const longest = Math.max(...imports.map(({ clip }) => clip.bars.bars.length));
  const extension = Math.max(0, longest - destinationDraft.plan.length);
  if (extension) {
    const allLanes = engineDeskLanes(viewBank(), 1).map((lane) => lane.key);
    destinationDraft = insertSilence(destinationDraft, destinationDraft.plan.length,
      extension, allLanes);
  }
  for (const { clip, newKey } of imports) {
    destinationDraft = pasteLaneTrack(editBank(), destinationDraft, 0, newKey, clip.bars);
  }
  if (!applyArrangementEdit(destinationDraft, null, { undo: false, render: false, rearmLoop: false })) return;
  rebuildForShape();
  selectLane(imports[0].newKey);

  const sourceName = resolveTrack(sourceId)?.title || sourceId;
  const missingVoiceImports = imports
    .filter(({ clip, newKey }) => !clip.track?.voice && !clip.track?.voiceParams
      && !PERCUSSION_LANES.includes(baseLane(newKey)));
  const missingVoices = missingVoiceImports.map(({ clip }) => clip.label);
  const importedNames = imports.map(({ clip }) => clip.label).join(', ');
  toast(`${imports.length} track${imports.length === 1 ? '' : 's'} imported from ${sourceName}: ${importedNames}`
    + (extension ? ` — extended this song by ${extension} bar${extension === 1 ? '' : 's'}` : '')
    + (missingVoices.length ? ` — choose presets for ${missingVoices.join(', ')}`
      : ' — notes, edits and channel settings copied'), 7000);
  if (missingVoiceImports.length) openVoicePickerFor(missingVoiceImports[0].newKey);
}

/** Hamburger -> Import Tracks -> Select Song -> Pick Tracks. */
async function importTracks() {
  closeMenu();
  const songs = listTracks().filter(visibleTrack)
    .filter((item) => resolveTrack(item.id)?.bank);
  if (!songs.length) {
    toast('No songs are available to import from');
    return;
  }
  const first = songs.find((item) => item.id !== trackId) || songs[0];
  const options = songs.map((item) => `<option value="${escapeHtml(item.id)}"`
    + `${item.id === first.id ? ' selected' : ''}>${escapeHtml(item.title || item.id)}`
    + `${item.id === trackId ? ' (current song)' : ''}</option>`).join('');
  const chosen = await ask('Import tracks',
    '<p>Choose the song whose complete tracks you want to add to this song.</p>'
    + `<label class="askfield">Source song<select id="importtracks-song">${options}</select></label>`,
    'Pick tracks');
  if (!chosen) return;
  const sourceId = $('importtracks-song')?.value;
  if (!sourceId) return;

  const lanes = importableTracksForSong(sourceId);
  if (!lanes.length) {
    toast('That song has no playable tracks to import');
    return;
  }
  const rows = lanes.map((lane) => `<label class="asktrack"><input type="checkbox"`
    + ` name="importtracks-lane" value="${escapeHtml(lane.key)}" checked>`
    + `<span>${escapeHtml(lane.label)}</span><code>${escapeHtml(lane.key)}</code></label>`).join('');
  const sourceTitle = resolveTrack(sourceId)?.title || sourceId;
  const picked = await ask(`Pick tracks from ${sourceTitle}`,
    `<p>Tick the complete tracks to add to <b>${escapeHtml(track.title || trackId)}</b>.</p>`
    + `<div class="asktracklist">${rows}</div>`, 'Import');
  if (!picked) return;
  const keys = [...document.querySelectorAll('input[name="importtracks-lane"]:checked')]
    .map((input) => input.value);
  if (!keys.length) {
    toast('No tracks selected');
    return;
  }
  importTracksFromSong(sourceId, keys);
}

const selFrom = () => (selectedBar ? Math.min(selectedBar.from, selectedBar.to) : 0);
const selTo = () => (selectedBar ? Math.max(selectedBar.from, selectedBar.to) : 0);
const selWidth = () => (selectedBar ? selTo() - selFrom() + 1 : 0);

let selectionEditorsDirty = false;
let selectionRefreshIdle = 0;
let selectionRefreshFrame = 0;
// Where the editors should be looking once they have been repainted. Held rather
// than acted on, because bringing a bar into view means scrolling rows that the
// pending repaint has not built yet — see `focusSelectionEditors`.
let selectionFocusPending = null;

function paintSelectionEditors() {
  selectionEditorsDirty = false;
  stepSeq.refresh();
  pianoRoll.refresh();
  kitRoll.refresh();
  const focus = selectionFocusPending;
  selectionFocusPending = null;
  if (focus) {
    pianoRoll.focusRange(focus.from, focus.to);
    kitRoll.focusRange(focus.from, focus.to);
  }
}

/**
 * Repaint the editors once, after the gesture that dirtied them has finished.
 *
 * Never synchronously, stopped or playing. One click on a bar dirties them twice —
 * `selectLane` for the channel and `markBar` for the range — and a double-click sends
 * that whole pass through three times, once per click event plus the dblclick. Painted
 * on the spot, that is five or six full rebuilds of a whole-song grid for one gesture:
 * measured at 250-330ms and ~75,000 elements on the 17-lane, 64-bar megamix, which is
 * exactly the "double-clicking a bar is slow to open the roll" report.
 *
 * Coalescing costs a frame and saves all but one of those rebuilds. Playing still waits
 * for idle instead — the roll is not what the ear is on, and a rebuild inside the audio
 * lookahead is a hole in the music (see heavy-ui.js).
 */
function scheduleSelectionEditors({ defer = false } = {}) {
  selectionEditorsDirty = true;
  // A range drag can cross dozens of bars in one gesture. The timeline band and the
  // arrangement highlight are cheap and stay live; rebuilding three whole-song note
  // grids is not. The gesture's pointerup calls us again without `defer`, once.
  if (defer) return;
  if (playing && typeof requestIdleCallback === 'function') {
    // A large piano roll or drum grid can take longer than the audio lookahead. Let
    // the browser paint it only when there is idle time; playback remains authoritative
    // and the timeline/loop overlay already show the new selection immediately.
    //
    // With a deadline, because a playing desk animates every frame and never LOOKS
    // idle to the browser: without one this callback simply never fired, and clicking
    // from track to track mid-song changed the roll's header but never its notes. The
    // paint itself is safe past the deadline — it runs through heavyUi, which queues
    // two seconds of audio ahead of the build.
    if (selectionRefreshIdle) return;
    selectionRefreshIdle = requestIdleCallback(() => {
      selectionRefreshIdle = 0;
      if (selectionEditorsDirty) paintSelectionEditors();
    }, { timeout: 300 });
    return;
  }
  // Without an idle callback to wait for, the next frame is the nearest thing. It used
  // to be "not at all", which left a playing desk showing the previous selection's
  // notes until the transport stopped — and now would strand the focus with them.
  if (selectionRefreshFrame) return;
  selectionRefreshFrame = requestAnimationFrame(() => {
    selectionRefreshFrame = 0;
    if (selectionEditorsDirty) paintSelectionEditors();
  });
}

/**
 * Bring the current selection into view in both editors.
 *
 * A repaint on its way owns the scroll: the rows it will build are not there yet, so
 * scrolling to them now lands on the old field and the new one arrives at the top of
 * the keyboard. Hand the focus to that repaint instead; with nothing pending — a
 * second click on a bar that is already selected — do it here and now.
 */
function focusSelectionEditors(from = selFrom(), to = selTo()) {
  if (selectionEditorsDirty) {
    selectionFocusPending = { from, to };
    return;
  }
  pianoRoll.focusRange(from, to);
  kitRoll.focusRange(from, to);
}

function flushSelectionEditors() {
  if (selectionRefreshIdle && typeof cancelIdleCallback === 'function') {
    cancelIdleCallback(selectionRefreshIdle);
  }
  selectionRefreshIdle = 0;
  if (selectionRefreshFrame) cancelAnimationFrame(selectionRefreshFrame);
  selectionRefreshFrame = 0;
  if (selectionEditorsDirty) paintSelectionEditors();
}

function markBar(key, from, to = from, { focus = true, deferEditors = false } = {}) {
  selectedBar = from != null ? { key: key ?? null, from, to: to ?? from } : null;
  // A visible arrangement selection is a new loop source; do not let a previously
  // armed beat range win invisibly after the user moves back to the desk timeline.
  pianoRollLoopRange = null;
  syncLoopButton();
  if (loopOn) {
    const bounds = currentLoopBounds();
    if (playing && bounds && Audio.loopStart != null && Audio.loopEnd != null) {
      // Keep the current bar intact. The audio engine swaps to the newest selection
      // at the next bar line, so selecting bars mid-playback never cuts a bar in half
      // or jumps into the middle of the newly selected range.
      pendingSeekStep = null;
      $('selregion').classList.remove('pending');
      Audio.setLoopAtBoundary(bounds.start, bounds.end);
      pendingLoopAnchor = { start: bounds.start, end: bounds.end };
      $('loopregion').classList.add('pending');
    } else {
      applyLoop();
    }
  }
  redrawSelection();
  // The grid shows the selection, so selecting bars IS how you choose what it shows —
  // one bar or eight, without a control of its own.
  scheduleSelectionEditors({ defer: deferEditors });
  // The piano roll is a whole-song view, so its last scroll position can be nowhere
  // near the bar just selected. Keep the selection visible on both axes; a large
  // range is centred by the roll rather than pretending the whole thing can fit.
  //
  // Unless the selection was made ON one of those rulers, where the bars are already in
  // front of you: centring on every move of that drag walks the field out from under the
  // pointer, so the bar you are dragging towards is never the one you reach.
  if (focus) focusSelectionEditors();
}

/**
 * Paint the current selection onto rows that have just been rebuilt.
 *
 * Separate from `markBar` because the two are different questions — "select this"
 * and "the DOM is new, put the selection back" — and folding them into one function
 * with defaulted arguments is how a rebuild silently collapsed a range to its first
 * bar every time the grid was redrawn.
 */
/**
 * The bars picked out, as the other half of the loop control.
 *
 * A selection is a MODE — it decides what a groove lands in, what a region edit acts on,
 * what the loop plays — and it was only ever drawn as a band on rulers you may not be
 * looking at. It belongs beside the loop switch because it IS what that switch loops
 * (see currentLoopBounds), and the two standing at opposite ends of the toolbar was the
 * only reason they did not look like one thing.
 */
function syncSelReadout() {
  const stat = $('selstat');
  if (!stat) return;
  stat.hidden = !selectedBar;
  if (!selectedBar) {
    if (loopOn && pianoRollLoopRange) {
      const beats = Math.max(1, Math.round((pianoRollLoopRange.end - pianoRollLoopRange.start) / 4));
      $('looptoggle').title = `Playing the piano-roll range — ${beats} beat${beats === 1 ? '' : 's'} round`;
    }
    return;
  }
  const from = selFrom();
  const to = selTo();
  $('selnow').textContent = from === to ? `${from + 1}` : `${from + 1}-${to + 1}`;
  stat.title = from === to ? `Bar ${from + 1} is picked out — ✕ to clear it`
    : `Bars ${from + 1}-${to + 1} are picked out — ✕ to clear them`;
  // The switch beside it names them too, so it says what it is about to loop rather than
  // how many bars that happens to be.
  $('looptoggle').title = loopOn
    ? `Playing bars ${from + 1}-${to + 1} round — click to play the whole song`
    : `Play bars ${from + 1}-${to + 1} round`;
}

function redrawSelection() {
  syncSelReadout();
  for (const el of document.querySelectorAll('.arrbar.sel')) el.classList.remove('sel');
  if (!selectedBar) { drawSelRegion(); return; }
  // The range is marked on the lane you dragged in, because that is the lane the
  // menu's per-lane items will act on. Everything else about the range — delete,
  // duplicate, silence — is the whole song, and the timeline band says so.
  const row = selectedBar.key == null ? null
    : document.querySelector(`.arrrow[data-lane="${CSS.escape(selectedBar.key)}"]`);
  const cells = row?.querySelectorAll('.arrbar');
  if (cells) for (let b = selFrom(); b <= selTo(); b++) cells[b]?.classList.add('sel');
  drawSelRegion();
}

/**
 * The selection as a band on the timeline, in the same percentages the loop region
 * uses. A range picked in the grid is a range of the SONG, so it belongs on the ruler
 * as well as in the rows — that is where you read bar numbers.
 */
function drawSelRegion() {
  const el = $('selregion');
  if (!el) return;
  const total = songShape().bars.length;
  if (!selectedBar || !total) { el.classList.remove('show'); return; }
  el.classList.add('show');
  el.style.left = `${(selFrom() / total) * 100}%`;
  el.style.width = `${(selWidth() / total) * 100}%`;
}

// ---- editing the arrangement -------------------------------------------------
//
// Every other edit on this desk is about BALANCE. These are about the song's SHAPE:
// which bars play, in what order, with what dropped out of them — the build-up and
// breakdown move that was hand-typed into `order` arrays until now.
//
// The editor works in bars (`tools/lib/arrangement-edit.js`), the file stores an
// order, and the conversion between them happens on the way in and out. Nothing here
// touches a composition file: an edit lands in `src/data/arrangements.js`, and
// deleting that entry puts the song back exactly as it was written.

/**
 * The song's OWN bank — layer lanes rewritten in, but the arrangement NOT applied.
 *
 * This is the bank the editing seam works against, and the distinction from
 * `viewBank()` is load-bearing. `applyArrangement` appends an entry's layer sections
 * onto `bank.sections`, and a draft built against that counts them twice: `sec` then
 * addresses a list one longer than the file will have, the saved order points one
 * past the end, and the bar falls back to the bare bank with the previous edit's
 * notes gone. Only the SECOND edit to a song shows it, so it stayed invisible for as
 * long as nothing wrote notes.
 *
 * `viewBank()` is still what everything that DRAWS the song wants — it is the song as
 * it now plays. This is the song as it is written, which is what an edit is relative to.
 */
const editBank = () => deskBank(track?.bank, mixFor(trackId));

/** This song as an editable bar list, built from whatever is in force for it. */
const arrDraftOf = () => draftOf(editBank(), arrFor(trackId));

/**
 * Take an edited bar list and make it true — in the draft, in the engine, and on
 * screen, in that order.
 *
 * The engine is handed the whole arrangement rather than a diff, and takes it
 * WITHOUT stopping: `setArrangement` swaps the order and drops the memoised plan,
 * leaving the transport where it is. You hear the change from the next bar, which is
 * the only way to judge a build-up — stopping the song to audition an edit to the
 * song is how you lose the thing you were listening for.
 *
 */
/** Which lanes this song has, as a comparable string. A SET — deliberately unordered. */
const laneSetSig = () => deskLanes(viewBank(), 1).map((l) => l.key).sort().join('\0');

function applyArrangementEdit(next, what, {
  undo: undoable = true, atStep = null, undoTag = null,
  render = true, persist = true, rearmLoop = true,
} = {}) {
  if (next?.refused) { toast(next.refused); return false; }
  // A painted note can introduce a drum lane the original song did not contain.
  // Remember the lane set so that edit gets a strip immediately, while ordinary
  // note moves avoid tearing down and rebuilding every control on the desk.
  // Sorted, because the question is which lanes exist and not what order they sit in.
  // Track order is a mix decision now, so an unsorted comparison would read a dragged
  // strip as a lane appearing and tear the whole desk down to rebuild the same rack.
  const lanesBefore = render ? laneSetSig() : null;
  // And the bar list as it stands, because the note editors are drawn from it. Repeating
  // bars, inserting silence or deleting them changes the SHAPE without changing the lane
  // set, and that used to repaint the arrangement alone: the grid above showed eight bars
  // where there had been four while the editor below it went on drawing four.
  const planBefore = render ? JSON.stringify(arrDraftOf()?.plan ?? null) : null;
  // And the grid the song is STORED on, for the same reason. Promoting a song onto 48 so
  // it can hold a triplet leaves the plan untouched, so the editors below were never told
  // — and both went on drawing sixteen columns a bar under a picker that said 1/16T,
  // which is a snap you cannot see, aim at or draw on until something else happens to
  // repaint them.
  const resolutionBefore = render ? (arrDraftOf()?.resolution ?? null) : null;
  // `null` never coalesces, which is right for a gesture that ends — a drawn note, a
  // pasted clip. A performance has no ending, so recording tags its writes and the run
  // of them collapses into the one snapshot `pushUndo` already knows how to make.
  if (undoable) pushUndo(undoTag);
  // The song's own bank, not the arranged one — see `editBank`. Compaction counts
  // `bank.sections` to number the layer, so handing it the arranged bank writes an
  // index past the end of the list the file will actually have.
  const entry = entryOf(editBank(), next);
  const issues = arrangementIssues(track.bank, entry, deskLanes(editBank(), 1).map((l) => l.key));
  if (issues.length) {
    // Refused rather than written: an unplayable arrangement is silence with a
    // playhead running through it, and the desk should say so while there is still
    // something to undo it from.
    toast(`That edit would not play — ${issues[0]}`, 6000);
    undo();
    return false;
  }
  arrDraft[trackId] = entry;
  reconcileFrozen();
  if (persist) localStorage.setItem(ARRANGE_KEY, JSON.stringify(arrDraft));
  bankCache.sig = null;                       // the song's shape changed under it
  Audio.setArrangement(entry);
  // When playback is stopped, Audio.setArrangement only stores the patch because
  // there is no live bank to swap. Keep the stopped desk's audition/keyboard bank in
  // step as well; otherwise a mute appears in the grid but the next note audition
  // still comes from the pre-edit arrangement. Playing uses the gap-free swap above.
  if (!playing) applyToEngine(mixFor(trackId));
  if (render) {
    const lanesAfter = laneSetSig();
    buildTimeline();
    if (lanesAfter !== lanesBefore) {
      rebuildForShape();                      // repaints the note editors on its way past
    } else {
      buildArrangement();
      // Only when the bars themselves moved. A note edit leaves the plan alone and the
      // panel that made it has already redrawn itself — repainting here as well would
      // rebuild a whole-song field twice for every step of a paint drag.
      if (JSON.stringify(next?.plan ?? null) !== planBefore
        || (entry?.resolution ?? null) !== resolutionBefore) {
        stepSeq.refresh();
        pianoRoll.refresh();
        kitRoll.refresh();
      }
    }
  }
  // `atStep` is which bar the loop should re-arm from, and it matters as soon as an
  // edit can land while the song is running. `applyLoop` snaps to the bar containing
  // the step it is given, so re-arming from `Audio.step` moves a multi-bar loop forward
  // whenever the scheduler happens to be past its first bar — a two-bar loop written
  // into during its second bar comes back as bars 2-3. A caller that knows the loop
  // did not move says so by passing `loopAnchor`.
  if (rearmLoop) applyLoop(atStep != null ? atStep : Audio.step);
  if (render) updateStatus();
  if (what) toast(`${what} — ⌘Z to undo`);
  return true;
}

/**
 * The step grid.
 *
 * It edits notes rather than shape, but it lands in the same place: a note edit is a
 * layer section on the arrangement, so it goes through `applyArrangementEdit` like a
 * build-up does and inherits undo, the A/B, Save and Revert without knowing they exist.
 *
 * The bars it shows are the SELECTION — the same rule `barMenu` follows, so "select
 * four bars, right-click, build up" and "select four bars and paint a fill" are the
 * same gesture with two endings. With nothing selected it shows the bar being played,
 * so opening it mid-loop lands you where you are listening.
 */
const stepSeq = createStepSeq({
  el: $('stepseq'),
  Audio,
  bank: () => viewBank(),
  editBank: () => editBank(),
  draft: () => arrDraftOf(),
  sel: () => {
    if (selectedBar) return { from: selFrom(), to: selTo() };
    const bars = songShape().bars.length;
    const b = bars ? Math.floor((Audio.step || 0) / 16) % bars : 0;
    return { from: b, to: b };
  },
  apply: (next, what) => applyArrangementEdit(next, what),
  laneColour,
  engineBank: () => engineBank(),
  toast,
  // The same row order and numbering the arrangement rows carry, so the two lists
  // read as one list rather than two opinions about the kit.
  kitLanes: () => deskLanes(viewBank(), 1).map((l) => l.key),
  laneNumber: (key) => laneNumbers.get(key),
  laneLabel: (key) => presetHeadingFor(key).name,
  addInstrument: (anchor) => addBlankTrack(anchor, { drumsOnly: true }),
  applyKit: (name, voices) => applyKit(name, voices),
  menu: (x, y, title, items) => { closeMenu(); openMenu(x, y, title, items); },
  // Closed from its own × as well as from the button, so the button is told rather
  // than assumed — the same reason `showOsk` sets the class instead of toggling it.
  onClose: () => { $('seqbtn').classList.remove('on'); rememberSongLayout(); },
});

// The roll follows the SELECTED CHANNEL. It had its own `rollLane` while it was a window
// of its own — a strip click yanking a floating panel would have been two things fighting
// — but it lives in that channel's panel now, under a header naming the channel, and
// directly above the rack whose selected strip is doing the choosing. Not following
// would be the odd behaviour.
//
// The panel sits between the arrangement and the mixer because it is driven from both:
// openNoteEditor() enters it by double-clicking an arrangement cell, and the strip
// selection below scopes it. It used to sit under the rack, next to that channel's
// effects, which grouped it with a panel that does not drive it and put the whole rack
// between the roll and the double-click that opens it.
const rollLanes = () => deskLanes(viewBank(), 1).map((l) => l.key).filter(rollEditable);

// Which part the roll is actually showing. A drum channel has no roll, so the selection
// falls through to the first melodic lane — and the region's caption has to name what is
// on screen rather than what is selected, so both read this one function.
function rollShownLane() {
  const sel = selectedLane && !selectedLane.startsWith('__') && rollEditable(selectedLane)
    ? selectedLane : null;
  return sel || rollLanes()[0] || 'lead';
}

function normalizedRearrangeFavourite(range) {
  const total = songShape().totalSteps;
  const start = clamp(Math.round(Number(range?.start) || 0), 0, total);
  const end = clamp(Math.round(Number(range?.end) || 0), start, total);
  if (end <= start) return null;
  // Form sections are four bars, so a favourite remains one self-contained phrase and
  // can be inserted without splitting it across the generated roadmap.
  if (end - start > 64) return null;
  return { from: start, length: end - start };
}

function isRearrangeFavourite(range) {
  const favourite = normalizedRearrangeFavourite(range);
  return !!favourite && rearrangeFavourites.some((item) =>
    item.from === favourite.from && item.length === favourite.length);
}

function toggleRearrangeFavourite(range, lane = rollShownLane()) {
  const favourite = normalizedRearrangeFavourite(range);
  if (!favourite) {
    toast('Choose a positive piano-roll range up to four bars for a favourite');
    return;
  }
  const index = rearrangeFavourites.findIndex((item) =>
    item.from === favourite.from && item.length === favourite.length);
  if (index >= 0) {
    rearrangeFavourites.splice(index, 1);
    toast(`Removed Rearrange favourite · ${rearrangeStepLabel(favourite.from)}`);
  } else {
    const used = rearrangeFavourites.reduce((sum, item) => sum + item.length, 0);
    if (used + favourite.length > songShape().totalSteps) {
      toast('Those favourites are longer than one song — remove one before adding this');
      return;
    }
    rearrangeFavourites.push({ ...favourite, lane: String(lane || rollShownLane()) });
    rearrangeFavourites.sort((a, b) => a.from - b.from || a.length - b.length);
    toast(`Added Rearrange favourite · ${rearrangeStepLabel(favourite.from)} for ${rearrangeStepLabel(favourite.from + favourite.length - 1)}`);
  }
  pianoRoll?.syncActions?.();
  renderRearrangeList();
}

const pianoRoll = createPianoRoll({
  el: $('pianoroll'),
  Audio,
  bank: () => viewBank(),
  editBank: () => editBank(),
  draft: () => arrDraftOf(),
  sel: () => {
    if (selectedBar) return { from: selFrom(), to: selTo() };
    const bars = songShape().bars.length;
    const b = bars ? Math.floor((Audio.step || 0) / 16) % bars : 0;
    return { from: b, to: b };
  },
  apply: (next, what) => applyArrangementEdit(next, what),
  laneColour,
  engineBank: () => engineBank(),
  // The channel is chosen on the desk. The roll shows whichever one is selected and no
  // longer offers a picker of its own, so there is nothing to tell the desk back.
  lane: rollShownLane,
  // Time, though, it can tell the desk: its ruler is the song's, so a drag across it
  // picks bars out exactly as the timeline's does. Both note editors do this, and both
  // draw the result on their own numbers.
  selectedBars: () => (selectedBar ? { from: selFrom(), to: selTo() } : null),
  onSelectBars: (from, to) => markBar(selectedBar?.key ?? null, from, to, { focus: false }),
  selectedTime: () => pianoRollTimeSelection,
  onAddRearrangeFavourite: (range) => toggleRearrangeFavourite(range, rollShownLane()),
  rearrangeFavouriteState: (range) => isRearrangeFavourite(range),
  onSelectTime: (range) => {
    pianoRollTimeSelection = range && {
      start: Math.max(0, Math.round(Number(range.start) || 0)),
      end: Math.max(0, Math.round(Number(range.end) || 0)),
    };
    // With no loop armed this is only an editing range. If a loop IS armed, keep the
    // previous transport range until the drag finishes, then hand the completed range
    // to the boundary-safe loop path below.
    if (!loopOn) pianoRollLoopRange = null;
  },
  onSelectTimeEnd: (range) => {
    if (!loopOn || !range || range.end <= range.start) return;
    armPianoRollLoop(range, { announce: false });
    toast('Loop range updated from the piano roll');
  },
  locators: () => (locA != null && locB != null
    ? { start: Math.min(locA, locB), end: Math.max(locA, locB) } : null),
  locatorPositions: () => ({ A: locA, B: locB }),
  onLocatorMove: (which, value) => {
    if (which === 'A') locA = value;
    if (which === 'B') locB = value;
  },
  onLocatorMoveEnd: (which, value) => {
    if (which === 'A') locA = value;
    if (which === 'B') locB = value;
    const pair = locA != null && locB != null
      ? { start: Math.min(locA, locB), end: Math.max(locA, locB) } : null;
    if (loopOn && pair && pair.end > pair.start) armPianoRollLoop(pair);
    else {
      pianoRollLoopRange = null;
      applyLoop();
    }
    pianoRoll.redraw();
    toast(`Locator ${which} moved`);
  },
  onDoubleClickStep: (step) => {
    jumpTo(step, { start: true });
    toast(`Playing from bar ${barOf(step)}, beat ${(Math.floor(step % 16 / 4) + 1)}`);
  },
  onLoopTime: (range) => armPianoRollLoop(range),
  menu: (x, y, title, items) => { closeMenu(); openMenu(x, y, title, items); },
  onClearLocator: (which) => {
    if (which === 'A') locA = null;
    if (which === 'B') locB = null;
    applyLoop();
    pianoRoll.redraw();
    toast(`Locator ${which} cleared`);
  },
  onClearLocators: () => {
    locA = null;
    locB = null;
    applyLoop();
    pianoRoll.redraw();
    toast('Both locators cleared');
  },
  onEraseTime: async (range) => {
    const count = pianoRoll.countTimeRange(range.start, range.end);
    if (!count) { toast('No notes between the locators'); return; }
    const ok = await ask(`Erase ${count} note${count === 1 ? '' : 's'}?`,
      '<p>This removes the notes between the piano-roll locators from the selected instrument.</p>',
      'Erase notes');
    if (!ok) return;
    const erased = pianoRoll.eraseTimeRange(range.start, range.end);
    toast(`${erased} note${erased === 1 ? '' : 's'} erased between locators`);
  },
  eraseSelectedBars: ({ from, to }) => {
    const laneKey = rollShownLane();
    const span = from === to ? `bar ${from + 1}` : `bars ${from + 1}–${to + 1}`;
    clearLaneBars(laneKey, from, to, `${presetHeadingFor(laneKey).name} erased in ${span}`);
  },
  laneLabel: (key) => presetHeadingFor(key).name,
  // The key, shared with the on-screen keyboard rather than copied: see the note on
  // `scale` in mixer-piano-roll.js. Read-only — the keyboard is where it is chosen.
  scale: () => ({ root: oskScaleRoot, id: oskScaleId }),
  // The desk's own toast, so choosing a mouse mode says what that mode now does.
  toast: (msg) => toast(msg),
  // No button of its own to un-light: the notes panel's fold button is what says
  // whether the roll is up.
  onClose: () => rememberSongLayout(),
});

const rollFollowButton = $('rollfollowbtn');
const syncRollFollowButton = () => {
  const frozen = !pianoRoll.followEnabled();
  rollFollowButton.classList.toggle('on', frozen);
  rollFollowButton.setAttribute('aria-pressed', frozen ? 'true' : 'false');
  rollFollowButton.title = frozen
    ? 'Resume the piano roll following playback'
    : 'Freeze the piano roll view';
  rollFollowButton.setAttribute('aria-label', rollFollowButton.title);
};
rollFollowButton.onclick = () => {
  pianoRoll.setFollow(!pianoRoll.followEnabled());
  syncRollFollowButton();
};
syncRollFollowButton();

/**
 * And the same kit, docked — the Notes panel's other editor.
 *
 * A percussion channel has no pitch axis, so the roll had nothing to offer it and the
 * panel simply emptied, holding its room for a field it could not fill. This is what
 * goes in it: one row per drum the song has, across the whole song, with the track names
 * in the column the keyboard has on a pitched channel.
 *
 * A second INSTANCE of the pattern editor and not a second pattern editor. The house
 * figures, the kits, the row order and the write path are THE KIT and there has to be
 * one of each; what differs is the four flags below. The floating window stays exactly
 * as it was — bar-scoped, with its shared-editing switch, on `g` and the grid button —
 * because "move the snare while I am looking at the bassline" is still a job.
 */
const kitRoll = createStepSeq({
  el: $('kitroll'),
  Audio,
  bank: () => viewBank(),
  editBank: () => editBank(),
  draft: () => arrDraftOf(),
  // The field shows the whole song, so `sel` no longer decides what is on screen — the
  // bar being played is only where the view opens.
  sel: () => {
    if (selectedBar) return { from: selFrom(), to: selTo() };
    const bars = songShape().bars.length;
    const b = bars ? Math.floor((Audio.step || 0) / 16) % bars : 0;
    return { from: b, to: b };
  },
  // What a figure, a groove or a mute lands in. The panel holds the CHOICE — it is made
  // in the menu that is about to act — and this turns it into bars, because only the desk
  // knows where the transport is and what is selected. `null` is the grid's word for the
  // whole of what is shown, which for the docked kit is the song.
  // The bars picked out, and picking them: the ruler is a control here as it is on the
  // timeline, and it is the same selection — one drag, wherever you happen to be looking.
  selectedBars: () => (selectedBar ? { from: selFrom(), to: selTo() } : null),
  onSelectBars: (from, to) => markBar(selectedBar?.key ?? null, from, to, { focus: false }),
  applyBars: (kind) => {
    if (kind === 'song') return null;
    if (kind === 'selection' && selectedBar) return { from: selFrom(), to: selTo() };
    // The bar being played — and the fallback for "the bars I select" with none selected,
    // because acting on the whole song there would be the one answer nobody asked for.
    const bars = songShape().bars.length;
    const b = bars ? Math.floor((Audio.step || 0) / 16) % bars : 0;
    return { from: b, to: b };
  },
  apply: (next, what) => applyArrangementEdit(next, what),
  laneColour,
  engineBank: () => engineBank(),
  toast,
  kitLanes: () => deskLanes(viewBank(), 1).map((l) => l.key),
  laneNumber: (key) => laneNumbers.get(key),
  laneLabel: (key) => presetHeadingFor(key).name,
  addInstrument: (anchor) => addBlankTrack(anchor, { drumsOnly: true }),
  applyKit: (name, voices) => applyKit(name, voices),
  menu: (x, y, title, items) => { closeMenu(); openMenu(x, y, title, items); },
  ns: 'kit',
  docked: true,
  wholeSong: true,
  scopeToggle: false,
  rulerLabel: 'Bar',
  // Its controls go in the panel's own header, beside its name — the row the region
  // already has, rather than a second row of chrome under it. They fold away with the
  // panel, and the roll contributes none, so it gets no bar at all.
  headerHost: () => $('notehead'),
  // A name in this column is the CHANNEL and its SOUND, not the arrangement mute it is
  // in the window: the bars on screen are the whole song, so "silence it in these bars"
  // has no meaning here — that moved into the row's own menu, where it can name its bars.
  // Clicking puts the desk on that drum and opens the library at it, which is what
  // clicking a preset does everywhere else on this desk. Percussion, so the library
  // offers the kit and nothing but — see openVoicePicker.
  onPickLane: (lane, el) => {
    selectLane(lane);
    const r = el?.getBoundingClientRect?.();
    openVoicePicker(r ? r.left : innerWidth / 2, r ? r.bottom + 6 : 120, lane);
  },
  currentLane: () => selectedLane,
  onClose: () => rememberSongLayout(),
});

const noteLengthMenuButton = $('notelenbtn');
const syncNoteLengthButton = () => {
  const show = editorFor(selectedLane) === 'roll' && pianoRoll.supportsLengths();
  noteLengthMenuButton.hidden = !show;
};
const openNoteLengthAdjust = (scopeKind, x, y) => {
  if (scopeKind === 'selection' && !pianoRoll.selectedLengthCount()) {
    toast('Select one or more notes first');
    return;
  }
  if (regionPanelBusy()) return;
  closeMenu();
  restorablePopup = { kind: 'noteLength', scopeKind };
  const el = $('regionedit');
  el.textContent = '';

  const head = document.createElement('div'); head.className = 'reghead';
  const heading = document.createElement('div'); heading.className = 'regtitle';
  heading.textContent = 'Adjust note lengths';
  const target = document.createElement('div'); target.className = 'regtarget';
  target.textContent = scopeKind === 'all' ? 'All notes in this track' : 'Selected notes';
  heading.append(target);
  const close = document.createElement('button'); close.className = 'regclose';
  close.textContent = '×'; close.title = 'Close'; close.onclick = closeMenu;
  head.append(heading, close); el.append(head);

  const section = document.createElement('div'); section.className = 'regsection';
  const caption = document.createElement('div'); caption.className = 'regcap';
  caption.textContent = 'Scale current lengths';
  const row = document.createElement('div'); row.className = 'regcontrol';
  const label = document.createElement('span'); label.textContent = 'Percentage';
  const range = document.createElement('input'); range.type = 'range';
  range.min = '1'; range.max = '400'; range.step = '1';
  range.setAttribute('aria-label', 'Note length percentage');
  const number = document.createElement('input'); number.type = 'number';
  number.min = '1'; number.step = '1'; number.inputMode = 'numeric';
  number.setAttribute('aria-label', 'Note length percentage');
  const reset = document.createElement('button'); reset.textContent = '100%';
  reset.title = 'Return to the original note lengths';
  const readout = document.createElement('div'); readout.className = 'regread';
  const formatPercent = (value) => `${Number.isInteger(value) ? value : Number(value.toFixed(2))}%`;
  let current = 100;
  const setPercent = (raw) => {
    if (!Number.isFinite(raw)) return;
    current = Math.max(1, Math.round(raw));
    range.value = Math.min(400, Math.max(1, current));
    number.value = formatPercent(current).slice(0, -1);
    readout.textContent = `${formatPercent(current)} of each note's current length`;
    row.classList.add('changed');
  };
  setPercent(current);
  range.oninput = () => setPercent(+range.value);
  number.oninput = () => {
    if (number.value !== '') setPercent(+number.value);
  };
  reset.onclick = () => setPercent(100);
  row.append(label, range, number, reset, readout);
  section.append(caption, row); el.append(section);

  const foot = document.createElement('div'); foot.className = 'regfoot';
  const cancel = document.createElement('button'); cancel.textContent = 'Cancel'; cancel.onclick = closeMenu;
  const apply = document.createElement('button'); apply.className = 'regapply';
  apply.textContent = 'Apply length';
  apply.onclick = () => {
    const percent = Number(number.value);
    if (!(percent > 0)) {
      toast('Enter a percentage above 0');
      number.focus();
      return;
    }
    const result = pianoRoll.adjustLengths({ scope: scopeKind, percent });
    if (!result.count) {
      closeMenu();
      toast(scopeKind === 'all' ? 'There are no notes in this track' : 'Select one or more notes first');
      return;
    }
    closeMenu();
    if (!result.changed) {
      toast('No note lengths changed');
      return;
    }
    toast(scopeKind === 'all'
      ? `Adjusted ${result.changed} note lengths in the track`
      : `Adjusted ${result.changed} selected note lengths`);
  };
  foot.append(cancel, apply); el.append(foot);
  el.onkeydown = (event) => {
    if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); closeMenu(); }
    if (event.key === 'Enter' && event.target === number) { event.preventDefault(); apply.click(); }
  };

  el.style.left = `${x}px`; el.style.top = `${y}px`; el.classList.add('show');
  const rect = el.getBoundingClientRect();
  el.style.left = `${Math.max(6, Math.min(x, innerWidth - rect.width - 6))}px`;
  el.style.top = `${Math.max(6, Math.min(y, innerHeight - rect.height - 6))}px`;
  requestAnimationFrame(() => number.focus({ preventScroll: true }));
};
const runNoteLengthQuantise = (scopeKind) => {
  if (scopeKind === 'selection' && !pianoRoll.selectedLengthCount()) {
    toast('Select one or more notes first');
    return;
  }
  const result = pianoRoll.quantiseLengths({ scope: scopeKind, grid: 1 });
  if (!result.count) {
    toast(scopeKind === 'all' ? 'There are no notes in this track' : 'Select one or more notes first');
    return;
  }
  toast(result.changed
    ? `Quantised ${result.changed} note lengths to 16ths`
    : 'All note lengths are already on 16ths');
};
noteLengthMenuButton.onclick = (ev) => {
  if (noteLengthMenuButton.hidden) return;
  const r = noteLengthMenuButton.getBoundingClientRect();
  // Every item here acts on the SELECTION unless it passes 'all', which is the whole
  // track across the whole song — `allNotes` in the grid, and the roll spans every bar.
  const run = (kind, value, label, scopeKind = 'selection') => {
    const result = pianoRoll.transformNotes({ scope: scopeKind, kind, value });
    if (!result.count) {
      toast(scopeKind === 'all' ? 'There are no notes in this track' : 'Select one or more notes first');
      return;
    }
    toast(result.changed ? `${label} — ${result.changed} note${result.changed === 1 ? '' : 's'}`
      : `${label} made no change`);
  };
  openMenu(r.left, r.bottom + 4, 'Transform selected notes', [
    { label: 'Legato to next event', run: () => run('legato', null, 'Legato') },
    { label: 'Staccato (50% gate)', run: () => run('staccato', null, 'Staccato') },
    { label: 'Fixed gate · 1/32', run: () => run('fixed', 0.5, 'Fixed 1/32 gate') },
    { label: 'Fixed gate · 1/16', run: () => run('fixed', 1, 'Fixed 1/16 gate') },
    { label: 'Fixed gate · 1/8', run: () => run('fixed', 2, 'Fixed 1/8 gate') },
    { label: 'Fixed gate · 1/4', run: () => run('fixed', 4, 'Fixed 1/4 gate') },
    { label: 'Fixed gate · 1/2', run: () => run('fixed', 8, 'Fixed 1/2 gate') },
    { label: 'Fixed gate · whole', run: () => run('fixed', 16, 'Fixed whole-note gate') },
    { label: 'Scale length · 1/2', run: () => run('scale', 50, 'Half length') },
    { label: 'Scale length · 3/4', run: () => run('scale', 75, 'Three-quarter length') },
    { label: 'Scale length · 1.25×', run: () => run('scale', 125, '1.25× length') },
    { label: 'Scale length · 1.5×', run: () => run('scale', 150, '1.5× length') },
    { label: 'Scale length · 2×', run: () => run('scale', 200, 'Double length') },
    { label: 'Scale length · 3×', run: () => run('scale', 300, 'Triple length') },
    { label: 'Scale length · 4×', run: () => run('scale', 400, 'Quadruple length') },
    { label: 'Custom length percentage…', run: () => openNoteLengthAdjust('selection', r.left, r.bottom + 4) },
    { label: 'Chop into 2', run: () => run('chop', 2, 'Chopped into 2') },
    { label: 'Repeat into 4', run: () => run('chop', 4, 'Repeated into 4') },
    { label: 'Invert chords / mirror melody', run: () => run('invert', null, 'Inverted') },
    { label: 'Reverse note order', run: () => run('reverse', null, 'Reversed') },
    // Starts, then lengths. Two different edits and both are wanted: a note can begin
    // off the grid and be exactly a sixteenth long, or begin on it and be a ragged
    // length. This one follows the QUANTISE picker, so it snaps to triplets when that is
    // what the roll is set to; the one below it is always sixteenths.
    { label: `Quantise starts to ${pianoRoll.quantiseLabel()}`, run: () => run('quantise', null, `Quantised to ${pianoRoll.quantiseLabel()}`) },
    // The same edit with the track as its scope, because selecting first is the step that
    // gets skipped: a part imported off the grid needs every note moved, not the handful
    // under the last marquee, and doing it lane by lane with ⌘A in between is where a
    // quantise silently does not happen. Follows the QUANTISE picker like the item above,
    // and the picker is the only thing deciding what survives: at 1/16 a note sitting on
    // a triplet position is FLATTENED onto the nearest sixteenth, which is the point of
    // the item — an imported performance is meant to come out straight. Pick a triplet
    // division instead and the triplets are what lands on the grid.
    { label: `Quantise all starts to ${pianoRoll.quantiseLabel()}`,
      run: () => run('quantise', null, `Quantised the track to ${pianoRoll.quantiseLabel()}`, 'all') },
    { label: 'Quantise lengths to 16ths', run: () => runNoteLengthQuantise('selection') },
    { label: 'Custom transform all notes…', run: () => openNoteLengthAdjust('all', r.left, r.bottom + 4) },
  ]);
};

// ---- the bottom row's two panels ------------------------------------------------
//
// Effects and Notes are now independent, side-by-side panels. Each folds on its
// own, and either panel's border lets you give more room to the panel you are working
// on. The kit's step grid remains a floating window — it belongs to the song, not to a
// channel.

/**
 * Put the roll away, or bring it back, for the channel that is now selected.
 *
 * Two things move together: the roll itself, and the preset named in the header. They
 * are one function because they answer the same question — what part is on screen —
 * and a header naming a preset with no roll under it is the bug this replaced.
 *
 * Nothing about the LAYOUT moves. Neither the fold nor the panel's height is touched:
 * the panel is the same box either way, empty while the selection has no part for it,
 * and the desk around it does not shift when you click from a drum strip to a melodic
 * one. Both of those are also why this can run on every selection change.
 */
function syncNotesPanel() {
  const workspaceView = $('desk').dataset.lowerView;
  const kind = workspaceView === 'pattern' ? 'kit'
    : workspaceView === 'roll' ? 'roll' : editorFor(selectedLane);
  const rollChanged = $('notes').classList.contains('rollless') !== (kind !== 'roll');
  const kitChanged = $('notes').classList.contains('kitless') !== (kind !== 'kit');
  $('notes').classList.toggle('rollless', kind !== 'roll');
  $('notes').classList.toggle('kitless', kind !== 'kit');
  // The panel is named for what is IN it. The roll is one channel's part, so it is Notes
  // and the preset playing them — what is ON SCREEN, not what is selected, since with the
  // master selected the roll still shows a lane. The kit is not one channel's anything:
  // every drum in the song is on it at once and the selected strip changes only which row
  // is marked, so naming one of them there would be a caption that means nothing.
  $('notelabel').textContent = kind === 'kit' ? 'Pattern' : 'Piano Roll';
  $('notepreset').textContent = kind === 'roll' ? presetHeadingFor(rollShownLane()).name : '';
  syncNoteLengthButton();
  if (kitChanged && kind === 'kit') {
    // The kit has no window into an instrument to lose — its scroll is time only, and
    // `build` puts that back itself — but it may never have been built at all, or was
    // left unbuilt while the panel was showing the roll. Same idle-time build.
    scheduleKitOpen();
  }
  if (!rollChanged || kind !== 'roll') return;
  // Coming back. The roll's window has to be re-fitted to the part whatever lane this
  // is: hiding the panel took its scroll position with it, so an unfitted roll opens
  // at the top of the keyboard — C8, with the part four octaves below the field. The
  // fit is keyed on the lane CHANGING, and coming back to the lane you left is not a
  // change, which is exactly the trip that was landing on C8. See forgetFit.
  pianoRoll.forgetFit();
  // And the roll may never have been built at all, or was left unbuilt while the panel
  // had nothing to show. Same idle-time build the fold uses.
  schedulePianoRollOpen();
}

/** Fold or unfold the notes panel — whichever of the two editors is in it. */
function setNotesFolded(on, refit = true) {
  if ($('lowerwork')) {
    $('notes').classList.remove('collapsed');
    return;
  }
  const hasRoll = !laneHidesRoll(selectedLane);
  const needsBuild = !on && !pianoRoll.isOpen() && hasRoll;
  const needsKit = !on && !kitRoll.isOpen() && editorFor(selectedLane) === 'kit';
  // Unfolding a roll that is already built. The fold hides it with `display: none`,
  // which takes the scroll position with it, and the lane has not changed, so nothing
  // would fit the window again — it came back at the top of the keyboard. Same trip
  // and same fix as the rollless one in syncNotesPanel. Only on a real fold change:
  // the border drag calls this on every pointermove, and a refresh per move would be
  // a rebuild of the whole roll per frame.
  const reopening = !on && !needsBuild && hasRoll && pianoRoll.isOpen()
    && $('notes').classList.contains('collapsed');
  $('notes').classList.toggle('collapsed', on);
  $('notefold').classList.toggle('folded', on);
  $('notefold').title = on ? 'Show the notes panel' : 'Collapse the notes panel';
  $('rollbtn').classList.toggle('on', !on);
  syncPanelResizeEdges();
  if (refit) {
    scheduleDeskFit(true);
  }
  if (needsBuild) {
    // A song can restore with Notes folded, in which case loadTrack deliberately did
    // not build the roll. Do that work after the fold/layout task, not inside the click
    // handler that is competing with the audio scheduler.
    schedulePianoRollOpen();
  } else if (reopening) {
    pianoRoll.forgetFit();
    pianoRoll.refresh();
  }
  // The kit gets the build but not the refit: unfolding cannot leave it looking at the
  // wrong part of an instrument, because a kit has no pitch axis to be lost in.
  if (needsKit) scheduleKitOpen();
}

let pianoRollOpenPending = 0;
let pianoRollFocusPending = null;
function spendPianoRollFocus() {
  if (!pianoRollFocusPending || !pianoRoll.isOpen()) return;
  const focus = pianoRollFocusPending;
  pianoRollFocusPending = null;
  // `open()` has just built the field and entered it into layout. Its own opening fit
  // is queued for this frame too; queue this afterwards so the bar explicitly opened
  // by the double-click has the last word on both the time and pitch axes.
  requestAnimationFrame(() => pianoRoll.focusRange(focus.from, focus.to));
}
function schedulePianoRollOpen() {
  if (pianoRollOpenPending) return;
  const run = () => {
    pianoRollOpenPending = 0;
    // Nothing to build for a channel that has no roll — and building one would paint
    // some other lane's part into a hidden panel, ready to flash up on the next fold.
    if (!notesRollUp() || pianoRoll.isOpen()) return;
    pianoRoll.open(true);
    spendPianoRollFocus();
  };
  if (typeof requestIdleCallback === 'function') {
    pianoRollOpenPending = requestIdleCallback(run, { timeout: 250 });
  } else {
    pianoRollOpenPending = setTimeout(run, 0);
  }
}

let kitOpenPending = 0;
function scheduleKitOpen() {
  if (kitOpenPending) return;
  const run = () => {
    kitOpenPending = 0;
    if (!notesKitUp() || kitRoll.isOpen()) return;
    kitRoll.open(true);
  };
  if (typeof requestIdleCallback === 'function') {
    kitOpenPending = requestIdleCallback(run, { timeout: 250 });
  } else {
    kitOpenPending = setTimeout(run, 0);
  }
}

$('notefold').onclick = () => {
  setNotesFolded(!$('notes').classList.contains('collapsed'));
  // Notes is the one fold that belongs to the song rather than to the desk — the roll
  // you were editing is context for that melody. pagehide records it eventually; do it
  // on the click so a crash or a hard reload does not lose the fold.
  rememberSongLayout();
};

function showStepSeq(on) {
  setLowerView(on ? 'pattern' : 'mixer');
}

let stepSeqWanted = false;
let stepSeqOpenPending = 0;
function scheduleStepSeqOpen() {
  if (stepSeqOpenPending) return;
  const run = () => {
    stepSeqOpenPending = 0;
    if (!stepSeqWanted || stepSeq.isOpen()) return;
    stepSeq.open(true);
    rememberSongLayout();
  };
  if (typeof requestIdleCallback === 'function') {
    stepSeqOpenPending = requestIdleCallback(run, { timeout: 250 });
  } else {
    stepSeqOpenPending = setTimeout(run, 0);
  }
}

function showPianoRoll(on) {
  setLowerView(on ? 'roll' : 'mixer');
  // Unfolding a panel with nothing to put in it would be a button doing nothing. The
  // fold still happens — it is remembered for the next channel that has an editor — but
  // say why nothing arrived. Only a gesture lane: a drum channel gets the kit now.
  if (on && !editorFor(selectedLane)) {
    toast(`${presetHeadingFor(selectedLane).name} builds its own timing inside the gesture`
      + ' — there is no grid for it');
  }
  rememberSongLayout();
}

// The lower half is one workspace, not three panels. Mixer is the stable home view;
// the two editors keep their own DOM and scroll state while hidden, so switching is a
// display operation rather than a rebuild or a song edit.
const LOWER_VIEW_KEY = 'mash-mixer-lower-view';
const LOWER_VIEWS = new Set(['mixer', 'roll', 'pattern']);
let lowerView = LOWER_VIEWS.has(localStorage.getItem(LOWER_VIEW_KEY))
  ? localStorage.getItem(LOWER_VIEW_KEY) : 'mixer';

/**
 * The real channel a note-editor workspace should own.
 *
 * Master and aux buses deliberately fall through to a melodic lane elsewhere so the
 * piano roll is never blank, but that is not enough for a workspace switch: the desk's
 * selection and the arrangement highlight must name the track actually being edited.
 * Pattern makes the same promise in the other direction by choosing a percussion lane.
 */
function laneForLowerView(view) {
  if (!track || (view !== 'roll' && view !== 'pattern')) return null;
  const wanted = view === 'pattern' ? 'kit' : 'roll';
  const lanes = deskLanes(viewBank(), 1);
  const current = lanes.find((lane) => lane.key === selectedLane
    && editorFor(lane.key) === wanted);
  return current?.key || lanes.find((lane) => editorFor(lane.key) === wanted)?.key || null;
}

function setLowerView(next, { remember = true } = {}) {
  const view = LOWER_VIEWS.has(next) ? next : 'mixer';
  arrangementKeyboardActive = false;
  const viewLane = laneForLowerView(view);
  lowerView = view;
  $('desk').dataset.lowerView = view;
  $('mixviewbtn').classList.toggle('on', view === 'mixer');
  $('rollbtn').classList.toggle('on', view === 'roll');
  $('seqbtn').classList.toggle('on', view === 'pattern');
  for (const [id, on] of [['mixviewbtn', view === 'mixer'], ['rollbtn', view === 'roll'], ['seqbtn', view === 'pattern']]) {
    $(id).setAttribute('aria-pressed', on ? 'true' : 'false');
  }

  // Old saved folds cannot make a selected view empty. The fold functions remain as
  // compatibility helpers while the old layout code is retired, but no visible
  // control can put these panels back into that state.
  $('notes').classList.remove('collapsed');
  $('rackwrap').classList.remove('collapsed');
  $('mixhead').classList.remove('folded');

  // This runs once while the shell is being wired, before the async song load below
  // has assigned `track`. At that point the structural view state is all we can set:
  // resolving the remembered lane would ask viewBank/deskLanes for a bank that does
  // not exist yet. loadTrack calls syncNotesPanel after the bank, rack and arrangement
  // have all been installed, so defer every song-dependent part until that boundary.
  if (track) {
    // Select after installing the view state. selectLane then refreshes the editor that
    // is coming ON screen rather than the one we just hid, and reveals the same lane in
    // the arrangement immediately. Reselecting is avoided, but a view switch still
    // reveals an already-selected compatible lane if the arrangement was scrolled away.
    if (viewLane && viewLane !== selectedLane) selectLane(viewLane);
    else syncNotesPanel();
    if (viewLane) {
      syncArrangementLaneSelection({ reveal: true });
      // Spend the reveal once more after the workspace fit settles. This matters when
      // the selected row was just below the arrangement viewport at the moment the
      // lower editor changed its own minimum-height contribution.
      keepLanePending = true;
    }
    if (view === 'roll') {
      if (!pianoRoll.isOpen()) schedulePianoRollOpen();
      else pianoRoll.refresh();
    } else if (view === 'pattern') {
      if (!kitRoll.isOpen()) scheduleKitOpen();
      else kitRoll.refresh();
    }
  }
  // The former floating grid represented the same Pattern editor. Close a restored
  // instance so there is one editor and one place edits can land.
  if (stepSeq.isOpen()) stepSeq.open(false);
  stepSeqWanted = false;
  if (remember) localStorage.setItem(LOWER_VIEW_KEY, view);
  scheduleDeskFit(true);
}

$('mixviewbtn').onclick = () => setLowerView('mixer');
$('rollbtn').onclick = () => setLowerView('roll');
$('seqbtn').onclick = () => setLowerView('pattern');
setLowerView(lowerView, { remember: false });

/**
 * Open whichever note editor the lane actually has.
 *
 * A percussion lane is booleans and gets the kit; a pitched one gets the roll. Both are
 * in the Notes panel, so the gesture is the same either way — double-click the bar you
 * want to work on, and the channel you clicked is the one selected. Making you know
 * which editor a snare belongs in before you can move it would be the desk's filing
 * system leaking into the work.
 *
 * The floating step grid is still where a lane with NO editor would have gone, and it is
 * still the panel for "the hats are wrong in this whole song" — but it is opened
 * deliberately now, from its own button or `g`, rather than being where a double-click
 * on a drum lands.
 */
function openNoteEditor(laneKey, bar) {
  arrangementKeyboardActive = false;
  if (bar != null && !(selectedBar && bar >= selFrom() && bar <= selTo())) {
    markBar(laneKey || 'kick', bar);
  }
  if (laneKey && !editorFor(laneKey)) { setLowerView('pattern'); return; }
  // Selecting the channel is what chooses the part — the roll is that channel's, and on
  // the kit it is the row the panel marks. Already on it when a double-click in the
  // grid got here, whose first click selected it: reselecting rebuilds the rack and
  // repaints the roll for nothing, and this is the gesture that opens the roll.
  if (laneKey && laneKey !== selectedLane) selectLane(laneKey);
  const kind = editorFor(laneKey || selectedLane);
  if (kind === 'roll' && bar != null) {
    pianoRollFocusPending = { from: bar, to: bar };
    // A bar double-click during playback is an inspection/edit gesture. Leave the
    // transport running, but hold the roll at the selected bar rather than letting
    // the live playhead page it away immediately after it opens. The header toggle
    // is the user's explicit escape hatch: turning Freeze off re-arms follow.
    if (playing) {
      pianoRoll.setFollow(false);
      syncRollFollowButton();
    }
  }
  setLowerView(kind === 'kit' ? 'pattern' : 'roll');
  if (kind === 'roll') {
    if (pianoRoll.isOpen()) spendPianoRollFocus();
    else schedulePianoRollOpen();
  }
}

const activeMelodicLanes = () => deskLanes(viewBank(), 1)
  .filter((l) => l.group === 'melodic').map((l) => l.key);
const laneHasBarFlag = (draft, from, to, field, lane) => {
  for (let i = from; i <= to; i++) {
    if (!(draft.plan[i]?.[field] || []).includes(lane)) return false;
  }
  return true;
};
const pasteLane = (draft, from, lane, clip) => {
  let out = draft;
  for (let i = 0; i < clip.bars.length; i++) {
    // The lengths go with the notes. A clip copied before this existed has none, and
    // sixteen nulls is the right thing to write for it: the destination's own lengths
    // belonged to the notes being replaced.
    const lengths = clip.lengths?.[i] || new Array(16).fill(null);
    // Converted to the DESTINATION's shape, never written as copied. A clip is a lane's
    // values as they were, and the three shapes are not interchangeable — see
    // `laneShape`, which exists because pasting a bassline onto `chords` wrote bare
    // numbers into a lane `scheduleStep` calls `.forEach` on.
    out = writeBarNotes(editBank(), out, from + i, lane,
      clip.bars[i].map((v) => laneShape(lane, v)), laneShapeLengths(lane, lengths));
  }
  return out;
};

/**
 * What the paste actually did, which is not always what was asked for.
 *
 * `writeBarNotes` returns the draft untouched for a bar that is not there, so a clip
 * longer than the room after `from` quietly loses its tail. Within one song that is
 * hard to do by accident; ACROSS songs it is the normal case — sixteen bars copied out
 * of `finale` land in an eight-bar shop cue with half of them gone and, until this,
 * nothing said so. The paste still happens: taking the first eight bars is almost
 * always what was wanted. It just no longer happens silently.
 */
const pasteLaneMessage = (draft, from, laneLabel, clip) => {
  const dropped = Math.max(0, clip.bars.length - Math.max(0, draft.plan.length - from));
  const what = `${laneLabel} pasted from ${clipLabel(clip)}`;
  return dropped ? `${what} — ${dropped} bar${dropped === 1 ? '' : 's'} past the end of the song, not pasted` : what;
};

/**
 * Empty a lane over a range of bars. Clear, in both panels.
 *
 * It WRITES the rests rather than setting the bar-level `delete` flag it used to. A
 * flag is a mark over notes that are still there: the lane went quiet, the roll still
 * showed the part, Reset brought it back, and the saved song kept every note. What
 * Clear means is that the bars are empty, so the bars are emptied — and ⌘Z, not a
 * second toggle, is what puts the part back.
 *
 * A percussion rest is `false` and a pitched one is `null`; the two are different
 * values in the file, and a lane of the wrong one stops writing back out as `seq(...)`
 * shorthand. `shared` is for clearing a whole track, where every bar is going anyway
 * and forking each one would write the same silence four times over; a range inside a
 * song must fork, or clearing bar 3 would empty the other bars of its pattern too.
 */
function clearLaneBars(laneKey, from, to, what, { shared = false } = {}) {
  const rest = PERCUSSION_LANES.includes(baseLane(laneKey)) ? false : null;
  const slots = arrDraftOf().resolution === 32 ? 32 : 16;
  const empty = Array.from({ length: slots }, () => rest);
  // Cleared means cleared: the lengths of notes that are gone go with them, or the
  // next note drawn on one of these steps inherits the length of whatever used to be
  // there. `null` here, always — a length has no percussion form.
  const noLengths = Array.from({ length: slots }, () => null);
  const write = shared ? writeBarNotesShared : writeBarNotes;
  const eb = editBank();
  // The flags come off with the notes: a bar that was marked deleted and is now empty
  // would otherwise still read as deleted, over nothing.
  let next = setLanesDeleted(arrDraftOf(), from, to, [laneKey], false);
  for (let bar = from; bar <= to; bar++) next = write(eb, next, bar, laneKey, empty, noLengths);
  applyArrangementEdit(next, what);
}

/** Delete in the arrangement means erase this instrument's notes, never remove song bars. */
function eraseSelectedArrangementBars() {
  if (!arrangementKeyboardActive || !selectedBar?.key) return false;
  const from = selFrom();
  const to = selTo();
  const laneKey = selectedBar.key;
  const span = from === to ? `bar ${from + 1}` : `bars ${from + 1}–${to + 1}`;
  clearLaneBars(laneKey, from, to,
    `${presetHeadingFor(laneKey).name} erased in ${span}`);
  return true;
}

const barFieldValue = (bar, field, lane) => {
  const value = bar?.[field];
  if (typeof value === 'number') return value;
  return Number.isFinite(value?.[lane]) ? value[lane] : 0;
};

/** One value when every selected bar/target agrees, otherwise null for "mixed". */
const uniformRegionValue = (draft, from, to, field, lanes) => {
  const values = new Set();
  for (let bar = from; bar <= to; bar++) {
    for (const lane of lanes) values.add(barFieldValue(draft.plan[bar], field, lane));
  }
  return values.size === 1 ? [...values][0] : null;
};

const rangeHasEveryFlag = (draft, from, to, field, lanes) => {
  for (let bar = from; bar <= to; bar++) {
    const flags = draft.plan[bar]?.[field] || [];
    if (!lanes.every((lane) => flags.includes(lane))) return false;
  }
  return true;
};

const signed = (value) => `${value > 0 ? '+' : value < 0 ? '−' : ''}${Math.abs(value)}`;
/**
 * A timing nudge, as the note value it actually is.
 *
 * The stored unit is a 1/32 note and stays that way — every song on disk is written in
 * it — but the control moves in HALVES of one, so the smallest nudge is a 1/64 and the
 * number no longer spells its own fraction. Count everything in 64ths and reduce from
 * there: 0.5 units is 1/64, 1 is 1/32, 6 is 3/16.
 */
const timingFraction = (units) => {
  const sixtyfourths = Math.round(Math.abs(units) * 2);
  let a = sixtyfourths; let b = 64;
  while (b) { const next = a % b; a = b; b = next; }
  const divisor = a || 1;
  return `${sixtyfourths / divisor}/${64 / divisor}`;
};
const timingText = (units) => (units
  ? `${units > 0 ? 'Delay' : 'Bring ahead'} ${timingFraction(units)} note`
  : 'On the grid');
// A file may still carry an explicit zero where the desk would have deleted the key;
// "on the grid" is what that means, and a signed fraction of nothing is not.
const timingBadge = (units) => (units
  ? `${units > 0 ? '+' : '−'}${timingFraction(units)}`
  : 'on the grid');

const NOTE_FX_DIRECTION_LABELS = {
  up: 'Up', down: 'Down', updown: 'Up / Down', downup: 'Down / Up',
  random: 'Random', asPlayed: 'As played',
};
const NOTE_FX_RATE_LABELS = [[4, '1/4'], [8 / 3, '1/4T'], [2, '1/8'], [4 / 3, '1/8T'],
  [1, '1/16'], [2 / 3, '1/16T'], [0.5, '1/32'], [1 / 3, '1/32T']];
const noteFxRateLabel = (rate) => (NOTE_FX_RATE_LABELS
  .find(([v]) => Math.abs(v - rate) < 1e-9)?.[1]
  || `${rate} steps`);
const effectDisplayName = (effect) => EFFECT_BY_ID[effect?.id]?.short
  || EFFECT_BY_ID[effect?.id]?.name || effect?.id || 'Unknown effect';
const hasActiveNoteFx = (fx) => Boolean(fx?.strum?.enabled || fx?.arp?.enabled);

/**
 * What a bar's Note FX override is worth printing in the grid.
 *
 * The presence of an override is not the answer, and badging `mode` alone was how a
 * whole row came to read NFX after a render that had removed every arpeggiator in it.
 * An override can exist purely to hold something OFF — that is what Render Arp used to
 * leave behind, and what an inherited-off track still leaves behind today. Resolve it
 * and badge what will actually sound, the way the hover card already does.
 */
function noteFxBadge(barPlanEntry, key, trackNoteFx) {
  const override = barPlanEntry?.noteFx?.[key];
  if (!override || override.mode === 'inherit') return '';
  // NFX OFF earns its badge by saying the bar departs from the track. A track with no
  // Note FX to switch off gives it nothing to report.
  if (override.mode === 'off') return hasActiveNoteFx(trackNoteFx) ? 'NFX OFF' : '';
  return hasActiveNoteFx(resolveNoteFx(trackNoteFx, barPlanEntry, key)) ? 'NFX' : '';
}

/**
 * The hover card describes processing, not content. Notes already have three visual
 * languages in the bar itself and a full editor on double-click; spelling every note
 * again in a system tooltip hid the decisions that are otherwise hardest to spot.
 *
 * These are EFFECTIVE settings. An inherited track Note FX therefore names what will
 * sound, and a bar insert snapshot replaces the ordinary channel chain in the card just
 * as it does in the engine. Bypassed devices remain visible, but are clearly struck out
 * as inactive rather than silently disappearing from the authored chain.
 */
function barOperationGroups(barPlanEntry, key, { frozen = false } = {}) {
  const laneMix = mixFor(trackId).lanes?.[key] || {};
  const muted = barPlanEntry?.off?.includes(key);
  const deleted = barPlanEntry?.delete?.includes(key);
  const playback = deleted
    ? { text: 'Deleted', tone: 'danger' }
    : muted ? { text: 'Muted', tone: 'warn' }
      : frozen ? { text: 'Frozen render', tone: 'ice' }
        : { text: 'Live', tone: 'active' };

  const changes = [];
  const transpose = typeof barPlanEntry?.transpose === 'number'
    ? (DRUM_LANES.includes(baseLane(key)) ? null : barPlanEntry.transpose)
    : barPlanEntry?.transpose?.[key];
  const offset = typeof barPlanEntry?.offset === 'number'
    ? barPlanEntry.offset : barPlanEntry?.offset?.[key];
  const gain = typeof barPlanEntry?.gain === 'number'
    ? barPlanEntry.gain : barPlanEntry?.gain?.[key];
  const pan = typeof barPlanEntry?.pan === 'number'
    ? barPlanEntry.pan : barPlanEntry?.pan?.[key];
  if (transpose != null) changes.push({ text: `Transpose ${transpose > 0 ? '+' : ''}${transpose}` });
  if (offset != null) changes.push({ text: `Timing ${timingBadge(offset)}` });
  if (gain != null) changes.push({ text: `Gain ${gain > 0 ? '+' : ''}${gain} dB` });
  if (pan != null) changes.push({ text: `Pan ${pan < 0 ? 'L' : 'R'}${Math.abs(pan)}` });

  const override = barPlanEntry?.noteFx?.[key];
  const resolved = resolveNoteFx(laneMix.noteFx, barPlanEntry, key);
  const noteItems = [];
  if (resolved.strum?.enabled) noteItems.push({
    text: `Strum · ${NOTE_FX_DIRECTION_LABELS[resolved.strum.direction] || 'Up'} · ${resolved.strum.gapMs ?? 18} ms`,
    tone: 'active',
  });
  if (resolved.arp?.enabled) {
    // The window is worth a card line of its own: it is the one arpeggiator setting that
    // moves notes the bar does not contain, so a bar reading as a chord it never plays
    // is otherwise unexplained. Printed resolved, so a window the engine had to widen
    // to an octave says the octave it will use.
    const window = noteFxRange(resolved.arp);
    // A limit is worth the same line for the same reason: it is the difference between
    // the octaves the card names and the notes the bar plays.
    const limit = noteFxLimit(resolved.arp);
    noteItems.push({
      text: `Arp · ${NOTE_FX_DIRECTION_LABELS[resolved.arp.direction] || 'Up'} · ${noteFxRateLabel(resolved.arp.rate ?? 1)} · ${resolved.arp.octaves ?? 1} oct`
        + (limit ? ` · ${limit} notes` : '')
        + (window ? ` · ${deskNoteName(window.lo, { fancy: true })}–${deskNoteName(window.hi, { fancy: true })}` : ''),
      tone: 'active',
    });
  }
  if (!noteItems.length) noteItems.push({
    text: override?.mode === 'off' ? 'Off for this bar' : 'None',
    tone: override?.mode === 'off' ? 'warn' : 'quiet',
  });
  const noteContext = override?.mode === 'on' ? 'Bar override'
    : override?.mode === 'off' ? 'Override'
      : (laneMix.noteFx?.strum?.enabled || laneMix.noteFx?.arp?.enabled) ? 'Track setting' : '';

  const barChain = barPlanEntry?.inlineFx?.[key];
  const insertChain = Array.isArray(barChain) && barChain.length ? barChain : (laneMix.effects || []);
  const insertItems = insertChain.map((effect) => ({
    text: `${effectDisplayName(effect)}${effect.bypass ? ' · bypassed' : ''}`,
    tone: effect.bypass ? 'bypassed' : 'active',
  }));
  if (!insertItems.length) insertItems.push({ text: 'No inserts', tone: 'quiet' });

  return [
    { label: 'Playback', items: [playback] },
    { label: 'Bar changes', items: changes.length ? changes : [{ text: 'None', tone: 'quiet' }] },
    { label: 'Note FX', context: noteContext, items: noteItems },
    { label: 'Insert FX', context: Array.isArray(barChain) && barChain.length ? 'Bar snapshot' : 'Channel chain',
      items: insertItems },
  ];
}

/** The compact identity card shown when a track name is hovered. */
function trackHoverGroups(preset, { frozen = false } = {}) {
  const synth = synthesizerLabelFor(preset);
  return [
    { label: 'Synthesiser', items: [{
      text: synth || 'Unknown', tone: synth ? 'active' : 'quiet',
    }] },
    { label: 'Playback', items: [{
      text: frozen ? 'Frozen render' : 'Live', tone: frozen ? 'ice' : 'active',
    }] },
  ];
}

/**
 * The right-click editor. One panel, three scopes, and the scope is whatever you
 * right-clicked: bars on a lane row edit that lane in those bars, the timeline edits
 * song structure, and a track — its strip or its row header — opens the whole track.
 *
 * There is no switch between them. Swapping scope inside the panel meant a window
 * that could quietly grow to cover the song while you were reading it, and every
 * label had to keep saying which mode was on. Exact values are staged and one Apply
 * creates one undo point; moving three sliders should not create thirty.
 */
function openRegionEditor(x, y, {
  laneKey = null, from = selFrom(), to = selTo(), wholeTrack = false, focusName = false,
} = {}) {
  if (regionPanelBusy()) return;
  closeMenu();
  restorablePopup = { kind: 'region', laneKey, from, to, wholeTrack, focusName };
  const el = $('regionedit');
  el.textContent = '';
  const draft = arrDraftOf();
  if (laneKey && wholeTrack) { from = 0; to = Math.max(0, draft.plan.length - 1); }
  const n = to - from + 1;
  const span = wholeTrack ? 'Entire track'
    : n === 1 ? `Bar ${from + 1}` : `Bars ${from + 1}–${to + 1}`;
  const scopeName = wholeTrack ? 'the whole song' : span.toLowerCase();
  const melodic = activeMelodicLanes();
  const lanes = laneKey ? [laneKey] : melodic;
  // A track's readable identity is its custom name, otherwise the preset currently
  // playing it. The engine lane key remains available everywhere it is needed for
  // storage and routing, but it must not leak into the track-name surface here.
  const laneLabel = laneKey ? presetHeadingFor(laneKey).name : 'All melodic tracks';
  const allSongLanes = deskLanes(viewBank(), 1).map((lane) => lane.key);

  const head = document.createElement('div'); head.className = 'reghead';
  const heading = document.createElement('div'); heading.className = 'regtitle';
  // On a whole track the title is the track, said the way the desk says it everywhere
  // else: its number and its name, exactly as the strip head and the arrangement row
  // carry them. "Hats-closed · Entire track" was a caption explaining the panel; this
  // names the thing the panel is about, which is the only question the title has to
  // answer. Bar-scoped panels still need to say WHICH bars, so those keep the span.
  const number = laneKey && laneNumbers.get(laneKey);
  const trackSeam = laneKey && seamFor(laneKey);
  const trackVoice = trackSeam && laneVoiceId(laneKey);
  const trackPreset = trackVoice && VOICES[trackVoice];
  // No sub-line on a track panel. "all 8 bars in the song" was telling you what the
  // panel already is — every section on it says track or channel, and there is nothing
  // else it could be operating on. The other two scopes are genuinely ambiguous and
  // keep theirs.
  heading.textContent = laneKey
    ? (wholeTrack ? `${number ? `Track ${number}. ` : ''}${laneLabel}` : `${laneLabel} · ${span}`)
    : span;
  if (!(laneKey && wholeTrack)) {
    const target = document.createElement('div'); target.className = 'regtarget';
    target.textContent = laneKey
      ? `Only ${laneLabel}, only ${scopeName}`
      : 'Timeline · the song structure in these bars; adjustments target every melodic track';
    heading.append(target);
  }
  const close = document.createElement('button'); close.className = 'regclose';
  close.textContent = '×'; close.title = 'Close'; close.onclick = closeMenu;
  head.append(heading, close); el.append(head);

  // `note` is a VALUE on the caption line, not more caption: the section says what it is
  // for and the note says what it is currently pointed at. It keeps its own case, because
  // every note this takes is a brand — MonoSynth, FMSynth, MRDR-3 — and `.regcap` is
  // uppercase, which would hand back MONOSYNTH.
  const section = (caption, note = null) => {
    const wrap = document.createElement('div'); wrap.className = 'regsection';
    const cap = document.createElement('div'); cap.className = 'regcap'; cap.textContent = caption;
    if (note) {
      const value = document.createElement('span');
      value.className = 'regcapnote';
      value.textContent = note;
      cap.append(value);
    }
    wrap.append(cap); el.append(wrap); return wrap;
  };
  const actionSection = (caption, actions, note = null) => {
    const wrap = section(caption, note);
    const grid = document.createElement('div'); grid.className = 'regactions';
    for (const action of actions.filter(Boolean)) {
      const button = document.createElement('button');
      button.textContent = action.label; button.title = action.title || action.label;
      button.disabled = !!action.disabled;
      if (action.danger) button.classList.add('danger');
      button.onclick = () => { closeMenu(); action.run(); };
      grid.append(button);
    }
    wrap.append(grid);
  };

  const controls = [];
  let applyButton = null;
  let nameChanged = false;
  const updateApply = () => {
    if (applyButton) applyButton.disabled = !nameChanged && !controls.some((control) => control.dirty);
  };

  // Renaming is the first thing on a track panel, not something under a heading about
  // adjustments — it is what the track is called, not something done to it. The label
  // is mix metadata keyed by the stable lane key, so authored tracks and added tracks
  // have the same naming behaviour without changing anything the engine schedules.
  const layer = laneKey && (mixFor(trackId).layers || []).find((item) => item.key === laneKey);
  const nameInput = laneKey && wholeTrack ? document.createElement('input') : null;
  const originalName = customTrackLabel(laneKey) || trackPreset?.label || laneLabel;
  if (nameInput) {
    const wrap = section('Track name');
    const row = document.createElement('label'); row.className = 'regname';
    nameInput.type = 'text'; nameInput.maxLength = 48; nameInput.spellcheck = false;
    nameInput.value = originalName;
    nameInput.oninput = () => {
      const next = nameInput.value.trim().replace(/\s+/g, ' ');
      nameChanged = !!next && next !== originalName;
      row.classList.toggle('changed', nameChanged);
      updateApply();
    };
    row.append(nameInput);
    wrap.append(row);
  }

  // Each of the three takes a noun, and this one's is EDITS: the desk's own bar-level
  // changes — mute, transpose, timing, gain, pan — as opposed to Notes (the part) and Track
  // (the channel and the row). It was `Reset` / `Reset track`, which read as "put the
  // track back" beside an Erase that had just taken the notes out, and could not have
  // done that: a note edit is a section of its own, and ⌘Z is what undoes one.
  const resetAction = laneKey && {
    label: 'Reset Edits',
    title: `Set ${laneLabel}'s mute, transpose, timing, gain and pan back to none in ${scopeName} — the notes are not touched`,
    run: () => {
      let next = arrDraftOf();
      next = setLanesOff(next, from, to, [laneKey], false);
      next = setLanesDeleted(next, from, to, [laneKey], false);
      next = transposeBars(next, from, to, [laneKey], 0);
      next = offsetBars(next, from, to, [laneKey], 0);
      next = gainBars(next, from, to, [laneKey], 0);
      next = panBars(next, from, to, [laneKey], 0);
      next = setBarNoteFx(next, from, to, laneKey, null);
      next = setBarEffects(next, from, to, laneKey, null);
      applyArrangementEdit(next, wholeTrack
        ? `${laneLabel} adjustments reset across the whole song`
        : `${laneLabel} adjustments reset in ${span.toLowerCase()}`);
    },
  };

  if (!laneKey) {
    const allMuted = rangeHasEveryFlag(draft, from, to, 'off', allSongLanes);
    actionSection('Song structure', [
      { label: 'Cut', title: `Copy ${span.toLowerCase()}, then remove it from the song`, run: () => {
        arrangementClipboard = { kind: 'bars', ...clipOrigin(span), ...copyBars(editBank(), arrDraftOf(), from, to) };
        applyArrangementEdit(deleteBars(arrDraftOf(), from, to), `${span} cut`);
      }},
      { label: 'Copy', title: `Copy ${span.toLowerCase()} with every track`, run: () => {
        arrangementClipboard = { kind: 'bars', ...clipOrigin(span), ...copyBars(editBank(), arrDraftOf(), from, to) };
        toast(`${span} copied`);
      }},
      // Bars, unlike notes, do NOT survive a song switch, and this is the one place on
      // the desk where the clipboard is deliberately narrower than it looks.
      //
      // A bar is a REFERENCE — `{ sec: 3 }` — and what section 3 is depends entirely on
      // the song it was read from. Pasted into another song those numbers still resolve,
      // silently, against the new song's sections: plumber's first two bars dropped into
      // hub kept `sec: 0` and came out as hub's own bar 1, a different bassline in a
      // different key, with nothing on screen to say the paste had not worked. Wrong
      // music that looks like a successful edit is worse than a button that is off, so
      // the button is off, and the tooltip sends you to Copy Notes — which carries
      // resolved pitches rather than references and therefore does travel.
      { label: 'Paste', title: arrangementClipboard?.kind === 'bars' && arrangementClipboard.song !== trackId
          ? `The copied bars belong to ${arrangementClipboard.songTitle} — copy notes instead to bring a part across songs`
          : `Insert the copied bars at bar ${from + 1}`,
        disabled: arrangementClipboard?.kind !== 'bars' || arrangementClipboard.song !== trackId,
        run: () => applyArrangementEdit(pasteBars(editBank(), arrDraftOf(), from, arrangementClipboard), `Bars pasted at ${from + 1}`) },
      { label: 'Repeat', title: `Duplicate ${span.toLowerCase()} once, immediately after it`,
        run: () => applyArrangementEdit(duplicateBars(arrDraftOf(), from, to, 1), `${span} repeated`) },
      { label: 'Insert Silence', title: `Insert ${n} silent bar${n === 1 ? '' : 's'} at bar ${from + 1}`,
        run: () => applyArrangementEdit(insertSilence(arrDraftOf(), from, n, allSongLanes), `Silence inserted at bar ${from + 1}`) },
      { label: allMuted ? 'Unmute Bars' : 'Mute Bars',
        title: `${allMuted ? 'Restore' : 'Silence'} every track in ${span.toLowerCase()} without removing the bars`,
        run: () => applyArrangementEdit(setLanesOff(arrDraftOf(), from, to, allSongLanes, !allMuted), `${span} ${allMuted ? 'unmuted' : 'muted'}`) },
      { label: 'Delete Bars', danger: true, title: `Remove ${span.toLowerCase()} and move everything after it earlier`,
        run: () => applyArrangementEdit(deleteBars(arrDraftOf(), from, to), `${span} deleted`) },
    ]);
  } else if (!wholeTrack) {
    const muted = laneHasBarFlag(draft, from, to, 'off', laneKey);
    const selectedFreezeScope = freezeScope(from, to);
    const exactFrozenSegment = frozenSegments(trackId, laneKey)
      .find((segment) => freezeScopeId(segment.scope) === freezeScopeId(selectedFreezeScope));
    const exactFrozen = !!exactFrozenSegment;
    const wholeFrozen = freezeLaneState(trackId, laneKey) === 'full';
    // Every label here is already scoped by the heading, so they stay short: this
    // panel cannot touch anything but this track in these bars.
    // No Edit notes… here either, for the reason the track panel does not have one: both
    // note editors have a toolbar button and a key of their own, they open on the
    // selected channel, and the right-click that opened this panel already selected it.
    actionSection(`${laneLabel} in ${scopeName}`, [
      { label: muted ? 'Unmute' : 'Mute', title: `${muted ? 'Unmute' : 'Mute'} ${laneLabel} in ${span.toLowerCase()}`,
        run: () => applyArrangementEdit(setLanesOff(arrDraftOf(), from, to, [laneKey], !muted), `${laneLabel} ${muted ? 'unmuted' : 'muted'} in ${span.toLowerCase()}`) },
      exactFrozen
        ? { label: 'Unfreeze Selected Bars', title: `Return ${span.toLowerCase()} to live source notes`,
          run: () => unfreezeLane(laneKey, { scope: selectedFreezeScope }) }
        : { label: 'Freeze Selected Bars',
          title: wholeFrozen ? `${laneLabel} is already frozen across the entire track`
            : `Render only ${span.toLowerCase()} and keep the rest of ${laneLabel} live`,
          disabled: wholeFrozen,
          run: () => freezeLane(laneKey, { scope: selectedFreezeScope }) },
      { label: 'Note FX…', title: `Set strum or arpeggiator for ${laneLabel}`,
        run: () => openNoteFxEditor(x, y, laneKey, { from, to }) },
      { label: 'Bar Effects…', title: `Insert an audio-effect snapshot on ${laneLabel} in ${span.toLowerCase()}`,
        run: () => openBarEffectsEditor(x, y, laneKey, { from, to }) },
      // The same three verbs as the track panel, meaning the same three things — only the
      // scope differs, and the heading is what says the scope. See NOTE-VERBS.
      { label: 'Copy Notes', title: `Copy only ${laneLabel}'s notes from ${span.toLowerCase()}`,
        run: () => {
          arrangementClipboard = { kind: 'lane', ...clipOrigin(laneLabel), ...copyLaneBars(editBank(), arrDraftOf(), from, to, laneKey) };
          toast(`${laneLabel} copied from ${span.toLowerCase()} — right-click another track, in this song or any other, to paste`);
        }},
      { label: 'Paste Notes', title: arrangementClipboard?.kind === 'lane'
          ? `Paste ${clipLabel(arrangementClipboard)} onto ${laneLabel} from bar ${from + 1}`
          : 'Copy notes from a track first',
        disabled: arrangementClipboard?.kind !== 'lane',
        run: () => applyArrangementEdit(pasteLane(arrDraftOf(), from, laneKey, arrangementClipboard),
          pasteLaneMessage(arrDraftOf(), from, laneLabel, arrangementClipboard)) },
      { label: 'Erase Notes', danger: true,
        title: `Empty ${laneLabel} in ${span.toLowerCase()}, leaving the other tracks and the rest of this one alone (⌘Z restores it)`,
        run: () => clearLaneBars(laneKey, from, to, `${laneLabel} erased in ${span.toLowerCase()}`) },
      resetAction,
    ]);
  } else if (wholeTrack) {
    // Everything you can do TO a track, on the thing you right-clicked. Mute and solo
    // are the two that are missing on purpose: they have their own buttons on both the
    // strip and the arrangement row, and a second copy in here would be a switch you
    // have to close the panel to see the state of.
    if (trackSeam) {
      // Buttons about the preset: which one, and what it sounds like. The preset's own
      // name is not in any label — it is on the line under the title, and it was making
      // the buttons different lengths on every track.
      //
      // "New preset from this…" is gone: the preset editor's own Save as new is the same
      // gesture at the moment you actually want it, which is after you have moved
      // something and decided to keep it rather than before you have opened the panel.
      actionSection('Sound', [
        { label: 'Preset', title: `Choose what plays ${laneLabel}`,
          run: () => openVoicePickerFor(laneKey, { x, y }) },
        // An engine preset is a bundle of bank keys rather than a synth, so there is
        // nothing for the editor to show.
        trackPreset && trackPreset.kind !== 'engine' && {
          label: 'Edit Preset', title: `Open ${trackPreset.label} in the preset editor`,
          run: () => editVoice(laneKey, { advanced: false, at: { x, y } }) },
        // KLNG8, MRDR-3 and TNGR-2 are the families with a second, wider surface, and until
        // now the only door to it was the ADVANCED button inside the panel — so getting
        // to it meant opening the small one first and then leaving it. This is the same
        // door, from the same panel that offers the small one, one click either way.
        //
        // Absent on every other preset rather than disabled: a button that cannot ever
        // light on this track is a promise of a screen that does not exist.
        trackPreset && isQuickVoice(trackPreset) && {
          label: 'Edit Advanced',
          title: `Open ${trackPreset.label} in the full-window editor — every control on one screen`,
          run: () => editVoice(laneKey, { advanced: true, at: { x, y } }) },
      ],
      // Which synth these two buttons would open. The title already names the PRESET
      // ("Track 7. Round Bass"); this is the other half of that identity, and it is the
      // half that says what the editor behind Edit Preset will actually look like —
      // KLNG8's six source cards and MonoSynth's filter page are not the same screen.
      // In full, not the strip's three letters: this is where there is room for the word,
      // and seeing MNO on the channel and MonoSynth here is how the abbreviation is
      // learned. Null on a lane with no preset, which drops the note and leaves SOUND.
      synthesizerLabelFor(trackPreset));
    }
    actionSection('Track', [
      { label: 'Rename Track…', title: `Rename ${laneLabel}`,
        run: () => openTrackEditor(x, y, laneKey, { focusName: true }) },
      { label: 'Note FX…', title: `Add strum or arpeggiator to ${laneLabel}`,
        run: () => openNoteFxEditor(x, y, laneKey) },
      { label: 'Channel Effects', title: `Open ${laneLabel}'s channel effects`,
        run: () => openChannelEffects(laneKey) },
      trackSeam && { label: 'Copy Track', title: `Copy ${laneLabel}'s complete part, sound and channel settings for a new track`,
        run: () => copyTrack(laneKey) },
      arrangementClipboard?.kind === 'track' && { label: 'Paste Track',
        title: `Add ${clipLabel(arrangementClipboard)} as a new independent track in this song`,
        run: () => pasteTrack() },
      frozenTracks.has(freezeKey(trackId, laneKey))
        ? { label: 'Unfreeze All', title: `Return every frozen part of ${laneLabel} to live source notes`,
          run: () => unfreezeLane(laneKey) }
        : { label: 'Freeze Track', title: `Render ${laneLabel}'s source processing for stable playback in this tab`,
          run: () => freezeLane(laneKey) },
      freezeLaneState(trackId, laneKey) === 'partial' && {
        label: 'Freeze Entire Track', title: `Replace the partial freezes with one freeze across ${laneLabel}`,
        run: () => freezeLane(laneKey),
      },
      // No Edit notes… here. The two note editors have a button each in the toolbar and a
      // key each (G and N), they open on the selected channel, and either can be left up
      // while you work — so a menu item that opens one of them is a third route to a panel
      // that is probably already on screen. The bar-scoped panel keeps its copy, because
      // there it also carries the selection into the editor, which nothing else does.
      // Always the one word. Which layer number the copy lands on is in the tooltip and
      // in the new track's name; on the button it was the one label too long for a cell.
      trackSeam && { label: 'Duplicate',
        title: layersOf(laneKey).length
          ? `Add ${laneLabel} layer ${layersOf(laneKey).length + 1}, playing the same part`
          : `Add another ${laneLabel} track playing the same part`,
        run: () => duplicateLane(laneKey) },
      // NOTE-VERBS. Three things can happen to the notes and each has one name, used in
      // this panel and in the bar panel with the same meaning:
      //
      //   Copy/Paste Notes — the part itself, moved between tracks or bars.
      //   Erase Notes      — the notes go. The track, its channel and its sound stay.
      //   Revert Edits     — the desk's own edits come off and the song's written part
      //                      comes back, erased notes included.
      //
      // They were Clear, Reset and Delete, three words for "less than there was" whose
      // difference you had to already know: Clear kept the track, Reset undid the clear,
      // and Delete was the only one that took the strip away. Now the noun says what is
      // affected — notes, edits, or the track — and only Delete Track removes anything
      // from the desk.
      { label: 'Copy Notes', title: `Copy ${laneLabel}'s notes from every bar`,
        run: () => {
          arrangementClipboard = { kind: 'lane', ...clipOrigin(laneLabel), ...copyLaneBars(editBank(), arrDraftOf(), from, to, laneKey) };
          toast(`${laneLabel} copied — right-click another track, in this song or any other, to paste`);
        }},
      { label: 'Paste Notes', title: arrangementClipboard?.kind === 'lane'
          ? `Paste ${clipLabel(arrangementClipboard)} onto ${laneLabel} from bar 1`
          : 'Copy notes from a track first',
        disabled: arrangementClipboard?.kind !== 'lane',
        run: () => applyArrangementEdit(pasteLane(arrDraftOf(), from, laneKey, arrangementClipboard),
          pasteLaneMessage(arrDraftOf(), from, laneLabel, arrangementClipboard)) },
      // Shared, because every bar is going anyway — see clearLaneBars.
      { label: 'Erase Notes', title: `Empty every bar of ${laneLabel}, keeping the track and its sound (⌘Z restores the part)`,
        run: () => clearLaneBars(laneKey, from, to, `${laneLabel} erased`, { shared: true }) },
      resetAction,
      // Two words, no track name, no wide row. The name was in the label because the item
      // used to live in a context menu that could be about anything; on a panel titled
      // `Track 3. Hats-closed` it was the third time the same word appeared, and it was the
      // one that made the button too long to fit its own cell. The confirmation names the
      // track — which is where a name earns its place, on the step you cannot take back.
      { label: 'Delete Track', danger: true,
        title: `Delete ${laneLabel} from this mix; the song bars and other tracks stay (⌘Z restores it)`,
        run: () => deleteLane(laneKey) },
    ]);
    // No Channel section. Copy channel, Paste channel, Paste effects, Bypass and Reset
    // channel are the signal path, not the part — they belong to the strip, and the strip's
    // own right-click has had exactly these five since before this panel existed. Keeping
    // them here as well gave the desk two routes to one set of buttons and made "what does
    // right-click do" depend on which view of the instrument you happened to be over.
  }

  // "Adjust Hats-closed across the whole song" on a panel called `Track 3. Hats-closed`
  // said the track's name twice and its scope once more than it needed to.
  const controlsSection = section(wholeTrack ? 'Adjust' : `Adjust ${laneLabel}`);
  const controlsWrap = document.createElement('div'); controlsWrap.className = 'regcontrols';
  controlsSection.append(controlsWrap);

  const addControl = ({ field, label, min, max, step, format }) => {
    const uniform = uniformRegionValue(draft, from, to, field, lanes);
    let current = uniform ?? 0;
    const row = document.createElement('div'); row.className = `regcontrol${uniform == null ? ' mixed' : ''}`;
    const name = document.createElement('span'); name.textContent = label;
    const range = document.createElement('input'); range.type = 'range';
    range.min = min; range.max = max; range.step = step; range.value = current;
    const number = document.createElement('input'); number.type = 'number';
    number.min = min; number.max = max; number.step = step;
    number.value = uniform == null ? '' : current; number.placeholder = 'mixed';
    const reset = document.createElement('button'); reset.textContent = 'Reset'; reset.title = `Reset ${label.toLowerCase()} to zero`;
    const readout = document.createElement('div'); readout.className = 'regread';
    readout.textContent = uniform == null ? 'Mixed values in this selection' : format(current);
    const control = { field, dirty: false, value: () => current };
    const set = (raw) => {
      if (!Number.isFinite(raw)) return;
      current = clamp(Math.round(clamp(raw, min, max) / step) * step, min, max);
      range.value = current; number.value = current;
      readout.textContent = format(current);
      control.dirty = true; row.classList.add('changed'); row.classList.remove('mixed');
      updateApply();
    };
    range.oninput = () => set(+range.value);
    number.oninput = () => { if (number.value !== '') set(+number.value); };
    reset.onclick = () => set(0);
    row.append(name, range, number, reset, readout);
    controlsWrap.append(row); controls.push(control);
  };

  if (!laneKey || melodic.includes(laneKey)) {
    addControl({ field: 'transpose', label: 'Transpose', min: -12, max: 12, step: 1,
      format: (value) => value ? `${signed(value)} semitone${Math.abs(value) === 1 ? '' : 's'}` : 'Original pitch' });
  }
  // Timing, gain and pan are per-TRACK: nudging every melodic track in a bar by the same
  // sixteenth moves nothing relative to anything, a bar's worth of gain across the
  // band is the master fader with extra steps, and panning the whole band is the master
  // balance. The timeline keeps transpose, which does mean something across a whole
  // section — a key change for four bars.
  //
  // Timing moves half a unit at a time. The file's unit is a 1/32 note and stays that
  // way, so half of one is the 1/64 that separates "behind the beat" from "late", and
  // everything downstream takes the number as it finds it — the engine multiplies it by
  // a 16th, the validator only asks that it be finite, the serializer keeps three
  // decimals. The fraction therefore costs nothing but this step and a readout that
  // spells the note value rather than the number.
  if (laneKey) {
    addControl({ field: 'offset', label: 'Timing', min: -8, max: 8, step: 0.5, format: timingText });
    addControl({ field: 'gain', label: 'Gain', min: -12, max: 12, step: 0.5,
      format: (value) => value ? `${signed(value)} dB` : 'Original level' });
    // An OFFSET from the channel's pot, in the pot's own numbers, and the readout says
    // so on every position: a lane sitting at +10 with -20 here plays the bar at -10, so
    // "20 left of the mix" is the true reading and "20 left" would not be. Re-panning
    // the channel afterwards carries the bar with it, which is why this is not a
    // position — a bar pinned to an absolute spot would silently escape the pot.
    addControl({ field: 'pan', label: 'Pan', min: -100, max: 100, step: 5,
      format: (value) => (value
        ? `${signed(value)} — ${value < 0 ? 'left' : 'right'} of the mix`
        : 'Where the mix puts it') });
  }

  const foot = document.createElement('div'); foot.className = 'regfoot';
  const cancel = document.createElement('button'); cancel.textContent = 'Cancel'; cancel.onclick = closeMenu;
  applyButton = document.createElement('button'); applyButton.className = 'regapply';
  applyButton.textContent = 'Apply changes'; applyButton.disabled = true;
  applyButton.onclick = () => {
    const label = nameInput ? nameInput.value.trim().replace(/\s+/g, ' ') : '';
    const nameOnly = !!nameChanged && !controls.some((control) => control.dirty);
    if (nameChanged && label) {
      // Name and arrangement edits share one undo snapshot when Apply changes
      // contains both. The mix mutation is deliberately staged before the
      // arrangement serializer reads the desk-owned layer list.
      pushUndo(null);
      editMix((m) => {
        m.labels = { ...(m.labels || {}), [laneKey]: label };
      }, null, { undo: false });
      bankCache.sig = null;
    }
    let next = arrDraftOf();
    for (const control of controls.filter((item) => item.dirty)) {
      if (control.field === 'transpose') next = transposeBars(next, from, to, lanes, control.value());
      else if (control.field === 'offset') next = offsetBars(next, from, to, lanes, control.value());
      else if (control.field === 'gain') next = gainBars(next, from, to, lanes, control.value());
      else if (control.field === 'pan') next = panBars(next, from, to, lanes, control.value());
    }
    closeMenu();
    if (controls.some((control) => control.dirty)) {
      applyArrangementEdit(next, wholeTrack
        ? `${laneLabel} adjusted across the entire track`
        : `${laneLabel} adjusted in ${span.toLowerCase()}`, { undo: !nameChanged });
      if (nameChanged) {
        buildRack();
        selectLane(laneKey);
      }
    } else if (nameOnly) {
      buildRack();
      buildArrangement();
      selectLane(laneKey);
      toast(`${label} renamed — ⌘Z to undo`);
    }
  };
  foot.append(cancel, applyButton); el.append(foot);
  el.onkeydown = (event) => { if (event.key === 'Escape') { event.stopPropagation(); closeMenu(); } };

  el.style.left = `${x}px`; el.style.top = `${y}px`; el.classList.add('show');
  const rect = el.getBoundingClientRect();
  el.style.left = `${Math.max(6, Math.min(x, innerWidth - rect.width - 6))}px`;
  el.style.top = `${Math.max(6, Math.min(y, innerHeight - rect.height - 6))}px`;
  if (focusName) requestAnimationFrame(() => el.querySelector('.regname input')?.focus());
}

function timelineMenu(ev) {
  ev.preventDefault();
  ev.stopPropagation();
  const clicked = timelineBar(ev);
  const inSel = selectedBar && clicked >= selFrom() && clicked <= selTo();
  if (!inSel) markBar(null, clicked);
  openRegionEditor(ev.clientX, ev.clientY, { from: selFrom(), to: selTo() });
}

/**
 * The menu on a bar. This is where arranging happens.
 *
 * Scope is the SELECTION when there is one covering the bar you right-clicked, and
 * that one bar otherwise — the same rule a file manager uses, and the one that makes
 * "select four bars, right-click, duplicate" work without a modifier.
 */
function barMenu(ev, laneKey, bar) {
  ev.preventDefault();
  ev.stopPropagation();
  arrangementKeyboardActive = true;
  const inSel = selectedBar && bar >= selFrom() && bar <= selTo();
  if (!inSel) markBar(laneKey, bar);
  else if (selectedBar.key !== laneKey) markBar(laneKey, selFrom(), selTo());
  openRegionEditor(ev.clientX, ev.clientY, { laneKey, from: selFrom(), to: selTo() });
}

/**
 * What a lane actually plays in one cell, step by step: 'A2 · — · A2 · C3'. The
 * shading says how busy a bar is; this says what is in it, which is the difference
 * between finding the bar and knowing whether the bass is on the root.
 *
 * Percussion is a hit or nothing, melodic lanes are frequencies, and chord lanes
 * are arrays of them — all three come back as one line you can read.
 */
function cellSteps(row, cell) {
  return (row.steps?.[cell] || []).map((v) => {
    if (v === true) return '●';
    if (Array.isArray(v)) return v.map((hz) => deskNoteNameHz(hz)).filter(Boolean).join('+') || '·';
    if (typeof v === 'number' && v > 0) return deskNoteNameHz(v) || '·';
    return '·';
  });
}

const cellNotes = (row, cell) => cellSteps(row, cell).join(' ');

/** Return the pitched values represented by one activity cell. */
function noteFrequencies(values) {
  return values.flatMap((value) => Array.isArray(value) ? value : [value])
    .filter((value) => typeof value === 'number' && value > 0);
}

/** Keep every percussion hit visible when a long song forces several sixteenths into
 * one visual cell. Return the exact fractional slots so the renderer can place a
 * rounded pattern-mixer hit at each boolean attack. */
function percussionHitPositions(values) {
  return values.reduce((out, value, index) => {
    if (value === true) out.push(index);
    return out;
  }, []);
}

/**
 * Place melodic marks on the vertical pitch contour of their lane. Percussion has no
 * pitch and stays centred; chords use the centre of their notes, with the same stable
 * lane range so a melody does not jump around merely because another cell is empty.
 */
function noteVisualGeometry(values, range) {
  const freqs = noteFrequencies(values);
  if (!freqs.length || !range) return { y: '50%', span: '0px' };
  const midis = freqs.map((hz) => 69 + 12 * Math.log2(hz / 440));
  const centre = midis.reduce((sum, midi) => sum + midi, 0) / midis.length;
  // Use the taller arrangement row: keep a small air margin, but let the contour
  // occupy most of the available pitch space so dots and the SVG trail agree.
  const y = 12 + (1 - ((centre - range.min) / range.span)) * 76;
  const spread = Math.min(10, Math.max(0, (Math.max(...midis) - Math.min(...midis)) * 1.8));
  return { y: `${clamp(y, 12, 88).toFixed(1)}%`, span: `${spread.toFixed(1)}px` };
}

/** Flatten a bar's visual cells into note events without confusing sequential notes
 * with a chord. A cell can contain several original sixteenths when a long song is
 * compressed; each event keeps its slot so the miniature marks retain rhythm. */
function melodicMovementPoints(steps, range) {
  if (!range || !steps.length) return [];
  const points = [];
  steps.forEach((values, cellIndex) => {
    const slots = Math.max(1, values.length);
    values.forEach((value, slot) => {
      const frequencies = noteFrequencies([value]);
      if (!frequencies.length) return;
      const x = ((cellIndex + (slot + 0.5) / slots) / steps.length) * 100;
      points.push({
        x,
        y: Number.parseFloat(noteVisualGeometry(frequencies, range).y),
      });
    });
  });
  return points;
}

/** The visible note heads use the same bar coordinates as the trail. Chord tones
 * share an x position but keep separate y positions; sequential tones move across
 * the bar instead of looking like a stack. */
function melodicDotPoints(steps, range) {
  if (!range || !steps.length) return [];
  const points = [];
  steps.forEach((values, cellIndex) => {
    const slots = Math.max(1, values.length);
    values.forEach((value, slot) => {
      const frequencies = noteFrequencies([value]);
      const x = ((cellIndex + (slot + 0.5) / slots) / steps.length) * 100;
      for (const hz of frequencies) {
        points.push({ x, y: Number.parseFloat(noteVisualGeometry([hz], range).y), cellIndex, slot });
      }
    });
  });
  return points;
}

/** Draw one smooth contour through the melodic note centres. It is deliberately a
 * visual shorthand, not a second piano roll: the dots still carry the attacks and
 * the curve only carries the movement of the line between them. */
function melodicMovementPath(steps, range) {
  const points = melodicMovementPoints(steps, range);
  return melodicMovementPathFromPoints(points);
}

function melodicMovementPathFromPoints(points) {
  if (points.length < 2) return '';
  let path = `M ${points[0].x.toFixed(2)} ${points[0].y.toFixed(2)}`;
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[i - 1] || points[i];
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[i + 2] || p2;
    const c1x = p1.x + (p2.x - p0.x) / 6;
    const c1y = p1.y + (p2.y - p0.y) / 6;
    const c2x = p2.x - (p3.x - p1.x) / 6;
    const c2y = p2.y - (p3.y - p1.y) / 6;
    path += ` C ${c1x.toFixed(2)} ${c1y.toFixed(2)}, ${c2x.toFixed(2)} ${c2y.toFixed(2)}, ${p2.x.toFixed(2)} ${p2.y.toFixed(2)}`;
  }
  return path;
}

/** Fade the last note toward the next bar only when that next bar continues the
 * phrase. This keeps a melodic line legible across a bar boundary without inventing
 * a trail into silence. */
function melodicMovementTailPath(last, next) {
  if (!last || !next || last.x >= 99.5) return '';
  const span = 100 - last.x;
  const targetY = last.y + (next.y - last.y) * .4;
  const c1x = last.x + span * .34;
  const c2x = 100 - span * .22;
  const c1y = last.y + (targetY - last.y) * .2;
  const c2y = targetY;
  return `M ${last.x.toFixed(2)} ${last.y.toFixed(2)} C ${c1x.toFixed(2)} ${c1y.toFixed(2)}, ${c2x.toFixed(2)} ${c2y.toFixed(2)}, 100 ${targetY.toFixed(2)}`;
}

// The drag in progress across the grid, if any. A range is picked by pressing in one
// bar and releasing in another; a press and release in the same bar is a click, and
// still means what it always meant.
let dragSel = null;
let dragClickSuppress = false;
let barDrag = null;
let barDragCue = null;
const clearBarDragCue = () => {
  barDragCue?.remove();
  barDragCue = null;
};
const showBarDragCue = (ev, copy) => {
  if (!barDragCue) {
    barDragCue = document.createElement('span');
    barDragCue.className = 'arrbardragcue';
    document.body.append(barDragCue);
  }
  barDragCue.textContent = copy ? '+' : '↦';
  barDragCue.classList.toggle('copy', copy);
  barDragCue.style.left = `${ev.clientX + 12}px`;
  barDragCue.style.top = `${ev.clientY + 12}px`;
};
// Command is the desk's advertised copy gesture on macOS. Option remains accepted for
// people already using the older hint and for keyboards where Command is unavailable.
const barCopyModifier = (ev) => ev.metaKey || ev.altKey;
const barDropTarget = (ev) => {
  const box = document.elementFromPoint(ev.clientX, ev.clientY)?.closest?.('.arrbar');
  if (!box) return null;
  const row = box.closest('.arrrow');
  return row?.dataset.lane ? { row, box, lane: row.dataset.lane, bar: Number(box.dataset.bar) } : null;
};
function finishBarDrag(cancelled = false) {
  const d = barDrag;
  barDrag = null;
  dragClickSuppress = !!d?.moved;
  clearBarDragCue();
  document.querySelectorAll('.arrbar.dragtarget').forEach((el) => el.classList.remove('dragtarget'));
  if (!d || cancelled || !d.moved || !d.target) return;
  const count = d.to - d.from + 1;
  const maxStart = Math.max(0, songShape().bars.length - count);
  const at = Math.max(0, Math.min(maxStart, d.target.bar));
  if (!d.copy && d.sourceLane === d.target.lane && at === d.from) return;
  const next = moveLaneBars(editBank(), arrDraftOf(), d.from, d.to, d.sourceLane, d.target.lane, at,
    { copy: d.copy });
  applyArrangementEdit(next, `${d.copy ? 'Copied' : 'Moved'} ${count} bar${count === 1 ? '' : 's'}`);
}
addEventListener('pointermove', (ev) => {
  if (!barDrag || !(ev.buttons & 1)) return;
  if (!barDrag.moved && Math.hypot(ev.clientX - barDrag.x, ev.clientY - barDrag.y) < 4) return;
  barDrag.copy = barCopyModifier(ev);
  const target = barDropTarget(ev);
  if (target) {
    barDrag.target = target;
    barDrag.moved = true;
    document.querySelectorAll('.arrbar.dragtarget').forEach((el) => el.classList.remove('dragtarget'));
    target.box.classList.add('dragtarget');
  }
  showBarDragCue(ev, barCopyModifier(ev));
});
addEventListener('pointerup', () => finishBarDrag());
addEventListener('pointercancel', () => finishBarDrag(true));
addEventListener('pointerup', () => {
  if (dragSel?.moved) scheduleSelectionEditors();
  if (dragSel) dragClickSuppress = !!dragSel.moved;
  dragSel = null;
});
addEventListener('pointercancel', () => {
  if (dragSel?.moved) scheduleSelectionEditors();
  dragSel = null;
  dragClickSuppress = false;
});

function buildArrangement() {
  const grid = $('arrgrid');
  grid.textContent = '';
  clearArrangementPlayback();
  arrCells = [];
  arrangementMeters.clear();
  const arrange = $('arrange');
  if (arrange) {
    arrange.dataset.noteVisual = noteVisualMode;
    arrange.dataset.noteAnimation = noteAnimation ? 'on' : 'off';
  }
  // The bar plan, so each cell knows whether the arrangement silences its lane here.
  const plan = songShape().bars;
  const patternStart = patternStarts(plan);
  // Keep the actual sixteenth grid wherever it remains legible. Four cells per bar
  // made every beat look like one note, which erased hats, syncopation and melodic
  // movement. The breakpoints cap the total at roughly 256 cells across a row while
  // preserving the finest useful rhythm for short songs.
  const perBar = [16, 8, 4, 2, 1].find((cells) => plan.length * cells <= 256) || 1;
  arrCellsPerBar = perBar;
  // Every lane, whatever the mixer is showing: the arrangement is the song, and a
  // song does not lose its drums because you are looking at the melody.
  const view = viewBank();
  const desk = deskLanes(view, 1).map((l) => l.key);
  const rows = laneActivity(view, 1, perBar);
  rows.sort((a, b) => desk.indexOf(a.key) - desk.indexOf(b.key));
  const pitchRanges = new Map();
  for (const row of rows) {
    const midis = row.steps.flatMap(noteFrequencies)
      .map((hz) => 69 + 12 * Math.log2(hz / 440));
    if (midis.length) {
      const min = Math.min(...midis);
      const max = Math.max(...midis);
      pitchRanges.set(row.key, { min, span: Math.max(1, max - min) });
    }
  }

  rows.forEach((row) => {
    const freezeState = freezeLaneState(trackId, row.key);
    const frozen = freezeState !== 'live';
    // The lane's track Note FX, read once per row: every bar badge resolves against it.
    const laneNoteFx = mixFor(trackId).lanes?.[row.key]?.noteFx || null;
    const el = document.createElement('div');
    el.className = `arrrow${frozen ? ' frozen' : ''}${freezeState === 'partial' ? ' partially-frozen' : ''}`;
    el.dataset.lane = row.key;
    // What this row says when it has no preset to name. Kept on the row so a retitle
    // after a voice change can fall back to the same two words this build used, without
    // rebuilding the grid to find them again — see refreshLaneIdentity.
    el.dataset.laneLabel = row.label;
    el.dataset.group = row.group || '';
    el.style.setProperty('--lane', laneColour(row.key));
    // The track header follows Logic's two-line hierarchy: identity above, controls
    // below. The number spans both lines; the bars sit alongside the upper line.
    const header = document.createElement('div');
    header.className = 'arrhead-cell';
    const preset = presetForLane(row.key);
    const displayLabel = customTrackLabel(row.key) || preset?.label || row.label;
    // Desk order, numbered — the way you refer to a track out loud ("mute 3") and
    // the order the strips run in below.
    const num = document.createElement('span');
    num.className = 'arrnum';
    num.textContent = String(laneNumbers.get(row.key) ?? '');
    const btns = document.createElement('div');
    btns.className = 'arrbtns';
    btns.append(...muteSoloPair(row.key, displayLabel));
    const icon = groupIcon(row.group);
    icon.classList.add('arrtrack-icon');
    const top = document.createElement('div');
    top.className = 'arrtrack-top';
    const category = document.createElement('span');
    category.className = 'arrpresetcat';
    category.textContent = preset?.category || cap(row.group || 'track');
    const name = document.createElement('div');
    name.className = 'arrname';
    name.textContent = displayLabel;
    const trackNumber = laneNumbers.get(row.key);
    name.dataset.tip = displayLabel;
    name.dataset.tipkind = 'track';
    name.dataset.tipkey = trackNumber ? `Track ${trackNumber}` : 'Track';
    name.dataset.tipcontext = `${trackNumber ? `Track ${trackNumber} · ` : ''}${plan.length} bars`;
    name.dataset.tipgroups = JSON.stringify(trackHoverGroups(preset, { frozen }));
    name.dataset.tiphints = JSON.stringify([
      { key: 'Click', text: 'Select / choose preset' },
      { key: 'Right-click', text: 'Track editor' },
    ]);
    // No title here: markClipped() puts one on only if the name is actually cut off.
    //
    // The name changes what plays the track — the same two-step the channel strip's
    // name takes. Pointing at a track still has to stay safe, and it is: the first
    // click on a row you are not on selects it and nothing more, so the library only
    // ever opens on a track you are already looking at. (This used to be the row's
    // right-click menu and nothing else, back when one click opened the picker
    // outright and landing on a name you meant to point at cost you a sound.)
    if (seamFor(row.key)) {
      name.setAttribute('role', 'button');
      name.addEventListener('click', (ev) => {
        // Not armed yet: let the click through to the header, which selects the row —
        // arming this name for the second click on the way past.
        if (!presetArmed(row.key)) { armPreset(row.key); return; }
        ev.stopPropagation();
        openVoicePicker(ev.clientX, ev.clientY, row.key);
      });
      // Two clicks of the name are not a double-click gesture: the header's dblclick
      // plays from where the lane comes in, which is not what the second click meant.
      name.addEventListener('dblclick', (ev) => ev.stopPropagation());
    }
    //
    // Selecting is what a plain click does, and it is the WHOLE header that does it: the
    // number, the family mark, the name, the type and the space around them are all the
    // same track, and a click that landed on the number and did nothing read as a dead
    // row. Only the controls with a job of their own opt out — M and S stop the click
    // themselves, and the level slider is a drag.
    header.addEventListener('click', () => selectLane(row.key));
    // The same double-click the strip head takes: play from the bar this lane comes in
    // on. Not on those same controls, where a double-click is two presses of a control
    // rather than a gesture on the track.
    header.addEventListener('dblclick', (ev) => {
      if (ev.target.closest('.arrbtns, .arrgain')) return;
      playFromLaneStart(row.key);
    });
    // The TRACK panel, and only here. The row is the track — what it plays, what plays
    // it, whether it is in the song — and the strip below is its channel. Both used to
    // open this, which meant two routes to one window and a right-click whose result you
    // could not predict from where you clicked. On the header cell only: the bars keep
    // their right-click for the bar menu.
    trackMenu(header, row.key);
    // Drag the header to move the track. The ROW is what travels, because the row is
    // what you are looking at, but only a press on the header starts it: the bars to
    // the right have a drag of their own — select a range for this instrument — and
    // that gesture is older and used more often than this one. The name and the two
    // buttons opt out for the same reason they opt out of everything else on the row.
    laneDragHandle(el, header, row.key, '.arrbtns, .arrgain, .arrname');
    const bottom = document.createElement('div');
    bottom.className = 'arrtrack-bottom';
    top.append(name);
    if (hasActiveNoteFx(laneNoteFx)) {
      const noteFx = document.createElement('span');
      noteFx.className = 'arrtrack-notefx';
      noteFx.textContent = 'NFX';
      noteFx.title = 'Track Note FX enabled';
      noteFx.setAttribute('aria-label', 'Track Note FX enabled');
      noteFx.setAttribute('role', 'button');
      noteFx.tabIndex = 0;
      const openTrackNoteFx = (ev) => {
        ev.stopPropagation();
        const r = noteFx.getBoundingClientRect();
        openNoteFxEditor(r.left, r.bottom + 4, row.key);
      };
      noteFx.addEventListener('click', openTrackNoteFx);
      noteFx.addEventListener('keydown', (ev) => {
        if (ev.key !== 'Enter' && ev.key !== ' ') return;
        ev.preventDefault();
        openTrackNoteFx(ev);
      });
      top.append(noteFx);
    }
    if (frozen) top.append(freezeMark('arrfreeze', '❄'));
    top.append(category);
    bottom.append(btns);
    header.append(num, icon, top, bottom);
    const bars = document.createElement('div');
    bars.className = 'arrbars';
    // Runs of playing beats are one region, not a row of chips. The chosen visual
    // language paints the note marks; the cells themselves stay the same width so the
    // columns continue to line up with the ruler.
    // A whole bar is the unit you pick, whatever resolution the shading is drawn at:
    // the cells inside a bar are a picture of it, and the bar is the target.
    const barCount = Math.ceil(row.density.length / perBar);
    for (let bar = 0; bar < barCount; bar++) {
      const box = document.createElement('div');
      const playing = row.density.slice(bar * perBar, (bar + 1) * perBar).some((v) => v > 0);
      const barFrozen = freezeCoversBar(trackId, row.key, bar);
      box.className = `arrbar${playing ? ' has-notes' : ''}${barFrozen ? ' frozen' : ''}`;
      box.dataset.bar = String(bar);
      const barColour = arrangementBarField(row.key);
      box.style.setProperty('--bar-colour', barColour);
      // A bar this lane plays in is tinted its own colour end to end, so the rests
      // inside it read as part of the bar rather than as the gap between two bars.
      // The tint also fills the gutters between beats, which is what makes a bar
      // with a hit on every other beat still look like one bar.
      if (playing) {
        box.style.background = barColour;
      }
      // Melodic detail is carried by the same fixed-size dots as percussion. The
      // smooth bar-wide trail uses those exact note positions, so compression
      // preserves rhythm without making the line drift from the marks.
      const barSteps = row.steps.slice(bar * perBar, (bar + 1) * perBar);
      const nextBarSteps = row.steps.slice((bar + 1) * perBar, (bar + 2) * perBar);
      const barPoints = row.group === 'melodic'
        ? melodicMovementPoints(barSteps, pitchRanges.get(row.key))
        : [];
      const nextBarPoints = row.group === 'melodic'
        ? melodicMovementPoints(nextBarSteps, pitchRanges.get(row.key))
        : [];
      const movement = row.group === 'melodic'
        ? melodicMovementPath(barSteps, pitchRanges.get(row.key))
        : '';
      const tail = melodicMovementTailPath(barPoints.at(-1), nextBarPoints[0]);
      const melodicDots = row.group === 'melodic'
        ? melodicDotPoints(barSteps, pitchRanges.get(row.key))
        : [];
      if (movement || tail) {
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        line.classList.add('arrmelodyline');
        line.setAttribute('viewBox', '0 0 100 100');
        line.setAttribute('preserveAspectRatio', 'none');
        line.setAttribute('aria-hidden', 'true');
        if (movement) {
          const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
          path.setAttribute('d', movement);
          line.append(path);
        }
        if (tail) {
          const fadeId = `arrtrailfade-${row.key.replace(/[^a-z0-9_-]/gi, '_')}-${bar}`;
          const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');
          const gradient = document.createElementNS('http://www.w3.org/2000/svg', 'linearGradient');
          gradient.id = fadeId;
          // Keep the handoff solid until the final few pixels of the bar. Using
          // bar-space coordinates avoids making a long tail look prematurely faded.
          gradient.setAttribute('x1', '94'); gradient.setAttribute('y1', '0');
          gradient.setAttribute('x2', '100'); gradient.setAttribute('y2', '0');
          gradient.setAttribute('gradientUnits', 'userSpaceOnUse');
          const solid = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
          solid.setAttribute('offset', '0'); solid.setAttribute('stop-color', 'var(--trail-thread)');
          solid.setAttribute('stop-opacity', '.74');
          const fade = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
          fade.setAttribute('offset', '1'); fade.setAttribute('stop-color', 'var(--trail-thread)');
          fade.setAttribute('stop-opacity', '.42');
          gradient.append(solid, fade); defs.append(gradient); line.append(defs);
          const tailPath = document.createElementNS('http://www.w3.org/2000/svg', 'path');
          tailPath.classList.add('arrtrailtail');
          tailPath.setAttribute('d', tail);
          tailPath.style.stroke = `url(#${fadeId})`;
          line.append(tailPath);
        }
        box.append(line);
      }
      for (const point of melodicDots) {
        const dot = document.createElement('span');
        dot.className = 'arrmicrodot';
        dot.dataset.cell = String(point.cellIndex);
        // The sixteenth INSIDE that cell this attack belongs to. A compressed song puts
        // several of them in one cell, and the playback accent has to follow the note
        // rather than the box it is drawn in.
        dot.dataset.slot = String(point.slot);
        dot.setAttribute('aria-hidden', 'true');
        dot.style.setProperty('--micro-x', `${point.x.toFixed(2)}%`);
        dot.style.setProperty('--micro-y', `${point.y.toFixed(1)}%`);
        box.append(dot);
      }
      for (let beat = 0; beat < perBar; beat++) {
        const cell = bar * perBar + beat;
        const d = row.density[cell] ?? 0;
        // Regions stay joined inside one pattern, but stop cleanly at a pattern
        // boundary. Without this the divider sits over one uninterrupted colour bar
        // and reads as a ruler tick rather than a change in the music.
        const openL = d > 0 && cell > 0 && row.density[cell - 1] > 0
          && !(beat === 0 && patternStart[bar]);
        const openR = d > 0 && row.density[cell + 1] > 0
          && !(beat === perBar - 1 && patternStart[bar + 1]);
        const c = document.createElement('div');
        // The downbeat tick would cut a region in half, so it only marks bars that
        // start something — a rest, or the first beat of a region.
        const note = d > 0;
        c.className = 'arrcell'
          + (perBar > 1 && beat === 0 && !openL ? ' barstart' : '')
          + (note ? ' note' : '');
        if (note) {
          c.style.setProperty('--note-strength', String(clamp(d, 0, 1)));
          c.style.setProperty('--note-tilt', `${(((bar * perBar + beat) * 17) % 7) - 3}deg`);
          const values = row.steps[cell] || [];
          const frequencies = noteFrequencies(values);
          // Which sixteenths inside this cell are attacks. One character per slot, read
          // back by the playback accent so a note on the second half of a cell is set
          // off when it sounds and not when the playhead reaches the cell.
          c.dataset.hits = (values.length ? values : [true])
            .map((value) => (value === true || noteFrequencies([value]).length ? '1' : '0')).join('');
          const hasChord = values.some((value) => Array.isArray(value)
            && noteFrequencies([value]).length > 1);
          if (hasChord) c.classList.add('chord');
          if (row.group === 'melodic' && frequencies.length) {
            // One visual cell can represent a whole bar in a long song. Keep the
            // actual attacks visible at their local time positions; only tones in
            // the same source step share an x coordinate and read as a chord.
            c.classList.add('micro-notes');
          }
          const percussionHits = percussionHitPositions(values);
          if (percussionHits.length) {
            c.classList.add('percussion');
            const slots = values.length;
            for (const index of percussionHits) {
              const hit = document.createElement('span');
              hit.className = 'arrhit';
              hit.dataset.slot = String(index);
              hit.setAttribute('aria-hidden', 'true');
              hit.style.left = `${(((index + 0.5) / slots) * 100).toFixed(1)}%`;
              c.append(hit);
            }
          }
          const geometry = noteVisualGeometry(values, pitchRanges.get(row.key));
          c.style.setProperty('--note-y', geometry.y);
          c.style.setProperty('--note-span', geometry.span);
        }
        if (d > 0) {
          if (noteVisualMode === 'solid') c.style.background = 'transparent';
          else c.style.background = 'transparent';
        } else if (playing) {
          c.style.background = 'transparent';        // the bar's own tint shows through
        }
        box.append(c);
      }
      // A lane the arrangement silences here keeps its written colour but gets the
      // muted treatment below. That is a different thing from deletion: the bar still
      // occupies time and can be unmuted without restoring any notes.
      if (plan[bar]?.off?.includes(row.key)) {
        box.classList.add('barmuted');
      }
      if (plan[bar]?.delete?.includes(row.key)) {
        box.classList.add('bardeleted');
      }
      const barFx = plan[bar]?.inlineFx?.[row.key] || [];
      const barFxNames = barFx.map((effect) => EFFECT_BY_ID[effect.id]?.short
        || EFFECT_BY_ID[effect.id]?.name || effect.id).join(' + ');
      // Keep the most important melodic edit visible without opening a tooltip. The
      // full details remain in the hover card, while a compact +5/-7 badge makes a transposed
      // bar immediately recognisable in the arrangement row.
      const transpose = typeof plan[bar]?.transpose === 'number'
        ? (row.group === 'melodic' ? plan[bar].transpose : null)
        : plan[bar]?.transpose?.[row.key];
      const offset = typeof plan[bar]?.offset === 'number'
        ? plan[bar].offset
        : plan[bar]?.offset?.[row.key];
      const gain = typeof plan[bar]?.gain === 'number'
        ? plan[bar].gain
        : plan[bar]?.gain?.[row.key];
      const pan = typeof plan[bar]?.pan === 'number'
        ? plan[bar].pan
        : plan[bar]?.pan?.[row.key];
      const badge = [
        transpose != null && `${transpose > 0 ? '+' : ''}${transpose}`,
        offset != null && timingBadge(offset),
        gain != null && `${gain > 0 ? '+' : ''}${gain}dB`,
        // L20 / R20, the way a console prints a pan — the one badge here that is a
        // direction rather than a quantity, and the sign would read as a semitone.
        pan != null && `${pan < 0 ? 'L' : 'R'}${Math.abs(pan)}`,
        noteFxBadge(plan[bar], row.key, laneNoteFx),
        barFx.length && `FX${barFx.length}${barFxNames ? ` · ${barFxNames}` : ''}`,
      ].filter(Boolean).join(' · ');
      if (badge) {
        const meta = document.createElement('span');
        meta.className = 'arrmeta';
        meta.textContent = badge;
        box.append(meta);
      }
      // Bars use the desk's structured card. Deliberately omit `title`: the browser's
      // old, unformatted note dump would otherwise appear over this popup later.
      box.dataset.tip = displayLabel;
      box.dataset.tipkind = 'bar';
      box.dataset.tipkey = trackNumber ? `Track ${trackNumber}` : 'Track';
      box.dataset.tipcontext = `Bar ${bar + 1}`;
      box.dataset.tipgroups = JSON.stringify([
        { label: 'Synthesiser', items: [{
          text: synthesizerLabelFor(preset) || 'Unknown',
          tone: synthesizerLabelFor(preset) ? 'active' : 'quiet',
        }] },
        ...barOperationGroups(plan[bar], row.key, { frozen: barFrozen }),
      ]);
      box.dataset.tiphints = JSON.stringify([
        { key: 'Click', text: 'Select' },
        { key: 'Drag', text: 'Move' },
        { key: '⌘ Drag', text: 'Copy' },
        { key: 'Right-click', text: 'Edit' },
        { key: 'Double-click', text: 'Notes' },
        { key: '▶', text: 'Play' },
      ]);
      const at = bar * 16;
      const playButton = document.createElement('button');
      playButton.type = 'button';
      playButton.className = 'arrbarplay';
      playButton.textContent = '▶';
      playButton.dataset.tip = `Play bar ${bar + 1}`;
      playButton.dataset.tipsays = `Start playback immediately from ${displayLabel} at bar ${bar + 1}.`;
      playButton.setAttribute('aria-label', `Play ${displayLabel} from bar ${bar + 1}`);
      playButton.onpointerdown = (ev) => ev.stopPropagation();
      playButton.ondblclick = (ev) => ev.stopPropagation();
      playButton.onclick = (ev) => {
        ev.stopPropagation();
        if (selectedLane !== row.key) selectLane(row.key);
        markBar(row.key, bar);
        jumpTo(at, { start: true, immediate: true });
        toast(`Playing from bar ${bar + 1}`);
      };
      box.append(playButton);
      box.onclick = (ev) => {
        arrangementKeyboardActive = true;
        if (dragClickSuppress) { dragClickSuppress = false; return; }
        const selectionChanges = !selectedBar || selFrom() !== bar || selTo() !== bar;
        // Only when it is a different channel. A double-click sends this handler
        // through twice before the dblclick that opens the roll, and re-selecting the
        // lane you are already on tears down and rebuilds the whole device rack.
        if (selectedLane !== row.key) selectLane(row.key);
        // Shift extends the selection from where it started, the way a list does.
        if (ev.shiftKey && selectedBar) markBar(selectedBar.key, selectedBar.from, bar);
        // Same reason: the second click of a double-click asks for the selection it
        // already has. Bring it back into view, which is the part of `markBar` that
        // still means something on a repeat click, and skip the repaint.
        else if (selectionChanges || selectedBar.key !== row.key) markBar(row.key, bar);
        else focusSelectionEditors();
      };
      // Drag across the row to take a range. Held on the row rather than the cell so
      // the pointer can leave the bar it started in, which is the whole gesture.
      box.onpointerdown = (ev) => {
        if (ev.button !== 0) return;
        arrangementKeyboardActive = true;
        // Empty bars have no musical content to carry. Keep their original gesture:
        // dragging across the row selects a bar range. A note-bearing bar is the only
        // place where the newer move/copy gesture should take ownership.
        if (!playing) {
          dragSel = { key: row.key, from: bar, moved: false };
          ev.stopPropagation();
          dragClickSuppress = false;
          barDrag = null;
          return;
        }
        const selectedRange = selectedBar?.key === row.key
          && bar >= selFrom() && bar <= selTo();
        const from = selectedRange ? selFrom() : bar;
        const to = selectedRange ? selTo() : bar;
        barDrag = { sourceLane: row.key, from, to, copy: barCopyModifier(ev), moved: false, target: null,
          x: ev.clientX, y: ev.clientY };
        showBarDragCue(ev, barCopyModifier(ev));
        ev.stopPropagation();
        dragClickSuppress = false;
        dragSel = null;
      };
      box.onpointerenter = () => {
        if (barDrag) return;
        if (!dragSel) return;
        dragSel.moved = true;
        markBar(dragSel.key, dragSel.from, bar, { focus: false, deferEditors: true });
      };
      // The bar menu: mute a lane here, drop the kit, duplicate, build up, delete.
      box.oncontextmenu = (ev) => barMenu(ev, row.key, bar);
      // Double-click opens the notes, not the transport.
      //
      // It used to play from here, matching the timeline. But a bar of a TRACK is a
      // different thing to point at than a moment of the song: the timeline is where
      // you go to hear, and a lane's bar is where you go to look at what it plays. The
      // ruler above still plays from where you double-click, so nothing was lost —
      // and "open what I am pointing at" is what a double-click means everywhere else
      // on the desk.
      box.ondblclick = () => openNoteEditor(row.key, bar);
      bars.append(box);
    }
    // Expanded gain/VU control in the lower header line, below the name and beside M/S.
    // The thumb controls gain while the rail shows the live channel level.
    const gainSlider = document.createElement('input');
    gainSlider.type = 'range';
    gainSlider.className = 'arrgain';
    gainSlider.min = 0;
    gainSlider.max = 1;
    gainSlider.step = 0.002;
    gainSlider.title = `${displayLabel} level`;
    const curGain = mixFor(trackId).lanes?.[row.key]?.gain ?? 0;
    gainSlider.value = dbToPos(curGain);
    const gainWrap = document.createElement('span');
    gainWrap.className = 'arrgainwrap';
    const vu = document.createElement('span');
    vu.className = 'arrvumeter';
    vu.title = `${displayLabel} live level (smoothed RMS)`;
    vu.setAttribute('aria-hidden', 'true');
    const vuFill = document.createElement('i');
    const vuPeak = document.createElement('b');
    vu.append(vuFill, vuPeak);
    const gainReadout = document.createElement('span');
    gainReadout.className = 'arrgainreadout';
    const showGain = (db) => { gainReadout.textContent = `${db > 0 ? '+' : ''}${db.toFixed(1)}`; };
    showGain(curGain);
    gainSlider.addEventListener('pointerdown', () => {
      gainReadout.classList.add('show');
      showGain(posToDb(+gainSlider.value));
    });
    const hideGain = () => gainReadout.classList.remove('show');
    gainSlider.addEventListener('pointerup', hideGain);
    gainSlider.addEventListener('pointercancel', hideGain);
    gainSlider.addEventListener('lostpointercapture', hideGain);
    // Both handlers end the same way, because they are the same act: set the lane's
    // level, then let every control that shows it redraw. The only difference is that a
    // drag must not have its own slider written back to mid-drag.
    const setGain = (db, { except = null, tag } = {}) => {
      showGain(db);
      editMix((m) => { laneOf(m, row.key).gain = db; }, tag);
      Audio.mixer?.lane(row.key)?.setGain(db);
      syncLaneGain(row.key, { except });
    };
    gainSlider.addEventListener('input', () => {
      setGain(posToDb(+gainSlider.value), { except: gainSlider, tag: `gain:${row.key}` });
    });
    // Untagged, so the reset is its own undo step rather than being coalesced into the
    // drag before it — the same bargain the channel fader's reset makes.
    gainSlider.addEventListener('dblclick', () => setGain(0));
    gainWrap.append(vu, gainSlider, gainReadout);
    arrangementMeters.set(row.key, { meter: vu, fill: vuFill, peak: vuPeak,
      shown: 0, held: 0, heldAt: 0 });
    bottom.append(gainWrap);
    // Keep the two-line header self-contained so future lower-row controls can be
    // added beside M/S without moving the track identity or the bar grid.
    const main = document.createElement('div');
    main.className = 'arrrow-main';
    main.append(header, bars);
    el.append(main);
    grid.append(el);
    arrCells.push({ key: row.key, bars });
  });
  // Reapply selection after replacing the rows, without moving a viewport the user may
  // have scrolled by hand. Song load and channel selection explicitly reveal their row.
  syncArrangementLaneSelection();
  redrawSelection();            // the rows are new; the selection is not
  updateArrangementNoteScale();
  syncArrangementScroll();
}

/**
 * Hand the ruler the rows' own width, and keep the two scrolled together.
 *
 * A bar cell has a floor of twelve pixels — four of padding each side and four of gap —
 * so a long song wants more width than the window has, and the rows overflow. The ruler
 * has no such floor: left alone it divides the same song across whatever width it is
 * given, which is a SECOND pixels-per-bar over the same columns. The two agreed only
 * while the song was short enough for the rows to fit; past that they drifted apart by a
 * bar for every few, and on a 290-bar song bar 157 sat under the mark for 193.
 *
 * Measured rather than recomputed: whatever the rows actually came out as is the width
 * the ruler takes, so there is no second formula to fall out of step with the first.
 */
/**
 * Page the arrangement along when playback runs off the right edge.
 *
 * A CHUNK at a time, not a pixel at a time: a view that slides continuously under a
 * playhead pinned to the middle makes the bars the moving object and the song impossible
 * to read against. Jumping a screenful leaves the next stretch still, which is what you
 * are trying to look at, and it only happens when the playhead has actually left.
 *
 * A tenth of a screen of lead-in, so the playhead lands just inside the new view rather
 * than on its very edge with nothing in front of it.
 */
function followArrangementScroll(frac) {
  const grid = $('arrgrid');
  const upper = $('upperwork');
  if (!grid || upper?.dataset.arrscroll !== '1') return;
  const span = grid.scrollWidth - grid.clientWidth;
  if (span <= 0) return;
  const bars = grid.querySelector('.arrrow .arrbars');
  const width = bars ? bars.scrollWidth : grid.scrollWidth;
  // The playhead's x in the SCROLLER's coordinates, which start at the row's left edge —
  // so the pinned name column counts. Measuring from the first bar instead put the
  // playhead a column further left than it really was, and the view sat still while it
  // walked off the right-hand side.
  const inset = bars ? bars.offsetLeft : 0;
  const x = inset + Math.max(0, Math.min(1, frac)) * width;
  // And the names are painted OVER the bars they cover, so the visible span starts after
  // them: a playhead behind that edge is on screen and unreadable, which is off screen.
  const left = grid.scrollLeft + inset;
  const right = grid.scrollLeft + grid.clientWidth;
  // Behind the view as well as ahead of it: a loop that jumps back to the top should
  // take the window with it rather than leave you looking at the bars it just left.
  if (x >= left && x < right - 4) return;
  const lead = grid.clientWidth * 0.1;
  grid.scrollLeft = Math.max(0, Math.min(span, x - inset - lead));
}

function syncArrangementScroll() {
  const grid = $('arrgrid');
  const upper = $('upperwork');
  if (!grid || !upper) return;
  const bars = grid.querySelector('.arrrow .arrbars');
  const width = bars ? Math.round(bars.scrollWidth) : 0;
  // Only when the rows genuinely want more than they have. A song that fits keeps the
  // behaviour it always had: bars stretched across the window, no scrollbar to reach for.
  const scrolls = width > 0 && grid.scrollWidth > grid.clientWidth + 1;
  upper.dataset.arrscroll = scrolls ? '1' : '0';
  upper.style.setProperty('--arr-content-w', `${width}px`);
  if (!scrolls) upper.style.setProperty('--arr-scroll', '0px');
  else upper.style.setProperty('--arr-scroll', `${Math.round(grid.scrollLeft)}px`);
  if (grid.dataset.scrollBound === '1') return;
  grid.dataset.scrollBound = '1';
  grid.addEventListener('scroll', () => {
    upper.style.setProperty('--arr-scroll', `${Math.round(grid.scrollLeft)}px`);
  }, { passive: true });
}

/** Keep note marks readable as more bars share the same width. Five pixels is the
 * authored maximum; narrow bars scale down from their actual rendered width, and all
 * note languages consume the same variable so percussion and melodic marks agree. */
function updateArrangementNoteScale() {
  const arrange = $('arrange');
  const bar = arrange?.querySelector('.arrbar');
  if (!arrange || !bar) return;
  const width = bar.getBoundingClientRect().width;
  if (!width) return;
  const size = clamp(width * 0.12, 3, 5);
  arrange.style.setProperty('--arr-note-size', `${size.toFixed(2)}px`);
}

function stopArrangementEcho(cell) {
  const timer = arrEchoTimers.get(cell);
  if (timer != null) clearTimeout(timer);
  arrEchoTimers.delete(cell);
  arrEchoCells.delete(cell);
  cell.classList.remove('echoing');
}

/** Leave one selected-track mark behind briefly as a visual playback echo. */
function startArrangementEcho(cell) {
  if (!cell || noteVisualMode !== 'trail' || !noteAnimation) return;
  stopArrangementEcho(cell);
  cell.classList.remove('playing');
  // Restart the CSS fade if this mark was echoed again before its previous tail died.
  void cell.offsetWidth;
  cell.classList.add('echoing');
  arrEchoCells.add(cell);
  arrEchoTimers.set(cell, setTimeout(() => stopArrangementEcho(cell), ARR_ECHO_DURATION));
}

/** Remove the active playback cue and any fading echoes. */
function clearArrangementPlayback() {
  for (const cell of arrPlayingCells) cell.classList.remove('playing');
  for (const cell of arrEchoCells) cell.classList.remove('echoing');
  for (const timer of arrEchoTimers.values()) clearTimeout(timer);
  arrEchoCells.clear();
  arrEchoTimers.clear();
  arrPlayingCells = [];
  arrPlayingAt = null;
}

/**
 * Follow the heard transport position without rebuilding the arrangement. The note
 * cells are already the semantic surface; playback only changes the small set that the
 * current beat lands on. Keeping the same references avoids restarting a CSS flourish
 * on every animation frame.
 */
function followArrangementVisual(step) {
  const next = [];
  let at = null;
  if (step != null && track && arrCells.length) {
    const totalSteps = songShape().totalSteps;
    at = Math.max(0, Math.floor(step)) % Math.max(1, totalSteps);
    const bar = Math.floor(at / 16);
    const within = at % 16;
    // One drawn cell can stand for several sixteenths in a long song. `slot` is which
    // of them is sounding, and it is what the marks are matched against — the cell is
    // only the box they are drawn in.
    const perCell = 16 / arrCellsPerBar;
    const cellIndex = Math.floor(within / perCell);
    const slot = within - cellIndex * perCell;
    const selectedArrangementLane = selectedLane
      && arrCells.some((row) => row.key === selectedLane)
      ? selectedLane
      : null;
    for (const row of arrCells) {
      // A full-desk playback cue is useful when no track is selected. Once the
      // user chooses a lane, keep the animated accent on that lane so the rows
      // remain readable while the rest still show their static note language.
      if (selectedArrangementLane && row.key !== selectedArrangementLane) continue;
      const barEl = row.bars.children[bar];
      const cell = barEl?.querySelectorAll('.arrcell')[cellIndex];
      if (!cell) continue;
      if (!cell.classList.contains('note') && !cell.classList.contains('recording-note')) continue;
      // A cell whose attacks are all on other sixteenths is not playing yet. Cells
      // written by the recorder carry no map, so they light on the whole cell as before.
      const hits = cell.dataset.hits;
      if (hits && hits[slot] !== '1') continue;
      next.push(cell);
      for (const hit of cell.querySelectorAll(`.arrhit[data-slot="${slot}"]`)) next.push(hit);
      for (const dot of barEl.querySelectorAll(`.arrmicrodot[data-cell="${cellIndex}"][data-slot="${slot}"]`)) {
        next.push(dot);
      }
    }
  }
  const same = next.length === arrPlayingCells.length
    && next.every((cell, i) => cell === arrPlayingCells[i]);
  // The same marks on a NEW sixteenth are a second attack, not the first one still
  // ringing, so the step has to be part of the comparison as well as the set.
  if (same && at === arrPlayingAt) return;
  const nextSet = new Set(next);
  const rehit = next.some((cell) => arrPlayingCells.includes(cell));
  for (const cell of arrPlayingCells) {
    cell.classList.remove('playing');
    if (!nextSet.has(cell)) startArrangementEcho(cell);
  }
  for (const cell of arrEchoCells) {
    if (nextSet.has(cell)) stopArrangementEcho(cell);
  }
  // Removing and re-adding the class in one frame does not restart a CSS animation
  // on its own. Only pay for the reflow when a mark is actually struck twice running.
  if (rehit) void $('arrange').offsetWidth;
  for (const cell of next) cell.classList.add('playing');
  arrPlayingCells = next;
  arrPlayingAt = at;
}

/** Locate the visible arrangement cell that owns a recorded note's quantised step. */
function arrangementCellFor(lane, bar, step) {
  const row = arrCells.find((entry) => entry.key === lane);
  const barEl = row?.bars.children[bar];
  if (!barEl) return null;
  const cellIndex = arrCellsPerBar === 1 ? 0 : Math.floor(step / (16 / arrCellsPerBar));
  return barEl.querySelectorAll('.arrcell')[cellIndex] || null;
}

/**
 * Paint a newly recorded note immediately, without asking the desk to rebuild. The
 * recorder's beat flush can then keep doing its cheap live write; the final take redraw
 * replaces this provisional mark with the authoritative arrangement data.
 */
function markRecordedVisual(lane, bar, step, open) {
  const cell = arrangementCellFor(lane, bar, step);
  if (!cell) return;
  cell.classList.add('note', 'recording-note');
  cell.style.setProperty('--note-strength', '1');
  cell.style.setProperty('--note-tilt', `${(((bar * arrCellsPerBar + step) * 17) % 7) - 3}deg`);
  const barEl = cell.parentElement;
  barEl?.classList.add('has-notes');
  if (barEl && !barEl.style.background) {
    barEl.style.background = arrangementBarField(lane);
  }
  cell.classList.toggle('recording-note', open);
}

// Folded or not is remembered like the panel heights are, and for the same reason: it
// is a statement about this desk rather than about the mix, so the desk you come back
// to is the one you left.
const ARR_FOLD_KEY = 'mash-mixer-arr-folded';
function setArrangeCollapsed(on) {
  if ($('upperwork')) on = false;
  const arrange = $('arrange');
  const changed = arrange.classList.contains('collapsed') !== on;
  arrange.classList.toggle('collapsed', on);
  // Before the early return, so the resize edges always match the folds even when the
  // fold itself has not changed: there is nothing to drag the height of when the
  // arrangement is shut, and a handle for it says there is.
  syncPanelResizeEdges();
  if (!changed) return;
  // Only on a real change: the border drag calls this every frame, and a fold that has
  // not moved is not worth a write.
  localStorage.setItem(ARR_FOLD_KEY, on ? '1' : '0');
  $('arrfold').classList.toggle('folded', on);
  $('arrfold').title = on ? 'Show the arrangement' : 'Collapse the arrangement';
}

$('arrfold').onclick = () => {
  setArrangeCollapsed(!$('arrange').classList.contains('collapsed'));
  scheduleDeskFit(true);
};
setArrangeCollapsed($('upperwork') ? false : localStorage.getItem(ARR_FOLD_KEY) === '1');

// The mixer folds like the panels above and below it. The family switches stay in
// the header while it is folded — they are what you are about to unfold it for.
const MIXER_KEY = 'mash-mixer-rack-folded';
function setMixerFolded(on, refit = true) {
  if ($('lowerwork')) on = false;
  const changed = $('rackwrap').classList.contains('collapsed') !== on;
  $('rackwrap').classList.toggle('collapsed', on);
  $('mixhead').classList.toggle('folded', on);
  $('mixfold').classList.toggle('folded', on);
  $('mixfold').title = on ? 'Show the mixer' : 'Collapse the mixer';
  syncPanelResizeEdges();
  // Only on a real change — the Notes border drag unfolds the rack on every frame it
  // is dragged upwards, and each of those was a localStorage write.
  if (changed) localStorage.setItem(MIXER_KEY, on ? '1' : '0');
  if (refit) scheduleDeskFit(true);
}
$('mixfold').onclick = () => setMixerFolded(!$('rackwrap').classList.contains('collapsed'));
setMixerFolded($('lowerwork') ? false : localStorage.getItem(MIXER_KEY) === '1', false);

// ---- meters + transport readout --------------------------------------------
let peakSeen = 0;
// Meter ballistics. The bar rises instantly and falls at a rate you can read — a
// meter that tracks the signal exactly flickers and tells you nothing about a hit
// that has already gone. The peak line holds where the loudest moment was, which is
// the number you are actually mixing against.
const METER_FALL = 55;        // percent of the scale per second
const PEAK_HOLD = 1400;       // ms the line sits before it starts sliding down
const PEAK_FALL = 30;         // percent per second once it does
let meterAt = 0;

function updateArrangementMeter(readout, lin, now, dt) {
  const value = typeof lin === 'number' ? lin : 0;
  const db = 20 * Math.log10(Math.max(1e-6, value));
  const pos = clamp((db + 48) / 48 * 100, 0, 100);
  readout.shown = Math.max(pos, (readout.shown ?? 0) - METER_FALL * dt);
  readout.fill.style.width = `${readout.shown}%`;
  if (pos >= (readout.held ?? 0)) {
    readout.held = pos;
    readout.heldAt = now;
  } else if (now - (readout.heldAt || 0) > PEAK_HOLD) {
    readout.held = Math.max(readout.shown, readout.held - PEAK_FALL * dt);
  }
  readout.peak.style.left = `${readout.held || 0}%`;
  readout.peak.style.opacity = readout.held > 0.5 ? '1' : '0';
  readout.meter.classList.toggle('clip', value >= 1);
}

/**
 * Everything in `tick` below the transport is a PICTURE of the audio, and a picture
 * nobody is looking at is not worth a millisecond.
 *
 * Every frame this walks each meter, reads its level, writes two style properties per
 * channel, toggles a clip class, then moves the playhead, rewrites two clocks and asks
 * four grids to follow the step. On a twenty-lane song that is a lot of layout, sixty
 * times a second — and it is spent on a window whose owner is in another app, where the
 * process has already been demoted and there is barely enough machine left to render
 * the audio. Scrolling in some OTHER application was enough to put a hole in the song:
 * none of that work arrives here, it simply takes the attention the audio needed, and
 * the desk was busy drawing meters into a window nobody was watching.
 *
 * So when the window is not the one being attended to, the drawing stops and the
 * transport does not. `syncLoopAnchor` and `syncPendingSeek` are above this line because
 * they are not pictures — they arm loops and land seeks, and a seek that waits for you
 * to look back at the desk is a broken seek. The loop keeps its frame so it can start
 * drawing again the moment focus returns; nothing is stale afterwards, because every
 * value below is recomputed from the engine rather than accumulated.
 *
 * Focus rather than `document.hidden`, for the reason the scheduler's lookahead uses it
 * too (see `lookahead` in src/engine/audio.js): the window this matters for is sitting
 * in plain sight the whole time, which is exactly why `hidden` never fires.
 */
function tick() {
  const now = performance.now();
  const dt = meterAt ? Math.min(0.25, (now - meterAt) / 1000) : 0;
  meterAt = now;
  syncLoopAnchor();
  syncPendingSeek();
  if (typeof document !== 'undefined' && !document.hasFocus()) {
    requestAnimationFrame(tick);
    return;
  }
  // Same argument as focus, one step further: the full-screen visualiser is a
  // window where the desk is not merely unattended but not on screen at all, and
  // the preset painting over it wants every millisecond the meters were spending.
  if (visualiserOpen) {
    requestAnimationFrame(tick);
    return;
  }
  let spanAt = now;
  if (Audio.mixer) {
    const laneLevels = new Map();
    for (const mt of meters) {
      // One number for a mono meter, [L, R] for the master's pair. Everything below is
      // per-channel and reads the same either way; the clip light and the session peak
      // take the louder side, which is the side that clipped.
      const v = mt.master || mt.key === '__master' ? Audio.mixer.masterLevels()
        : mt.key.startsWith('__aux:') ? Audio.mixer.auxLevel(mt.key.slice(6))
        : Audio.mixer.lane(mt.key)?.level();
      const vals = Array.isArray(v) ? v : [v];
      let loudest = 0;
      // A strip that reads silence, has already fallen to the floor and holds no peak
      // has nothing left to animate: every assignment below would write back the value
      // already there. Skipping them is not an approximation — it is the same five
      // style writes per channel, declined. Worth declining because this loop is the
      // one per-frame cost that scales with how many LANES a song has, and the songs
      // that struggle are the ones carrying two dozen strips of which most are resting
      // at any moment. The falling case is deliberately excluded: a meter on its way
      // down still has frames to draw, and `shown > 0` keeps it in the loop until it
      // arrives. See `mixer-general-performance-plan.md`, priority 6.
      if (mt.chans.every((ch, i) => !(vals[i] > 0) && !(ch.shown > 0) && !(ch.held > 0))) {
        laneLevels.set(mt.key, 0);
        continue;
      }
      mt.chans.forEach((ch, i) => {
        const lin = typeof vals[i] === 'number' ? vals[i] : 0;
        if (lin > loudest) loudest = lin;
        // dB scale bottoming at -48 reads far better than linear for quiet lanes.
        const db = 20 * Math.log10(Math.max(1e-6, lin));
        const pos = clamp((db + 48) / 48 * 100, 0, 100);
        ch.shown = Math.max(pos, (ch.shown ?? 0) - METER_FALL * dt);
        if (mt.horizontal) ch.fill.style.width = `${ch.shown}%`;
        else ch.fill.style.height = `${ch.shown}%`;
        if (pos >= (ch.held ?? 0)) { ch.held = pos; ch.heldAt = now; }
        else if (now - (ch.heldAt || 0) > PEAK_HOLD) {
          ch.held = Math.max(ch.shown, ch.held - PEAK_FALL * dt);
        }
        if (mt.horizontal) ch.peak.style.left = `${ch.held || 0}%`;
        else ch.peak.style.bottom = `${ch.held || 0}%`;
        ch.peak.style.opacity = ch.held > 0.5 ? '1' : '0';
      });
      laneLevels.set(mt.key, loudest);
      mt.meter.classList.toggle('clip', loudest >= 1);
      if (mt.key === '__master' && loudest > peakSeen) peakSeen = loudest;
    }
    // Use the already-read channel level where the rack has a strip; only filtered
    // lanes need a second lookup, so every arrangement VU still follows the same
    // engine meter source without doubling normal visible-lane reads.
    for (const [key, readout] of arrangementMeters) {
      const lin = laneLevels.has(key) ? laneLevels.get(key) : Audio.mixer.lane(key)?.level();
      updateArrangementMeter(readout, lin, now, dt);
    }
    spanAt = frameSpan('meters', spanAt);
  }
  const beat = Audio.songBeat();
  if (beat != null && track) {
    const { spb, totalSteps, loopSecs } = songShape();
    const outputHeard = heardStepNow() ?? 0;
    const heardStep = heardStepNow() ?? 0;
    const sourceStep = sourceHeardStepNow() ?? heardStep;
    const frac = sourceStep / totalSteps;
    $('playhead').style.left = (frac * 100) + '%';
    $('tnow').textContent = `${fmtTime(outputHeard * spb)}/${fmtTime(loopSecs)}`;
    $('barnow').textContent = `${Math.floor(outputHeard / 16) + 1}/${totalSteps / 16}`;
    const visualStep = arrangementVisualStep(heardStep);
    followArrangementVisual(visualStep);
    followArrangementScroll(frac);
    if (rearrangeActive()) followArrangementVisual(arrangementVisualStep(sourceStep));
    spanAt = frameSpan('arrangement', spanAt);
    oskFollow(sourceStep);
    spanAt = frameSpan('keyboard', spanAt);
    stepSeq.follow(sourceStep);
    spanAt = frameSpan('stepseq', spanAt);
    pianoRoll.follow(sourceStep);
    spanAt = frameSpan('pianoroll', spanAt);
    kitRoll.follow(sourceStep);
    spanAt = frameSpan('kitroll', spanAt);
    recordFollow(heardStep);
    syncRearrangeProgress(outputHeard);
    spanAt = frameSpan('rearrange', spanAt);
  } else {
    followArrangementVisual(null);
    oskFollow(null);
    stepSeq.follow(null);
    pianoRoll.follow(null);
    kitRoll.follow(null);
    syncRearrangeProgress(null);
  }
  writeGridInfo();
  const peakText = peakSeen > 0
    ? `Master peak ${(20 * Math.log10(peakSeen)).toFixed(1)} dBFS${peakSeen >= 1 ? '  ** CLIPPING **' : ''}` : '';
  $('peakinfo').textContent = peakText;
  // The watchdog's verdict lives in its own FIXED footer slot, and it lingers: a
  // message that vanishes the instant the trouble passes is a message nobody finishes
  // reading — the desk glitches, you look down, and the evidence is already gone.
  // Live trouble shows at full strength; a cleared verdict stays for a while, dimmed
  // and saying so, then leaves.
  const nowMs = performance.now();
  if (health.text) { lastHealthText = health.text; lastHealthAt = nowMs; }
  const healthLive = !!health.text;
  const lingering = !healthLive && lastHealthText
    && nowMs - lastHealthAt < HEALTH_LINGER_MS;
  const ah = $('audiohealth');
  if (ah) {
    ah.textContent = healthLive ? health.text
      : lingering ? `${lastHealthText} · cleared` : '';
    ah.style.opacity = healthLive ? '1' : '0.55';
    ah.classList.toggle('trouble', healthLive);
  }
  requestAnimationFrame(tick);
}

/**
 * WHICH GRID THIS SONG RUNS ON, AND WHAT PUT IT THERE.
 *
 * The resolution is not something anyone sets. It is promoted by what you do — picking a
 * triplet snap, switching on a 1/32 arpeggiator, pasting a fine clip — and demoted again
 * on save when nothing needs it. That is the right behaviour, and the reason there is
 * deliberately no resolution dial; but it makes the cost invisible, and this is the line
 * that makes it visible again.
 *
 * The sting is in `_fineBars`. A SONG-WIDE reason — the bank's own grid, a track-level
 * 1/32 arp, a lane written wider than the flag — sets it to null, and then no bar may skip
 * a tick for the whole song. One arpeggiator on one channel is paid for by all sixty-five
 * bars. A per-bar reason leaves the set intact and only those bars pay, which is why the
 * two cases read differently below.
 *
 * Silent on an ordinary sixteenth song, which is nearly all of them: a status bar that
 * says "normal" all day teaches you to stop reading it.
 */
let gridInfoWas = null;
function writeGridInfo() {
  const el = $('gridinfo');
  if (!el) return;
  const res = Audio.transportResolution || 16;
  const reason = Audio._fineBarsReason || '';
  const bars = Audio._fineBars;
  let text = '';
  if (reason) {
    const why = /^native-\d+-step-bank$/.test(reason) ? "the song's own grid"
      : reason === 'track-level-1/32-arp' ? 'a 1/32 arp on a channel'
        : reason === 'a-lane-array-of-64-or-more' ? 'a lane written finer than the flag'
          : reason;
    text = `Grid ${res} — ${why}, every bar`;
  } else if (bars && bars.size) {
    text = `Grid ${res} — ${bars.size} bar${bars.size === 1 ? '' : 's'}`;
  } else if (res !== 16) {
    text = `Grid ${res}`;
  }
  // Written only on change. This runs every frame, and setting textContent on a node that
  // already says the right thing still costs a layout.
  if (text === gridInfoWas) return;
  gridInfoWas = text;
  el.textContent = text;
  el.title = text
    ? `${text}. The grid follows the music — a triplet snap or a 1/32 arp promotes it, and`
      + ' saving demotes it again when nothing needs it.'
    : 'The note grid this song is stored on, and what promoted it';
}

/**
 * The load readout — and what it may honestly claim.
 *
 * There is no way to ask a browser how much of the audio thread a graph is using.
 * Chrome's `AudioContext.renderCapacity` would answer exactly that and does not
 * exist (checked on Chrome 151); it is feature-detected below in case it ever
 * arrives. What CAN be measured is only whether the thread is currently FAILING:
 * `ctx.currentTime` against the wall clock reads 1.00 whether the graph uses five
 * percent of the core or ninety-five, and only moves once the audio is already
 * breaking up.
 *
 * That is a deadline, not a gauge, and showing it as one was the mistake this
 * replaces: a desk playing a two-lane sketch read "GOOD 1.00×", which looks like a
 * limit, and the ±1% jitter of measuring a clock with a timer tripped "NEAR LIMIT"
 * on songs that were not near anything.
 *
 * So the readout says nothing alarming while the audio is fine, and names the CAUSE
 * when it is not — which are two different causes needing two different answers:
 *
 *   · the AUDIO THREAD is behind — the graph costs more than this machine can
 *     render in realtime. That is the song, the layers, or the effects, and the
 *     answers are on the desk: mute or solo while you work, bypass an insert,
 *     simplify a dense layer's voice, or bounce it.
 *   · the MAIN THREAD stalled — the audio thread is keeping up but the scheduler
 *     that feeds it did not get its turn. That is the browser or the machine being
 *     busy (another app, a heavy panel, a bounce), and no change to the mix fixes it.
 *
 * The estimate stays, quietly, as what it always was: a rough sum of measured effect
 * costs, useful for "what would adding this cost" and honest about not counting
 * voices. It is never coloured, because an estimate that has never been wrong on
 * this machine is still not evidence about anyone else's.
 */
function updateCpu() {
  const mix = mixFor(trackId);
  let total = ENGINE_BASE_COST;
  const counts = [];
  for (const [key, L] of Object.entries(mix.lanes || {})) {
    for (const e of (L.effects || [])) {
      if (e.bypass) continue;
      const def = EFFECT_BY_ID[e.id];
      if (def) { total += def.cost || 0.1; counts.push(def.name); }
    }
  }
  for (const e of (mix.masterEffects || [])) {
    if (e.bypass) continue;
    const def = EFFECT_BY_ID[e.id];
    if (def) { total += def.cost || 0.1; counts.push(`${def.name} (master)`); }
  }
  if ((mix.lanes && Object.values(mix.lanes).some((L) => (L.send?.reverb ?? 0) > 0))) total += 0.73;
  // Voices are NOT in this number. `ENGINE_BASE_COST` is the engine's own measured
  // cost with its own hand-written voices in it, and a Tone voice replacing one costs
  // something else again — nobody has measured what. Rather than quietly under-report,
  // the readout says how many are running and admits the figure does not cover them.
  const voiced = Object.entries(VOICE_LANES)
    .filter(([, seam]) => VOICES[mix.voice?.[seam.voiceKey]] || mix.voiceParams?.[seam.voiceKey])
    .map(([lane]) => lane);
  const el = $('cpu');
  const clockMin = $('clockmin');
  const c = Audio.ctx;
  // The estimate is the resting state: a number, no verdict attached.
  const estimate = `~${total.toFixed(0)}%${voiced.length ? '+' : ''}`;
  // ...and a trouble state only when something has actually gone wrong for long
  // enough to be real. `audioBehind` and `uiStalled` are set by the watchdog, which
  // requires several consecutive bad seconds — see checkAudioHealth.
  const trouble = health.audioBehind ? 'AUDIO OVERLOADED'
    : health.audioStruggling ? 'AUDIO STRUGGLING'
      : health.uiStalled ? 'MACHINE BUSY' : '';
  // The verdict does NOT ride the CPU readout any more (Peter: a toolbar number that
  // turns into words and back is a readout you stop trusting). The toolbar keeps the
  // resting estimate; the words live in the footer's own fixed slot — see the
  // audiohealth line in the tick loop, which also keeps a cleared verdict visible for
  // a while instead of vanishing the instant the trouble passes.
  el.textContent = estimate;
  if (clockMin) {
    clockMin.textContent = Number.isFinite(health.songRatioMin)
      ? `${health.songRatioMin.toFixed(3)}×` : '—';
    clockMin.title = Number.isFinite(health.songRatioMin)
      ? `Lowest measured audio-clock rate since ${track?.title || 'this song'} was loaded: `
        + `${health.songRatioMin.toFixed(3)} seconds rendered per wall-clock second. `
        + 'Near 1.000× means the audio met its deadline; a sustained lower value means the mix was too heavy. '
        + 'A healthy 1.000× cannot distinguish a light song from one close to the limit.'
      : 'Starts measuring during playback. Near 1.000× means the audio met its deadline; '
        + 'it cannot distinguish a light song from one close to the limit.';
  }

  const heaviest = counts.length ? counts.slice(0, 4).join(', ') : 'none';
  const requestedLatency = latencyPreference === '0.1'
    ? '100 ms (Maximum safety)' : `${latencyPreference} (${latencyOption(latencyPreference).label})`;
  const audioSafety = `Audio safety: buffer ${latencyOption(activeLatencyPreference).label}`
    + (pendingLatencyPreference ? ` (pending ${latencyOption(pendingLatencyPreference).label})` : '')
    + `; requested ${requestedLatency}`
    + `; read-ahead ${Math.round((Audio.sequencerLookahead || AUDIO_LOOKAHEAD_DEFAULT) * 1000)} ms; `
    + reportedAudioLatency(c) + '.';
  const cache = Audio.noteCacheHealth?.();
  const cacheLine = cache?.enabled
    ? `\nNote cache: ${cache.buffers} buffers / ${(cache.bytes / (1024 * 1024)).toFixed(1)} MB; `
      + `${cache.queued} still to render, ${cache.rendering} rendering; ${cache.hits} hits, `
      + `${cache.misses} misses, ${cache.stale} stale discarded`
      // Preparation no longer pauses for playback — it trickles: one render per idle
      // slice, held only while the audio clock sits in the borderline band. See the
      // trickle notes above pumpCache in voices.js.
      + (cache.playbackActive ? '; preparation trickling during playback.' : '.') : '';
  el.title = (health.audioBehind || health.audioStruggling
    ? (health.audioBehind
      ? 'THE AUDIO THREAD CANNOT RENDER THIS MIX IN REALTIME on this machine'
      : 'THE AUDIO THREAD IS MISSING ITS DEADLINE — at the edge, and you may not have'
        + ' heard it yet')
      + ` (rendering ${health.ratio.toFixed(2)}s per second).\n`
      + 'The mix is the thing to change: mute or solo lanes while you work (a silenced'
      + ' lane costs nothing), bypass an insert, give a dense sixteenth-note layer a'
      + ' simpler voice, or bounce it.\n'
      + `Heaviest effects here: ${heaviest}.\n\n`
    : health.uiStalled
      ? 'THE AUDIO IS FINE BUT THE BROWSER IS BUSY: the scheduler that feeds it ran'
        + ' out of queued notes, which is another app, a heavy panel or a bounce'
        + ' taking the machine — not the mix. Increase Sequencer read-ahead if this'
        + ' happens repeatedly.\n\n'
      : '')
    + `Estimate: ~${total.toFixed(0)}% of one core — the engine (${ENGINE_BASE_COST}%) plus`
    + ` ${counts.length} active effect${counts.length === 1 ? '' : 's'}`
    + (counts.length ? `: ${counts.join(', ')}` : '')
    + '.\nAn ESTIMATE, not a measurement: effect costs were measured on one desktop and'
    + ' a phone will differ.'
    + (voiced.length ? ` It also counts no voices — ${voiced.length} lane${voiced.length === 1 ? '' : 's'}`
      + ` here play a synth preset (${voiced.join(', ')}), hence the +. A dense`
      + ' sixteenth-note layer on a library preset can cost more than every effect in'
      + ' the song put together.' : '')
    + '\n\nThere is no way to ask a browser how loaded the audio thread is, so this desk'
    + ' says nothing while the audio keeps up and tells you the cause when it does not.'
    + (health.dropouts ? `\n\n${health.dropouts} dropout${health.dropouts === 1 ? '' : 's'}`
      + ' since this song was loaded.' : '')
    + `\n${audioSafety}`
    + cacheLine
    + (health.audioBehind
      ? '\nMaximum safety may absorb brief output spikes, but sustained overload still'
        + ' requires muting, soloing, simplifying, or bouncing work.' : '');
  // Coloured only for measured trouble. An estimate never lights the lamp: it is a
  // guess about this machine, and a guess is not a reason to alarm anybody.
  // The lamp follows the verdict to its footer slot; the toolbar estimate stays a
  // plain number that never lights anything — it is a guess about one machine.
  $('audiohealth')?.classList.toggle('dirty', !!trouble);
}

// ---- audio health watchdog --------------------------------------------------
//
// Two failures this desk has actually had, both invisible until now:
//
//  * STARVATION. The graph costs more than the one core the audio thread gets, and
//    the clock falls behind the wall — `ctx.currentTime` advances 0.36s in a second
//    at the worst measured. Nothing in the UI said so; it sounded like mystery
//    glitches and read like a haunting. The watchdog measures the one number that
//    settles it (the same probe that settled it by hand) and puts it on the
//    transport while it is true.
//
//  * DEAD OUTPUT. Meters moving, mix silent, only a reload helps. The master meter
//    taps masterTrim BEFORE the master chain (see mixer.js) — so that state is,
//    precisely, signal alive at the trim and nothing after the chain. A stuck
//    DynamicsCompressor is the standing suspect (fed one NaN it holds it forever),
//    but the recovery below does not need the culprit's name: rebuild the master
//    chain from the mix, and if the output stays dead, cycle the context so the
//    browser opens a fresh output stream. Each step logs what it saw, so the day it
//    fires there is finally evidence instead of a symptom.
//
// One second between checks: cheap enough to run always, fast enough that the
// three-strike rule below reacts inside a bar or two.
const loopLogOpen = $('looplogopen');
const loopLogDialog = $('looplogdialog');
const loopLogClose = $('looplogclose');
const loopLogDone = $('looplogdone');
const loopLogCopy = $('looplogcopy');
const loopLogDownload = $('looplogdownload');
const loopLogClear = $('looplogclear');
const profileTrackLoadButton = $('profiletrackload');
const loopLogText = $('looplogtext');
const loopLogStatus = $('looplogstatus');
const perfDiagOpen = $('perfdiagopen');
const perfDiag = $('perfdiag');
const perfDiagHead = $('perfdiaghead');
const perfDiagClose = $('perfdiagclose');
const perfDiagDone = $('perfdiagdone');
const perfDiagClear = $('perfdiagclear');
const perfDiagPopout = $('perfdiagpopout');
const perfDiagState = $('perfdiagstate');
const perfDiagStatus = $('perfdiagstatus');
const perfDiagLog = $('perfdiaglog');
const perfDiagMetricEls = new Map(
  [...document.querySelectorAll('#perfdiagmetrics .perfmetric')]
    .map((el) => [el.dataset.perfmetric, el]),
);

const health = {
  text: '', lastWall: 0, lastCt: 0, deadRuns: 0,
  analyser: null, buf: null, longTask: 0,
  // Why silence was EXPECTED, last time it was. Logged once per spell rather than
  // every second, so a paused desk does not narrate itself.
  quietWhy: '',
  // What the readout is allowed to say, and the evidence behind it.
  //
  // `ratio` is how much audio the thread rendered per second of wall clock. It is a
  // DEADLINE, not a gauge — 1.00 whether the graph is nearly empty or nearly full —
  // so it may only ever raise an alarm, never reassure. Measuring a clock with a
  // timer wobbles by a percent or so either way, which is why `audioBehind` needs a
  // real shortfall sustained over several seconds rather than one dip.
  ratio: NaN, songRatioMin: Infinity, marginMin: null,
  // The last few (wall, clock) pairs, so a shortfall can be judged over half a second
  // without waiting a whole one to notice it — see checkAudioHealth's ring.
  samples: [],
  behindSince: 0, audioBehind: false, audioStruggling: false,
  uiStalled: false, uiStalledAt: 0,
  // Last dead-output cause, kept so a later recovery row says what recovered rather
  // than merely that something did. The event itself is persisted immediately below:
  // a dead output may prevent the next audible loop boundary from ever arriving.
  deadCause: '',
  recovering: false,
  freshRecoveries: 0,
  // The most recent control gesture, recorded before its click handler runs. When an
  // unwrapped surface stalls, this is the only useful name a Long Task can be given:
  // browsers report its duration but generally attribute it only to "self".
  lastAction: null,
  // Passes that began after the scheduler's queue had emptied — the count of times
  // the music actually had a hole in it. Reset when a song is loaded, so the number
  // is about the song in front of you.
  dropouts: 0,
};

function resetSongClockMinimum() {
  health.songRatioMin = Infinity;
  health.ratio = NaN;
  health.samples.length = 0;
  health.lastWall = 0;
  health.lastCt = 0;
  const readout = $('clockmin');
  if (readout) readout.textContent = '—';
}

// One aggregate window per audible sequencer lap. The engine tells us the exact
// audio time of a wrap; these fields retain the worst of the existing watchdog's
// four-per-second observations until that boundary reaches the speakers.
const loopHealthWindow = {
  ratioMin: Infinity, marginMin: Infinity, longTaskMax: 0,
  struggling: false, overloaded: false, machineBusy: false,
  // Scheduler WORK, drained per lap rather than per tick. Starvation says the queue
  // ran dry; this says what each pass cost and how much of it went on ticks between
  // the sixteenths. An optimisation is accepted or rejected on these, because a wall
  // time on this laptop drifts by more than the effect being measured.
  work: null,
  // Relief SHADOW: what the throttling machine would have done, had it been wired to
  // anything. Counted per lap so a row says "this lap would have spent 1.5s in relief"
  // rather than leaving the reader to diff timestamps.
  reliefMs: 0, reliefEnters: 0, reliefVerdict: '',
};
let loopLogRecords = [];
try {
  const stored = JSON.parse(localStorage.getItem(LOOP_LOG_KEY) || '[]');
  if (Array.isArray(stored)) loopLogRecords = stored.slice(-LOOP_LOG_LIMIT);
} catch { loopLogRecords = []; }
const loopLogSession = new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);
const loopLapCounts = new Map();
let lastLoggedDropouts = 0;

// The persisted loop CSV is deliberately sparse: it records loop boundaries and
// fault/recovery events, not a row every quarter second. This smaller session ring is
// the live window's readout. It is cheap to overwrite, never touches localStorage, and
// gives a developer the sequence immediately before a dropout without turning the
// diagnostics file into a telemetry firehose.
const PERF_DIAG_LIMIT = 240;
const PERF_DIAG_SAMPLE_MS = 1000;
let perfDiagRecords = [];
let perfDiagLastSampleAt = 0;
let perfDiagLastKey = '';
let perfDiagPopup = null;
const PERF_POS_KEY = 'mash-mixer-perfdiag-pos';

const LOOP_LOG_COLUMNS = [
  'time', 'session', 'song', 'lap', 'loopStart', 'loopEnd', 'recordType', 'status',
  'detail', 'audioState', 'preMasterPeak', 'postMasterPeak', 'deadRuns', 'recoveryTier',
  'stallSource', 'stallSourceMs',
  'clockMin', 'schedulerMarginMinMs', 'longTaskMaxMs', 'dropoutsDelta', 'dropoutsTotal',
  // Priority 0 telemetry — measurement only, no behaviour behind any of it yet.
  'schedTicks', 'schedFineTickPct', 'schedLaneReads', 'schedFineLaneReadPct',
  'schedLaneReadsPerTick', 'schedPreamblePerTick',
  // Which named section of the desk's animation frame spent the most, and how much —
  // the column that turns "a 340ms task ran" into something to go and read.
  'frameHotspot', 'frameHotspotMs',
  'reliefMs', 'reliefEnters', 'reliefVerdict', 'auxDuty',
  'bufferMode', 'latencyRequest', 'baseLatencyMs', 'outputLatencyMs', 'readAheadMs',
  // `cacheQueued` is the BACKLOG at the moment of the row — what the cache still owes.
  // Before the queuedTotal rename it silently carried the lifetime count instead, which
  // is why every row logged before 2026-08-17 has it equal to `cacheMisses`.
  'cacheEnabled', 'cacheBuffers', 'cacheMB', 'cacheQueued', 'cacheQueuedTotal',
  'cacheRendering', 'cachePlanCandidates', 'cachePlanSelected', 'cachePlanCompleted',
  'cachePlanPending', 'cachePlanSelectedMB', 'cachePlanBenefit',
  'cacheHits', 'cacheMisses', 'cacheStale', 'pools', 'poolSlots', 'retiredPools',
  'liveNotes', 'heldNative', 'cachedSources', 'mrdrLaneStages', 'mrdrChorusLegs',
  'mrdrTailEligible', 'mrdrTailCulled', 'mrdrTailSkipped', 'mrdrTailPotentialMs',
  'mrdrTailSavedMs', 'mrdrTailRatio', 'jsHeapMB',
  'operationDurationMs', 'operationBytes', 'operationSegments', 'heapBeforeMB', 'heapAfterMB',
  'profileTrack', 'profilePreset', 'profileBars', 'profileAudioSeconds',
  'profileFullMs', 'profileDryMs', 'profileLoadPct', 'profileFxDeltaMs',
];

// Declared above their first use rather than beside their helpers: resetLoopHealthWindow
// clears the duty accumulator, and a song can be loaded before this file finishes.
let reliefState = newReliefState();
const auxDuty = newAuxDuty();

function resetLoopHealthWindow() {
  loopHealthWindow.ratioMin = Infinity;
  loopHealthWindow.marginMin = Infinity;
  loopHealthWindow.longTaskMax = 0;
  loopHealthWindow.struggling = false;
  loopHealthWindow.overloaded = false;
  loopHealthWindow.machineBusy = false;
  loopHealthWindow.work = null;
  loopHealthWindow.reliefMs = 0;
  loopHealthWindow.reliefEnters = 0;
  loopHealthWindow.reliefVerdict = '';
  frameSpans.clear();
  auxDuty.clear();
  lastLoggedDropouts = health.dropouts;
}

// ---- priority 0: scheduler work, relief shadow, aux duty --------------------
//
// All three are measurement. Nothing below changes what is scheduled, what is drawn,
// or what the graph contains — the plan in work/local/mixer-general-performance-plan.md
// puts this phase first precisely so that the phases which DO change behaviour have a
// noise floor to be judged against. The accepted stress baseline is a pair of Clock
// minima 0.4% apart, and 0.4% is not a result until the spread of an unchanged run is
// known.

// ---- which part of the desk owned the animation frame -----------------------
//
// `longTaskMaxMs` says the main thread was blocked. It has never said BY WHAT, and
// `stallSource` only names a stall that a click was standing next to — so every
// periodic cost the desk pays lands in the CSV as "unattributed", 154 rows of it in
// one investigation. That is the difference between reading a diagnosis and spending
// an evening inferring one, and the answer was a DOM projection in a panel that no
// column mentioned.
//
// So the desk times its own frame. Spans are accumulated by name and the heaviest is
// written beside the long task it explains. Deliberately a running timestamp rather
// than a wrapper taking a callback: this is instrumentation on the one path that was
// already too expensive, and it should not allocate a closure per section per frame
// to say so. One `performance.now()` per boundary is the whole cost.
let frameSpans = new Map();
const frameSpan = (name, since) => {
  const now = performance.now();
  frameSpans.set(name, (frameSpans.get(name) || 0) + (now - since));
  return now;
};

/** The heaviest named section of the window, and what it spent. */
function frameHotspotFields() {
  let name = '';
  let ms = 0;
  for (const [key, spent] of frameSpans) if (spent > ms) { ms = spent; name = key; }
  return name ? { frameHotspot: name, frameHotspotMs: Math.round(ms) } : {};
}

/** Fold this tick's scheduler-work counters into the lap window. */
function accumulateSchedulerWork() {
  const w = Audio.takeSchedulerWork ? Audio.takeSchedulerWork() : null;
  if (!w || !w.ticks) return;
  const into = loopHealthWindow.work || (loopHealthWindow.work = {
    ticks: 0, fineTicks: 0, laneReads: 0, fineLaneReads: 0, notePlans: 0,
    fineNotePlans: 0, preambleMerges: 0, preambleTransposes: 0,
    preambleSilentSweeps: 0, preambleFrozenWalks: 0,
  });
  for (const key of Object.keys(into)) into[key] += w[key] || 0;
}

/** The scheduler-work columns for one lap row, as rates rather than raw totals. */
function schedulerWorkFields() {
  const w = loopHealthWindow.work;
  if (!w || !w.ticks) return {};
  const pct = (n) => Math.round(1000 * n / w.ticks) / 10;
  const preamble = w.preambleMerges + w.preambleTransposes
    + w.preambleSilentSweeps + w.preambleFrozenWalks;
  return {
    schedTicks: w.ticks,
    schedFineTickPct: pct(w.fineTicks),
    schedLaneReads: w.laneReads,
    // The number priority 1b is judged on: of every lane resolution the scheduler did,
    // how many happened on a tick between the sixteenths. If this is near zero on the
    // stress song, the lane predicate is not worth its risk.
    schedFineLaneReadPct: w.laneReads
      ? Math.round(1000 * w.fineLaneReads / w.laneReads) / 10 : 0,
    schedLaneReadsPerTick: Math.round(10 * w.laneReads / w.ticks) / 10,
    // The number priority 1a is judged on, and the one no lane predicate can reach:
    // work done resolving the BAR, before a single lane is looked at.
    schedPreamblePerTick: Math.round(10 * preamble / w.ticks) / 10,
  };
}

/**
 * Run the relief machine and record what it decided. It is not wired to any drawing.
 *
 * `longTaskMs` is passed in rather than read off `health`, because the watchdog zeroes
 * that field partway through its own pass and a shadow reading taken after the reset
 * would report a clean main thread on exactly the ticks that were not.
 */
function updateReliefShadow(wall, { dropouts, marginMin, longTaskMs, ratio }) {
  const { state, event, verdict } = reliefTransition(reliefState, {
    wall, playing, ratio, dropouts, marginMin, longTaskMs,
    struggling: health.audioStruggling, behind: health.audioBehind,
  });
  if (state.active && reliefState.active) {
    loopHealthWindow.reliefMs += HEALTH_TICK_MS;
  }
  if (verdict) loopHealthWindow.reliefVerdict = verdict;
  reliefState = state;
  if (!event) return;
  if (event.type === 'on') {
    loopHealthWindow.reliefEnters++;
    appendDiagnosticEvent('PERFORMANCE RELIEF ON (shadow)',
      `would throttle drawing: ${event.reason}`, {
        schedulerMarginMinMs: Number.isFinite(event.marginMin)
          ? Math.round(event.marginMin * 1000) : '',
        longTaskMaxMs: Math.round(event.longTaskMs || 0),
        dropoutsDelta: event.dropouts || 0,
        reliefVerdict: event.reason,
      });
  } else {
    appendDiagnosticEvent('PERFORMANCE RELIEF OFF (shadow)',
      `would restore drawing after ${Math.round(event.durationMs)}ms of ${event.reason}`,
      { reliefMs: Math.round(event.durationMs), reliefVerdict: event.reason });
  }
}

/**
 * Sample every aux return: connected, and is anything arriving at it?
 *
 * Both readings are already there — `aux(id).active` is the prune/wake state and the
 * send meter is on every aux input and already pulled — so this adds a map lookup and
 * a compare per aux, four times a second. See the go/no-go note in the plan: if these
 * columns come back near 100% fed on a dense mix, aux sleeping is not worth building.
 */
function accumulateAuxActivity(dtMs) {
  const mixer = Audio.mixer;
  if (!mixer || !playing) return;
  for (const def of mixer.auxes || []) {
    accumulateAuxDuty(auxDuty, def.id, {
      dtMs,
      connected: !!mixer.aux(def.id)?.active,
      level: mixer.auxLevel(def.id) || 0,
    });
  }
}

const csvCell = (value) => {
  if (value == null) return '';
  const s = String(value);
  return /[",\n]/.test(s) ? `"${s.replaceAll('"', '""')}"` : s;
};

function loopLogCsv() {
  return [LOOP_LOG_COLUMNS.join(','), ...loopLogRecords.map((record) =>
    LOOP_LOG_COLUMNS.map((key) => csvCell(record[key])).join(','))].join('\n');
}

// Mirror the log onto the disk of the machine the desk is running on.
//
// The CSV has always been downloadable, which is right for keeping one and wrong for
// READING one: the question a performance investigation asks is "what did the last two
// passes do", and it is usually asked by somebody who is not sitting at this browser.
// The dev server writes it to `work/local/mixer-diagnostics.csv`, where anything can
// read it without a download, a file picker or a paste.
//
// Debounced, because a lap row and a fault event can land within a frame of each other
// and the point is a file on disk, not a request per record. Fire-and-forget: this is a
// convenience on top of localStorage, which remains the log that actually persists, so a
// desk served from anywhere but `npm run mixer` simply gets a 404 and carries on. The
// failure is remembered rather than logged each time — a console warning four times a
// minute about a mirror nobody asked for is its own kind of noise.
let diagnosticsMirrorTimer = null;
let diagnosticsMirrorOff = false;
function mirrorDiagnosticsLog() {
  if (!DEV_USER || diagnosticsMirrorOff || diagnosticsMirrorTimer != null) return;
  diagnosticsMirrorTimer = setTimeout(async () => {
    diagnosticsMirrorTimer = null;
    try {
      const response = await fetch('/diagnostics-log', {
        method: 'POST',
        headers: { 'content-type': 'text/csv' },
        body: loopLogCsv(),
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
    } catch (error) {
      diagnosticsMirrorOff = true;
      console.log('[diagnostics] not mirroring to disk —'
        + ` this desk is not served by \`npm run mixer\` (${error.message})`);
    }
  }, 2000);
}

function persistLoopRecord(record) {
  loopLogRecords.push(record);
  if (loopLogRecords.length > LOOP_LOG_LIMIT) loopLogRecords.splice(0, loopLogRecords.length - LOOP_LOG_LIMIT);
  try { localStorage.setItem(LOOP_LOG_KEY, JSON.stringify(loopLogRecords)); } catch { /* UI still holds this session */ }
  refreshLoopLogUi();
  mirrorDiagnosticsLog();
}

function diagnosticRuntimeFields() {
  const cache = Audio.noteCacheHealth?.() || {};
  const runtime = Audio.voices?.runtimeHealth?.() || {};
  const ctx = Audio.ctx;
  const memory = performance.memory?.usedJSHeapSize;
  const plan = cache.plan || {};
  const tail = runtime.mrdrTail || {};
  return {
    bufferMode: latencyOption(activeLatencyPreference).label,
    latencyRequest: activeLatencyPreference,
    baseLatencyMs: ctx?.baseLatency == null ? '' : +(ctx.baseLatency * 1000).toFixed(2),
    outputLatencyMs: ctx?.outputLatency == null ? '' : +(ctx.outputLatency * 1000).toFixed(2),
    readAheadMs: Math.round((Audio.sequencerLookahead || AUDIO_LOOKAHEAD_DEFAULT) * 1000),
    cacheEnabled: !!cache.enabled, cacheBuffers: cache.buffers ?? 0,
    cacheMB: cache.bytes == null ? '' : +(cache.bytes / (1024 * 1024)).toFixed(2),
    cacheQueued: cache.queued ?? 0, cacheQueuedTotal: cache.queuedTotal ?? 0,
    cacheRendering: cache.rendering ?? 0,
    cachePlanCandidates: plan.candidates ?? 0, cachePlanSelected: plan.selected ?? 0,
    cachePlanCompleted: plan.completed ?? 0, cachePlanPending: plan.pending ?? 0,
    cachePlanSelectedMB: plan.selectedBytes == null
      ? '' : +(plan.selectedBytes / (1024 * 1024)).toFixed(2),
    cachePlanBenefit: plan.selectedBenefit == null ? '' : +Number(plan.selectedBenefit).toFixed(2),
    cacheHits: cache.hits ?? 0, cacheMisses: cache.misses ?? 0, cacheStale: cache.stale ?? 0,
    pools: runtime.pools ?? 0, poolSlots: runtime.poolSlots ?? 0,
    retiredPools: runtime.retiredPools ?? 0, liveNotes: runtime.liveNotes ?? 0,
    heldNative: runtime.heldNative ?? 0, cachedSources: runtime.cachedSources ?? 0,
    mrdrLaneStages: runtime.mrdrLaneStages ?? 0, mrdrChorusLegs: runtime.mrdrChorusLegs ?? 0,
    mrdrTailEligible: tail.eligible ?? 0, mrdrTailCulled: tail.culled ?? 0,
    mrdrTailSkipped: tail.skipped ?? 0,
    mrdrTailPotentialMs: tail.potentialSeconds == null ? '' : Math.round(tail.potentialSeconds * 1000),
    mrdrTailSavedMs: tail.savedSeconds == null ? '' : Math.round(tail.savedSeconds * 1000),
    mrdrTailRatio: tail.potentialRatio == null ? '' : +Number(tail.potentialRatio).toFixed(4),
    jsHeapMB: Number.isFinite(memory) ? +(memory / (1024 * 1024)).toFixed(1) : '',
  };
}

function perfDiagSnapshot() {
  const fields = diagnosticRuntimeFields();
  const scheduler = schedulerWorkFields();
  const hotspot = frameHotspotFields();
  const ratio = Number.isFinite(health.ratio) ? +health.ratio.toFixed(3) : null;
  const margin = Number.isFinite(health.marginMin) ? +(health.marginMin * 1000).toFixed(1) : null;
  const status = health.audioBehind ? 'AUDIO OVERLOADED'
    : health.audioStruggling ? 'AUDIO STRUGGLING'
      : health.uiStalled ? 'PLAYBACK INTERRUPTED'
        : playing ? (fields.cacheRendering ? 'CACHE RENDERING' : 'PLAYING') : 'STOPPED';
  return {
    ...fields, ...scheduler, ...hotspot, status, ratio, margin,
    longTask: Math.round(Math.max(health.longTask || 0, loopHealthWindow.longTaskMax || 0)),
    dropouts: health.dropouts || 0, audioState: Audio.ctx?.state || 'uninitialised',
    playing: !!playing, time: new Date().toISOString(),
  };
}

const perfNumber = (value, suffix = '') => value == null || value === '' || !Number.isFinite(Number(value))
  ? '—' : `${value}${suffix}`;

function perfDiagDetail(snapshot) {
  const clock = perfNumber(snapshot.ratio, 'x');
  const margin = perfNumber(snapshot.margin, ' ms');
  const cache = `cache q${snapshot.cacheQueued}/r${snapshot.cacheRendering}`
    + (snapshot.cachePlanCandidates ? ` · plan ${snapshot.cachePlanCompleted}/${snapshot.cachePlanSelected}` : '')
    + ` · hits ${snapshot.cacheHits || 0}/misses ${snapshot.cacheMisses || 0}`;
  const cpu = snapshot.frameHotspot
    ? ` · hot ${snapshot.frameHotspot} ${snapshot.frameHotspotMs || 0}ms`
    : '';
  return `clock ${clock} · margin ${margin} · ${cache} · dropouts ${snapshot.dropouts}${cpu}`;
}

function perfDiagPayload() {
  return {
    current: perfDiagCurrent,
    records: perfDiagRecords.slice(),
  };
}

let perfDiagCurrent = null;

function syncPerfDiagPopup() {
  const popup = perfDiagPopup;
  if (!popup || popup.closed) { perfDiagPopup = null; return; }
  try {
    const payload = perfDiagPayload();
    const state = popup.document.getElementById('mash-perf-state');
    const metrics = popup.document.getElementById('mash-perf-metrics');
    const log = popup.document.getElementById('mash-perf-log');
    if (!state || !metrics || !log) return;
    const current = payload.current || {};
    state.textContent = `${current.status || 'WAITING'} · ${current.time || ''}`;
    metrics.textContent = current.status ? [
      `AUDIO  ${current.status} · clock ${perfNumber(current.ratio, 'x')} · margin ${perfNumber(current.margin, ' ms')} · long task ${perfNumber(current.longTask, ' ms')} · dropouts ${current.dropouts} · ${current.frameHotspot ? `hot ${current.frameHotspot} ${current.frameHotspotMs || 0}ms` : 'no frame hotspot yet'}`,
      `CACHE  ${current.cacheEnabled ? 'on' : 'off'} · ${current.cacheBuffers} buffers · ${current.cacheMB || 0} MB · queue ${current.cacheQueued} · rendering ${current.cacheRendering} · plan ${current.cachePlanCompleted || 0}/${current.cachePlanSelected || 0} · hits/misses/stale ${current.cacheHits || 0}/${current.cacheMisses || 0}/${current.cacheStale || 0}`,
      `MRDR   ${current.mrdrLaneStages || 0} lane stages · ${current.mrdrChorusLegs || 0} wet legs · ${current.liveNotes || 0} live notes · ${current.cachedSources || 0} cached sources · tails ${current.mrdrTailCulled || 0} culled`,
      `OUTPUT ${current.audioState || '—'} · ${current.bufferMode || '—'} · base ${perfNumber(current.baseLatencyMs, ' ms')} · read-ahead ${perfNumber(current.readAheadMs, ' ms')} · heap ${perfNumber(current.jsHeapMB, ' MB')}`,
    ].join('\n') : 'Waiting for a sample…';
    log.textContent = payload.records.map((record) => {
      const time = record.time?.slice(11, 23) || '';
      return `${time} ${String(record.status || '').padEnd(22)} ${record.detail || ''}`;
    }).join('\n');
    log.scrollTop = log.scrollHeight;
  } catch {
    perfDiagPopup = null;
  }
}

function refreshPerfDiagUi() {
  if (!perfDiagOpen || !perfDiag) return;
  perfDiagOpen.hidden = !DEV_USER;
  if (!DEV_USER) return;
  const current = perfDiagCurrent || perfDiagSnapshot();
  const metricText = {
    audio: `${current.status || 'WAITING'}\nclock ${perfNumber(current.ratio, 'x')} · margin ${perfNumber(current.margin, ' ms')}\nlong task ${perfNumber(current.longTask, ' ms')} · dropouts ${current.dropouts || 0}\n${current.frameHotspot ? `hot ${current.frameHotspot} · ${current.frameHotspotMs || 0} ms` : 'no frame hotspot yet'}${current.schedTicks ? `\nscheduler ${current.schedTicks} ticks · fine ${current.schedFineTickPct || 0}% · lanes ${current.schedLaneReads || 0}` : ''}`,
    cache: `${current.cacheEnabled ? 'ON' : 'OFF'} · ${current.cacheBuffers || 0} buffers · ${current.cacheMB || 0} MB\nqueue ${current.cacheQueued || 0} · rendering ${current.cacheRendering || 0}\nplan ${current.cachePlanCompleted || 0}/${current.cachePlanSelected || 0} · pending ${current.cachePlanPending || 0}\nhits ${current.cacheHits || 0} · misses ${current.cacheMisses || 0} · stale ${current.cacheStale || 0}`,
    mrdr: `${current.mrdrLaneStages || 0} lane stages · ${current.mrdrChorusLegs || 0} wet legs\nlive ${current.liveNotes || 0} · cached ${current.cachedSources || 0}\ntails ${current.mrdrTailCulled || 0} culled · ${current.mrdrTailSkipped || 0} skipped`,
    browser: `${current.audioState || '—'} · ${current.bufferMode || '—'}\nbase ${perfNumber(current.baseLatencyMs, ' ms')} · read-ahead ${perfNumber(current.readAheadMs, ' ms')}\nheap ${perfNumber(current.jsHeapMB, ' MB')} · pools ${current.pools || 0}`,
  };
  for (const [key, el] of perfDiagMetricEls) {
    const p = el.querySelector('p');
    if (p) p.textContent = metricText[key] || '—';
    el.classList.toggle('bad', key === 'audio' && /OVERLOADED|STRUGGLING|INTERRUPTED/.test(current.status || ''));
  }
  if (perfDiagState) perfDiagState.textContent = current.status
    ? `${current.status} · ${current.time?.slice(11, 23) || ''}` : 'Waiting for playback';
  if (perfDiagStatus) perfDiagStatus.textContent = perfDiagRecords.length
    ? `${perfDiagRecords.length} live message${perfDiagRecords.length === 1 ? '' : 's'} · latest: ${perfDiagRecords.at(-1).detail}`
    : 'Open the song and press Play to begin live sampling.';
  if (perfDiagLog) {
    perfDiagLog.textContent = perfDiagRecords.map((record) => {
      const time = record.time?.slice(11, 23) || '';
      return `${time} ${String(record.status || '').padEnd(22)} ${record.detail || ''}`;
    }).join('\n');
    perfDiagLog.scrollTop = perfDiagLog.scrollHeight;
  }
  syncPerfDiagPopup();
}

function recordPerfDiag(kind, status, detail, snapshot = null) {
  if (!DEV_USER) return;
  const current = snapshot || perfDiagSnapshot();
  perfDiagCurrent = current;
  perfDiagRecords.push({
    time: current.time, kind, status, detail,
    ...current,
  });
  if (perfDiagRecords.length > PERF_DIAG_LIMIT) {
    perfDiagRecords.splice(0, perfDiagRecords.length - PERF_DIAG_LIMIT);
  }
  refreshPerfDiagUi();
}

function samplePerfDiag(force = false) {
  if (!DEV_USER || (!playing && !force)) return;
  const now = performance.now();
  if (!force && now - perfDiagLastSampleAt < PERF_DIAG_SAMPLE_MS) return;
  const snapshot = perfDiagSnapshot();
  const key = [snapshot.status, snapshot.ratio, snapshot.margin, snapshot.cacheQueued,
    snapshot.cacheRendering, snapshot.cachePlanPending, snapshot.dropouts,
    snapshot.mrdrLaneStages, snapshot.mrdrChorusLegs].join('|');
  // Keep the once-a-second heartbeat while playing, but also retain immediate samples
  // when a verdict or queue state changes so a dropout has a useful lead-in.
  if (!force && key === perfDiagLastKey && now - perfDiagLastSampleAt < PERF_DIAG_SAMPLE_MS * 2) return;
  perfDiagLastSampleAt = now;
  perfDiagLastKey = key;
  recordPerfDiag('sample', snapshot.status, perfDiagDetail(snapshot), snapshot);
}

/** Persist a fault or recovery now; unlike a lap row, this does not wait for audio. */
function appendDiagnosticEvent(status, detail, fields = {}) {
  if (!DEV_USER) return;
  recordPerfDiag('event', status, detail);
  persistLoopRecord({
    time: new Date().toISOString(), session: loopLogSession, song: trackId,
    lap: '', loopStart: Audio.loopStart ?? '', loopEnd: Audio.loopEnd ?? '',
    recordType: 'event', status, detail, audioState: Audio.ctx?.state || '',
    clockMin: Number.isFinite(health.ratio) ? health.ratio.toFixed(3) : '',
    schedulerMarginMinMs: health.marginMin == null ? '' : Math.round(health.marginMin * 1000),
    longTaskMaxMs: Math.round(health.longTask || 0), dropoutsDelta: fields.dropoutsDelta ?? 0,
    dropoutsTotal: health.dropouts, ...diagnosticRuntimeFields(),
    // Scheduler work and the frame's heaviest owner on EVENT rows too, not only on the
    // lap row. These columns used to appear only in `appendLoopLog`, which is a fine
    // place for them right up until the song is long enough to be interesting: a lap
    // row is written when a loop wraps, so a seven-minute import nobody plays to the
    // end emits event after event and never a single lap. Four sessions of diagnostics
    // on one such song carried 223 rows, every one of them an event, and every
    // scheduler-work column in all of them blank — the instrumentation was wired
    // correctly and reported nothing, which is the worst of both. Both helpers read a
    // window reset at the same points, so these are rates since the last lap or reset
    // rather than since the song began.
    ...schedulerWorkFields(), ...frameHotspotFields(), ...fields,
  });
}

function refreshLoopLogUi() {
  if (!loopLogOpen) return;
  loopLogOpen.hidden = !DEV_USER;
  loopLogOpen.textContent = `Loop diagnostics (${loopLogRecords.length})`;
  if (loopLogText) loopLogText.value = loopLogCsv();
  if (loopLogStatus) {
    const latest = loopLogRecords.at(-1);
    loopLogStatus.textContent = latest
      ? `${loopLogRecords.length} record${loopLogRecords.length === 1 ? '' : 's'} saved · latest: `
        + (latest.recordType === 'event'
          ? `${latest.song} · ${latest.status}`
          : `${latest.song} lap ${latest.lap} · ${latest.status} · clock ${latest.clockMin || 'n/a'}x`)
      : 'No diagnostics recorded yet. Start playback and let a song or locator loop wrap.';
  }
}

function diagnosticActionLabel(target) {
  const el = target?.closest?.('button, [role="button"], input, select, summary, [tabindex]');
  if (!el) return '';
  const named = el.getAttribute('aria-label') || el.getAttribute('title')
    || el.textContent?.replace(/\s+/g, ' ').trim() || el.id || el.tagName.toLowerCase();
  return named.slice(0, 100);
}

document.addEventListener('pointerdown', (event) => {
  const label = diagnosticActionLabel(event.target);
  if (label) health.lastAction = { label, at: performance.now() };
}, true);

function lastDiagnosticAction(within = 2000) {
  const action = health.lastAction;
  return action && performance.now() - action.at <= within ? action : null;
}

function appendLoopLog({ start, end }) {
  if (!DEV_USER || !playing || !Audio.ctx || !Audio.bank) return;
  const key = `${trackId}|${start}|${end}`;
  const lap = (loopLapCounts.get(key) || 0) + 1;
  loopLapCounts.set(key, lap);
  const ctx = Audio.ctx;
  const status = loopHealthWindow.overloaded ? 'AUDIO OVERLOADED'
    : loopHealthWindow.struggling ? 'AUDIO STRUGGLING'
      : loopHealthWindow.machineBusy ? 'MACHINE BUSY' : 'OK';
  const record = {
    time: new Date().toISOString(), session: loopLogSession, song: trackId, lap,
    loopStart: start, loopEnd: end, recordType: 'loop', status, detail: '',
    audioState: ctx.state, preMasterPeak: '', postMasterPeak: '', deadRuns: health.deadRuns,
    recoveryTier: '', stallSource: '', stallSourceMs: '',
    clockMin: Number.isFinite(loopHealthWindow.ratioMin) ? loopHealthWindow.ratioMin.toFixed(3) : '',
    schedulerMarginMinMs: Number.isFinite(loopHealthWindow.marginMin)
      ? Math.round(loopHealthWindow.marginMin * 1000) : '',
    longTaskMaxMs: Math.round(loopHealthWindow.longTaskMax),
    dropoutsDelta: Math.max(0, health.dropouts - lastLoggedDropouts), dropoutsTotal: health.dropouts,
    ...diagnosticRuntimeFields(),
    ...schedulerWorkFields(),
    reliefMs: loopHealthWindow.reliefMs, reliefEnters: loopHealthWindow.reliefEnters,
    reliefVerdict: loopHealthWindow.reliefVerdict, auxDuty: auxDutySummary(auxDuty),
  };
  const liveSnapshot = perfDiagSnapshot();
  recordPerfDiag('loop', status,
    `lap ${lap} · ${perfDiagDetail(liveSnapshot)}`, liveSnapshot);
  persistLoopRecord(record);
  resetLoopHealthWindow();
}

// The dead-output escalation, in TICKS of the watchdog — which runs four times a
// second, so these are 3, 6, 9 and 12 seconds. Named rather than written as numbers
// because they were literal tick counts once, and when the tick got four times
// faster every one of them silently became a quarter of the wait it was written to be.
const HEALTH_TICK_MS = 250;
const DEAD_TIER_1 = 3 * 1000 / HEALTH_TICK_MS;    // name the fault, rebuild what it names
const DEAD_TIER_2 = 6 * 1000 / HEALTH_TICK_MS;    // rebuild every chain the mix holds
const DEAD_TIER_3 = 9 * 1000 / HEALTH_TICK_MS;    // suspend/resume the context
const DEAD_TIER_4 = 12 * 1000 / HEALTH_TICK_MS;   // give up and say so
// How many (wall, clock) pairs the ratio ring holds — one second of observation at the
// tick above. A full ring is also what the latching per-song minimum waits for, so it
// never records the moment before the output device started; see checkAudioHealth.
const CLOCK_RING = 4;

// The longest main-thread task of the last watchdog window. The scheduler runs on
// that thread with a quarter-second queued in front of it, so this is the number
// that ATTRIBUTES a starved scheduler: "queue fell to 40ms" plus "a 210ms task just
// ran" is a diagnosis, where either alone is a shrug.
if (typeof PerformanceObserver !== 'undefined') {
  try {
    new PerformanceObserver((list) => {
      for (const e of list.getEntries()) {
        if (e.duration > health.longTask) health.longTask = e.duration;
      }
    }).observe({ entryTypes: ['longtask'] });
  } catch { /* longtask unsupported — the margin numbers still tell most of it */ }
}

// The muted-sink trick every meter in mixer.js uses, on the FINAL mix: a terminal
// analyser is not guaranteed to be pulled, and a health tap that only sometimes
// reads is worse than none.
function healthTap() {
  if (health.analyser || !Audio.ctx || !Audio.master) return;
  const ctx = Audio.ctx;
  const an = ctx.createAnalyser();
  an.fftSize = 256;
  const sink = ctx.createGain();
  sink.gain.value = 0;
  Audio.master.connect(an);
  an.connect(sink);
  sink.connect(ctx.destination);
  health.analyser = an;
  health.buf = new Float32Array(an.fftSize);
}

const diagnosticPeak = (value) => Number.isFinite(value) ? +value.toFixed(6) : String(value);

/**
 * A play press is a demand for sound, so it takes back every giving-up the desk did.
 *
 * THE RECOVERY LADDER LATCHES. Once two fresh contexts have failed, `freshRecoveries`
 * stays at two for the life of the page and the third tier stops replacing the context
 * at all — every later strike goes straight to "reload the desk". Nothing cleared that
 * but a reload, so one bad overload could leave the rest of a session silent even after
 * the mix that caused it was fixed. Pressing Play is the least ambiguous statement there
 * is that sound is wanted now, and it is a fresh gesture besides, which is exactly what
 * a suspended context needs. So it resets the strike count, hands the ladder its full
 * allowance back, and resumes a context that is not running.
 *
 * The clock ring is emptied with them. Its samples were taken across however long the
 * desk sat silent, and a stale pair reads as a stopped clock — the watchdog would trip
 * its own dead-output detector on the first tick after Play and repair a graph that had
 * only just been handed back.
 *
 * WHAT IT DOES NOT DO is rebuild anything here. `rebuildRealtimeContext` nulls `ctx`,
 * `bank` and `mixer` before restoring them from a snapshot, and setPlaying is about to
 * call `setBank` — starting one under the other races two writers into the same fields.
 * A desk that had already spent both rebuild tiers instead has its strike count parked
 * one tier short of the fresh context, so the ladder itself replaces the graph three
 * seconds later, on its own timeline, IF the silence is still there. If it is not, the
 * next quarter-second tick reads healthy and puts the count back to zero.
 */
function reviveAudioForPlay() {
  // A rebuild in flight owns the graph and will reset all of this when it settles.
  if (health.recovering) return;
  const wasDead = !!health.deadCause || health.deadRuns >= DEAD_TIER_1;
  // Have the cheap tiers already been tried and failed in this session? Only then is
  // skipping them right; a first fault still deserves a chain rebuild before a context.
  const rebuildsSpent = health.freshRecoveries > 0 || health.deadRuns >= DEAD_TIER_2;
  health.deadRuns = 0;
  health.freshRecoveries = 0;
  health.samples.length = 0;
  health.lastWall = 0;
  health.lastCt = 0;
  if (health.text.startsWith('AUDIO OUTPUT')) health.text = '';
  if (Audio.ctx && Audio.ctx.state !== 'running') Audio.resumeContext?.();
  if (!wasDead) return;
  if (rebuildsSpent) health.deadRuns = DEAD_TIER_2;
  appendDiagnosticEvent('AUDIO REVIVE ON PLAY',
    `Play cleared ${health.deadCause || 'a dead output'}`
    + (rebuildsSpent ? '; both rebuild tiers already spent, so the next strike replaces the context'
      : '; the repair ladder starts again from the first tier'), {
      deadRuns: health.deadRuns,
      recoveryTier: rebuildsSpent ? 'fresh context armed' : 'ladder rearmed',
    });
  health.deadCause = '';
}

function checkAudioHealth() {
  const ctx = Audio.ctx;
  if (!ctx || health.recovering) return;
  healthTap();
  const wall = performance.now();
  const ct = ctx.currentTime;
  const dt = (wall - health.lastWall) / 1000;
  const advance = ct - health.lastCt;
  const first = !health.lastWall;
  health.lastWall = wall;
  health.lastCt = ct;
  if (first || ctx.state !== 'running' || dt <= 0) {
    health.text = ''; health.ratio = NaN; health.samples.length = 0;
    health.behindSince = 0; health.audioBehind = false; health.audioStruggling = false;
    return;
  }
  // The ratio over the last HALF SECOND, from a ring of quarter-second samples.
  //
  // Sampled four times a second so trouble is noticed quickly, but judged over two
  // samples so it is not judged on one late timer: a quarter-second tick arriving
  // 15ms late reads as 0.94 all by itself, and reporting that as the audio thread
  // failing would put the desk back to crying wolf. Summing the pair before dividing
  // is what averages the jitter out rather than averaging two noisy ratios.
  health.samples.push({ dt, advance });
  if (health.samples.length > CLOCK_RING) health.samples.shift();
  const over = (n) => {
    const use = health.samples.slice(-n);
    // Fewer samples than asked for is not the average that was asked for. The ring is
    // emptied on every Play press and on every tick the context is not running, so
    // without this the sample straight after a clear was judged ALONE as if it were a
    // pair — the one late timer the pair exists to average out.
    if (use.length < n) return NaN;
    const w = use.reduce((s, x) => s + x.dt, 0);
    const a = use.reduce((s, x) => s + x.advance, 0);
    return w > 0 ? a / w : 1;
  };
  const ratio = over(2);
  health.ratio = ratio;
  // The MINIMUM is a different claim from the alarm above it, and needs a stricter
  // sample. It latches for the life of the song, so one bad reading is not a dip that
  // passes — it is what the toolbar says about this song until the next one loads.
  //
  // The reading it must not latch is the START of playback. `resume()` resolves and
  // `ctx.state` reads 'running' before the output device has produced its first render
  // quantum, so `currentTime` is still frozen for a tick or two while everything is
  // working exactly as intended — and that reads 0.000, which then sat in the toolbar
  // all session claiming the song had once rendered no audio at all.
  //
  // So the min waits for a FULL ring: one unbroken second of a running context since
  // the last clear. The alarm keeps the two-sample ratio, because it has its own
  // sustained-shortfall window and is allowed to be quick.
  if (playing && health.samples.length >= CLOCK_RING && Number.isFinite(ratio)) {
    health.songRatioMin = Math.min(health.songRatioMin, ratio);
    loopHealthWindow.ratioMin = Math.min(loopHealthWindow.ratioMin, ratio);
  }

  // What is coming OUT of the whole desk, against what is arriving at the trim.
  // `!isFinite`, not `isNaN`: an Infinity poisons a compressor exactly as hard and
  // is what an unstable filter reaches first on its way there.
  let post = 0;
  let nan = false;
  if (health.analyser) {
    health.analyser.getFloatTimeDomainData(health.buf);
    for (let i = 0; i < health.buf.length; i++) {
      const v = health.buf[i];
      if (!Number.isFinite(v)) { nan = true; break; }
      const a = Math.abs(v);
      if (a > post) post = a;
    }
  }
  const preLR = Audio.mixer ? Audio.mixer.masterLevels() : [0, 0];
  // Do not let `NaN || 0` launder a poisoned pre-master meter into silence. Its
  // non-finiteness is exactly the evidence needed to name an upstream fault.
  const preValues = [preLR[0] ?? 0, preLR[1] ?? 0];
  const preNonFinite = preValues.some((value) => !Number.isFinite(value));
  const pre = preNonFinite ? NaN : Math.max(preValues[0], preValues[1]);

  // Is output EXPECTED right now? Silence is the correct answer to a stopped
  // transport, a muted desk, a level at zero or a panic, and repairing the graph
  // because it is obeying you would be the watchdog inventing a fault. Only the
  // states that make silence WRONG accumulate strikes; the rest reset them and say
  // once, quietly, which one it was.
  const quiet = !playing ? 'transport stopped'
    : !Audio.bank ? 'no bank loaded'
      : Audio.muted ? 'desk muted'
        : Audio.panicked ? 'panicked'
          : !(Audio.levels.master > 1e-3) ? 'master level at zero'
            : !(Audio.levels.music > 1e-3) ? 'music level at zero'
              : '';
  if (quiet !== health.quietWhy) {
    if (quiet) console.log(`[audio-health] silence is expected (${quiet}) — not watching output`);
    health.quietWhy = quiet;
  }

  // Dead output: a non-finite sample anywhere in the final mix, real signal at the
  // trim with nothing downstream of it, or a clock that has stopped moving while the
  // context claims to run (the output stream itself has died). Three consecutive
  // seconds before acting, so a song change or one late timer cannot trip it.
  const clockStalled = ratio < 0.05;
  // The old detector could only see signal disappear BETWEEN the trim and output.
  // When an overloaded graph died upstream, both meters stayed at zero and looked
  // exactly like a rest. The sequencer now publishes short-lived evidence whenever a
  // real note has been scheduled; only sustained zero/zero during that evidence is a
  // fault. Sparse written rests never accumulate the three seconds of strikes.
  const expected = !!Audio.outputExpected?.();
  const silentWhileExpected = expected && pre < 1e-7 && post < 1e-7;
  const dead = !quiet && (nan || preNonFinite || clockStalled
    || (pre > 2e-3 && post < 1e-7) || silentWhileExpected);
  const previousDeadRuns = health.deadRuns;
  health.deadRuns = dead ? health.deadRuns + 1 : 0;
  if (!dead && !quiet && health.deadCause) {
    console.log('[audio-health] output recovered');
    appendDiagnosticEvent('AUDIO OUTPUT RECOVERED', `Recovered from ${health.deadCause}`, {
      preMasterPeak: diagnosticPeak(pre), postMasterPeak: diagnosticPeak(post),
      deadRuns: previousDeadRuns || '', recoveryTier: 'recovered',
    });
    health.deadCause = '';
    health.freshRecoveries = 0;
    health.text = '';
  }
  if (health.deadRuns === DEAD_TIER_1) {
    // WHERE is it poisoned? Every strip and every return already owns a meter, and a
    // meter reading non-finite is that chain saying so — so the answer costs a walk
    // of numbers that exist rather than a single new node. Whatever it names gets
    // rebuilt alongside the master, which is the difference between a repair aimed
    // at the fault and one aimed at the usual suspect.
    const poisoned = [];
    if (Audio.mixer) {
      for (const key of Audio.mixer.lanes) {
        const v = Audio.mixer.lane(key)?.level();
        if (!Number.isFinite(Array.isArray(v) ? v[0] : v)) poisoned.push(key);
      }
      for (const a of AUXES) {
        const v = Audio.mixer.auxLevel(a.id);
        if (!Number.isFinite(Array.isArray(v) ? v[0] : v)) poisoned.push(`__aux:${a.id}`);
      }
      if (!Number.isFinite(pre)) poisoned.push('__master(pre-chain)');
    }
    console.warn('[audio-health] output dead 3s:', JSON.stringify({
      nan, clockStalled, pre: +pre.toFixed(4), post, ratio: +ratio.toFixed(3),
      state: ctx.state, sr: ctx.sampleRate,
      poisoned: poisoned.length ? poisoned : 'none (fault is after the trim)',
    }));
    health.deadCause = nan || preNonFinite ? 'non-finite audio graph output'
      : clockStalled ? 'AudioContext clock stalled'
        : silentWhileExpected ? 'scheduled notes produced zero output'
          : 'pre-master signal present but final output silent';
    appendDiagnosticEvent('AUDIO OUTPUT DEAD', health.deadCause, {
      preMasterPeak: diagnosticPeak(pre), postMasterPeak: diagnosticPeak(post),
      deadRuns: health.deadRuns, recoveryTier: 'rebuild named chains',
    });
    // The filter writes that led here, newest last. An unstable biquad is the
    // standing suspect for where a non-finite sample comes from, and this is the
    // only record of what was asked of one — see VoiceRack.recentFilterWrites.
    const writes = Audio.voices?.recentFilterWrites?.();
    if (nan && writes?.length) {
      console.warn('[audio-health] recent filter automation (newest last):', writes);
    }
    if (!clockStalled && Audio.mixer) {
      console.warn(`[audio-health] rebuilding the master chain${poisoned.length
        ? ` and ${poisoned.length} named chain(s)` : ''} from the mix`);
      const bpm = deskTempo();
      Audio.mixer.setMasterEffects(effectsOf('__master'), bpm);
      const m = mixFor(trackId);
      for (const key of poisoned) {
        if (key.startsWith('__aux:')) Audio.mixer.setAuxEffects(key.slice(6), effectsOf(key), bpm);
        else if (m.lanes?.[key]?.effects?.length) Audio.mixer.lane(key)?.setEffects(m.lanes[key].effects, bpm);
      }
    }
    health.text = 'AUDIO OUTPUT DEAD — repairing';
  } else if (health.deadRuns === DEAD_TIER_2) {
    // The master chain was not it (or the NaN is stuck upstream of the trim — a
    // compressor on a LANE holds one exactly as hard). Rebuild every chain the mix
    // names, lanes and returns alike, from the same state the strips already show.
    if (Audio.mixer) {
      console.warn('[audio-health] still dead — rebuilding every lane and return chain');
      const bpm = deskTempo();
      const m = mixFor(trackId);
      for (const [key, L] of Object.entries(m.lanes || {})) {
        if (L.effects?.length) Audio.mixer.lane(key)?.setEffects(L.effects, bpm);
      }
      for (const a of AUXES) Audio.mixer.setAuxEffects(a.id, effectsOf(`__aux:${a.id}`), bpm);
    }
    appendDiagnosticEvent('AUDIO OUTPUT REPAIR', 'Still silent after first repair', {
      preMasterPeak: diagnosticPeak(pre), postMasterPeak: diagnosticPeak(post),
      deadRuns: health.deadRuns, recoveryTier: 'rebuild all effect chains',
    });
  } else if (health.deadRuns === DEAD_TIER_3) {
    // A poisoned node or dead platform stream can survive suspend/resume because that
    // is still the same graph on the same context. Replace it outright, rebuilding
    // from the engine's live draft while retaining its exact transport and loop.
    if (health.freshRecoveries >= 2) {
      console.error('[audio-health] two fresh contexts also stayed silent; reload required');
      health.text = 'AUDIO OUTPUT DEAD — reload the desk';
      appendDiagnosticEvent('AUDIO OUTPUT DEAD', 'Fresh-context recovery exhausted; reload required', {
        preMasterPeak: diagnosticPeak(pre), postMasterPeak: diagnosticPeak(post),
        deadRuns: health.deadRuns, recoveryTier: 'reload required',
      });
      health.deadRuns = DEAD_TIER_4;
    } else {
      health.recovering = true;
      health.freshRecoveries++;
      console.warn('[audio-health] still dead — rebuilding on a fresh AudioContext');
      appendDiagnosticEvent('AUDIO OUTPUT REPAIR', 'Still silent after graph rebuilds', {
        preMasterPeak: diagnosticPeak(pre), postMasterPeak: diagnosticPeak(post),
        deadRuns: health.deadRuns, recoveryTier: 'fresh context',
      });
      Audio.rebuildRealtimeContext().then((recovered) => {
        health.recovering = false;
        health.analyser = null;
        health.buf = null;
        health.lastWall = 0;
        health.lastCt = 0;
        health.samples.length = 0;
        health.deadRuns = 0;
        if (recovered) {
          health.text = 'AUDIO OUTPUT REBUILT — checking';
          appendDiagnosticEvent('AUDIO OUTPUT REPAIR', 'Graph rebuilt on a fresh AudioContext', {
            deadRuns: 0, recoveryTier: 'fresh context complete',
          });
        } else {
          health.text = 'AUDIO OUTPUT DEAD — reload the desk';
          appendDiagnosticEvent('AUDIO OUTPUT DEAD', 'Fresh AudioContext could not be created', {
            deadRuns: DEAD_TIER_4, recoveryTier: 'reload required',
          });
        }
      });
    }
  } else if (health.deadRuns === DEAD_TIER_4) {
    console.error('[audio-health] output did not come back; the desk needs a reload');
    health.text = 'AUDIO OUTPUT DEAD — reload the desk';
    appendDiagnosticEvent('AUDIO OUTPUT DEAD', 'Automatic recovery exhausted; reload required', {
      preMasterPeak: diagnosticPeak(pre), postMasterPeak: diagnosticPeak(post),
      deadRuns: health.deadRuns, recoveryTier: 'reload required',
    });
  }
  if (health.deadRuns >= DEAD_TIER_1) return;

  // The OTHER starvation: the audio thread is fine but the MAIN thread stalled long
  // enough that the sequencer's queue ran low — a UI build holding the floor. `late`
  // means the queue actually emptied and notes were scheduled into the past: an
  // audible hole, attributed to the stall that caused it. The known-heavy panels
  // prefill before they build (see Audio.prefill); this is what catches the ones
  // nobody has hooked yet, by name of cost if not of button.
  const sched = Audio.takeSchedulerHealth ? Audio.takeSchedulerHealth() : null;
  // Published for the CPU readout — see updateCpu. `Infinity` means no pass ran in
  // this window (a stopped desk), which is not a low-water mark.
  health.marginMin = sched && Number.isFinite(sched.marginMin) ? sched.marginMin : null;
  if (playing && health.marginMin != null) {
    loopHealthWindow.marginMin = Math.min(loopHealthWindow.marginMin, health.marginMin);
  }
  // MACHINE BUSY: the queue actually emptied, so the music had a hole in it. Only a
  // real emptying counts — a near miss is logged below but never shown, because the
  // desk saying "nearly" every time a panel opens is the noise this readout was
  // rewritten to stop. Held for eight seconds so a message nobody was looking at
  // when it happened is still there a moment later, then it clears itself.
  if (sched?.late > 0) {
    health.dropouts += sched.late;
    health.uiStalled = true;
    health.uiStalledAt = wall;
    loopHealthWindow.machineBusy = true;
    const heavy = lastHeavyBuild();
    const action = lastDiagnosticAction();
    appendDiagnosticEvent('PLAYBACK INTERRUPTED',
      `${sched.late} scheduler pass${sched.late === 1 ? '' : 'es'} ran after the queue emptied`, {
        schedulerMarginMinMs: Math.round(sched.marginMin * 1000),
        longTaskMaxMs: Math.round(health.longTask || 0), dropoutsDelta: sched.late,
        stallSource: heavy?.label || action?.label || 'unattributed',
        stallSourceMs: heavy ? Math.round(heavy.ms) : '',
      });
  } else if (health.uiStalled && wall - health.uiStalledAt > 8000) {
    health.uiStalled = false;
  }
  if (sched && Audio.bank && (sched.late > 0 || sched.marginMin < 0.08)) {
    // Name the build if one just ran. The observer knows a task was long; only the
    // call site knows it was the preset library — see lib/heavy-ui.js.
    const heavy = lastHeavyBuild();
    const action = lastDiagnosticAction();
    console.warn(`[audio-health] main-thread stall starved the scheduler: queue fell to `
      + `${Math.round(Math.max(0, sched.marginMin) * 1000)}ms`
      + (sched.late ? `, ${sched.late} pass(es) after it emptied — that was audible` : ' (near miss)')
      + (health.longTask ? `; longest task ${Math.round(health.longTask)}ms` : '')
      + (heavy ? `; after ${heavy.label} (${Math.round(heavy.ms)}ms)`
        : action ? `; after ${action.label} (surface not yet protected)`
          : '; no recent control gesture or heavy UI build — unattributed'));
  }
  if (playing) loopHealthWindow.longTaskMax = Math.max(loopHealthWindow.longTaskMax, health.longTask);
  // Kept before the reset below, for the shadow relief sample at the end of this pass:
  // read after it, every tick would report a main thread with nothing long on it.
  const longTaskMs = health.longTask || 0;
  health.longTask = 0;
  // Priority 0 accumulation. Draining the engine's work counters here rather than per
  // lap keeps them bounded on a desk that is never looped, and costs one method call
  // four times a second.
  accumulateSchedulerWork();
  accumulateAuxActivity(dt * 1000);

  // The audio thread falling behind, said in TWO stages — because by the time a
  // shortfall has lasted long enough to be certain, you have already heard it.
  //
  //   · STRUGGLING, after half a second. A heads-up while it is still recoverable:
  //     the thread is missing its deadline but the queue in front of it may still be
  //     covering the gap, so nothing may be audible yet. This is the moment to stop
  //     adding, and the whole reason the warning is staged.
  //   · OVERLOADED, after two seconds. Now it is not a blip.
  //
  // 0.95 is the line, and it is deliberately well clear of the noise: reading a clock
  // with a timer wobbles about a percent, while a graph that genuinely cannot keep up
  // does not hover — the dense song at its worst measured 0.365. Clearing needs 0.98,
  // so a reading that is merely wobbling around the line cannot flicker the readout.
  const STRUGGLE_MS = 500;
  const OVERLOAD_MS = 2000;
  // Two ways to be behind, because shortfalls come in two sizes and waiting for the
  // averaged one to notice a severe one is waiting for no reason. A SMALL shortfall
  // has to be averaged over half a second to be told apart from a late timer; a
  // SEVERE one cannot be a late timer at all — a quarter-second tick would have to
  // arrive 28ms late to read 0.90, and the graph that is genuinely over its budget
  // reads 0.4. So a single bad sample under 0.90 counts immediately.
  const instant = over(1);
  const behind = Audio.bank && (ratio < 0.95 || instant < 0.90);
  if (behind && !health.behindSince) health.behindSince = wall;
  if (!behind && ratio > 0.98) health.behindSince = 0;
  const behindFor = health.behindSince ? wall - health.behindSince : 0;

  const wasStruggling = health.audioStruggling;
  const wasBehind = health.audioBehind;
  health.audioStruggling = behindFor >= STRUGGLE_MS;
  health.audioBehind = behindFor >= OVERLOAD_MS;
  if (playing) {
    loopHealthWindow.struggling ||= health.audioStruggling;
    loopHealthWindow.overloaded ||= health.audioBehind;
  }
  if (health.audioStruggling && !wasStruggling) {
    console.warn(`[audio-health] audio thread missing its deadline: clock ${ratio.toFixed(3)}x`
      + ' — stop adding to this mix');
  }
  if (health.audioBehind && !wasBehind) {
    console.warn(`[audio-health] audio thread behind realtime for ${Math.round(behindFor)}ms:`
      + ` clock ${ratio.toFixed(3)}x — the graph costs more than one core on this machine`);
  }
  if ((wasBehind || wasStruggling) && !health.behindSince) {
    console.log('[audio-health] audio thread caught up');
  }
  // The transport line stays for genuine trouble only, and says the same thing the
  // readout does rather than a second vocabulary for it.
  // When the mix is too heavy AND the cache still has a backlog, the banner says the
  // way out instead of only naming the problem: pausing now catches up at full speed
  // (see setNoteCacheTransportRunning), so the honest instruction is to use it. Only
  // when there is nothing left to prepare does the message fall back to the plain
  // verdict — at that point the mix genuinely costs more than the machine has.
  const cacheBacklog = (Audio.noteCacheHealth?.()?.queued || 0);
  health.text = health.audioBehind
    ? (cacheBacklog > 25
      ? `OVERLOADED — pause to catch up (${cacheBacklog} left)`
      : 'OVERLOADED — mix too heavy')
    : health.audioStruggling ? 'STRUGGLING — near the limit'
      : health.uiStalled ? 'INTERRUPTED — browser busy' : '';
  // The readout shows what was just measured, so the thing that measures refreshes
  // it — nothing else calls `updateCpu` while a song merely plays. Only when the
  // VERDICT changes, though: this runs four times a second now, and rebuilding a
  // tooltip that nobody is hovering, sixty times a bar, is exactly the sort of idle
  // main-thread work the rest of this file exists to remove. The once-a-second pass
  // keeps the numbers inside the tooltip fresh for whoever is reading them.
  // SHADOW ONLY. This decides whether the desk would reduce its drawing, and logs the
  // decision; it does not reduce anything. Running it now — before any UI hangs off
  // it — is what makes the thresholds arguable from real sessions rather than from a
  // guess, and it is where the flapping risk near 0.95x will show up if it exists.
  updateReliefShadow(wall, {
    dropouts: sched?.late || 0, marginMin: health.marginMin, longTaskMs, ratio,
  });
  const verdict = `${health.audioBehind}|${health.audioStruggling}|${health.uiStalled}`;
  if (verdict !== health.lastVerdict || wall - (health.lastCpuAt || 0) > 1000) {
    health.lastVerdict = verdict;
    health.lastCpuAt = wall;
    updateCpu();
  }
  samplePerfDiag();
}
// Four times a second. The clock check is two subtractions and the analyser read is
// 256 floats; what it buys is noticing a shortfall in half a second instead of three,
// which is the difference between a warning and a post-mortem.
setInterval(checkAudioHealth, HEALTH_TICK_MS);

// scheduleStep announces a wrap when it queues the next pass, which can be up to a
// second before it is audible. Delay the snapshot to that AudioContext time; this is
// what makes each row describe the lap the listener just heard rather than part of
// the lap being scheduled in front of it.
// A queued Rearrange edit reaching the audio. The panel stops flashing here and only
// here: this fires when the scheduler actually consumed the recipe, which with a wide
// read-ahead can be a bar later than the arithmetic suggests. Anything self-timed
// would clear the mark while the old arrangement was still coming out of the speakers.
Audio.onRearrangementInstalled?.(() => {
  if (!rearrangePending) return;
  rearrangePending = false;
  renderRearrangeList();
  syncRearrangeProgress(Audio.rearrangement ? Audio.step : null);
});

Audio.onLoop?.((loop) => {
  // A recipe reaching its end with looping off STOPS there — at the moment the ear
  // reaches the boundary, not when the scheduler does: the scheduler runs a lookahead
  // ahead of the music, and parking the transport early would cut the final bar off.
  if (loop.rearrangement && !loop.looping && playing) {
    const wait = Math.max(0, (loop.when - Audio.ctx.currentTime) * 1000);
    setTimeout(() => {
      if (!playing || !rearrangeActive() || rearrangeLoopOn) return;
      setPlaying(false);
      toast('M8TRX finished');
    }, wait);
  }
  if (!DEV_USER || !Audio.ctx) return;
  const bank = Audio.bank;
  const song = trackId;
  const wait = Math.max(0, (loop.when - Audio.ctx.currentTime) * 1000);
  setTimeout(() => {
    if (!playing || Audio.bank !== bank || trackId !== song) return;
    appendLoopLog(loop);
  }, wait);
});

function placePerfDiag(x = null, y = null) {
  if (!perfDiag) return;
  if (x == null || y == null) {
    let saved = null;
    try { saved = JSON.parse(localStorage.getItem(PERF_POS_KEY) || 'null'); } catch { saved = null; }
    x = saved?.x ?? Math.max(8, (innerWidth - perfDiag.offsetWidth) / 2);
    y = saved?.y ?? 70;
  }
  const left = clamp(Number(x) || 8, 6, Math.max(6, innerWidth - perfDiag.offsetWidth - 6));
  const top = clamp(Number(y) || 8, 6, Math.max(6, innerHeight - perfDiag.offsetHeight - 6));
  perfDiag.style.left = `${left}px`;
  perfDiag.style.top = `${top}px`;
  perfDiag.style.transform = 'none';
  try { localStorage.setItem(PERF_POS_KEY, JSON.stringify({ x: left, y: top })); } catch { /* optional preference */ }
}

function openPerfDiag() {
  if (!DEV_USER || !perfDiag) return;
  perfDiag.hidden = false;
  perfDiagOpen?.setAttribute('aria-expanded', 'true');
  placePerfDiag();
  samplePerfDiag(true);
  perfDiagClose?.focus();
}

function closePerfDiag() {
  if (!perfDiag) return;
  perfDiag.hidden = true;
  perfDiagOpen?.setAttribute('aria-expanded', 'false');
  perfDiagOpen?.focus();
}

// The panel is intentionally not modal: a developer can drag it out of the way while
// moving faders, and the song continues under it. Buttons in the title bar are excluded
// so a click on Clear/Pop out never starts a move gesture.
perfDiagHead?.addEventListener('pointerdown', (event) => {
  if (perfDiag?.hidden || event.target.closest('button')) return;
  event.preventDefault();
  const rect = perfDiag.getBoundingClientRect();
  const dx = event.clientX - rect.left;
  const dy = event.clientY - rect.top;
  const move = (next) => placePerfDiag(next.clientX - dx, next.clientY - dy);
  const stop = () => {
    perfDiagHead.classList.remove('dragging');
    perfDiagHead.removeEventListener('pointermove', move);
  };
  perfDiagHead.classList.add('dragging');
  try { perfDiagHead.setPointerCapture(event.pointerId); } catch { /* synthetic pointer */ }
  perfDiagHead.addEventListener('pointermove', move);
  perfDiagHead.addEventListener('pointerup', stop, { once: true });
  perfDiagHead.addEventListener('pointercancel', stop, { once: true });
});

function openPerfDiagPopup() {
  if (!DEV_USER) return;
  const popup = window.open('', 'mash-mixer-performance',
    'popup=yes,width=900,height=680,resizable=yes,scrollbars=yes');
  if (!popup) { toast('Pop-out blocked — the in-page log is still available'); return; }
  perfDiagPopup = popup;
  popup.document.open();
  popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>MASHENSTEIN live performance</title><style>
    :root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;padding:16px;background:#151820;color:#e8ebf2;font:12px/1.45 ui-monospace,monospace}
    h1{margin:0 0 4px;color:#50d0ba;font:600 15px/1.2 ui-sans-serif,system-ui;letter-spacing:.08em}
    #mash-perf-state{color:#a4acbb;font-size:10px}#mash-perf-metrics{margin:14px 0 10px;padding:10px;border:1px solid #303746;border-radius:6px;white-space:pre-wrap}
    #mash-perf-log{margin:0;padding:10px;min-height:500px;max-height:calc(100vh - 100px);overflow:auto;border:1px solid #303746;border-radius:6px;background:#0e1117;white-space:pre-wrap}
  </style></head><body><h1>LIVE PERFORMANCE</h1><div id="mash-perf-state">Waiting for playback</div><pre id="mash-perf-metrics">Waiting for a sample…</pre><pre id="mash-perf-log" tabindex="0"></pre></body></html>`);
  popup.document.close();
  popup.addEventListener('beforeunload', () => { if (perfDiagPopup === popup) perfDiagPopup = null; }, { once: true });
  popup.focus();
  syncPerfDiagPopup();
}

perfDiagOpen?.addEventListener('click', () => { closeMenu(); openPerfDiag(); });
perfDiagClose?.addEventListener('click', closePerfDiag);
perfDiagDone?.addEventListener('click', closePerfDiag);
perfDiagClear?.addEventListener('click', () => {
  perfDiagRecords = [];
  perfDiagCurrent = null;
  perfDiagLastKey = '';
  refreshPerfDiagUi();
  toast('Live performance log cleared');
});
perfDiagPopout?.addEventListener('click', openPerfDiagPopup);
addEventListener('keydown', (event) => {
  if (event.key !== 'Escape' || perfDiag?.hidden) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  closePerfDiag();
}, true);
addEventListener('resize', () => {
  if (!perfDiag?.hidden) placePerfDiag(perfDiag.offsetLeft, perfDiag.offsetTop);
});
refreshPerfDiagUi();

function openLoopLog() {
  refreshLoopLogUi();
  if (typeof loopLogDialog.showModal === 'function') loopLogDialog.showModal();
  else loopLogDialog.setAttribute('open', '');
  loopLogText?.focus();
}

function closeLoopLog() {
  if (loopLogDialog.open && typeof loopLogDialog.close === 'function') loopLogDialog.close();
  else loopLogDialog.removeAttribute('open');
  loopLogOpen?.focus();
}

if (loopLogOpen) loopLogOpen.onclick = openLoopLog;
if (loopLogClose) loopLogClose.onclick = closeLoopLog;
if (loopLogDone) loopLogDone.onclick = closeLoopLog;
if (loopLogCopy) loopLogCopy.onclick = async () => {
  const csv = loopLogCsv();
  try {
    await navigator.clipboard.writeText(csv);
    toast('Loop diagnostics copied');
  } catch {
    loopLogText.value = csv;
    loopLogText.select();
    toast('Log selected — copy it with your keyboard');
  }
};
if (loopLogDownload) loopLogDownload.onclick = () => {
  saveBlob(`mashenstein-loop-diagnostics-${loopLogSession}.csv`,
    new Blob([loopLogCsv()], { type: 'text/csv;charset=utf-8' }));
};
if (loopLogClear) loopLogClear.onclick = () => {
  loopLogRecords = [];
  loopLapCounts.clear();
  try { localStorage.removeItem(LOOP_LOG_KEY); } catch { /* nothing else to clear */ }
  resetLoopHealthWindow();
  refreshLoopLogUi();
  toast('Loop diagnostics cleared');
};
if (profileTrackLoadButton) profileTrackLoadButton.onclick = () => void profileTrackLoad();
refreshLoopLogUi();

/**
 * Where the work stands against the file. Not a badge in the header any more: the
 * desk is for mixing, and a mix that is not in src/data/mix.js yet is not an alarm —
 * drafts are kept in localStorage, so the only thing at stake is whether the game has
 * heard it. So it is a dot on the drawer that holds Save, and the item inside says it
 * in words, naming the song it would write.
 */
function updateStatus() {
  updateCpu();
  const d = isDirty(trackId);
  // A library preset carrying unsaved edits is a change to the game that Save song
  // will not write — it belongs to voices.js, and only the panel's own Save puts it
  // there. So it lights the same lamp and says which sounds it means: the alternative
  // is a desk that looks saved while an hour of sound design is one reload from gone.
  const owed = [...dirtyLibraryVoices].map((id) => VOICES[id]?.label || id);
  $('navbtn').classList.toggle('unsaved', d || owed.length > 0);
  $('navbtn').title = [
    d ? `${track.title} has changes that are not in its song file yet` : '',
    owed.length ? `Unsaved preset edits: ${owed.join(', ')} — these live in the library,`
      + ' so Save song does not write them. Use the editor’s own Save.' : '',
  ].filter(Boolean).join('\n') || 'Open songs and file actions';
  // The label does not name the song — the menu is headed "this song", and an
  // imported title like CHECKOUT-PROMENADE-GARY-BRIGHT-ORGAN-DANCE-MIX would set the
  // width of the whole drawer. The name is in the tooltip, where it costs nothing.
  const save = $('save');
  const writable = track?.writable !== false;
  // Which of the three halves this press would write, named rather than implied. A save
  // that says only "Save song" is a save you have to remember the state of the desk to
  // predict, and the mix half is the one that quietly eats a level when you guess wrong.
  const halves = [
    draft[trackId] != null && mixChanged(draft[trackId], saved[trackId]) ? 'the mix' : null,
    arrDirty(trackId) ? 'the arrangement' : null,
    variantDirty(trackId) ? 'the cabinet screen' : null,
  ].filter(Boolean);
  // On the deployed desk a save is a copy in this browser, not a file, and the button
  // has to say which of the two it is — "Saved" against a mix that is one cleared
  // browser from gone is the one reading nobody should have to guess at.
  save.textContent = !writable ? 'Read-only MIDI import'
    : STATIC ? (d ? 'Save my mix' : 'Saved — matches your copy')
      : d ? 'Save song' : 'Saved — matches the file';
  save.disabled = !writable || !d;
  save.title = !writable ? 'This legacy MIDI import has no desk-owned file section to save'
    : STATIC ? (d ? `Keep ${halves.join(' and ')} as your copy of this song, in this browser only`
      : `${track.title} matches the copy you saved in this browser`)
      : d ? `Write ${halves.join(' and ')} into src/data/songs/${trackId}.js`
      + (cabOnDesk[trackId] ? `\n\nWARNING: the desk is showing the "${cabOnDesk[trackId]}" cabinet`
        + ' mix, not the level mix. Capture it back to the cabinet screen first.' : '')
      : `${track.title} already matches its file`;
  // Save As, and it is offered on everything with a bank — including a read-only MIDI
  // import, where it is the only way to keep an edit at all, and including a copy of a
  // copy, which is just the next snapshot. Nothing is written but the new file, so
  // there is no song this button could put wrong and nothing to guard it against.
  const copyButton = $('savecopy');
  if (copyButton) {
    copyButton.hidden = !track?.bank;
    copyButton.title = track?.bank
      ? `Keep ${track.title} exactly as the desk has it now — music, mix, arrangement and`
        + ` cabinet screen — as a song of its own under a new name.`
        + (STATIC ? ' Kept in this browser.' : ' Written into src/data/imported, listed under'
          + ` Saved copies. ${track.title} is not written, and nothing in the game changes.`)
      : '';
  }
  // Saving an alternate needs a server to write the file and a bank to copy, so it is
  // offered on the game's own songs and on alternates of them — not on scratch songs,
  // where the saved song already IS yours and Save writes it.
  const altButton = $('savealt');
  if (altButton) {
    // `writable` is the guard that matters: a legacy MIDI import has no desk-owned
    // file section, so it could be forked and then never promoted back — an alternate
    // of a song that can never become the song is a dead end wearing a live button.
    const can = !STATIC && !!track?.bank && track.writable !== false
      && (!isDeskSong(track) || track.group === 'alternate');
    altButton.hidden = !can;
    altButton.textContent = 'Save as alternate…';
    altButton.title = can
      ? `Keep what is on the desk now as a named alternate — its own file in`
        + ` src/data/imported, listed under Alternate Game Songs. ${track.title} is not written.`
      : '';
  }
  // The one button that writes a file other than the one on the desk. It names the
  // song it would write, always, and it is only ever on an alternate.
  const promote = $('promotealt');
  if (promote) {
    const parent = track?.alternateOf ? resolveTrack(track.alternateOf) : null;
    promote.hidden = STATIC || !parent;
    if (parent) {
      promote.textContent = `Save over ${parent.title}…`;
      promote.title = `Make this alternate the song: writes it into`
        + ` src/data/songs/${track.alternateOf}.js. The version it replaces is kept,`
        + ' so you can go back to it.';
    }
  }
  const deleteButton = $('deletesong');
  if (deleteButton) {
    const scratch = isDeskSong(track) && track?.writable === true;
    deleteButton.hidden = !scratch;
    deleteButton.title = scratch
      ? (STATIC ? `Remove ${track.title} from this browser`
        : `Permanently remove ${track.title} from src/data/imported and discard its desk history`)
      : 'Only scratch songs created in this desk can be deleted';
  }
  // Only a song that SHIPPED has an original to go back to. One you made here has no
  // other version of itself anywhere — Delete is the button for that.
  const original = $('resetoriginal');
  if (original) original.hidden = !STATIC || !SHIPPED_SONG_IDS.has(trackId);
  // A game song has two ways back and a user needs one. "Back to the original mix" is
  // the whole of it — the shipped song, whatever they have done to it since — and next
  // to that, a Discard that only reaches their own last save is a second undo with a
  // subtler meaning than anybody wants to work out. On their own songs it stays: there
  // the saved copy IS the song, and going back to it is the ordinary thing to want.
  const revertButton = $('revert');
  if (revertButton) revertButton.hidden = !DEV_USER && !isDeskSong(track);
}

// The drawer is the one project-level surface. The song browser is rendered on every
// open so imported and newly-created scratch songs appear without a page reload.
function resetDrawerSections() {
  document.querySelectorAll('#navdrawer .drawersection[data-drawer-section]').forEach((section) => {
    section.classList.remove('collapsed');
    section.querySelector('.drawersectiontoggle')?.setAttribute('aria-expanded', 'true');
  });
}

document.querySelectorAll('#navdrawer .drawersectiontoggle').forEach((toggle) => {
  toggle.onclick = (ev) => {
    ev.stopPropagation();
    const section = toggle.closest('.drawersection');
    const collapsed = section.classList.toggle('collapsed');
    toggle.setAttribute('aria-expanded', String(!collapsed));
  };
});

function openDrawer() {
  const drawer = $('navdrawer');
  if (drawer.classList.contains('show')) { closeMenu(); return; }
  closeMenu();
  resetDrawerSections();
  $('songsearch').value = '';
  renderSongBrowser();
  syncFreezeExportButton();
  drawer.classList.add('show');
  $('drawerbackdrop').classList.add('show');
  drawer.setAttribute('aria-hidden', 'false');
  $('drawerbackdrop').setAttribute('aria-hidden', 'false');
  $('navbtn').setAttribute('aria-expanded', 'true');
  // Nothing to type into when the search box is off, and focusing a hidden field is a
  // keyboard that answers nowhere.
  if (!STATIC) requestAnimationFrame(() => $('songsearch').focus());
}

$('navbtn').onclick = (ev) => { ev.stopPropagation(); openDrawer(); };
$('drawerclose').onclick = closeMenu;
$('drawerbackdrop').onclick = closeMenu;
addEventListener('keydown', (ev) => {
  if (ev.key === 'Escape' && $('navdrawer').classList.contains('show')) {
    // Stopped as well as handled, and immediately: Escape is the desk's panic, and that
    // handler listens on this same window. Closing the drawer you just opened is not a
    // reason to cut the sound as well.
    ev.preventDefault();
    ev.stopImmediatePropagation();
    closeMenu();
  }
});
$('navdrawer').addEventListener('click', (ev) => {
  const button = ev.target.closest('button');
  if (!button || button.id === 'navbtn' || button.id === 'newsong') return;
  // Keep font and playhead controls live while the drawer is open; action buttons
  // leave the drawer before opening a modal, render job, or file chooser.
  if (!['save', 'savecopy', 'savealt', 'promotealt',
    'revert', 'importtracks', 'history', 'resetsong', 'deletesong', 'renderwav', 'auditionwav', 'midi',
    'importmidi', 'exportfreezes', 'importfreezes', 'exportjson', 'voicelibbtn',
    'applytocab', 'auditioncab', 'clearcab', 'loadcab'].includes(button.id)) return;
  closeMenu();
});

// ---- typeface --------------------------------------------------------------
// A desk you stare at for hours may as well be set in something you like. Only
// fonts actually on this machine are offered: a list of names that quietly fall
// back to the same default is a list of one font wearing ten labels.
const FONTS = [
  ['System mono', 'ui-monospace, SFMono-Regular, Menlo, monospace'],
  ['SF Mono', '"SF Mono", ui-monospace, monospace'],
  ['Menlo', 'Menlo, monospace'],
  ['Monaco', 'Monaco, monospace'],
  ['JetBrains Mono', '"JetBrains Mono", monospace'],
  ['IBM Plex Mono', '"IBM Plex Mono", monospace'],
  ['Fira Code', '"Fira Code", monospace'],
  ['Source Code Pro', '"Source Code Pro", monospace'],
  ['Iosevka', 'Iosevka, monospace'],
  ['Avenir Next', '"Avenir Next", sans-serif'],
  ['Helvetica Neue', '"Helvetica Neue", sans-serif'],
  ['Futura', 'Futura, sans-serif'],
  ['Optima', 'Optima, sans-serif'],
];

/**
 * Is this family really installed? document.fonts.check answers yes for names it
 * has never heard of, so this measures instead: a string set in the family and in a
 * generic comes out the same width only when the family fell back to the generic.
 */
const fontProbe = document.createElement('canvas').getContext('2d');
function fontInstalled(name) {
  const probe = 'mmmMMMwwWWiil1@%#';
  for (const generic of ['monospace', 'serif']) {
    fontProbe.font = `72px ${generic}`;
    const base = fontProbe.measureText(probe).width;
    fontProbe.font = `72px "${name}", ${generic}`;
    if (Math.abs(fontProbe.measureText(probe).width - base) > 0.5) return true;
  }
  return false;
}

const FONT_KEY = 'mash-mixer-font';
const fontSel = $('font');
for (const [name, stack] of FONTS) {
  if (name !== 'System mono' && !fontInstalled(name.replace(/"/g, ''))) continue;
  const o = document.createElement('option');
  o.value = stack; o.textContent = name;
  fontSel.append(o);
}
const savedFont = localStorage.getItem(FONT_KEY);
if (savedFont && [...fontSel.options].some((o) => o.value === savedFont)) fontSel.value = savedFont;
const applyFont = () => {
  document.documentElement.style.setProperty('--font', fontSel.value);
  localStorage.setItem(FONT_KEY, fontSel.value);
  // Row heights move with the typeface, so the strips, the rack's floor and the
  // panel's reserved height all have to be measured again.
  requestAnimationFrame(() => { forgetStripMetrics(); reserveDevices(); fitStrips(); });
};
applyFont();
fontSel.onchange = () => { applyFont(); toast(`Set in ${fontSel.selectedOptions[0].textContent}`); };

// Colour is a desk preference, not part of a song. Keep it next to the typeface
// picker so a long listening session can change its atmosphere without touching
// any arrangement or mix data.
const THEMES = [
  ['default', 'Midnight'],
  ['amber', 'Amber CRT'],
  ['ocean', 'Ocean Terminal'],
  ['plum', 'Plum Night'],
  ['light', 'Light Paper'],
  ['midday', 'Midday'],
  ['dawn', 'Dawn'],
  ['dusk', 'Dusk'],
  ['oscar', 'Oscar'],
];
const THEME_KEY = 'mash-mixer-theme';
const themeSel = $('theme');
for (const [id, label] of THEMES) {
  const option = document.createElement('option');
  option.value = id; option.textContent = label;
  themeSel.append(option);
}
const savedTheme = localStorage.getItem(THEME_KEY);
if (savedTheme && THEMES.some(([id]) => id === savedTheme)) themeSel.value = savedTheme;
const applyTheme = () => {
  const id = themeSel.value;
  document.documentElement.toggleAttribute('data-mixer-theme', id !== 'default');
  if (id !== 'default') document.documentElement.dataset.mixerTheme = id;
  localStorage.setItem(THEME_KEY, id);
  // Anything that has to know whether it is drawing on paper or on slate reads this,
  // and it can only be read after the attribute is on the element.
  measureSurface();
};
const refreshThemeColours = () => {
  if (!track) return;
  // Track colours are inline because the same lane colour is shared by the rack,
  // arrangement, piano roll and step grid. Rebuild those views after a theme switch
  // so the inline values follow the new finite palette immediately.
  buildRack();
  buildArrangement();
};
applyTheme();
themeSel.onchange = () => {
  applyTheme();
  refreshThemeColours();
  toast(`Set ${themeSel.selectedOptions[0].textContent} theme`);
};

// The arrangement's note language is a desk preference beside Theme. It is deliberately
// not part of a song: changing how a pattern is seen must never dirty or rewrite music.
const noteVisualSel = $('notevisual');
for (const [id, label] of NOTE_VISUALS) {
  const option = document.createElement('option');
  option.value = id; option.textContent = label;
  noteVisualSel.append(option);
}
noteVisualSel.value = noteVisualMode;
const noteAnimationInput = $('noteanimation');
noteAnimationInput.checked = noteAnimation;

function applyNoteVisualPreferences({ render = true } = {}) {
  const arrange = $('arrange');
  if (arrange) {
    arrange.dataset.noteVisual = noteVisualMode;
    arrange.dataset.noteAnimation = noteAnimation ? 'on' : 'off';
  }
  localStorage.setItem(NOTE_VISUAL_KEY, noteVisualMode);
  localStorage.setItem(NOTE_ANIMATION_KEY, noteAnimation ? 'on' : 'off');
  if (render && track) buildArrangement();
}

applyNoteVisualPreferences({ render: false });
noteVisualSel.onchange = () => {
  noteVisualMode = noteVisualSel.value;
  applyNoteVisualPreferences();
  toast(`Showing ${noteVisualSel.selectedOptions[0].textContent}`);
};
noteAnimationInput.onchange = () => {
  noteAnimation = noteAnimationInput.checked;
  applyNoteVisualPreferences({ render: false });
  toast(noteAnimation ? 'Note playback accents on' : 'Note playback accents off');
};

// Audio safety is a desk preference, not part of a song. The output-buffer choice is
// a construction hint and therefore needs a reload once the live context exists;
// read-ahead is only a scheduler margin and can move while the song plays.
audioLatencySel = $('audiolatency');
audioAheadSel = $('audioahead');
audioSettingsStatus = $('audiosettingsstatus');
audioSettingsSummary = $('audiosettingssummary');
const audioSettingsOpen = $('audiosettingsopen');
const audioSettingsDialog = $('audiosettingsdialog');
const audioSettingsClose = $('audiosettingsclose');
const audioSettingsCancel = $('audiosettingscancel');
const audioSettingsApply = $('audiosettingsapply');
const noteCacheToggle = $('notecachetoggle');
audioLatencySel.value = latencyPreference;
audioAheadSel.value = String(readAheadPreference);

function updateAudioSettingsDraft() {
  audioLatencySel.value = normalizeLatency(audioLatencySel.value);
  audioAheadSel.value = String(normalizeLookahead(audioAheadSel.value));
  audioSettingsDirty = normalizeLatency(audioLatencySel.value) !== latencyPreference
    || normalizeLookahead(audioAheadSel.value) !== readAheadPreference;
  audioSettingsApply.disabled = !audioSettingsDirty;
  syncAudioSettingsStatus();
}

function discardAudioSettingsDraft() {
  audioLatencySel.value = latencyPreference;
  audioAheadSel.value = String(readAheadPreference);
  audioSettingsDirty = false;
  audioSettingsApply.disabled = true;
  syncAudioSettingsStatus();
}

function closeAudioSettings({ discard = true } = {}) {
  if (discard) discardAudioSettingsDraft();
  if (audioSettingsDialog.open && typeof audioSettingsDialog.close === 'function') {
    audioSettingsDialog.close();
  } else {
    audioSettingsDialog.removeAttribute('open');
    audioSettingsOpen.setAttribute('aria-expanded', 'false');
    audioSettingsOpen.focus();
  }
}

function openAudioSettings() {
  if (audioSettingsDialog.open) return;
  discardAudioSettingsDraft();
  audioSettingsOpen.setAttribute('aria-expanded', 'true');
  if (typeof audioSettingsDialog.showModal === 'function') audioSettingsDialog.showModal();
  else audioSettingsDialog.setAttribute('open', '');
  audioLatencySel.focus();
}

audioSettingsOpen.onclick = openAudioSettings;
audioSettingsClose.onclick = closeAudioSettings;
audioSettingsCancel.onclick = closeAudioSettings;
audioSettingsDialog.addEventListener('close', () => {
  discardAudioSettingsDraft();
  audioSettingsOpen.setAttribute('aria-expanded', 'false');
  audioSettingsOpen.focus();
});
// The desk's global Escape shortcut is PANIC. A native dialog owns Escape while it
// is open, so close this settings surface without stopping the song.
addEventListener('keydown', (event) => {
  if ((!audioSettingsDialog.open && !loopLogDialog?.open) || event.key !== 'Escape') return;
  event.preventDefault();
  event.stopImmediatePropagation();
  if (audioSettingsDialog.open) closeAudioSettings();
  else closeLoopLog();
}, true);

function applyAudioSettings() {
  const nextLatency = normalizeLatency(audioLatencySel.value);
  const nextAhead = normalizeLookahead(audioAheadSel.value);
  const latencyChanged = nextLatency !== latencyPreference;
  const aheadChanged = nextAhead !== readAheadPreference;
  if (!latencyChanged && !aheadChanged) {
    closeAudioSettings();
    return;
  }

  // Commit both desk preferences from one Apply action. Read-ahead can take effect
  // immediately; an output-buffer change still needs a new AudioContext, so it is
  // recorded as pending until the user chooses Reload now or Later.
  if (aheadChanged) {
    readAheadPreference = nextAhead;
    localStorage.setItem(LOOKAHEAD_KEY, String(nextAhead));
    Audio.setSequencerLookahead(nextAhead);
  }
  audioSettingsDirty = false;
  audioSettingsApply.disabled = true;

  if (!latencyChanged) {
    syncAudioSettingsStatus();
    closeAudioSettings({ discard: false });
    toast('Audio settings applied');
    return;
  }

  const option = latencyOption(nextLatency);
  latencyPreference = nextLatency;
  localStorage.setItem(LATENCY_KEY, nextLatency);
  // A context cannot be reconfigured after construction. Before that point the
  // choice is safe to apply immediately; normally the Mixer has already created its
  // context by the time a user can open this dialog.
  if (!Audio.ctx) {
    activeLatencyPreference = nextLatency;
    pendingLatencyPreference = null;
    Audio.setLatencyHint(option.hint);
    syncAudioSettingsStatus();
    closeAudioSettings({ discard: false });
    toast('Audio settings applied');
    return;
  }
  if (nextLatency === activeLatencyPreference) {
    pendingLatencyPreference = null;
    syncAudioSettingsStatus();
    closeAudioSettings({ discard: false });
    toast('Audio settings applied');
    return;
  }
  pendingLatencyPreference = nextLatency;
  syncAudioSettingsStatus();
  closeAudioSettings({ discard: false });
  ask('Reload audio buffer?',
    `${option.label} will be used when the Mixer creates its next AudioContext. `
    + (aheadChanged ? `Sequencer read-ahead is now ${Math.round(nextAhead * 1000)} ms. ` : '')
    + 'Reloading preserves your saved song and arrangement drafts. Unsaved library '
    + 'preset edits may still trigger the browser’s normal reload warning.',
    'Reload now').then((reload) => {
      if (reload) {
        location.reload();
      } else {
        toast(`${option.label} will apply the next time the Mixer reloads`, 5000);
      }
      syncAudioSettingsStatus();
    });
}

audioLatencySel.onchange = updateAudioSettingsDraft;
audioAheadSel.onchange = updateAudioSettingsDraft;
audioSettingsApply.onclick = applyAudioSettings;
updateAudioSettingsDraft();

function syncNoteCacheToggle() {
  if (!noteCacheToggle) return;
  noteCacheToggle.hidden = !DEV_USER;
  noteCacheToggle.textContent = `Note cache: ${noteCacheEnabled ? 'On' : 'Off'}`;
  noteCacheToggle.setAttribute('aria-pressed', String(noteCacheEnabled));
}

if (noteCacheToggle) {
  noteCacheToggle.onclick = () => {
    noteCacheEnabled = !noteCacheEnabled;
    localStorage.setItem(NOTE_CACHE_KEY, noteCacheEnabled ? '1' : '0');
    Audio.setNoteCache(noteCacheEnabled);
    syncNoteCacheToggle();
    toast(noteCacheEnabled
      ? 'Note cache on — preparation starts cold'
      : 'Note cache off — using live synths');
  };
}
syncNoteCacheToggle();

// How far behind the graph the speakers actually are, beyond what the browser owns
// up to. songBeat() subtracts ctx.outputLatency already; Bluetooth, an interface
// with its own buffer, or a device that simply reports zero are what this is for.
// Remembered per machine, because that is what it is a property of.
// About three frames: the attack ramp on a note plus the trip from a rAF callback to
// the glass. Set by eye against a kick, and it is a default rather than a constant —
// a different screen or a different device wants a different number.
const PH_KEY = 'mash-mixer-playhead-ms';
// The roll and arrangement line were still a little behind the audible attack on the
// current desk/browser combination. Keep this as a modest screen lead; an explicit
// stored calibration still wins below, and [ / ] remain available for other displays.
const PH_DEFAULT = 70;
const storedPh = localStorage.getItem(PH_KEY);
let phOffset = storedPh == null || storedPh === '' ? PH_DEFAULT : (Number(storedPh) || 0);
const phInput = $('phoffset');
phInput.value = String(phOffset);

function setPhOffset(ms) {
  phOffset = clamp(Math.round(ms), -300, 300);
  phInput.value = String(phOffset);
  localStorage.setItem(PH_KEY, String(phOffset));
}
phInput.oninput = () => {
  // An empty box is someone part-way through typing a number, not a request for
  // zero. Storing 0 there quietly parks the line fifty milliseconds behind the
  // music with nothing on screen to say why — and it is remembered, so it stays
  // wrong across reloads.
  if (phInput.value.trim() === '') return;
  setPhOffset(Number(phInput.value) || 0);
};
phInput.onblur = () => { phInput.value = String(phOffset); };

// Tempo you can drag — half speed to hear what a reverb is really doing, or up ten to
// check the kick still fits, and then KEEP it if it was right.
//
// It used to be audition-only, on the reasoning that the bpm belongs to the song
// rather than to its mix and a desk should not quietly rewrite the composition. The
// first half of that is true and the conclusion was wrong: a tempo you drag and lose
// is a decision the desk cannot make. It is saved on the ARRANGEMENT instead, which
// is exactly the seam that already exists for this — the song stays written at the
// tempo it was written at, and the arrangement says what it is played at, the same way
// `order` overrides the bank's own order. So the drag is an ordinary song edit: ⌘Z
// undoes it, the dot on the hamburger notices it, Save writes it, the game plays it,
// and deleting the entry puts the composed tempo back.
//
// Click the readout to do exactly that.
const deskTempo = () => arrFor(trackId)?.bpm ?? track?.bank?.bpm ?? 120;
/** The tempo the song is WRITTEN at — what the arrangement's tempo is measured against. */
const composedTempo = () => track?.bank?.bpm ?? 120;
function showTempo() {
  const el = $('bpm');
  const bpm = Math.round(deskTempo());
  const own = bpm === Math.round(composedTempo());
  el.textContent = String(bpm);
  el.classList.toggle('tweaked', !own);
  el.parentElement.title = own
    ? 'Drag to change the tempo this song plays at — saved with the song'
    : `Played at ${bpm} bpm, written at ${Math.round(composedTempo())}`
      + ` — click to go back to that. Saved with the song.`;
}
/**
 * Put the tempo in force onto the engine, the echo and the readout.
 *
 * Audio.bpm is set here rather than left to the bank: a stopped desk has no live bank
 * for `setArrangement` to swap, and the keyboard and the note auditions still have to
 * play at the tempo the readout is showing.
 */
function pushTempo() {
  const bpm = deskTempo();
  Audio.bpm = bpm;
  Audio.setDelay({});                 // the echo is tempo-synced, so it follows
  Audio.mixer?.retune(bpm);           // and so is every division-based insert
  showTempo();
}
function setDeskTempo(v) {
  const bpm = clamp(Math.round(v), 40, 240);
  if (bpm === Math.round(deskTempo())) return;
  // Deliberately NOT through `applyArrangementEdit`. That path re-pushes the whole mix
  // at the engine and rebuilds every row of the bar grid, which is right for an edit
  // that moves a bar and wrong forty times during one drag: a tempo moves no bars and
  // no lanes. What it does need is what every arrangement edit needs — an undo step,
  // the draft, the engine, the screen — so those four are here rather than borrowed.
  //
  // One step per drag rather than one per pixel: pushUndo coalesces on the tag.
  pushUndo('bpm');
  // Null when the drag lands back on the composed tempo, so the entry goes away
  // rather than restating what the bank already says — see entryOf. Built against the
  // song's OWN bank, like every other entry — see editBank.
  const entry = entryOf(editBank(),
    setTempo(arrDraftOf(), bpm === Math.round(composedTempo()) ? null : bpm));
  arrDraft[trackId] = entry;
  localStorage.setItem(ARRANGE_KEY, JSON.stringify(arrDraft));
  Audio.setArrangement(entry);
  pushTempo();
  buildTimeline();                    // the clock and the song length move with it
  updateStatus();                     // and the dot that says the file has not heard it
}
dragNumber($('bpm'), {
  value: deskTempo,
  set: setDeskTempo,
  range: 80, step: 1,
  onClick: () => {
    if (Math.round(deskTempo()) === Math.round(composedTempo())) return;
    setDeskTempo(composedTempo());
    toast(`Back to ${Math.round(composedTempo())} bpm — the tempo this song is written at`);
  },
});

// Swing you can drag — the tempo's twin, and it travels the whole way on the same rails:
// the same arrangement entry, the same ⌘Z, the same Save, the same click-to-revert.
//
// Every song in this game is composed as a grid of sixteenths. This is how far off that
// grid it is PLAYED: the number is the on-grid sixteenth's share of its pair, so 50 is
// the grid exactly, around 58 is where most funk and hip-hop actually sits, 66 is the
// triplet shuffle and 75 the dotted one. Only the odd sixteenth moves, which is what
// lets one number cover a whole song — a pad on a downbeat does not shift at all, and
// the groove is entirely in the notes between the beats.
//
// Straight is what every song here was written as, so the readout measures against 50
// rather than against a value the bank supplies, and clicking it goes back there.
const deskSwing = () => arrFor(trackId)?.swing ?? track?.bank?.swing ?? SWING_STRAIGHT;
/** The swing the song is WRITTEN with — straight, unless a composition ever says otherwise. */
const composedSwing = () => track?.bank?.swing ?? SWING_STRAIGHT;
function showSwing() {
  const el = $('swing');
  const swing = Math.round(deskSwing());
  const own = swing === Math.round(composedSwing());
  el.textContent = `${swing}%`;
  el.classList.toggle('tweaked', !own);
  el.parentElement.title = own
    ? 'Drag to swing the whole song — every off-beat sixteenth late, the beats where they are.'
      + ' 66% is a triplet shuffle. Saved with the song.'
    : `Played with ${swing}% swing, written ${
      Math.round(composedSwing()) === SWING_STRAIGHT ? 'straight' : `at ${Math.round(composedSwing())}%`
    } — click to go back to that. Saved with the song.`;
}
/**
 * Put the swing in force onto the engine and the readout.
 *
 * `Audio.swing` is set here for the same reason `pushTempo` sets `Audio.bpm`: a stopped
 * desk has no live bank for `setArrangement` to swap, and selecting a song while it is
 * silent must still leave the engine agreeing with the number on the screen — otherwise
 * the first bar after pressing Play is the last song's feel.
 */
function pushSwing() {
  Audio.swing = deskSwing();
  showSwing();
}
function setDeskSwing(v) {
  const swing = clamp(Math.round(v), SWING_STRAIGHT, SWING_MAX);
  if (swing === Math.round(deskSwing())) return;
  // The same reasoning as the tempo above, and more so: swing moves no bars, no lanes
  // and no bar LENGTHS, so there is not even a timeline to rebuild. One undo step per
  // drag, coalesced on the tag.
  pushUndo('swing');
  const entry = entryOf(editBank(),
    setSwing(arrDraftOf(), swing === Math.round(composedSwing()) ? null : swing));
  arrDraft[trackId] = entry;
  localStorage.setItem(ARRANGE_KEY, JSON.stringify(arrDraft));
  // Seamless by construction: setArrangement leaves `step` and `nextTime` alone, and
  // swing is read fresh on every sixteenth, so a drag across the range re-feels the
  // music under the playhead without a seam or a reset.
  Audio.setArrangement(entry);
  pushSwing();
  updateStatus();
}
dragNumber($('swing'), {
  value: deskSwing,
  set: setDeskSwing,
  // A range of 25 across the drag, because the whole musical span is 50 to 75 — the same
  // pixels the tempo spends on 80 bpm are spent here on the only 25 numbers there are.
  range: 25, step: 1,
  onClick: () => {
    if (Math.round(deskSwing()) === Math.round(composedSwing())) return;
    setDeskSwing(composedSwing());
    toast(Math.round(composedSwing()) === SWING_STRAIGHT
      ? 'Back to straight — on the grid this song is written on'
      : `Back to ${Math.round(composedSwing())}% swing — what this song is written with`);
  },
});

// ---- on-screen keyboard -----------------------------------------------------
//
// Play the selected channel. Everything else on this desk asks what a song already
// sounds like; this asks what a channel sounds like, which is the question you have
// while you are choosing its voice, dialling its filter or listening to what an
// effect did to it — and the only way to answer it before was to run the song and
// wait for the part to come round.
//
// The note is played by the sequencer, through the engine's own previewNote: the
// channel's voice, its note length, its gain, and its strip with everything on it.
// So a muted channel is silent here too, and a channel goes quiet while another is
// soloed. That is the desk being honest rather than the keyboard being broken — the
// title bar says which, in amber, when it happens.
//
// Three ways in, one seam: the drawn keys, the computer keyboard, and a MIDI port all
// end at the same one-note call. A melodic channel gets keys; a drum channel gets the
// song's kit as pads, because two octaves that all play the same kick is a piano
// pretending to be a drum machine.

// Held, not looked up — the same reason `voiceEditEl` is. Docked into the preset
// library this element is MOVED into that window, and the library rebuilds itself on
// every keystroke in its search box: for the moment between the rebuild emptying the
// old slots and the desk parking it into the new ones, the keyboard is detached, and
// `getElementById` does not find a detached element. A lookup there comes back null and
// takes the sequencer's own tick down with it.
const oskEl = $('osk');
const OSK_POS_KEY = 'mash-mixer-osk-pos';

// ---- the key the keyboard is in ---------------------------------------------
//
// A filter over a chromatic keyboard, not a re-lettering of it: the keys stay where a
// piano puts them, the ones outside the key are dimmed, and the bench's figures land on
// the ones inside. Remembered, because it is a preference about how you play rather
// than a property of any song — see SCALES.
//
// Out-of-scale keys still SOUND. A guide that greys the wrong notes helps; one that
// refuses them is an instrument arguing with you, and the accidental you wanted is
// always the one it would have refused.
const OSK_SCALE_KEY = 'mash-mixer-osk-scale';
let oskScaleRoot = 0;
let oskScaleId = 'chromatic';
try {
  const saved = JSON.parse(localStorage.getItem(OSK_SCALE_KEY) || 'null');
  if (saved && SCALE_BY_ID[saved.id]) { oskScaleId = saved.id; oskScaleRoot = saved.root | 0; }
} catch { /* the default key is C chromatic, which is no key at all */ }

/** What the keyboard is set to — `{ root, steps }`, or null when it is chromatic. */
function oskScale() {
  const steps = SCALE_BY_ID[oskScaleId]?.steps;
  return steps ? { root: oskScaleRoot, steps } : null;
}

function setOskScale({ root, id }) {
  if (root != null) oskScaleRoot = ((root % 12) + 12) % 12;
  if (id != null && SCALE_BY_ID[id]) oskScaleId = id;
  localStorage.setItem(OSK_SCALE_KEY, JSON.stringify({ root: oskScaleRoot, id: oskScaleId }));
  if (oskShown()) buildOsk();
  voiceLibrary.refresh();          // the bench's readout is in this key too
}
// How many octaves a PIANO draws here — three, plus the octave above's C so it ends on
// one. It is what the computer keyboard reaches: two full octaves of letters and the
// start of a third, see QWERTY_SEMIS, so the board on screen and the board under your
// fingers are the same instrument and the letters stop at the edge of it rather than a
// third of the way along.
//
// It is not the span in a KEY. A scale gets the same key at the same size and as many of
// them as the space holds — see oskKeyPlan — so three octaves of white keys is what sets
// how big a key is, and a pentatonic drawn with that key reaches four and a bit.
const OSK_OCTAVES = 3;
// The piano's own count, which is the reference every board is drawn against.
const OSK_KEYS = 7 * OSK_OCTAVES + 1;
// The FLOATING board's key, in pixels. Out on the desk there is no band to divide, so
// this is the size rather than the result of one — and the ratio the docked board's black
// keys keep, since it is the only place the two widths are stated together.
//
// 39, not 26. It is the whole of how big the mini keyboard is: three octaves is the span
// wherever it is drawn (see OSK_OCTAVES), so a wider key is a wider window, and at 26 it
// was a keyboard you aimed a mouse at rather than one you played.
const KEY_W = 39;                        // white key width, px
const BLACK_W = 26;
// A black key as a fraction of a white one. The layout is built in units of a key rather
// than in pixels — see buildOskKeys — so this, not BLACK_W, is what it positions with.
const BLACK_UNIT = BLACK_W / KEY_W;
// ...and how tall each is AT that width. Not four independent numbers: a key is a shape,
// and these four are it. Every board scales the set by whatever its own key width came
// out at — see buildOskKeys — so the docked one in a wide band and the floating one in
// its window are the same instrument at two sizes rather than two keyboards.
const KEY_H = 129;
const BLACK_H = 81;
const WHITE_SEMIS = [0, 2, 4, 5, 7, 9, 11];
/** Black key semitone -> the white key of its octave it sits after. */
const BLACK_SEMIS = [[1, 0], [3, 1], [6, 3], [8, 4], [10, 5]];
// The computer keyboard laid out the way every DAW lays it out: a PAIR of rows per
// octave, whites on the row you rest on and blacks on the row above, where a piano has
// them. The bottom pair is the lower octave — Z X C V B N M with S D G H J over it — and
// the QWERTY pair is the one above, Q W E R T Y U with 2 3 5 6 7 over that. Two hands,
// two octaves, and the shape under your fingers is the shape on the screen.
//
// It was one row before — A W S E D… — which is a piano's two rows folded onto a
// keyboard's two rows once. That reaches sixteen semitones and then stops in the middle
// of an octave, so anything wider than a fifth and a bit meant the octave buttons.
//
// The third octave gets what is left of the rows, which is C up to G — `[ = ]` carry on
// past P exactly where the pattern puts them, F on the white key at the end of the row
// and F# on the number key above the gap it leaves. `[` and `]` nudge the playhead when
// the keyboard is not catching; while it is, they are notes, which is the same bargain M
// S R B L already made.
//
// A keyboard is two pairs of rows and a bit, and G is where the bit runs out. The notes
// past it are still drawn, still clickable, and still reachable by shifting the octave —
// see setOskOctave.
const QWERTY_SEMIS = {
  z: 0, s: 1, x: 2, d: 3, c: 4, v: 5, g: 6, b: 7, h: 8, n: 9, j: 10, m: 11,
  q: 12, 2: 13, w: 14, 3: 15, e: 16, r: 17, 5: 18, t: 19, 6: 20, y: 21, 7: 22, u: 23,
  i: 24, 9: 25, o: 26, 0: 27, p: 28, '[': 29, '=': 30, ']': 31,
};
/**
 * Unlabelled seconds — a key that plays a note some other key already draws.
 *
 * The bottom row ends on B and the note you want next is a C, which lives on the row
 * above: a run up the octave has to leave the row it started on at the last step. `,` is
 * that C without the jump — it is where your hand already is, one key past M.
 *
 * Not drawn on the keyboard, and deliberately. Q is what that note is called here; a key
 * wearing two letters is a keyboard asking you which one you meant.
 */
const QWERTY_ALIASES = { ',': 12 };
const SEMI_QWERTY = Object.fromEntries(Object.entries(QWERTY_SEMIS).map(([k, s]) => [s, k]));
// The kit under the same hand: the home row, one letter per pad, left to right.
const PAD_KEYS = ['a', 's', 'd', 'f', 'g', 'h', 'j', 'k'];
// In a key the keys are all one kind and so are the letters: one per degree, straight
// across. The piano's paired rows exist to mirror black keys and white ones and in a key
// there are none to mirror — so these are whole rows, taken bottom upwards for the same
// reason the piano's are: low notes under the low row.
//
// Three rows, because three octaves of a scale is more degrees than one row has letters
// for. It was the home row alone, which ran out ten keys in and left the rest of the
// board unlabelled — a keyboard that stops telling you what plays it half way along.
const SCALE_KEYS = [
  'z', 'x', 'c', 'v', 'b', 'n', 'm',
  'a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l', ';',
  'q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p',
];
/**
 * General MIDI's drum notes, for the pads.
 *
 * Every drum machine and every pad controller sends these, so a kick pad plays the
 * kick rather than whichever pad happens to be third from the left. A note this does
 * not name falls back to position, which is what an ordinary keyboard sends.
 */
const GM_DRUMS = {
  35: 'kick', 36: 'kick', 37: 'rim', 38: 'snare', 39: 'clap', 40: 'snare',
  42: 'hats', 44: 'hats', 46: 'ohats', 49: 'crash', 51: 'crash', 57: 'crash',
};

let oskOct = 3;
let oskLane = null;                      // the lane the keys on screen were built for
let oskBenchId = null;                   // ...or the library preset, if the bench has one
let oskCatch = false;                    // is the computer keyboard playing it?
const oskHeld = new Set();               // held computer keys, so auto-repeat is one note
// Preview notes that are still sounding, keyed by the same `src` as recordOff —
// `k:a` for the computer A key, `m:60` for MIDI note 60. On note-off the engine
// triggers the synth's release envelope instead of letting a fixed sequencer
// length cut it off.
const previewHeld = new Map();           // src → { laneKey, freq }
const chordInputGroups = new Map();       // source key → generated per-tone source keys
const oskHeldVisuals = new Map();        // src → the key or pad it is holding lit

function oskHoldVisual(src, el) {
  if (!src || !el) return;
  const previous = oskHeldVisuals.get(src);
  if (previous && previous !== el) {
    oskHeldVisuals.delete(src);
    if (![...oskHeldVisuals.values()].includes(previous)) previous.classList.remove('held');
  }
  oskHeldVisuals.set(src, el);
  el.classList.add('held');
}

function oskReleaseVisual(src) {
  const el = oskHeldVisuals.get(src);
  if (!el) return;
  oskHeldVisuals.delete(src);
  if (![...oskHeldVisuals.values()].includes(el)) el.classList.remove('held');
}

function clearOskHeldVisuals() {
  for (const el of oskHeldVisuals.values()) el.classList.remove('held');
  oskHeldVisuals.clear();
}

/**
 * ---- recording -------------------------------------------------------------------
 *
 * The keyboard has played a channel for a while; this is the switch that makes it
 * WRITE. It sits here rather than beside the transport because it is a property of the
 * input: which channel the notes go to, which octave the keys are in and whether the
 * computer keys are yours are all decisions taken in the keyboard's own title bar, and
 * where the notes land is the last of them.
 *
 * Armed is not recording. Arming while the song is stopped is legal and is the count-in
 * you get for nothing — capture begins the instant you hit space, and there is no click
 * track in this engine to count you in with anyway. Looping two bars is a better one:
 * you hear the bar before your entry on every pass.
 *
 * `recOpen` maps a SOURCE key to the take's token, so a note-off can find the note-on
 * it belongs to. Three inputs, three namespaces, because a MIDI note 60 and the letter
 * `c` and pointer 3 are three different fingers and may be down at once:
 *
 *   k:z    a computer key            m:60   a MIDI note number
 *   p:3    a pointer on a key or pad
 */
let recArmed = false;
let recTake = null;
let recGrid = 1;                         // sixteenth-step units; 0.5 is a 32nd.
let recLastBeat = -1;
let recLastHeard = 0;
let recChord = null;                     // the note that anchors the current cluster
let recSessionNotes = 0;                 // everything played since arming, for the completion toast
const recSessionLanes = new Set();       // ...and which channels it went to, for the toast
let recChordWarned = false;              // the monophonic warning, once per take
let recUndoPushed = false;                // one undo snapshot for the whole take
let recLiveDirty = false;                 // beat commits waiting for final persistence/redraw
const recOpen = new Map();

const recording = () => recArmed && playing;

const midiFreq = (m) => 440 * 2 ** ((m - 69) / 12);
const oskShown = () => oskEl.classList.contains('show');
/** Master and the send returns are not played by anything — they are where things go. */
const oskPlayable = (key) => !!key && !key.startsWith('__');

/**
 * Which octave to open a channel on: the one its own lowest note is in.
 *
 * A bass keyboard that opens at middle C is two octaves of notes the part never
 * plays, and a twinkle that opens at C1 is silence you have to go looking for the
 * cause of. The song already knows where the part lives.
 */
function laneOctave(key) {
  const b = viewBank();
  let low = null;
  const scan = (block) => {
    const arr = block && block[key];
    if (!Array.isArray(arr)) return;
    for (const v of arr) {
      for (const f of Array.isArray(v) ? v : [v]) {
        if (typeof f === 'number' && f > 0 && (low == null || f < low)) low = f;
      }
    }
  };
  scan(b);
  for (const sec of b?.sections || []) scan(sec);
  // A percussion lane holds booleans and a silent one holds nothing: both land here,
  // and the middle of the keyboard is as good an answer as there is.
  if (low == null) return clampOskOctave(3);
  return clampOskOctave(Math.floor(Math.round(12 * Math.log2(low / 440) + 69) / 12) - 1);
}

/**
 * The preset the keyboard should play instead of a channel, if any.
 *
 * While the library is open it owns the keys. That is the point of it being open: you
 * are working on a preset, not on a channel, and the sound you want under your fingers
 * is the one whose parameters are in front of you. It reverts to the selected channel
 * the moment the library closes. See tools/mixer-voice-library.js.
 */
const oskBench = () => voiceLibrary.picked;

// ---- recording: capture, buffer, flush ---------------------------------------------

/**
 * The region a take is being played into: the armed loop, or the whole song.
 *
 * It is what a note rounds INSIDE. A pickup played thirty milliseconds before the
 * loop's downbeat has to come round to the top of the loop rather than falling off the
 * end of it, which is the one place recording needs to know that a loop is armed.
 */
function recRegion() {
  const { totalSteps } = songShape();
  if (loopOn && locA != null && locB != null) {
    const start = Math.min(locA, locB);
    const end = Math.max(locA, locB);
    return { from: start, span: end - start };
  }
  return { from: 0, span: totalSteps };
}

/** The take, made on first use. Reading is the desk's business; the buffer is not. */
function ensureTake() {
  if (recTake) return recTake;
  const slots = arrDraftOf()?.resolution === 32 ? 32 : 16;
  recTake = createTake({
    // Through the delta chain and then the bank, against the bank as it is WRITTEN —
    // the read half of the write this will go out through. `viewBank()` here would
    // seed an overdub off the ARRANGED song and quietly drop the previous edit; see
    // the note over `editBank`.
    read: (bar, key) => readBarLane(editBank(), arrDraftOf(), bar, key),
    resizable: rollResizable,
    // Against the bank as it is WRITTEN, and read fresh each time: changing a channel's
    // preset mid-take changes whether that channel can hold a chord.
    stacks: (lane) => polyLane(editBank(), lane),
    slots,
  });
  return recTake;
}

/**
 * One played note, on its way into the song.
 *
 * Called from the same two functions that sound it, so all three inputs are recorded by
 * one hook. Everything that decides WHERE is here; everything that decides WHAT is in
 * tools/lib/note-recorder.js and the roll's own note semantics underneath it.
 */
function recordNote(laneKey, midi, freq, src) {
  if (!recording() || !laneKey || !track) return;
  const heard = heardStepNow();
  if (heard == null) return;
  const { from, span } = recRegion();
  recGrid = pianoRoll.quantise();
  // The first note of a cluster decides the step for the rest of it, or a chord whose
  // notes land either side of a rounding boundary comes out as a note plus a dyad a
  // step later. See `chordAnchor`.
  const picked = chordAnchor(recChord, performance.now(),
    quantiseStep(heard, { grid: recGrid, from, span }));
  recChord = picked.anchor;
  const step = picked.step;
  const bar = barOfStep(step);
  const fine = arrDraftOf()?.resolution === 32;
  const inBar = Math.round(stepInBar(step) * (fine ? 2 : 1));
  // A monophonic lane holds ONE frequency per step, so a chord played into one keeps
  // only its last note — not a bug to be fixed but the shape of the bank. Said out
  // loud, once per take, because silently keeping one note of three is indistinguishable
  // from the recorder dropping them.
  if (!polyLane(editBank(), laneKey) && laneKind(laneKey) !== 'perc' && !recChordWarned) {
    const held = recTake?.entries().find((e) => e.bar === bar && e.lane === laneKey);
    if (held && held.notes16[inBar] != null) {
      recChordWarned = true;
      // Only the gesture lanes and the two word lanes reach this now, and for each of
      // them a step is not a pitch: a sweep is the start of a shape, `vox` picks a word.
      // Naming that is more use than "one note at a time", which invites the fair
      // question of why, given you can hear yourself play two.
      toast(`${targetLabel(laneKey)} plays one shape per step rather than notes, so it`
        + ' cannot hold a chord', 6000);
    }
  }
  const token = ensureTake().add({ bar, lane: laneKey, step: inBar, midi, freq });
  if (!token) return;
  recSessionNotes += 1;
  // Remembered against the source so the note-off can find it, and against the step it
  // went down on so the length can be measured from there rather than from the wall
  // clock — a tempo drag mid-take would otherwise change what a held key meant.
  // Everything the note-off needs, and everything needed to put this note back into a
  // FRESH take if a flush lands while the key is still down — see `carryHeld`. `at` is
  // the original press either way, so the length is measured from where the note really
  // started rather than from wherever the last flush happened to be.
  markRecordedVisual(laneKey, bar, inBar, true);
  if (src) recOpen.set(src, { token, at: heard, bar, lane: laneKey, step: inBar, midi, freq });
}

/**
 * Put the notes that are still HELD back into the take a flush just emptied.
 *
 * The bug this exists for, and it is worth writing down because the cause was a speed-up
 * rather than an edit to any of this: a flush clears the take, and clearing the take
 * throws away the open-note tokens with it. A note-off arriving afterwards has nothing to
 * attach a length to, so it writes none and the note keeps the roll's one-step default.
 *
 * That was nearly invisible while the flush was on the bar line — two seconds, and most
 * notes are released inside the bar they were played in. Making the flush four times
 * faster made it near-universal: at 500ms almost every note worth calling held spans a
 * boundary, and every length silently became a sixteenth.
 *
 * So the held notes are re-added to the new take and their tokens repointed. Re-adding is
 * safe and cheap: the note has just been written, so the fresh seed already contains it,
 * `noteCell` puts the same frequency back on the same step, and `noteLength` carries over
 * whatever length was there. Nothing about the recorded note changes — only the take's
 * ability to still be told how long it turned out to be.
 */
function carryHeld() {
  if (!recTake || !recOpen.size) return;
  for (const [src, held] of recOpen) {
    const token = recTake.add({
      bar: held.bar, lane: held.lane, step: held.step, midi: held.midi, freq: held.freq,
    });
    // Not through `recordNote`: this is the same note, not a second one, so it must not
    // count again — and re-seeding is what makes the length reachable, not a new press.
    if (token) recOpen.set(src, { ...held, token });
    else recOpen.delete(src);
  }
}

/** That note came up. Nothing to do at all unless something measured a length. */
function recordOff(src) {
  const held = src && recOpen.get(src);
  if (!held) return;
  recOpen.delete(src);
  if (!recTake) return;
  const heard = heardStepNow();
  if (heard == null) return;
  const { span } = recRegion();
  recTake.close(held.token, heldLength(held.at, heard,
    { grid: pianoRoll.quantise(), span }));
  markRecordedVisual(held.lane, held.bar, held.step, false);
}

/** Finish every kind of preview input, not just its recording token. */
function releasePreview(src) {
  const held = previewHeld.get(src);
  if (!held) return;
  Audio.releasePreviewNote(held.laneKey, held.freq);
  previewHeld.delete(src);
}

function releaseInputPreview(src) {
  const group = chordInputGroups.get(src);
  if (group) {
    for (const child of group) releasePreview(child);
    return;
  }
  releasePreview(src);
}

function oskRelease(src) {
  const group = chordInputGroups.get(src);
  if (group) {
    chordInputGroups.delete(src);
    for (const child of group) oskRelease(child);
    oskReleaseVisual(src);
    return;
  }
  recordOff(src);
  releasePreview(src);
  oskReleaseVisual(src);
}

function releaseOskSources(prefix) {
  const sources = new Set([
    ...recOpen.keys(), ...previewHeld.keys(), ...oskHeldVisuals.keys(),
    ...sustainHeld,
  ]);
  for (const src of sources) {
    if (!src.startsWith(prefix)) continue;
    sustainHeld.delete(src);
    oskRelease(src);
  }
}

/**
 * Hand the take to the song, as one arrangement edit per buffered beat.
 *
 * This is the bar grid's `commit()` with the selection replaced by the take, and for
 * the same reasons: each bar is written on its own, and each write is CHAINED onto the
 * draft the last one returned, so forking one bar cannot lose another's edit.
 *
 * `writeBarNotesShared`, not `writeBarNotes`. Recording into a loop is changing the
 * PATTERN: plumber plays section 0 for four bars, and a note forked into bar 1 alone
 * would come back every fourth pass — which reads as dropped notes rather than as an
 * edit. Shared is what makes a two-bar loop behave the way the ear expects.
 *
 * Beat commits deliberately skip the expensive desk redraw, synchronous localStorage
 * write and loop re-arm. Those are presentation/save work, not audio work; doing all
 * three every 500ms starves the sequencer while somebody is playing into it. The live
 * arrangement still receives the note at the beat, and the final take boundary does
 * the one redraw and persistence pass.
 */
function flushTake(reason) {
  const live = reason === 'beat';
  if (!recTake?.count()) return false;
  const eb = editBank();
  let d = arrDraftOf();
  const entries = recTake.entries();
  for (const { bar, lane } of entries) recSessionLanes.add(lane);
  // Cleared BEFORE the apply, not after: `applyArrangementEdit` can refuse an edit and
  // undo it, and a take still sitting in the buffer would be written again on the next
  // beat and refused again, for ever.
  //
  // `recOpen` is NOT cleared. A key that is still down has not finished being a note, and
  // dropping it here is what made every held note come out a sixteenth long.
  recTake.clear();
  for (const { bar, lane, notes16, lengths16 } of entries) {
    d = writeBarNotesShared(eb, d, bar, lane, notes16, lengths16);
  }
  // ALWAYS silent. The summary belongs to the take ending, not to a write — and those
  // are not the same moment: by the time you disarm, the last beat has usually already
  // taken the buffer, so a toast hung off the final write fires only if you happened to
  // stop within half a second of playing. `endTake` announces instead.
  //
  // Four writes a bar is four times the notice anyway, and a toast twice a second is not
  // notice, it is weather.
  //
  // One snapshot covers the whole take. Beat commits can be separated by more than the
  // ordinary 700ms gesture coalescing window, so do not rely on the generic tag alone.
  const committed = applyArrangementEdit(d, null, {
    undo: !recUndoPushed,
    undoTag: 'record',
    // The loop has not moved — note recording changes lane data, not the loop region.
    atStep: loopOn ? loopAnchor : Audio.step,
    render: !live,
    persist: !live,
    rearmLoop: !live,
  });
  if (!committed) return false;
  recUndoPushed = true;
  recLiveDirty = live;
  // After the write, so the re-seeded notes read a draft that already holds them.
  carryHeld();
  if (!live) {
    stepSeq.refresh();
    pianoRoll.refresh();
    kitRoll.refresh();
  }
  return true;
}

/** Finish a take whose beat commits already reached the live engine. */
function finalizeLiveTake() {
  if (!recLiveDirty) return;
  localStorage.setItem(ARRANGE_KEY, JSON.stringify(arrDraft));
  buildTimeline();
  buildArrangement();
  stepSeq.refresh();
  pianoRoll.refresh();
  kitRoll.refresh();
  updateStatus();
  recLiveDirty = false;
}

/**
 * Drop what has not been written yet. Part of what ⎋ means while recording — the panic
 * takes this with it, so the take ends where the sound did.
 *
 * Note what this is NOT: it is not "throw the take away". The take is written every beat,
 * so by the time you reach for Escape almost all of it is already in the song and the
 * buffer holds at most half a second of playing. Undoing the rest is ⌘Z's job, and the
 * toast says so rather than letting Escape claim more than it does.
 *
 * That was a fair description when the flush was on the bar line and a whole bar could be
 * in flight. It stopped being one when the flush got four times faster, which is the kind
 * of thing a speed-up quietly breaks.
 */
function discardTake() {
  const n = recTake?.count() || 0;
  recTake?.clear();
  recOpen.clear();
  // The session totals go too, or `endTake` announces a take that was just abandoned.
  recSessionNotes = 0;
  recSessionLanes.clear();
  recUndoPushed = false;
  return n;
}

/**
 * Close every key that is still down, flush, and say what was recorded.
 *
 * Called when the take is ending rather than merely crossing a beat. A note held when the
 * transport stops has a real length — the time between the press and the stop — and
 * dropping it would make the last note of every take the only one with no phrasing on it.
 *
 * The summary lives here rather than on the final write, because the final write usually
 * is not the final anything: a beat flush has almost always emptied the buffer already,
 * so a toast hung off it fired only when you stopped inside half a second of playing.
 * Announced from the session totals instead, which are true whenever this is called.
 *
 * `announce: false` for undo, which flushes only so that ⌘Z has the take to remove — and
 * "Recorded 6 notes" a moment before taking them away is a lie about what just happened.
 */
function endTake(reason, { announce = true } = {}) {
  if (recTake) for (const src of [...recOpen.keys()]) oskRelease(src);
  flushTake(reason);
  finalizeLiveTake();
  if (announce && recSessionNotes > 0) {
    const lanes = [...recSessionLanes].map(targetLabel).join(', ');
    toast(`Recorded ${recSessionNotes} note${recSessionNotes === 1 ? '' : 's'}`
      + `${lanes ? ` — ${lanes}` : ''} — ⌘Z to undo, Save to keep it`, 5000);
  }
  recSessionNotes = 0;
  recSessionLanes.clear();
  recUndoPushed = false;
}

/**
 * The BEAT is the commit boundary.
 *
 * It was the bar line, and the bar line is too slow to play against: a note does not
 * appear in the roll until the take is written, so at 120bpm you could play something
 * and watch two seconds of nothing before it turned up. Long enough to think the
 * recorder had missed it and play it again.
 *
 * A beat is four times sooner — 500ms at 120bpm — and costs nothing, because the undo
 * steps coalesce (see `flushTake`) and the intermediate writes are silent. The whole
 * take is still one ⌘Z.
 *
 * Everything buffered goes, including the beat just left. Holding back "the beat under
 * the playhead" is the tempting mistake: in a one-bar loop the playhead comes back round
 * to it, and the buffer would never flush at all. Flushing twice is harmless — the next
 * entry re-seeds from a draft that already holds the earlier notes.
 */
function recordFollow(heardStep) {
  const beat = Math.floor(heardStep / 4);
  if (!recording()) { recLastBeat = beat; recLastHeard = heardStep; return; }
  // Either a new beat, or time went backwards — which is the loop coming round, and on
  // a short loop it is the only signal there is.
  if (beat !== recLastBeat || heardStep < recLastHeard) flushTake('beat');
  recLastBeat = beat;
  recLastHeard = heardStep;
}

/**
 * Arm, or stop.
 *
 * Arming OPENS the keyboard if it is closed, which is what lets the gate below stay in
 * place. The computer keys cannot be un-gated — the desk's letters are its shortcuts,
 * and `oskCatch` is the negotiated hand-over — and MIDI could be, safely, but should
 * not: a note-on writing into a song with no keyboard on screen, no channel name in
 * front of you and no armed lamp anywhere is a song changing for reasons you cannot
 * see. Since arming opens the keyboard, the gate costs the user nothing.
 */
function setRecord(on) {
  if (on === recArmed) return;
  recArmed = on;
  if (on) {
    // The keyboard is NOT opened any more. MIDI reaches the song without it, and the
    // arm lives in the header where you can see it whatever is shut — so a window is
    // something you open to play with a mouse, not a tax on arming. Only the computer
    // keys still need it, and `oskCatch` is its own switch.
    const heard = heardStepNow();
    recLastBeat = heard == null ? -1 : Math.floor(heard / 4);
    recLastHeard = heard ?? 0;
    recSessionNotes = 0;
    recSessionLanes.clear();
    recUndoPushed = false;
    recLiveDirty = false;
    recChord = null;
    recChordWarned = false;
    // An imported .mid has no desk marker, so Save is off on it — see `writable`. The
    // take will play, and localStorage will keep it between refreshes, but it can never
    // reach the file. Better said once, on arming, than found out afterwards.
    if (track && track.writable === false) {
      toast('Recording, but this song came from a .mid and cannot be saved', 5000);
    } else if (!oskPlayable(selectedLane)) {
      toast('Select a channel first — that is where the notes would go');
    } else {
      toast(playing
        ? `Recording into ${targetLabel(selectedLane)} — ⇧R to stop, ⎋ to stop everything`
        : `Armed on ${targetLabel(selectedLane)} — recording starts when the song does`);
    }
  } else {
    endTake('disarm');
  }
  syncRecordUi();
}

/** Two states, and they have to look different: armed is not yet recording. */
function syncRecordUi() {
  // Both buttons, because there are two now: one in the header that is always reachable,
  // one in the keyboard's title bar beside the inputs it decides the fate of. Two
  // controls, one fact — so neither is the source of truth and both are told.
  for (const btn of [oskEl.querySelector('.oskrec'), $('recbtn')]) {
    if (!btn) continue;
    btn.classList.toggle('on', recArmed);
    btn.classList.toggle('live', recording());
  }
  $('midibtn')?.classList.toggle('on', midiOn);
  oskEl.classList.toggle('recording', recording());
  $('playhead').classList.toggle('recording', recording());
}

/**
 * Sound one key. The engine does the rest — see AudioSys.previewNote.
 *
 * `record` is how a GESTURE says it is not a note. A drag across the keys is a glide
 * and fires as fast as pointermove does; recording it would put sixteen semitones in a
 * bar every time somebody went looking for the note they wanted. So the pointer records
 * on the way DOWN and never on the way across, and `src` is the finger it came from, so
 * a note-off can find the note-on it belongs to.
 */
function oskPlay(midi, { record = true, src = null, chord = true } = {}) {
  const bench = oskBench();
  // On the bench a drum IS tuned by the key: a percussion lane's `noteKey` is what
  // soloBank writes the pressed frequency into, and a preset kick you can play up and
  // down is how you find out whether its pitch envelope holds together. That is the
  // opposite of `oskHit` below, and deliberately so — there the kick belongs to a song.
  //
  // It is also why recording is unreachable from here: a preset on the bench has no
  // channel, and the lane its note goes down is an implementation detail of hearing a
  // sound with no strip on it. There is no lane for a take to be written to.
  if (bench) {
    const freq = midiFreq(midi);
    // Every PITCHED preset takes a note-off now — the native paths as well as the
    // pooled ones: `_playGame` registers its gain for a release, `_playAdditive` gates
    // its whole drawbar stack, and MRDR-3 holds per note. Only noise and drum are
    // one-shots whose full envelope is scheduled at note-on with nothing to lift. A
    // pitched preset left out of this map is a key that never comes up: at best it runs
    // its length whatever you do, and on a sustaining patch it rings for thirty seconds.
    const bv = VOICES[bench];
    if (src && bv && bv.kind === 'tone') {
      previewHeld.set(src, { laneKey: benchLane(bv), freq });
    }
    benchPlay(Audio, bench, freq, { bpm: deskTempo() });
    return;
  }
  if (!oskPlayable(selectedLane)) return;
  const chordMidis = chord && laneKind(selectedLane) !== 'perc'
    ? pianoRoll.inputChord(midi) : null;
  if (chordMidis?.length) {
    const children = chordMidis.map((tone, i) => `${src || `input:${midi}`}:ch${i}`);
    if (src) chordInputGroups.set(src, children);
    chordMidis.forEach((tone, i) => oskPlay(tone, {
      record, src: children[i], chord: false,
    }));
    return;
  }
  const freq = midiFreq(midi);
  if (src) {
    // Same rule as the bench above: pitched presets are held and released, noise and
    // drum are struck.
    const lv = voiceOf(engineBank(), selectedLane);
    if (lv && lv.kind === 'tone') {
      previewHeld.set(src, { laneKey: selectedLane, freq });
    }
  }
  lanePreview(selectedLane, freq);
  if (record) recordNote(selectedLane, midi, freq, src);
}

// ---- when a CHANNEL preview is allowed to sound ------------------------------
//
// The same rule the bench has, for the other half of the keyboard.
//
// `previewNote` schedules at `ctx.currentTime + 0.02`, and the audio clock advances in
// blocks — several calls inside one block read the same `currentTime` and therefore ask
// for the same instant. One note at a time that never happens; a SWEEP across the keys
// fires as fast as pointermove does, and the notes land on a voice pool two slots deep
// where Tone requires each slot's times to be non-decreasing. Two at one instant is a
// thrown assert rather than a glide.
//
// So the desk hands out times rather than letting each key ask for one: the time you
// asked for, or the earliest still legal, whichever is later. A millisecond apart is
// inaudible in a glide, and it is all the assert wants.
//
// Keyed by LANE. The pool is per (lane, voice, echo), and a lane plays one voice at a
// time — changing the voice builds a new pool with an empty timeline, and the mark
// resetting with it is exactly right.
const PREVIEW_GAP = 0.001;
let previewLastAt = 0;
let previewLastLane = null;

function lanePreview(laneKey, freq) {
  const ctx = Audio.ctx;
  if (!ctx) return;
  const now = ctx.currentTime;
  if (laneKey !== previewLastLane) { previewLastLane = laneKey; previewLastAt = 0; }
  const t = Math.max(now + 0.02, previewLastAt + PREVIEW_GAP);
  previewLastAt = t;
  Audio.previewNote(laneKey, freq, { bank: engineBank(), at: t - now });
}

/**
 * Sound one drum, at its own pitch.
 *
 * No frequency, deliberately: a percussion lane carries the note it is struck at as a
 * bank key, and the answer to "what does this kick sound like" is the kick the song
 * plays, not a kick tuned to whatever key happened to be under the finger.
 */
function oskHit(laneKey, { record = true, src = null } = {}) {
  if (!oskPlayable(laneKey)) return;
  // Through the same gate as the keys. A drag across the pads is a ROLL — the gesture
  // most likely to ask for two hits on one drum inside a single audio block.
  lanePreview(laneKey, null);
  // A roll is a real musical gesture, unlike a glide, and one day it should be
  // recordable. Not today: it arrives as pointermove and would need its own rate limit
  // to be a figure rather than a smear, and that is a decision about drumming rather
  // than about recording. See `oskPlay` on the `record` flag.
  if (record) recordNote(laneKey, null, null, src);
}

/** The channel, and what it is played by — the two things a preview is asking about. */
function oskTitle() {
  // Named as the library rather than as a lane, because it is not one. The bench lane
  // the note actually goes down is an implementation detail of hearing a preset with no
  // channel — putting `bass` in the title bar would claim the bass strip is involved,
  // and the whole point of the bench is that no strip is.
  const bench = oskBench();
  if (bench) return `Library · ${VOICES[bench]?.label || bench}`;
  if (!oskPlayable(selectedLane)) return 'Select a channel';
  const seam = seamFor(selectedLane);
  const voice = seam && VOICES[engineBank()?.[seam.voiceKey]];
  return `${targetLabel(selectedLane)} · ${voice ? voice.label : 'Engine voice'}`;
}

/**
 * Why a key might make no sound. Worth saying: everything the keyboard plays goes
 * through the channel strip, so the desk's own mute and solo silence it exactly as
 * they silence the song, and a keyboard that has gone quiet for a reason you set
 * yourself two minutes ago otherwise reads as a broken keyboard.
 */
function oskWhy() {
  // Nothing to say on the bench: it has no strip, so there is no mute, no solo and no
  // fader that could be the reason — which is most of why the bench exists.
  if (oskBench()) return null;
  if (!oskPlayable(selectedLane)) return 'Nothing to play';
  // On a kit every pad is its own channel, so mute is a pad's business, not the
  // window's — it is drawn on the pad instead.
  if (!oskIsKit() && Audio.mixer?.lane(selectedLane)?.state?.mute) return 'Muted';
  if (soloed.size && !soloed.has(selectedLane) && !oskIsKit()) return 'Not the soloed channel';
  if (soloedAux.size) return 'A send is soloed';
  return null;
}

function oskFlash(el) {
  if (!el) return;
  el.classList.add('lit');
  setTimeout(() => el.classList.remove('lit'), 130);
}

const oskKeyEl = (midi) => oskEl.querySelector(`.oskkey[data-midi="${midi}"]`);

function buildOsk() {
  const el = oskEl;
  // What the ends of the range ARE moves with the board — a key with a high root reaches
  // further above its base C than a chromatic one, and docking changes how many keys
  // there are to reach with. So the octave is held to them here, where every rebuild
  // passes, rather than only where it is set.
  oskOct = clampOskOctave(oskOct);
  el.textContent = '';
  el.classList.toggle('catching', oskCatch);
  oskLane = selectedLane;
  oskBenchId = oskBench();

  // The title bar is also the handle: a window you move by its name is the one thing
  // every floating panel has ever done, and it leaves the keys free to be keys.
  const head = document.createElement('div');
  head.className = 'oskhead';
  const title = document.createElement('span');
  title.className = 'osktitle';
  title.textContent = oskTitle();
  title.title = oskIsKit()
    ? 'Click a pad to hear that drum through its own channel — drag across them for a roll'
    : 'Click the keys to hear this channel — drag across them to glide';
  // Not a caption under the keyboard, which is a line of text you read once and then
  // never again: a mark in the title bar, only when there is something to say.
  const warn = document.createElement('span');
  warn.className = 'oskwarn';
  const why = oskWhy();
  warn.textContent = why || '';
  warn.hidden = !why;
  const sp = document.createElement('span');
  sp.className = 'sp';
  const catchBtn = document.createElement('button');
  catchBtn.className = 'oskcatch';
  // `Keyboard`, not `catch keys`. It is what the button turns on — the computer
  // keyboard as an instrument — and every other control here is named for the thing
  // rather than for the mechanism behind it.
  catchBtn.textContent = 'Keyboard';
  catchBtn.classList.toggle('on', oskCatch);
  catchBtn.title = 'Play from the computer keyboard. Z X C V B N M is the lower octave '
    + 'with its black keys on S D G H J, and Q W E R T Y U the one above with 2 3 5 6 7 '
    + 'over it, carrying on through I O P and [ = ]. − and + shift the whole board, and '
    + ', is the C above M for a run that ends where your hand already is.'
    + '\n\nWhile this is on, the desk’s own shortcuts on those keys — M S R B L'
    + ' and [ ] for the playhead — are yours to play with instead.';
  catchBtn.onclick = () => setOskCatch(!oskCatch);
  const midiBtn = document.createElement('button');
  midiBtn.className = 'oskmidi';
  midiBtn.textContent = 'MIDI';
  midiBtn.classList.toggle('on', midiOn);
  const ins = midiOn ? midiInputs().map((i) => i.name) : [];
  midiBtn.title = midiOn
    ? (ins.length ? `Playing from ${ins.join(', ')} — click to stop listening`
      : 'Listening, but nothing is plugged in yet')
    : 'Play this channel from a MIDI keyboard. Recording captures the notes and how '
      + 'long you hold them; the level is the channel’s own, as the song plays it.';
  midiBtn.onclick = () => setMidi(!midiOn);
  // Where the notes GO. It sits between the two inputs and the close button because
  // that is the order you decide things in: which channel this is, whether the computer
  // keys are yours, whether MIDI is listening — and then whether any of it is kept.
  const recBtn = document.createElement('button');
  recBtn.className = 'oskrec';
  recBtn.textContent = 'Record';
  recBtn.classList.toggle('on', recArmed);
  recBtn.classList.toggle('live', recording());
  recBtn.title = 'Play notes INTO this channel. Starts and recorded held lengths are '
    + 'quantised to sixteenths — a bank holds sixteen start steps to the bar — and written '
    + 'into the bars the loop is playing, everywhere that part repeats.'
    + '\n\nHow long you hold a key becomes the note’s length. Recording only ADDS notes; '
    + 'taking one out is the piano roll’s job.'
    + '\n\nA bar’s worth of playing is one ⌘Z. ⎋ stops everything and drops whatever has '
    + 'not been written yet. ⇧R from anywhere.';
  recBtn.onclick = () => setRecord(!recArmed);
  const close = document.createElement('button');
  // Folded rather than closed while it is part of the library's workspace — same
  // reasoning as the editor's there. Out on the desk it is a window, and closing a
  // window is closing it.
  //
  // Two different acts, so two different marks. A ✕ means gone, and using it for
  // something that folds away and comes back is the button lying about what it does —
  // you hesitate over a ✕ in a panel you have work in. A chevron pointing DOWN, the way
  // this band collapses, says put-away and says which way.
  //
  // Closing gets the desk's standard mark — see `.popclose`. It was an SVG glyph here
  // and a 19px ✕ on the preset library and an 11px `×` on the step sequencer, which is
  // three controls wearing one job: a close button you have to identify on each panel
  // is a close button you look for. Folding keeps its own mark, because it is a
  // different act.
  const folds = !!voiceLibrary.slots && oskEl.classList.contains('docked');
  close.className = folds ? 'oskclose oskfold' : 'oskclose popclose';
  close.title = folds ? 'Hide the keyboard — the bar below brings it back' : 'Close the keyboard';
  if (folds) close.append(foldIcon('down')); else close.textContent = '✕';
  close.onclick = () => (folds ? voiceLibrary.collapse('keys', true) : showOsk(false));
  head.append(title, warn, sp, midiBtn, catchBtn, recBtn, close);

  const ctl = document.createElement('div');
  ctl.className = 'oskctl';
  // Lit whenever the channel sounds, whatever it sounds — the one readout that means
  // the same thing on a piano and on a kit.
  //
  // At the END of the two source buttons, in the title bar, in every layout. Anything
  // that sounds the channel lights it — MIDI, the computer keyboard, or the song playing
  // through it — so sitting in FRONT of MIDI it read as MIDI's own lamp, and away at the
  // right-hand end of the control row it was a lamp belonging to nothing. After Keyboard
  // it closes the group it is the readout for, and it is in the same place whether the
  // keyboard is floating, docked, or drawing a kit's pads.
  const pulse = document.createElement('span');
  pulse.className = 'oskpulse';
  pulse.title = 'The channel is sounding';
  head.insertBefore(pulse, close);

  // A drum channel is not played by a keyboard, it is played by pads — and by the
  // whole KIT's pads, not one channel's. A kick has one sound and one pitch: two
  // octaves of keys that all play it is a piano pretending, where the row of drums
  // the song actually has is an instrument you can play a beat on. Every pad goes
  // through its own channel strip, so this is the song's kit, mixed as it is mixed.
  if (oskIsKit()) {
    // No octave to shift and no range to state, so there is no control row at all.
    el.append(head, buildOskPads());
  } else {
    // ONE row, wherever it is. The name, the octave, the range, the key and the two
    // source buttons all lead left to right across a single band: what this is, where it
    // is, what it plays in, and what plays it.
    //
    // Docked was already this. Floating kept the two-band version it started as — a title
    // bar with a control row under it — which is two things to scan where there is width
    // for one, and made the same keyboard a different panel depending on where it was
    // sitting. `ctl` survives as the box the octave and scale controls are BUILT in; it
    // is never appended, only emptied into the head.
    const keys = buildOskKeys(ctl);
    // In front of MIDI rather than after it: left to right the row reads what this is,
    // where it is, and then what you can do to it.
    for (const child of [...ctl.children]) head.insertBefore(child, midiBtn);
    el.append(head, keys);
    // Only now is there a window to measure — see fillFloatingKeys.
    fillFloatingKeys(head, keys);
  }
  wireOskDrag(el, head);
  // The head has just been replaced, so the lamp state has to be put back onto the new
  // button — a rebuild mid-take is an octave change or a channel change, not the take
  // ending.
  syncRecordUi();
}

// The keyboard's pads and M8TRX's missing-kit offer ask the same question — what drums
// does this song actually have — and they must never answer it differently: a row of pads
// under a panel saying the song has no drums is one of them lying. One reader, declared
// with the M8TRX control that also reads it.
const oskKitLanes = songKitLanes;
// Pads are the SONG's kit — one pad per drum channel it has. The bench has no kit and
// no channels: it is one preset, and the thing you want to do to a drum preset you are
// shaping is play it up and down to hear its pitch envelope. So the bench always gets
// keys, drum preset or not.
const oskIsKit = () => !oskBench() && oskPlayable(selectedLane)
  && PERCUSSION_LANES.includes(baseLane(selectedLane));

function buildOskPads() {
  const pads = document.createElement('div');
  pads.className = 'oskpads';
  const kit = oskKitLanes();
  for (let i = 0; i < kit.length; i++) {
    const { key, label } = kit[i];
    const pad = document.createElement('div');
    pad.className = 'oskpad';
    pad.dataset.lane = key;
    pad.classList.toggle('sel', key === selectedLane);
    // Its own channel, its own mute: a pad you can hit and hear nothing from is the
    // one thing a kit must not do quietly.
    pad.classList.toggle('muted', !!Audio.mixer?.lane(key)?.state?.mute);
    const name = document.createElement('span');
    name.className = 'oskpadname';
    name.textContent = label;
    const letter = document.createElement('span');
    letter.className = 'oskletter';
    letter.textContent = (PAD_KEYS[i] || '').toUpperCase();
    pad.append(letter, name);
    const seam = seamFor(key);
    const voice = seam && VOICES[engineBank()?.[seam.voiceKey]];
    pad.title = `Play ${label} — ${voice ? voice.label : 'the engine’s own drum'}, through its own channel`;
    pads.append(pad);
  }
  pads.addEventListener('pointerdown', (ev) => {
    const pad = ev.target.closest('.oskpad');
    if (!pad) return;
    ev.preventDefault();
    try { pads.setPointerCapture(ev.pointerId); } catch { /* not a real pointer */ }
    const src = `p:${ev.pointerId}`;
    oskHit(pad.dataset.lane, { src });
    oskHoldVisual(src, pad);
    oskFlash(pad);
  });
  // A drag across the pads is a roll, the same gesture a glide is on the keys — and
  // like a glide it is not recorded. See `oskHit`.
  pads.addEventListener('pointermove', (ev) => {
    if (!ev.buttons) return;
    const pad = document.elementFromPoint(ev.clientX, ev.clientY)?.closest?.('.oskpad');
    const src = `p:${ev.pointerId}`;
    if (!pad || oskHeldVisuals.get(src) === pad
      || pad.classList.contains('lit') || pad.classList.contains('held')) return;
    oskReleaseVisual(src);
    oskHit(pad.dataset.lane, { record: false });
    oskHoldVisual(src, pad);
    oskFlash(pad);
  });
  // A pad has no length to measure, but its preview still needs an explicit release;
  // the shared helper also lets go of any recorder token without leaking one per hit.
  for (const type of ['pointerup', 'pointercancel']) {
    pads.addEventListener(type, (ev) => oskRelease(`p:${ev.pointerId}`));
  }
  return pads;
}

/**
 * Put a built row of keys at a width.
 *
 * A key is a SHAPE, and the shape is the one the floating board has — see KEY_H. The
 * heights used to be CSS, one pair of numbers for the floating board and another for the
 * docked one, which meant the docked keys were whatever proportion its band width
 * happened to make them: the same 132px key was a stub at 49 across and about right at
 * 39. Deriving every other measurement from the width — the black keys, both heights — is
 * the only way a keyboard that sizes itself to a band still looks like a keyboard in
 * every band.
 */
function sizeOskKeys(keys, width) {
  const scale = width / KEY_W;            // everything else is this key, to proportion
  keys.style.width = `${(Number(keys.dataset.count) || 0) * width}px`;
  keys.style.setProperty('--oskwhiteh', `${KEY_H * scale}px`);
  keys.style.setProperty('--oskblackh', `${BLACK_H * scale}px`);
  for (const k of keys.children) {
    k.style.left = `${Number(k.dataset.at) * width}px`;
    k.style.width = `${Number(k.dataset.wide) * width}px`;
  }
}

/**
 * Measure the floating window, and give it the keys that fit in it.
 *
 * Docked, the band states its width and `oskKeyPlan` divides it. Floating, the width is
 * the title bar's — a window is as wide as the widest thing in it — and the keys cannot
 * know it until they are in the document with it. So the row is built at the count the
 * plan can reach on its own, measured here, and built once more if the answer moved.
 *
 * Kept in `oskFloatRoom` rather than being applied to the keys directly, because the
 * count is the answer to more than one question: `oskBoard` reads the same plan to work
 * out how far the board reaches, and a row with more keys on it than the plan admits to
 * would let the octave buttons walk off the top of the range.
 */
const OSK_GUTTER = 10;                   // `.oskkeys` margin, per side — see the CSS
function fillFloatingKeys(head, keys) {
  if (oskEl.classList.contains('docked')) return;
  // The head's box IS the window's content width — it is a block in a shrink-to-fit
  // panel. Zero while the keyboard is hidden, which is nothing to fit to.
  const room = head.getBoundingClientRect().width - (OSK_GUTTER + OSK_CHASSIS) * 2;
  if (!(room > 0) || Math.abs(room - oskFloatRoom) < 0.5) return;
  oskFloatRoom = room;
  // More keys is further up the keyboard, and the octave was held to the range the
  // narrower board could reach — see clampOskOctave. Start again rather than patch it:
  // the second pass measures the same width and stops there.
  const oct = clampOskOctave(oskOct);
  if (oct !== oskOct) { oskOct = oct; buildOsk(); return; }
  // Replaced whole rather than compared first: the measurement can move the count, the
  // width or neither, and rebuilding one row is cheaper than working out which.
  const row = oskKeyRow();
  keys.replaceWith(row.keys);
  head.querySelector('.oskrange').textContent = row.label;
  // The board can have grown wider than the screen has room for to the right of where the
  // window sits. `oskPlace` is what keeps a window on it, and it otherwise only runs when
  // the window is moved or first opened.
  const x = parseFloat(oskEl.style.left);
  const y = parseFloat(oskEl.style.top);
  if (Number.isFinite(x) && Number.isFinite(y)) oskPlace(x, y);
}

function buildOskKeys(ctl) {
  // `−` and `+`, not `◀` and `▶`. An octave is a quantity you take some away from and
  // add some to, and the arrows read as "seek" — the transport's own job. They are also
  // the keystrokes now, which is only sayable because they are the keystrokes: an arrow
  // on a button cannot tell you to press anything.
  const down = document.createElement('button');
  down.textContent = '−';
  down.className = 'oskdown';
  down.onclick = () => setOskOctave(oskOct - 1);
  const up = document.createElement('button');
  up.textContent = '+';
  up.className = 'oskup';
  up.onclick = () => setOskOctave(oskOct + 1);
  // Dimmed at the ends of the instrument rather than removed or disabled: the pair is a
  // readout of where you are in the range as much as it is a control, and one that
  // vanishes is a row whose buttons move under your hand. Disabling them would take the
  // tooltip with it, which is the half of this that says WHY the button stopped.
  const { lo, hi } = oskOctaveRange();
  down.classList.toggle('atend', oskOct <= lo);
  up.classList.toggle('atend', oskOct >= hi);
  down.title = oskOct <= lo
    ? `As low as the keyboard goes — ${deskNoteName(OSK_LOW_MIDI)} is the bottom of the range`
    : 'An octave down ( the − key, while Keyboard is on )';
  up.title = oskOct >= hi
    ? `As high as the keyboard goes — ${deskNoteName(OSK_HIGH_MIDI)} is the top of the range`
    : 'An octave up ( the = key, while Keyboard is on )';
  const oct = document.createElement('span');
  oct.className = 'oskoct';
  oct.textContent = `C${oskOct}`;
  const range = document.createElement('span');
  range.className = 'oskrange';

  // ---- the key to play in.
  //
  // Two controls, because they are two questions — which note is home, and what kind of
  // scale sits on it — and one combined list would be sixty entries saying twelve times
  // five. Together they dim the keys outside the key and put the bench's figures inside
  // it. See SCALES.
  const scaleWrap = document.createElement('span');
  scaleWrap.className = 'oskscale';
  const scaleK = document.createElement('span');
  scaleK.className = 'oskscalek';
  scaleK.textContent = 'Scale';
  const rootSel = document.createElement('select');
  rootSel.className = 'fxsel oskroot';
  for (let i = 0; i < 12; i++) {
    const o = document.createElement('option');
    o.value = String(i); o.textContent = PITCH_CLASSES[i];
    if (i === oskScaleRoot) o.selected = true;
    rootSel.append(o);
  }
  rootSel.title = 'Which note is home';
  rootSel.onchange = () => setOskScale({ root: Number(rootSel.value) });
  const kindSel = document.createElement('select');
  kindSel.className = 'fxsel oskscalekind';
  for (const s of SCALES) {
    const o = document.createElement('option');
    o.value = s.id; o.textContent = s.label;
    if (s.id === oskScaleId) o.selected = true;
    kindSel.append(o);
  }
  kindSel.title = 'Notes outside the key are dimmed — they still play, because the'
    + ' accidental you wanted is always the one a keyboard would have refused.'
    + '\n\nThe bench’s figures land inside it: a triad in Minor comes out minor.';
  kindSel.onchange = () => setOskScale({ id: kindSel.value });
  // The root means nothing without a scale to sit on, and offering it there is offering
  // a control that cannot do anything.
  rootSel.disabled = oskScaleId === 'chromatic';
  scaleWrap.append(scaleK, rootSel, kindSel);

  ctl.append(down, oct, up, range, scaleWrap);

  const row = oskKeyRow();
  range.textContent = row.label;
  return row.keys;
}

/**
 * The keys themselves, and the reading of what they span.
 *
 * Its own function because it gets built twice on a floating board: once at the count the
 * plan can work out on its own, and again once the window has been measured and the plan
 * knows how many keys the window actually holds. See fillFloatingKeys.
 */
function oskKeyRow() {
  const keys = document.createElement('div');
  keys.className = 'oskkeys';
  let label = '';
  // How many keys there are and how wide each one is — the space's answer, with the
  // instrument's own ends taken off it. See oskBoard.
  const plan = oskBoard();
  const base = (oskOct + 1) * 12;
  keys.dataset.count = String(plan.count);
  // Remembered so `fitDockedKeys` can tell whether the band has moved since — a rebuild
  // re-docks, and re-docking asks it again.
  oskDrawnFor = plan.fills ? oskRoom() : -1;

  const sc = oskScale();
  // Laid out in UNITS OF A KEY — `at` is how many keys along it starts, `wide` how many
  // it covers — with `sizeOskKeys` the only place a key becomes pixels. Two callers ask
  // for the same row at two widths: the plan's, and then whatever the frame turned out
  // to be once the head could be measured (see fillFloatingKeys). A row that exists only
  // in pixels cannot be asked the second question without being built again.
  const addKey = (cls, semi, at, wide, letter) => {
    const k = document.createElement('div');
    k.className = `oskkey ${cls}`;
    k.dataset.midi = String(base + semi);
    k.dataset.at = String(at);
    k.dataset.wide = String(wide);
    const name = document.createElement('span');
    name.className = 'oskname';
    // Only the C's are named. Every white key labelled is fifteen readings where you
    // needed one: you find a note by counting from the nearest C, so the C's are the
    // landmarks and the rest is the noise you count through. The octave is in the
    // number, which is the part that was actually hard to see.
    name.textContent = (base + semi) % 12 === 0 ? deskNoteName(base + semi) : '';
    const l = document.createElement('span');
    l.className = 'oskletter';
    l.textContent = (letter || '').toUpperCase();
    k.append(l, name);
    keys.append(k);
    return k;
  };

  if (sc) {
    // ---- in a key: only the notes of it, all the same key.
    //
    // Not a piano with the wrong notes greyed out. A scale has five or seven notes and
    // a piano has twelve, so the black keys in a key are gaps — and a row of uniform
    // keys with nothing between them is the whole point: every key belongs, so you can
    // play it without reading it. GarageBand's scale mode, and for the same reason.
    //
    // The trade is real and worth naming: the notes outside the key are not on the
    // keyboard at all now, where before they were dimmed and still playable. That is
    // what choosing a key MEANS here — chromatic is one item up the list and gives the
    // piano back.
    // Exactly as many degrees as the band holds, counted up from the root — the RANGE
    // is what gives when the width changes, not the size of the keys.
    const offset = (((sc.root - (base % 12)) % 12) + 12) % 12;
    const notes = [];
    for (let i = 0; notes.length < plan.count; i++) {
      notes.push(Math.floor(i / sc.steps.length) * 12 + offset + sc.steps[i % sc.steps.length]);
      if (i > 512) break;                // a step list is never empty, but never loop forever
    }
    label = `${deskNoteName(base + notes[0])} – ${deskNoteName(base + notes[notes.length - 1])}`;
    notes.forEach((semi, i) => {
      const k = addKey('white scalekey', semi, i, 1, SCALE_KEYS[i]);
      // The ROOT is the landmark here, and it is the only one. C is where a piano's
      // octaves visibly start, which is why it is the mark in chromatic — but in A minor
      // pentatonic there is no C to count from, and labelling both leaves two competing
      // answers to "where am I" on a keyboard that has no black keys to tell them apart.
      const isTonic = ((base + semi - sc.root) % 12 + 12) % 12 === 0;
      k.querySelector('.oskname').textContent = isTonic ? deskNoteName(base + semi) : '';
      k.classList.toggle('tonic', isTonic);
    });
  } else {
    const whites = plan.count;
    for (let i = 0; i < whites; i++) {
      const semi = Math.floor(i / 7) * 12 + WHITE_SEMIS[i % 7];
      addKey('white', semi, i, 1, SEMI_QWERTY[semi]);
    }
    label = `${deskNoteName(base)} – `
      + `${deskNoteName(base + Math.floor((whites - 1) / 7) * 12 + WHITE_SEMIS[(whites - 1) % 7])}`;
    // After the whites, so they draw over them without a z-index to maintain. Only the
    // ones that fall inside the drawn whites: the board can now end part way through an
    // octave, exactly as a real one does, and a black key past the last white would hang
    // off the end with nothing under it.
    for (let o = 0; o * 7 < whites; o++) {
      for (const [semi, after] of BLACK_SEMIS) {
        const at = o * 7 + after + 1;
        if (at >= whites) continue;
        addKey('black', o * 12 + semi, at - BLACK_UNIT / 2, BLACK_UNIT, SEMI_QWERTY[o * 12 + semi]);
      }
    }
  }

  sizeOskKeys(keys, plan.width);

  // One listener on the container rather than one per key, so a drag across the
  // keyboard glides — which is how you find the note you are after.
  keys.addEventListener('pointerdown', (ev) => {
    const k = ev.target.closest('.oskkey');
    if (!k) return;
    ev.preventDefault();
    // Captured so a glide off the end of the keyboard still ends the gesture here.
    try { keys.setPointerCapture(ev.pointerId); } catch { /* not a real pointer */ }
    const src = `p:${ev.pointerId}`;
    oskPlay(Number(k.dataset.midi), { src });
    oskHoldVisual(src, k);
    oskFlash(k);
  });
  keys.addEventListener('pointermove', (ev) => {
    if (!ev.buttons) return;
    const k = document.elementFromPoint(ev.clientX, ev.clientY)?.closest?.('.oskkey');
    const src = `p:${ev.pointerId}`;
    if (!k || oskHeldVisuals.get(src) === k
      || k.classList.contains('lit') || k.classList.contains('held')) return;
    // A glide is one gesture looking for one note, not a run of notes to keep.
    releasePreview(src);
    oskReleaseVisual(src);
    oskPlay(Number(k.dataset.midi), { record: false, src });
    oskHoldVisual(src, k);
    oskFlash(k);
  });
  // Lifting the finger is where a clicked note gets its length. `pointercancel` too:
  // the gesture ending some other way is still the key coming up, and a note left open
  // would take the length of everything played after it.
  for (const type of ['pointerup', 'pointercancel']) {
    keys.addEventListener(type, (ev) => oskRelease(`p:${ev.pointerId}`));
  }

  return { keys, label };
}

/** The title bar moves the window. Everything it does is in its own tooltips. */
function wireOskDrag(el, head) {
  head.addEventListener('pointerdown', (ev) => {
    // Docked there is no window to move — it is a band in the library's workspace, and
    // `#osk.docked .oskhead` already says so with `cursor: default`. Dragging it would
    // also be the only thing on the desk that moved a `position: static` node.
    if (el.classList.contains('docked')) return;
    // A control in the title bar is a control, not a grab handle. `button` alone was
    // enough while the head held nothing else; docked it also holds the two scale
    // dropdowns, and `preventDefault` on a select's pointerdown is exactly what stops
    // the list from opening — so the key and the scale could only be changed on the
    // floating keyboard, which is a control that silently does nothing where it lives.
    if (ev.target.closest('button, select, input')) return;
    ev.preventDefault();
    const r = el.getBoundingClientRect();
    const dx = ev.clientX - r.left;
    const dy = ev.clientY - r.top;
    const move = (e) => oskPlace(e.clientX - dx, e.clientY - dy);
    const stop = () => {
      head.removeEventListener('pointermove', move);
      head.classList.remove('dragging');
    };
    head.classList.add('dragging');
    try { head.setPointerCapture(ev.pointerId); } catch { /* not a real pointer */ }
    head.addEventListener('pointermove', move);
    head.addEventListener('pointerup', stop, { once: true });
    head.addEventListener('pointercancel', stop, { once: true });
  });
}

/** Move the window, and keep it on the screen — including after a resize. */
function oskPlace(x, y) {
  const el = oskEl;
  const r = el.getBoundingClientRect();
  const left = clamp(x, 4, Math.max(4, innerWidth - r.width - 4));
  const top = clamp(y, 4, Math.max(4, innerHeight - r.height - 4));
  el.style.left = `${left}px`;
  el.style.top = `${top}px`;
  localStorage.setItem(OSK_POS_KEY, JSON.stringify({ x: left, y: top }));
}

// The ends of the instrument: A0 and C8, a grand piano's own. Past them in either
// direction is not a register anything plays — a sub-bass rumble the desk cannot even
// meter and a whistle above the top of the treble staff — and every voice in the rack is
// tuned for the span between them. The keyboard shifts by whole octaves, so this is a
// limit on the OCTAVE the board sits at rather than on each key: the whole span it draws
// has to land inside them.
const OSK_LOW_MIDI = 21;                 // A0
const OSK_HIGH_MIDI = 108;               // C8

/**
 * The board as it will actually be drawn: how many keys, how wide, and what they span.
 *
 * One answer to a question the layout and the octave buttons both ask, and they have to
 * agree on it. `oskKeyPlan` says how many keys the SPACE holds; this is where the piano's
 * own ends have their say, and the two are not the same number.
 *
 * Where they part is a sparse key in a wide window. Thirty-five pentatonic degrees is
 * nearly seven octaves — more than A0 to C8 holds — so there is no octave to sit at that
 * puts both ends inside the range, and the clamp, asked to satisfy two limits that cannot
 * both be met, honoured the bottom one and drew up to F#8. The keys past the end come off
 * instead: a board that stops at the top of the instrument, which is what a keyboard with
 * eighty-eight keys does too.
 *
 * `at(i)` is the i-th key in semitones above the base C — the same walk both branches of
 * `oskKeyRow` make, written once so the range cannot be worked out from a different
 * keyboard than the one on screen. `base` is always a C, so the offset from it up to the
 * root IS the root.
 */
function oskBoard() {
  const sc = oskScale();
  const plan = oskKeyPlan(sc ? sc.steps.length : 7);
  const at = sc
    ? (i) => Math.floor(i / sc.steps.length) * 12 + sc.root + sc.steps[i % sc.steps.length]
    : (i) => Math.floor(i / 7) * 12 + WHITE_SEMIS[i % 7];
  const low = at(0);
  // The lowest octave this board may sit at is fixed by its bottom key, so the highest
  // note it could ever reach is measured from there — and any key past that is a key the
  // instrument does not have.
  const lo = Math.ceil((OSK_LOW_MIDI - low) / 12) - 1;
  const ceiling = OSK_HIGH_MIDI - (lo + 1) * 12;
  let count = plan.count;
  while (count > 1 && at(count - 1) > ceiling) count--;
  return { count, width: plan.width, fills: plan.fills, lo, low, high: at(count - 1) };
}

/** Which octaves the board may sit at and still draw inside A0 – C8. */
function oskOctaveRange() {
  const { lo, high } = oskBoard();
  // Never crossed: `oskBoard` has already taken off any key that would make it so.
  return { lo, hi: Math.max(lo, Math.floor((OSK_HIGH_MIDI - high) / 12) - 1) };
}

function clampOskOctave(n) {
  const { lo, hi } = oskOctaveRange();
  return clamp(n, lo, hi);
}

function setOskOctave(n) {
  oskOct = clampOskOctave(n);
  if (oskShown()) buildOsk();
}

function setOskCatch(on) {
  if (!on) releaseOskSources('k:');
  oskCatch = !!on && oskShown();
  oskHeld.clear();
  if (oskShown()) buildOsk();
}

/** The title follows the channel; the keys only get rebuilt if the channel moved. */
function refreshOsk() {
  if (!oskShown()) return;
  // Arriving on the bench, or leaving it, changes what the keys ARE — a kit channel
  // draws pads and the bench never does — so it counts as a move exactly as changing
  // channel does. Relabelling alone would leave a row of the song's drum pads sitting
  // under a title bar naming a preset none of them play.
  if (oskLane !== selectedLane || oskBenchId !== oskBench()) {
    const bench = oskBench();
    // The bench opens where the preset was measured: A2, which lives in octave 2. A
    // keyboard that opened at middle C would put the note the level was taken at two
    // octaves below the lowest key.
    if (bench) oskOct = clampOskOctave(2);
    else if (oskPlayable(selectedLane) && !oskIsKit()) oskOct = laneOctave(selectedLane);
    buildOsk();
    return;
  }
  const el = oskEl;
  const t = el.querySelector('.osktitle');
  if (t) t.textContent = oskTitle();
  const warn = el.querySelector('.oskwarn');
  const why = oskWhy();
  if (warn) { warn.textContent = why || ''; warn.hidden = !why; }
  for (const pad of el.querySelectorAll('.oskpad')) {
    pad.classList.toggle('muted', !!Audio.mixer?.lane(pad.dataset.lane)?.state?.mute);
  }
}

function showOsk(on) {
  const el = oskEl;
  el.classList.toggle('show', on);
  $('oskbtn').classList.toggle('on', on);
  if (!on) {
    releaseOskSources('p:');
    releaseOskSources('k:');
    clearOskHeldVisuals();
    oskCatch = false; oskHeld.clear(); el.classList.remove('docked');
    // Closing the keyboard no longer disarms. It used to, because the arm lived in here
    // and a recorder running behind a shut window was a song changing invisibly — but
    // the arm is in the header now and stays lit, so closing a window you were not
    // playing with is not a reason to end a take. Any keys still HELD are closed, since
    // their note-off is going with the window.
    syncRecordUi();
    rememberSongLayout();
    return;
  }
  if (oskBench()) oskOct = clampOskOctave(2);   // where A2 lives — see refreshOsk
  else if (oskPlayable(selectedLane) && oskLane !== selectedLane) oskOct = laneOctave(selectedLane);
  buildOsk();
  // Along the bottom of the library while that is open, rather than floating over it.
  // Positioning is the floating window's business and is skipped entirely when docked —
  // a `position: fixed` left/top on a node inside a flex row is a node somewhere else.
  if (voiceLibrary.slots) { dockIntoLibrary(); rememberSongLayout(); return; }
  let pos = null;
  try { pos = JSON.parse(localStorage.getItem(OSK_POS_KEY) || 'null'); } catch { pos = null; }
  const r = el.getBoundingClientRect();
  // First open: bottom right, above the footer, where it covers the least of the rack.
  oskPlace(pos?.x ?? innerWidth - r.width - 24, pos?.y ?? innerHeight - r.height - 54);
  rememberSongLayout();
}

/**
 * A computer key, while the keyboard is catching them. Returns true when it was one
 * of ours, which is what tells the desk's own shortcuts to keep their hands off.
 */
function oskTypedKey(e) {
  if (!oskCatch || !oskShown()) return false;
  // Nothing the keyboard plays needs Shift, so the whole shifted alphabet stays the
  // desk's — which is the only reason ⇧R can arm recording while your hands are on the
  // notes. Without this, `r` is a semitone and the desk never sees the shortcut.
  if (e.shiftKey) return false;
  const key = e.key.toLowerCase();
  // Escape is the panic now, and the keyboard does not claim it. It used to mean the
  // biggest thing there was to back out of — the take while one was running, key-catching
  // otherwise — but an emergency cut that stops working whenever this window is up is not
  // one you can rely on, and both of the old meanings are inside the panic anyway: it
  // stops the transport, disarms the take and drops what has not been written. Handing
  // the letters back is what the ⌨ button in the title bar is for.
  if (key === 'escape') return false;
  // A kit is one row of pads, so the home row is all it needs and Z/X have nothing
  // to shift. Everything else on the keyboard falls back to the desk.
  if (oskIsKit()) {
    const i = PAD_KEYS.indexOf(key);
    if (i === -1) return false;
    const pad = oskEl.querySelectorAll('.oskpad')[i];
    if (!pad) return false;
    if (e.repeat || oskHeld.has(key)) return true;
    oskHeld.add(key);
    const src = `k:${key}`;
    oskHit(pad.dataset.lane, { src });
    oskHoldVisual(src, pad);
    oskFlash(pad);
    return true;
  }
  // The octave, on the two keys drawn on the buttons: `−` and `+`, literally. `=` used
  // to do the up as well, unshifted, which is the better keystroke — but it is the third
  // octave's F# now, and a note that also jumped the board out from under the hand
  // playing it is not a note you could use. Z and X went the same way, to C and D.
  if (key === '-' || key === '_') { setOskOctave(oskOct - 1); return true; }
  if (key === '+') { setOskOctave(oskOct + 1); return true; }
  // In a key the letters run straight across the degrees drawn on screen, so the lookup
  // is the keyboard itself rather than a semitone table — there is no fixed mapping from
  // a letter to a note when which notes exist depends on the scale.
  if (oskScale()) {
    const i = SCALE_KEYS.indexOf(key);
    if (i === -1) return false;
    const k = oskEl.querySelectorAll('.oskkey')[i];
    if (!k) return false;
    if (e.repeat || oskHeld.has(key)) return true;
    oskHeld.add(key);
    const src = `k:${key}`;
    oskPlay(Number(k.dataset.midi), { src });
    oskHoldVisual(src, k);
    oskFlash(k);
    return true;
  }
  const semi = QWERTY_SEMIS[key] ?? QWERTY_ALIASES[key];
  if (semi == null) return false;
  // Auto-repeat is the operating system, not you playing the note again.
  if (e.repeat || oskHeld.has(key)) return true;
  oskHeld.add(key);
  const midi = (oskOct + 1) * 12 + semi;
  const src = `k:${key}`;
  const k = oskKeyEl(midi);
  oskPlay(midi, { src });
  oskHoldVisual(src, k);
  oskFlash(k);
  return true;
}

/**
 * Light what the channel is playing, while it plays it.
 *
 * The other half of a keyboard on a mixing desk: pressing a key asks what a channel
 * sounds like, and watching it asks what the channel is DOING — which notes the part
 * is actually made of, where in the octave it sits, whether the twinkle you cannot
 * pick out of the mix is playing at all — live, and on the thing you are about to
 * play yourself.
 *
 * Driven from the desk's own playhead rather than from the sequencer, so it lands
 * with the ear: `heardStep` has already had the scheduler's lookahead and the
 * playhead offset taken out of it. Null means nothing is playing.
 */
let oskStep = -1;
let oskBlockCache = { bank: null, list: null };
function oskFollow(heardStep) {
  if (!oskShown()) return;
  const step = heardStep == null ? -1 : Math.floor(heardStep);
  if (step === oskStep) return;
  oskStep = step;
  const el = oskEl;
  for (const k of el.querySelectorAll('.sung')) k.classList.remove('sung');
  for (const b of el.querySelectorAll('.offscreen')) b.classList.remove('offscreen');
  el.querySelector('.oskpulse')?.classList.remove('on');
  // Nothing to follow on the bench. These keys are playing a library preset, not a
  // channel, so lighting them from the song's selected lane would be the keyboard
  // reporting on a part none of them can sound.
  if (step < 0 || oskBench() || !oskPlayable(selectedLane)) return;
  const b = viewBank();
  if (oskBlockCache.bank !== b) oskBlockCache = { bank: b, list: songBlocks(b, 1) };
  const list = oskBlockCache.list;
  if (!list.length) return;
  // The song's form, resolved: a section is a partial bank spread over the whole, so
  // the notes under the playhead are the block's, not the top-level bank's.
  const block = list[Math.floor(step / 32) % list.length];
  if (!block) return;
  // The whole kit lights, not just the selected pad: watching a beat go past is the
  // point of having the drums in one row.
  if (oskIsKit()) {
    for (const pad of el.querySelectorAll('.oskpad')) {
      if (!block[pad.dataset.lane]?.[step % 32]) continue;
      pad.classList.add('sung');
      el.querySelector('.oskpulse')?.classList.add('on');
    }
    return;
  }
  const value = block[selectedLane] && block[selectedLane][step % 32];
  if (!value) return;
  el.querySelector('.oskpulse')?.classList.add('on');
  const base = (oskOct + 1) * 12;
  for (const f of Array.isArray(value) ? value : [value]) {
    if (typeof f !== 'number' || !(f > 0)) continue;
    const midi = Math.round(12 * Math.log2(f / 440) + 69);
    const k = oskKeyEl(midi);
    // A note the keyboard cannot show lights the octave button that would reach it,
    // which is both "there is more up there" and which way to go for it.
    if (k) k.classList.add('sung');
    else el.querySelector(midi < base ? '.oskdown' : '.oskup')?.classList.add('offscreen');
  }
}

/**
 * A real keyboard, over Web MIDI.
 *
 * The same seam the on-screen keys and the computer keyboard use, with a third caller
 * on it — a note-on becomes `oskPlay` or a pad hit and nothing else changes, which is
 * the whole reason previewNote takes a note rather than a gesture.
 *
 * Note-OFF is honoured: a held key sustains, because the rack learned how. Every path
 * the desk can preview — the pooled Tone classes through `triggerRelease`, and the three
 * native ones through `_heldNative` — runs its envelope to the sustain level and waits
 * there for the key to come up. A layer at sustain 0 still dies as written, which is what
 * a struck sound is.
 *
 * And the DAMPER (CC 64) does what a damper does: while it is down, note-offs are
 * deferred rather than dropped, and lifting it releases everything still holding. Notes
 * played while it is down sustain too, exactly as a piano's do.
 *
 * Velocity is still ignored, and that is not laziness: the level is the lane's, and a
 * preview at half of it is a preview of a mix decision nobody made. Worth revisiting the
 * day the desk plays notes INTO a song rather than only out of one.
 */
let midiAccess = null;
let midiOn = false;
const synthMidiListeners = new Set();
const synthMidiStateListeners = new Set();

function midiInputs() {
  return midiAccess ? [...midiAccess.inputs.values()] : [];
}

const synthMidiAdapter = {
  playback: false,
  subscribe(listener) { synthMidiListeners.add(listener); return () => synthMidiListeners.delete(listener); },
  onState(listener) { synthMidiStateListeners.add(listener); return () => synthMidiStateListeners.delete(listener); },
  state: () => ({ on: midiOn, inputs: midiInputs().map((input) => input.name || 'MIDI input') }),
  setEnabled: (on) => setMidi(on),
};
const emitSynthMidi = (event) => { for (const listener of synthMidiListeners) listener(event); };
const emitSynthMidiState = () => {
  const state = synthMidiAdapter.state();
  for (const listener of synthMidiStateListeners) listener(state);
};

// The damper pedal, and what it is holding.
//
// CC 64 is the one controller worth reading here: it is the pedal under every keyboard,
// and its whole job is to stop note-offs from arriving. Below 64 is up, at or above is
// down — the MIDI convention, and what every half-pedal-less keyboard sends.
let sustainDown = false;
const sustainHeld = new Set();

/** Lift or press the damper. Lifting releases everything it was holding, at once. */
function setSustain(down) {
  if (down === sustainDown) return;
  sustainDown = down;
  if (down) return;
  for (const src of sustainHeld) {
    releaseInputPreview(src);
    chordInputGroups.delete(src);
  }
  sustainHeld.clear();
}

/** Drop the pedal and its notes — the keyboard going away, or a panic. */
function dropSustain() {
  sustainDown = false;
  for (const src of sustainHeld) {
    releaseInputPreview(src);
    chordInputGroups.delete(src);
  }
  sustainHeld.clear();
}

function onMidiMessage(e) {
  const [status, note, vel] = e.data;
  const kind = status & 0xf0;
  if (kind === 0xB0 && note === 64) {
    const down = vel >= 64;
    emitSynthMidi({ type: 'sustain', down });
    setSustain(down); return;
  }
  // A note-off is either an actual 0x80 or a note-on at velocity zero, which is how
  // most keyboards send one. It was discarded outright until recording existed to have
  // a use for it; now it is the only thing that knows how long a note was.
  if (kind === 0x80 || (kind === 0x90 && !vel)) {
    const src = `m:${note}`;
    emitSynthMidi({ type: 'off', midi: note, source: src });
    if (sustainDown && (previewHeld.has(src) || chordInputGroups.has(src))) {
      // The KEY is up — the drawn key unlights and the recorder closes the note at the
      // length it was actually played. Only the sound is held over, which is the one
      // thing a damper does. A recorded note that grew because a foot was down would be
      // a part nobody played.
      const group = chordInputGroups.get(src);
      if (group) for (const child of group) recordOff(child);
      else recordOff(src);
      oskReleaseVisual(src);
      sustainHeld.add(src);
      return;
    }
    oskRelease(src);
    return;
  }
  if (kind !== 0x90) return;
  // Re-pressing a key the pedal is holding takes it back: the note restarts, as it does
  // on a piano and as `_releasePreview` already makes it do in the rack.
  sustainHeld.delete(`m:${note}`);
  // No `oskShown()` any more. A MIDI keyboard is a real instrument sitting in front of
  // you: your eyes are on your hands or on the roll filling up, not on a drawn keyboard,
  // and requiring a window you are not looking at is a window in the way. What the gate
  // was protecting against — a song changing for reasons you cannot see — is better
  // served by the arm being in the header, where it is visible whatever else is shut.
  //
  // The computer keys are a different case and keep their gate: the desk's letters are
  // its shortcuts, and `oskCatch` is the negotiated hand-over. See `oskTypedKey`.
  if (!oskPlayable(selectedLane)) return;
  if (oskIsKit()) {
    // Off the song's kit rather than off the drawn pads, so a drum arrives whether or
    // not the keyboard is open. The pads are one view of this list, not the list.
    const kit = oskKitLanes();
    if (!kit.length) return;
    const named = GM_DRUMS[note];
    const lane = (kit.find((l) => baseLane(l.key) === named) || kit[note % kit.length]).key;
    const src = `m:${note}`;
    const pad = oskEl.querySelector(`.oskpad[data-lane="${CSS.escape(lane)}"]`);
    oskHit(lane, { src });
    oskHoldVisual(src, pad);
    oskFlash(pad);
    return;
  }
  const src = `m:${note}`;
  emitSynthMidi({ type: 'on', midi: note, source: src });
  oskPlay(note, { src });
  if (!oskShown()) return;
  const k = oskKeyEl(note);
  // A note off the end of the keyboard still sounds — it is a real instrument's note,
  // not a click on a drawn key — so the arrow lights rather than nothing happening.
  if (k) { oskHoldVisual(src, k); oskFlash(k); }
  else oskEl.querySelector(note < (oskOct + 1) * 12 ? '.oskdown' : '.oskup')?.classList.add('offscreen');
}

function attachMidi() {
  for (const input of midiInputs()) input.onmidimessage = onMidiMessage;
}

async function setMidi(on, { announce = true } = {}) {
  if (!on) {
    for (const input of midiInputs()) input.onmidimessage = null;
    midiOn = false;
    localStorage.removeItem(MIDI_LS_KEY);
    // Anything still held loses its note-off with the port, so close it here rather than
    // leaving the note open to take the length of whatever is played next. The pedal goes
    // with it: a damper left down when the keyboard is unplugged would hold the next thing
    // you played until you plugged the keyboard back in and pressed it again.
    dropSustain();
    releaseOskSources('m:');
    emitSynthMidi({ type: 'panic' });
    emitSynthMidiState();
    $('midibtn')?.classList.toggle('on', false);
    if (announce) toast('MIDI off');
    if (oskShown()) buildOsk();
    return;
  }
  if (!navigator.requestMIDIAccess) {
    toast('This browser has no Web MIDI — Chrome and Edge do');
    return;
  }
  try {
    midiAccess = await navigator.requestMIDIAccess();
  } catch {
    toast('MIDI was refused — allow it for this site and try again');
    return;
  }
  midiOn = true;
  localStorage.setItem(MIDI_LS_KEY, '1');
  attachMidi();
  // A keyboard plugged in after the desk was opened is the ordinary case, not the
  // exception: the browser hands over the ports it has, and the rest arrive later.
  midiAccess.onstatechange = (event) => {
    if (!midiOn) return;
    // A removed port may never send its note-offs. Close every source at the
    // disconnect edge even when another MIDI input remains available.
    if (event?.port?.type === 'input' && event.port.state === 'disconnected') {
      dropSustain();
      releaseOskSources('m:');
      emitSynthMidi({ type: 'panic' });
    }
    attachMidi(); if (oskShown()) refreshOsk(); emitSynthMidiState();
  };
  const names = midiInputs().map((i) => i.name);
  toast(names.length ? `MIDI in: ${names.join(', ')}` : 'MIDI on — nothing plugged in yet');
  $('midibtn')?.classList.toggle('on', true);
  emitSynthMidiState();
  if (oskShown()) buildOsk();
}

addEventListener('keyup', (e) => {
  const key = e.key.toLowerCase();
  oskHeld.delete(key);
  // The same event, now also carrying a length. It already existed to stop auto-repeat
  // being heard as a run of notes, which is the same fact about the key from the other
  // side: this is when it came up.
  oskRelease(`k:${key}`);
});
addEventListener('resize', () => {
  scheduleDeskEdges();
  if (!oskShown()) return;
  // Docked it has no position to keep — it has a width to re-fit instead.
  if (oskEl.classList.contains('docked')) { fitDockedKeys(); return; }
  oskPlace(parseFloat(oskEl.style.left) || 0, parseFloat(oskEl.style.top) || 0);
});
measureDeskEdges();
watchDeskEdges();

// ---- wiring ----------------------------------------------------------------
// Loading a song is a thing you do a few times an hour, so it does not need a
// control sitting open on the header; what you DO need at all times is which song
// you are on, and that reads better in the footer where it has room for its name.
const SONG_GROUPS = [
  ['Themes', 'theme'],
  ['Cabinets', 'cabinet'],
  // Next to the songs they are alternates of, because that is the comparison anybody
  // opening one is making: this version of NEON BLASTERS against the shipped one.
  ['Alternate Game Songs', 'alternate'],
  ['Shop auditions', 'audition'],
  ['Scratch songs', 'scratch'],
  // Snapshots — "Save a copy…" on any song. Under the scratch material rather than
  // beside the songs they were taken from: a copy is a moment somebody kept, not a
  // version of anything being decided, and a dozen of them stacked next to NEON
  // BLASTERS would read as twelve candidates for it.
  ['Saved copies', 'copy'],
  ['MIDI imports', 'imported'],
  // Last, and deliberately: one per style pack, written by tools/style-auditions.js so
  // a pack's opening sounds can be heard and swapped rather than read off a list. They
  // are development scaffolding, so they sort under the material rather than over it.
  ['Style auditions', 'styleAudition'],
].filter(([, group]) => !STATIC || group === 'theme' || group === 'scratch' || group === 'copy');

/** Which songs this desk is allowed to show. Everything, unless it is the deployed one. */
const visibleTrack = (t) => !STATIC || SHIPPED_SONG_IDS.has(t.id) || deskSongIds.has(t.id);

// In the static deployed mixer there is no server, so anything that fetches or
// posts to one cannot work. Hide those buttons rather than leaving them to answer
// every click with an error toast. Discard stays: it is pure client state, and it is
// what makes the one shipped song safe to pull apart.
if (STATIC) {
  // A few songs at most, all of them yours, and nothing to come back to that is not
  // already on the list — so no search box and no most-recently-opened.
  const recent = document.getElementById('recent');
  if (recent) recent.hidden = true;
  document.querySelector('.drawersearch')?.setAttribute('hidden', '');
  // The cabinet screen is the game's business, not a tester's: it decides what a
  // level's stage-select sounds like, and every control in it writes song data that
  // this build cannot save anyway.
  document.querySelector('[data-drawer-section="cabinet"]')?.setAttribute('hidden', '');
  // Render / Files STAYS. It used to go wholesale, on the grounds that rendering
  // needed headless Chromium and the exports needed a disk. Neither is true any more:
  // the WAV is rendered by this browser, through the same engine playing the song
  // (see mixer-bounce.js), and the MIDI and the JSON backup never needed a server —
  // they are bytes built here and handed to a download. On a desk whose only copy of
  // your work is localStorage, a way to get that work OUT is not a luxury.
  //
  // The two that genuinely cannot work here still go: Audition drives a plugin host
  // on the machine running the mixer, and Import MIDI writes a song file to a disk
  // this build does not have.
  $('auditionwav')?.setAttribute('hidden', '');
  $('importmidi')?.setAttribute('hidden', '');
  document.getElementById('opensectionhead')?.replaceChildren('Songs');
  // Save keeps a copy in this browser instead of writing a file, so the way back to the
  // shipped song is its own button — Discard now only reaches your copy. updateStatus
  // is what shows it, because it is only ever offered on a song that shipped.
  //
  // The fourth thing this rule covers is not hidden here, because it is not in the
  // shell: the voice editor's Save, Save as New, Update and Delete all post, and they
  // are built in mixer-voice-editor.js. They come off through its `canFile` dependency,
  // handed in where the editor is created. Editing a synth is untouched — a preset
  // opened from a strip is copied into the song and kept by the song's own Save.
}

const RECENT_KEY = 'mash-mixer-recent-songs';
const RECENT_LIMIT = 5;

function recentSongIds() {
  let ids = [];
  try { ids = JSON.parse(localStorage.getItem(RECENT_KEY) || '[]'); } catch { ids = []; }
  if (!Array.isArray(ids)) ids = [];
  return ids.filter((id, i) => i < RECENT_LIMIT && resolveTrack(id) && visibleTrack(resolveTrack(id)));
}

function rememberRecent(id) {
  if (!id) return;
  const ids = [id, ...recentSongIds().filter((x) => x !== id)].slice(0, RECENT_LIMIT);
  localStorage.setItem(RECENT_KEY, JSON.stringify(ids));
}

function forgetRecent(id) {
  localStorage.setItem(RECENT_KEY, JSON.stringify(recentSongIds().filter((x) => x !== id)));
}

function selectSong(id) {
  cancelStartPreparation();
  peakSeen = 0;
  // The dropout count is about the song in front of you, like the peak reading beside
  // it — carrying the last song's holes over would make a clean mix look faulty.
  health.dropouts = 0;
  health.uiStalled = false;
  health.audioBehind = false;
  health.behindSince = 0;
  health.audioStruggling = false;
  loadTrack(id);
  $('nowsong').textContent = track.title;
  localStorage.setItem(SONG_KEY, id);
  rememberRecent(id);
  // Whatever this song has stored for its cabinet screen, shown rather than assumed.
  if (typeof cabSyncControls === 'function') cabSyncControls();
  if ($('navdrawer')?.classList.contains('show')) renderSongBrowser();
}

function songButton(t, { recent = false } = {}) {
  const b = document.createElement('button');
  b.className = `drawer-song${t.id === trackId ? ' on' : ''}`;
  const name = document.createElement('span'); name.className = 'songname'; name.textContent = t.title;
  const id = document.createElement('span'); id.className = 'songid'; id.textContent = t.id;
  b.append(name, id);
  b.title = `${t.title} — ${t.id}` + (recent ? ' · recently opened' : '');
  b.onclick = () => { closeMenu(); selectSong(t.id); toast(`Loaded ${t.title}`); };
  return b;
}

function renderSongBrowser() {
  const tracks = listTracks().filter(visibleTrack);
  const byId = new Map(tracks.map((t) => [t.id, t]));
  const query = ($('songsearch').value || '').trim().toLowerCase();
  const matches = (t) => !query || `${t.title} ${t.id}`.toLowerCase().includes(query);
  const recent = $('recent');
  recent.textContent = '';
  const recentTracks = recentSongIds().map((id) => byId.get(id)).filter(Boolean).filter(matches);
  if (recentTracks.length) {
    const h = document.createElement('div'); h.className = 'drawersectionhead'; h.textContent = 'Recently opened';
    recent.append(h, ...recentTracks.map((t) => songButton(t, { recent: true })));
  }

  const list = $('songlist');
  list.textContent = '';
  let any = false;
  for (const [title, group] of SONG_GROUPS) {
    const rows = tracks.filter((t) => t.group === group && matches(t));
    if (!rows.length) continue;
    any = true;
    // A handful of songs, all of them yours: one flat list under the section's own
    // heading, the shipped one first and whatever you have made after it. Shelves with
    // a count of 1 on them are a filing system for a list that does not need filing.
    if (STATIC) { list.append(...rows.map((t) => songButton(t))); continue; }
    // Collapsed by default because the local desk has six shelves of songs; the
    // deployed one has a single row, and a row you have to unfold is a row you miss.
    const open = !!query || STATIC;
    const section = document.createElement('div');
    section.className = `drawergroup${open ? '' : ' collapsed'}`;
    const h = document.createElement('button');
    h.className = 'drawergrouptoggle'; h.type = 'button';
    h.setAttribute('aria-expanded', String(open));
    const label = document.createElement('span'); label.textContent = title;
    const count = document.createElement('span'); count.className = 'groupcount'; count.textContent = rows.length;
    h.append(label, count);
    h.onclick = (ev) => {
      ev.stopPropagation();
      const collapsed = section.classList.toggle('collapsed');
      h.setAttribute('aria-expanded', String(!collapsed));
    };
    section.append(h, ...rows.map((t) => songButton(t)));
    list.append(section);
  }
  if (!any) {
    const empty = document.createElement('div'); empty.className = 'drawerempty';
    empty.textContent = query ? 'No songs match that search.' : 'No songs available.';
    list.append(empty);
  }
}

$('songsearch').oninput = renderSongBrowser;

// What the New Song dialog was last asked for, minus the title. Everything else in it
// is a working preference — you are usually making eight-bar boom-bap sketches all
// afternoon — while the name is the one field that has to be different every time.
const NEW_SONG_KEY = 'mash-mixer-new-song';
let newSongPrefs = {};
try { newSongPrefs = JSON.parse(localStorage.getItem(NEW_SONG_KEY) || '{}') || {}; }
catch { newSongPrefs = {}; }

async function createNewSong() {
  closeMenu();
  // Prefilled with a name nobody in the drawer is using, so the field can just be
  // accepted. The server picks its own if this is cleared.
  const suggested = randomSongName({ taken: listTracks().map((t) => t.title) });
  const prefs = {
    template: 'full-band', style: 'auto', bars: 8, bpm: 120, styleTempo: true, ...newSongPrefs,
  };
  const sel = (value, want) => (value === want ? ' selected' : '');
  const answered = ask('Create a scratch song',
    `<label class="askfield">Title<input id="newsongtitle" type="text" spellcheck="false" value="${escapeHtml(suggested)}"></label>`
    // Template first, because it decides what the rest of the dialog is even for: a
    // Blank song has no style and no tempo of its own to inherit.
    + '<label class="askfield">Template<select id="newsongtemplate">'
    + `<option value="full-band"${sel(prefs.template, 'full-band')}>Full Song</option>`
    + `<option value="beat"${sel(prefs.template, 'beat')}>Beats Only</option>`
    + `<option value="blank"${sel(prefs.template, 'blank')}>Blank</option>`
    + '</select></label>'
    + '<label class="askfield" id="newsongstylefield">Style<select id="newsongstyle">'
    + `<option value="auto"${sel(prefs.style, 'auto')}>Auto</option>`
    + SONG_STYLES.map((s) => `<option value="${s.id}"${sel(prefs.style, s.id)}>${escapeHtml(s.label)} · ${s.bpm} BPM</option>`).join('')
    + '</select></label>'
    + '<label class="askfield">Tempo<input id="newsongbpm" type="number" min="40" max="240" step="1"></label>'
    + `<label class="askcheck" id="newsongtempofield"><input id="newsongstyletempo" type="checkbox"${prefs.styleTempo ? ' checked' : ''}>Use the template’s own tempo</label>`
    + `<label class="askfield">Bars<input id="newsongbars" type="number" min="1" max="64" step="1" value="${prefs.bars}"></label>`,
    'Create');
  const title = $('newsongtitle');
  title.focus(); title.select();
  const templateSelect = $('newsongtemplate');
  const styleSelect = $('newsongstyle');
  const styleField = $('newsongstylefield');
  const tempoField = $('newsongtempofield');
  const styleTempo = $('newsongstyletempo');
  const bpmField = $('newsongbpm');
  // The tempo box is either yours to type in or the template's to report. Left as an
  // empty box with a placeholder, it was a field that looked unanswered and a number
  // you could not see; disabled and filled in, it says what you are about to get.
  //
  // Your own tempo is remembered separately from the template's. Reading it back out
  // of the box would mean that glancing at Boom Bap's 88 and then switching to Blank
  // silently made 88 your number.
  let manual = Number(prefs.bpm) || 120;
  bpmField.oninput = () => { if (!bpmField.disabled) manual = Number(bpmField.value) || manual; };
  const paint = () => {
    const blank = templateSelect.value === 'blank';
    styleField.hidden = blank;
    tempoField.hidden = blank;
    const chosen = SONG_STYLES.find((s) => s.id === styleSelect.value);
    const fromTemplate = !blank && styleTempo.checked;
    bpmField.disabled = fromTemplate;
    if (!fromTemplate) bpmField.value = String(manual);
    // Auto has no tempo to show until the seed has picked a style, so it says so
    // rather than showing a number that is not the one it will use.
    else if (chosen) bpmField.value = String(chosen.bpm);
    else { bpmField.value = ''; bpmField.placeholder = 'chosen with the style'; }
  };
  templateSelect.onchange = paint;
  styleSelect.onchange = paint;
  styleTempo.onchange = paint;
  paint();
  if (!await answered) { $('navbtn').focus(); return; }
  const blank = templateSelect.value === 'blank';
  const payload = {
    title: title.value,
    // Null means "the tempo this style is written at" — the server resolves it once it
    // knows which style the seed picked, which is the only place that can.
    bpm: !blank && styleTempo.checked ? null : manual,
    bars: Number($('newsongbars').value),
    template: templateSelect.value,
    style: blank ? 'auto' : styleSelect.value,
  };
  newSongPrefs = {
    template: payload.template,
    style: styleSelect.value,
    bars: payload.bars,
    bpm: manual,
    styleTempo: styleTempo.checked,
  };
  localStorage.setItem(NEW_SONG_KEY, JSON.stringify(newSongPrefs));
  // The static deployed mixer has no server to ask. Asking anyway does not fail
  // cleanly: a host that serves the page will answer a POST with its own 405 page,
  // which is a perfectly successful fetch carrying somebody else's HTML, and that
  // used to arrive in front of the tester as the error dialog.
  let res = null;
  if (typeof __MASH_STATIC_MIXER__ === 'undefined') {
    try {
      res = await fetch('/new-song', {
        method: 'POST', headers: { 'content-type': 'application/json' },
        body: JSON.stringify(payload),
      });
    } catch { res = null; }
  }
  if (!res) {
    // No server — generate the song right here in the browser, and keep it there.
    // There is no file to read it back from, so the browser IS the file: the song and
    // whatever gets saved onto it both live in localStorage. See LOCAL_SONGS_KEY.
    try {
      const seed = Math.floor(Math.random() * 0xffffffff);
      const plan = newSongPlan({ ...payload, seed });
      // A scratch id that nothing in the track list is already using.
      let id = slugForClient(plan.spec.title);
      const taken = new Set(listTracks().map((t) => t.id));
      for (let n = 2; taken.has(id); n++) id = `${slugForClient(plan.spec.title)}-${n}`;
      const track = {
        id,
        bank: plan.bank,
        title: plan.spec.title,
        slug: id,
        group: 'scratch',
        writable: true,             // saved into this browser rather than into a file
      };
      registerTrack(track);
      deskSongIds.add(id);
      saved[id] = null;
      savedArr[id] = null;
      persistLocalSongs();
      selectSong(id);
      if (playing) setPlaying(true, 0);
      toast(`Created ${track.title} — ${plan.style.label}, ${plan.key}, ${plan.spec.bpm} BPM`
        + ' · kept in this browser', 5000);
    } catch (err) {
      await tell('Could not create the song', escapeHtml(err.message || err));
    }
    return;
  }
  const text = await res.text();
  if (!res.ok) { await tell('Could not create the song', escapeHtml(text)); return; }
  const out = JSON.parse(text);
  registerTrack(out.track);
  saved[out.track.id] = null;
  savedArr[out.track.id] = null;
  selectSong(out.track.id);
  if (playing) setPlaying(true, 0);
  // What it came out as, because with Auto the style is the interesting part of the
  // answer and the alternative is guessing it from the sound.
  toast(`Created ${out.track.title} — ${out.style}, ${out.key}, ${out.bpm} BPM`);
}

$('newsong').onclick = createNewSong;

async function deleteScratchSong() {
  if (!isDeskSong(track) || track?.writable !== true) return;
  closeMenu();
  const id = trackId;
  const title = track.title;
  const ok = await ask(`Delete ${escapeHtml(title)}?`,
    `<b>This cannot be undone.</b><br>`
    + (STATIC
      ? `It removes <b>${escapeHtml(title)}</b> from this browser — the song, the mix you saved`
        + ' onto it, and anything unsaved on top of that.'
      : `It removes <b>src/data/imported/${escapeHtml(id)}.js</b> and its saved desk history.`
        + `<br><br>Any unsaved browser draft for this scratch song is discarded too.`), 'Delete');
  if (!ok) { toast('Delete cancelled'); return; }
  let res;
  if (STATIC) {
    // Nothing on a disk to ask about — this browser holds the only copy, so taking it
    // out of the two stores below IS the delete.
    deskSongIds.delete(id);
    delete variantSaved[id];
    delete variantDraft[id];
  } else try {
    res = await fetch('/delete-song', {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ id }),
    });
  } catch {
    await tell('Could not delete the song', 'The mixer server did not answer.');
    return;
  }
  if (res && !res.ok) {
    const body = await res.text();
    await tell('Could not delete the song', res.status === 404
      ? 'This mixer is running older code. Restart <b>npm run mixer</b> and try again.'
      : escapeHtml(body));
    return;
  }
  const fallback = listTracks().filter(visibleTrack).find((t) => t.id !== id);
  unregisterTrack(id);
  delete draft[id];
  delete saved[id];
  delete arrDraft[id];
  delete savedArr[id];
  delete songLayouts[id];
  forgetRecent(id);
  localStorage.setItem(LS_KEY, JSON.stringify(draft));
  localStorage.setItem(ARRANGE_KEY, JSON.stringify(arrDraft));
  if (STATIC) { persistLocalSongs(); persistLocalSave(); }
  saveSongLayouts();
  undoStack.length = 0;
  lastEditTag = null;
  if (fallback) selectSong(fallback.id);
  renderSongBrowser();
  toast(`${title} deleted`);
}

$('deletesong').onclick = deleteScratchSong;

// Where playback last began, so Stop has somewhere to go back to. Pause holds where
// it is; Stop returns to the start of the take. That pair is the reason there are
// four buttons instead of one that changes its mind.
let startedAt = 0;

function releaseHeldPreviews() {
  for (const held of previewHeld.values()) {
    Audio.releasePreviewNote(held.laneKey, held.freq);
  }
  previewHeld.clear();
  chordInputGroups.clear();
  clearOskHeldVisuals();
  oskHeld.clear();
}

/** Stop every live note and scheduled sound without changing the MIDI switch. */
function silenceAll() {
  cancelStartPreparation();
  releaseHeldPreviews();
  // Stop closes MIDI-held recording tokens too, but leaves the MIDI ports attached.
  releaseOskSources('m:');
  voiceLibrary.stopPattern();
  if (recArmed) setRecord(false);
  if (playing) setPlaying(false);
  else if (Audio.bank) Audio.setBank(null);
  Audio.panic();
  if (oskShown()) {
    oskStep = -1;
    refreshOsk();
  }
}

/**
 * The emergency cut, on ⎋: no held input or scheduled sound survives it.
 *
 * It was a red button in the header as well, which is one control too many for what it
 * does — Stop already silences everything you can hear, and the part panic adds on top
 * (dropping and re-attaching MIDI, so a note-off that never arrived cannot leave a key
 * down) is worth a key you can hit without aiming a mouse at it. Bound in the desk's
 * keyboard handler, where every other context has already had its refusal.
 */
function panicAll() {
  const restoreMidi = midiOn;
  setMidi(false, { announce: false });
  silenceAll();
  if (restoreMidi) setMidi(true, { announce: false });
  toast(restoreMidi
    ? 'PANIC — all sound silenced and MIDI restored'
    : 'PANIC — all sound silenced and MIDI off');
}

/** Start or stop the transport, optionally from a given step.
 *  When `fromStep` is 0 and loop is on with locators set, the loop is armed
 *  WITHOUT jumping — the song plays from the start and begins looping only
 *  when it reaches the locator region naturally. */
// The footer verdict's linger: how long a cleared verdict stays readable. Long enough
// to look down after a glitch and still find the words; short enough that old trouble
// does not haunt a healthy desk.
const HEALTH_LINGER_MS = 12000;
let lastHealthText = '';
let lastHealthAt = 0;

function setPlaying(on, fromStep = null, { countIn = 0 } = {}) {
  // Before `playing` changes, so `recording()` is still true and the take can measure
  // the keys that are still down against the position the music actually stopped at.
  // The transport stopping is the take ending; the arm stays on, so hitting play again
  // carries straight on recording.
  if (!on && recArmed) endTake('stopped');
  playing = on;
  // The note cache pumps at full speed the moment the transport is not rolling — a
  // pause is precisely the "let it catch up" gesture, and it used to build at trickle
  // pace and read as useless. See setNoteCacheTransportRunning in the engine.
  Audio.setNoteCacheTransport?.(playing);
  $('play').classList.toggle('on', playing);
  $('pause').disabled = !playing;
  // The bench's play button says whether it would join the song or start beside it, and
  // that answer changes here. Told rather than left to the next repaint: the library
  // does not repaint on transport, so it would have gone on offering the wrong one.
  voiceLibrary.syncChanged();
  peakSeen = 0;
  if (playing) {
    // BEFORE the bank goes in, so a context that is suspended or a watchdog that has
    // given up is dealt with while there is still nothing depending on either.
    reviveAudioForPlay();
    resetLoopHealthWindow();
    // Resume where the playhead was parked, not back at the top.
    const at = fromStep != null ? fromStep : parkedAt;
    startedAt = at;
    Audio.setBank(track.bank, mixFor(trackId), arrFor(trackId), { countIn });
    applyToEngine(mixFor(trackId));
    Audio.step = at;
    // "Play from start" with loop on: arm the selected loop region but don't jump
    // the playhead into it — let the song play from 0 and naturally enter the loop.
    if (fromStep === 0 && loopOn && currentLoopBounds()) {
      applyLoopNoJump();
    } else {
      applyLoop(at);
      // "From the start" of a song that names its own start bar is that bar, not bar 1.
      // Only from the start: resuming from a park has a position of its own already.
      if (fromStep === 0 && songLoopGoverns()) Audio.armSongLoop({ seek: true });
    }
    // The beat the take starts on, so the first boundary the playhead crosses is a real
    // crossing rather than a flush measured against a stale `-1`.
    recLastBeat = Math.floor((at % Math.max(1, songShape().totalSteps)) / 4);
    recLastHeard = at;
  } else {
    // Exactly where the playhead is, so Play carries on from here; the loop region
    // still snaps to the bar that contains it.
    const { totalSteps } = songShape();
    parkedAt = ((Audio.step % totalSteps) + totalSteps) % totalSteps;
    Audio.setLoop();
    Audio.setBank(null);
    // setBank(null) is the game's "no song" state: applyMix zeroes every send and
    // clears the dry taps, and with no entry to read it never puts them back, so
    // pruneAuxes then unhooks the returns. Harmless in the game, which only reaches
    // that state on the way out of a song — but the desk sits in it every time you
    // pause, and the sends came back only when something re-applied the mix, which
    // made them look like they needed an A/B to wake up. The engine should always
    // carry the mix you are looking at, playing or not.
    applyToEngine(mixFor(trackId));
    flushSelectionEditors();
    // Pausing is the parked moment the song analysis waits for. If the Rearrange
    // panel was opened mid-playback its key readout deferred the walk; run it now so
    // the answer appears the moment there is main thread to spare.
    if (rearrangePanelOpen) syncRearrangeKeyReadout();
  }
  // Armed and recording look different, and which one this is has just changed.
  syncRecordUi();
}
/**
 * Warm the cache briefly, then start. A cache is an optimisation, not a prerequisite
 * for sound: waiting forever for an OfflineAudioContext is worse than letting the first
 * notes use the live rack and warming the rest for the next pass.
 */
/*
 * How long "play from top" will hold the transport while the note cache prepares.
 *
 * 1200ms was right when a plan was tens of renders — the pooled pluck lanes. The day
 * the string section became cacheable a plan grew to hundreds, and a 1.2s budget
 * prepared five notes, expired, and started cold every time — which is why nobody had
 * ever actually seen the "Preparing MRDR-3 n / m" state the button carries: it was
 * gone inside a second, and the first laps played through the audible warm-up instead.
 *
 * The button is its own escape hatch — pressing it again during preparation means
 * "start now" — so the deadline's only job is to stop a stuck render from holding the
 * transport hostage forever. Three minutes covers the largest plan the desk has
 * produced (about 500 renders) with room; nobody has to wait it out, ever.
 */
const NOTE_CACHE_START_BUDGET_MS = 180000;
let preparingFromStart = false;
let startPreparationToken = 0;
let preparationControl = 'start';
let preparationFromStep = 0;
let preparationHandoff = 0;
let startingPreparedTransport = false;

const waitForCacheTick = () => new Promise((resolve) => setTimeout(resolve, 40));

function showStartPreparation(on, control = preparationControl) {
  preparingFromStart = on;
  if (on) preparationControl = control;
  const fromTop = preparationControl === 'start';
  $('playstart').classList.toggle('preparing', on && fromTop);
  $('play').classList.toggle('preparing', on && !fromTop);
  $('playstart').setAttribute('aria-busy', String(on && fromTop));
  $('play').setAttribute('aria-busy', String(on && !fromTop));
  $('playstart').title = on && fromTop
    ? 'Preparing note cache — playback starts automatically'
    : 'Play from the top of the song';
  $('play').title = on && !fromTop
    ? 'Preparing this loop — playback starts automatically'
    : 'Play (space)';
  $('playstart').dataset.tip = on && fromTop ? 'Start now' : 'Play from top';
  // Both transport buttons remain live while the cache warms. They are useful escape
  // hatches in their own right: Start means step 0, Play means the parked/loop step.
  // Disabling one while telling the user to press it again was both contradictory and
  // the source of the old "press play to start" dead end.
  $('playstart').disabled = false;
  $('play').disabled = false;
}

function cancelStartPreparation() {
  if (!preparingFromStart && !startingPreparedTransport) return false;
  startPreparationToken++;
  preparationHandoff++;
  showStartPreparation(false);
  Audio.setNoteCachePreparationHeld(false);
  return true;
}

async function startPreparedTransport(message = '', fromStep = preparationFromStep) {
  if (startingPreparedTransport) return false;
  startingPreparedTransport = true;
  const handoff = ++preparationHandoff;
  let started = false;
  Audio.setNoteCachePreparationHeld(true);
  showStartPreparation(false);
  try {
    // Cache preparation finishes in an async callback, so this handoff is no longer
    // necessarily inside the click that unlocked Web Audio. Resume before the bank is
    // scheduled; otherwise the desk can say it is playing while a suspended context
    // holds every cached source silent. `prepareAndStart` also calls ensure() inside the
    // original gesture, which makes this a retry rather than the first unlock attempt.
    if (Audio.ctx?.state === 'suspended' && typeof Audio.ctx.resume === 'function') {
      try { await Audio.ctx.resume(); } catch { /* setPlaying retries on the gesture path */ }
    }
    // Stop can arrive while resume() is pending. Do not resurrect playback after that
    // deliberate cancellation, and do not leave the cache hold behind on the abort path.
    if (handoff !== preparationHandoff) return false;
    setPlaying(true, fromStep);
    started = true;
    // `bank` now keeps preparation paused. Releasing the explicit hold here means the
    // next ordinary Stop/Pause can warm whatever this pass discovers.
    Audio.setNoteCachePreparationHeld(false);
    if (message) toast(message);
    return true;
  } finally {
    if (!started) Audio.setNoteCachePreparationHeld(false);
    startingPreparedTransport = false;
  }
}

async function prepareAndStart({ fromStep = 0, range = null, control = 'start' } = {}) {
  if (startingPreparedTransport) return;
  if (preparingFromStart) {
    startPreparationToken++;
    // The button that was actually clicked owns the position. In particular, Start
    // from beginning must still mean step 0 if a locator-loop warm-up is in progress.
    const immediateStep = control === 'start' ? 0 : preparationFromStep;
    await startPreparedTransport('Starting now', immediateStep);
    return;
  }

  // Unlock/create the realtime context in the click that requested playback. The final
  // start happens after async cache work, so relying on that later callback as the first
  // autoplay gesture is intermittent on browsers that require an explicit unlock.
  try { Audio.ensure?.(); } catch (error) {
    console.warn('[mixer] audio context could not be primed before cache preparation', error);
  }

  // Hold the worker BEFORE stopping. setBank(null) normally releases it, which would
  // let the first old job start while the complete arrangement is still being
  // inventoried and before its late-section priorities have been sorted.
  Audio.setNoteCachePreparationHeld(true);
  if (playing) setPlaying(false);
  preparationFromStep = fromStep;
  if (fromStep === 0) jumpTo(0); // park and draw bar 1 while the cache is prepared
  let initial;
  let preparationFailed = false;
  try {
    initial = Audio.prepareNoteCache?.(engineBank(), range
      ? { startStep: range.start, endStep: range.end } : {}) || Audio.noteCacheHealth?.();
  } catch (error) {
    // Inventory is only an optimisation. A malformed/edited arrangement must never
    // strand the transport with its cache hold set and no way to start the song.
    preparationFailed = true;
    console.warn('[mixer] note cache preparation skipped; starting live', error);
    initial = Audio.noteCacheHealth?.() || { enabled: false };
  }
  // A WARM SONG STARTS INSTANTLY. Only the selected plan is a reason to wait: the cache
  // can also contain unrelated jobs left by an earlier pass, and those must not hold a
  // fresh transport hostage. `plan.pending` is the selected live backlog; `rendering`
  // covers the one job already inside OfflineAudioContext when the plan was committed.
  const initialPending = initial?.plan?.pending || 0;
  if (preparationFailed || !initial?.enabled || (!initialPending && !initial.rendering)) {
    await startPreparedTransport(initial?.buffers
      ? `Playing ${range ? 'loop' : 'from beginning'} · ${initial.buffers} cached note${initial.buffers === 1 ? '' : 's'}`
      : '');
    return;
  }

  const token = ++startPreparationToken;
  showStartPreparation(true, control);
  Audio.setNoteCachePreparationHeld(false);
  const selected = initial.plan?.selected || 0;
  const planned = initial.plan?.candidates || 0;
  toast(`Preparing ${range ? 'loop' : 'audio'}… ${selected || initialPending} sound${(selected || initialPending) === 1 ? '' : 's'} selected${planned ? ` of ${planned}` : ''}`, 3000);
  const deadline = performance.now() + NOTE_CACHE_START_BUDGET_MS;
  let budgetExpired = false;
  while (token === startPreparationToken) {
    const health = Audio.noteCacheHealth?.();
    const planPending = health?.plan?.pending || 0;
    if (!health?.enabled || (!planPending && !health.rendering)) break;
    if (performance.now() >= deadline) { budgetExpired = true; break; }
    const plan = health.plan || {};
    const done = plan.completed || 0;
    if (planPending || health.rendering) {
      const total = Math.max(0, plan.selected || selected || planPending + done);
      const label = total ? `Preparing MRDR-3 ${Math.min(total, done)} / ${total}` : 'Preparing audio';
      showStartPreparation(true, control);
      $('play').dataset.tip = `${label} · Start now`;
      $('playstart').dataset.tip = `${label} · Start now`;
    }
    await waitForCacheTick();
  }

  if (token !== startPreparationToken) return;
  const health = Audio.noteCacheHealth?.();
  await startPreparedTransport(health?.buffers
    ? `Playing ${range ? 'loop' : 'from beginning'} · ${health.buffers} cached note${health.buffers === 1 ? '' : 's'}`
    : `Playing ${range ? 'loop' : 'from beginning'}${budgetExpired ? ' · live warm-up' : ''}`);
}

async function playFromBeginning() {
  // START FROM THE TOP IS THE ONE THAT COUNTS IN, and while a recipe is armed the top is
  // the recipe's. M8TRX used to carry its own Play button for this; the desk's transport
  // already means "from the beginning", so it says it here instead of twice.
  if (rearrangeActive()) { playRearrangement(); return; }
  return prepareAndStart({ fromStep: 0, control: 'start' });
}

async function playFromParked() {
  if (rearrangeActive()) { setPlaying(true); return; }
  const bounds = loopOn ? currentLoopBounds() : null;
  // While a top-of-song warm-up is in progress, the ordinary no-loop branch must not
  // bypass the handoff with a raw setPlaying(true). Route Play through the same token
  // cancellation so the cache callback cannot start a second transport a moment later.
  if (preparingFromStart) {
    return prepareAndStart({ fromStep: parkedAt, range: bounds, control: 'play' });
  }
  if (!bounds) { setPlaying(true); return; }
  return prepareAndStart({ fromStep: parkedAt, range: bounds, control: 'play' });
}

$('play').onclick = () => { if (!playing) void playFromParked(); };
$('pause').onclick = () => { if (playing) setPlaying(false); };
$('stop').onclick = () => {
  cancelStartPreparation();
  const at = startedAt;
  silenceAll();
  jumpTo(at, { immediate: true });
  toast(`Stopped at bar ${Math.floor(at / 16) + 1}`);
};
$('playstart').onclick = playFromBeginning;
$('rearrangebtn').onclick = () => {
  if (rearrangePanelOpen) closeRearrangePanel();
  else openRearrangePanel();
};
// A range input brings its own arrow keys, so the hand-rolled radio-group keyboard handling
// this replaced is gone with the buttons.
$('regrain').oninput = () => { setRearrangeGrain(Number($('regrain').value) / 100); };
$('reform').onchange = () => { setRearrangeForm($('reform').value); };
$('restyle').onchange = () => {
  setRearrangeStyle($('restyle').value);
};
syncRearrangeStyle();
syncRearrangeGrain();
syncRearrangeForm();
for (const [name, spec] of Object.entries(REARRANGE_DIALS)) {
  $(spec.id).oninput = () => {
    syncRearrangeDial(name);
    // Mood decides which key the walk lands in and Drive decides which kit Auto builds,
    // so both readouts have to follow the hand rather than wait for the next Go.
    if (name === 'mood') syncRearrangeKeyReadout();
    if (name === 'drive') syncRearrangeDrumControl();
    // Moving a dial is what gives Reshape something to do, so it is what lights it up.
    syncRearrangeSeedHold();
  };
}
syncRearrangeDials();
$('refill').onchange = syncRearrangeAdvanced;
// New length had no handler at all — it was only ever read at generate time, so changing it
// left Reshape greyed out as though nothing had moved.
$('relength').onchange = syncRearrangeAdvanced;
$('rekey').onchange = () => { syncRearrangeKeyReadout(); syncRearrangeAdvanced(); };
syncRearrangeKeyReadout();
// Placed under its own button, and re-placed every time it opens: the band above it wraps
// with the window, so the button is not where it was last time.
$('readvancedpop').addEventListener('toggle', (event) => {
  const button = $('readvancedbtn');
  button.classList.toggle('on', event.newState === 'open');
  if (event.newState !== 'open') return;
  const pop = $('readvancedpop');
  const at = button.getBoundingClientRect();
  pop.style.left = `${Math.max(8, Math.min(at.left, innerWidth - pop.offsetWidth - 8))}px`;
  pop.style.top = `${Math.max(8, Math.min(at.bottom + 6, innerHeight - pop.offsetHeight - 8))}px`;
});
syncRearrangeAdvanced();
$('redice').onclick = luckyDip;
$('reseedhold').onclick = () => {
  rearrangeSeedHold = !rearrangeSeedHold;
  syncRearrangeSeedHold();
  renderRearrangeList();
  toast(rearrangeSeedHold
    ? 'Go will keep this arrangement and change only what the dials ask for'
    : 'Go will build a completely different arrangement each time');
};
syncRearrangeSeedHold();
$('retranspose').oninput = () => { syncRearrangeTranspose(); syncRearrangeAdvanced(); };
syncRearrangeTranspose();
// Wheel and touch, not 'scroll': the follow's own scrollIntoView fires 'scroll' too,
// and a guard that reacts to itself would hold itself off forever.
for (const id of ['rearrangeform']) {
  $(id)?.addEventListener('wheel', holdRearrangeFollow, { passive: true });
  $(id)?.addEventListener('touchmove', holdRearrangeFollow, { passive: true });
}
wireRearrangeTimelineSelection();
// The menu closes on anything that is not itself: a click elsewhere, Escape, or the panel
// scrolling out from under it.
document.addEventListener('pointerdown', (event) => {
  if (!event.target.closest?.('#reslicemenu')) closeRearrangeSliceMenu();
}, true);
document.addEventListener('keydown', (event) => { if (event.key === 'Escape') closeRearrangeSliceMenu(); });
$('rearrangeform')?.addEventListener('scroll', closeRearrangeSliceMenu, { passive: true });
$('reclearselection').onclick = clearRearrangeOperationSelection;
$('reslicetranspose').onchange = () => transformSelectedRearrange('transpose', 'Slice transpose changed',
  { value: Number($('reslicetranspose').value) });
$('restutter').onchange = () => {
  const shape = $('restutter').value;
  if (!shape) return;
  const label = REARRANGE_STUTTER_SHAPES[shape]
    ? `${shape[0].toUpperCase()}${shape.slice(1)} stutter` : `Slice stuttered ×${shape}`;
  transformSelectedRearrange('stutter', label, { value: shape });
};
$('reclearkept').onclick = clearRearrangeKeptState;
$('reslicechord').onchange = () => transformSelectedRearrange('harmony', 'Slice chord changed',
  { value: Number($('reslicechord').value) });
$('remute').onclick = () => {
  const selected = [...rearrangeSelectedOperations];
  const silent = selected.length
    && selected.every((item) => rearrangeRecipe?.operations?.[item]?.mute);
  transformSelectedRearrange(silent ? 'unmute' : 'mute', silent ? 'Slices sounding' : 'Slices muted');
};
$('rejoin').onclick = () => transformSelectedRearrange('join', 'Slices joined');
// The Part rail's own ½ and ×2, on whichever part is held — the same two transforms the
// part card carries, reached without going back to the card.
$('recopysection').onclick = () => {
  const picked = [...rearrangeSelectedOperations].sort((a, b) => a - b);
  if (!picked.length) { toast('Select the slices to copy'); return; }
  const bars = picked.reduce((sum, index) => {
    const op = rearrangeRecipe.operations[index];
    return sum + (op ? op.length * op.repeats : 0);
  }, 0) / 16;
  rearrangeCopiedSection = {
    name: picked.length === 1 ? '1 slice' : `${picked.length} slices`,
    bars,
    operations: picked.map((index) => ({ ...rearrangeRecipe.operations[index] })),
  };
  renderRearrangeList();
  toast(`Copied ${rearrangeCopiedSection.name} · ${String(+bars.toFixed(2))} bars`);
};
$('repastesection').onclick = () => {
  const picked = [...rearrangeSelectedOperations];
  if (!picked.length || !rearrangeCopiedSection) { toast('Copy something first, then select where it goes'); return; }
  try {
    const result = replaceRearrangementSlices(rearrangeRecipe, picked, rearrangeCopiedSection.operations);
    applyRearrangeEdit(result.recipe, `Pasted ${rearrangeCopiedSection.name}`);
  } catch (error) { toast(error?.message || 'Could not paste there'); }
};
$('replayfrom').onclick = playRearrangeSelection;
$('resplit').onclick = () => transformSelectedRearrange('split', 'Split');
$('reunroll').onclick = () => transformSelectedRearrange('unroll', 'Separated passes');
$('redoublerepeats').onclick = () => transformSelectedRearrange('repeat-more', 'Repeat increased');
$('rehalfrepeats').onclick = () => transformSelectedRearrange('repeat-less', 'Repeat reduced');
$('rerollselected').onclick = () => transformSelectedRearrange('reroll', 'New material under those slices');
$('reclipselected').onclick = snapshotSelectedRearrangeClip;
$('reremove').onclick = () => transformSelectedRearrange('remove', 'Borrowed from the neighbours');
$('redeleteselected').onclick = () => transformSelectedRearrange('delete', 'Deleted slices');
